def _yt_cache_put(cache: OrderedDict, key: str, value: dict, max_size: int) -> None:
    """Insert/update key and evict oldest (LRU) entries when over max_size."""
    cache[key] = value
    while len(cache) > max_size:
        try:
            cache.popitem(last=False)
        except KeyError:
            break
