_DICTIONARY_ENRICHMENT_JOB_TTL_SEC = 1800.0


def _dictionary_enrichment_job_redis_key(lookup_id: str) -> str:
    return f"dict:enrichment:job:{str(lookup_id or '').strip()}"


def _dictionary_enrichment_cache_redis_key(cache_key: str) -> str:
    return f"dict:enrichment:cache:{str(cache_key or '').strip()}"


def _set_shared_dictionary_enrichment_job(job: dict[str, Any]) -> None:
    client = get_redis_client()
    lookup_id = str((job or {}).get("lookup_id") or "").strip()
    if client is None or not lookup_id:
        return
    payload = copy.deepcopy(job if isinstance(job, dict) else {})
    client.set(
        _dictionary_enrichment_job_redis_key(lookup_id),
        json.dumps(payload, ensure_ascii=False),
        ex=int(_DICTIONARY_ENRICHMENT_JOB_TTL_SEC),
    )
    for key_name in ("cache_key", "cache_key_shared"):
        cache_key = str(payload.get(key_name) or "").strip()
        if cache_key:
            client.set(
                _dictionary_enrichment_cache_redis_key(cache_key),
                lookup_id,
                ex=int(_DICTIONARY_ENRICHMENT_JOB_TTL_SEC),
            )


def _get_shared_dictionary_enrichment_job_by_lookup_id(lookup_id: str) -> dict[str, Any] | None:
    client = get_redis_client()
    normalized_lookup_id = str(lookup_id or "").strip()
    if client is None or not normalized_lookup_id:
        return None
    raw = client.get(_dictionary_enrichment_job_redis_key(normalized_lookup_id))
    if not raw:
        return None
    try:
        payload = json.loads(raw)
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


def _get_shared_dictionary_enrichment_job_for_cache_keys(*cache_keys: str) -> dict[str, Any] | None:
    client = get_redis_client()
    if client is None:
        return None
    for cache_key in (str(item or "").strip() for item in cache_keys if str(item or "").strip()):
        lookup_id = str(client.get(_dictionary_enrichment_cache_redis_key(cache_key)) or "").strip()
        if not lookup_id:
            continue
        payload = _get_shared_dictionary_enrichment_job_by_lookup_id(lookup_id)
        if isinstance(payload, dict):
            return payload
    return None


# --- Deep analysis ("Полный разбор") shared store -------------------------------
# The bot process computes a full dictionary lookup for a DM word/phrase/sentence,
# writes the raw lookup here keyed by an id, and replies with a `?startapp=razbor_<id>`
# button. The Mini-App then reads it back by id (no second LLM call). Redis-only,
# TTL 24h — long enough for a chat link opened later, no new DB table (DiskFull-safe).
_DEEP_ANALYSIS_STORE_TTL_SEC = 86400


def _deep_analysis_redis_key(deep_id: str) -> str:
    return f"dict:deep:{str(deep_id or '').strip()}"


def _get_deep_analysis_record(deep_id: str) -> dict[str, Any] | None:
    client = get_redis_client()
    normalized = str(deep_id or "").strip()
    if client is None or not normalized:
        return None
    raw = client.get(_deep_analysis_redis_key(normalized))
    if not raw:
        return None
    try:
        payload = json.loads(raw)
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


# A pending «Расширенный перевод» request written by the bot at mode-selection time
# (dict:deepreq:{request_key} = {user_id, word, source_lang, target_lang}). The Mini-App
# opens ?startapp=razbor_req_<key>, and the backend runs the full lookup on open.
def _deep_request_redis_key(request_id: str) -> str:
    return f"dict:deepreq:{str(request_id or '').strip()}"


def _get_deep_request_record(request_id: str) -> dict[str, Any] | None:
    client = get_redis_client()
    normalized = str(request_id or "").strip()
    if client is None or not normalized:
        return None
    raw = client.get(_deep_request_redis_key(normalized))
    if not raw:
        return None
    try:
        payload = json.loads(raw)
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


def _deep_request_cache_id(user_id: int, word: str, source_lang: str, target_lang: str) -> str:
    """Deterministic dict:deep id for a (user, word, pair) so re-opening the same
    request reuses the computed lookup instead of re-running the LLM."""
    seed = f"{int(user_id)}|{str(word or '').strip()}|{source_lang}|{target_lang}"
    return "reqc_" + hashlib.sha1(seed.encode("utf-8", "ignore")).hexdigest()[:16]


def _quick_dict_deep_id(user_id: int, word: str, source_lang: str, target_lang: str) -> str:
    """Deterministic dict:deep id for a quick-dictionary result so the same
    (user, word, pair) reuses ONE shareable record instead of leaking a new one
    per lookup — mirrors _deep_request_cache_id for the quick-dict overlay."""
    seed = (
        f"qd|{int(user_id)}|{str(word or '').strip().lower()}"
        f"|{str(source_lang or '').strip().lower()}|{str(target_lang or '').strip().lower()}"
    )
    return "qd_" + hashlib.sha1(seed.encode("utf-8", "ignore")).hexdigest()[:16]


def _store_quick_dict_deep_record(
    *,
    user_id: int,
    word: str,
    source_lang: str,
    target_lang: str,
    direction: str,
    raw: dict | None,
) -> str:
    """Persist the RAW quick-dict lookup under a deterministic dict:deep id so the
    Mini-App can offer the SAME instant «Поделиться» as the «Полный разбор» screen
    (share/link → guest view). Best-effort — returns "" if there is nothing to store
    (no Redis / empty raw), in which case the overlay simply hides the share button."""
    client = get_redis_client()
    if client is None or not isinstance(raw, dict) or not raw:
        return ""
    deep_id = _quick_dict_deep_id(int(user_id), word, source_lang, target_lang)
    try:
        client.set(
            _deep_analysis_redis_key(deep_id),
            ex=_DEEP_ANALYSIS_STORE_TTL_SEC,
            value=json.dumps(
                {
                    "user_id": int(user_id),
                    "lookup": raw,
                    "query_word": str(word or "").strip(),
                    "source_lang": str(source_lang or "").strip().lower(),
                    "target_lang": str(target_lang or "").strip().lower(),
                    "direction": str(direction or "").strip().lower(),
                    "created_at": int(time.time()),
                    "origin": "quick_dict",
                }
            ),
        )
        return deep_id
    except Exception:
        logging.debug("quick-dict deep record store failed", exc_info=True)
        return ""
