def _is_webapp_allowlist_bypass_enabled() -> bool:
    return str(os.getenv("WEBAPP_DISABLE_ALLOWLIST") or "").strip().lower() in {"1", "true", "yes", "on"}


def _allowlist_cache_key(user_id: int) -> tuple[str, int]:
    return ("allowlist", int(user_id))


def _instance_lease_cache_key(user_id: int) -> tuple[str, int]:
    return ("instance_lease", int(user_id))


def _allowlist_redis_key(user_id: int) -> str:
    return f"webapp:allowlist:{int(user_id)}"


def _webapp_start_idempotency_key(user_id: int) -> str:
    return translation_start_idempotency_key(int(user_id))


def _webapp_finish_idempotency_key(user_id: int) -> str:
    return translation_finish_idempotency_key(int(user_id))


def _snapshot_refresh_idempotency_key(*, snapshot_kind: str, user_id: int, snapshot_key: str | None) -> str:
    normalized_kind = str(snapshot_kind or "").strip() or "snapshot"
    normalized_key = str(snapshot_key or "-").strip() or "-"
    return f"webapp:idempotency:snapshot_refresh:{normalized_kind}:{int(user_id)}:{normalized_key}"


def _load_shared_json_payload(redis_key: str) -> dict[str, Any] | None:
    client = get_redis_client()
    if client is None:
        return None
    try:
        raw = client.get(str(redis_key or "").strip())
    except Exception:
        logging.warning("Failed to load shared Redis payload: key=%s", redis_key, exc_info=True)
        return None
    if not raw:
        return None
    try:
        payload = json.loads(raw)
    except Exception:
        return None
    return dict(payload) if isinstance(payload, dict) else None


def _store_shared_json_payload(redis_key: str, payload: dict[str, Any], *, ttl_sec: int) -> bool:
    client = get_redis_client()
    if client is None:
        return False
    try:
        client.set(
            str(redis_key or "").strip(),
            json.dumps(dict(payload or {}), ensure_ascii=False),
            ex=max(1, int(ttl_sec or 1)),
        )
        return True
    except Exception:
        logging.warning("Failed to store shared Redis payload: key=%s", redis_key, exc_info=True)
        return False


def _delete_shared_key(redis_key: str) -> None:
    client = get_redis_client()
    if client is None:
        return
    try:
        client.delete(str(redis_key or "").strip())
    except Exception:
        logging.warning("Failed to delete shared Redis key: key=%s", redis_key, exc_info=True)


def _try_acquire_shared_idempotency(redis_key: str, *, ttl_sec: int) -> str | None:
    return claim_shared_idempotency(str(redis_key or "").strip(), ttl_sec=max(1, int(ttl_sec or 1)))


def _release_shared_idempotency(redis_key: str, token: str | None) -> None:
    release_shared_idempotency(str(redis_key or "").strip(), token)


def _should_dispatch_shared_snapshot_refresh(*, snapshot_kind: str, user_id: int, snapshot_key: str | None) -> bool:
    token = _try_acquire_shared_idempotency(
        _snapshot_refresh_idempotency_key(
            snapshot_kind=snapshot_kind,
            user_id=int(user_id),
            snapshot_key=snapshot_key,
        ),
        ttl_sec=SNAPSHOT_REFRESH_IDEMPOTENCY_TTL_SEC,
    )
    return bool(token)


def _cache_webapp_allowlist(user_id: int, allowed: bool) -> None:
    # Positive results: full TTL (the allow-list changes rarely). Negative results:
    # short TTL so a just-approved user is never locked out beyond ~1 min.
    if allowed:
        fresh_ttl = WEBAPP_ALLOWLIST_CACHE_TTL_SEC
        stale_ttl = WEBAPP_ALLOWLIST_CACHE_STALE_TTL_SEC
        shared_ttl = WEBAPP_SHARED_ALLOWLIST_CACHE_TTL_SEC
    else:
        fresh_ttl = stale_ttl = shared_ttl = WEBAPP_ALLOWLIST_NEG_CACHE_TTL_SEC
    _HOTPATH_ALLOWLIST_CACHE.put(
        _allowlist_cache_key(user_id),
        bool(allowed),
        fresh_ttl_sec=fresh_ttl,
        stale_ttl_sec=stale_ttl,
    )
    _store_shared_json_payload(
        _allowlist_redis_key(int(user_id)),
        {
            "allowed": bool(allowed),
            "updated_at_ms": int(time.time() * 1000),
        },
        ttl_sec=shared_ttl,
    )


def _resolve_webapp_user_allowed(user_id: int) -> tuple[bool, str]:
    if _is_webapp_allowlist_bypass_enabled():
        return True, "bypass"
    cache_key = _allowlist_cache_key(user_id)
    cached = _HOTPATH_ALLOWLIST_CACHE.get(cache_key, allow_stale=True)
    if cached is not None:
        return bool(cached.get("payload")), "cache"
    shared_cached = _load_shared_json_payload(_allowlist_redis_key(int(user_id)))
    if isinstance(shared_cached, dict) and "allowed" in shared_cached:
        allowed = bool(shared_cached.get("allowed"))
        _HOTPATH_ALLOWLIST_CACHE.put(
            cache_key,
            allowed,
            fresh_ttl_sec=WEBAPP_ALLOWLIST_CACHE_TTL_SEC,
            stale_ttl_sec=WEBAPP_ALLOWLIST_CACHE_STALE_TTL_SEC,
        )
        return allowed, "redis"
    with db_acquire_scope("request_guard_access"):
        allowed = bool(is_telegram_user_allowed(int(user_id)))
    _cache_webapp_allowlist(int(user_id), allowed)
    return allowed, "db"


def _get_cached_webapp_instance_lease(user_id: int, *, allow_stale: bool = True) -> dict | None:
    cache_key = _instance_lease_cache_key(user_id)
    cached = _HOTPATH_INSTANCE_LEASE_CACHE.get(cache_key, allow_stale=allow_stale)
    if cached and isinstance(cached.get("payload"), dict):
        return dict(cached.get("payload") or {})
    lease = get_webapp_instance_lease(int(user_id))
    if lease:
        _HOTPATH_INSTANCE_LEASE_CACHE.put(
            cache_key,
            dict(lease),
            fresh_ttl_sec=WEBAPP_INSTANCE_LEASE_CACHE_TTL_SEC,
            stale_ttl_sec=WEBAPP_INSTANCE_LEASE_CACHE_STALE_TTL_SEC,
        )
    else:
        _HOTPATH_INSTANCE_LEASE_CACHE.invalidate(cache_key)
    return lease


def _resolve_cached_webapp_instance_lease(user_id: int) -> tuple[dict | None, str]:
    cache_key = _instance_lease_cache_key(user_id)
    cached = _HOTPATH_INSTANCE_LEASE_CACHE.get(cache_key, allow_stale=True)
    if cached and isinstance(cached.get("payload"), dict):
        return dict(cached.get("payload") or {}), "cache"
    return _get_cached_webapp_instance_lease(int(user_id), allow_stale=True), "db"


def _cache_webapp_instance_lease(user_id: int, lease: dict | None) -> None:
    cache_key = _instance_lease_cache_key(user_id)
    if isinstance(lease, dict) and lease:
        _HOTPATH_INSTANCE_LEASE_CACHE.put(
            cache_key,
            dict(lease),
            fresh_ttl_sec=WEBAPP_INSTANCE_LEASE_CACHE_TTL_SEC,
            stale_ttl_sec=WEBAPP_INSTANCE_LEASE_CACHE_STALE_TTL_SEC,
        )
        return
    _HOTPATH_INSTANCE_LEASE_CACHE.invalidate(cache_key)


def _notify_admins_new_user_async(user_id: int, display_name: str, source: str) -> None:
    """Fire-and-forget «+1» DM to admins. Never on the request's critical path: this runs
    once per brand-new user, and a slow Telegram API call must not delay their first screen."""

    def _send() -> None:
        try:
            admin_ids = sorted(int(item) for item in get_admin_telegram_ids() if int(item) > 0)
        except Exception:
            return
        if not admin_ids:
            return
        text = (
            "🆕 Новый пользователь подключился\n\n"
            f"User: {display_name or f'user_{int(user_id)}'}\n"
            f"User ID: {int(user_id)}\n"
            f"Откуда: {source}\n\n"
            f"Закрыть доступ: /deny {int(user_id)}"
        )
        # Через честную доставку: отказ Telegram приходит телом ответа, и прежний вызов
        # его не видел — уведомление о новом человеке могло не приходить неделями, а в
        # логах не осталось бы ни следа (там стоял даже не warning, а debug).
        from backend.telegram_delivery import send_telegram_message
        for admin_id in admin_ids:
            дошло, почему = send_telegram_message(
                chat_id=int(admin_id), text=text, parse_mode=None,
                what="уведомление о новом человеке")
            if not дошло:
                logging.warning("уведомление о новом человеке не дошло до %s — %s",
                                admin_id, почему)

    try:
        threading.Thread(target=_send, name="notify-new-user", daemon=True).start()
    except Exception:
        logging.debug("new-user notify thread spawn failed", exc_info=True)


_DM_REACHABLE_CACHE_TTL_SEC = max(
    60, min(86400, int((os.getenv("DM_REACHABLE_CACHE_TTL_SEC") or "21600").strip() or "21600"))
)
# «Not reachable» expires fast on purpose: the nudge asks the user to open the bot, and the
# moment they do it must stop showing. A long negative TTL would keep nagging someone who
# already did what we asked.
_DM_UNREACHABLE_CACHE_TTL_SEC = max(
    30, min(600, int((os.getenv("DM_UNREACHABLE_CACHE_TTL_SEC") or "120").strip() or "120"))
)


def _is_dm_reachable(user_id: int) -> bool:
    """Can the bot write to this user at all? Cached — the answer changes once per lifetime."""
    cache_key = ("dm_reachable", int(user_id))
    cached = _HOTPATH_ALLOWLIST_CACHE.get(cache_key, allow_stale=True)
    if cached is not None:
        return bool(cached.get("payload"))
    try:
        with db_acquire_scope("dm_reachable_probe"):
            reachable = bool(has_reply_keyboard_delivered(int(user_id)))
    except Exception:
        logging.debug("dm reachability probe failed uid=%s", user_id, exc_info=True)
        # Fail as «reachable»: a DB hiccup must never make us nag a normal user.
        return True
    ttl = _DM_REACHABLE_CACHE_TTL_SEC if reachable else _DM_UNREACHABLE_CACHE_TTL_SEC
    _HOTPATH_ALLOWLIST_CACHE.put(cache_key, reachable, fresh_ttl_sec=ttl, stale_ttl_sec=ttl)
    return reachable


def _build_dm_start_hint(user_id: int, user_name: str = "") -> dict | None:
    """Nudge payload for someone playing a group task who never opened the bot in a DM.

    They can play here and now, but every task, reminder and result the bot sends lands in a
    private chat Telegram will not let us open on our own — so without one tap from them the
    app stays a one-off page. Returns None (no nudge) for everyone else.
    """
    if _is_dm_reachable(int(user_id)):
        return None
    name = str(user_name or "").strip()
    return {
        "name": name,
        "bot_username": str(TELEGRAM_BOT_USERNAME or "").strip().lstrip("@"),
        "start_param": "fromgame",
    }


def _self_serve_attempt_memo_key(user_id: int) -> tuple[str, int]:
    return ("self_serve_attempt", int(user_id))


def _remember_self_serve_attempt(user_id: int) -> None:
    """Remember «tried to self-serve-grant this user and the door stayed shut».

    Same TTL as the negative allow-list decision (WEBAPP_ALLOWLIST_NEG_CACHE_TTL_SEC, 60s),
    so an admin's /allow is never delayed by more than what the allow-list cache already
    costs — the memo only suppresses the redundant grant attempt, never a positive answer.
    """
    _HOTPATH_ALLOWLIST_CACHE.put(
        _self_serve_attempt_memo_key(int(user_id)),
        True,
        fresh_ttl_sec=WEBAPP_ALLOWLIST_NEG_CACHE_TTL_SEC,
        stale_ttl_sec=WEBAPP_ALLOWLIST_NEG_CACHE_TTL_SEC,
    )


def _self_serve_source_label(user_data: dict | None, parsed_init_data: dict | None) -> str:
    start_param = ""
    if isinstance(parsed_init_data, dict):
        start_param = str(parsed_init_data.get("start_param") or "").strip()
    if start_param.startswith("ref_"):
        referrer = start_param[4:].strip()
        return f"реферальная ссылка (от {referrer})" if referrer else "реферальная ссылка"
    if start_param.startswith("razbor_"):
        return "ссылка на «Полный разбор»"
    if start_param.startswith("dive_"):
        return "ссылка на разбор вопроса"
    if start_param:
        return f"приложение (?startapp={start_param[:40]})"
    return "приложение (Mini App)"


def _access_denied_payload(user_id: int) -> dict:
    """Что сказать человеку, которого не пустили. Ровно два законных состояния:

      · он в ОЧЕРЕДИ — упёрлись в потолок впуска (PUBLIC_ACCESS_CAP). Отдаём его
        НОМЕР: экран показывает его крупно и обещает написать в чат с ботом;
      · ему ЗАПРЕТИЛ администратор — прежний текст и прежний экран.

    Есть и третье, НЕЗАКОННОЕ состояние: мы не смогли выяснить, какое из двух. Тогда
    нельзя ни то, ни другое. «Закрыт администратором» обвинил бы человека, которого
    никто не запрещал, за нашу неудачу с чтением базы; «вы в очереди» пообещал бы
    письмо, которое некому отправить, — его ведь не поставили ни в какую очередь.
    Поэтому третий ответ говорит правду: у нас не вышло, попробуйте позже.
    """
    bot = str(TELEGRAM_BOT_USERNAME or "").strip().lstrip("@")
    try:
        from backend.database import access_waitlist_position, public_access_cap
        потолок = public_access_cap()
        номер = access_waitlist_position(int(user_id)) if потолок > 0 else None
    except Exception:
        logging.error("дверь: не смогли выяснить, очередь это или запрет (user_id=%s)",
                      user_id, exc_info=True)
        return {
            "error": "Не получилось проверить доступ. Попробуйте открыть приложение через минуту.",
            "reason": "access_check_failed",
            "bot_username": bot,
        }
    if потолок > 0:
        return {
            "error": "Вы в очереди на подключение — мы напишем, как только откроем.",
            "reason": "in_queue",
            "queue_position": int(номер) if номер else None,
            "bot_username": bot,
        }
    return {
        "error": "Доступ к приложению закрыт администратором.",
        "reason": "access_closed",
        "bot_username": bot,
    }


def _grant_self_serve_webapp_access(
    user_id: int,
    user_data: dict | None = None,
    parsed_init_data: dict | None = None,
    source_override: str | None = None,
) -> bool:
    """Let a brand-new user in on their first Mini-App open, and tell the admin.

    ┌─ ПРОВЕРЕНО 28.08.2026. НЕ ПОДНИМАТЬ ЭТО КАК НОВУЮ НАХОДКУ. ────────────────┐
    │ Здесь стояло: «Invite share-cards open the Mini App DIRECTLY               │
    │ (t.me/<bot>/app?startapp=…) without ever sending /start». ЭТО НЕВЕРНО, и   │
    │ на этом комментарии уже была построена лишняя конструкция с отложенной     │
    │ досылкой писем «на случай, если чата с ботом нет».                         │
    │                                                                            │
    │ Перебраны ВСЕ ссылки t.me, которые проект кому-либо отдаёт. Ссылок вида    │
    │ `t.me/<bot>/app?startapp=` нет НИ ОДНОЙ — они существовали только в этом   │
    │ комментарии и в докстроке теста. Приглашение — `t.me/<bot>?start=ref_<id>`,│
    │ и оно ведёт В ЧАТ С БОТОМ (backend_server.py:51023, bot_3.py:3617).        │
    │                                                                            │
    │ Живая база на ту же дату: впущено 16, из них самостоятельно пришли 4, а    │
    │ настоящих людей среди них 2 (id 7 и 777 — тестовые строки, телеграмных id  │
    │ такой длины не бывает). У ОБОИХ настоящих чат с ботом есть: один писал     │
    │ боту, оба прошли онбординг. Людей, попавших в приложение мимо бота, в      │
    │ живых данных НЕ найдено.                                                   │
    │                                                                            │
    │ ЧТО ОСТАЁТСЯ ПРАВДОЙ: эта дверь нужна, потому что мини-апп открывается     │
    │ раньше, чем человек жмёт /start (замер: 3 из 4 самостоятельных входов      │
    │ засчитаны здесь, а не в боте). Узкий путь в приложение мимо бота тоже      │
    │ существует — `?startapp=share_…` и `wdiff_…`, кнопка «Поделиться» на       │
    │ разборе слова. Но это показ одного слова другу, а не приглашение.          │
    │                                                                            │
    │ Как перемерить: grep -roE "t\.me/[^\"' )]+" по backend, bot_3.py,          │
    │ frontend/src — и SELECT note FROM bt_3_allowed_users.                      │
    └────────────────────────────────────────────────────────────────────────────┘

    Returns True when access now exists.
    """
    uid = int(user_id)
    if uid <= 0 or _is_synthetic_telegram_user_id(uid):
        return False
    # A denied user's client keeps retrying, and every retry lands here with a cached
    # "not allowed" — without this memo each one re-ran the denial lookup + recheck
    # (3 SELECTs, 2 pool checkouts) with nothing cached in between, i.e. a per-request
    # DB path anyone denied could amplify at will. The grant itself needs to happen once
    # per user in a lifetime, so remembering "just tried, door stayed shut" for the same
    # 60s the negative allow-list decision already lives costs nothing and adds no lag.
    memo_key = _self_serve_attempt_memo_key(uid)
    if _HOTPATH_ALLOWLIST_CACHE.get(memo_key, allow_stale=False) is not None:
        return False
    display_name = _extract_display_name(user_data or {}) if user_data else None
    if user_data:
        # Регистрация нового человека — первое место, где мы вообще узнаём, как его зовут.
        # Запоминаем сразу, чтобы ни один будущий пользователь не начинал жизнь безымянным.
        remember_user_identity(
            uid,
            first_name=str((user_data or {}).get("first_name") or ""),
            last_name=str((user_data or {}).get("last_name") or ""),
            tg_username=str((user_data or {}).get("username") or ""),
            source="signup",
        )
    source = str(source_override or "").strip() or _self_serve_source_label(user_data, parsed_init_data)
    try:
        with db_acquire_scope("self_serve_access_grant"):
            granted = bool(auto_grant_telegram_user(uid, display_name, source))
    except Exception:
        logging.warning("self-serve webapp access grant failed user_id=%s", uid, exc_info=True)
        _remember_self_serve_attempt(uid)
        return False
    if not granted:
        # Either an admin denied this user, or another entry point won the race and the row
        # already exists. Re-read the source of truth (bypassing the caches we know are stale
        # here) so a concurrent grant still lets the user through instead of 403-ing them.
        try:
            invalidate_telegram_user_allowed_cache(uid)
            with db_acquire_scope("self_serve_access_recheck"):
                allowed = bool(is_telegram_user_allowed(uid))
        except Exception:
            logging.warning("self-serve access recheck failed user_id=%s", uid, exc_info=True)
            allowed = False
        _cache_webapp_allowlist(uid, allowed)
        if not allowed:
            _remember_self_serve_attempt(uid)
        return allowed
    _cache_webapp_allowlist(uid, True)
    _notify_admins_new_user_async(uid, display_name or "", source)
    return True


def _is_webapp_user_allowed(user_id: int) -> bool:
    allowed, _source = _resolve_webapp_user_allowed(int(user_id))
    if allowed:
        return True
    return _grant_self_serve_webapp_access(int(user_id))


def _is_synthetic_telegram_user_id(user_id: int) -> bool:
    try:
        candidate = int(user_id)
    except Exception:
        return False
    synthetic_floor = max(
        0,
        int((os.getenv("SYNTHETIC_TELEGRAM_USER_ID_MIN") or "9100000001").strip() or "9100000001"),
    )
    return candidate >= synthetic_floor


def _supported_learning_languages_for_mode() -> list[str]:
    if GERMAN_ONLY_MODE:
        return [GERMAN_ONLY_LEARNING_LANGUAGE]
    return sorted(SUPPORTED_LEARNING_LANGUAGES)


def _supported_native_languages_for_mode() -> list[str]:
    if GERMAN_ONLY_MODE:
        return [GERMAN_ONLY_NATIVE_LANGUAGE]
    return sorted(SUPPORTED_NATIVE_LANGUAGES)


def _normalize_language_profile_for_mode(
    *,
    native_language: str | None,
    learning_language: str | None,
) -> tuple[str, str]:
    native = str(native_language or "").strip().lower()
    learning = str(learning_language or "").strip().lower()
    if GERMAN_ONLY_MODE:
        return GERMAN_ONLY_NATIVE_LANGUAGE, GERMAN_ONLY_LEARNING_LANGUAGE
    if native not in SUPPORTED_NATIVE_LANGUAGES:
        native = GERMAN_ONLY_NATIVE_LANGUAGE
    if learning not in SUPPORTED_LEARNING_LANGUAGES:
        learning = GERMAN_ONLY_LEARNING_LANGUAGE
    return native, learning


def _normalize_language_profile_payload_for_mode(profile: dict | None, *, user_id: int) -> dict:
    payload = dict(profile or {})
    native, learning = _normalize_language_profile_for_mode(
        native_language=payload.get("native_language"),
        learning_language=payload.get("learning_language"),
    )
    payload["user_id"] = int(user_id)
    payload["native_language"] = native
    payload["learning_language"] = learning
    payload["has_profile"] = bool(payload.get("has_profile"))
    return payload


# The durable browser-dictionary token authenticates the standalone Safari / home-screen
# dictionary, which has NO Telegram initData. It is scoped to the dictionary + TTS endpoints
# that dictionary actually uses — never the whole WebApp API. The global access guard below
# must honor it, else it 400s ("initData обязателен") before the endpoint's own token
# resolution ever runs (the real reason standalone audio / breakdown / save all failed).
_DICT_TOKEN_ACCESS_PREFIXES = (
    "/api/webapp/dictionary",
    "/api/webapp/tts/",
)
_DICT_TOKEN_ACCESS_EXACT = frozenset({
    "/api/webapp/flashcards/manual-selection/add",
    # Проверка сохранённого слова. Плашка всплывает сразу после сохранения — в том
    # числе в словаре с рабочего стола, у которого сессии Telegram нет вовсе.
    "/api/webapp/word-audit/check-one",
    "/api/webapp/word-audit/apply",
    "/api/webapp/word-audit/list",
})


def _сбой_запроса(exc: Exception, *, что: str, код: int = 500):
    """Человеку — понятный текст, в лог — техническую правду.

    Сырое сообщение исключения на экране запрещено правилом ноль: человек читает
    «KeyError: \'lemma_key\'» или «connection already closed» и не понимает ни что
    случилось, ни что делать. Замер 22.08.2026: таких мест в ответах клиенту было 26,
    и фронт показывает это поле как текст сообщения (`data.error` → `message`).

    Технический текст не пропадает — он уходит в лог со стеком и с именем места, то
    есть остаётся ровно там, где полезен: у нас, а не у человека.

    Намеренные сообщения (`except ValueError`) сюда НЕ переводятся: их писали для
    человека, и подменять их общей фразой значило бы потерять смысл.
    """
    logging.warning("%s не удалось: %s", что, exc, exc_info=True)
    return jsonify({"error": "Не получилось. Попробуйте ещё раз через минуту."}), код


def _dict_token_access_allowed(path: str) -> bool:
    p = str(path or "")
    if p in _DICT_TOKEN_ACCESS_EXACT:
        return True
    return any(p.startswith(prefix) for prefix in _DICT_TOKEN_ACCESS_PREFIXES)


# Per-process cache so we persist a user's display name at most once per (day, name),
# not on every webapp request. Value = "<YYYY-MM-DD>:<name>".
_display_name_refresh_seen: dict[int, str] = {}


def _maybe_persist_display_name(user_id: int, user_data: dict) -> None:
    """Единственная точка записи имени на стороне приложения: каждый вход приносит свежий
    профиль от Telegram, мы кладём его в таблицу личности (её читают все тексты для
    человека) и заодно в прогресс — там на имени висит старая аналитика. Никогда не
    задерживает и не роняет запрос."""
    try:
        uid = int(user_id or 0)
        if uid <= 0 or not user_data:
            return
        first = str(user_data.get("first_name") or "").strip()
        last = str(user_data.get("last_name") or "").strip()
        display = (f"{first} {last}").strip() or str(user_data.get("username") or "").strip()
        if not display:
            return
        cache_key = f"{datetime.now(timezone.utc):%Y-%m-%d}:{display}"
        if _display_name_refresh_seen.get(uid) == cache_key:
            return
        _display_name_refresh_seen[uid] = cache_key
        remember_user_identity(
            uid,
            first_name=first,
            last_name=last,
            tg_username=str(user_data.get("username") or ""),
            source="webapp_visit",
        )
        refresh_user_display_name(uid, display)
    except Exception:
        logging.debug("persist display name failed", exc_info=True)


@app.before_request
def enforce_webapp_access():
    path = request.path or ""
    # Backward compatibility for legacy frontend/API paths without /api prefix.
    # /webapp/t/<token> is the standalone home-screen app ENTRY (serves HTML), NOT a legacy
    # API path — it must be exempt from the /webapp/ → /api/webapp/ redirect below, else the
    # installed icon 307-bounces to /api/webapp/t/<token> and never loads the app.
    if path in {"/webapp", "/webapp/"} or path.startswith("/webapp/t/"):
        return None
    if path in _LEGACY_API_EXACT_PATHS or path.startswith(_LEGACY_API_PREFIXES):
        return redirect(f"/api{path}", code=307)

    is_protected = path.startswith("/api/webapp/") or path in _ACCESS_PROTECTED_EXACT_PATHS
    if not is_protected or path in _ACCESS_PUBLIC_WEBAPP_PATHS:
        return None

    # Cheap flag check; starts the cross-process cache-invalidation reader once per process.
    # Hooked here as well as in the billing guard so an /allow or /deny propagates even in a
    # worker that has not yet served a billing-guarded path.
    _ensure_cache_invalidation_feed_started()

    payload = request.get_json(silent=True) or {}
    init_data = _extract_request_init_data(payload)

    resolved_user_id: int | None = None
    resolved_user_data: dict = {}
    resolved_parsed = None

    if init_data and _telegram_hash_is_valid(init_data):
        resolved_parsed = _parse_telegram_init_data(init_data)
        resolved_user_data = resolved_parsed.get("user") or {}
        uid = resolved_user_data.get("id")
        if uid:
            resolved_user_id = int(uid)
    elif _dict_token_access_allowed(path):
        # Standalone Safari / home-screen quick dictionary: no Telegram initData, only a
        # durable browser-dictionary token. Accept it — but ONLY for the dict/tts endpoints
        # it is scoped to — so the request reaches the endpoint (which re-resolves the user).
        token = _extract_dict_browser_token(payload)
        if token:
            try:
                rec = resolve_dict_browser_token(token)
                if rec and int(rec.get("user_id") or 0) > 0:
                    resolved_user_id = int(rec["user_id"])
            except Exception:
                logging.debug("dict browser token resolve in access guard failed", exc_info=True)

    # Full standalone app (home-screen icon opened OUTSIDE Telegram): no initData, only a
    # durable APP-browser token. Unlike the narrow dict token (allowlisted paths only), this
    # one authorizes EVERY protected /api/webapp/* path — it is the user's durable login for
    # the detached app. Consulted only when initData didn't already authenticate.
    resolved_via_app_token = False
    if not resolved_user_id:
        app_token = _extract_app_browser_token(payload)
        if app_token:
            try:
                rec = resolve_app_browser_token(app_token)
                if rec and int(rec.get("user_id") or 0) > 0:
                    resolved_user_id = int(rec["user_id"])
                    resolved_via_app_token = True
            except Exception:
                logging.debug("app browser token resolve in access guard failed", exc_info=True)

    # Someone who blocked/deleted the bot must not keep using the detached home-screen app —
    # the app token is durable and Telegram block events never invalidate it. Same event-driven,
    # day-cached gate the standalone dictionary uses. Only for token auth (an in-Telegram
    # initData user cannot have blocked the bot and still be here), so the in-app path is untouched.
    if resolved_via_app_token and _dict_user_has_left_bot(resolved_user_id):
        return _dict_gate_response()

    if not resolved_user_id:
        if not init_data:
            return jsonify({"error": "initData обязателен"}), 400
        if not _telegram_hash_is_valid(init_data):
            return jsonify({"error": "initData не прошёл проверку"}), 401
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    is_allowed, allowlist_cache_source = _resolve_webapp_user_allowed(int(resolved_user_id))
    if not is_allowed:
        # Self-serve access: a first-time visitor who arrived by invite link is let in here
        # and the admin is notified. Only an admin-denied user still gets the 403.
        is_allowed = _grant_self_serve_webapp_access(
            int(resolved_user_id),
            resolved_user_data,
            resolved_parsed,
        )
        allowlist_cache_source = "self_serve"
    if not is_allowed:
        # `reason` lets the SPA show a calm full-screen card instead of a red error banner
        # (the same central 403 interceptor that handles the bot-left gate picks it up).
        #
        # ДВА РАЗНЫХ СОСТОЯНИЯ, и смешивать их нельзя. Человек в ОЧЕРЕДИ пришёл по
        # ссылке и ни в чём не виноват: он упёрся в потолок впуска, который владелец
        # двигает ступенями. Сказать ему «доступ закрыт администратором» — соврать и
        # обидеть. Ему полагается номер, причина и обещание написать самим.
        return jsonify(_access_denied_payload(int(resolved_user_id))), 403

    g.telegram_user_id = int(resolved_user_id)
    g.telegram_user = resolved_user_data
    g.telegram_init_data = resolved_parsed
    g.webapp_access_guard_cache_source = allowlist_cache_source
    if resolved_user_data:
        _maybe_persist_display_name(int(resolved_user_id), resolved_user_data)
    return None


@app.before_request
def enforce_webapp_single_instance():
    if not WEBAPP_SINGLE_INSTANCE_GUARD_ENABLED:
        return None
    path = request.path or ""
    is_protected = path.startswith("/api/webapp/") or path in _ACCESS_PROTECTED_EXACT_PATHS
    if not is_protected or path in _ACCESS_PUBLIC_WEBAPP_PATHS:
        return None
    if path in {"/api/webapp/bootstrap", "/api/webapp/instance/claim", "/api/webapp/instance/release"}:
        return None

    user_id = getattr(g, "telegram_user_id", None)
    if not user_id:
        return None

    instance_id = _extract_webapp_instance_id()
    if not instance_id:
        return None

    with db_acquire_scope("request_guard_instance"):
        active_lease, instance_cache_source = _resolve_cached_webapp_instance_lease(int(user_id))

    g.webapp_instance_guard_cache_source = instance_cache_source
    g.webapp_instance_guard_auto_claimed = False
    if not active_lease or not _webapp_instance_lease_is_fresh(active_lease):
        g.webapp_instance_id = instance_id
        return None

    active_instance_id = str(active_lease.get("instance_id") or "").strip()
    # Single-instance is scoped PER SURFACE: only conflict when the active lease is the
    # SAME surface (app_context) as this request. A user with the Telegram Mini App AND
    # the installed PWA open at once has two DIFFERENT surfaces → they never deactivate
    # each other (this was the ~20-30s "Эта копия больше не активна" flash).
    active_ctx = str(active_lease.get("app_context") or "").strip().lower()
    request_ctx = _extract_webapp_app_context()
    if (active_instance_id and active_instance_id != instance_id
            and (not request_ctx or not active_ctx or active_ctx == request_ctx)):
        return jsonify(_build_webapp_instance_conflict_payload(active_lease)), 409

    g.webapp_instance_id = instance_id
    return None


@app.before_request
def enforce_billing_guards():
    path = request.path or ""
    if path in _BILLING_GUARD_SKIP_PATHS:
        return None
    if path in {"/health", "/api/health"} or path.startswith("/health/") or path.startswith("/api/health/"):
        return None
    if path not in _BILLING_GUARD_RULES:
        return None
    if path.startswith("/api/admin/"):
        return None
    if _admin_token_is_valid() and path.startswith("/api/admin/"):
        return None
    with db_acquire_scope("request_guard_billing"):
        payload, status = _apply_billing_guard(path)
    if payload:
        return jsonify(payload), int(status or 429)
    return None


# === Раздача фронта ===
@app.route("/webapp")
@app.route("/webapp/")
def serve_webapp_entry():
    # Onboarding opens the standalone app in Safari as /webapp?aqt=<token>. Bake that token
    # into the manifest link server-side too (not only via runtime JS), so "Add to Home Screen"
    # captures a token-carrying start_url even before the bundle's applyAppHomeScreenMeta runs —
    # exactly the dict's ?dqt= behaviour. Without a token, serve the plain index.html unchanged.
    if str(request.args.get("aqt") or request.args.get("initData") or "").strip():
        return _serve_app_entry_html()
    response = send_from_directory(FRONTEND_DIST, "index.html")
    return _apply_webapp_entry_cache_headers(response)


def _serve_dict_entry_html(token: str = ""):
    """The quick-dictionary home-screen PWA needs its OWN manifest and a dictionary
    apple-touch-icon baked into the HTML that Safari parses at load time. So for /dict
    we rewrite those two links.

    The launch auth token arrives via the PATH (/dict/t/<token>) — iOS RELIABLY keeps a
    path segment in a home-screen start_url, whereas it DROPS query strings (?dqt=) from
    start_url, which left the installed icon unauthenticated (only the no-auth quick
    translate worked). We forward the token to the manifest link as ?dqt= (that's a
    normal resource fetch, where the query IS honored) so the dynamic manifest can bake
    it into a PATH-based start_url. The ?dqt= query is still accepted for Safari use."""
    tok = str(token or request.args.get("dqt") or "").strip()
    launch_init = str(request.args.get("initData") or "").strip()
    manifest_href = "/dict-manifest.webmanifest"
    if tok:
        manifest_href += f"?dqt={quote(tok, safe='')}"
    elif launch_init:
        manifest_href += f"?initData={quote(launch_init, safe='')}"
    try:
        html = (FRONTEND_DIST / "index.html").read_text(encoding="utf-8")
        html = html.replace('href="/manifest.webmanifest"', f'href="{manifest_href}"')
        html = html.replace('href="/icons/apple-touch-icon.png"', 'href="/icons/dict-apple-touch-icon.png"')
        response = Response(html, mimetype="text/html")
    except Exception:
        response = send_from_directory(FRONTEND_DIST, "index.html")
    return _apply_webapp_entry_cache_headers(response)


_TOUR_OG_TITLE = "Со мной немецкий идёт легче"
_TOUR_OG_DESCRIPTION = (
    "Разбор любого слова за секунду, тренажёры вместо зубрёжки и YouTube "
    "с двойными субтитрами. Пройди короткий тур."
)


def _serve_tour_entry_html():
    """index.html + Open Graph теги для пригласительной ссылки /tour.

    Мессенджер (Telegram, WhatsApp, Viber…) при вставке ссылки скачивает эту
    страницу и строит превью по og:*-тегам. Без них уходит голая синяя ссылка —
    именно то, что мы чиним. Кнопку так дать нельзя (её умеет только бот через
    inline-режим), поэтому картинка берётся в варианте "web": на ней нарисован
    адрес, чтобы человек видел, куда идти.

    Картинка общая для всех, лежит в R2 и рендерится один раз; если R2 недоступен,
    просто отдаём страницу без og:image — превью будет беднее, но ничего не падает.
    """
    from html import escape

    image_url = ""
    try:
        from backend.share_card import share_card_url
        image_url = share_card_url("web", _resolve_bot_username()) or ""
    except Exception as exc:
        logging.warning("tour OG image unavailable: %s", exc)

    try:
        html = (FRONTEND_DIST / "index.html").read_text(encoding="utf-8")
        page_url = request.url
        tags = [
            '<meta property="og:type" content="website">',
            f'<meta property="og:title" content="{escape(_TOUR_OG_TITLE)}">',
            f'<meta property="og:description" content="{escape(_TOUR_OG_DESCRIPTION)}">',
            f'<meta property="og:url" content="{escape(page_url)}">',
            f'<meta name="description" content="{escape(_TOUR_OG_DESCRIPTION)}">',
        ]
        if image_url:
            tags += [
                f'<meta property="og:image" content="{escape(image_url)}">',
                '<meta property="og:image:width" content="1080">',
                '<meta property="og:image:height" content="1080">',
                '<meta name="twitter:card" content="summary_large_image">',
                f'<meta name="twitter:image" content="{escape(image_url)}">',
            ]
        html = html.replace("</head>", "\n    ".join([""] + tags) + "\n  </head>", 1)
        response = Response(html, mimetype="text/html")
    except Exception:
        response = send_from_directory(FRONTEND_DIST, "index.html")
    return _apply_webapp_entry_cache_headers(response)


@app.route("/dict/t/<token>")
def serve_dict_entry_with_token(token):
    """Path-token entry for the home-screen dictionary: /dict/t/<token>. iOS preserves a
    PATH segment in a home-screen start_url (unlike a ?query=), so the installed icon
    cold-launches authenticated. Serves the same dict HTML, token folded into the
    manifest link."""
    return _serve_dict_entry_html(token=str(token or "").strip())


@app.route("/dict-manifest.webmanifest")
def serve_dict_manifest():
    """Quick-dict PWA manifest. When fetched with an auth token (?dqt=) or ?initData=,
    bake it into a PATH-based start_url ("/dict/t/<token>") so the installed home-screen
    icon cold-launches AUTHENTICATED — iOS uses the manifest's start_url for the icon and
    DROPS query strings from it, so the token must live in the path. Without a token,
    serve the static manifest unchanged. Scope stays "/dict" (a path prefix)."""
    token = str(request.args.get("dqt") or "").strip()
    launch_init = str(request.args.get("initData") or "").strip()
    try:
        manifest = json.loads((FRONTEND_DIST / "dict-manifest.webmanifest").read_text(encoding="utf-8"))
    except Exception:
        return send_from_directory(FRONTEND_DIST, "dict-manifest.webmanifest")
    if token:
        manifest["start_url"] = f"/dict/t/{quote(token, safe='')}"
    elif launch_init:
        manifest["start_url"] = f"/dict?initData={quote(launch_init, safe='')}"
    response = Response(json.dumps(manifest, ensure_ascii=False), mimetype="application/manifest+json")
    # A per-user start_url must never be shared/cached across users or launches.
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


def _serve_app_entry_html(token: str = ""):
    """Serve the MAIN app's index.html with its manifest link rewritten to carry the durable
    app token, so iOS "Add to Home Screen" captures a start_url that authenticates the icon.

    Same iOS gotcha as the dictionary: a home-screen start_url DROPS query strings but KEEPS a
    path segment, so the token arrives via the PATH (/webapp/t/<token>) and we forward it to the
    dynamic manifest as ?aqt= (a normal resource fetch, where the query IS honored) which bakes
    it into a PATH-based start_url. Unlike the dict entry we keep the app's own apple-touch-icon
    (this IS the app, not the dictionary)."""
    tok = str(token or request.args.get("aqt") or "").strip()
    launch_init = str(request.args.get("initData") or "").strip()
    manifest_href = "/app-manifest.webmanifest"
    if tok:
        manifest_href += f"?aqt={quote(tok, safe='')}"
    elif launch_init:
        manifest_href += f"?initData={quote(launch_init, safe='')}"
    try:
        html = (FRONTEND_DIST / "index.html").read_text(encoding="utf-8")
        html = html.replace('href="/manifest.webmanifest"', f'href="{manifest_href}"')
        response = Response(html, mimetype="text/html")
    except Exception:
        response = send_from_directory(FRONTEND_DIST, "index.html")
    return _apply_webapp_entry_cache_headers(response)


@app.route("/webapp/t/<token>")
def serve_app_entry_with_token(token):
    """Path-token entry for the home-screen MAIN app: /webapp/t/<token>. iOS preserves a PATH
    segment in a home-screen start_url (unlike a ?query=), so the installed icon cold-launches
    authenticated. Serves the app HTML with the token folded into the manifest link."""
    return _serve_app_entry_html(token=str(token or "").strip())


@app.route("/app-manifest.webmanifest")
def serve_app_manifest():
    """MAIN app PWA manifest. When fetched with an app token (?aqt=) or ?initData=, bake it into
    a PATH-based start_url ("/webapp/t/<token>") so the installed home-screen icon cold-launches
    AUTHENTICATED (iOS uses the manifest's start_url for the icon and DROPS query strings from it,
    so the token must live in the path). Without a token, serve the static app manifest unchanged.
    Reuses the app's own manifest.webmanifest (name/icons/theme); only start_url is rewritten."""
    token = str(request.args.get("aqt") or "").strip()
    launch_init = str(request.args.get("initData") or "").strip()
    try:
        manifest = json.loads((FRONTEND_DIST / "manifest.webmanifest").read_text(encoding="utf-8"))
    except Exception:
        return send_from_directory(FRONTEND_DIST, "manifest.webmanifest")
    if token:
        manifest["start_url"] = f"/webapp/t/{quote(token, safe='')}"
    elif launch_init:
        manifest["start_url"] = f"/webapp?initData={quote(launch_init, safe='')}"
    response = Response(json.dumps(manifest, ensure_ascii=False), mimetype="application/manifest+json")
    # A per-user start_url must never be shared/cached across users or launches.
    response.headers["Cache-Control"] = "no-store, max-age=0"
    return response


@app.route("/", defaults={"path": ""})
@app.route("/<path:path>")
def serve_frontend(path):
    # /dict (and short alias /d): serve index.html with the dictionary manifest+icon
    # baked in, so "Add to Home Screen" opens the dictionary (start_url "/dict"), not
    # the app root, and shows a dictionary icon instead of the app hero.
    if str(path or "").strip("/").lower() in ("dict", "d"):
        return _serve_dict_entry_html()

    # /tour: the shareable invite link. Messengers fetch this HTML to build the link
    # preview, so the Felix card has to be in the <head> as Open Graph tags.
    if str(path or "").strip("/").lower() == "tour":
        return _serve_tour_entry_html()

    # если запросили конкретный файл (например assets/...), отдаём его
    file_path = FRONTEND_DIST / path
    if path != "" and file_path.exists():
        response = send_from_directory(FRONTEND_DIST, path)
        normalized_path = str(path or "").lstrip("/")
        if normalized_path.startswith("assets/"):
            return _apply_hashed_asset_cache_headers(response)
        if normalized_path == "index.html":
            return _apply_webapp_entry_cache_headers(response)
        # The service-worker script and its runtime MUST never be HTTP-cached. If sw.js is
        # served cacheable, the browser's periodic "is there a new worker?" check re-reads the
        # STALE cached sw.js, sees identical bytes, and concludes "no update" — so a deployed
        # build never reaches installed home-screen PWAs (they stay frozen for days, exactly the
        # "nothing changed after deploy / clearing cache" symptom). no-store forces a real
        # revalidation every time, so a fresh sw.js is fetched and the update actually fires.
        if normalized_path in {"sw.js", "registerSW.js", "manifest.webmanifest"} or normalized_path.startswith("workbox-"):
            return _apply_webapp_entry_cache_headers(response)
        return response

    # иначе отдаём index.html (SPA-логика)
    response = send_from_directory(FRONTEND_DIST, "index.html")
    return _apply_webapp_entry_cache_headers(response)


