# ── Сколько запросов приложение обслуживает ОДНОВРЕМЕННО ───────────────────
# Владелец 28.08.2026: «как я могу понять, что есть необходимость это сделать?» — про
# следующую ступень поднятия потолка. Пока пик занятости заметно ниже потолка,
# поднимать нечего: это деньги за память впустую. Упёрлись — время ступени.
#
# Считаем в памяти процесса (одна пара +1/−1 на запрос, стоит наносекунды), а в базу
# кладём только когда пик ВЫРОС или когда упёрлись в потолок, и не чаще раза в минуту.
# Писать на каждом запросе было бы дороже самого замера.
_INFLIGHT_LOCK = threading.Lock()
_INFLIGHT_NOW = 0
_INFLIGHT_PEAK = 0
_CEILING_HITS = 0
_CAPACITY_FLUSH_LAST = 0.0
_CAPACITY_FLUSH_MIN_SEC = 60.0


def _capacity_ceiling() -> int:
    """Сколько запросов процесс физически может вести одновременно."""
    try:
        сведения = _runtime_capacity_info()
        потолок = сведения.get("concurrent_requests")
        return int(потолок) if потолок else 0
    except Exception:
        return 0


@app.before_request
def _capacity_track_start():
    global _INFLIGHT_NOW, _INFLIGHT_PEAK, _CEILING_HITS
    потолок = _capacity_ceiling()
    with _INFLIGHT_LOCK:
        _INFLIGHT_NOW += 1
        сейчас = _INFLIGHT_NOW
        if сейчас > _INFLIGHT_PEAK:
            _INFLIGHT_PEAK = сейчас
        # «Упёрлись» = заняты ВСЕ места. Следующий запрос будет ждать освобождения.
        if потолок and сейчас >= потолок:
            _CEILING_HITS += 1
    return None


@app.teardown_request
def _capacity_track_end(_exc=None):
    global _INFLIGHT_NOW
    with _INFLIGHT_LOCK:
        if _INFLIGHT_NOW > 0:
            _INFLIGHT_NOW -= 1
    _capacity_flush_if_due()


def _capacity_flush_if_due() -> None:
    """Сложить пик в базу — отчёт владельцу шлёт БОТ, другой сервис, памяти он не видит.

    Сбой записи здесь НЕ глушится в тишину: он логируется. Но и запрос человека из-за
    него падать не должен — замер не имеет права ломать работу. Поэтому исключение
    ловится и считается: потерянный замер = недооценённая нагрузка, о нём надо знать.
    """
    global _CAPACITY_FLUSH_LAST, _INFLIGHT_PEAK, _CEILING_HITS
    now = time.time()
    with _INFLIGHT_LOCK:
        if (now - _CAPACITY_FLUSH_LAST) < _CAPACITY_FLUSH_MIN_SEC:
            return
        пик, упирания = _INFLIGHT_PEAK, _CEILING_HITS
        if пик <= 0 and упирания <= 0:
            return
        _CAPACITY_FLUSH_LAST = now
        _CEILING_HITS = 0          # упирания складываются в базе, поэтому здесь обнуляем
        # Пик НЕ обнуляем: в базе берётся наибольший за сутки, а внутри процесса он
        # должен остаться, иначе следующая запись занизит его до случайного значения.
    try:
        from backend.database import record_capacity
        record_capacity(service="BACKEND_WEB", kind="web_requests",
                        ceiling=_capacity_ceiling(), peak=пик, hits=упирания)
    except Exception:
        logging.warning("замер занятости не записался (пик=%s, упираний=%s)",
                        пик, упирания, exc_info=True)


def _runtime_capacity_info() -> dict:
    """С какой пропускной способностью РЕАЛЬНО работает этот процесс.

    Заведено 28.08.2026, когда поднимали потолок веб-сервиса. Вопрос «сколько запросов
    приложение тянет одновременно прямо сейчас» не имел ответа: переменные окружения
    показывают, что ЗАДАНО, а не что процесс подхватил, а свои настройки приложение
    пишет только в момент старта — Railway к тому времени отдаёт уже другой хвост лога.
    Дважды за день пришлось бы отвечать догадкой; вместо этого — числа из самого процесса.

    `threads` и `workers` читаются из окружения ЭТОГО процесса — ровно те значения,
    по которым gunicorn себя и построил (см. CMD в Dockerfile.backend). `db_pool_max` —
    настоящая константа слоя базы, не пересказ переменной.

    Одновременных запросов = workers × threads. Соединений с базой на процесс —
    db_pool_max: если оно меньше threads, потоки будут стоять в очереди за соединением.
    """
    def _целое(имя: str, по_умолчанию: int) -> int | None:
        сырое = (os.getenv(имя) or "").strip()
        if not сырое:
            return по_умолчанию
        try:
            return int(сырое)
        except ValueError:
            logging.warning("%s задана не числом: %r", имя, сырое)
            return None

    воркеров = _целое("WEB_CONCURRENCY", 1)
    потоков = _целое("GUNICORN_THREADS", 2)
    из_базы = None
    try:
        from backend.database import DB_POOL_MAXCONN, DB_POOL_MINCONN
        из_базы = {"db_pool_max": int(DB_POOL_MAXCONN), "db_pool_min": int(DB_POOL_MINCONN)}
    except Exception:
        logging.warning("не смогли прочитать настройки пула базы", exc_info=True)
    итог = {"workers": воркеров, "threads": потоков,
            "concurrent_requests": (воркеров * потоков) if (воркеров and потоков) else None,
            "inflight_now": _INFLIGHT_NOW, "inflight_peak": _INFLIGHT_PEAK,
            "ceiling_hits": _CEILING_HITS}
    if из_базы:
        итог.update(из_базы)
    return итог


@app.route("/api/web/auth/telegram", methods=["POST"])
def web_auth_telegram():
    payload = request.get_json(silent=True) or {}
    if not _telegram_login_hash_is_valid(payload):
        return jsonify({"error": "Telegram login hash invalid"}), 401

    auth_date_raw = str(payload.get("auth_date") or "").strip()
    try:
        auth_date = int(auth_date_raw)
    except Exception:
        return jsonify({"error": "auth_date invalid"}), 400
    if int(time.time()) - auth_date > max(60, TELEGRAM_LOGIN_TTL_SECONDS):
        return jsonify({"error": "Telegram login expired"}), 401

    user_id_raw = str(payload.get("id") or "").strip()
    if not user_id_raw.isdigit():
        return jsonify({"error": "user_id invalid"}), 400
    user_id = int(user_id_raw)

    user_data = {
        "id": user_id,
        "first_name": str(payload.get("first_name") or "").strip(),
        "last_name": str(payload.get("last_name") or "").strip(),
        "username": str(payload.get("username") or "").strip(),
        "photo_url": str(payload.get("photo_url") or "").strip(),
    }

    if not _resolve_webapp_user_allowed(user_id)[0] and not _grant_self_serve_webapp_access(
        user_id,
        user_data,
        None,
        source_override="вход через Telegram в браузере",
    ):
        return jsonify({"error": "Доступ к приложению закрыт администратором."}), 403
    init_data = _build_signed_init_data_for_user(user_data, auth_date=int(time.time()))
    if not init_data:
        return jsonify({"error": "Не удалось выпустить initData"}), 500
    return jsonify(
        {
            "ok": True,
            "initData": init_data,
            "user": user_data,
            "chat_type": "browser",
        }
    )


@app.route("/api/user/language-profile", methods=["GET", "POST"])
def user_language_profile():
    user_id, _username, error = _authenticate_webapp_request()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status

    if request.method == "GET":
        profile = _normalize_language_profile_payload_for_mode(
            get_user_language_profile(user_id=user_id),
            user_id=int(user_id),
        )
        return jsonify(
            {
                "ok": True,
                "profile": profile,
                "supported": {
                    "learning_language": _supported_learning_languages_for_mode(),
                    "native_language": _supported_native_languages_for_mode(),
                },
            }
        )

    payload = request.get_json(silent=True) or {}
    learning_language = str(payload.get("learning_language") or "").strip().lower()
    native_language = str(payload.get("native_language") or "").strip().lower()

    # Allow POST read-mode to avoid query-string issues with large initData in WebView.
    if not learning_language and not native_language:
        profile = _normalize_language_profile_payload_for_mode(
            get_user_language_profile(user_id=user_id),
            user_id=int(user_id),
        )
        return jsonify(
            {
                "ok": True,
                "profile": profile,
                "supported": {
                    "learning_language": _supported_learning_languages_for_mode(),
                    "native_language": _supported_native_languages_for_mode(),
                },
            }
        )

    if not learning_language or not native_language:
        return jsonify({"error": "learning_language и native_language обязательны"}), 400
    try:
        native_language, learning_language = _normalize_language_profile_for_mode(
            native_language=native_language,
            learning_language=learning_language,
        )
        old_profile = _normalize_language_profile_payload_for_mode(
            get_user_language_profile(user_id=user_id),
            user_id=int(user_id),
        )
        old_pair = (
            str(old_profile.get("native_language") or "ru").strip().lower(),
            str(old_profile.get("learning_language") or "de").strip().lower(),
        )
        profile = _normalize_language_profile_payload_for_mode(
            upsert_user_language_profile(
                user_id=user_id,
                learning_language=learning_language,
                native_language=native_language,
            ),
            user_id=int(user_id),
        )
        _invalidate_user_language_pair_cache(user_id)
        new_pair = (
            str(profile.get("native_language") or "ru").strip().lower(),
            str(profile.get("learning_language") or "de").strip().lower(),
        )
        reset_sessions = old_pair != new_pair
        if reset_sessions:
            # Switching language pair must start from a clean translation screen.
            # Unfinished sentences remain untranslated in DB (counted in analytics),
            # while active sessions are closed to avoid cross-pair leakage in UI.
            with db_acquire_scope("user_language_profile_reset"), get_db_connection_context() as conn:
                with conn.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE bt_3_user_progress
                        SET end_time = NOW(), completed = TRUE
                        WHERE user_id = %s AND completed = FALSE;
                        """,
                        (int(user_id),),
                    )
    except ValueError as exc:
        return jsonify(
            {
                "error": str(exc),
                "supported": {
                    "learning_language": _supported_learning_languages_for_mode(),
                    "native_language": _supported_native_languages_for_mode(),
                },
            }
        ), 400
    except Exception as exc:
        return jsonify({"error": f"Ошибка сохранения language profile: {exc}"}), 500
    _mark_today_plan_snapshot_stale(user_id=int(user_id))
    _mark_skill_progress_snapshot_stale(user_id=int(user_id))
    _mark_weekly_plan_snapshot_stale(user_id=int(user_id))
    _mark_plan_analytics_snapshot_stale(user_id=int(user_id))
    return jsonify({"ok": True, "profile": profile, "reset_sessions": reset_sessions})


@app.route("/api/webapp/starter-dictionary/status", methods=["POST"])
def webapp_starter_dictionary_status():
    user_id, _username, error = _authenticate_webapp_request()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status
    try:
        source_lang, target_lang, profile = _get_user_language_pair(int(user_id))
        offer = _build_starter_dictionary_offer(
            user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            profile=profile,
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка статуса базового словаря: {exc}"}), 500
    return jsonify({"ok": True, "offer": offer})


@app.route("/api/webapp/starter-dictionary/apply", methods=["POST"])
def webapp_starter_dictionary_apply():
    user_id, _username, error = _authenticate_webapp_request()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status

    payload = request.get_json(silent=True) or {}
    raw_action = str(
        payload.get("action")
        or payload.get("decision")
        or ""
    ).strip().lower()
    if raw_action in {"yes", "accept", "accepted", "connect", "reconnect"}:
        action = "accepted"
    elif raw_action in {"disconnect", "remove", "disable"}:
        action = "disconnected"
    elif raw_action in {"no", "decline", "declined", "skip"}:
        action = "declined"
    else:
        return jsonify({"error": "action должен быть accept/decline/disconnect"}), 400

    force_reimport = bool(payload.get("force_reimport"))
    source_lang, target_lang, profile = _get_user_language_pair(int(user_id))
    current_state = get_starter_dictionary_state(int(user_id))
    previous_imported_count = max(0, int(current_state.get("last_imported_count") or 0))
    previous_imported_at = None
    previous_imported_at_raw = str(current_state.get("last_imported_at") or "").strip()
    if previous_imported_count > 0 and previous_imported_at_raw:
        try:
            previous_imported_at = datetime.fromisoformat(previous_imported_at_raw.replace("Z", "+00:00"))
        except Exception:
            previous_imported_at = None
    decided_at = datetime.now(timezone.utc)

    if not STARTER_DICTIONARY_ENABLED:
        return jsonify({"error": "Базовый словарь временно отключён"}), 400
    if STARTER_DICTIONARY_SOURCE_USER_ID <= 0:
        return jsonify({"error": "Не задан source_user_id базового словаря"}), 500

    template_total = count_dictionary_entries_for_language_pair(
        int(STARTER_DICTIONARY_SOURCE_USER_ID),
        source_lang,
        target_lang,
        both_directions=True,
    )

    if action == "declined":
        try:
            # Выключение обязано выключать. Раньше «отказ» только записывал решение: слова
            # оставались, подписка продолжала работать, а переключатель «весь словарь» при
            # следующем открытии экрана возвращался обратно. Текст при этом обещал
            # «останутся только твои слова».
            set_starter_dictionary_subscription(int(user_id), False)
            _removed = remove_untouched_subscription_words(int(user_id))
            state = upsert_starter_dictionary_state(
                user_id=int(user_id),
                decision_status="declined",
                source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
                template_version=STARTER_DICTIONARY_TEMPLATE_VERSION,
                source_lang=source_lang,
                target_lang=target_lang,
                last_imported_count=previous_imported_count,
                decided_at=decided_at,
                last_imported_at=previous_imported_at,
                import_status="idle",
                active_job_id=None,
                last_error=None,
                import_started_at=None,
                import_finished_at=datetime.now(timezone.utc),
            )
            offer = _build_starter_dictionary_offer(
                user_id=int(user_id),
                source_lang=source_lang,
                target_lang=target_lang,
                profile=profile,
            )
        except Exception as exc:
            return jsonify({"error": f"Ошибка сохранения решения: {exc}"}), 500
        return jsonify(
            {
                "ok": True,
                "action": "declined",
                "state": state,
                "offer": offer,
                "removed_count": int(_removed),
                "template_total": int(template_total),
            }
        )

    if action == "disconnected":
        try:
            # Disconnecting the starter dictionary also cancels the live subscription — no more
            # of the admin's new words drip in. Words the user already studied stay their own.
            set_starter_dictionary_subscription(int(user_id), False)
            # Удаляем только НЕТРОНУТОЕ: слова от автора, которые человек не учил и не
            # трогал. Всё, что он проходил, правил, помечал или раскладывал по папкам,
            # остаётся — это его словарь и его история, на ней держится аналитика.
            # Прежняя чистка искала только строки старого копирования, поэтому у
            # подписчика не находила НИЧЕГО и сообщала «удалять нечего».
            _untouched_removed = remove_untouched_subscription_words(int(user_id))
            disconnect_result = {"deleted_count": int(_untouched_removed)}
            state = upsert_starter_dictionary_state(
                user_id=int(user_id),
                decision_status="declined",
                source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
                template_version=STARTER_DICTIONARY_TEMPLATE_VERSION,
                source_lang=source_lang,
                target_lang=target_lang,
                last_imported_count=0,
                decided_at=decided_at,
                last_imported_at=None,
                import_status="idle",
                active_job_id=None,
                last_error=None,
                import_started_at=None,
                import_finished_at=datetime.now(timezone.utc),
            )
            offer = _build_starter_dictionary_offer(
                user_id=int(user_id),
                source_lang=source_lang,
                target_lang=target_lang,
                profile=profile,
            )
        except Exception as exc:
            return jsonify({"error": f"Ошибка отключения базового словаря: {exc}"}), 500
        return jsonify(
            {
                "ok": True,
                "action": "disconnected",
                "state": state,
                "offer": offer,
                "disconnect_result": disconnect_result,
                "template_total": int(template_total),
            }
        )

    if template_total <= 0:
        return jsonify({"error": "Для текущей языковой пары базовый словарь пока пуст"}), 400

    current_import_status = str(current_state.get("import_status") or "idle").strip().lower() or "idle"
    active_job_id = str(current_state.get("active_job_id") or "").strip() or None
    if current_import_status == "running":
        offer = _build_starter_dictionary_offer(
            user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            profile=profile,
        )
        return jsonify(
            {
                "ok": True,
                "action": "accepted",
                "started_in_background": True,
                "already_in_progress": True,
                "job_id": active_job_id,
                "offer": offer,
                "template_total": int(template_total),
            }
        )

    user_pair_total = count_dictionary_entries_for_language_pair(
        int(user_id),
        source_lang,
        target_lang,
        both_directions=True,
    )
    already_accepted = str(current_state.get("decision_status") or "").strip().lower() == "accepted"
    if already_accepted and user_pair_total > 0 and not force_reimport:
        offer = _build_starter_dictionary_offer(
            user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            profile=profile,
        )
        return jsonify(
            {
                "ok": True,
                "action": "accepted",
                "already_connected": True,
                "offer": offer,
                "import_result": {
                    "inserted_count": 0,
                    "template_total": int(template_total),
                },
            }
        )

    try:
        job_id = f"starter_{int(time.time() * 1000)}_{uuid4().hex[:10]}"
        state = upsert_starter_dictionary_state(
            user_id=int(user_id),
            decision_status="accepted",
            source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
            template_version=STARTER_DICTIONARY_TEMPLATE_VERSION,
            source_lang=source_lang,
            target_lang=target_lang,
            last_imported_count=previous_imported_count,
            decided_at=decided_at,
            last_imported_at=previous_imported_at,
            import_status="running",
            active_job_id=job_id,
            last_error=None,
            import_started_at=decided_at,
            import_finished_at=None,
        )
        offer = _build_starter_dictionary_offer(
            user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            profile=profile,
        )
        _want_full = bool(payload.get("full"))
        if True:
            # ОБА варианта — подписка, копирования больше нет. Разница только в потолке:
            # «весь словарь» без потолка, «быстрый старт» — не больше STARTER_DICTIONARY_IMPORT_LIMIT
            # слов. Слова в любом случае идут из одной очереди по нужности и появляются в
            # библиотеке по мере занятий, а не сваливаются пачкой.
            set_starter_dictionary_subscription(
                int(user_id),
                True,
                subscription_limit=None if _want_full else int(STARTER_DICTIONARY_IMPORT_LIMIT),
            )
            state = upsert_starter_dictionary_state(
                user_id=int(user_id),
                decision_status="accepted",
                source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
                template_version=STARTER_DICTIONARY_TEMPLATE_VERSION,
                source_lang=source_lang,
                target_lang=target_lang,
                last_imported_count=previous_imported_count,
                decided_at=decided_at,
                last_imported_at=previous_imported_at,
                import_status="done",
                active_job_id=None,
                last_error=None,
                import_started_at=decided_at,
                import_finished_at=datetime.now(timezone.utc),
            )
        # Копирования здесь больше нет. Оно стоило человеку 11 минут ожидания, теряло всю
        # работу при обрыве (одна транзакция на тысячу слов) и умело залипать навсегда:
        # один пользователь просидел в статусе «идёт импорт» с 11 июня и не получил ничего.
    except Exception as exc:
        return jsonify({"error": f"Ошибка импорта базового словаря: {exc}"}), 500

    return jsonify(
        {
            "ok": True,
            "action": "accepted",
            "started_in_background": True,
            "job_id": job_id,
            "state": state,
            "offer": offer,
            "template_total": int(template_total),
        }
    )


def _build_telegram_data_check_string(init_data: str) -> str:
    pairs = parse_qsl(init_data, keep_blank_values=True)
    data = {key: value for key, value in pairs if key != "hash"}
    sorted_pairs = [f"{key}={data[key]}" for key in sorted(data.keys())]
    return "\n".join(sorted_pairs)


def _telegram_hash_is_valid(init_data: str) -> bool:
    if not _telegram_init_data_auth_date_is_fresh(init_data):
        return False
    telegram_bot_token = _ensure_telegram_bot_token()
    data_check_string = _build_telegram_data_check_string(init_data)
    secret_key = hmac.new(
        b"WebAppData",
        telegram_bot_token.encode("utf-8"),
        hashlib.sha256,
    ).digest()
    calculated_hash = hmac.new(
        secret_key,
        data_check_string.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    received_hash = dict(parse_qsl(init_data, keep_blank_values=True)).get("hash")
    return hmac.compare_digest(calculated_hash, received_hash or "")


def _telegram_init_data_auth_date_is_fresh(
    init_data: str,
    *,
    max_age_seconds: int | None = None,
    max_future_skew_seconds: int = 300,
) -> bool:
    if not init_data:
        return False
    ttl_seconds = max(60, int(max_age_seconds or TELEGRAM_WEBAPP_INIT_TTL_SECONDS))
    parsed_pairs = dict(parse_qsl(init_data, keep_blank_values=True))
    auth_date_raw = str(parsed_pairs.get("auth_date") or "").strip()
    if not auth_date_raw:
        return False
    try:
        auth_date = int(auth_date_raw)
    except Exception:
        return False
    now_ts = int(time.time())
    if auth_date > now_ts + max(0, int(max_future_skew_seconds)):
        return False
    return (now_ts - auth_date) <= ttl_seconds


def _parse_telegram_init_data(init_data: str) -> dict:
    data = dict(parse_qsl(init_data, keep_blank_values=True))
    user_payload = data.get("user")
    user_data = json.loads(user_payload) if user_payload else None
    return {
        "user": user_data,
        "auth_date": data.get("auth_date"),
        "query_id": data.get("query_id"),
        "chat_type": data.get("chat_type"),
        "chat_instance": data.get("chat_instance"),
    }


# Поля, которые подписывает виджет Telegram Login. Список закрытый и взят из документации
# Telegram: id, first_name, last_name, username, photo_url, auth_date.
_TELEGRAM_LOGIN_SIGNED_FIELDS = frozenset({
    "id", "first_name", "last_name", "username", "photo_url", "auth_date",
})


def _telegram_login_hash_is_valid(payload: dict) -> bool:
    """Подпись считается ТОЛЬКО по полям, которые подписал Telegram.

    Раньше в строку подписи шло ВСЁ, что пришло в теле запроса, — и вход через виджет не
    работал НИКОГДА. Причина в нашем же коде: у автономного приложения есть перехватчик
    запросов, который дописывает свой токен полем `aqt` в тело каждого POST к /api/
    (frontend/src/main.jsx). Дописанное поле попадало в строку подписи, а подпись Telegram
    его не покрывает — хеш не сходился ни разу. Владелец увидел это 23.08.2026, когда
    впервые дошёл до экрана входа: до того приложение держало сохранённый пропуск и логин
    не требовался.

    Лишние поля теперь просто не участвуют в проверке. Это не послабление: подпись
    по-прежнему обязана сойтись по всем полям Telegram, и подделать её нельзя. Зато
    добавка чего угодно снаружи больше не ломает вход.
    """
    received_hash = str(payload.get("hash") or "").strip()
    if not received_hash:
        return False
    telegram_bot_token = _ensure_telegram_bot_token()
    unexpected = sorted(
        str(k) for k in payload.keys()
        if str(k) != "hash" and str(k) not in _TELEGRAM_LOGIN_SIGNED_FIELDS
    )
    if unexpected:
        # Не ошибка, но знать надо: значит кто-то ещё дописывает поля в тело входа.
        logging.info("вход через Telegram: в теле лишние поля %s — в подписи не учитываю",
                     unexpected)
    data = {}
    for key, value in payload.items():
        if key == "hash" or str(key) not in _TELEGRAM_LOGIN_SIGNED_FIELDS:
            continue
        if value is None:
            continue
        data[str(key)] = str(value)
    data_check_string = "\n".join(f"{key}={data[key]}" for key in sorted(data.keys()))
    secret_key = hashlib.sha256(telegram_bot_token.encode("utf-8")).digest()
    calculated_hash = hmac.new(secret_key, data_check_string.encode("utf-8"), hashlib.sha256).hexdigest()
    return hmac.compare_digest(calculated_hash, received_hash)


def _build_signed_init_data_for_user(user_data: dict, auth_date: int | None = None) -> str:
    if not user_data:
        return ""
    telegram_bot_token = _ensure_telegram_bot_token()
    compact_user = {
        "id": int(user_data.get("id")),
        "first_name": str(user_data.get("first_name") or "").strip(),
        "last_name": str(user_data.get("last_name") or "").strip(),
        "username": str(user_data.get("username") or "").strip(),
    }
    photo_url = str(user_data.get("photo_url") or "").strip()
    if photo_url:
        compact_user["photo_url"] = photo_url
    payload = {
        "auth_date": str(int(auth_date or time.time())),
        "user": json.dumps(compact_user, ensure_ascii=False, separators=(",", ":")),
    }
    data_check_string = "\n".join(f"{key}={payload[key]}" for key in sorted(payload.keys()))
    secret_key = hmac.new(
        b"WebAppData",
        telegram_bot_token.encode("utf-8"),
        hashlib.sha256,
    ).digest()
    payload["hash"] = hmac.new(secret_key, data_check_string.encode("utf-8"), hashlib.sha256).hexdigest()
    return urlencode(payload)


# Про кого мы уже спрашивали Telegram и он тоже не знает имени. Без этого каждый запрос
# такого пользователя тянул бы за собой обращение к Telegram прямо в обработчике.
_UNKNOWN_NAME_RETRY_SEC = 900
_unknown_display_name_seen: dict[int, float] = {}


def _known_display_name_for_user(user_id: int | None) -> str:
    """Как зовут пользователя: таблица личности, а если там пусто — спрашиваем Telegram
    один раз и тут же запоминаем. Возвращает "" когда имени правда нет: подставлять
    вместо него "None" или "user_123" нельзя — это уходит человеку в текст."""
    safe_user_id = int(user_id or 0)
    if safe_user_id <= 0:
        return ""
    try:
        label = get_user_display_name(safe_user_id)
        if label:
            _unknown_display_name_seen.pop(safe_user_id, None)
            return label
        asked_at = _unknown_display_name_seen.get(safe_user_id)
        if asked_at and (time.time() - asked_at) < _UNKNOWN_NAME_RETRY_SEC:
            return ""
        _unknown_display_name_seen[safe_user_id] = time.time()
        label = clean_identity_name(_fetch_telegram_chat_display_name(safe_user_id))
        if label:
            remember_user_identity(safe_user_id, display_name=label, source="telegram_getchat")
        return label
    except Exception:
        logging.debug("known display name lookup failed user=%s", safe_user_id, exc_info=True)
        return ""


def _delivery_display_name(user_id: int | None, raw_value: str | None = None) -> str:
    """Имя для текста, который уходит ЧЕЛОВЕКУ. Берёт то, что передали, если это настоящее
    имя, иначе — имя из таблицы личности. "" когда не знаем: звать по id нельзя."""
    return clean_identity_name(raw_value) or _known_display_name_for_user(user_id)


def _extract_webapp_user_from_init_data(init_data: str) -> tuple[int | None, str | None]:
    if not init_data or not _telegram_hash_is_valid(init_data):
        return None, None
    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return None, None
    return int(user_id), _extract_display_name(user_data)


def _extract_request_init_data(payload: dict | None = None) -> str:
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    auth_header = str(request.headers.get("Authorization") or "").strip()
    bearer = auth_header.removeprefix("Bearer ").strip() if auth_header.startswith("Bearer ") else ""
    return str(
        request.headers.get("X-Telegram-InitData")
        or request.headers.get("X-Telegram-Init-Data")
        or bearer
        or body.get("initData")
        or request.args.get("initData")
        or ""
    ).strip()


def _extract_dict_browser_token(payload: dict | None = None) -> str:
    """The durable browser-dictionary token from header/body/query — used by the
    standalone Safari / home-screen dictionary, which has no Telegram initData."""
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    return str(
        request.headers.get("X-Dict-Token")
        or (body.get("dict_token") if isinstance(body, dict) else "")
        or (body.get("dqt") if isinstance(body, dict) else "")
        or request.args.get("dqt")
        or ""
    ).strip()


def _extract_app_browser_token(payload: dict | None = None) -> str:
    """The durable APP-browser token from header/body/query — used by the standalone
    home-screen main app, which has no Telegram initData. Distinct from the dict token
    (different header/keys) so the two scopes never collide."""
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    return str(
        request.headers.get("X-App-Token")
        or (body.get("app_token") if isinstance(body, dict) else "")
        or (body.get("aqt") if isinstance(body, dict) else "")
        or request.args.get("aqt")
        or ""
    ).strip()


def _resolve_webapp_user_id(payload: dict | None = None) -> int | None:
    """Resolve the acting user's Telegram id from a valid Telegram initData, a durable
    browser-dictionary token, OR a durable app-browser token. Returns None when none
    authenticates. Lets both the standalone dictionary and the standalone home-screen app
    work past initData's 30-day TTL without weakening the in-Telegram initData path."""
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    init_data = _extract_request_init_data(body)
    if init_data and _telegram_hash_is_valid(init_data):
        try:
            uid = (_parse_telegram_init_data(init_data).get("user") or {}).get("id")
            if uid:
                return int(uid)
        except Exception:
            pass
    token = _extract_dict_browser_token(body)
    if token:
        try:
            rec = resolve_dict_browser_token(token)
            if rec and int(rec.get("user_id") or 0) > 0:
                return int(rec["user_id"])
        except Exception:
            logging.debug("dict browser token resolve failed", exc_info=True)
    app_token = _extract_app_browser_token(body)
    if app_token:
        try:
            rec = resolve_app_browser_token(app_token)
            if rec and int(rec.get("user_id") or 0) > 0:
                return int(rec["user_id"])
        except Exception:
            logging.debug("app browser token resolve failed", exc_info=True)
    return None


def _authenticate_webapp_request(payload: dict | None = None) -> tuple[int | None, str | None, str | None]:
    """Token-aware twin of _get_authenticated_user_from_request_init_data: same
    (user_id, username, error) contract and the same allow-list gate, but the user may
    also authenticate with the durable app/dict browser token. Needed by everything the
    standalone home-screen app reaches — it has no Telegram initData, so an initData-only
    handler would 400 there and force the UI into a read-only stub."""
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    username = None
    init_data = _extract_request_init_data(body)
    if init_data:
        _uid, uname = _extract_webapp_user_from_init_data(init_data)
        if _uid:
            username = uname
    user_id = _resolve_webapp_user_id(body)
    if not user_id:
        return None, None, "initData не прошёл проверку и токен недействителен"
    if not _is_webapp_user_allowed(int(user_id)):
        return None, None, "Доступ к приложению закрыт администратором."
    if not _normalize_user_label(username):
        # Token-authenticated request (no Telegram initData) — fall back to the name we
        # already know, so rows this request writes are never nameless.
        username = _known_display_name_for_user(int(user_id)) or None
    return int(user_id), username, None


# Standalone-dictionary abandonment gate. Someone who BLOCKED/DELETED the bot must not keep
# using the detached home-screen dictionary. We never check per-request against Telegram: the
# "blocked" flag is event-driven (my_chat_member / Forbidden), and we cache the yes/no decision
# in Redis for a day so a lookup only reads a single key. Fails OPEN — a Redis/DB hiccup never
# wrongly locks anyone out. A block/return event busts this key so a return unlocks promptly.
_DICT_GATE_CACHE_TTL_SEC = max(
    60, int(str(os.getenv("DICT_GATE_CACHE_TTL_SEC") or "86400").strip() or "86400")
)


def _dict_user_has_left_bot(user_id: int | None) -> bool:
    if not user_id or int(user_id) <= 0:
        return False
    key = f"dict:gate:{int(user_id)}"
    try:
        client = get_redis_client()
    except Exception:
        client = None
    if client is not None:
        try:
            cached = client.get(key)
            if cached is not None:
                return str(cached) == "1"
        except Exception:
            pass
    blocked = False
    try:
        from backend.database import is_user_bot_blocked
        blocked = bool(is_user_bot_blocked(int(user_id)))
    except Exception:
        blocked = False
    if client is not None:
        try:
            client.set(key, "1" if blocked else "0", ex=_DICT_GATE_CACHE_TTL_SEC)
        except Exception:
            pass
    return blocked


_RESOLVED_BOT_USERNAME_CACHE: dict[str, str] = {}


def _resolve_bot_username() -> str:
    """The bot's @username for deep links. Prefer the env var, but the WEB service often
    doesn't have TELEGRAM_BOT_USERNAME set (only the bot service does) — so fall back to
    deriving it once from the bot token via getMe and caching it. Never returns a bare host."""
    if TELEGRAM_BOT_USERNAME:
        return TELEGRAM_BOT_USERNAME
    cached = _RESOLVED_BOT_USERNAME_CACHE.get("value")
    if cached:
        return cached
    try:
        if TELEGRAM_Deutsch_BOT_TOKEN:
            resp = requests.get(
                f"https://api.telegram.org/bot{TELEGRAM_Deutsch_BOT_TOKEN}/getMe", timeout=5,
            )
            uname = str(((resp.json() or {}).get("result") or {}).get("username") or "").strip().lstrip("@")
            if uname:
                _RESOLVED_BOT_USERNAME_CACHE["value"] = uname
                return uname
    except Exception:
        logging.debug("getMe bot-username resolve failed", exc_info=True)
    # Last-resort constant so the return-to-bot button is NEVER a bare t.me, even on a service
    # that has neither the username env nor the bot token. Env-overridable if the handle changes.
    return (os.getenv("TELEGRAM_BOT_USERNAME_FALLBACK") or "Ich_Deutsch_bot").strip().lstrip("@")


def _dict_gate_response():
    """The 403 the standalone dictionary renders as a full-screen 'return to bot' screen.
    Carries the bot username so its button can deep-link straight back to the bot."""
    return jsonify({
        "blocked": True,
        "reason": "bot_blocked",
        "bot_username": _resolve_bot_username(),
        "message": "Чтобы пользоваться словарём, вернись в бота.",
    }), 403


def _extract_webapp_instance_id(payload: dict | None = None) -> str | None:
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    raw = str(
        request.headers.get("X-Webapp-Instance-Id")
        or body.get("instanceId")
        or body.get("instance_id")
        or ""
    ).strip()
    if not raw:
        return None
    cleaned = re.sub(r"[^a-zA-Z0-9._:-]+", "-", raw).strip("-")
    return cleaned[:128] if cleaned else None


def _extract_webapp_session_id(payload: dict | None = None) -> str | None:
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    raw = str(
        body.get("sessionId")
        or body.get("session_id")
        or request.headers.get("X-Webapp-Session-Id")
        or ""
    ).strip()
    return raw[:128] if raw else None


def _extract_webapp_app_context(payload: dict | None = None) -> str:
    """Surface of the request: 'telegram' (Mini App), 'pwa' (installed home-screen
    app), 'browser'. The client sends it on every request. Single-instance is scoped
    PER SURFACE — a user may keep the Telegram Mini App AND the installed PWA open at
    once; they must NOT deactivate each other."""
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    raw = str(
        request.headers.get("X-Webapp-App-Context")
        or body.get("appContext")
        or body.get("app_context")
        or ""
    ).strip().lower()
    return raw[:64]


def _webapp_instance_lease_is_fresh(lease: dict | None) -> bool:
    if not isinstance(lease, dict):
        return False
    last_seen_at = str(lease.get("last_seen_at") or "").strip()
    if not last_seen_at:
        return False
    try:
        seen_dt = datetime.fromisoformat(last_seen_at.replace("Z", "+00:00"))
    except Exception:
        return False
    if seen_dt.tzinfo is None:
        seen_dt = seen_dt.replace(tzinfo=timezone.utc)
    age_seconds = (datetime.now(timezone.utc) - seen_dt.astimezone(timezone.utc)).total_seconds()
    return age_seconds <= max(5, int(WEBAPP_INSTANCE_LEASE_TTL_SECONDS))


def _build_webapp_instance_conflict_payload(lease: dict | None = None) -> dict:
    payload = {
        "error": "webapp_instance_conflict",
        "message": "Приложение уже продолжило работу в другом окне.",
        "ttl_seconds": int(WEBAPP_INSTANCE_LEASE_TTL_SECONDS),
    }
    if isinstance(lease, dict):
        active_instance_id = str(lease.get("instance_id") or "").strip()
        if active_instance_id:
            payload["active_instance_id"] = active_instance_id
        last_seen_at = str(lease.get("last_seen_at") or "").strip()
        if last_seen_at:
            payload["active_last_seen_at"] = last_seen_at
    return payload


# _sanitize_observability_id lives in backend.observability (imported above)


def _extract_observability_request_id(payload: dict | None = None) -> str:
    body = payload if isinstance(payload, dict) else {}
    candidates = [
        body.get("request_id"),
        body.get("correlation_id"),
    ]
    if has_request_context():
        candidates = [
            request.headers.get("X-Request-ID"),
            request.headers.get("X-Correlation-ID"),
            request.args.get("request_id"),
            request.args.get("correlation_id"),
            *candidates,
            getattr(g, "request_id", None),
        ]
    for candidate in candidates:
        safe = _sanitize_observability_id(candidate)
        if safe:
            return safe
    return f"req_{uuid4().hex[:20]}"


# _build_observability_correlation_id lives in backend.observability (imported above)


def _to_epoch_ms() -> int:
    return int(time.time() * 1000)


# _elapsed_ms_since lives in backend.observability (imported above)


_AUTH_TRACE_PATHS = {
    "/api/webapp/start",
    "/api/webapp/session",
    "/api/billing/status",
}
_REQUEST_LOG_PATHS = {
    "/api/healthz",
    "/api/webapp/topics",
}


def _log_compact_trace(event: str, **fields) -> None:
    parts = [str(event or "").strip() or "trace"]
    for key, value in fields.items():
        if value is None:
            continue
        if isinstance(value, bool):
            rendered = "true" if value else "false"
        elif isinstance(value, (int, float)):
            rendered = str(value)
        else:
            rendered = json.dumps(str(value), ensure_ascii=False)
        parts.append(f"{key}={rendered}")
    logging.info(" ".join(parts))


@app.before_request
def trace_authenticated_webapp_request_entry():
    _configure_backend_web_logging()
    path = request.path or ""
    if path not in _AUTH_TRACE_PATHS:
        return None
    payload = request.get_json(silent=True) if request.method in {"POST", "PUT", "PATCH"} else None
    request_id = _extract_observability_request_id(payload if isinstance(payload, dict) else None)
    g.request_id = request_id
    g.auth_trace_started_at_ms = _to_epoch_ms()
    g.auth_trace_started_perf = time.perf_counter()
    _log_compact_trace(
        "auth_req",
        stage="entry",
        request_id=request_id,
        path=path,
        method=request.method,
        started_at_ms=int(g.auth_trace_started_at_ms),
    )
    return None


@app.before_request
def init_compact_request_observability():
    _configure_backend_web_logging()
    path = request.path or ""
    if path not in _REQUEST_LOG_PATHS:
        return None
    payload = request.get_json(silent=True) if request.method in {"POST", "PUT", "PATCH"} else None
    if not getattr(g, "request_id", None):
        g.request_id = _extract_observability_request_id(payload if isinstance(payload, dict) else None)
    if not getattr(g, "correlation_id", None):
        g.correlation_id = _build_observability_correlation_id(
            payload=payload if isinstance(payload, dict) else None,
            prefix="http_request",
        )
    g.request_log_started_perf = time.perf_counter()
    return None


@app.after_request
def trace_authenticated_webapp_request_exit(response):
    path = request.path or ""
    if path not in _AUTH_TRACE_PATHS:
        return response
    started_perf = getattr(g, "auth_trace_started_perf", None)
    duration_ms = int((time.perf_counter() - started_perf) * 1000) if started_perf is not None else None
    _log_compact_trace(
        "auth_req",
        stage="exit",
        request_id=getattr(g, "request_id", None),
        path=path,
        method=request.method,
        user_id=getattr(g, "trace_auth_user_id", None),
        duration_ms=duration_ms,
        status=getattr(response, "status_code", None),
    )
    return response


@app.after_request
def emit_compact_request_observability(response):
    path = request.path or ""
    if path not in _REQUEST_LOG_PATHS:
        return response
    started_perf = getattr(g, "request_log_started_perf", None)
    duration_ms = int((time.perf_counter() - started_perf) * 1000) if started_perf is not None else None
    _log_flow_observation(
        "http_request",
        "completed",
        route=path,
        method=request.method,
        request_id=getattr(g, "request_id", None),
        correlation_id=getattr(g, "correlation_id", None),
        duration_ms=duration_ms,
        status=getattr(response, "status_code", None),
    )
    return response


@app.teardown_request
def trace_authenticated_webapp_request_exception(exc):
    if exc is None or not has_request_context():
        return None
    path = request.path or ""
    if path not in _AUTH_TRACE_PATHS:
        return None
    started_perf = getattr(g, "auth_trace_started_perf", None)
    duration_ms = int((time.perf_counter() - started_perf) * 1000) if started_perf is not None else None
    _log_compact_trace(
        "auth_req",
        stage="exception",
        request_id=getattr(g, "request_id", None),
        path=path,
        method=request.method,
        user_id=getattr(g, "trace_auth_user_id", None),
        duration_ms=duration_ms,
        exception=exc.__class__.__name__,
    )
    return None


def _parse_iso_datetime(value: Any) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        return None


def _duration_between_ms(start_dt: datetime | None, end_dt: datetime | None) -> int | None:
    if not start_dt or not end_dt:
        return None
    start_value = start_dt if start_dt.tzinfo else start_dt.replace(tzinfo=timezone.utc)
    end_value = end_dt if end_dt.tzinfo else end_dt.replace(tzinfo=timezone.utc)
    return max(0, int((end_value - start_value).total_seconds() * 1000))


# _log_flow_observation lives in backend.observability (imported above)


def _estimate_json_payload_size_bytes(payload: Any) -> int | None:
    try:
        return len(json.dumps(payload, ensure_ascii=False, separators=(",", ":"), default=str).encode("utf-8"))
    except Exception:
        return None


_FINISH_REQUEST_OBSERVABILITY_CONTEXT_KEY = "_finish_request_observability_context"


def _get_finish_request_observability_context() -> dict[str, Any] | None:
    if not has_request_context():
        return None
    context = getattr(g, _FINISH_REQUEST_OBSERVABILITY_CONTEXT_KEY, None)
    return context if isinstance(context, dict) else None


def _set_finish_request_observability_context(context: dict[str, Any]) -> dict[str, Any]:
    if has_request_context():
        setattr(g, _FINISH_REQUEST_OBSERVABILITY_CONTEXT_KEY, context)
    return context


def _init_finish_request_observability_context(*, request_id: str, correlation_id: str, started_perf: float) -> dict[str, Any]:
    context = {
        "request_id": request_id,
        "correlation_id": correlation_id,
        "route_started_perf": started_perf,
        "route_name": "finish_webapp_translation",
        "route_path": "/api/webapp/finish",
        "phase": "finish_http_request_received",
        "user_id": None,
        "source_session_id": None,
        "response_sent_logged": False,
    }
    return _set_finish_request_observability_context(context)


def _update_finish_request_observability_context(**fields: Any) -> dict[str, Any] | None:
    context = _get_finish_request_observability_context()
    if context is None:
        return None
    for key, value in fields.items():
        if value is None:
            continue
        context[str(key)] = value
    return context


def _log_finish_request_event(
    stage: str,
    *,
    classification: str,
    phase_started_perf: float | None = None,
    **fields: Any,
) -> None:
    context = _get_finish_request_observability_context() or {}
    context_phase = str(stage or "").strip() or "unknown"
    context["phase"] = context_phase
    payload: dict[str, Any] = {
        "phase": context_phase,
        "classification": str(classification or "").strip() or "unknown",
        "request_id": context.get("request_id"),
        "correlation_id": context.get("correlation_id"),
        "user_id": context.get("user_id"),
        "source_session_id": context.get("source_session_id"),
        "route_name": context.get("route_name"),
        "route_path": context.get("route_path"),
        "route_duration_ms": _elapsed_ms_since(float(context.get("route_started_perf") or time.perf_counter())),
    }
    if phase_started_perf is not None:
        payload["phase_duration_ms"] = _elapsed_ms_since(phase_started_perf)
    for key, value in fields.items():
        if value is None:
            continue
        payload[str(key)] = value
    _log_flow_observation("webapp_translation", context_phase, **payload)


@app.after_request
def _finish_request_after_request(response):
    context = _get_finish_request_observability_context()
    if context and not bool(context.get("response_sent_logged")):
        response_size_bytes = None
        try:
            response_size_bytes = response.calculate_content_length()
        except Exception:
            response_size_bytes = None
        _log_finish_request_event(
            "finish_response_sent",
            classification="success" if int(getattr(response, "status_code", 500) or 500) < 500 else "failure",
            http_status=int(getattr(response, "status_code", 500) or 500),
            response_size_bytes=response_size_bytes,
        )
        context["response_sent_logged"] = True
    return response


@app.teardown_request
def _finish_request_teardown_request(error):
    context = _get_finish_request_observability_context()
    if context and not bool(context.get("response_sent_logged")):
        _log_finish_request_event(
            "finish_response_aborted",
            classification="failure",
            error_code=error.__class__.__name__ if error else "response_not_sent",
        )


def _snapshot_age_ms(snapshot: dict | None) -> int | None:
    refreshed_at = _parse_iso_datetime((snapshot or {}).get("refreshed_at"))
    if refreshed_at is None:
        return None
    now_utc = datetime.now(timezone.utc)
    refreshed_utc = refreshed_at if refreshed_at.tzinfo else refreshed_at.replace(tzinfo=timezone.utc)
    return max(0, int((now_utc - refreshed_utc).total_seconds() * 1000))


def _snapshot_is_fresh(snapshot: dict | None) -> bool:
    fresh_until_at = _parse_iso_datetime((snapshot or {}).get("fresh_until_at"))
    if fresh_until_at is None:
        return False
    fresh_until_utc = fresh_until_at if fresh_until_at.tzinfo else fresh_until_at.replace(tzinfo=timezone.utc)
    return fresh_until_utc > datetime.now(timezone.utc)


def _snapshot_is_servable_stale(snapshot: dict | None) -> bool:
    stale_until_at = _parse_iso_datetime((snapshot or {}).get("stale_until_at"))
    if stale_until_at is None:
        return False
    stale_until_utc = stale_until_at if stale_until_at.tzinfo else stale_until_at.replace(tzinfo=timezone.utc)
    return stale_until_utc > datetime.now(timezone.utc)


def _store_snapshot_in_front_cache(
    cache_manager: HotPathCacheManager,
    *,
    front_key: tuple,
    snapshot: dict | None,
    fresh_ttl_sec: int,
    stale_ttl_sec: int,
) -> None:
    if not isinstance(snapshot, dict):
        return
    payload = snapshot.get("payload") if isinstance(snapshot.get("payload"), dict) else {}
    meta = dict(snapshot.get("meta") or {}) if isinstance(snapshot.get("meta"), dict) else {}
    meta["_snapshot_refreshed_at"] = snapshot.get("refreshed_at")
    meta["_snapshot_fresh_until_at"] = snapshot.get("fresh_until_at")
    meta["_snapshot_stale_until_at"] = snapshot.get("stale_until_at")
    refreshed_at = _parse_iso_datetime(snapshot.get("refreshed_at"))
    refreshed_at_ts = (
        (refreshed_at if refreshed_at and refreshed_at.tzinfo else refreshed_at.replace(tzinfo=timezone.utc)).timestamp()
        if refreshed_at is not None
        else None
    )
    cache_manager.put(
        front_key,
        payload,
        fresh_ttl_sec=fresh_ttl_sec,
        stale_ttl_sec=stale_ttl_sec,
        meta=meta,
        refreshed_at_ts=refreshed_at_ts,
    )


