def _write_translation_check_read_models(
    session: dict[str, Any] | None,
    *,
    pending_items_override: int | None = None,
    running_items_override: int | None = None,
    summary_payload: dict[str, Any] | None = None,
) -> None:
    if not isinstance(session, dict):
        return
    try:
        session_id = int(session.get("id") or 0)
    except Exception:
        return
    if session_id <= 0:
        return
    summary_available = bool(summary_payload) or bool(session.get("summary_json"))
    set_translation_check_status_card(
        session_id,
        _build_translation_check_status_card_payload(
            session,
            pending_items_override=pending_items_override,
            running_items_override=running_items_override,
            summary_available=summary_available,
        ),
    )
    if isinstance(summary_payload, dict) and summary_payload:
        set_translation_check_terminal_summary(session_id, summary_payload)
    elif isinstance(session.get("summary_json"), dict) and session.get("summary_json"):
        set_translation_check_terminal_summary(session_id, dict(session.get("summary_json") or {}))


def _translation_check_card_should_reconcile(
    card_payload: dict[str, Any] | None,
    *,
    state_payload: dict[str, Any] | None = None,
    dispatch_payload: dict[str, Any] | None = None,
) -> bool:
    if not isinstance(card_payload, dict):
        return True
    status = str(card_payload.get("status") or "").strip().lower()
    if status in {"done", "failed", "canceled"}:
        return False
    return _translation_check_redis_state_should_reconcile(
        state_payload if isinstance(state_payload, dict) else {},
        dispatch_payload if isinstance(dispatch_payload, dict) else None,
    )


def _build_translation_check_job_status_payload(
    *,
    session: dict[str, Any] | None,
    status_poll_count: int = 0,
) -> dict[str, Any]:
    compact_session = _build_compact_translation_check_session(session) or {}
    session_status = str(compact_session.get("status") or "queued").strip().lower() or "queued"
    total_items = int(compact_session.get("total_items") or 0)
    completed_items = int(compact_session.get("completed_items") or 0)
    failed_items = int(compact_session.get("failed_items") or 0)
    pending_items = max(0, total_items - completed_items - failed_items)
    if session_status in {"done", "failed", "canceled"}:
        suggested_poll_after_ms = 0
    elif session_status in {"queued", "pending"}:
        suggested_poll_after_ms = 4000
    else:
        suggested_poll_after_ms = 2500
    return {
        "session": compact_session,
        "progress": {
            "total": total_items,
            "completed": completed_items,
            "failed": failed_items,
            "running": 0,
            "pending": pending_items,
        },
        "polling": {
            "suggested_delay_ms": int(suggested_poll_after_ms),
            "terminal": bool(session_status in {"done", "failed", "canceled"}),
        },
    }


def _translation_check_next_poll_after_ms(
    *,
    session_status: str,
) -> int:
    normalized_status = str(session_status or "").strip().lower()
    if normalized_status in {"done", "failed", "canceled"}:
        return 0
    if normalized_status in {"queued", "pending"}:
        return 4000
    return 2500


def _build_translation_check_fast_path_payload(
    *,
    session_id: int,
    user_id: int,
    job_status: dict[str, Any],
    source_lang: str,
    target_lang: str,
    status_poll_count: int = 0,
) -> dict[str, Any] | None:
    if not isinstance(job_status, dict):
        return None
    cached_session = dict(job_status.get("session") or {}) if isinstance(job_status.get("session"), dict) else {}
    if not cached_session:
        return None
    cached_session["id"] = int(cached_session.get("id") or session_id)
    cached_session["user_id"] = int(cached_session.get("user_id") or user_id)
    cached_session["source_lang"] = str(cached_session.get("source_lang") or source_lang or "").strip().lower() or source_lang
    cached_session["target_lang"] = str(cached_session.get("target_lang") or target_lang or "").strip().lower() or target_lang
    status_value = str(job_status.get("status") or cached_session.get("status") or "").strip().lower()
    cached_session["status"] = "queued" if status_value == "pending" else (status_value or "queued")
    if job_status.get("error") and not cached_session.get("last_error"):
        cached_session["last_error"] = str(job_status.get("error") or "").strip() or None
    return _build_translation_check_payload(
        session=cached_session,
        items=[],
        source_lang=str(cached_session.get("source_lang") or source_lang or "ru"),
        target_lang=str(cached_session.get("target_lang") or target_lang or "de"),
        include_items=False,
        status_poll_count=status_poll_count,
    )


def _build_translation_fill_pending_payload(
    *,
    source_lang: str,
    target_lang: str,
    generation_status_payload: dict[str, Any] | None,
    expected_total: int = 7,
    base_payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = dict(base_payload or {})
    normalized_expected_total = max(1, int(expected_total or 7))
    raw_generation_status = str((generation_status_payload or {}).get("status") or "").strip().lower()
    if raw_generation_status in {"pending", "running"}:
        generation_status = raw_generation_status
    else:
        generation_status = "pending"
    payload.update(
        {
            "items": [],
            "ready_count": 0,
            "expected_total": normalized_expected_total,
            "remaining_count": normalized_expected_total,
            "generation_in_progress": True,
            "generation_status": generation_status,
            "generation_error": str((generation_status_payload or {}).get("error") or "").strip() or None,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )
    return payload


def _remember_translation_session_fill_launched_at(session_id: int, launched_at_ms: int) -> None:
    with _OBSERVABILITY_LOCK:
        _TRANSLATION_SESSION_FILL_LAUNCHED_AT_MS[int(session_id)] = int(launched_at_ms)
        if len(_TRANSLATION_SESSION_FILL_LAUNCHED_AT_MS) > 10000:
            _TRANSLATION_SESSION_FILL_LAUNCHED_AT_MS.clear()


def _pop_translation_session_fill_launched_at(session_id: int) -> int | None:
    with _OBSERVABILITY_LOCK:
        return _TRANSLATION_SESSION_FILL_LAUNCHED_AT_MS.pop(int(session_id), None)


def _translation_session_fill_runner_is_active(session_id: int | None) -> bool:
    if session_id is None:
        return False
    with _TRANSLATION_SESSION_FILL_RUNNERS_LOCK:
        return int(session_id) in _TRANSLATION_SESSION_FILL_RUNNERS


def _translation_check_runner_lock_key(session_id: int) -> int:
    # Namespace lock key to avoid collisions with other advisory lock users.
    return (5401 << 32) + (int(session_id) & 0xFFFFFFFF)


def _translation_check_runtime_age_ms(value: Any) -> int | None:
    parsed = _parse_iso_datetime(value)
    if parsed is None:
        return None
    return max(0, int((datetime.now(timezone.utc) - parsed).total_seconds() * 1000))


def _translation_check_redis_state_should_reconcile(
    state_payload: dict[str, Any] | None,
    dispatch_payload: dict[str, Any] | None = None,
) -> bool:
    if not isinstance(state_payload, dict):
        return True
    status = str(state_payload.get("status") or "").strip().lower()
    if status in {"done", "failed", "canceled"}:
        return False

    now_ms = int(time.time() * 1000)

    def _age_ms(raw_value: Any) -> int | None:
        try:
            parsed = int(raw_value)
        except Exception:
            return None
        return max(0, now_ms - parsed)

    if status in {"queued", "pending"}:
        updated_age_ms = _age_ms(state_payload.get("updated_at_ms"))
        dispatched_age_ms = _age_ms((dispatch_payload or {}).get("dispatched_at_ms"))
        if updated_age_ms is not None and updated_age_ms >= _TRANSLATION_CHECK_REDIS_STATE_RECONCILE_QUEUED_STALE_MS:
            return True
        if dispatched_age_ms is not None and dispatched_age_ms >= _TRANSLATION_CHECK_REDIS_STATE_RECONCILE_QUEUED_STALE_MS:
            return True
        return False

    if status == "running":
        heartbeat_age_ms = _age_ms(
            state_payload.get("last_heartbeat_ms")
            or (dispatch_payload or {}).get("last_heartbeat_ms")
        )
        updated_age_ms = _age_ms(state_payload.get("updated_at_ms"))
        if heartbeat_age_ms is not None and heartbeat_age_ms >= _TRANSLATION_CHECK_REDIS_STATE_RECONCILE_RUNNING_STALE_MS:
            return True
        if heartbeat_age_ms is None and updated_age_ms is not None and updated_age_ms >= _TRANSLATION_CHECK_REDIS_STATE_RECONCILE_RUNNING_STALE_MS:
            return True
        return False

    return False


def _normalize_scope_kind_payload(value) -> str:
    kind = str(value or "").strip().lower()
    if kind == "group":
        return "group"
    return "personal"


def _extract_scope_context_from_payload(*, init_data: str, payload: dict | None = None) -> dict:
    body = payload if isinstance(payload, dict) else {}
    scope_context = body.get("scope_context")
    context_payload = scope_context if isinstance(scope_context, dict) else body
    parsed = _parse_telegram_init_data(init_data) if init_data else {}
    chat_type = str(
        context_payload.get("chat_type")
        or parsed.get("chat_type")
        or ""
    ).strip().lower()
    raw_chat_id = context_payload.get("chat_id")
    if raw_chat_id is None:
        raw_chat_id = context_payload.get("id")
    chat_id = _safe_int(raw_chat_id)
    chat_title = str(
        context_payload.get("chat_title")
        or context_payload.get("title")
        or ""
    ).strip() or None
    is_group_type = chat_type in {"group", "supergroup"}
    has_group_context = bool(is_group_type and chat_id is not None)
    return {
        "chat_type": chat_type if chat_type else None,
        "chat_id": int(chat_id) if chat_id is not None else None,
        "chat_title": chat_title,
        "has_group_context": has_group_context,
    }


def _get_authenticated_user_from_request_init_data() -> tuple[int | None, str | None, str | None]:
    payload = request.get_json(silent=True) or {}
    init_data = _extract_request_init_data(payload)
    if not init_data:
        return None, None, "initData обязателен"
    user_id, username = _extract_webapp_user_from_init_data(init_data)
    if not user_id:
        return None, None, "initData не прошёл проверку или user_id отсутствует"
    if not _is_webapp_user_allowed(int(user_id)):
        return None, None, "Доступ к приложению закрыт администратором."
    return int(user_id), username, None


def _admin_token_is_valid() -> bool:
    token = (request.headers.get("X-Admin-Token") or "").strip()
    required = (os.getenv("ADMIN_TOKEN") or os.getenv("AUDIO_DISPATCH_TOKEN") or "").strip()
    if not required:
        return False
    return bool(token) and token == required


def _extract_guard_user_id_for_path(path: str) -> int | None:
    if path == "/api/token":
        try:
            return int(str(request.args.get("user_id") or "").strip())
        except Exception:
            return None
    # enforce_webapp_access already resolved the acting user — from Telegram initData OR the
    # durable browser-dictionary token — and stashed it on g. Prefer that so the billing guard
    # accepts the standalone dictionary's token too (else billed endpoints like TTS 400 with
    # "user_id не определён для billing guard" even though the token authenticated upstream).
    guard_uid = getattr(g, "telegram_user_id", None)
    if guard_uid:
        try:
            return int(guard_uid)
        except Exception:
            pass
    user_id, _username, _error = _get_authenticated_user_from_request_init_data()
    return int(user_id) if user_id is not None else None


# Cache the per-user billing-guard DECISION so the hot path (e.g. every 🔊 tap) doesn't re-run
# ~4-5 billing DB aggregations (entitlement + today's cost SUM + plan limit + today's feature
# SUM + Stripe sync). Soft daily limits tolerate a few-minute staleness — a user can't burn much
# in the window, and every billed action is STILL recorded, so the next re-check after the TTL
# sees the true totals. Invalidated on subscription change so a fresh Pro upgrade is instant.
_BILLING_GUARD_DECISION_CACHE: dict[str, tuple[tuple, float]] = {}
_BILLING_GUARD_DECISION_CACHE_LOCK = threading.Lock()
_BILLING_GUARD_CACHE_TTL_SEC = max(0, int(str(os.getenv("BILLING_GUARD_CACHE_TTL_SEC") or "180").strip() or "180"))
# Paths whose decision depends on request params (not just the user) — never cache these.
_BILLING_GUARD_NO_CACHE_PATHS = {"/api/webapp/youtube/transcript"}


def _drop_local_billing_guard_cache(user_id: int) -> None:
    """Drop this PROCESS's cached billing decisions for one user. No announcement — used both
    by the local invalidation below and by the cross-process feed reader (which must not
    re-publish what it just consumed)."""
    try:
        prefix = f"{int(user_id)}|"
    except Exception:
        return
    with _BILLING_GUARD_DECISION_CACHE_LOCK:
        for k in [key for key in _BILLING_GUARD_DECISION_CACHE if key.startswith(prefix)]:
            _BILLING_GUARD_DECISION_CACHE.pop(k, None)


def _invalidate_billing_guard_cache_for_user(user_id: int) -> None:
    """Drop a user's cached billing decisions (e.g. right after they upgrade/pay) so entitlement
    changes take effect immediately instead of waiting out the TTL.

    The decision cache lives in PROCESS memory, so dropping it here fixes only the worker that
    handled the payment. With WEB_CONCURRENCY=1 that is everyone; the moment the service is
    scaled wider, a paying user would keep seeing «нужен тариф» on every other worker until the
    TTL expired. Announcing the change on the shared feed keeps that from becoming true.
    """
    _drop_local_billing_guard_cache(user_id)
    try:
        publish_cache_invalidation("billing", int(user_id))
    except Exception:
        logging.debug("billing invalidation publish failed uid=%s", user_id, exc_info=True)


_CACHE_INVALIDATION_FEED_ENABLED = str(
    os.getenv("CACHE_INVALIDATION_FEED_ENABLED") or "1"
).strip().lower() in {"1", "true", "yes", "on"}
_CACHE_INVALIDATION_FEED_POLL_SEC = max(
    1, min(60, int(str(os.getenv("CACHE_INVALIDATION_FEED_POLL_SEC") or "5").strip() or "5"))
)
# Re-read a small overlapping window each tick. Two processes never share a clock exactly,
# and dropping a cache entry twice is harmless — missing an event is not.
_CACHE_INVALIDATION_FEED_LOOKBACK_SEC = 30
_cache_invalidation_feed_thread: threading.Thread | None = None
_cache_invalidation_feed_lock = threading.Lock()


def _apply_cache_invalidation_event(kind: str, user_id: int) -> None:
    if kind == "billing":
        _drop_local_billing_guard_cache(user_id)
        return
    if kind == "allowlist":
        _HOTPATH_ALLOWLIST_CACHE.invalidate(_allowlist_cache_key(user_id))
        _HOTPATH_ALLOWLIST_CACHE.invalidate(_self_serve_attempt_memo_key(user_id))
        try:
            invalidate_telegram_user_allowed_cache(user_id)
        except Exception:
            logging.debug("allowlist local invalidation failed uid=%s", user_id, exc_info=True)


def _cache_invalidation_feed_loop() -> None:
    """Poll the shared invalidation feed and apply the events to THIS process's caches.

    One Redis read every few seconds per process, regardless of traffic — deliberately not
    a per-request check, which would trade a rare staleness window for a permanent network
    hop on the hot path. Everything is wrapped: a Redis outage degrades to today's
    TTL-bounded behaviour instead of killing the thread.
    """
    last_seen = time.time() - _CACHE_INVALIDATION_FEED_LOOKBACK_SEC
    while True:
        time.sleep(_CACHE_INVALIDATION_FEED_POLL_SEC)
        try:
            client = get_redis_client()
            if client is None:
                continue
            now = time.time()
            members = client.zrangebyscore(CACHE_INVALIDATION_FEED_KEY, last_seen, "+inf")
            for member in members or []:
                parts = str(member).split(":")
                if len(parts) < 2:
                    continue
                try:
                    _apply_cache_invalidation_event(parts[0], int(parts[1]))
                except Exception:
                    logging.debug("cache invalidation event apply failed: %s", member, exc_info=True)
            last_seen = now - _CACHE_INVALIDATION_FEED_LOOKBACK_SEC
        except Exception:
            logging.debug("cache invalidation feed poll failed", exc_info=True)


def _ensure_cache_invalidation_feed_started() -> None:
    """Start the feed reader lazily, on the first guarded request. Keeps the thread out of
    processes that merely import this module (bot, workers, tests)."""
    global _cache_invalidation_feed_thread
    if not _CACHE_INVALIDATION_FEED_ENABLED or _cache_invalidation_feed_thread is not None:
        return
    with _cache_invalidation_feed_lock:
        if _cache_invalidation_feed_thread is not None:
            return
        try:
            thread = threading.Thread(
                target=_cache_invalidation_feed_loop,
                name="cache-invalidation-feed",
                daemon=True,
            )
            thread.start()
            _cache_invalidation_feed_thread = thread
            logging.info(
                "cache invalidation feed reader started (poll=%ss)", _CACHE_INVALIDATION_FEED_POLL_SEC
            )
        except Exception:
            logging.warning("failed to start cache invalidation feed reader", exc_info=True)


def _apply_billing_guard(path: str) -> tuple[dict | None, int | None]:
    _ensure_cache_invalidation_feed_started()
    rule = _BILLING_GUARD_RULES.get(path) or {}
    user_id = _extract_guard_user_id_for_path(path)
    if user_id is None:
        return {"error": "user_id не определён для billing guard"}, 400
    cacheable = _BILLING_GUARD_CACHE_TTL_SEC > 0 and path not in _BILLING_GUARD_NO_CACHE_PATHS
    cache_key = f"{int(user_id)}|{path}" if cacheable else ""
    if cacheable:
        now = time.time()
        with _BILLING_GUARD_DECISION_CACHE_LOCK:
            hit = _BILLING_GUARD_DECISION_CACHE.get(cache_key)
            if hit and hit[1] > now:
                return hit[0]
    decision = _compute_billing_guard(path, rule, int(user_id))
    if cacheable:
        with _BILLING_GUARD_DECISION_CACHE_LOCK:
            _BILLING_GUARD_DECISION_CACHE[cache_key] = (decision, time.time() + _BILLING_GUARD_CACHE_TTL_SEC)
    return decision


def _compute_billing_guard(path: str, rule: dict, user_id: int) -> tuple[dict | None, int | None]:
    if path == "/api/webapp/youtube/transcript":
        payload = request.get_json(silent=True) or {}
        video_id = str(payload.get("videoId") or "").strip()
        if video_id:
            cached_data, _cache_tier, _cached_db_duration_ms = _load_cached_youtube_transcript_data(video_id)
            if cached_data:
                return None, None

    if path == "/api/webapp/youtube/translate":
        if not _can_access_youtube_subtitle_translation(int(user_id)):
            return None, None

    paid_feature = str(rule.get("paid_feature") or "").strip()
    if paid_feature:
        payload, status = _paid_surface_gate_response(
            user_id=int(user_id),
            feature=paid_feature,
            feature_title=str(rule.get("paid_feature_title") or paid_feature),
        )
        if payload:
            return payload, status

    _sync_user_subscription_from_live_stripe(user_id=int(user_id))
    now_utc = datetime.now(timezone.utc)
    if bool(rule.get("cap")):
        cap_error = enforce_daily_cost_cap(user_id=int(user_id), now_ts_utc=now_utc, tz="Europe/Vienna")
        if cap_error:
            return cap_error, 429

    feature_code = str(rule.get("feature_code") or "").strip()
    if feature_code:
        payload = request.get_json(silent=True) or {}
        requested_units = 1.0
        if feature_code == "tts_chars_daily":
            requested_units = float(len((payload.get("text") or "").strip()))
        feature_error = enforce_feature_limit(
            user_id=int(user_id),
            feature_code=feature_code,
            requested_units=requested_units,
            now_ts_utc=now_utc,
            tz="Europe/Vienna",
        )
        if feature_error:
            return feature_error, 429
    return None, None


def _today_local_date(tz_name: str = "Europe/Vienna") -> date:
    try:
        tzinfo = ZoneInfo(str(tz_name or "Europe/Vienna"))
    except Exception:
        tzinfo = timezone.utc
    return datetime.now(timezone.utc).astimezone(tzinfo).date()


def _sum_billing_units_today(
    *,
    user_id: int,
    action_type: str,
    units_type: str,
    tz_name: str = "Europe/Vienna",
    cursor=None,
) -> float:
    action_value = str(action_type or "").strip().lower()
    units_value = str(units_type or "").strip().lower()
    if not action_value or not units_value:
        return 0.0
    day_local = _today_local_date(tz_name=tz_name)
    query = """
        SELECT COALESCE(SUM(units_value), 0)
        FROM bt_3_billing_events
        WHERE user_id = %s
          AND action_type = %s
          AND units_type = %s
          AND (event_time AT TIME ZONE %s)::date = %s;
    """
    params = (int(user_id), action_value, units_value, str(tz_name or "Europe/Vienna"), day_local)
    try:
        if cursor is not None:
            cursor.execute(query, params)
            row = cursor.fetchone()
            return float((row or [0])[0] or 0.0)
        with db_acquire_scope("billing_units_today"), get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(query, params)
                row = cursor.fetchone()
        return float((row or [0])[0] or 0.0)
    except Exception:
        return 0.0


def _normalize_flashcards_mode(mode: str | None) -> str:
    value = str(mode or "").strip().lower()
    if value in {"quiz", "blocks", "sentence", "fsrs"}:
        return value
    return "quiz"


FLASHCARDS_QUEUE_SOURCE_ALLOWED = {"system", "manual"}
MANUAL_TRAINING_SELECTION_MAX_CARDS = 5000


def _normalize_flashcards_queue_source(value: str | None) -> str:
    normalized = str(value or "").strip().lower()
    if normalized in FLASHCARDS_QUEUE_SOURCE_ALLOWED:
        return normalized
    return "system"


def _resolve_flashcards_manual_selection(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    queue_source: str,
    cursor=None,
) -> list[int] | None:
    normalized_queue_source = _normalize_flashcards_queue_source(queue_source)
    if normalized_queue_source != "manual":
        return None
    return get_manual_training_selection_card_ids(
        user_id=int(user_id),
        source_lang=source_lang,
        target_lang=target_lang,
        cursor=cursor,
    )


def _build_manual_selection_availability(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    card_ids: list[int],
    now_utc: datetime | None = None,
    cursor=None,
) -> dict:
    """Честная сводка по ручной выборке: сколько отмечено, сколько очередь отдаст СЕЙЧАС,
    сколько спит до своего срока и когда вернётся ближайшее.

    ЗАЧЕМ. Счётчик «Выбрано сейчас: 9» обещал девять карточек, а очередь отдавала
    столько, сколько разрешал интервал повторения (замер 27.08.2026: 8 из 9, девятое
    спало до следующего дня). Два разных числа на одном экране — это и есть дефект,
    который человек видит как «программа потеряла мои слова». Алгоритм не трогаем
    (решение владельца 27.08.2026), но экран обязан назвать оба числа заранее.

    ЕДИНЫЙ ИСТОЧНИК. `available_now` берётся из _compute_srs_queue_info — того же
    расчёта, которым живёт сама выдача карточек. Своего правила отбора здесь нет
    специально: иначе экран и очередь разошлись бы уже на следующей правке.
    """
    now_utc = now_utc or datetime.now(timezone.utc)
    normalized_ids = [int(card_id) for card_id in (card_ids or []) if int(card_id) > 0]
    if not normalized_ids:
        return {
            "selected_total": 0,
            "available_now": 0,
            "asleep_count": 0,
            "next_available_at": None,
            "not_trainable_count": 0,
        }
    queue_info = _compute_srs_queue_info(
        user_id=int(user_id),
        now_utc=now_utc,
        source_lang=source_lang,
        target_lang=target_lang,
        queue_source="manual",
        allowed_card_ids=normalized_ids,
        cursor=cursor,
    )
    sleep_info = describe_manual_selection_sleep(
        user_id=int(user_id),
        card_ids=normalized_ids,
        now_utc=now_utc,
        cursor=cursor,
    )
    available_now = int(queue_info.get("due_count") or 0) + int(queue_info.get("new_remaining_today") or 0)
    return {
        "selected_total": len(normalized_ids),
        "available_now": max(0, available_now),
        "asleep_count": int(sleep_info.get("asleep_count") or 0),
        "next_available_at": sleep_info.get("next_due_at"),
        "not_trainable_count": int(sleep_info.get("not_trainable_count") or 0),
    }


def _build_upgrade_payload(plan_code: str = "pro") -> dict:
    return {
        "available": True,
        "plan_code": str(plan_code or "pro"),
        "action": "checkout",
        "endpoint": "/api/billing/create-checkout-session",
    }


def _check_flashcards_words_daily_limit(
    *,
    user_id: int,
    mode: str,
    requested_words: int,
    tz_name: str = "Europe/Vienna",
    cursor=None,
) -> dict:
    normalized_mode = _normalize_flashcards_mode(mode)
    safe_requested = max(1, int(requested_words or 1))
    now_utc = datetime.now(timezone.utc)
    entitlement, _subscription = _resolve_user_entitlement(
        user_id=int(user_id),
        now_ts_utc=now_utc,
        tz=tz_name,
        refresh_from_stripe=cursor is None,
        cursor=cursor,
    )
    effective_mode = str(entitlement.get("effective_mode") or "free").strip().lower() or "free"
    if effective_mode != "free":
        return {
            "allowed_words": safe_requested,
            "used_words": 0.0,
            "limit_words": None,
            "effective_mode": effective_mode,
        }

    used_words = _sum_billing_units_today(
        user_id=int(user_id),
        action_type=f"flashcards_words_answered_{normalized_mode}",
        units_type="words",
        tz_name=tz_name,
        cursor=cursor,
    )
    limit_words = float(FREE_FLASHCARDS_WORDS_DAILY_PER_MODE)
    remaining_words = max(0.0, limit_words - used_words)
    allowed_words = min(safe_requested, max(0, int(remaining_words)))
    if allowed_words <= 0:
        reset_at = str(entitlement.get("reset_at") or "").strip()
        return {
            "error": {
                "error": "feature_limit_exceeded",
                "error_code": "flashcards_daily_words_limit_exceeded",
                "limit": int(limit_words),
                "reset_at": reset_at,
                "title": "Лимит повторения слов на сегодня достигнут",
                "message": (
                    f"На бесплатном тарифе можно повторять до {int(limit_words)} слов в день.\n\n"
                    "Завтра лимит автоматически обновится."
                ),
                "upgrade": _build_upgrade_payload("pro"),
            }
        }
    return {
        "allowed_words": int(allowed_words),
        "used_words": float(used_words),
        "limit_words": int(limit_words),
        "effective_mode": effective_mode,
    }


def _log_flashcards_words_answered(
    *,
    user_id: int,
    mode: str,
    answered_words: int,
    source_lang: str,
    target_lang: str,
) -> None:
    count = max(0, int(answered_words or 0))
    if count <= 0:
        return
    normalized_mode = _normalize_flashcards_mode(mode)
    _billing_log_event_safe(
        user_id=int(user_id),
        action_type=f"flashcards_words_answered_{normalized_mode}",
        provider="app_internal",
        units_type="words",
        units_value=float(count),
        source_lang=source_lang,
        target_lang=target_lang,
        status="estimated",
        metadata={"mode": normalized_mode, "answered_words": count},
        idempotency_seed=f"flashcards_words_answered:{user_id}:{normalized_mode}:{count}:{time.time_ns()}",
    )


def _flashcards_free_limit_queue_info(limit_state: dict | None, *, pending_answered_words: int = 0) -> dict:
    state = limit_state if isinstance(limit_state, dict) else {}
    effective_mode = str(state.get("effective_mode") or "free").strip().lower() or "free"
    payload: dict[str, object] = {"effective_mode": effective_mode}
    if effective_mode == "free":
        limit_words = int(state.get("limit_words") or FREE_FLASHCARDS_WORDS_DAILY_PER_MODE)
        used_words = int(float(state.get("used_words") or 0)) + max(0, int(pending_answered_words or 0))
        payload["free_daily_words_limit"] = limit_words
        payload["free_daily_words_used"] = min(used_words, limit_words)
    else:
        payload["free_daily_words_limit"] = None
        payload["free_daily_words_used"] = None
    return payload


def _check_voice_minutes_daily_limit(
    *,
    user_id: int,
    tz_name: str = "Europe/Vienna",
) -> dict:
    now_utc = datetime.now(timezone.utc)
    entitlement, _subscription = _resolve_user_entitlement(user_id=int(user_id), now_ts_utc=now_utc, tz=tz_name)
    effective_mode = str(entitlement.get("effective_mode") or "free").strip().lower() or "free"
    daily_limit = float(FREE_VOICE_MINUTES_DAILY_LIMIT if effective_mode == "free" else PAID_VOICE_MINUTES_DAILY_LIMIT)
    used_minutes = _sum_billing_units_today(
        user_id=int(user_id),
        action_type="livekit_room_minutes",
        units_type="audio_minutes",
        tz_name=tz_name,
    )
    if used_minutes >= daily_limit:
        return {
            "error": {
                "error": "feature_limit_exceeded",
                "error_code": "voice_minutes_daily_limit_exceeded",
                "feature": "voice_minutes_daily",
                "limit": int(daily_limit),
                "used": round(float(used_minutes), 3),
                "unit": "minutes",
                "reset_at": entitlement.get("reset_at"),
                "upgrade": _build_upgrade_payload("pro"),
            }
        }
    return {
        "effective_mode": effective_mode,
        "limit_minutes": int(daily_limit),
        "used_minutes": round(float(used_minutes), 3),
    }


def _parse_iso_datetime_utc(value: str | None) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except Exception:
        return None


def _is_reader_doc_expired_for_free(doc: dict | None) -> tuple[bool, str | None]:
    item = doc if isinstance(doc, dict) else {}
    created_at_dt = _parse_iso_datetime_utc(item.get("created_at"))
    if created_at_dt is None:
        return False, None
    expires_at_dt = created_at_dt + timedelta(days=FREE_READER_STORAGE_DAYS)
    return datetime.now(timezone.utc) > expires_at_dt, expires_at_dt.isoformat()


def _get_user_language_pair(user_id: int) -> tuple[str, str, dict]:
    user_key = int(user_id)
    now_ts = time.time()
    cached_entry: dict | None = None
    with _LANGUAGE_PAIR_CACHE_LOCK:
        cached = _LANGUAGE_PAIR_CACHE.get(user_key)
        if isinstance(cached, dict):
            cached_entry = dict(cached)
        if cached and float(cached.get("expires_at") or 0.0) > now_ts:
            native_language, learning_language = _normalize_language_profile_for_mode(
                native_language=cached.get("source_lang"),
                learning_language=cached.get("target_lang"),
            )
            return (
                native_language,
                learning_language,
                _normalize_language_profile_payload_for_mode(
                    dict(cached.get("profile") or {}),
                    user_id=user_key,
                ),
            )
    if cached_entry:
        native_language, learning_language = _normalize_language_profile_for_mode(
            native_language=cached_entry.get("source_lang"),
            learning_language=cached_entry.get("target_lang"),
        )
        return (
            native_language,
            learning_language,
            _normalize_language_profile_payload_for_mode(
                cached_entry.get("profile") or {},
                user_id=user_key,
            ),
        )

    profile = _normalize_language_profile_payload_for_mode(
        get_user_language_profile(user_id=user_key),
        user_id=user_key,
    )
    native_language, learning_language = _normalize_language_profile_for_mode(
        native_language=profile.get("native_language"),
        learning_language=profile.get("learning_language"),
    )
    with _LANGUAGE_PAIR_CACHE_LOCK:
        _LANGUAGE_PAIR_CACHE[user_key] = {
            "source_lang": native_language,
            "target_lang": learning_language,
            "profile": dict(profile or {}),
            "expires_at": now_ts + float(LANGUAGE_PAIR_CACHE_TTL_SEC),
        }
    return native_language, learning_language, profile


def _extract_webapp_language_pair_hint(payload: dict | None = None) -> tuple[str, str] | None:
    body = payload if isinstance(payload, dict) else (request.get_json(silent=True) or {})
    pair_payload = body.get("language_pair") if isinstance(body.get("language_pair"), dict) else {}
    source_lang = _normalize_short_lang_code(
        request.headers.get("X-Webapp-Source-Lang")
        or request.args.get("source_lang")
        or pair_payload.get("source_lang")
        or body.get("source_lang"),
        fallback="",
    )
    target_lang = _normalize_short_lang_code(
        request.headers.get("X-Webapp-Target-Lang")
        or request.args.get("target_lang")
        or pair_payload.get("target_lang")
        or body.get("target_lang"),
        fallback="",
    )
    if source_lang not in SUPPORTED_NATIVE_LANGUAGES:
        return None
    if target_lang not in SUPPORTED_LEARNING_LANGUAGES:
        return None
    return source_lang, target_lang


def _remember_user_language_pair_hint(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    cached_profile: dict | None = None,
) -> dict:
    safe_user_id = int(user_id)
    profile_payload = dict(cached_profile or {})
    if not profile_payload:
        profile_payload = {
            "user_id": safe_user_id,
            "native_language": str(source_lang or "ru").strip().lower() or "ru",
            "learning_language": str(target_lang or "de").strip().lower() or "de",
            "updated_at": None,
            "has_profile": False,
        }
    now_ts = time.time()
    with _LANGUAGE_PAIR_CACHE_LOCK:
        _LANGUAGE_PAIR_CACHE[safe_user_id] = {
            "source_lang": str(source_lang or "ru").strip().lower() or "ru",
            "target_lang": str(target_lang or "de").strip().lower() or "de",
            "profile": dict(profile_payload),
            "expires_at": now_ts + float(LANGUAGE_PAIR_CACHE_TTL_SEC),
        }
    return dict(profile_payload)


def _get_user_language_pair_for_webapp_request(
    user_id: int,
    *,
    payload: dict | None = None,
) -> tuple[str, str, dict, str]:
    safe_user_id = int(user_id)
    hint_pair = _extract_webapp_language_pair_hint(payload)
    if hint_pair:
        source_lang, target_lang = _normalize_language_profile_for_mode(
            native_language=hint_pair[0],
            learning_language=hint_pair[1],
        )
        cached_profile: dict | None = None
        with _LANGUAGE_PAIR_CACHE_LOCK:
            cached = _LANGUAGE_PAIR_CACHE.get(safe_user_id)
            if cached:
                cached_profile = _normalize_language_profile_payload_for_mode(
                    dict(cached.get("profile") or {}),
                    user_id=safe_user_id,
                )
        profile = _remember_user_language_pair_hint(
            user_id=safe_user_id,
            source_lang=source_lang,
            target_lang=target_lang,
            cached_profile=cached_profile,
        )
        return source_lang, target_lang, profile, "request_hint"

    user_key = safe_user_id
    now_ts = time.time()
    cached_entry: dict | None = None
    with _LANGUAGE_PAIR_CACHE_LOCK:
        cached = _LANGUAGE_PAIR_CACHE.get(user_key)
        if isinstance(cached, dict):
            cached_entry = dict(cached)
        if cached and float(cached.get("expires_at") or 0.0) > now_ts:
            native_language, learning_language = _normalize_language_profile_for_mode(
                native_language=cached.get("source_lang"),
                learning_language=cached.get("target_lang"),
            )
            return (
                native_language,
                learning_language,
                _normalize_language_profile_payload_for_mode(
                    dict(cached.get("profile") or {}),
                    user_id=safe_user_id,
                ),
                "memory_cache",
            )
    if cached_entry:
        native_language, learning_language = _normalize_language_profile_for_mode(
            native_language=cached_entry.get("source_lang"),
            learning_language=cached_entry.get("target_lang"),
        )
        return (
            native_language,
            learning_language,
            _normalize_language_profile_payload_for_mode(
                cached_entry.get("profile") or {},
                user_id=safe_user_id,
            ),
            "stale_memory_cache",
        )

    profile = _normalize_language_profile_payload_for_mode(
        get_user_language_profile(user_id=user_key),
        user_id=user_key,
    )
    native_language, learning_language = _normalize_language_profile_for_mode(
        native_language=profile.get("native_language"),
        learning_language=profile.get("learning_language"),
    )
    _remember_user_language_pair_hint(
        user_id=user_key,
        source_lang=native_language,
        target_lang=learning_language,
        cached_profile=profile,
    )
    return native_language, learning_language, profile, "db_profile"


def _invalidate_user_language_pair_cache(user_id: int) -> None:
    with _LANGUAGE_PAIR_CACHE_LOCK:
        _LANGUAGE_PAIR_CACHE.pop(int(user_id), None)


def _build_starter_dictionary_offer(
    *,
    user_id: int,
    source_lang: str | None = None,
    target_lang: str | None = None,
    profile: dict | None = None,
) -> dict:
    safe_user_id = int(user_id)
    profile_payload = dict(profile or {}) if isinstance(profile, dict) else get_user_language_profile(safe_user_id)
    has_profile = bool(profile_payload.get("has_profile"))
    pair_source = str(
        source_lang
        or profile_payload.get("native_language")
        or "ru"
    ).strip().lower() or "ru"
    pair_target = str(
        target_lang
        or profile_payload.get("learning_language")
        or "de"
    ).strip().lower() or "de"

    state = get_starter_dictionary_state(safe_user_id)
    user_pair_total = count_dictionary_entries_for_language_pair(
        safe_user_id,
        pair_source,
        pair_target,
        both_directions=True,
    )
    starter_pair_total = count_starter_dictionary_entries_for_language_pair(
        safe_user_id,
        pair_source,
        pair_target,
    )

    template_total = 0
    if STARTER_DICTIONARY_ENABLED and STARTER_DICTIONARY_SOURCE_USER_ID > 0:
        template_total = count_dictionary_entries_for_language_pair(
            int(STARTER_DICTIONARY_SOURCE_USER_ID),
            pair_source,
            pair_target,
            both_directions=True,
        )

    subscription_available = 0
    try:
        if state.get("live_subscription") and STARTER_DICTIONARY_SOURCE_USER_ID > 0:
            subscription_available = count_admin_subscription_available_words(
                user_id=safe_user_id,
                source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
                source_lang=pair_source,
                target_lang=pair_target,
            )
    except Exception:
        logging.debug("не удалось посчитать доступное по подписке uid=%s", safe_user_id, exc_info=True)
    try:
        subscription_delivered = count_subscription_delivered(safe_user_id)
    except Exception:
        logging.debug("не удалось посчитать выданное по подписке uid=%s", safe_user_id, exc_info=True)
        subscription_delivered = 0
    decision_status = str(state.get("decision_status") or "pending").strip().lower() or "pending"
    suggested_count = min(max(0, int(template_total)), int(STARTER_DICTIONARY_IMPORT_LIMIT))
    should_prompt = bool(
        STARTER_DICTIONARY_ENABLED
        and has_profile
        and template_total > 0
        and user_pair_total <= 0
        and decision_status == "pending"
    )

    return {
        "enabled": bool(STARTER_DICTIONARY_ENABLED),
        "source_user_id": int(STARTER_DICTIONARY_SOURCE_USER_ID),
        "template_version": STARTER_DICTIONARY_TEMPLATE_VERSION,
        "import_limit": int(STARTER_DICTIONARY_IMPORT_LIMIT),
        "folder_name": STARTER_DICTIONARY_FOLDER_NAME,
        "source_lang": pair_source,
        "target_lang": pair_target,
        "state": state,
        "has_profile": has_profile,
        "user_pair_total": int(user_pair_total),
        "starter_pair_total": int(starter_pair_total),
        "template_total": int(template_total),
        "suggested_count": int(suggested_count),
        "should_prompt": should_prompt,
        "can_reconnect": bool(STARTER_DICTIONARY_ENABLED and template_total > 0 and has_profile),
        # Отключить можно всегда, когда подписка включена. Раньше кнопка зависела от числа
        # СКОПИРОВАННЫХ строк, а подписка не копирует ничего — поэтому у подписчиков она
        # была вечно серой, то есть заблокирована ровно у тех, кому нужна.
        "can_disconnect": bool(int(starter_pair_total) > 0 or state.get("live_subscription")),
        # Сколько слов автора человек уже получил и сколько ему положено. По этим числам
        # интерфейс показывает «урезанный выбран до конца — включить весь?», иначе выдача
        # просто молча останавливается и читается как поломка.
        "subscription_limit": state.get("subscription_limit"),
        "subscription_delivered": int(subscription_delivered),
        # Сколько слов автора человеку ещё доступно. Функция была написана, но НИ РАЗУ не
        # вызывалась — и именно из неё однажды взяли число, которое показали как факт.
        # Теперь она питает интерфейс, а не лежит мёртвым грузом.
        "subscription_available": int(subscription_available),
        "subscription_exhausted": bool(
            state.get("live_subscription")
            and state.get("subscription_limit")
            and subscription_delivered >= int(state.get("subscription_limit") or 0)
        ),
    }


def _run_starter_dictionary_import_job(
    *,
    job_id: str,
    user_id: int,
    source_lang: str,
    target_lang: str,
    decided_at: datetime,
    previous_imported_count: int,
    previous_imported_at: datetime | None,
    import_limit: int | None = None,
) -> None:
    started_at = datetime.now(timezone.utc)
    effective_limit = max(1, min(50000, int(import_limit or STARTER_DICTIONARY_IMPORT_LIMIT)))
    try:
        import_result = import_starter_dictionary_snapshot(
            source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
            target_user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            import_limit=effective_limit,
            folder_name=STARTER_DICTIONARY_FOLDER_NAME,
            template_version=STARTER_DICTIONARY_TEMPLATE_VERSION,
        )
        imported_count = max(0, int(import_result.get("inserted_count") or 0))
        imported_at = datetime.now(timezone.utc)
        upsert_starter_dictionary_state(
            user_id=int(user_id),
            decision_status="accepted",
            source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
            template_version=STARTER_DICTIONARY_TEMPLATE_VERSION,
            source_lang=source_lang,
            target_lang=target_lang,
            last_imported_count=imported_count,
            decided_at=decided_at,
            last_imported_at=imported_at,
            import_status="done",
            active_job_id=None,
            last_error=None,
            import_started_at=started_at,
            import_finished_at=imported_at,
        )
        logging.info(
            "Starter dictionary import completed: user=%s job=%s source_lang=%s target_lang=%s inserted=%s",
            int(user_id),
            str(job_id or "").strip(),
            str(source_lang or "").strip().lower(),
            str(target_lang or "").strip().lower(),
            imported_count,
        )
    except Exception as exc:
        finished_at = datetime.now(timezone.utc)
        upsert_starter_dictionary_state(
            user_id=int(user_id),
            decision_status="accepted",
            source_user_id=int(STARTER_DICTIONARY_SOURCE_USER_ID),
            template_version=STARTER_DICTIONARY_TEMPLATE_VERSION,
            source_lang=source_lang,
            target_lang=target_lang,
            last_imported_count=max(0, int(previous_imported_count or 0)),
            decided_at=decided_at,
            last_imported_at=previous_imported_at,
            import_status="failed",
            active_job_id=None,
            last_error=str(exc or "").strip() or "starter_dictionary_import_failed",
            import_started_at=started_at,
            import_finished_at=finished_at,
        )
        logging.warning(
            "Starter dictionary import failed: user=%s job=%s source_lang=%s target_lang=%s error=%s",
            int(user_id),
            str(job_id or "").strip(),
            str(source_lang or "").strip().lower(),
            str(target_lang or "").strip().lower(),
            exc,
            exc_info=True,
        )


def _start_starter_dictionary_import_runner(
    *,
    job_id: str,
    user_id: int,
    source_lang: str,
    target_lang: str,
    decided_at: datetime,
    previous_imported_count: int,
    previous_imported_at: datetime | None,
    import_limit: int | None = None,
) -> None:
    worker = threading.Thread(
        target=_run_starter_dictionary_import_job,
        kwargs={
            "job_id": str(job_id or "").strip(),
            "user_id": int(user_id),
            "source_lang": str(source_lang or "").strip().lower(),
            "target_lang": str(target_lang or "").strip().lower(),
            "decided_at": decided_at,
            "previous_imported_count": max(0, int(previous_imported_count or 0)),
            "previous_imported_at": previous_imported_at,
            "import_limit": import_limit,
        },
        daemon=True,
        name=f"starter-dictionary-{int(user_id)}",
    )
    worker.start()


def _normalize_dictionary_lookup_word(word: str) -> str:
    compact = re.sub(r"\s+", " ", str(word or "").strip())
    return compact.casefold()


def _build_dictionary_lookup_cache_key(
    *,
    user_id: int | None,
    source_lang: str,
    target_lang: str,
    query_source_lang: str,
    query_target_lang: str,
    lookup_lang: str,
    word: str,
) -> str:
    normalized_word = _normalize_dictionary_lookup_word(word)
    owner = str(int(user_id)) if user_id is not None else "shared"
    return "|".join(
        [
            DICTIONARY_CACHE_SCHEMA_VERSION,
            owner,
            str(source_lang or "").strip().lower(),
            str(target_lang or "").strip().lower(),
            str(query_source_lang or "").strip().lower(),
            str(query_target_lang or "").strip().lower(),
            str(lookup_lang or "").strip().lower(),
            normalized_word,
        ]
    )


def _prune_dictionary_lookup_cache(now_ts: float) -> None:
    expired_keys = [
        key
        for key, payload in _DICTIONARY_LOOKUP_CACHE.items()
        if float(payload.get("expires_at") or 0.0) <= now_ts
    ]
    for key in expired_keys:
        _DICTIONARY_LOOKUP_CACHE.pop(key, None)

    while len(_DICTIONARY_LOOKUP_CACHE) > DICTIONARY_LOOKUP_CACHE_MAX_ITEMS:
        oldest_key = min(
            _DICTIONARY_LOOKUP_CACHE.items(),
            key=lambda item: float(item[1].get("created_at") or 0.0),
        )[0]
        _DICTIONARY_LOOKUP_CACHE.pop(oldest_key, None)


def _get_cached_dictionary_lookup(cache_key: str) -> dict | None:
    now_ts = time.time()
    with _DICTIONARY_LOOKUP_CACHE_LOCK:
        cached = _DICTIONARY_LOOKUP_CACHE.get(cache_key)
        if not cached:
            return None
        if float(cached.get("expires_at") or 0.0) <= now_ts:
            _DICTIONARY_LOOKUP_CACHE.pop(cache_key, None)
            return None
        cached["last_hit_at"] = now_ts
        payload = copy.deepcopy(cached.get("payload") or {})
    return payload if isinstance(payload, dict) else None


def _drop_cached_dictionary_lookup(cache_key: str) -> None:
    """Выбросить запись словарного кэша — и из памяти, и из общей базы.

    Нужна там, где кэш оказался НЕПРАВ: он живёт годами и раздаётся всем, поэтому
    ошибочная карточка должна уметь исчезнуть, а не ждать истечения срока."""
    if not cache_key:
        return
    with _DICTIONARY_LOOKUP_CACHE_LOCK:
        _DICTIONARY_LOOKUP_CACHE.pop(cache_key, None)
    if not DICTIONARY_PERSISTENT_CACHE_ENABLED:
        return
    try:
        from backend.database import delete_dictionary_lookup_cache
        delete_dictionary_lookup_cache(cache_key=cache_key)
    except Exception:
        logging.debug("не удалось убрать кэш словаря из базы: %s", cache_key, exc_info=True)


def _set_cached_dictionary_lookup(cache_key: str, payload: dict) -> None:
    if not cache_key or not isinstance(payload, dict):
        return
    now_ts = time.time()
    cache_payload = copy.deepcopy(payload)
    with _DICTIONARY_LOOKUP_CACHE_LOCK:
        _DICTIONARY_LOOKUP_CACHE[cache_key] = {
            "payload": cache_payload,
            "created_at": now_ts,
            "last_hit_at": now_ts,
            "expires_at": now_ts + float(DICTIONARY_LOOKUP_CACHE_TTL_SEC),
        }
        _prune_dictionary_lookup_cache(now_ts)


def _build_quick_translate_cache_key(*, text: str, source_lang: str | None, target_lang: str) -> str:
    safe_text = str(text or "").strip()
    # ОДНО СЛОВО — ОДИН КЛЮЧ, независимо от регистра. Первое слово в строке человек
    # пишет с большой буквы, это норма письма, а не другой запрос. Раньше «Толстый»
    # и «толстый» были для нас двумя разными словами с двумя разными ответами
    # (замер 11.08.2026: в общем пуле 35 таких пар).
    # У фраз регистр не трогаем: там заглавная буква может стоять за именем.
    if safe_text and " " not in safe_text:
        safe_text = safe_text.casefold()
    safe_source_lang = _normalize_short_lang_code(source_lang, fallback="") or ""
    safe_target_lang = _normalize_short_lang_code(target_lang, fallback="de")
    text_hash = hashlib.sha1(safe_text.encode("utf-8", "ignore")).hexdigest()
    return f"{safe_source_lang}:{safe_target_lang}:{text_hash}"


def _prune_quick_translate_cache(now_ts: float) -> None:
    expired_keys = [
        key
        for key, payload in _QUICK_TRANSLATE_CACHE.items()
        if float((payload or {}).get("expires_at") or 0.0) <= now_ts
    ]
    for key in expired_keys:
        _QUICK_TRANSLATE_CACHE.pop(key, None)

    while len(_QUICK_TRANSLATE_CACHE) > QUICK_TRANSLATE_CACHE_MAX_ITEMS:
        oldest_key = min(
            _QUICK_TRANSLATE_CACHE.items(),
            key=lambda item: float((item[1] or {}).get("created_at") or 0.0),
        )[0]
        _QUICK_TRANSLATE_CACHE.pop(oldest_key, None)


def _get_cached_quick_translate(cache_key: str) -> dict | None:
    safe_cache_key = str(cache_key or "").strip()
    if not safe_cache_key:
        return None
    now_ts = time.time()
    with _QUICK_TRANSLATE_CACHE_LOCK:
        cached = _QUICK_TRANSLATE_CACHE.get(safe_cache_key)
        if not cached:
            return None
        if float(cached.get("expires_at") or 0.0) <= now_ts:
            _QUICK_TRANSLATE_CACHE.pop(safe_cache_key, None)
            return None
        cached["last_hit_at"] = now_ts
        payload = copy.deepcopy(cached.get("payload") or {})
    return payload if isinstance(payload, dict) else None


def _set_cached_quick_translate(cache_key: str, payload: dict) -> None:
    safe_cache_key = str(cache_key or "").strip()
    if not safe_cache_key or not isinstance(payload, dict):
        return
    now_ts = time.time()
    cache_payload = copy.deepcopy(payload)
    with _QUICK_TRANSLATE_CACHE_LOCK:
        _QUICK_TRANSLATE_CACHE[safe_cache_key] = {
            "payload": cache_payload,
            "created_at": now_ts,
            "last_hit_at": now_ts,
            "expires_at": now_ts + float(QUICK_TRANSLATE_CACHE_TTL_SEC),
        }
        _prune_quick_translate_cache(now_ts)


def _acquire_quick_translate_inflight_slot(cache_key: str) -> tuple[bool, threading.Event | None]:
    safe_cache_key = str(cache_key or "").strip()
    if not safe_cache_key:
        return True, None
    with _QUICK_TRANSLATE_CACHE_LOCK:
        existing = _QUICK_TRANSLATE_INFLIGHT.get(safe_cache_key)
        if existing is not None:
            return False, existing
        event = threading.Event()
        _QUICK_TRANSLATE_INFLIGHT[safe_cache_key] = event
        return True, event


def _release_quick_translate_inflight_slot(cache_key: str) -> None:
    safe_cache_key = str(cache_key or "").strip()
    if not safe_cache_key:
        return
    with _QUICK_TRANSLATE_CACHE_LOCK:
        event = _QUICK_TRANSLATE_INFLIGHT.pop(safe_cache_key, None)
    if event is not None:
        event.set()


# Кеш вычитки жил ЗДЕСЬ и был вторым — своим у мини-аппа, отдельно от бота. Обе
# поверхности спрашивали один и тот же корректор об одном и том же слове и платили
# дважды. С 21.08.2026 кеш и правило одни на всех и живут в `backend/dictionary_door.py`.


def _run_dictionary_door_proofread(text: str, *, lang: str, user_id, origin: str) -> str:
    """Вычитка через ОБЩИЙ модуль `backend/dictionary_door.py` — одно правило на всех.

    До 21.08.2026 копий было две: своя у бота и своя у мини-аппа. Разные функции, разные
    кеши, один и тот же корректор внутри — ровно то расхождение, против которого общий
    модуль и написан: обе поверхности спрашивали модель об одном и том же слове и
    платили дважды. Веб-копия вдобавок пускала к модели то, за что платить незачем: у
    общей двери отсечки строже (длина, есть ли буквы вообще, ссылка/почта/число — не
    язык), так что переход на неё ещё и дешевле.

    Ведомость пишется ровно тогда, когда обращение К МОДЕЛИ СОСТОЯЛОСЬ: ответ из кеша
    денег не стоил, и записи быть не должно. Общая дверь сообщает об этом сама.
    """
    def _bill() -> None:
        if user_id is None:
            return
        try:
            _billing_log_openai_usage(
                user_id=int(user_id),
                action_type="quick_correct",
                source_lang=lang or None,
                target_lang=None,
                usage=get_last_llm_usage(reset=True),
                seed=f"quick_correct_{origin}:{user_id}:{time.time_ns()}",
                metadata={"origin": origin, "text": text[:64]},
            )
        except Exception:
            logging.debug("quick_correct billing log failed", exc_info=True)

    from backend import dictionary_door
    return dictionary_door.proofread(text, lang=lang, on_usage=_bill)


def _proofread_dictionary_phrase(text: str, *, source_lang: str, user_id: int | None) -> str:
    """Server-side twin of the /api/translate/quick/correct route, called from the dictionary
    SAVE endpoints AND from the lookup routes so a typed phrase is proofread no matter WHICH
    surface it came from — see `_dictionary_hit_or_corrected_word` for the lookup side. The
    client-side proofread only covers the quick-dictionary overlay; wiring it here means every
    manual-entry surface (in-app dictionary, reader, YouTube, world-news, deep analysis, ask/
    answer overlays, …) is corrected too — the mechanism must be origin-independent.

    Returns the corrected form, or "" when nothing needs fixing / on ANY failure — the caller
    then keeps the user's exact text. Cached (incl. the "nothing to fix" result, and shared
    with the client route's cache, so the overlay's own call is not billed twice); best-effort
    billing. A save NEVER waits on or fails because of this call."""
    clean = str(text or "").strip()
    lang = _normalize_short_lang_code(source_lang, fallback="") or ""
    return _run_dictionary_door_proofread(
        clean, lang=lang, user_id=user_id, origin="dictionary_save")


# ── Кто написал текст, который человек сохраняет ─────────────────────────────────
# Решение владельца 20.08.2026, дословно: «я как пользователь вижу фразу и вижу его
# перевод, почему я должен думать, что сохранение будет какое-то другое?»
#
# Вычитка моделью придумана для одного случая: человек НАБРАЛ слово руками, и в нём
# может быть опечатка, чужой артикль, неверный падеж. Там она к месту.
#
# Но там, где текст показали МЫ САМИ — карточка «Новости дня», слово из читалки, оборот
# из субтитров, вариант из нашего разбора, — вычитывать нечего: мы правим собственный
# текст вслепую, без контекста, за время человека и у него на глазах. Если наш текст
# плох, он плох УЖЕ НА ЭКРАНЕ, и чинить это надо там, где он рождается.
#
# Цена была не теоретической: вычитка вызывалась ВНУТРИ сохранения и ждала ответа
# модели до 10 секунд (комментарий рядом уверял, что «сохранение никогда не ждёт» —
# это было неправдой). Замер 20.08.2026: 1875 таких обращений за 30 дней.
#
# Списки закрытые и по именам: угадывать по маске нельзя, незнакомое имя — это не
# «наверное набрал человек», а незакрытый случай, и он обязан быть в логе.
_TYPED_BY_USER_ORIGINS = {
    "webapp_dictionary_save",      # окно словаря: человек ввёл слово в поиск
    "webapp_quick_dictionary",     # быстрый словарь: то же, ввод руками
    "mobile_dictionary_save",      # мобильное приложение и Share Extension
    "bot_private_save",            # личный чат с ботом: слово прислал человек
}

_SHOWN_BY_US_ORIGINS = {
    "worldnews_phrase_save",             # карточка «Новость дня»
    # Свой вариант человек уже вписал ОСОЗНАННО и уже увидел, что о нём думает судья
    # (`/api/webapp/dictionary/check-variant`). Прогонять его ещё раз при сохранении
    # значило бы перерешать за человека то, что он только что решил сам.
    "worldnews_phrase_save_own",
    "reader",                            # тап по слову в книге/статье
    "youtube",                           # слово из субтитров
    "youtube_dict_widget",
    "sentence_gpt_seed",                 # наш собственный посев
    "artikel_sprint_save", "trainer_save", "adjektiv_trainer", "synonym_save",
    "webapp_quick_dictionary_related", "webapp_quick_dictionary_example",
    "webapp_related", "webapp_example",  # это наши подсказки, не ввод человека
    "webapp_deep_analysis_option", "webapp_deep_analysis_example",
    "webapp_deepdive_save", "translations_block", "ask_overlay",
    "vocabulary_add_from_pool", "import", "subscription",
}


def _save_source_was_typed_by_user(origin_process: str) -> bool:
    """Набрал ли текст человек — или показали его мы.

    Незнакомое имя источника считаем НАШИМ показом и текст не трогаем: молча
    подправить человеку то, что он видел на экране, хуже, чем не подправить. Но
    молчать об этом нельзя — имя уходит в лог, чтобы случай закрыли явно.
    """
    origin = str(origin_process or "").strip().lower()
    if origin in _TYPED_BY_USER_ORIGINS:
        return True
    if origin in _SHOWN_BY_US_ORIGINS:
        return False
    logging.warning("сохранение словаря: источник %r не отнесён ни к набранному "
                    "человеком, ни к показанному нами — вычитку не делаем", origin)
    return False


def _apply_dictionary_source_proofread(
    *, source_text, word_ru, word_de, translation_ru, translation_de, source_lang, user_id,
    origin_process,
):
    """Proofread the source phrase and propagate the fix to the columns that MIRROR the source
    side only (never the translation side, which is the other language). Returns the possibly-
    updated (source_text, word_ru, word_de, translation_ru, translation_de) tuple; a no-op when
    there is nothing to fix.

    Вычитка идёт ТОЛЬКО там, где текст набрал человек (см. `_save_source_was_typed_by_user`).
    Там, где показали мы, сохраняется ровно то, что человек видел на экране, — и сохраняется
    мгновенно, без обращения к модели."""
    if not _save_source_was_typed_by_user(origin_process):
        return source_text, word_ru, word_de, translation_ru, translation_de
    corrected = _proofread_dictionary_phrase(source_text, source_lang=source_lang, user_id=user_id)
    original = source_text
    if corrected and corrected != original:
        source_text = corrected
        if word_ru == original:
            word_ru = corrected
        if word_de == original:
            word_de = corrected
        if translation_ru == original:
            translation_ru = corrected
        if translation_de == original:
            translation_de = corrected
    return source_text, word_ru, word_de, translation_ru, translation_de


def _cached_card_is_about(payload, word: str, lookup_lang: str) -> bool:
    """Правда ли, что лежащая в кэше карточка — про ЭТО слово.

    Зачем. 11.08.2026 человек набрал «Blad» (настоящее прилагательное «blad» —
    толстый), вычитка приняла его за опечатку частого «Blatt», и разбор про лист
    лёг в общий кэш под ключом «blad». Саму вычитку мы починили, но отравленная
    запись продолжала раздаваться ВСЕМ, кто спросит это слово, ещё десять лет —
    столько живёт общий ключ. Кэш обязан уметь признавать себя неправым.

    Проверяем узко и только там, где ответ доказуем: спросили ОДНО немецкое слово,
    и оно есть в выверенном внешнем словаре — значит заголовок карточки должен быть
    им же. Всё остальное (фразы, словоформы, незнакомые слова) пропускаем: «wuchsen»
    законно ведёт на «wachsen», и объявить это подменой было бы хуже болезни."""
    item = payload.get("item") if isinstance(payload, dict) else None
    if not isinstance(item, dict):
        return True
    if str(lookup_lang or "").strip().lower() != "de":
        return True
    asked = str(word or "").strip()
    if not asked or not _dictionary_layer_knows(asked, source_lang="de", target_lang="ru"):
        return True
    got = _LEADING_GERMAN_ARTICLE_RE.sub("", str(item.get("word_de") or "").strip()).strip()
    if not got:
        return True
    return got.casefold() == _LEADING_GERMAN_ARTICLE_RE.sub("", asked).strip().casefold()


def _with_fresh_unit_content(payload: dict, word: str, lookup_lang: str) -> dict:
    """Отдать из кеша ответ, но с содержимым СВЕЖЕГО общего слова.

    ЗАЧЕМ. Кеш быстрого словаря живёт десять лет (DICTIONARY_PERSISTENT_CACHE_TTL_SEC =
    315 360 000 секунд): ответ, записанный в марте, отдаётся до сих пор. Замер
    26.08.2026: в кеше 2 882 записи, и у 2 121 из них слово чинили УЖЕ ПОСЛЕ того, как
    ответ туда лёг. То есть мы правим слово, оно верное в словаре и в тренировке, а
    человек ищет его в быстром словаре и получает мартовский снимок со старой ошибкой.

    Это последнее место, где жило старое: список словаря и обе ветки тренировки закрыты
    раньше. Правило склейки то же самое, что и там, — своё писать нельзя, разойдётся.

    ⚠ КЕШ ПРИ ЭТОМ ПРОДОЛЖАЕТ ЭКОНОМИТЬ. Мы не выбрасываем записи и не идём к модели:
    берём готовый ответ и подмешиваем в него то, что с тех пор появилось на слове.

    ⚠ И НЕ ЛОМАЕМ ОТВЕТ, ЕСЛИ СЛОВА В СЛОЕ НЕТ. Не нашли единицу — отдаём кеш как есть:
    лучше прежний ответ, чем пустой экран.
    """
    if not isinstance(payload, dict) or not isinstance(payload.get("item"), dict):
        return payload
    if str(lookup_lang or "").strip().lower() != "de" or not str(word or "").strip():
        return payload
    try:
        from backend import lex_units
        from backend.database import merge_unit_card_for_serve
        # ⚠ lookup отдаёт САМ РАЗБОР, а не обёртку с полем «card». Первая версия этой
        # функции искала `единица["card"]`, всегда получала None и молча возвращала кеш
        # как есть — склейка «работала», не делая ничего. Поймано проверкой на живых
        # словах «geschützt» и «kreieren» 26.08.2026.
        единица = lex_units.lookup(word, source_lang="de", target_lang="ru")
        if not isinstance(единица, dict) or not единица.get("__lex_has_card"):
            return payload
        разбор = {k: v for k, v in единица.items() if not k.startswith("__lex_")}
        if not разбор:
            return payload
        свежий = dict(payload)
        свежий["item"] = merge_unit_card_for_serve(dict(payload["item"]), разбор, None)
        return свежий
    except Exception:
        # Склейка — улучшение, а не условие ответа. Не вышло — отдаём кеш как есть,
        # но говорим об этом в лог: молча деградировать нельзя.
        logging.warning("кеш словаря: не удалось подмешать свежее слово для %r",
                        str(word)[:60], exc_info=True)
        return payload


def _get_cached_dictionary_lookup_with_tier(
    cache_key: str, *, expected_word: str = "", lookup_lang: str = "",
) -> tuple[dict | None, str]:
    def _usable(payload):
        if not isinstance(payload, dict) or not expected_word:
            return True
        if _cached_card_is_about(payload, expected_word, lookup_lang):
            return True
        # Отравленную запись не просто пропускаем — ВЫБРАСЫВАЕМ, иначе следующий
        # человек снова заплатит за неё разбором, который не покажут.
        logging.warning("кэш словаря отдал карточку про другое слово: спросили %r", expected_word[:60])
        try:
            _drop_cached_dictionary_lookup(cache_key)
        except Exception:
            logging.debug("не удалось выбросить отравленный кэш %s", cache_key, exc_info=True)
        return False

    cached = _get_cached_dictionary_lookup(cache_key)
    if cached and _usable(cached):
        return _with_fresh_unit_content(cached, expected_word, lookup_lang), "memory"
    if not DICTIONARY_PERSISTENT_CACHE_ENABLED:
        return None, "none"
    persistent = get_dictionary_lookup_cache(
        cache_key=cache_key,
        ttl_seconds=DICTIONARY_PERSISTENT_CACHE_TTL_SEC,
    )
    if isinstance(persistent, dict) and _usable(persistent):
        _set_cached_dictionary_lookup(cache_key, persistent)
        return _with_fresh_unit_content(persistent, expected_word, lookup_lang), "db"
    return None, "none"


def _set_cached_dictionary_lookup_all(
    *,
    cache_key: str,
    payload: dict,
    source_lang: str,
    target_lang: str,
    query_source_lang: str,
    query_target_lang: str,
    lookup_lang: str,
    normalized_word: str,
) -> None:
    # Тонкую карточку одиночного слова не публикуем в общий (shared) ключ: она осела бы
    # там на 10 лет и раздавалась всем вместо настоящего разбора.
    item = payload.get("item") if isinstance(payload, dict) else None
    if (
        "|shared|" in str(cache_key or "")
        and isinstance(item, dict)
        and _is_single_word_dictionary_entry(str(item.get("source_text") or normalized_word), source_lang)
        and _dictionary_payload_needs_enrichment(item)
    ):
        logging.debug("shared dictionary cache write skipped (thin card): %s", normalized_word)
        return
    _set_cached_dictionary_lookup(cache_key, payload)
    if not DICTIONARY_PERSISTENT_CACHE_ENABLED:
        return
    try:
        upsert_dictionary_lookup_cache(
            cache_key=cache_key,
            source_lang=source_lang,
            target_lang=target_lang,
            query_source_lang=query_source_lang,
            query_target_lang=query_target_lang,
            lookup_lang=lookup_lang,
            normalized_word=normalized_word,
            response_json=payload,
        )
    except Exception as exc:
        logging.debug("Failed to upsert persistent dictionary cache: %s", exc)


def _acquire_dictionary_lookup_inflight_slot(cache_key: str) -> tuple[bool, threading.Event | None]:
    if not DICTIONARY_COALESCE_ENABLED or not cache_key:
        return True, None
    with _DICTIONARY_LOOKUP_INFLIGHT_LOCK:
        existing = _DICTIONARY_LOOKUP_INFLIGHT.get(cache_key)
        if existing and isinstance(existing.get("event"), threading.Event):
            started_at = float(existing.get("started_at") or 0.0)
            if started_at > 0 and (time.time() - started_at) > DICTIONARY_COALESCE_STALE_SEC:
                _DICTIONARY_LOOKUP_INFLIGHT.pop(cache_key, None)
            else:
                return False, existing["event"]
        event = threading.Event()
        _DICTIONARY_LOOKUP_INFLIGHT[cache_key] = {"event": event, "started_at": time.time()}
        return True, event


def _release_dictionary_lookup_inflight_slot(cache_key: str, event: threading.Event | None) -> None:
    if not cache_key or event is None:
        return
    with _DICTIONARY_LOOKUP_INFLIGHT_LOCK:
        existing = _DICTIONARY_LOOKUP_INFLIGHT.get(cache_key)
        if existing and existing.get("event") is event:
            event.set()
            _DICTIONARY_LOOKUP_INFLIGHT.pop(cache_key, None)


def _prune_dictionary_enrichment_jobs_locked(now_ts: float | None = None) -> None:
    safe_now = float(now_ts or time.time())
    expired_lookup_ids = [
        lookup_id
        for lookup_id, job in _DICTIONARY_ENRICHMENT_JOBS.items()
        if safe_now >= float(job.get("expires_at") or 0.0)
    ]
    if not expired_lookup_ids:
        return
    expired_lookup_id_set = set(expired_lookup_ids)
    for lookup_id in expired_lookup_ids:
        _DICTIONARY_ENRICHMENT_JOBS.pop(lookup_id, None)
    expired_cache_keys = [
        cache_key
        for cache_key, lookup_id in _DICTIONARY_ENRICHMENT_CACHE_TO_LOOKUP_ID.items()
        if lookup_id in expired_lookup_id_set
    ]
    for cache_key in expired_cache_keys:
        _DICTIONARY_ENRICHMENT_CACHE_TO_LOOKUP_ID.pop(cache_key, None)


def _clone_dictionary_enrichment_job(job: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(job, dict):
        return None
    return copy.deepcopy(job)


def _get_dictionary_enrichment_job_by_lookup_id(lookup_id: str) -> dict[str, Any] | None:
    normalized_lookup_id = str(lookup_id or "").strip()
    if not normalized_lookup_id:
        return None
    shared_job = _get_shared_dictionary_enrichment_job_by_lookup_id(normalized_lookup_id)
    if isinstance(shared_job, dict):
        return _clone_dictionary_enrichment_job(shared_job)
    with _DICTIONARY_ENRICHMENT_LOCK:
        _prune_dictionary_enrichment_jobs_locked()
        return _clone_dictionary_enrichment_job(_DICTIONARY_ENRICHMENT_JOBS.get(normalized_lookup_id))


def _get_dictionary_enrichment_job_for_cache_keys(*cache_keys: str) -> dict[str, Any] | None:
    normalized_keys = [str(item or "").strip() for item in cache_keys if str(item or "").strip()]
    if not normalized_keys:
        return None
    shared_job = _get_shared_dictionary_enrichment_job_for_cache_keys(*normalized_keys)
    if isinstance(shared_job, dict):
        return _clone_dictionary_enrichment_job(shared_job)
    with _DICTIONARY_ENRICHMENT_LOCK:
        _prune_dictionary_enrichment_jobs_locked()
        for cache_key in normalized_keys:
            lookup_id = _DICTIONARY_ENRICHMENT_CACHE_TO_LOOKUP_ID.get(cache_key)
            if not lookup_id:
                continue
            job = _DICTIONARY_ENRICHMENT_JOBS.get(lookup_id)
            if isinstance(job, dict):
                return _clone_dictionary_enrichment_job(job)
    return None


def _dictionary_pool_langs_from_item(item: dict, direction: str, source_lang: str, target_lang: str) -> tuple[str, str]:
    """Пара языков САМОЙ карточки: направление запроса (de-ru / ru-de) важнее профиля —
    иначе немецкое слово легло бы в пул как русское."""
    parts = [p.strip().lower() for p in str(direction or "").split("-") if p.strip()]
    if len(parts) == 2:
        return parts[0], parts[1]
    payload_pair = item.get("language_pair") if isinstance(item, dict) else None
    if isinstance(payload_pair, dict):
        src = str(payload_pair.get("source_lang") or "").strip().lower()
        tgt = str(payload_pair.get("target_lang") or "").strip().lower()
        if src and tgt:
            return src, tgt
    return str(source_lang or "").strip().lower(), str(target_lang or "").strip().lower()


def _store_dictionary_item_in_pool(
    item: dict | None,
    *,
    direction: str = "",
    source_lang: str = "",
    target_lang: str = "",
) -> None:
    """Положить результат в ОБЩИЙ ПУЛ. Вызывается на КАЖДОМ пути, каким слово к нам
    попадает — не только при сохранении: обычный запрос перевода тоже пополняет пул,
    чтобы следующий пользователь получил слово от нас, а не из GPT."""
    if not isinstance(item, dict) or not item:
        return
    try:
        pool_source_lang, pool_target_lang = _dictionary_pool_langs_from_item(item, direction, source_lang, target_lang)
        source_text = str(item.get("source_text") or "").strip()
        target_text = str(item.get("target_text") or "").strip()
        if not source_text:
            source_text = str(item.get("word_de") if pool_source_lang == "de" else item.get("word_ru") or "").strip()
        if not target_text:
            target_text = str(
                item.get("translation_ru") if pool_target_lang == "ru" else item.get("translation_de") or ""
            ).strip()
        if not source_text or not target_text:
            return
        # Проставляем вид записи (слово/фраза/предложение) прямо при укладке в пул —
        # без него база не отвечает на вопрос «чего у нас накоплено».
        if isinstance(item, dict) and not str(item.get("entry_kind") or "").strip():
            try:
                item = {**item, "entry_kind": _detect_dictionary_entry_kind(
                    source_text=source_text,
                    target_text=target_text,
                    source_lang=pool_source_lang,
                    target_lang=pool_target_lang,
                    response_json=item,
                )}
            except Exception:
                pass
        upsert_dictionary_pool_entry(
            source_lang=pool_source_lang,
            target_lang=pool_target_lang,
            source_text=source_text,
            target_text=target_text,
            word_ru=str(item.get("word_ru") or "").strip() or None,
            translation_de=str(item.get("translation_de") or "").strip() or None,
            word_de=str(item.get("word_de") or "").strip() or None,
            translation_ru=str(item.get("translation_ru") or "").strip() or None,
            response_json=item,
        )
    except Exception as exc:
        logging.debug("dictionary pool upsert skipped: %s", exc)


def _store_quick_translate_in_pool(
    *, text: str, result: dict | None, source_lang: str | None, target_lang: str | None,
) -> None:
    """Положить результат быстрого перевода в общий пул.

    Осознанно кладём ТОНКУЮ запись (слово + перевод + артикль, без разбора): она делает
    слово находимым для всех, а полноту добирает обогащение, которое по правилу
    «побеждает более полная карточка» просто перезапишет её. Единственное, чего нельзя, —
    затереть тонким уже существующий разбор; за это отвечает тот же upsert.

    СТРАЖ (11.08.2026). ОДИНОЧНОЕ СЛОВО от машинного переводчика сюда больше не
    попадает. Пул общий: что в него легло, то завтра увидят все, кто спросит это
    слово. А машинный ответ на одиночное слово — это строка без грамматики, из
    которой мы же потом достраивали часть речи по заглавной букве. Так «Толстый»
    стал «die Dicke» и лёг в пул готовой правдой для всех.

    Что осталось: ФРАЗЫ и предложения. Там переводчик хорош по-настоящему, никакой
    грамматики мы про них не утверждаем, и именно на них пул экономит модель.

    Слова в пул по-прежнему попадают — но осознанно: когда человек нажал
    «В словарь» или когда карточку построил настоящий разбор. Пул записывает то,
    что кто-то сохранил, а не то, что переводчик угадал, пока человек печатал."""
    if not isinstance(result, dict):
        return
    translation = str(result.get("translation") or "").strip()
    source = str(text or "").strip()
    if result.get("machine") and source and " " not in source:
        _log_flow_observation(
            "quick_translate", "pool_write_refused",
            word=source[:64], reason="machine_single_word",
            provider=str(result.get("provider") or ""),
        )
        return
    resolved_source_lang = str(
        source_lang or result.get("detected_source_lang") or ""
    ).strip().lower()
    resolved_target_lang = str(target_lang or "").strip().lower()
    if not source or not translation or not resolved_source_lang or not resolved_target_lang:
        return
    if resolved_source_lang == resolved_target_lang:
        return
    try:
        payload = {
            "source_lang": resolved_source_lang,
            "target_lang": resolved_target_lang,
            "source_text": source,
            "target_text": translation,
            "language_pair": {
                "code": f"{resolved_source_lang}-{resolved_target_lang}",
                "source_lang": resolved_source_lang,
                "target_lang": resolved_target_lang,
            },
            "entry_kind": _detect_dictionary_entry_kind(
                source_text=source, target_text=translation,
                source_lang=resolved_source_lang, target_lang=resolved_target_lang,
            ),
        }
        article = str(result.get("article") or "").strip()
        if article:
            payload["article"] = article
        # Число и лемма едут в пул вместе с записью: без них следующий читатель снова
        # примет форму за слово и построит склонение от «Probleme», а не от «Problem».
        number = str(result.get("grammatical_number") or "").strip()
        if number:
            payload["grammatical_number"] = number
        lemma_de = str(result.get("lemma_de") or "").strip()
        if lemma_de:
            payload["lemma_de"] = lemma_de
        if resolved_source_lang == "de":
            payload["word_de"], payload["translation_de"] = source, source
        if resolved_target_lang == "ru":
            payload["word_ru"], payload["translation_ru"] = translation, translation
        if resolved_source_lang == "ru":
            payload["word_ru"], payload["translation_ru"] = source, source
        if resolved_target_lang == "de":
            payload["word_de"], payload["translation_de"] = translation, translation
        upsert_dictionary_pool_entry(
            source_lang=resolved_source_lang,
            target_lang=resolved_target_lang,
            source_text=source,
            target_text=translation,
            word_ru=payload.get("word_ru"),
            translation_de=payload.get("translation_de"),
            word_de=payload.get("word_de"),
            translation_ru=payload.get("translation_ru"),
            response_json=payload,
        )
    except Exception as exc:
        logging.debug("quick translate → pool skipped: %s", exc)


# Голое немецкое слово: только буквы и дефис, без пробелов, артиклей и цифр. Всё
# остальное (фразы, ссылки, числа) до словаря не доходит и в базу не ходит.
_SINGLE_GERMAN_WORD_RE = re.compile(r"[A-Za-zÄÖÜäöüß]{2,}(?:-[A-Za-zÄÖÜäöüß]{2,})*")



def _verified_entry_for_prompt(word: str, *, lookup_lang: str = "") -> dict | None:
    """Факты о слове из ВЫВЕРЕННОГО словаря — для подсказки модели, что править нечего.

    Отдаём лемму, часть речи и первый перевод: этого достаточно, чтобы модель поняла,
    о каком именно слове её спрашивают, и не подменила его похожим частотным.
    None — значит слова мы не знаем, и никаких утверждений о нём не делаем."""
    if str(lookup_lang or "").strip().lower() not in ("", "de"):
        return None
    if not _dictionary_layer_knows(word, source_lang="de", target_lang="ru"):
        return None
    try:
        from backend.dictionary_entries import entries_for_query
        found = entries_for_query(word, source_lang="de", target_lang="ru")
    except Exception:
        return None
    if not found:
        return None
    top = found[0]
    return {
        "lemma": top.get("display") or top.get("headword") or "",
        "pos": top.get("pos") or "",
        "gloss": top.get("translation") or "",
    }

def _dictionary_layer_knows(word: str, *, source_lang: str, target_lang: str) -> bool:
    """Знает ли НАШ словарь это написание как настоящее слово.

    Нужна там, где мы собираемся что-то «исправлять»: исправлять можно только то,
    чего мы не знаем. Спрашивает ВЫВЕРЕННЫЙ внешний словарь (FreeDict, 26 630
    статей) — бесплатно и без сети.

    Именно внешний, а не наш собственный слой: в наших единицах живут наши же
    прошлые ошибки («Neugeborenes» — слова такого нет) и двери для опечаток
    («Bestürtz» ведёт на «bestürzt»). Дай им право вето над корректором — и они
    объявят себя правильными навсегда.

    Вето даётся ТОЛЬКО голому одиночному слову. «das Neugeborenes» неверно именно
    АРТИКЛЕМ («das Neugeborene» или «ein Neugeborenes»), а само написание
    «Neugeborenes» словарь знает — сверять такую строку с однословным словарём
    значит выбросить то единственное, что в ней сломано. Согласование артикля с
    формой проверяет вычитка, и отбирать у неё эту работу нельзя.

    Молчание тут не приговор слову, а честное «не знаем»: тогда вычитка своё дело
    делает как раньше."""
    if str(source_lang or "").strip().lower() != "de":
        return False
    candidate = str(word or "").strip()
    if not candidate or not _SINGLE_GERMAN_WORD_RE.fullmatch(candidate):
        return False
    try:
        from backend.dictionary_entries import known_in_base_dictionary
        return known_in_base_dictionary(word, "de")
    except Exception:
        logging.debug("базовый словарь не ответил при проверке слова %r", word, exc_info=True)
        return False


def _dictionary_hit_or_corrected_word(
    *, word: str, source_lang: str, target_lang: str, user_id: int | None
) -> tuple[dict | None, str]:
    """Наш словарь → промах → ВЫЧИТКА слова → снова наш словарь. Возвращает найденную
    карточку (или None) и то написание, с которым идти дальше.

    Почему вычитка живёт именно здесь. Раньше она стояла только на СОХРАНЕНИИ, а платим
    мы за разбор раньше — на поиске. Поэтому за неверную форму мы честно платили GPT,
    строили ей карточку и заводили ей единицу, и только текст правили потом. Так в слое
    и появилось «das Neugeborenes» — слова, которого в немецком нет.

    Почему это не дорого. Вычитку зовём ТОЛЬКО после того, как наш собственный словарь
    ответить не смог, то есть ровно там, где мы всё равно собираемся платить за полный
    разбор. Слово, которое у нас уже есть, верное по определению — спрашивать не о чем,
    и на попадании в свой словарь не тратится ничего. А на промахе дешёвая вычитка
    вместо разбора нередко ЭКОНОМИТ: исправленное слово часто уже лежит у нас."""
    item = _load_dictionary_item_from_pool(word=word, source_lang=source_lang, target_lang=target_lang)
    if item:
        return item, word
    # ПУЛ — ЭТО НЕ ВЕСЬ НАШ СЛОВАРЬ. Правило выше («слово, которое у нас уже есть,
    # верное по определению») проверялось только по пулу, а словарных статей у нас
    # 26 630. Так «blad» (толстый, прилагательное) — настоящее немецкое слово,
    # которого просто не было в пуле, — уехало в корректор, тот «исправил» его на
    # частое «Blatt», и человек получил разбор совсем другого слова: заголовок
    # «толстый», а под ним лист, страница и die Seite (11.08.2026).
    if _dictionary_layer_knows(word, source_lang=source_lang, target_lang=target_lang):
        return None, word
    if not dictionary_intake.worth_language_check(word, source_lang):
        return None, word
    corrected = _proofread_dictionary_phrase(word, source_lang=source_lang, user_id=user_id)
    corrected = dictionary_intake.clean_text(corrected)
    if not corrected or corrected == word:
        return None, word
    logging.info("словарь: вход %r исправлен на %r перед разбором", word[:60], corrected[:60])
    item = _load_dictionary_item_from_pool(
        word=corrected, source_lang=source_lang, target_lang=target_lang
    )
    return item, corrected


def _load_reverse_pool_item(*, word: str, source_lang: str, target_lang: str) -> dict | None:
    """Обратное сопоставление: слово, известное нам как ЦЕЛЬ перевода в противоположном
    направлении. Карточка собирается разворотом (см. dictionary_pool_reverse) — она почти
    всегда НЕПОЛНАЯ, и это нормально: вызывающая сторона использует её как готовое ядро и
    экономит основной запрос к GPT, оставляя только дообогащение."""
    # Слой единиц делает то же самое честно (слово ↔ слово), поэтому при включённом слое
    # костыль отключается: именно он приклеил разбор «der Rüpel» к заголовку «der Flegel».
    if DICTIONARY_UNITS_LOOKUP_ENABLED:
        return _load_item_from_units_layer(word=word, source_lang=source_lang, target_lang=target_lang)
    if not DICTIONARY_POOL_REVERSE_ENABLED:
        return None
    try:
        row = get_pool_dictionary_entry_reverse(
            source_lang=source_lang, target_lang=target_lang, source_text=word,
        )
        if not isinstance(row, dict):
            return None
        return build_reverse_pool_item(
            row, want_source_lang=source_lang, want_target_lang=target_lang,
        )
    except Exception as exc:
        logging.debug("reverse pool lookup failed: %s", exc)
        return None


def _reverse_pool_item_to_core_raw(item: dict, *, detected: str = "source") -> dict:
    """Превратить развёрнутую карточку в `raw` того же вида, что отдаёт основной запрос к
    GPT, — чтобы дальше сработал ОБЫЧНЫЙ конвейер обогащения (job → кеш → пул) и ничего
    специального для фронта не понадобилось."""
    return {
        "detected_language": detected,
        "word_source": str(item.get("source_text") or "").strip(),
        "word_target": str(item.get("target_text") or "").strip(),
        "part_of_speech": item.get("part_of_speech"),
        "article": item.get("article"),
        "forms": item.get("forms") if isinstance(item.get("forms"), dict) else {},
        "usage_examples": item.get("usage_examples") if isinstance(item.get("usage_examples"), list) else [],
    }


def _dictionary_answer_scope(item: dict | None, default: str) -> str:
    """Метка «кто ответил» для телеметрии: слой единиц или старый банк.

    Без честной метки отчёт не отличает одно от другого — а решать, можно ли убирать
    старый путь, надо по числу, а не на ощупь."""
    if isinstance(item, dict) and item.get("__lex_unit_id"):
        return "lex_units" if item.get("__lex_has_card") else "lex_units_seed"
    return default


def _load_item_from_units_layer(*, word: str, source_lang: str, target_lang: str) -> dict | None:
    """Ответ из слоя ЕДИНИЦ: написание → указатель → слово → переводы.

    Заменяет собой и прямой поиск по общему банку, и «обратное сопоставление» по русской
    стороне: «враг» — такая же единица, как «der Feind», и связь между ними уже есть.
    Именно обратное сопоставление склеило когда-то разбор «der Rüpel» с заголовком
    «der Flegel» — в слое единиц такое невозможно, разбор лежит на своей единице."""
    if not DICTIONARY_UNITS_LOOKUP_ENABLED:
        return None
    try:
        return lex_units.lookup(word, source_lang=source_lang, target_lang=target_lang)
    except Exception as exc:
        logging.debug("units lookup failed for %r: %s", word, exc)
        return None


def _load_dictionary_item_from_pool(*, word: str, source_lang: str, target_lang: str) -> dict | None:
    """Первая инстанция любого запроса перевода: наш собственный пул. Отдаём карточку
    только если она ПОЛНАЯ — тонкую отдавать нельзя, иначе пользователь навсегда получит
    обрезанный разбор вместо настоящего."""
    # Слой единиц спрашиваем ПЕРВЫМ: он опознаёт слово, а не строку текста, поэтому
    # находит и то, что банк видит только в обратном направлении. Правило «отдаём лишь
    # полную карточку» действует и здесь.
    unit_item = _load_item_from_units_layer(word=word, source_lang=source_lang, target_lang=target_lang)
    if (
        isinstance(unit_item, dict)
        and unit_item.get("__lex_has_card")
        and not _dictionary_payload_needs_enrichment(unit_item)
    ):
        return unit_item
    try:
        candidates = get_pool_dictionary_candidates(
            source_lang=source_lang,
            target_lang=target_lang,
            source_text=word,
        )
    except Exception as exc:
        logging.debug("dictionary pool lookup failed: %s", exc)
        return None
    asked_article = (
        _normalize_german_article(_strip_german_leading_article(word)[0])
        if source_lang == "de" else ""
    )
    for entry in candidates:
        if not isinstance(entry, dict):
            continue
        payload = entry.get("response_json")
        if not isinstance(payload, dict) or not payload:
            continue
        if _dictionary_payload_needs_enrichment(payload):
            continue
        # Чужой род — чужое слово: «der Kiefer» (челюсть) и «die Kiefer» (сосна) дают
        # один заголовок. Если человек назвал артикль, запись с ДРУГИМ артиклем не наша.
        if asked_article:
            entry_article = _normalize_german_article(
                _strip_german_leading_article(str(entry.get("source_text") or ""))[0]
            )
            if entry_article and entry_article != asked_article:
                continue
        # У части старых записей сам перевод лежит только в колонках строки, а в карточке его
        # нет. Без этой подстановки пользователь получил бы «готовый» ответ без перевода.
        payload = dict(payload)
        if not str(payload.get("source_text") or "").strip():
            payload["source_text"] = str(entry.get("source_text") or "").strip()
        if not str(payload.get("target_text") or "").strip():
            payload["target_text"] = str(entry.get("target_text") or "").strip()
        if not str(payload.get("target_text") or "").strip():
            continue  # перевода нет нигде — отдавать нечего
        if target_lang == "ru" and not str(payload.get("translation_ru") or "").strip():
            payload["translation_ru"] = payload["target_text"]
        if source_lang == "de" and not str(payload.get("word_de") or "").strip():
            payload["word_de"] = payload["source_text"]
        return payload
    return None


def _create_dictionary_enrichment_job(
    *,
    lookup_id: str,
    user_id: int,
    cache_key: str,
    cache_key_shared: str,
    normalized_word: str,
    lookup_lang: str,
    source_lang: str,
    target_lang: str,
    query_source_lang: str,
    query_target_lang: str,
    word: str,
    direction: str,
    core_item: dict[str, Any],
    core_raw: dict[str, Any],
) -> dict[str, Any]:
    now_ts = time.time()
    job = {
        "lookup_id": str(lookup_id),
        "user_id": int(user_id),
        "cache_key": str(cache_key or "").strip(),
        "cache_key_shared": str(cache_key_shared or "").strip(),
        "normalized_word": str(normalized_word or "").strip(),
        "lookup_lang": str(lookup_lang or "").strip().lower(),
        "source_lang": str(source_lang or "").strip().lower(),
        "target_lang": str(target_lang or "").strip().lower(),
        "query_source_lang": str(query_source_lang or "").strip().lower(),
        "query_target_lang": str(query_target_lang or "").strip().lower(),
        "word": str(word or "").strip(),
        "direction": str(direction or "").strip().lower(),
        "status": "enriching",
        "core_item": copy.deepcopy(core_item if isinstance(core_item, dict) else {}),
        "core_raw": copy.deepcopy(core_raw if isinstance(core_raw, dict) else {}),
        "item": None,
        "error": "",
        "created_at": now_ts,
        "updated_at": now_ts,
        "expires_at": now_ts + _DICTIONARY_ENRICHMENT_JOB_TTL_SEC,
    }
    with _DICTIONARY_ENRICHMENT_LOCK:
        _prune_dictionary_enrichment_jobs_locked(now_ts)
        _DICTIONARY_ENRICHMENT_JOBS[str(lookup_id)] = job
        if job["cache_key"]:
            _DICTIONARY_ENRICHMENT_CACHE_TO_LOOKUP_ID[job["cache_key"]] = str(lookup_id)
        if job["cache_key_shared"]:
            _DICTIONARY_ENRICHMENT_CACHE_TO_LOOKUP_ID[job["cache_key_shared"]] = str(lookup_id)
        cloned = _clone_dictionary_enrichment_job(job) or {}
    logging.info(
        "Dictionary enrichment queued: lookup_id=%s user_id=%s word=%r direction=%s source_lang=%s target_lang=%s query_source_lang=%s query_target_lang=%s",
        str(lookup_id),
        int(user_id),
        str(word or ""),
        str(direction or "").strip().lower(),
        str(source_lang or "").strip().lower(),
        str(target_lang or "").strip().lower(),
        str(query_source_lang or "").strip().lower(),
        str(query_target_lang or "").strip().lower(),
    )
    _set_shared_dictionary_enrichment_job(cloned)
    return cloned


def _update_dictionary_enrichment_job(
    lookup_id: str,
    *,
    status: str | None = None,
    item: dict[str, Any] | None = None,
    direction: str | None = None,
    error: str | None = None,
) -> None:
    normalized_lookup_id = str(lookup_id or "").strip()
    if not normalized_lookup_id:
        return
    with _DICTIONARY_ENRICHMENT_LOCK:
        _prune_dictionary_enrichment_jobs_locked()
        job = _DICTIONARY_ENRICHMENT_JOBS.get(normalized_lookup_id)
        if not isinstance(job, dict):
            return
        if status:
            job["status"] = str(status).strip().lower()
        if isinstance(item, dict):
            job["item"] = copy.deepcopy(item)
        if direction is not None:
            job["direction"] = str(direction or "").strip().lower()
        if error is not None:
            job["error"] = str(error or "").strip()
        job["updated_at"] = time.time()
        job["expires_at"] = job["updated_at"] + _DICTIONARY_ENRICHMENT_JOB_TTL_SEC
        _set_shared_dictionary_enrichment_job(job)


def _resolve_dictionary_query_languages(
    *,
    word: str,
    source_lang: str,
    target_lang: str,
    lookup_lang: str,
) -> tuple[str, str]:
    query_source_lang = source_lang
    query_target_lang = target_lang
    if lookup_lang and lookup_lang == target_lang:
        query_source_lang = target_lang
        query_target_lang = source_lang
    elif lookup_lang and lookup_lang == source_lang:
        query_source_lang = source_lang
        query_target_lang = target_lang
    elif _is_legacy_ru_de_pair(source_lang, target_lang):
        is_ru = any("а" <= ch.lower() <= "я" or ch.lower() == "ё" for ch in str(word or ""))
        query_source_lang = "ru" if is_ru else "de"
        query_target_lang = "de" if is_ru else "ru"
    return query_source_lang, query_target_lang


def _resolve_dictionary_direction(
    *,
    detected: str,
    lookup_lang: str,
    query_source_lang: str,
    query_target_lang: str,
) -> str:
    if lookup_lang and lookup_lang in {query_source_lang, query_target_lang}:
        return f"{query_source_lang}-{query_target_lang}"
    return (
        f"{query_source_lang}-{query_target_lang}"
        if str(detected or "").strip().lower() != "target"
        else f"{query_target_lang}-{query_source_lang}"
    )


def _build_dictionary_result_from_raw(
    *,
    raw: dict[str, Any],
    query_word: str,
    source_lang: str,
    target_lang: str,
    query_source_lang: str,
    query_target_lang: str,
    lookup_lang: str,
) -> tuple[dict[str, Any], str, str, str, str]:
    result, detected, source_value, target_value = _build_multilang_dictionary_result(
        raw=raw if isinstance(raw, dict) else {},
        query_word=query_word,
        source_lang=query_source_lang,
        target_lang=query_target_lang,
    )
    direction = _resolve_dictionary_direction(
        detected=detected,
        lookup_lang=lookup_lang,
        query_source_lang=query_source_lang,
        query_target_lang=query_target_lang,
    )
    decorated = _decorate_dictionary_item(
        result if isinstance(result, dict) else {},
        source_lang=source_lang,
        target_lang=target_lang,
        direction=direction,
    )
    # The word-family fields (synonyms / antonyms / related / collocations) are the
    # FOREIGN words the learner studies — they must be in the learning language
    # (target_lang), never the native explanation language. The LLM sometimes slips and
    # returns native-language paraphrases (e.g. Russian «неприятный человек» for a German
    # phrase). Drop wrong-script entries so we never show native-language "synonyms".
    _sanitize_learning_language_fields(decorated, target_lang)
    # ── АРТИКЛЬ НЕ КЛЕИТСЯ К ФРАЗЕ — И НА ЖИВОМ ОТВЕТЕ ТОЖЕ ──────────────────────
    #
    # Это же правило стояло с утра 22.08.2026, но ТОЛЬКО на пути сохранения
    # (`_prepare_dictionary_response_json_for_save`), и не сработало там, где владелец
    # его и увидел. Он набрал «Aus Gag» в быстром словаре, ответ помечен «машинный
    # перевод — этого слова нет в словаре», то есть через сохранение НЕ проходил, — и
    # над двумя словами снова стояло «die», а фраза числилась существительным.
    # Проверять надо было путём экрана, а не вызовом функции.
    #
    # Здесь общий сборщик ответа: через него идут и живой поиск, и обогащение карточки.
    # Поэтому правило живёт тут, а на сохранении остаётся вторым рубежом — туда приходят
    # записи из импортов, которые сюда не заглядывают.
    decorated = _apply_german_headword_normalization(
        payload=decorated, source_lang=source_lang, target_lang=target_lang,
    )
    return decorated, direction, detected, source_value, target_value


_CYRILLIC_RE = re.compile(r"[А-Яа-яЁё]")
_LATIN_RE = re.compile(r"[A-Za-zÀ-ÿ]")
# Learning languages we can script-check. de/en/es/it/fr/nl/pt are Latin-script; ru is Cyrillic.
_LATIN_LEARNING_LANGS = {"de", "en", "es", "it", "fr", "nl", "pt"}


def _entry_wrong_script_for_learning_lang(text: str, learn_lang: str) -> bool:
    """True when a word-family entry is clearly in the wrong script for the learning
    language (so it is a native-language paraphrase leaking into a foreign-word list)."""
    t = str(text or "")
    if not t.strip():
        return True
    ll = str(learn_lang or "").strip().lower()
    if ll in _LATIN_LEARNING_LANGS:
        return bool(_CYRILLIC_RE.search(t))  # a German/etc. word must not be Cyrillic
    if ll == "ru":
        return bool(_LATIN_RE.search(t)) and not bool(_CYRILLIC_RE.search(t))
    return False


def _sanitize_learning_language_fields(item: dict, learn_lang: str) -> dict:
    """Strip synonyms / antonyms / collocations / related words that are in the wrong
    (native) language for the learning language. In-place; returns the item."""
    if not isinstance(item, dict):
        return item
    ll = str(learn_lang or "").strip().lower()
    if ll not in _LATIN_LEARNING_LANGS and ll != "ru":
        return item
    for key in ("synonyms", "antonyms", "common_collocations"):
        vals = item.get(key)
        if isinstance(vals, list):
            # Синоним приходит либо строкой (старый вид), либо {word, gloss} — с 08.08.2026
            # мы просим перевод рядом со словом. Проверяем ИМЕННО слово: перевод по
            # определению на языке объяснений, и проверять его этим стражем нельзя —
            # иначе он вычистит всё, что сам же и попросил.
            kept = []
            for v in vals:
                word = v.get("word") if isinstance(v, dict) else v
                if not isinstance(word, str) or not word.strip():
                    continue
                if _entry_wrong_script_for_learning_lang(word, ll):
                    continue
                kept.append(v)
            item[key] = kept
    rel = item.get("related_words")
    if isinstance(rel, list):
        item["related_words"] = [
            r for r in rel
            if isinstance(r, dict) and not _entry_wrong_script_for_learning_lang(r.get("word"), ll)
        ]
    return item


def _keep_core_headword(
    core_raw: dict[str, Any] | None,
    merged_raw: dict[str, Any] | None,
    *,
    query_source_lang: str,
    query_target_lang: str,
) -> dict[str, Any]:
    """Не дать дообогащению подменить РАЗБИРАЕМОЕ СЛОВО.

    Ядро карточки (находка в нашем словаре или основной ответ GPT) уже назвало немецкое
    слово. Дообогащение просят разобрать ИСХОДНЫЙ запрос — для «Грубиян» оно свободно
    отвечает другим синонимом, и склейка меняет заголовок, оставляя формы, транскрипцию и
    примеры от прежнего слова. Так карточка «der Flegel» получила формы «der Rüpel»
    (26.07). Здесь слово ядра остаётся за ядром, а вместе с ним и всё, что описывает
    именно его; расхождение пишем в лог, чтобы такие случаи было видно."""
    core = core_raw if isinstance(core_raw, dict) else {}
    merged = merged_raw if isinstance(merged_raw, dict) else {}
    german_key = "word_source" if str(query_source_lang or "").lower() == "de" else "word_target"
    core_word = str(core.get(german_key) or "").strip()
    merged_word = str(merged.get(german_key) or "").strip()
    if not core_word or not merged_word:
        return merged
    normalize = lambda value: re.sub(r"^(?:der|die|das)\s+", "", value.strip(), flags=re.I).casefold()
    if normalize(core_word) == normalize(merged_word):
        return merged
    logging.warning(
        "dictionary enrichment renamed the word (%r → %r) — keeping the core word and its facts",
        core_word, merged_word,
    )
    fixed = dict(merged)
    fixed[german_key] = core_word
    # Всё это описывает КОНКРЕТНОЕ немецкое слово: если слово осталось прежним, то и
    # факты о нём должны быть прежними, а не от синонима, который назвало дообогащение.
    for field in ("forms", "pronunciation", "article", "usage_examples",
                  "common_collocations", "government_patterns", "grammar_tables"):
        if field in core:
            fixed[field] = copy.deepcopy(core[field])
        else:
            fixed.pop(field, None)
    return fixed


def _merge_dictionary_raw_payloads(
    core_raw: dict[str, Any] | None,
    enrichment_raw: dict[str, Any] | None,
) -> dict[str, Any]:
    merged = copy.deepcopy(core_raw if isinstance(core_raw, dict) else {})
    enrich = enrichment_raw if isinstance(enrichment_raw, dict) else {}
    # A payload the model produced but we could not parse (openai_manager.parse_llm_json
    # gave up) carries SHAPE only — part_of_speech "other", empty meanings, raw_text.
    # Merging it wipes a core card that was already right («die Eltern» → no article, empty
    # screen, 24.07). Treat it as "no enrichment happened".
    if enrich.get("parse_failed"):
        logging.warning(
            "dictionary enrichment unparsable — keeping the core card as is (word=%r)",
            str(enrich.get("word_source") or enrich.get("word_de") or "").strip(),
        )
        return merged
    list_keys = {
        "translations",
        "usage_examples",
        "common_collocations",
        "government_patterns",
        "save_worthy_options",
        "synonyms",
        "antonyms",
        "related_words",
        "synonym_differences",
        "register_examples",
        "common_mistakes",
        "false_friends",
    }
    dict_keys = {
        "forms",
        "pronunciation",
        "meanings",
        "connotation",
    }
    for key, value in enrich.items():
        if key in list_keys:
            if isinstance(value, list) and value:
                merged[key] = copy.deepcopy(value)
            continue
        if key in dict_keys:
            if isinstance(value, dict) and value:
                base = merged.get(key) if isinstance(merged.get(key), dict) else {}
                next_value = copy.deepcopy(base)
                for nested_key, nested_value in value.items():
                    if nested_value in (None, "", [], {}):
                        continue
                    next_value[nested_key] = copy.deepcopy(nested_value)
                merged[key] = next_value
            continue
        if value in (None, "", [], {}):
            continue
        # "other" is the model's shrug: it must never demote a concrete part of speech the
        # core lookup already knew (base dict says noun → the article backstop below needs it).
        if (
            key == "part_of_speech"
            and str(value).strip().lower() in ("other", "unknown")
            and str(merged.get(key) or "").strip()
        ):
            continue
        merged[key] = copy.deepcopy(value)
    return merged


def _require_stripe_config(*, require_webhook_secret: bool = False) -> str | None:
    if stripe is None:
        return "Stripe SDK не установлен на этом deploy"
    if not STRIPE_SECRET_KEY:
        return "STRIPE_SECRET_KEY не задан"
    if require_webhook_secret and not STRIPE_WEBHOOK_SECRET:
        return "STRIPE_WEBHOOK_SECRET не задан"
    return None


def _build_billing_webapp_return_url(
    state: str,
    *,
    include_session_id: bool = False,
    session_id: str | None = None,
) -> str:
    base_url = f"{APP_BASE_URL}/webapp?mode=webapp&section=subscription&billing={state}"
    if session_id:
        return f"{base_url}&session_id={session_id}"
    if include_session_id:
        return f"{base_url}&session_id={{CHECKOUT_SESSION_ID}}"
    return base_url


def _build_billing_telegram_start_param(state: str) -> str:
    clean_state = str(state or "").strip().lower()
    if clean_state not in {"success", "cancel", "portal"}:
        clean_state = "subscription"
    return f"billing_{clean_state}"


def _build_billing_telegram_return_url(state: str, *, include_session_id: bool = False) -> str:
    base_url = f"{APP_BASE_URL}/billing/telegram-return?state={state}"
    if include_session_id:
        return f"{base_url}&session_id={{CHECKOUT_SESSION_ID}}"
    return base_url


def _safe_int(value) -> int | None:
    try:
        return int(str(value).strip())
    except Exception:
        return None


def _stripe_unix_ts_to_datetime(value) -> datetime | None:
    ts = _safe_int(value)
    if ts is None:
        return None
    try:
        return datetime.fromtimestamp(ts, tz=timezone.utc)
    except Exception:
        return None


def _map_stripe_subscription_status(status: str | None) -> str:
    status_value = str(status or "").strip().lower()
    if status_value == "active":
        return "active"
    if status_value == "trialing":
        return "trialing"
    if status_value in {"past_due", "unpaid", "incomplete", "incomplete_expired"}:
        return "past_due"
    if status_value == "canceled":
        return "canceled"
    return "inactive"


def _resolve_user_id_for_stripe_event(
    *,
    metadata_user_id,
    client_reference_id,
    stripe_customer_id,
    stripe_subscription_id,
) -> int | None:
    user_id = _safe_int(metadata_user_id) or _safe_int(client_reference_id)
    if user_id:
        return int(user_id)
    if stripe_customer_id:
        sub = get_user_subscription_by_customer_id(str(stripe_customer_id))
        if sub and sub.get("user_id") is not None:
            return int(sub["user_id"])
    if stripe_subscription_id:
        sub = get_user_subscription_by_stripe_subscription_id(str(stripe_subscription_id))
        if sub and sub.get("user_id") is not None:
            return int(sub["user_id"])
    return None


def _get_or_create_stripe_customer_id(user_id: int, username: str | None = None) -> str:
    subscription = get_or_create_user_subscription(user_id=int(user_id), now_ts=datetime.now(timezone.utc))
    existing_customer_id = str(subscription.get("stripe_customer_id") or "").strip()
    if existing_customer_id:
        try:
            customer = stripe.Customer.retrieve(existing_customer_id)
            if customer and not getattr(customer, "deleted", False):
                return existing_customer_id
        except Exception as exc:
            logging.warning("stripe customer retrieve failed for user_id=%s customer=%s: %s", user_id, existing_customer_id, exc)

    customer = stripe.Customer.create(
        metadata={"user_id": str(int(user_id))},
        name=str(username or "").strip() or None,
    )
    customer_id = str(getattr(customer, "id", "") or "")
    if not customer_id:
        raise RuntimeError("Stripe customer id is empty")
    bind_stripe_customer_to_user(int(user_id), customer_id)
    return customer_id


def _upsert_subscription_from_stripe_payload(
    *,
    user_id: int,
    plan_code: str | None,
    stripe_customer_id: str | None,
    stripe_subscription_id: str | None,
    stripe_status: str | None,
    current_period_end_ts,
    db_conn=None,
) -> dict:
    return set_subscription_from_stripe(
        user_id=int(user_id),
        plan_code=str(plan_code or "pro").strip().lower() or "pro",
        stripe_customer_id=stripe_customer_id,
        stripe_subscription_id=stripe_subscription_id,
        status=_map_stripe_subscription_status(stripe_status),
        current_period_end=_stripe_unix_ts_to_datetime(current_period_end_ts),
        db_conn=db_conn,
    )


def _resolve_billing_plan_checkout_config(plan_code: str | None) -> tuple[str, str]:
    plan_code_value = str(plan_code or "").strip().lower()
    if not plan_code_value:
        raise ValueError("Код тарифа не передан")

    plan = get_billing_plan(plan_code_value)
    if not plan:
        raise ValueError(f"Тариф '{plan_code_value}' не найден")
    if not bool(plan.get("is_active")):
        raise ValueError(f"Тариф '{plan_code_value}' неактивен")
    if not bool(plan.get("is_paid")):
        raise ValueError(f"Тариф '{plan_code_value}' не является платным")

    price_id = str(plan.get("stripe_price_id") or "").strip()
    if not price_id:
        # Legacy fallback for deployments where DB plan rows exist but Stripe ids are managed via env.
        price_id_map = {
            "support_coffee": STRIPE_PRICE_ID_SUPPORT_COFFEE,
            "support_cheesecake": STRIPE_PRICE_ID_SUPPORT_CHEESECAKE,
            "pro": STRIPE_PRICE_ID_PRO,
        }
        price_id = str(price_id_map.get(plan_code_value) or "").strip()
    if not price_id:
        raise ValueError(f"Stripe price id не задан для тарифа '{plan_code_value}'")
    return plan_code_value, price_id


def _stripe_object_value(payload_obj, field: str, default=None):
    if payload_obj is None:
        return default
    try:
        value = getattr(payload_obj, field)
        if value is not None:
            return value
    except Exception:
        pass
    if isinstance(payload_obj, dict):
        value = payload_obj.get(field)
        if value is not None:
            return value
    get_method = getattr(payload_obj, "get", None)
    if callable(get_method):
        try:
            value = get_method(field)
            if value is not None:
                return value
        except Exception:
            pass
    return default


def _extract_plan_code_from_stripe_payload(payload_obj, default: str = "pro") -> str:
    if payload_obj is None:
        return default
    metadata = _stripe_object_value(payload_obj, "metadata", {}) or {}
    value = str(
        _stripe_object_value(metadata, "plan_code", "")
        or _stripe_object_value(payload_obj, "plan_code", "")
        or ""
    ).strip().lower()
    if value:
        return value

    price_id_candidates: list[str] = []
    top_level_price = _stripe_object_value(payload_obj, "price")
    if top_level_price is not None:
        top_level_price_id = str(_stripe_object_value(top_level_price, "id", "") or "").strip()
        if top_level_price_id:
            price_id_candidates.append(top_level_price_id)
    top_level_plan = _stripe_object_value(payload_obj, "plan")
    if top_level_plan is not None:
        top_level_plan_id = str(_stripe_object_value(top_level_plan, "id", "") or "").strip()
        if top_level_plan_id:
            price_id_candidates.append(top_level_plan_id)
    items = _stripe_object_value(payload_obj, "items")
    item_entries = _stripe_object_value(items, "data", []) or []
    for item in item_entries:
        item_price = _stripe_object_value(item, "price")
        item_price_id = str(_stripe_object_value(item_price, "id", "") or "").strip()
        if item_price_id:
            price_id_candidates.append(item_price_id)
        item_plan = _stripe_object_value(item, "plan")
        item_plan_id = str(_stripe_object_value(item_plan, "id", "") or "").strip()
        if item_plan_id:
            price_id_candidates.append(item_plan_id)

    price_to_plan = {
        str(STRIPE_PRICE_ID_PRO or "").strip(): "pro",
        str(STRIPE_PRICE_ID_SUPPORT_COFFEE or "").strip(): "support_coffee",
        str(STRIPE_PRICE_ID_SUPPORT_CHEESECAKE or "").strip(): "support_cheesecake",
    }
    for price_id in price_id_candidates:
        mapped = price_to_plan.get(str(price_id or "").strip())
        if mapped:
            return mapped
    return default


def _stripe_subscription_rank(status: str | None) -> int:
    value = str(status or "").strip().lower()
    if value == "active":
        return 4
    if value == "trialing":
        return 3
    if value in {"past_due", "unpaid"}:
        return 2
    if value in {"incomplete", "incomplete_expired"}:
        return 1
    return 0


def _select_effective_stripe_subscription(
    subscriptions: list,
    *,
    preferred_subscription_id: str | None = None,
):
    candidates = [item for item in (subscriptions or []) if str(_stripe_subscription_value(item, "id", "") or "").strip()]
    if not candidates:
        return None

    preferred_id = str(preferred_subscription_id or "").strip()
    active_like = [
        item
        for item in candidates
        if str(_stripe_subscription_value(item, "status", "") or "").strip().lower()
        in {"active", "trialing", "past_due", "unpaid"}
    ]
    pool = active_like or candidates

    def _sort_key(item) -> tuple[int, int, int, int, int]:
        subscription_id = str(_stripe_subscription_value(item, "id", "") or "").strip()
        status_value = str(_stripe_subscription_value(item, "status", "") or "").strip().lower()
        cancel_at_period_end = bool(_stripe_subscription_value(item, "cancel_at_period_end", False))
        current_period_end_ts = _safe_int(_stripe_subscription_value(item, "current_period_end", 0)) or 0
        created_ts = _safe_int(_stripe_subscription_value(item, "created", 0)) or 0
        return (
            _stripe_subscription_rank(status_value),
            1 if not cancel_at_period_end else 0,
            1 if preferred_id and subscription_id == preferred_id else 0,
            current_period_end_ts,
            created_ts,
        )

    return max(pool, key=_sort_key)


def _get_live_billing_price_snapshot(stripe_price_id: str | None) -> dict:
    price_id_value = str(stripe_price_id or "").strip()
    if not price_id_value:
        return {
            "amount_minor": None,
            "amount_value": None,
            "currency": None,
            "recurring_interval": None,
            "recurring_interval_count": None,
            "price_source": "missing_price_id",
        }
    if stripe is None or not STRIPE_SECRET_KEY:
        return {
            "amount_minor": None,
            "amount_value": None,
            "currency": None,
            "recurring_interval": None,
            "recurring_interval_count": None,
            "price_source": "stripe_unavailable",
        }
    try:
        price_obj = stripe.Price.retrieve(price_id_value)
        amount_minor = getattr(price_obj, "unit_amount", None)
        if amount_minor is None and hasattr(price_obj, "get"):
            amount_minor = price_obj.get("unit_amount")
        currency_value = getattr(price_obj, "currency", None)
        if currency_value is None and hasattr(price_obj, "get"):
            currency_value = price_obj.get("currency")
        recurring = getattr(price_obj, "recurring", None)
        if recurring is None and hasattr(price_obj, "get"):
            recurring = price_obj.get("recurring")
        recurring_interval = None
        recurring_interval_count = None
        if recurring:
            if hasattr(recurring, "get"):
                recurring_interval = recurring.get("interval")
                recurring_interval_count = recurring.get("interval_count")
            else:
                recurring_interval = getattr(recurring, "interval", None)
                recurring_interval_count = getattr(recurring, "interval_count", None)
        amount_value = None
        if amount_minor is not None:
            try:
                amount_value = float(amount_minor) / 100.0
            except Exception:
                amount_value = None
        return {
            "amount_minor": int(amount_minor) if amount_minor is not None else None,
            "amount_value": amount_value,
            "currency": str(currency_value or "").upper() or None,
            "recurring_interval": str(recurring_interval or "").strip().lower() or None,
            "recurring_interval_count": int(recurring_interval_count or 0) or None,
            "price_source": "stripe_live",
        }
    except Exception as exc:
        logging.warning("stripe price retrieve failed price_id=%s: %s", price_id_value, exc)
        return {
            "amount_minor": None,
            "amount_value": None,
            "currency": None,
            "recurring_interval": None,
            "recurring_interval_count": None,
            "price_source": "stripe_error",
        }


def _stripe_subscription_value(subscription_obj, field: str, default=None):
    return _stripe_object_value(subscription_obj, field, default)


def _sync_user_subscription_from_live_stripe(
    *,
    user_id: int,
    subscription: dict | None = None,
    force: bool = False,
) -> dict:
    user_id_value = int(user_id)
    trace_enabled = has_request_context() and (request.path or "") in _AUTH_TRACE_PATHS
    trace_request_id = getattr(g, "request_id", None) if trace_enabled else None
    trace_started_perf = time.perf_counter()
    subscription_row = dict(subscription) if isinstance(subscription, dict) else (get_user_subscription(user_id_value) or {})
    if not subscription_row:
        if trace_enabled:
            _log_compact_trace(
                "auth_sync",
                stage="skip_no_subscription",
                request_id=trace_request_id,
                path=request.path,
                user_id=user_id_value,
                duration_ms=int((time.perf_counter() - trace_started_perf) * 1000),
            )
        return {}

    stripe_customer_id = str(subscription_row.get("stripe_customer_id") or "").strip() or None
    stripe_subscription_id = str(subscription_row.get("stripe_subscription_id") or "").strip() or None
    # Stripe retired → never re-activate Pro from live Stripe (would resurrect leftover
    # test-mode subs). Return the local row unchanged.
    if stripe is None or not STRIPE_SECRET_KEY or not STRIPE_BILLING_ENABLED or (not stripe_customer_id and not stripe_subscription_id):
        if trace_enabled:
            _log_compact_trace(
                "auth_sync",
                stage="skip_no_live_sync",
                request_id=trace_request_id,
                path=request.path,
                user_id=user_id_value,
                had_stripe_customer_id=bool(stripe_customer_id),
                had_stripe_subscription_id=bool(stripe_subscription_id),
                duration_ms=int((time.perf_counter() - trace_started_perf) * 1000),
            )
        return subscription_row

    local_status = str(subscription_row.get("status") or "").strip().lower()
    local_plan_code = str(subscription_row.get("plan_code") or "").strip().lower()
    if not force and local_status in {"active", "trialing"} and local_plan_code and local_plan_code != "free":
        if trace_enabled:
            _log_compact_trace(
                "auth_sync",
                stage="skip_active_paid",
                request_id=trace_request_id,
                path=request.path,
                user_id=user_id_value,
                plan_code=local_plan_code,
                status=local_status,
                duration_ms=int((time.perf_counter() - trace_started_perf) * 1000),
            )
        return subscription_row

    try:
        subscriptions = []
        stripe_call_duration_ms = 0
        if trace_enabled:
            _log_compact_trace(
                "auth_sync",
                stage="live_stripe_start",
                request_id=trace_request_id,
                path=request.path,
                user_id=user_id_value,
                by_customer=bool(stripe_customer_id),
                by_subscription=(not bool(stripe_customer_id)) and bool(stripe_subscription_id),
            )
        stripe_call_started_perf = time.perf_counter()
        if stripe_customer_id:
            listed = stripe.Subscription.list(customer=stripe_customer_id, status="all", limit=100)
            if hasattr(listed, "auto_paging_iter"):
                subscriptions = list(listed.auto_paging_iter())
            else:
                subscriptions = list(_stripe_object_value(listed, "data", []) or [])
        elif stripe_subscription_id:
            live_subscription = stripe.Subscription.retrieve(stripe_subscription_id)
            subscriptions = [live_subscription] if live_subscription else []
        stripe_call_duration_ms = int((time.perf_counter() - stripe_call_started_perf) * 1000)
        if trace_enabled:
            _log_compact_trace(
                "auth_sync",
                stage="live_stripe_done",
                request_id=trace_request_id,
                path=request.path,
                user_id=user_id_value,
                stripe_duration_ms=stripe_call_duration_ms,
                subscription_count=len(subscriptions),
            )

        selected = _select_effective_stripe_subscription(
            subscriptions,
            preferred_subscription_id=stripe_subscription_id,
        )
        if not selected and stripe_subscription_id:
            selected = stripe.Subscription.retrieve(stripe_subscription_id)
        if not selected:
            return subscription_row

        live_subscription_id = str(_stripe_subscription_value(selected, "id", "") or "").strip() or None
        live_customer_id = str(_stripe_subscription_value(selected, "customer", "") or "").strip() or stripe_customer_id
        live_status_raw = str(_stripe_subscription_value(selected, "status", "") or "").strip().lower()
        live_status = _map_stripe_subscription_status(live_status_raw)
        live_plan_code = _extract_plan_code_from_stripe_payload(
            selected,
            default=local_plan_code or "pro",
        )
        should_upsert = force or any((
            live_plan_code != local_plan_code,
            live_status != local_status,
            (live_subscription_id or "") != (stripe_subscription_id or ""),
            (live_customer_id or "") != (stripe_customer_id or ""),
        ))
        if not should_upsert:
            if trace_enabled:
                _log_compact_trace(
                    "auth_sync",
                    stage="done_no_change",
                    request_id=trace_request_id,
                    path=request.path,
                    user_id=user_id_value,
                    stripe_duration_ms=stripe_call_duration_ms,
                    plan_code=local_plan_code or live_plan_code,
                    status=local_status or live_status,
                    duration_ms=int((time.perf_counter() - trace_started_perf) * 1000),
                )
            return subscription_row

        updated = _upsert_subscription_from_stripe_payload(
            user_id=user_id_value,
            plan_code=live_plan_code,
            stripe_customer_id=live_customer_id,
            stripe_subscription_id=live_subscription_id,
            stripe_status=live_status_raw or live_status,
            current_period_end_ts=_stripe_subscription_value(selected, "current_period_end"),
        )
        _invalidate_billing_front_caches_for_user(user_id_value)
        if trace_enabled:
            _log_compact_trace(
                "auth_sync",
                stage="done",
                request_id=trace_request_id,
                path=request.path,
                user_id=user_id_value,
                stripe_duration_ms=stripe_call_duration_ms,
                plan_code=str(updated.get("plan_code") or live_plan_code or ""),
                status=str(updated.get("status") or live_status or ""),
                duration_ms=int((time.perf_counter() - trace_started_perf) * 1000),
            )
        return updated
    except Exception:
        if trace_enabled:
            _log_compact_trace(
                "auth_sync",
                stage="error",
                request_id=trace_request_id,
                path=request.path,
                user_id=user_id_value,
                duration_ms=int((time.perf_counter() - trace_started_perf) * 1000),
                exception=sys.exc_info()[0].__name__ if sys.exc_info()[0] else "Exception",
            )
        logging.warning(
            "Live Stripe subscription sync failed user_id=%s customer=%s subscription=%s",
            user_id_value,
            stripe_customer_id,
            stripe_subscription_id,
            exc_info=True,
        )
        return subscription_row


def _resolve_user_entitlement(
    *,
    user_id: int,
    now_ts_utc: datetime | None = None,
    tz: str = "Europe/Vienna",
    subscription: dict | None = None,
    refresh_from_stripe: bool = True,
    cursor=None,
) -> tuple[dict, dict]:
    if cursor is not None and not refresh_from_stripe and not isinstance(subscription, dict):
        entitlement = resolve_entitlement(
            user_id=int(user_id),
            now_ts_utc=now_ts_utc,
            tz=tz,
            cursor=cursor,
        )
        return entitlement, {}
    # Fast path (Phase 2.1): if the CACHED entitlement already says Pro, skip the uncached
    # subscription read + live Stripe sync and return it. This is behavior-preserving — the
    # live sync deliberately NEVER re-verifies an already-active-paid user (see its eligibility
    # gate), so for a Pro user the old path already did nothing but extra queries. Only
    # free/lapsed/unknown users fall through to the full refresh below (to catch a NEW sub).
    # Guarded on subscription/cursor None so row-consuming callers (billing status) are unaffected.
    if subscription is None and cursor is None:
        try:
            _cached_ent = resolve_entitlement(int(user_id))
        except Exception:
            _cached_ent = None
        if _cached_ent is not None and str(_cached_ent.get("effective_mode") or "free").strip().lower() != "free":
            return _cached_ent, {}
    subscription_row = dict(subscription) if isinstance(subscription, dict) else (get_user_subscription(int(user_id)) or {})
    if refresh_from_stripe:
        subscription_row = _sync_user_subscription_from_live_stripe(
            user_id=int(user_id),
            subscription=subscription_row or None,
        )
    entitlement = resolve_entitlement(
        user_id=int(user_id),
        now_ts_utc=now_ts_utc,
        tz=tz,
        subscription=subscription_row or None,
    )
    return entitlement, subscription_row


def _build_paid_feature_required_response(
    *,
    feature: str,
    feature_title: str,
    entitlement: dict | None = None,
) -> dict:
    entitlement_payload = dict(entitlement or {})
    return {
        "ok": False,
        "error": "paid_feature_required",
        "feature": str(feature or "").strip(),
        "feature_title": str(feature_title or "").strip() or str(feature or "").strip(),
        "effective_mode": str(entitlement_payload.get("effective_mode") or "free").strip().lower() or "free",
    }


def _paid_surface_gate_response(
    *,
    user_id: int,
    feature: str,
    feature_title: str,
) -> tuple[dict | None, int | None]:
    # Fast path via the Redis-cached entitlement (Phase 2.1): an already-Pro user passes the
    # gate instantly — 1 Redis GET, no Postgres read, no live Stripe sync. We only fall back
    # to the full live-refresh path when the CACHED answer looks FREE, so a user who JUST
    # subscribed (webhook maybe not arrived) is still caught before we deny them.
    try:
        cached = resolve_entitlement(int(user_id))  # bare call -> cached read path
        if str(cached.get("effective_mode") or "free").strip().lower() != "free":
            return None, None
    except Exception:
        pass
    entitlement, _subscription = _resolve_user_entitlement(
        user_id=int(user_id),
        now_ts_utc=datetime.now(timezone.utc),
        tz="Europe/Vienna",
    )
    effective_mode = str(entitlement.get("effective_mode") or "free").strip().lower() or "free"
    if effective_mode == "free":
        return _build_paid_feature_required_response(
            feature=feature,
            feature_title=feature_title,
            entitlement=entitlement,
        ), 402
    return None, None


def _analytics_paid_gate_response(user_id: int) -> tuple[dict | None, int | None]:
    return _paid_surface_gate_response(
        user_id=int(user_id),
        feature="analytics",
        feature_title="Аналитика",
    )


def _refresh_subscription_before_translation_start(user_id: int) -> None:
    user_id_value = int(user_id)
    # Already-Pro (cached)? The live Stripe sync's eligibility gate skips active-paid users,
    # so there's nothing to refresh — skip the uncached subscription read + sync entirely.
    try:
        if str(resolve_entitlement(user_id_value).get("effective_mode") or "free").strip().lower() != "free":
            return
    except Exception:
        pass
    trace_request_id = getattr(g, "request_id", None) if has_request_context() else None
    trace_path = request.path if has_request_context() else None
    started_perf = time.perf_counter()
    db_lookup_started_perf = time.perf_counter()
    subscription_before = get_user_subscription(user_id_value) or {}
    db_lookup_duration_ms = int((time.perf_counter() - db_lookup_started_perf) * 1000)
    stripe_customer_id = str(subscription_before.get("stripe_customer_id") or "").strip()
    stripe_subscription_id = str(subscription_before.get("stripe_subscription_id") or "").strip()
    local_status = str(subscription_before.get("status") or "").strip().lower()
    local_plan_code = str(subscription_before.get("plan_code") or "").strip().lower()
    live_sync_eligible = bool(
        stripe is not None
        and STRIPE_SECRET_KEY
        and (stripe_customer_id or stripe_subscription_id)
        and not (local_status in {"active", "trialing"} and local_plan_code and local_plan_code != "free")
    )
    _log_compact_trace(
        "auth_refresh",
        stage="enter",
        request_id=trace_request_id,
        path=trace_path,
        user_id=user_id_value,
        entered=True,
        db_lookup_duration_ms=db_lookup_duration_ms,
        had_stripe_customer_id=bool(stripe_customer_id),
        had_stripe_subscription_id=bool(stripe_subscription_id),
        called_sync=True,
        live_sync_eligible=live_sync_eligible,
    )
    try:
        sync_started_perf = time.perf_counter()
        subscription_after = _sync_user_subscription_from_live_stripe(
            user_id=user_id_value,
            subscription=subscription_before or None,
        )
        sync_duration_ms = int((time.perf_counter() - sync_started_perf) * 1000)
        entitlement_started_perf = time.perf_counter()
        entitlement = resolve_entitlement(
            user_id=user_id_value,
            now_ts_utc=datetime.now(timezone.utc),
            tz="Europe/Vienna",
            subscription=subscription_after or None,
        )
        entitlement_duration_ms = int((time.perf_counter() - entitlement_started_perf) * 1000)
        _log_compact_trace(
            "auth_refresh",
            stage="done",
            request_id=trace_request_id,
            path=trace_path,
            user_id=user_id_value,
            db_lookup_duration_ms=db_lookup_duration_ms,
            sync_duration_ms=sync_duration_ms,
            stripe_duration_ms=sync_duration_ms if live_sync_eligible else 0,
            entitlement_duration_ms=entitlement_duration_ms,
            plan_code=str((subscription_after or {}).get("plan_code") or ""),
            status=str((subscription_after or {}).get("status") or ""),
            effective_mode=str(entitlement.get("effective_mode") or ""),
            duration_ms=int((time.perf_counter() - started_perf) * 1000),
        )
    except Exception:
        _log_compact_trace(
            "auth_refresh",
            stage="error",
            request_id=trace_request_id,
            path=trace_path,
            user_id=user_id_value,
            db_lookup_duration_ms=db_lookup_duration_ms,
            duration_ms=int((time.perf_counter() - started_perf) * 1000),
            exception=sys.exc_info()[0].__name__ if sys.exc_info()[0] else "Exception",
        )
        raise


def _schedule_customer_active_subscriptions_for_period_end(
    *,
    stripe_customer_id: str,
) -> dict:
    customer_id = str(stripe_customer_id or "").strip()
    if not customer_id:
        return {
            "active_count": 0,
            "cancel_scheduled_count": 0,
            "already_scheduled_count": 0,
            "failed_count": 0,
            "latest_period_end_ts": 0,
            "cancel_scheduled_ids": [],
            "already_scheduled_ids": [],
            "failed_ids": [],
        }
    result = {
        "active_count": 0,
        "cancel_scheduled_count": 0,
        "already_scheduled_count": 0,
        "failed_count": 0,
        "latest_period_end_ts": 0,
        "cancel_scheduled_ids": [],
        "already_scheduled_ids": [],
        "failed_ids": [],
    }
    statuses_to_schedule = {"active", "trialing", "past_due", "unpaid"}
    listed = stripe.Subscription.list(
        customer=customer_id,
        status="all",
        limit=100,
    )
    if hasattr(listed, "auto_paging_iter"):
        subscriptions = list(listed.auto_paging_iter())
    else:
        subscriptions = list(_stripe_object_value(listed, "data", []) or [])

    for subscription in subscriptions:
        subscription_id = str(_stripe_subscription_value(subscription, "id", "") or "").strip()
        if not subscription_id:
            continue
        status_value = str(_stripe_subscription_value(subscription, "status", "") or "").strip().lower()
        if status_value not in statuses_to_schedule:
            continue
        result["active_count"] += 1
        current_period_end_ts = _safe_int(_stripe_subscription_value(subscription, "current_period_end", 0)) or 0
        if current_period_end_ts > int(result["latest_period_end_ts"]):
            result["latest_period_end_ts"] = int(current_period_end_ts)

        cancel_at_period_end = bool(_stripe_subscription_value(subscription, "cancel_at_period_end", False))
        if cancel_at_period_end:
            result["already_scheduled_ids"].append(subscription_id)
            continue
        try:
            stripe.Subscription.modify(
                subscription_id,
                cancel_at_period_end=True,
                proration_behavior="none",
            )
            result["cancel_scheduled_ids"].append(subscription_id)
        except Exception:
            result["failed_ids"].append(subscription_id)
            logging.warning(
                "Failed to schedule subscription cancel_at_period_end customer=%s sub_id=%s",
                customer_id,
                subscription_id,
                exc_info=True,
            )

    result["cancel_scheduled_count"] = len(result["cancel_scheduled_ids"])
    result["already_scheduled_count"] = len(result["already_scheduled_ids"])
    result["failed_count"] = len(result["failed_ids"])
    return result


def schedule_user_paid_subscription_cancel_at_period_end(user_id: int) -> dict[str, Any]:
    user_id_value = int(user_id)
    result: dict[str, Any] = {
        "user_id": user_id_value,
        "subscription_found": False,
        "local_status_before": None,
        "local_plan_before": None,
        "stripe_customer_id": None,
        "stripe_subscription_id": None,
        "active_candidate_ids": [],
        "scheduled_ids": [],
        "already_scheduled_ids": [],
        "failed_ids": [],
        "stripe_status": "noop",
        "latest_period_end_ts": 0,
        "effective_access_until": None,
    }
    subscription = get_user_subscription(user_id_value) or {}
    if not subscription:
        result["stripe_status"] = "no_local_subscription"
        return result

    result["subscription_found"] = True
    result["local_status_before"] = str(subscription.get("status") or "")
    result["local_plan_before"] = str(subscription.get("plan_code") or "")
    stripe_customer_id = str(subscription.get("stripe_customer_id") or "").strip() or None
    stripe_subscription_id = str(subscription.get("stripe_subscription_id") or "").strip() or None
    result["stripe_customer_id"] = stripe_customer_id
    result["stripe_subscription_id"] = stripe_subscription_id

    if stripe is None or not STRIPE_SECRET_KEY:
        result["stripe_status"] = "stripe_unavailable"
        return result

    if stripe_customer_id:
        try:
            schedule_result = _schedule_customer_active_subscriptions_for_period_end(
                stripe_customer_id=stripe_customer_id,
            )
            result["scheduled_ids"] = list(schedule_result.get("cancel_scheduled_ids") or [])
            result["already_scheduled_ids"] = list(schedule_result.get("already_scheduled_ids") or [])
            result["failed_ids"] = list(schedule_result.get("failed_ids") or [])
            result["latest_period_end_ts"] = int(schedule_result.get("latest_period_end_ts") or 0)
            result["active_candidate_ids"] = result["scheduled_ids"] + result["already_scheduled_ids"] + result["failed_ids"]
            if result["failed_ids"]:
                result["stripe_status"] = "partial_failure" if (result["scheduled_ids"] or result["already_scheduled_ids"]) else "schedule_failed"
            elif result["scheduled_ids"]:
                result["stripe_status"] = "scheduled_for_period_end"
            elif result["already_scheduled_ids"]:
                result["stripe_status"] = "already_scheduled_for_period_end"
            else:
                result["stripe_status"] = "no_active_subscription"
        except Exception:
            result["stripe_status"] = "list_failed"
            logging.warning("Failed to schedule cancel_at_period_end for user_id=%s customer=%s", user_id_value, stripe_customer_id, exc_info=True)
    elif stripe_subscription_id:
        result["active_candidate_ids"] = [stripe_subscription_id]
        try:
            subscription_obj = stripe.Subscription.retrieve(stripe_subscription_id)
            result["latest_period_end_ts"] = _safe_int(_stripe_subscription_value(subscription_obj, "current_period_end", 0)) or 0
            cancel_at_period_end = bool(_stripe_subscription_value(subscription_obj, "cancel_at_period_end", False))
            status_value = str(_stripe_subscription_value(subscription_obj, "status", "") or "").strip().lower()
            if status_value not in {"active", "trialing", "past_due", "unpaid"}:
                result["stripe_status"] = "no_active_subscription"
            elif cancel_at_period_end:
                result["already_scheduled_ids"] = [stripe_subscription_id]
                result["stripe_status"] = "already_scheduled_for_period_end"
            else:
                stripe.Subscription.modify(
                    stripe_subscription_id,
                    cancel_at_period_end=True,
                    proration_behavior="none",
                )
                result["scheduled_ids"] = [stripe_subscription_id]
                result["stripe_status"] = "scheduled_for_period_end"
        except Exception:
            result["failed_ids"] = [stripe_subscription_id]
            result["stripe_status"] = "schedule_failed"
            logging.warning("Failed to schedule cancel_at_period_end for user_id=%s sub_id=%s", user_id_value, stripe_subscription_id, exc_info=True)
    else:
        result["stripe_status"] = "no_active_subscription"

    latest_period_end_ts = int(result.get("latest_period_end_ts") or 0)
    if latest_period_end_ts > 0:
        try:
            result["effective_access_until"] = datetime.fromtimestamp(latest_period_end_ts, tz=timezone.utc).isoformat()
        except Exception:
            result["effective_access_until"] = None
    return result


def _normalize_customer_stripe_subscriptions(
    *,
    stripe_customer_id: str,
    dry_run: bool = True,
) -> dict:
    customer_id = str(stripe_customer_id or "").strip()
    result = {
        "stripe_customer_id": customer_id,
        "dry_run": bool(dry_run),
        "active_candidate_count": 0,
        "non_cancelled_count": 0,
        "already_cancelled_count": 0,
        "kept_subscription_id": None,
        "to_cancel_ids": [],
        "cancelled_ids": [],
        "failed_ids": [],
        "status": "noop",
    }
    if not customer_id:
        result["status"] = "missing_customer_id"
        return result

    statuses_to_consider = {"active", "trialing", "past_due", "unpaid"}
    listed = stripe.Subscription.list(customer=customer_id, status="all", limit=100)
    if hasattr(listed, "auto_paging_iter"):
        subscriptions = list(listed.auto_paging_iter())
    else:
        subscriptions = list(_stripe_object_value(listed, "data", []) or [])

    candidates: list[dict] = []
    for subscription in subscriptions:
        subscription_id = str(_stripe_subscription_value(subscription, "id", "") or "").strip()
        status_value = str(_stripe_subscription_value(subscription, "status", "") or "").strip().lower()
        if not subscription_id or status_value not in statuses_to_consider:
            continue
        created_ts = _safe_int(_stripe_subscription_value(subscription, "created", 0)) or 0
        period_end_ts = _safe_int(_stripe_subscription_value(subscription, "current_period_end", 0)) or 0
        cancel_at_period_end = bool(_stripe_subscription_value(subscription, "cancel_at_period_end", False))
        candidates.append(
            {
                "id": subscription_id,
                "status": status_value,
                "created_ts": int(created_ts),
                "period_end_ts": int(period_end_ts),
                "cancel_at_period_end": cancel_at_period_end,
            }
        )

    result["active_candidate_count"] = len(candidates)
    if not candidates:
        result["status"] = "no_active_candidates"
        return result

    non_cancelled = [item for item in candidates if not bool(item.get("cancel_at_period_end"))]
    already_cancelled = [item for item in candidates if bool(item.get("cancel_at_period_end"))]
    result["non_cancelled_count"] = len(non_cancelled)
    result["already_cancelled_count"] = len(already_cancelled)
    if len(non_cancelled) <= 1:
        result["status"] = "already_normalized"
        if non_cancelled:
            result["kept_subscription_id"] = str(non_cancelled[0].get("id") or "")
        return result

    keep_item = sorted(
        non_cancelled,
        key=lambda item: (
            int(item.get("created_ts") or 0),
            int(item.get("period_end_ts") or 0),
            str(item.get("id") or ""),
        ),
        reverse=True,
    )[0]
    keep_id = str(keep_item.get("id") or "")
    result["kept_subscription_id"] = keep_id
    to_cancel = [item for item in non_cancelled if str(item.get("id") or "") != keep_id]
    result["to_cancel_ids"] = [str(item.get("id") or "") for item in to_cancel if str(item.get("id") or "")]
    if not to_cancel:
        result["status"] = "already_normalized"
        return result

    if dry_run:
        result["status"] = "would_cancel_duplicates"
        return result

    for item in to_cancel:
        sub_id = str(item.get("id") or "").strip()
        if not sub_id:
            continue
        try:
            stripe.Subscription.modify(
                sub_id,
                cancel_at_period_end=True,
                proration_behavior="none",
            )
            result["cancelled_ids"].append(sub_id)
        except Exception:
            result["failed_ids"].append(sub_id)
            logging.warning(
                "Failed to normalize duplicate stripe subscription customer=%s sub_id=%s",
                customer_id,
                sub_id,
                exc_info=True,
            )
    result["status"] = "normalized" if result["cancelled_ids"] else ("partial_failed" if result["failed_ids"] else "noop")
    return result


def _build_language_pair_payload(source_lang: str, target_lang: str) -> dict:
    return {
        "source_lang": source_lang,
        "target_lang": target_lang,
        "code": f"{source_lang}-{target_lang}",
    }


def _parse_direction_pair(direction: str | None) -> tuple[str, str] | None:
    raw = str(direction or "").strip().lower()
    if "-" not in raw:
        return None
    src, tgt = [chunk.strip() for chunk in raw.split("-", 1)]
    src = _normalize_short_lang_code(src, fallback="")
    tgt = _normalize_short_lang_code(tgt, fallback="")
    if not src or not tgt or src == tgt:
        return None
    return src, tgt


def _resolve_dictionary_save_pair(
    profile_source_lang: str,
    profile_target_lang: str,
    payload_source_lang: str | None,
    payload_target_lang: str | None,
    payload_direction: str | None,
    response_json: dict | None = None,
) -> tuple[str, str]:
    profile_forward = (profile_source_lang, profile_target_lang)
    profile_reverse = (profile_target_lang, profile_source_lang)
    allowed_pairs = {profile_forward}
    if profile_reverse[0] and profile_reverse[1] and profile_reverse[0] != profile_reverse[1]:
        allowed_pairs.add(profile_reverse)

    payload_src = _normalize_short_lang_code(payload_source_lang, fallback="")
    payload_tgt = _normalize_short_lang_code(payload_target_lang, fallback="")
    if payload_src and payload_tgt and payload_src != payload_tgt:
        candidate = (payload_src, payload_tgt)
        if candidate in allowed_pairs:
            return candidate

    dir_pair = _parse_direction_pair(payload_direction)
    if dir_pair and dir_pair in allowed_pairs:
        return dir_pair

    if isinstance(response_json, dict):
        rj_src = _normalize_short_lang_code(response_json.get("source_lang"), fallback="")
        rj_tgt = _normalize_short_lang_code(response_json.get("target_lang"), fallback="")
        if rj_src and rj_tgt and rj_src != rj_tgt:
            candidate = (rj_src, rj_tgt)
            if candidate in allowed_pairs:
                return candidate
        rj_dir_pair = _parse_direction_pair(response_json.get("direction"))
        if rj_dir_pair and rj_dir_pair in allowed_pairs:
            return rj_dir_pair

    return profile_forward


def _is_missing_dictionary_schema_error(exc: Exception) -> bool:
    message = str(exc or "").strip().lower()
    if not message:
        return False
    return (
        "bt_3_dictionary_entries" in message
        or "canonical_entry_id" in message
        or exc.__class__.__name__ in {"UndefinedTable", "UndefinedColumn"}
    )


_BILINGUAL_RU_COMBO_RE = re.compile(r"^(?P<pre>[^—]*?)\s+—\s+(?P<post>.+)$", re.DOTALL)


def _strip_bilingual_ru_combo(value):
    """Guard against the reader bilingual selection saving 'German — Russian' into a
    Russian field (word_ru/translation_ru) — the front of the SRS card then shows both
    languages. Conservative: only strip the German prefix when the text before ' — ' is
    Latin/German (no Cyrillic) and the part after has Cyrillic; otherwise leave as-is."""
    s = value if isinstance(value, str) else (str(value) if value else "")
    if not s or " — " not in s:
        return value
    m = _BILINGUAL_RU_COMBO_RE.match(s.strip())
    if not m:
        return value
    pre, post = m.group("pre"), m.group("post").strip()
    has_cyr = lambda x: bool(re.search(r"[А-Яа-яЁё]", x))
    has_lat = lambda x: bool(re.search(r"[A-Za-zÄÖÜäöüß]", x))
    if pre and has_lat(pre) and not has_cyr(pre) and has_cyr(post):
        return post
    return value


def _fix_swapped_sides_before_save(kwargs: dict) -> dict:
    """Не дать сохранить карточку сторонами наоборот.

    В личных карточках нашлась запись, где немецкий текст лежал в русской графе, а
    русский — в немецкой. Последствие видно не сразу: в тренировке вслух читается
    русская фраза вместо немецкой, потому что «изучаемая сторона» определяется по графе.
    Защита от переворота стояла только в одном пути сохранения, а карточка пришла из
    бота — мимо неё. Здесь сходятся ВСЕ пути, поэтому проверяем тут.

    Меняем местами только при однозначном признаке: в немецкой графе кириллица, а в
    русской — латиница без кириллицы. Спорные случаи не трогаем."""
    if "de" not in {str(kwargs.get("source_lang") or "").lower(), str(kwargs.get("target_lang") or "").lower()}:
        return kwargs
    word_de = str(kwargs.get("word_de") or "")
    word_ru = str(kwargs.get("word_ru") or "")
    if not word_de or not word_ru:
        return kwargs
    cyrillic = re.compile(r"[А-Яа-яЁё]")
    latin = re.compile(r"[A-Za-zÄÖÜäöüß]")
    if cyrillic.search(word_de) and latin.search(word_ru) and not cyrillic.search(word_ru):
        logging.warning("dictionary save: стороны перепутаны, меняю местами (%r ↔ %r)",
                        word_de[:40], word_ru[:40])
        fixed = dict(kwargs)
        fixed["word_de"], fixed["word_ru"] = kwargs.get("word_ru"), kwargs.get("word_de")
        fixed["translation_de"], fixed["translation_ru"] = (
            kwargs.get("translation_ru"), kwargs.get("translation_de"))
        return fixed
    return kwargs


_LOWERCASE_HEADWORD_POS = {"verb", "adjective", "adverb"}


def _fix_headword_case_before_save(kwargs: dict) -> dict:
    """Немецкий глагол/прилагательное/наречие пишется со строчной буквы.

    Слово часто приезжает из начала предложения («Gelingen», «Schlank») и так и
    сохраняется с заглавной. Дальше по нему строится таблица спряжения — и человек
    видит «ich Gelinge / wir Gelingen». Правим один раз, на входе.

    Трогаем только одиночное слово с известной частью речи: в заголовке-предложении
    («Das Problem wurde behoben.») заглавная стоит по делу, а у существительного она
    обязательна."""
    word_de = str(kwargs.get("word_de") or "").strip()
    # Заглавная в таком слове — ошибка где угодно, не только в первой букве:
    # «eRGATTERN» осталось от прежней версии этой же правки.
    if not word_de or " " in word_de or word_de == word_de.lower():
        return kwargs
    response_json = kwargs.get("response_json")
    if not isinstance(response_json, dict):
        return kwargs
    pos = str(response_json.get("part_of_speech") or "").strip().lower()
    # Заглавная внутри слова — сломанное написание, но верить части речи тут можно
    # только у глагола: в базе такими оказались «zEITSCHRIFT» и «eROBERUNG» —
    # существительные с неверной пометкой, и опустить их значило бы испортить.
    if any(ch.isupper() for ch in word_de[1:]):
        if pos != "verb":
            return kwargs
    elif pos not in _LOWERCASE_HEADWORD_POS:
        return kwargs
    # Заглавные внутри слова — сломанное написание, опускаем целиком: «ERGATTERN» с
    # заменой одной буквы дало бы «eRGATTERN», то есть хуже, чем было.
    fixed_word = word_de.lower() if any(ch.isupper() for ch in word_de[1:]) \
        else word_de[:1].lower() + word_de[1:]
    fixed = dict(kwargs)
    fixed["word_de"] = fixed_word
    if str(response_json.get("word_de") or "").strip() == word_de:
        patched = dict(response_json)
        patched["word_de"] = fixed_word
        fixed["response_json"] = patched
    for key in ("source_text", "translation_de"):
        if str(kwargs.get(key) or "").strip() == word_de:
            fixed[key] = fixed_word
    return fixed


def _attach_saved_entry_to_lex_unit(entry_id, kwargs: dict) -> None:
    """Сразу привязать сохранённую карточку к её слову в слое.

    Делаем это на сохранении, а не разовыми проходами: иначе каждый новый день
    добавляет карточки без указателя и слой отстаёт от жизни. Строго не критично —
    сбой привязки не должен ломать само сохранение."""
    if not entry_id:
        return
    try:
        # Разбор передаём вместе с привязкой: слово, разобранное для одного человека,
        # обязано стать разобранным для всех, кто на него подписан. Понижения не будет —
        # тонкое сохранение не перебьёт собранный ночью полный разбор.
        lex_units.attach_entry_to_unit(
            int(entry_id),
            word_de=kwargs.get("word_de"),
            word_ru=kwargs.get("word_ru"),
            source_lang=kwargs.get("source_lang"),
            target_lang=kwargs.get("target_lang"),
            card=kwargs.get("response_json") if isinstance(kwargs.get("response_json"), dict) else None,
        )
    except Exception:
        logging.debug("attach saved entry to lex unit failed", exc_info=True)
    # Копию разбора новой карточке НЕ кладём: содержимое приезжает с общего слова при
    # показе (перепись читателей — docs/tasks/dictionary_readers_census.md). Раньше здесь
    # шёл перенос, потому что читатели умели читать только личную карточку.
    # Рубильник UNIT_CARD_NIGHT_SPREAD=1 возвращает прежнее поведение.
    if UNIT_CARD_NIGHT_SPREAD_ENABLED:
        try:
            fill_thin_cards_from_units(limit=1, entry_id=int(entry_id))
        except Exception:
            logging.debug("перенос готового разбора в новую карточку не удался", exc_info=True)


def _db_rule_that_refused(exc) -> str:
    """Имя правила базы, которое отказало. Пусто — отказ не от правила."""
    text = str(exc or "")
    if "violates check constraint" not in text and "нарушает ограничение-проверку" not in text:
        return ""
    for part in text.replace('"', " ").replace("«", " ").replace("»", " ").split():
        if part.startswith(("chk_wdq_", "chk_pool_")):
            return part
    return ""


def _repair_dictionary_kwargs_for_db_rule(kwargs: dict, rule: str) -> dict | None:
    """Починить сохранение, которое база отказалась принять. Возвращает исправленный
    набор полей или None, если починить нечем.

    Человеку до наших правил дела нет: он отправил фразу и ждёт, что она сохранится.
    Поэтому отказ базы — это не ошибка для показа, а сигнал нам: разобраться, что не
    так, и записать правильно. Сама фраза у нас есть, остальное — наша работа."""
    fixed = dict(kwargs)
    word_de = str(fixed.get("word_de") or "")
    word_ru = str(fixed.get("word_ru") or "")

    if rule in ("chk_wdq_german_side_is_latin", "chk_pool_pair_is_two_languages",
                "chk_wdq_pair_is_two_languages"):
        # Немецкая колонка без единой латинской буквы = стороны перепутаны местами.
        if dictionary_intake.has_cyrillic(word_de) and dictionary_intake.has_latin(word_ru):
            fixed["word_de"], fixed["word_ru"] = word_ru, word_de
            fixed["translation_de"], fixed["translation_ru"] = (
                fixed.get("translation_ru"), fixed.get("translation_de"),
            )
            fixed["source_lang"], fixed["target_lang"] = (
                fixed.get("target_lang"), fixed.get("source_lang"),
            )
            return fixed
    if rule == "chk_wdq_german_side_is_latin":
        # Латыни нет ни с одной стороны — немецкую колонку не выдумываем, оставляем
        # карточку на одной стороне: слово человека сохранится, а не пропадёт.
        if word_ru.strip():
            fixed["word_de"] = None
            fixed["translation_de"] = None
            return fixed
        return None
    if rule in ("chk_wdq_pair_is_two_languages", "chk_pool_pair_is_two_languages"):
        # Одинаковая пара языков — определяем по алфавиту того, что реально записано.
        if dictionary_intake.has_latin(word_de) and dictionary_intake.has_cyrillic(word_ru):
            fixed["source_lang"], fixed["target_lang"] = "de", "ru"
            return fixed
        fixed["source_lang"] = None
        fixed["target_lang"] = None
        return fixed
    if rule == "chk_wdq_response_is_object":
        fixed["response_json"] = {}
        return fixed
    if rule in ("chk_wdq_has_a_side", "chk_pool_texts_filled"):
        return None  # нечего сохранять: обе стороны пусты
    return None


def _kwargs_repaired_for_db_rule(kwargs: dict, exc) -> dict:
    """Одна попытка починки перед повтором сохранения. Не наше правило или чинить нечем —
    поднимаем исходную ошибку дальше: тихо терять слово человека нельзя."""
    rule = _db_rule_that_refused(exc)
    if not rule:
        raise exc
    repaired = _repair_dictionary_kwargs_for_db_rule(kwargs, rule)
    if repaired is None:
        logging.error("сохранение отклонено правилом %s и починить нечем: %s", rule, exc)
        raise exc
    logging.warning("сохранение отклонено правилом %s — починили и повторяем", rule)
    return repaired


def _save_dictionary_entry_with_schema_retry(**kwargs) -> None:
    kwargs = _fix_swapped_sides_before_save(kwargs)
    kwargs = _fix_headword_case_before_save(kwargs)
    try:
        entry_id = save_webapp_dictionary_query_returning_id(**kwargs)
        _attach_saved_entry_to_lex_unit(entry_id, kwargs)
        return entry_id
    except Exception as exc:
        if _is_missing_dictionary_schema_error(exc):
            logging.warning(
                "Dictionary save hit missing schema; running ensure_webapp_tables and retrying once: error=%s",
                exc,
            )
            ensure_webapp_tables()
        else:
            kwargs = _kwargs_repaired_for_db_rule(kwargs, exc)
    entry_id = save_webapp_dictionary_query_returning_id(**kwargs)
    _attach_saved_entry_to_lex_unit(entry_id, kwargs)
    return entry_id


def _save_dictionary_entry_with_inserted_schema_retry(**kwargs) -> tuple[int, bool]:
    kwargs = _fix_swapped_sides_before_save(kwargs)
    kwargs = _fix_headword_case_before_save(kwargs)
    try:
        result = save_webapp_dictionary_query_returning_id_with_inserted(**kwargs)
        _attach_saved_entry_to_lex_unit((result or (None,))[0], kwargs)
        return result
    except Exception as exc:
        if _is_missing_dictionary_schema_error(exc):
            logging.warning(
                "Dictionary save hit missing schema; running ensure_webapp_tables and retrying once: error=%s",
                exc,
            )
            ensure_webapp_tables()
        else:
            kwargs = _kwargs_repaired_for_db_rule(kwargs, exc)
    result = save_webapp_dictionary_query_returning_id_with_inserted(**kwargs)
    _attach_saved_entry_to_lex_unit((result or (None,))[0], kwargs)
    return result


def _flip_inverted_ru_de_dictionary_payload(
    *,
    source_lang: str,
    target_lang: str,
    source_text: str,
    target_text: str,
    word_ru: str,
    word_de: str,
    translation_de: str,
    translation_ru: str,
) -> tuple[str, str, str, str, str, str, str, str]:
    """Server-side guard: a ru→de save whose Russian side carries NO Cyrillic is in fact a
    German headword posted with an inverted language pair (the grammar-trainer word taps
    did exactly this). Left alone, the ru→de column alignment copies the German into
    translation_de/word_de and the entry renders German on both sides with no translation.
    Re-file such a payload as de→ru so the German can only ever land in the German columns.
    Returns the (possibly unchanged) tuple of pair + texts."""
    if source_lang != "ru" or target_lang != "de":
        return source_lang, target_lang, source_text, target_text, word_ru, word_de, translation_de, translation_ru
    ru_side = [source_text, word_ru, translation_ru]
    de_side = [target_text, word_de, translation_de]
    if any(_text_has_cyrillic(v) for v in ru_side):
        return source_lang, target_lang, source_text, target_text, word_ru, word_de, translation_de, translation_ru
    german = next((str(v or "").strip() for v in (word_de, target_text, translation_de, source_text) if str(v or "").strip()), "")
    if not german:
        return source_lang, target_lang, source_text, target_text, word_ru, word_de, translation_de, translation_ru
    logging.warning(
        "Dictionary save: inverted ru→de payload without Cyrillic, re-filed as de→ru: german=%r",
        german,
    )
    # No Russian anywhere (that is the bug) → leave the RU columns empty and let the
    # background enrichment fill the real translation instead of echoing the German.
    return "de", "ru", german, "", "", german, "", ""


# A "rephrase" arrow the reader/YouTube GPT-sheet can glue into a saved field:
# "original -> alternative" (both German) or "original -> translation" (German → Russian).
# Only the spaced ASCII form and the Unicode arrows count, so a normal word/phrase — which
# never contains " -> " — is left untouched.
_REPHRASE_ARROW_RE = re.compile(r"\s+->\s+|\s*[→⟶]\s*|\s+—>\s+")


def _strip_rephrase_arrow_combo(value: str | None, *, prefer_script: str = "") -> str:
    """Keep a single clean segment when a save glued 'original -> alternative' into one
    field (the reader/YouTube rephrase artifact — 130 rows cleaned 2026-07-22). Fires only
    when a rephrase arrow is present, so ordinary text is never changed. `prefer_script`
    picks the right half per field: 'de' → the first Latin (German) segment, 'ru' → the
    Cyrillic (Russian) segment; '' → the first segment (the original)."""
    text = str(value or "")
    if not _REPHRASE_ARROW_RE.search(text):
        return text.strip()
    segments = [s.strip() for s in _REPHRASE_ARROW_RE.split(text) if s.strip()]
    if not segments:
        return text.strip()
    script = str(prefer_script or "").strip().lower()
    if script == "ru":
        cyrillic = [s for s in segments if _CYRILLIC_RE.search(s)]
        return cyrillic[-1] if cyrillic else segments[0]
    if script == "de":
        latin = [s for s in segments if _LATIN_RE.search(s) and not _CYRILLIC_RE.search(s)]
        return latin[0] if latin else segments[0]
    return segments[0]


def _correct_inverted_dictionary_scripts(
    *,
    source_lang: str,
    target_lang: str,
    source_text: str,
    target_text: str,
    word_ru: str,
    word_de: str,
    translation_de: str,
    translation_ru: str,
) -> tuple[str, str, str, str, str, str, str, str]:
    """Symmetric companion to _flip_inverted_ru_de_dictionary_payload, covering the
    direction that guard leaves open: a RUSSIAN string sitting in the GERMAN headword
    slot on a de/ru save. Left alone, the deterministic grammar tables decorate it as
    German — "der Понос / des Поносс", the adjective "морщинистыйer / am морщинистыйsten".
    A real German word ALWAYS carries Latin letters (umlauts included), so
    "Cyrillic present and no Latin at all" is a strong, safe signal the slot is misfilled.

    Two shapes:
      • Full inversion (de-slot Cyrillic-only AND ru-slot Latin-only) — the German is
        simply sitting in the RU columns; swap them back.
      • Only Russian present (de-slot Cyrillic-only, no Latin German anywhere) — re-file
        as ru→de so the enrichment fetches the real German instead of echoing Russian.

    Runs AFTER the column-fill/_align step, when word_de/word_ru are populated."""
    sl = _normalize_short_lang_code(source_lang, fallback="")
    tl = _normalize_short_lang_code(target_lang, fallback="")
    unchanged = (source_lang, target_lang, source_text, target_text, word_ru, word_de, translation_de, translation_ru)
    if {sl, tl} != {"de", "ru"}:
        return unchanged

    def _cyrillic_only(value) -> bool:
        s = str(value or "")
        return bool(_CYRILLIC_RE.search(s)) and not bool(_LATIN_RE.search(s))

    def _latin_only(value) -> bool:
        s = str(value or "")
        return bool(_LATIN_RE.search(s)) and not bool(_CYRILLIC_RE.search(s))

    german_slot = str(word_de or "").strip()
    if not _cyrillic_only(german_slot):
        return unchanged  # German slot holds real (Latin) text — nothing to fix.

    # word_de is Russian. Rescue the real German from the RU columns if it is there.
    russian = german_slot
    if _latin_only(word_ru) or _latin_only(translation_ru):
        german = str(word_ru if _latin_only(word_ru) else translation_ru).strip()
        logging.warning(
            "Dictionary save: swapped inverted de/ru columns (German was in the RU slot): german=%r russian=%r",
            german, russian,
        )
        # Clean de→ru: German in the German columns, Russian in the Russian columns.
        return "de", "ru", german, russian, russian, german, german, russian

    # No German anywhere → treat it as a Russian word the user wants translated to German,
    # so enrichment fills the real German rather than the grammar tables decorating Russian.
    logging.warning(
        "Dictionary save: Russian in German slot with no German found; re-filed as ru→de: ru=%r",
        russian,
    )
    return "ru", "de", russian, "", russian, "", "", russian


def _align_dictionary_legacy_ru_de_columns(
    *,
    source_lang: str,
    target_lang: str,
    source_text: str,
    target_text: str,
    word_ru: str,
    word_de: str,
    translation_de: str,
    translation_ru: str,
) -> tuple[str, str, str, str, str, str]:
    src_text = str(source_text or "").strip()
    tgt_text = str(target_text or "").strip()
    ru_word = str(word_ru or "").strip()
    de_word = str(word_de or "").strip()
    de_translation = str(translation_de or "").strip()
    ru_translation = str(translation_ru or "").strip()

    if source_lang == "ru" and target_lang == "de":
        src = src_text or ru_word or ru_translation
        tgt = tgt_text or de_word or de_translation
        if src:
            ru_word = src
            ru_translation = src
            if not src_text:
                src_text = src
        if tgt:
            de_word = tgt
            de_translation = tgt
            if not tgt_text:
                tgt_text = tgt
    elif source_lang == "de" and target_lang == "ru":
        src = src_text or de_word or de_translation
        tgt = tgt_text or ru_word or ru_translation
        if src:
            de_word = src
            de_translation = src
            if not src_text:
                src_text = src
        if tgt:
            ru_word = tgt
            ru_translation = tgt
            if not tgt_text:
                tgt_text = tgt

    return src_text, tgt_text, ru_word, de_word, de_translation, ru_translation


_GERMAN_SINGLE_WORD_ARTICLES = {
    "der",
    "die",
    "das",
    "den",
    "dem",
    "des",
    "ein",
    "eine",
    "einen",
    "einem",
    "einer",
    "eines",
}

_GERMAN_DEFINITE_ARTICLES = {"der", "die", "das"}

_DICTIONARY_SAVE_ENRICHMENT_LOCK = threading.Lock()
_DICTIONARY_SAVE_ENRICHMENT_INFLIGHT: set[int] = set()


def _dictionary_entry_tokens(value: str | None) -> list[str]:
    return re.findall(r"[0-9A-Za-zÀ-ÿА-Яа-яЁёÄÖÜäöüß'-]+", str(value or "").strip(), flags=re.UNICODE)


def _german_sides_match(candidate: str | None, word_de: str | None) -> bool:
    """Одна и та же немецкая сторона, записанная с артиклем и без него?

    Нужно, чтобы найти, в каком поле карточки лежит немецкий заголовок: «der Marktpreis»
    в одном поле и «Marktpreis» в другом — это одно и то же, а «рыночная цена» — нет.
    Сравниваем по словам без ведущего артикля; ничего не додумываем и не угадываем.
    """
    left = _dictionary_entry_tokens(candidate)
    right = _dictionary_entry_tokens(word_de)
    if not left or not right:
        return False

    def _bare(tokens: list[str]) -> list[str]:
        if len(tokens) > 1 and tokens[0].casefold() in _GERMAN_SINGLE_WORD_ARTICLES:
            return [t.casefold() for t in tokens[1:]]
        return [t.casefold() for t in tokens]

    return _bare(left) == _bare(right)


def _looks_like_dictionary_sentence(value: str | None) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    tokens = _dictionary_entry_tokens(text)
    if len(tokens) >= 5:
        return True
    if len(tokens) >= 3 and re.search(r"[.!?]", text):
        return True
    return False


def _is_single_word_dictionary_entry(value: str | None, lang: str | None) -> bool:
    text = str(value or "").strip()
    if not text or _looks_like_dictionary_sentence(text):
        return False
    tokens = _dictionary_entry_tokens(text)
    if not tokens:
        return False
    normalized_lang = _normalize_short_lang_code(lang, fallback="")
    if normalized_lang == "de" and len(tokens) == 2 and tokens[0].casefold() in _GERMAN_SINGLE_WORD_ARTICLES:
        return True
    return len(tokens) == 1


def _detect_dictionary_entry_kind(
    *,
    source_text: str,
    target_text: str,
    source_lang: str,
    target_lang: str,
    response_json: dict | None = None,
) -> str:
    payload = response_json if isinstance(response_json, dict) else {}
    part_of_speech = str(payload.get("part_of_speech") or "").strip().lower()
    if part_of_speech == "phrase":
        return "phrase"
    probe_source = str(source_text or payload.get("source_text") or "").strip()
    probe_target = str(target_text or payload.get("target_text") or "").strip()

    # Судим по НЕМЕЦКОЙ стороне, а не по той, с которой пришёл запрос.
    #
    # До 14.08.2026 здесь проверялась исходная сторона: `_is_single_word_dictionary_entry(
    # probe_source, source_lang)`. Когда человек ищет от русского, исходная сторона —
    # русский перевод, а он почти всегда многословный. Поэтому одиночное немецкое слово
    # штатно объявлялось «фразой», и дальше срабатывали два разрушительных следствия:
    #   • артикль не приклеивался к заголовку — `_apply_german_headword_normalization`
    #     выходит на первой же проверке `entry_kind != "word"`, хотя род лежал рядом
    #     в том же payload («Прорыв водопроводной трубы» → `Rohrbruch` вместо
    #     `der Rohrbruch`);
    #   • стиралась разбивка по значениям (ниже по коду, `payload.pop("dictionary_senses")`).
    # Замер 13.08.2026: 2961 личная карточка помечена фразой/предложением при одиночном
    # немецком слове, у 2949 из них значения восстанавливаются без обращения к модели.
    #
    # Пороги при этом НИ ПРИ ЧЁМ — их проверяли отдельно: подъём с 5 до 10 слов убирает
    # лишь 5% ошибок. Дело было именно в стороне.
    source_code = _normalize_short_lang_code(source_lang, fallback="")
    target_code = _normalize_short_lang_code(target_lang, fallback="")
    if source_code == "de" and probe_source:
        german_probe, german_lang = probe_source, source_code
    elif target_code == "de" and probe_target:
        german_probe, german_lang = probe_target, target_code
    else:
        # Немецкой стороны нет вовсе (английские и итальянские пары) — работаем
        # по-старому, от исходной стороны.
        german_probe, german_lang = probe_source, source_code

    # Одиночное слово проверяем ПЕРВЫМ. Иначе длинное предложение на чужой стороне
    # снова перебивало бы вердикт: «Er ___ jeden Morgen früh zur Arbeit.» → losfahren.
    if _is_single_word_dictionary_entry(german_probe, german_lang):
        return "word"
    if _looks_like_dictionary_sentence(probe_source) or _looks_like_dictionary_sentence(probe_target):
        return "sentence"
    return "phrase"


def _build_dictionary_senses(response_json: dict | None, fallback_target: str) -> list[dict]:
    payload = response_json if isinstance(response_json, dict) else {}
    senses: list[dict] = []
    seen_keys: set[tuple[str, str]] = set()

    def _append(raw_entry: Any, *, default_label: str, is_primary: bool = False) -> None:
        if isinstance(raw_entry, str):
            value = str(raw_entry).strip()
            context = ""
            example_source = ""
            example_target = ""
        elif isinstance(raw_entry, dict):
            value = str(
                raw_entry.get("value")
                or raw_entry.get("translation")
                or raw_entry.get("target")
                or raw_entry.get("translation_target")
                or raw_entry.get("translation_de")
                or ""
            ).strip()
            context = str(
                raw_entry.get("context")
                or raw_entry.get("note")
                or raw_entry.get("explanation")
                or ""
            ).strip()
            example_source = str(raw_entry.get("example_source") or raw_entry.get("source") or "").strip()
            example_target = str(
                raw_entry.get("example_target")
                or raw_entry.get("target")
                or raw_entry.get("example_de")
                or ""
            ).strip()
        else:
            return
        if not value:
            return
        dedupe_key = (value.casefold(), context.casefold())
        if dedupe_key in seen_keys:
            return
        seen_keys.add(dedupe_key)
        senses.append(
            {
                "rank": 0,
                "label": "main" if is_primary else default_label,
                "value": value,
                "context": context,
                "example_source": example_source,
                "example_target": example_target,
            }
        )

    meanings = payload.get("meanings") if isinstance(payload.get("meanings"), dict) else {}
    primary = meanings.get("primary") if isinstance(meanings, dict) else None
    if isinstance(primary, dict):
        _append(primary, default_label="main", is_primary=True)

    for item in (meanings.get("secondary") if isinstance(meanings, dict) else []) or []:
        _append(item, default_label="secondary")

    for item in payload.get("translations") or []:
        _append(item, default_label="secondary", is_primary=bool(isinstance(item, dict) and item.get("is_primary")))

    if not senses:
        fallback_value = str(fallback_target or payload.get("target_text") or payload.get("translation_de") or payload.get("translation_ru") or "").strip()
        if fallback_value:
            _append({"value": fallback_value}, default_label="main", is_primary=True)

    ranked_senses: list[dict] = []
    for index, item in enumerate(senses, start=1):
        ranked_senses.append(
            {
                **item,
                "rank": index,
                "label": "main" if index == 1 else ("secondary" if item.get("label") != "main" else "main"),
            }
        )
    return ranked_senses[:5]


def _normalize_german_article(value: str | None) -> str:
    normalized = str(value or "").strip().casefold()
    if normalized in _GERMAN_DEFINITE_ARTICLES:
        return normalized
    return ""


def _strip_german_leading_article(text: str) -> tuple[str, str]:
    compact = re.sub(r"\s+", " ", str(text or "").strip())
    if not compact:
        return "", ""
    parts = compact.split(" ", 1)
    if len(parts) == 2 and parts[0].casefold() in _GERMAN_SINGLE_WORD_ARTICLES:
        return parts[0].casefold(), parts[1].strip()
    return "", compact


# Words that cannot be the head noun right after a definite article — if a leading
# "der/die/das" is followed by one of these (or by a lowercase word), the article was
# prepended to a clause by mistake, not attached to a noun. German nouns are
# capitalised, so a real noun head is a capitalised word NOT in this set.
_GERMAN_NON_NOUN_LEADERS = frozenset({
    "im", "am", "beim", "zum", "zur", "vom", "ins", "aufs", "ans", "durchs", "fürs", "ums",
    "der", "die", "das", "den", "dem", "des", "ein", "eine", "einen", "einem", "einer", "eines",
    "mein", "dein", "sein", "ihr", "unser", "euer", "kein", "keine", "keinen", "keinem",
    "dieser", "diese", "dieses", "diesen", "diesem", "jener", "jene", "jeder", "jede", "alle", "man",
    "ich", "du", "er", "sie", "es", "wir", "jemanden", "jemand", "niemand", "etwas", "nichts",
    "lass", "lasst", "sei", "seid", "hab", "habe", "geh", "komm", "mach", "nimm", "gib", "schau", "bitte",
})


def _strip_spurious_leading_article(text: str) -> str | None:
    """If `text` is a definite article wrongly prepended to a clause (the next word is
    lowercase or a known non-noun leader), return the text without it. Else None — so a
    real noun phrase ("der Bösewicht im Film", "Die Fälschung von Daten …") is preserved."""
    article, bare = _strip_german_leading_article(text)
    if not article or not bare:
        return None
    toks = bare.split()
    if len(toks) < 2:  # "der Flur" → a single noun, the article belongs
        return None
    head = toks[0]
    if head[:1].islower() or head.casefold() in _GERMAN_NON_NOUN_LEADERS:
        return bare
    return None


# Plurale tantum: nouns that exist ONLY in the plural, so de.wiktionary documents no
# genus for them and every genus-based backstop returns nothing (that is why «Eltern»
# reached the user's dictionary bare). Their definite article is always «die».
_GERMAN_PLURALE_TANTUM = {
    "eltern", "großeltern", "urgroßeltern", "schwiegereltern", "stiefeltern",
    "pflegeeltern", "adoptiveltern", "geschwister", "leute", "ferien",
    "kosten", "unkosten", "einkünfte", "spesen", "finanzen", "personalien",
}


def _german_plural_only_article(lemma: str, forms: dict | None = None) -> str:
    """«die» for a noun that only exists in the plural, else ''.

    Two signals: a curated Plurale-tantum list, and a surface that IS its own plural
    (forms.plural == the word) — in both cases the definite article is «die», and no
    genus lookup can supply it."""
    bare = _strip_german_leading_article(str(lemma or "").strip())[1] or str(lemma or "").strip()
    if not bare:
        return ""
    if bare.casefold() in _GERMAN_PLURALE_TANTUM:
        return "die"
    plural = ""
    if isinstance(forms, dict):
        plural = _strip_german_leading_article(str(forms.get("plural") or ""))[1]
    if plural and plural.casefold() == bare.casefold():
        return "die"
    return ""


def _authoritative_german_article(lemma: str) -> str:
    """de.wiktionary's DOCUMENTED genus for a single German noun, as der/die/das —
    returned ONLY when exactly one gender is documented (unambiguous). '' for
    unknown or two-gender words. Cached forever in bt_3_wiktionary_genus_cache
    (network only on the first miss), so it warms a fast path for repeat lemmas.

    Fail-open by contract: any error, timeout, ambiguity or miss → '' so the caller
    keeps the model's article. This can only CORRECT the article, never blank a
    working one — the existing enrichment scheme stays intact underneath."""
    lemma = str(lemma or "").strip()
    if not lemma or _CYRILLIC_RE.search(lemma):
        return ""
    try:
        from backend.article_wiktionary_ref import reference_articles
        verdict = reference_articles([lemma]).get(lemma) or {}
        arts = verdict.get("articles") or set()
        if len(arts) == 1:
            a = next(iter(arts))
            return a if a in {"der", "die", "das"} else ""
    except Exception:
        logging.debug("authoritative article lookup failed for %r", lemma, exc_info=True)
    return ""


def _normalize_saved_german_single_word(
    value: str | None,
    *,
    part_of_speech: str,
    article: str,
) -> str:
    compact = re.sub(r"\s+", " ", str(value or "").strip())
    if not compact or not _is_single_word_dictionary_entry(compact, "de"):
        return compact
    # Never decorate a Cyrillic (Russian) string as a German headword — that is what turned a
    # mis-slotted "Понос" into "der Понос". Leave it untouched so the caller's script guards /
    # the trustworthy German column take over instead of this cementing the bug.
    if _CYRILLIC_RE.search(compact):
        return compact
    _existing_article, bare = _strip_german_leading_article(compact)
    probe = bare or compact
    normalized_pos = str(part_of_speech or "").strip().lower()
    normalized_article = _normalize_german_article(article)
    # НИ ОДНО слово не отдаём лемматизатору spaCy. Маленькая модель de_core_news_sm
    # откусывает окончание: существительным — замер 29.07.2026 (Felge→Felg,
    # Gefriertruhe→Gefriertruh, Gepäckwagen→Gepäckwag, Wassertropfen→Wassertropfe),
    # глаголам — замер 04.08.2026 (beibringen→beibring, stolpern→stolper,
    # herausfinden→herausfind, zerquetschen→zerquetsch). Обрезки уезжали заголовками
    # карточек и в общий пул: 261 личная карточка у 11 человек и 39 строк пула.
    #
    # Тогда, 29.07, вывели только существительные, и это была половина решения: догадка
    # осталась на глаголах. Она здесь вообще не нужна — к этому месту слово приходит из
    # разбора, где словарная форма уже стоит («beibring» в теле карточки соседствует с
    # базовой формой «beibringen»), так что модель не приводила форму, а переписывала
    # готовый правильный ответ своей догадкой. Словарную форму даёт разбор и справочник
    # Wiktionary; молчат оба — оставляем написание человека. Догадка не имеет права
    # переписывать слово, ровно как и артикль.
    normalized_lemma = probe
    # zu-инфинитив → словарная форма: «klarzukommen» → «klarkommen».
    #
    # Это НЕ догадка лемматизатора, о которой сказано выше, и потому она здесь уместна:
    # «zu» между отделяемой приставкой и основой — чистая синтаксическая частица, она не
    # бывает частью словарной формы ни у одного немецкого глагола. Снятие обратимо и
    # проверяемо, в отличие от откусывания окончаний spaCy.
    #
    # Замер 14.08.2026: пять таких заголовков (klarzukommen, anzulehnen, auszulaugen,
    # aufzudecken, umzukrempeln), два из них заведены в тот же день — дверь открыта и
    # течёт. У всех пяти к неверному заголовку была пририсована выдуманная парадигма
    # («ich klarzukomme»), потому что таблицы строятся от заголовка.
    # Правило одно на весь проект, живёт в backend/german_grammar_tables.py.
    if _GRAMMAR_LOOKS_LIKE_ZU_INFINITIVE(normalized_lemma):
        stripped = _GRAMMAR_STRIP_ZU_INFINITIVE(normalized_lemma)
        if stripped:
            normalized_lemma = stripped
    if normalized_pos == "noun" and normalized_article:
        bare_noun = normalized_lemma[:1].upper() + normalized_lemma[1:] if normalized_lemma else normalized_lemma
        return f"{normalized_article} {bare_noun}".strip()
    if normalized_pos == "verb":
        return normalized_lemma.lower()
    return compact


def _apply_german_headword_normalization(
    *,
    payload: dict[str, Any],
    source_lang: str,
    target_lang: str,
) -> dict[str, Any]:
    normalized = dict(payload)
    # Guard against the LLM labelling a whole SENTENCE as a noun and prepending a spurious
    # definite article to it (e.g. RU "В коридоре свет горит" → entry_kind=sentence yet
    # pos=noun, word_de="der Im Flur brennt das Licht"). That entry_kind=sentence + pos=noun
    # pairing is self-contradictory and only happens on this misclassification — a real noun
    # phrase ("der Bösewicht im Film") is entry_kind=word, so it is left untouched. Strip the
    # bogus leading article and drop the noun label.
    # ── АРТИКЛЬ ПРИНАДЛЕЖИТ СЛОВУ, А НЕ ФРАЗЕ ────────────────────────────────────
    #
    # Владелец 22.08.2026 прислал «Ноющая, тянущая боль в боку» → над заголовком
    # «ziehender, dumpfer Schmerz in der Seite» отдельной строкой стоял артикль «der»,
    # а сама фраза помечена «существительное». Это несогласованно в обе стороны: при
    # артикле окончания прилагательных должны быть слабыми («der ziehende, dumpfe
    # Schmerz»), а без артикля — сильными, как и написано. Человек заучивает смесь.
    #
    # ОТКУДА БЕРЁТСЯ. Машинка авторитетного артикля ниже уже защищена — она работает
    # только на одном слове (`_is_single_word_dictionary_entry`). Но артикль приходит
    # ещё и ПОЛЕМ МОДЕЛИ: она разбирает существительное ВНУТРИ фразы («der Schmerz»)
    # и подписывает им всю фразу. На многословном этот артикль не снимал никто, потому
    # что функция выходит раньше — на проверке `entry_kind != 'word'`.
    #
    # Замер 22.08.2026: 518 разборов из 10 337 помечены существительным при многословном
    # заголовке; у 208 из них заголовок начинается со строчной, то есть артикль встаёт
    # перед прилагательным или предлогом и виден как ошибка сразу.
    #
    # Прежняя защита ловила только `entry_kind = sentence`; правило то же, но полное:
    # многословное — не существительное, у него нет ни рода, ни артикля.
    #
    # ┌─ НАЙДЕНО 28.08.2026. НЕМЕЦКАЯ СТОРОНА БЕРЁТСЯ ИЗ КАРТОЧКИ, А НЕ ИЗ НАСТРОЙКИ. ─┐
    # │ Правило выше верное, но опора под ним была слабая: немецкую сторону выбирали  │
    # │ по языковой паре пользователя. У пары «русский → немецкий» (то есть у         │
    # │ большинства) `target_lang='de'`, и «немецкой стороной» объявлялся target_text │
    # │ — а там лежит РУССКИЙ перевод. «рыночная цена» — два слова, значит правило    │
    # │ решало, что это фраза, стирало артикль и переписывало часть речи.             │
    # │                                                                              │
    # │ Замер 27.08.2026, одно слово «Marktpreis», ответ модели побуквенно один:      │
    # │     пара de→ru:  article='der'  part_of_speech='noun'                         │
    # │     пара ru→de:  article=''     part_of_speech='phrase'   ← дефект            │
    # │                                                                              │
    # │ ПОЧЕМУ НЕ ЗАМЕТИЛИ. Строчка выбора стороны написана под УЗКОЕ правило         │
    # │ (`entry_kind='sentence'`, коммит 90b1a377) и почти никогда не работала.       │
    # │ 22.08.2026 правило расширили на любой многословный заголовок (1732c41a), а    │
    # │ опору перенесли как есть. Плюс во ВСЕХ четырёх файлах тестов прописана пара   │
    # │ de→ru — то есть ровно тот случай, где ошибки нет.                             │
    # │                                                                              │
    # │ Накопилось мало (замер 27.08): 11 записей пула и одна карточка Vorauszahlung. │
    # │ Перемерить: пул, где word_de — одно слово с заглавной, pos='phrase', артикль  │
    # │ пуст.                                                                        │
    # └──────────────────────────────────────────────────────────────────────────────┘
    #
    # Судим по полю, которое немецкой стороной И ЯВЛЯЕТСЯ. Настройка пары остаётся
    # запасным вариантом — на случай, если немецкого поля в карточке нет вовсе.
    # ⚠ Та же переменная решает, КУДА записать исправленный текст. Ошибись здесь — и
    # немецкий заголовок уедет в поле русского перевода, поэтому поле для записи
    # ищется по содержимому, а не назначается.
    _gk = "source_text" if _normalize_short_lang_code(source_lang, fallback="") == "de" else (
        "target_text" if _normalize_short_lang_code(target_lang, fallback="") == "de" else "")
    _word_de = str(normalized.get("word_de") or "").strip()
    if _word_de:
        _gtext = _word_de
        _gk = ""
        for _candidate in ("source_text", "target_text"):
            if _german_sides_match(str(normalized.get(_candidate) or ""), _word_de):
                _gk = _candidate
                break
    else:
        _gtext = str((normalized.get(_gk) if _gk else "") or "").strip()
    if _gtext and not _is_single_word_dictionary_entry(_gtext, "de"):
        _fixed = _strip_spurious_leading_article(_gtext) or _gtext
        if _fixed != _gtext:
            if _gk:
                normalized[_gk] = _fixed
            if normalized.get("word_de"):
                normalized["word_de"] = _fixed
        if str(normalized.get("article") or "").strip():
            normalized["article"] = ""
        if str(normalized.get("part_of_speech") or "").strip().lower() == "noun":
            # «Существительное» у фразы — это и есть причина приклеенного артикля.
            # Чиним пометку, а не только её последствие.
            normalized["part_of_speech"] = "phrase"
        return normalized
    if str(normalized.get("entry_kind") or "").strip().lower() != "word":
        return normalized
    part_of_speech = str(normalized.get("part_of_speech") or "").strip().lower()
    article = str(normalized.get("article") or "").strip()
    # ┌─ ПРОВЕРЕНО 28.08.2026. НЕ ПОДНИМАТЬ ЭТО КАК НОВУЮ НАХОДКУ. ──────────────────┐
    # │ Здесь немецкая сторона по-прежнему выбирается ПО НАСТРОЙКЕ ПАРЫ — то есть    │
    # │ тем самым способом, который выше (блок про многословность) пришлось          │
    # │ заменить. У пары ru→de `german_side_key='target_text'`, а там русский текст. │
    # │ На бумаге дальше страшное: строка `normalized["word_de"] = normalized_german`│
    # │ записала бы русское слово в поле НЕМЕЦКОГО заголовка.                        │
    # │                                                                             │
    # │ НО ЭТОТ БЛОК СЮДА НЕ ДОХОДИТ, и вход заперт строкой выше: `entry_kind` на    │
    # │ этом этапе ещё не проставлен (замер живого разбора 27.08: entry_kind=None),  │
    # │ его ставит `_detect_dictionary_entry_kind` позже, при укладке в пул. Условие  │
    # │ `entry_kind != "word"` разворачивает нас раньше.                             │
    # │                                                                             │
    # │ Замер живой базы 28.08, разложено на классы:                                │
    # │   72 записи пула с кириллицей в word_de, из них                              │
    # │     58 — целые русские фразы и предложения (человек набрал по-русски,        │
    # │          немецкая сторона не собралась) — ДРУГОЙ класс, не отсюда;           │
    # │     14 — одно русское слово, но там ПЕРЕВЁРНУТЫ стороны целиком              │
    # │          («городок» ← «das Städtchen»), все от 02.04–12.07.2026 — тоже        │
    # │          другой класс, следы старого переезда.                                │
    # │   Записей вида «немецкое слово подменено своим русским переводом» — НЕТ.      │
    # │                                                                             │
    # │ ВЫВОД: дефекта нет, риск заперт условием `entry_kind`. Трогать не надо.       │
    # │ Но если кто-то начнёт проставлять entry_kind РАНЬШЕ этой функции — замок      │
    # │ откроется, и сюда придётся принести ту же правку, что и выше (судить по       │
    # │ word_de через `_german_sides_match`).                                         │
    # │ Перемерить: SELECT COUNT(*) FROM bt_3_dictionary_entries                      │
    # │             WHERE word_de ~ '^[А-Яа-яЁё-]+$';   (было 14, все старые)          │
    # └─────────────────────────────────────────────────────────────────────────────┘
    german_side_key = "source_text" if _normalize_short_lang_code(source_lang, fallback="") == "de" else (
        "target_text" if _normalize_short_lang_code(target_lang, fallback="") == "de" else ""
    )
    if not german_side_key:
        return normalized
    current_german = str(normalized.get(german_side_key) or normalized.get("word_de") or "").strip()
    if not _is_single_word_dictionary_entry(current_german, "de"):
        return normalized
    # Authoritative der/die/das backstop: for a single-word noun, prefer the genus
    # de.wiktionary documents over the model's article (the mini soft spot). Only
    # on an unambiguous single gender, and NEVER singularise a plural: skip a plural
    # surface, and only OVERRIDE a clean article when the entry is a confirmed
    # singular — else just fill a missing one. This mirrors the offline backfill's safety.
    #
    # «Это форма множественного» теперь спрашивается у справочника, а не у самой
    # модели: раньше признаком служило её же поле forms.plural, то есть показания
    # того, кто и ошибается. У формы множественного артикль может быть только «die»
    # («die Probleme»), поэтому подтверждённая форма его и получает, а лемма пишется
    # рядом отдельным полем — из неё потом строится склонение.
    # The part-of-speech gate also accepts an UNKNOWN pos on a capitalized single word: a
    # model shrug ("other") or a parse failure must not disable the article machinery — that
    # is exactly how «Eltern» was saved bare. If the genus lookup then confirms a noun, the
    # label is corrected too, so the headword renders as «die Eltern».
    _pos_unknown = part_of_speech in ("", "other", "unknown")
    _noun_surface = bool(current_german) and current_german[:1].isupper() and not _CYRILLIC_RE.search(current_german)
    if DICTIONARY_AUTHORITATIVE_ARTICLE_ENABLED and (part_of_speech == "noun" or (_pos_unknown and _noun_surface)):
        _bare = _strip_german_leading_article(current_german)[1] or current_german
        _forms = normalized.get("forms") if isinstance(normalized.get("forms"), dict) else {}
        _plural_bare = _strip_german_leading_article(str(_forms.get("plural") or ""))[1]
        from backend.german_surface import PL, SG, german_surface
        _verdict = german_surface(_bare)
        _confirmed_plural = _verdict["number"] == PL and _verdict["confidence"] == "high"
        _is_plural_surface = (
            _verdict["number"] == PL
            or (bool(_plural_bare) and _plural_bare.casefold() == _bare.casefold())
        )
        _singular_confirmed = (
            _verdict["number"] == SG
            or (bool(_plural_bare) and _plural_bare.casefold() != _bare.casefold())
        )
        _clean_existing = _normalize_german_article(article)
        _resolved = ""
        if _confirmed_plural:
            _resolved = "die"
            normalized["grammatical_number"] = PL
            if _verdict["lemma"] and _verdict["lemma"].casefold() != _bare.casefold():
                normalized["lemma_de"] = _verdict["lemma"]
        elif not _is_plural_surface:
            _auth = _authoritative_german_article(_bare)
            if _auth and _auth != _clean_existing and (not _clean_existing or _singular_confirmed):
                _resolved = _auth
        if not _resolved and not _clean_existing:
            # Plural-only nouns (die Eltern, die Ferien, die Kosten) have no documented
            # genus, so the lookup above can never fill them. Only fills, never overrides.
            _resolved = _german_plural_only_article(_bare, _forms)
        if _resolved:
            article = _resolved
            normalized["article"] = _resolved
            if _pos_unknown:
                part_of_speech = "noun"
                normalized["part_of_speech"] = "noun"
    normalized_german = _normalize_saved_german_single_word(
        current_german,
        part_of_speech=part_of_speech,
        article=article,
    )
    if not normalized_german:
        return normalized
    normalized[german_side_key] = normalized_german
    normalized["word_de"] = normalized_german
    if _normalize_short_lang_code(source_lang, fallback="") == "de":
        normalized["translation_de"] = normalized_german
    if _normalize_short_lang_code(target_lang, fallback="") == "de":
        normalized["translation_de"] = normalized_german
    return normalized


def _prepare_dictionary_response_json_for_save(
    *,
    response_json: dict | None,
    source_text: str,
    target_text: str,
    source_lang: str,
    target_lang: str,
    word_ru: str | None,
    word_de: str | None,
    translation_de: str | None,
    translation_ru: str | None,
) -> dict:
    payload = dict(response_json) if isinstance(response_json, dict) else {}
    # Bare saves from the games/news decks arrive with response_json={} (no source_text
    # inside), so this MUST be set here or _detect_dictionary_entry_kind below reads a
    # missing key and the whole save 500s ("Wort konnte nicht gespeichert werden").
    # Regression from eded6991, which dropped this line while adding the article sanitiser.
    payload["source_text"] = source_text or str(word_ru or word_de or "").strip()
    # Sanitise the article at the door: keep only a clean der/die/das, drop any prose
    # the model sometimes emits here ("der (Hinterwäldler)", "die (Plural)",
    # "der/die/das (зависит…)"). A blank is safe — the headword-normalisation gard and
    # the word_de token supply the right article; garbage never reaches storage again.
    if "article" in payload:
        payload["article"] = _normalize_german_article(payload.get("article"))
    payload["target_text"] = target_text or str(translation_de or translation_ru or word_de or "").strip()
    # Обе стороны карточки не могут быть ОДНИМ И ТЕМ ЖЕ текстом: учить по такой нечему.
    # Замер 14.08.2026: две карточки на 24 906, и одна из них лежала у человека в очереди
    # повторения — он открывал её и видел «Это того не стоит» и вопросом, и ответом.
    # Причина: в target_text попал текст исходной стороны, хотя правильный перевод всё это
    # время лежал в колонке word_de. Данные были целы, испорчено одно поле разбора.
    # Поэтому чиним не выдумкой, а подстановкой из колонки нужной стороны.
    if payload["target_text"] and _normalize_space(payload.get("source_text")).casefold() == \
            _normalize_space(payload["target_text"]).casefold():
        german_side = str(word_de or translation_de or "").strip()
        native_side = str(word_ru or translation_ru or "").strip()
        rescue = german_side if _normalize_short_lang_code(target_lang, fallback="") == "de" else native_side
        if rescue and _normalize_space(rescue).casefold() != _normalize_space(payload["source_text"]).casefold():
            payload["target_text"] = rescue
        else:
            # Спасать нечем — перевода нет нигде. Пусть карточка считается неполной и
            # уедет на дообогащение, а не ляжет в тренировку пустышкой.
            logging.warning(
                "dictionary save: обе стороны совпадают и перевод не найден (%r)",
                str(payload.get("source_text"))[:60],
            )
    payload["source_lang"] = source_lang
    payload["target_lang"] = target_lang
    payload["language_pair"] = _build_language_pair_payload(source_lang, target_lang)
    if word_ru:
        payload["word_ru"] = str(word_ru).strip()
    if word_de:
        payload["word_de"] = str(word_de).strip()
    if translation_de:
        payload["translation_de"] = str(translation_de).strip()
    if translation_ru:
        payload["translation_ru"] = str(translation_ru).strip()

    entry_kind = _detect_dictionary_entry_kind(
        source_text=payload["source_text"],
        target_text=payload["target_text"],
        source_lang=source_lang,
        target_lang=target_lang,
        response_json=payload,
    )
    payload["entry_kind"] = entry_kind
    if entry_kind == "word":
        senses = _build_dictionary_senses(payload, payload["target_text"])
        if senses:
            payload["dictionary_senses"] = senses
    # Раньше здесь стояло `payload.pop("dictionary_senses", None)` — у всего, что не
    # опознано словом, разбивка по значениям СТИРАЛАСЬ перед записью, молча и навсегда.
    #
    # Снято 14.08.2026 по трём независимым проверкам:
    #   • цена ошибки несимметрична. Там, где метка «фраза/предложение» верна, стирание
    #     отнимает 10-13 записей из ста — у настоящего предложения «значение» и так
    #     дословно равно переводу. Там, где метка неверна, отнимает 99,6 из ста;
    #   • неверной метка была часто: 2961 личная карточка помечена фразой или
    #     предложением при одиночном немецком слове (замер 13.08.2026);
    #   • экономии стирание не давало: очередь ночного обогащения с этим гейтом 20
    #     кандидатов, без него 22 — он связывал ровно две записи.
    # Причину (проверку по исходной стороне вместо немецкой) чинит сам детектор выше,
    # но угадайка на пути СОХРАНЕНИЯ не должна удалять ни при какой точности: ошибка
    # удаления необратима, ошибка пометки — нет. Значения остаются лежать; экран и так
    # решает по entry_kind, показывать их или нет, и это решение обратимо.

    payload = _apply_german_headword_normalization(
        payload=payload,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    # СТРАЖ НА ВХОДЕ: регистр немецкого заголовка. В немецком с заглавной пишутся
    # только существительные, а сохранение приносит «Abbuchen», «Akut», «Nahtlos» —
    # особенно когда слово попало в словарь из начала предложения. Замер 15.08.2026:
    # 357 карточек уже лежат так. На ПОКАЗЕ это правило стоит (compose_german_headword,
    # _build_item), но без заслона здесь каждое новое слово ложилось бы криво снова.
    # Работает только для ОДНОГО слова и только при явно неименной части речи: у фразы
    # заглавная законна, а пустая часть речи прячет имена собственные.
    _pos_for_case = str(payload.get("part_of_speech") or "").strip()
    for _key in ("word_de", "translation_de"):
        _value = str(payload.get(_key) or "").strip()
        if _value and " " not in _value:
            _fixed = german_headword_case(_value, _pos_for_case)
            if _fixed != _value:
                payload[_key] = _fixed

    # СТРАЖ НА ВХОДЕ, ОБЩИЙ ДЛЯ ЧЕТЫРЁХ ПРАВИЛ. Свалка с номерами разрезается, регистр
    # опускается, перевод внутри перевода отсеивается, повторы снимаются — всё это ДО
    # записи, а не только при показе.
    #
    # Владелец 16.08.2026: «мы исправляли словарь три дня — а в будущем что-нибудь
    # защитили?» До этого дня правила стояли только на показе: экран выглядел
    # правильно, а в базу продолжало ложиться прежнее. Правила показа при этом
    # остаются — накопленное всё ещё лежит, и убирать их рано.
    #
    # Замеры, из-за которых эти четыре правила появились (15.08.2026): повторов 11 848
    # из 33 954 значений; перевод внутри перевода у 1358 слов из 4627; свалок с
    # номерами на карточках 15; переводов с заглавной 1418.
    payload = normalize_card_meanings_for_storage(
        payload, german_pos=str(payload.get("part_of_speech") or ""),
    )
    return payload


def _resolve_dictionary_semantic_folder_for_save(user_id: int, response_json: dict | None) -> tuple[str, int | None]:
    payload = response_json if isinstance(response_json, dict) else {}
    language_pair = payload.get("language_pair") if isinstance(payload.get("language_pair"), dict) else {}
    source_entry = payload.get("source_entry") if isinstance(payload.get("source_entry"), dict) else {}
    target_entry = payload.get("target_entry") if isinstance(payload.get("target_entry"), dict) else {}
    origin_meta = payload.get("origin_meta") if isinstance(payload.get("origin_meta"), dict) else {}
    semantic_tag = normalize_dictionary_semantic_tag(
        payload.get("semantic_category")
        or payload.get("semantic_tag")
        or payload.get("category")
        or language_pair.get("semantic_category")
        or source_entry.get("semantic_category")
        or target_entry.get("semantic_category")
        or origin_meta.get("semantic_category")
        or origin_meta.get("semantic_tag")
    )
    if not semantic_tag:
        return "", None
    try:
        folder = get_or_create_dictionary_semantic_folder(int(user_id), semantic_tag)
        folder_id = int(folder.get("id") or 0) if isinstance(folder, dict) else 0
        return semantic_tag, folder_id if folder_id > 0 else None
    except Exception:
        logging.warning(
            "Dictionary semantic folder resolve failed: user_id=%s semantic_tag=%s",
            int(user_id),
            semantic_tag,
            exc_info=True,
        )
        return "", None


def _normalize_dictionary_enrich_payload(enrich: dict | None) -> dict:
    enrich_data = dict(enrich) if isinstance(enrich, dict) else {}
    prefixes = enrich_data.get("prefixes")
    if isinstance(prefixes, list):
        normalized_prefixes = []
        for item in prefixes:
            if not isinstance(item, dict):
                continue
            normalized = dict(item)
            if normalized.get("translation_target") and not normalized.get("translation_de"):
                normalized["translation_de"] = normalized.get("translation_target")
            if normalized.get("translation_source") and not normalized.get("translation_ru"):
                normalized["translation_ru"] = normalized.get("translation_source")
            if normalized.get("example_target") and not normalized.get("example_de"):
                normalized["example_de"] = normalized.get("example_target")
            normalized_prefixes.append(normalized)
        enrich_data["prefixes"] = normalized_prefixes
    return enrich_data


def _rich_enrich_card_fields(
    *,
    source_text: str,
    target_text: str,
    source_lang: str,
    target_lang: str,
    timeout_seconds: float | None = None,
) -> dict:
    """Produce a FULL, unified card for a German headword by running the SAME rich
    `dictionary_assistant_multilang` prompt the LIVE dictionary lookup uses.

    Previously the lazy on-open enrich and the nightly pool both used the THIN
    `enrich_word_multilang` prompt, which returns only forms + examples — no Rektion,
    collocations, meanings, etymology or memory tip. Cards filled that way could never
    reach the fullness of a live-looked-up card (that split was the "kreieren куцый /
    absprechen полный" mismatch). Routing every enrich path through this one prompt makes
    card fullness depend on the WORD, not on which path happened to fill it.

    The German word is always the query (source_lang=de) with explanations in the native
    language, so the card is German-oriented regardless of how the entry was stored.
    Returns the rich item dict, or {} on any failure (caller keeps the thin card)."""
    sl = str(source_lang or "").strip().lower()
    tl = str(target_lang or "").strip().lower()
    if sl == "de":
        german_word, native_lang = source_text, tl
    elif tl == "de":
        german_word, native_lang = target_text, sl
    else:
        german_word, native_lang = source_text, tl
    german_word = str(german_word or "").strip()
    native_lang = (native_lang or "ru").strip().lower() or "ru"
    if not german_word:
        return {}
    # ── СМЫСЛ, КОТОРЫЙ СОХРАНИЛ ЧЕЛОВЕК, ЕДЕТ К МОДЕЛИ ───────────────────────────
    #
    # Владелец 22.08.2026: карточка «die Hose anhaben» была сохранена со смыслом «Быть
    # главным» (идиома), а ночь обогатила её про БУКВАЛЬНОЕ ношение брюк — управление
    # «etwas anhaben — Er hat einen Anzug an», примеры «Welche Hose hast du heute an?»,
    # мнемоника про одежду. Идиомы в карточке не было ни строкой, при этом сверху
    # по-прежнему стояло «Быть главным»: подпись и содержимое про разное.
    #
    # ПРИЧИНА БЫЛА ЗДЕСЬ, В ДВУХ СТРОКАХ ВЫШЕ. Перевод человека честно доезжал сюда
    # аргументом `target_text`, но использовался ТОЛЬКО чтобы понять, какая сторона
    # немецкая. Если немецкий слева — русский не уходил к модели вообще, и она разбирала
    # основное значение, потому что другого не видела.
    #
    # Теперь он идёт отдельным полем. Промпт решает, что с ним делать: сохранённый смысл
    # становится главным значением карточки, а основное уходит вторым — решение владельца
    # 22.08.2026 («ставь первым его оттенок, основное строкой ниже»). Слепо промпт ему не
    # верит: если смысл к выражению не подходит вовсе, он строит обычную карточку и
    # говорит об этом полем `saved_meaning_fits`.
    saved_meaning = ""
    _native_side = target_text if sl == "de" else source_text
    if str(_native_side or "").strip() and str(_native_side or "").strip() != german_word:
        saved_meaning = str(_native_side).strip()
    try:
        raw = asyncio.run(
            run_dictionary_lookup_multilang(
                word=german_word,
                source_lang="de",
                target_lang=native_lang,
                explanation_lang=native_lang,
                extra_payload=(
                    {"saved_meaning": {"text": saved_meaning, "language": native_lang}}
                    if saved_meaning else None),
                # Промпт и модель — те же, что у живого разбора (system_instruction_key не
                # трогаем), меняется ТОЛЬКО имя задачи. Иначе в ведомости фоновый досбор и
                # запрос живого человека пишутся одной строкой и различить их нечем: за
                # месяц пришлось разводить их по часу суток и по совпадению с сохранениями.
                # Имя стоит в _SYSTEM_ATTRIBUTION_TASKS, так что эта работа — всегда наша.
                task_name="dictionary_card_enrichment",
                # В фоне никто не ждёт ответа, поэтому жёсткий «живой» таймаут здесь
                # только вредит: ночью 85 слов из 200 срывались на 14 секундах.
                responses_timeout_seconds=timeout_seconds,
            )
        )
    except Exception as exc:
        logging.warning("rich enrich lookup failed word=%r: %s", german_word, exc)
        return {}
    if not isinstance(raw, dict) or not raw:
        return {}
    # ⚠ СМЫСЛ МЕНЯЕТСЯ, ЯЗЫК ПОЛЕЙ — НЕТ, и на модель тут полагаться нельзя.
    #
    # Как только рядом со словом появляется русский смысл, модель начинает путать
    # стороны: на «die Hose anhaben» со смыслом «Быть главным» она положила в немецкое
    # поле примера русское предложение «В этой семье традиционно папа всегда носит
    # штаны.» Прямая просьба в задании («example_source в языке слова») это не
    # вылечила — проверено дважды 22.08.2026.
    #
    # Поэтому стороны примеров выправляются кодом, тем же правилом, что чинит уже
    # лежащие разборы: если слева чужой язык, а справа нужный — половины меняются
    # местами. Не выбрасываем: пример хороший, он просто повёрнут.
    from backend.lex_units import orient_examples_to_unit_language
    raw = orient_examples_to_unit_language(raw, "de")
    try:
        item, _direction, _detected, _sv, _tv = _build_dictionary_result_from_raw(
            raw=raw,
            query_word=german_word,
            source_lang="de",
            target_lang=native_lang,
            query_source_lang="de",
            query_target_lang=native_lang,
            lookup_lang="",
        )
    except Exception as exc:
        logging.warning("rich enrich build failed word=%r: %s", german_word, exc)
        return {}
    return item if isinstance(item, dict) else {}


def _dictionary_payload_needs_enrichment(response_json: dict | None) -> bool:
    payload = response_json if isinstance(response_json, dict) else {}
    entry_kind = str(payload.get("entry_kind") or "").strip().lower()
    # A payload that DECLARES another kind (sentence, phrase…) is out of scope. A payload
    # with no entry_kind at all is a thin save (bot private chat, quick game saves): it
    # carries only the word + translation, so the card stays empty unless we enrich it.
    # The caller still gates on _is_single_word_dictionary_entry before spending an LLM call.
    if entry_kind and entry_kind != "word":
        return False
    # Существительное БЕЗ АРТИКЛЯ — карточка неполная, сколько бы в ней ни было примеров.
    #
    # Проверка стоит ВЫШЕ всех «есть примеры → значит полная»: без неё карточка, у которой
    # не хватает только рода, объявлялась полной и не пересматривалась больше никогда.
    # Для немецкого это не мелочь — род и есть половина слова.
    # Замер 14.08.2026: таких карточек 32 на 5156 существительных, то есть проверка
    # добирает ровно недостающее и лавины платных перезапросов не устраивает.
    # Множественное сюда не попадает: у него артикль «die» выводится из числа, спрашивать
    # модель незачем (см. compose_german_headword в backend/database.py).
    if (
        str(payload.get("part_of_speech") or "").strip().lower() == "noun"
        and not str(payload.get("article") or "").strip()
        and str(payload.get("grammatical_number") or "").strip().lower() not in {"pl", "plural"}
    ):
        return True
    # Примеры и таблицы — самый надёжный признак настоящей карточки. Без этой проверки
    # карточка с двумя примерами и формами (но одним смыслом без контекста) считалась
    # «пустой», и мы платили за её обогащение СНОВА при каждом открытии и каждом проходе
    # бэкфилла (найдено замером 21.07 на «der Zufall»).
    if isinstance(payload.get("usage_examples"), list) and any(
        str(item).strip() if not isinstance(item, dict) else (
            str(item.get("source") or item.get("target") or "").strip()
        )
        for item in payload["usage_examples"]
    ):
        return False
    if isinstance(payload.get("grammar_tables"), (dict, list)) and payload["grammar_tables"]:
        return False
    if isinstance(payload.get("meanings"), dict):
        primary = payload["meanings"].get("primary")
        secondary = payload["meanings"].get("secondary")
        if isinstance(primary, dict) and str(primary.get("value") or "").strip():
            return False
        if isinstance(secondary, list) and any(isinstance(item, dict) and str(item.get("value") or "").strip() for item in secondary):
            return False
    translations = payload.get("translations")
    if isinstance(translations, list) and any(
        (
            isinstance(item, dict) and str(item.get("value") or item.get("translation") or "").strip()
        ) or (
            isinstance(item, str) and str(item).strip()
        )
        for item in translations
    ):
        return False
    senses = payload.get("dictionary_senses")
    if isinstance(senses, list) and len(senses) >= 2:
        return False
    first_sense = senses[0] if isinstance(senses, list) and senses else {}
    if isinstance(first_sense, dict):
        if str(first_sense.get("context") or "").strip():
            return False
        if str(first_sense.get("example_source") or "").strip():
            return False
        if str(first_sense.get("example_target") or "").strip():
            return False
    return True


def _dictionary_word_card_is_thin(payload: dict | None) -> bool:
    """A single-WORD card built by the OLD thin prompt: it may carry forms + examples +
    dictionary_senses (so _dictionary_payload_needs_enrichment calls it "full"), yet lacks
    EVERY rich block the live prompt produces — meanings, translations, collocations,
    Rektion, mnemonic, etymology. This is the "kreieren куцый" state.

    Used ONLY by the user-paced on-open enrich to upgrade such a card to a full one; the
    nightly job deliberately keeps the conservative gate so it never mass-re-enriches on the
    thin→rich switch (that cost-heavy sweep is a separate, explicit step)."""
    if not isinstance(payload, dict):
        return False
    if str(payload.get("entry_kind") or "word").strip().lower() not in ("", "word"):
        return False

    def _nonempty_list(key: str) -> bool:
        v = payload.get(key)
        return isinstance(v, list) and len(v) > 0

    # ANY rich marker → already full (the thin prompt never emits these).
    if _nonempty_list("common_collocations") or _nonempty_list("government_patterns"):
        return False
    if _nonempty_list("translations"):
        return False
    meanings = payload.get("meanings")
    if isinstance(meanings, dict):
        primary = meanings.get("primary")
        if isinstance(primary, dict) and str(primary.get("value") or "").strip():
            return False
        secondary = meanings.get("secondary")
        if isinstance(secondary, list) and any(
            isinstance(m, dict) and str(m.get("value") or "").strip() for m in secondary
        ):
            return False
    # memory_tip / etymology_note are no longer generated (card trimmed 2026-07-24) — dropped
    # from the richness markers so lean cards are treated as complete, not re-enriched.
    return True


def _run_saved_dictionary_entry_enrichment(
    *,
    entry_id: int,
    source_lang: str,
    target_lang: str,
    source_text_hint: str,
    target_text_hint: str,
    force: bool = False,
) -> None:
    try:
        entry = get_dictionary_entry_by_id(int(entry_id))
        if not entry:
            return
        response_json = entry.get("response_json")
        if isinstance(response_json, str):
            try:
                response_json = json.loads(response_json)
            except Exception:
                response_json = {}
        if not isinstance(response_json, dict):
            response_json = {}
        if not force and not _dictionary_payload_needs_enrichment(response_json):
            return

        source_text, target_text = _resolve_entry_texts_for_pair(
            entry=entry,
            response_json=response_json,
            source_lang=source_lang,
            target_lang=target_lang,
            source_text_hint=source_text_hint,
            target_text_hint=target_text_hint,
        )
        if not _is_single_word_dictionary_entry(source_text, source_lang):
            return

        # Unified rich enrichment (same prompt as the live lookup) — full card, not the
        # thin forms+examples the old enrich_word prompt returned.
        enrich_data = _normalize_dictionary_enrich_payload(
            _rich_enrich_card_fields(
                source_text=source_text,
                target_text=target_text,
                source_lang=source_lang,
                target_lang=target_lang,
            )
        )
        if not enrich_data:
            return

        merged_response_json = dict(response_json)
        merged_response_json.update(enrich_data)
        merged_response_json = _prepare_dictionary_response_json_for_save(
            response_json=merged_response_json,
            source_text=source_text,
            target_text=target_text,
            source_lang=source_lang,
            target_lang=target_lang,
            word_ru=str(entry.get("word_ru") or merged_response_json.get("word_ru") or "").strip() or None,
            word_de=str(entry.get("word_de") or merged_response_json.get("word_de") or "").strip() or None,
            translation_de=str(entry.get("translation_de") or merged_response_json.get("translation_de") or "").strip() or None,
            translation_ru=str(entry.get("translation_ru") or merged_response_json.get("translation_ru") or "").strip() or None,
        )
        # A de→ru row whose RU column carries no Cyrillic was saved German-on-both-sides
        # (bare-text save with no gloss). response_json alone would not repair the list
        # view, so rewrite the legacy columns from the freshly enriched card as well.
        russian = _extract_target_translation_from_breakdown(merged_response_json)
        if (
            source_lang == "de"
            and target_lang == "ru"
            and _text_has_cyrillic(russian)
            and not _text_has_cyrillic(entry.get("translation_ru"))
        ):
            update_dictionary_entry_full_columns(
                int(entry_id),
                word_ru=str(merged_response_json.get("word_ru") or russian),
                word_de=str(merged_response_json.get("word_de") or source_text),
                translation_de=str(merged_response_json.get("translation_de") or source_text),
                translation_ru=russian,
                response_json=merged_response_json,
            )
        else:
            update_webapp_dictionary_entry(int(entry_id), merged_response_json)
        _publish_enriched_card_to_shared_stores(
            payload=merged_response_json,
            source_lang=source_lang,
            target_lang=target_lang,
            source_text=source_text,
            target_text=target_text or russian,
        )
        logging.info(
            "Dictionary save enrichment ready: entry_id=%s source_lang=%s target_lang=%s source_text=%r",
            int(entry_id),
            source_lang,
            target_lang,
            source_text,
        )
    except Exception as exc:
        logging.warning(
            "Dictionary save enrichment failed: entry_id=%s source_lang=%s target_lang=%s error=%s",
            int(entry_id),
            source_lang,
            target_lang,
            exc,
            exc_info=True,
        )
    finally:
        with _DICTIONARY_SAVE_ENRICHMENT_LOCK:
            _DICTIONARY_SAVE_ENRICHMENT_INFLIGHT.discard(int(entry_id))


_CYRILLIC_RE = re.compile(r"[А-Яа-яЁё]")


def _text_has_cyrillic(value) -> bool:
    return bool(_CYRILLIC_RE.search(str(value or "")))


def _extract_target_translation_from_breakdown(item) -> str:
    """Pull a concise target-language translation string out of a GPT breakdown item
    (translations[].value / meanings.primary). Mirrors the frontend extractor so the
    backfill produces the same standard card a fresh save would."""
    if not isinstance(item, dict):
        return ""
    out: list[str] = []

    def push(v) -> None:
        raw = v.get("value") if isinstance(v, dict) else v
        s = str(raw or "").strip()
        if s and s not in out:
            out.append(s)

    for t in (item.get("translations") or []):
        if len(out) >= 2:
            break
        push(t)
    if not out:
        meanings = item.get("meanings")
        if isinstance(meanings, dict):
            push(meanings.get("primary"))
    return ", ".join(out)


def _dictionary_entry_already_has_russian(row: dict) -> bool:
    """True if the de→ru entry already carries a Russian translation somewhere, so the
    backfill can skip it (no LLM call, no overwrite of good data)."""
    if _text_has_cyrillic(row.get("translation_ru")) or _text_has_cyrillic(row.get("word_ru")):
        return True
    response_json = row.get("response_json")
    if isinstance(response_json, str):
        try:
            response_json = json.loads(response_json)
        except Exception:
            response_json = {}
    if _text_has_cyrillic(_extract_target_translation_from_breakdown(response_json)):
        return True
    return False


def backfill_quick_dictionary_translations(
    *,
    dry_run: bool = True,
    max_entries: int = 400,
    user_id: int | None = None,
    days: int | None = None,
) -> dict:
    """Repair quick-dictionary entries (incl. tapped synonym chips) that were stored as
    bare German text without a Russian translation. For each broken de→ru entry, re-run
    the canonical breakdown lookup and rewrite ALL columns to the standard card format.
    dry_run=True only scans and reports; pass dry_run=False to actually write."""
    report = {
        "dry_run": bool(dry_run),
        "days": days,
        "scanned": 0,
        "broken": 0,
        "fixed": 0,
        "skipped_has_ru": 0,
        "skipped_no_german": 0,
        "errors": 0,
        "samples": [],
        "diagnostics": {},
    }
    try:
        report["diagnostics"] = get_dictionary_backfill_diagnostics(user_id=user_id)
    except Exception as exc:
        report["diagnostics"] = {"error": str(exc)}
    try:
        rows = get_quick_dictionary_entries_for_backfill(user_id=user_id, limit=max_entries, days=days)
    except Exception as exc:
        report["errors"] += 1
        report["error_detail"] = str(exc)
        return report

    for row in rows:
        report["scanned"] += 1
        # Candidacy (de→ru, translation_ru lacks Cyrillic) is already enforced in SQL.
        response_json = row.get("response_json")
        if isinstance(response_json, str):
            try:
                response_json = json.loads(response_json)
            except Exception:
                response_json = {}
        if _dictionary_entry_already_has_russian(row):
            report["skipped_has_ru"] += 1
            continue
        # The German headword the chip/word was saved under. On rows saved with an
        # inverted ru→de pair the German sits in word_ru, so fall back to it too.
        german = str(row.get("word_de") or row.get("translation_de") or "").strip()
        if not german and not _text_has_cyrillic(row.get("word_ru")):
            german = str(row.get("word_ru") or "").strip()
        if not german and isinstance(response_json, dict):
            german = str(response_json.get("word_de") or response_json.get("source_text") or "").strip()
        if not german:
            report["skipped_no_german"] += 1
            continue
        report["broken"] += 1
        if len(report["samples"]) < 25:
            report["samples"].append({"id": row.get("id"), "german": german})
        if dry_run:
            continue
        try:
            rich = asyncio.run(run_dictionary_lookup_multilang(german, "de", "ru"))
            russian = _extract_target_translation_from_breakdown(rich)
            if not _text_has_cyrillic(russian):
                report["errors"] += 1
                continue
            rich_word_de = str((rich or {}).get("word_de") or "").strip() or german
            prepared = _prepare_dictionary_response_json_for_save(
                response_json=rich if isinstance(rich, dict) else {},
                source_text=german,
                target_text=russian,
                source_lang="de",
                target_lang="ru",
                word_ru=russian,
                word_de=rich_word_de,
                translation_de=german,
                translation_ru=russian,
            )
            update_dictionary_entry_full_columns(
                int(row.get("id")),
                word_ru=str(prepared.get("word_ru") or russian),
                word_de=str(prepared.get("word_de") or rich_word_de),
                translation_de=str(prepared.get("translation_de") or german),
                translation_ru=str(prepared.get("translation_ru") or russian),
                response_json=prepared,
                # Rows saved with an inverted pair are re-filed as de→ru, otherwise the
                # reader would keep interpreting the German column as the source.
                source_lang="de",
                target_lang="ru",
            )
            report["fixed"] += 1
        except Exception as exc:
            report["errors"] += 1
            logging.warning(
                "dictionary translation backfill failed entry_id=%s german=%r error=%s",
                row.get("id"), german, exc, exc_info=True,
            )
    return report


def _publish_enriched_card_to_shared_stores(
    *,
    payload: dict | None,
    source_lang: str,
    target_lang: str,
    source_text: str,
    target_text: str,
) -> None:
    """Обогащённая карточка — ОБЩЕЕ достояние. Кто бы её ни оплатил (сохранение, открытие
    пустой карточки, бэкфилл), она уходит в общий пул и в общий кеш запросов, чтобы
    следующий пользователь получил слово от нас, а не из GPT."""
    if not isinstance(payload, dict) or not payload:
        return
    if _dictionary_payload_needs_enrichment(payload):
        return  # неполную карточку в общие хранилища не кладём
    src = str(source_text or "").strip()
    tgt = str(target_text or "").strip()
    if not src or not tgt:
        return
    # ЕДИНИЦА — дом разбора: обогащённая карточка ложится на само слово, и его получают
    # все, кто на слово подписан, а не только тот, чью карточку дообогатили. Пул пока
    # тоже наполняем: из него читает поиск, и отключим мы его только когда чтение
    # переедет на единицы.
    try:
        german = src if str(source_lang or "").lower() == "de" else (
            tgt if str(target_lang or "").lower() == "de" else ""
        )
        if german:
            unit_id = lex_units.ensure_unit(german, "de")
            if unit_id:
                lex_units.save_unit_card_if_richer(int(unit_id), payload, source="обогащение")
    except Exception as exc:
        logging.debug("обогащённая карточка → единица не легла: %s", exc)
    try:
        upsert_dictionary_pool_entry(
            source_lang=source_lang,
            target_lang=target_lang,
            source_text=src,
            target_text=tgt,
            word_ru=str(payload.get("word_ru") or "").strip() or None,
            translation_de=str(payload.get("translation_de") or "").strip() or None,
            word_de=str(payload.get("word_de") or "").strip() or None,
            translation_ru=str(payload.get("translation_ru") or "").strip() or None,
            response_json=payload,
        )
    except Exception as exc:
        logging.debug("enriched card → pool failed: %s", exc)
    if not DICTIONARY_SHARED_CACHE_ENABLED:
        return
    try:
        normalized_word = _normalize_dictionary_lookup_word(src)
        query_source_lang, query_target_lang = _resolve_dictionary_query_languages(
            word=src,
            source_lang=source_lang,
            target_lang=target_lang,
            lookup_lang=source_lang,
        )
        cache_key_shared = _build_dictionary_lookup_cache_key(
            user_id=None,
            source_lang=source_lang,
            target_lang=target_lang,
            query_source_lang=query_source_lang,
            query_target_lang=query_target_lang,
            lookup_lang=source_lang,
            word=src,
        )
        _set_cached_dictionary_lookup_all(
            cache_key=cache_key_shared,
            payload={
                "item": payload,
                "direction": f"{query_source_lang}-{query_target_lang}",
                "lookup_status": "ready",
                "enrichment_pending": False,
            },
            source_lang=source_lang,
            target_lang=target_lang,
            query_source_lang=query_source_lang,
            query_target_lang=query_target_lang,
            lookup_lang=source_lang,
            normalized_word=normalized_word,
        )
    except Exception as exc:
        logging.debug("enriched card → shared cache failed: %s", exc)


def _drop_wrong_language_examples(enrich_data: dict | None, *, learning_lang: str = "de") -> dict:
    """Выбросить примеры, написанные не на изучаемом языке.

    Страховка на случай, если модель снова напишет примеры на родном языке: пустить такую
    карточку в ОБЩИЙ пул хуже, чем оставить её без примеров, — ошибку увидят все."""
    data = dict(enrich_data) if isinstance(enrich_data, dict) else {}
    examples = data.get("usage_examples")
    if not isinstance(examples, list) or learning_lang != "de":
        return data
    kept = []
    for item in examples:
        text = str(item.get("source") or item.get("example_source") or "") if isinstance(item, dict) else str(item or "")
        if text.strip() and not _text_has_cyrillic(text):
            kept.append(item)
    if len(kept) != len(examples):
        logging.warning(
            "enrichment returned %s non-German usage examples — dropped",
            len(examples) - len(kept),
        )
    data["usage_examples"] = kept
    return data


_POOL_ENRICH_SINGLE_PAIR = False  # True = только заданная пара (для ручной отладки)
# ПОТОЛОК НОЧИ: 500 карточек. Решение владельца 25.08.2026.
#
# На 25.08 пустых слов и словосочетаний 1 815 — при 500 за ночь это четыре ночи, а не
# один счёт на всю сумму. Владелец дословно: «не нужно сразу всё отправлять, это будет
# четыре ночи, кэшированная отправка дешевле».
#
# Почему именно 500, а не «сколько получится»: потолок держит расход предсказуемым при
# любом числе людей. Считать его надо в КАРТОЧКАХ ЗА НОЧЬ, а не в пользователях — работа
# растёт от числа новых РАЗНЫХ слов, а не от того, сколько человек их сохранило: замер
# 25.08.2026 — на 15 596 слов приходится 24 855 карточек, то есть 1,59 человека на слово.
POOL_NIGHT_ENRICH_DAILY_CAP = int((os.getenv("POOL_NIGHT_ENRICH_DAILY_CAP") or "500").strip() or "500")
# Раздача уже собранного разбора по личным карточкам не стоит ничего — это обычный UPDATE,
# без единого обращения к модели. Поэтому потолок здесь щедрый: он ограничивает только
# длину ночного прохода, а не расходы. Отставание на 01.08.2026 — 3648 карточек.
UNIT_CARD_SPREAD_NIGHT_LIMIT = int(
    (os.getenv("UNIT_CARD_SPREAD_NIGHT_LIMIT") or "2000").strip() or "2000"
)
# Ночная раздача выключена 15.08.2026 — читатели берут содержимое с общего слова, и
# копии в личных карточках больше не нужны (подробности у самого вызова). Переменная
# оставлена как рубильник: поставить 1 — раздача снова пойдёт.
UNIT_CARD_NIGHT_SPREAD_ENABLED = str(
    os.getenv("UNIT_CARD_NIGHT_SPREAD") or "0"
).strip().lower() in {"1", "true", "yes", "on"}
# Одно слово могут держать у себя несколько человек; больше сотни копий одной карточки
# не бывает, а потолок страхует от бесконечного прохода при странных данных.
UNIT_CARD_SPREAD_PER_WORD_LIMIT = 100
# Ночью ответа никто не ждёт, а полный разбор — тяжёлый запрос: с «живым» таймаутом в
# 14 секунд 85 слов из 200 срывались, не дождавшись ответа. Даём фону нормальное время.
# «Полный разбор» человек ждёт осознанно и на длинном предложении 14 секунд не хватает:
# запрос срывается, включается запасной путь — простой перевод, — и экран выходит пустым,
# без значений, примеров и вариантов для сохранения. Даём ему больше времени.
DICTIONARY_DEEP_RESPONSES_TIMEOUT_SECONDS = max(
    5.0, float((os.getenv("DICTIONARY_DEEP_RESPONSES_TIMEOUT_SECONDS") or "35").strip() or "35"))

POOL_NIGHT_ENRICH_TIMEOUT_SECONDS = max(
    5.0, float((os.getenv("POOL_NIGHT_ENRICH_TIMEOUT_SECONDS") or "60").strip() or "60"))
_POOL_NIGHT_ENRICH_LOCK = threading.Lock()
_POOL_NIGHT_ENRICH_RUNNING = False


SYNONYM_BACKFILL_NIGHT_LIMIT = max(
    0, int((os.getenv("SYNONYM_BACKFILL_NIGHT_LIMIT") or "400").strip() or "400")
)


def _run_synonym_backfill(*, limit: int, learning_lang: str = "de", native_lang: str = "ru") -> dict:
    """Добрать синонимы словам, у которых разбор уже есть, а синонимов нет.

    Зачем отдельно от основного ночного добора. Тот берёт слова БЕЗ разбора и уже
    обогащённые не трогает вовсе — правильно, иначе он платил бы дважды. Но синонимы мы
    стали просить только 10.08.2026: до этого их не просил ни один промпт живого пути.
    Значит всё накопленное осталось бы без них навсегда — замер того же дня: 9 469 слов,
    из них 9 261 лежат у людей в личных карточках.

    Запрос короткий, только про синонимы: карточка целиком уже куплена, и переспрашивать
    её значило бы платить второй раз за то же.

    Пустой ответ — не ошибка: у части слов близких синонимов действительно нет, и модели
    прямо сказано возвращать пустой список, а не выдумывать. Такое слово мы больше не
    трогаем: считать его «недоделанным» и спрашивать каждую ночь — это платить за
    один и тот же отказ бесконечно. Поэтому в карточку кладём отметку, что спрашивали.
    """
    report = {"picked": 0, "filled": 0, "empty": 0, "errors": 0, "remaining": 0}
    if limit <= 0:
        return report
    try:
        from backend import lex_units
        from backend.openai_manager import run_dictionary_synonyms_backfill
        units = lex_units.units_needing_synonyms(limit, lang=learning_lang)
    except Exception:
        logging.warning("отбор слов для добора синонимов не удался", exc_info=True)
        return report

    report["picked"] = len(units)
    for unit in units:
        german = str(unit.get("display") or "").strip()
        if not german:
            continue
        try:
            data = asyncio.run(run_dictionary_synonyms_backfill(
                word=german,
                translation=str(unit.get("translation") or ""),
                source_lang=learning_lang,
                target_lang=native_lang,
                explanation_lang=native_lang,
            ))
        except Exception:
            logging.warning("добор синонимов не удался для %r", german, exc_info=True)
            report["errors"] += 1
            continue

        if not isinstance(data, dict):
            report["errors"] += 1
            continue

        patch = {}
        for key in ("synonyms", "antonyms", "related_words"):
            value = data.get(key)
            if isinstance(value, list) and value:
                patch[key] = value
        # Тот же страж целостности, что и на записи разбора: этот путь пишет в разбор
        # напрямую (card || patch), мимо lex_units.save_unit_card, — значит защита
        # обязана стоять и здесь. Отметку «спрашивали» при этом сохраняем: слово
        # спрашивали, а негодный ответ модели не повод гонять его в очереди вечно.
        from backend.mangled_text import mangled_strings_inside
        порча = mangled_strings_inside(patch)
        if порча:
            logging.warning("синонимы для %r не записаны — текст размножен сам на себя: %s",
                            german, " | ".join(x[:70] for x in порча[:3]))
            report["errors"] += 1
            patch = {}

        # Отметка «спрашивали» ставится ВСЕГДА, даже когда модель вернула пустоту:
        # без неё слово вернулось бы в очередь завтра и послезавтра.
        patch["synonyms_asked_at"] = datetime.now(timezone.utc).isoformat()

        try:
            from backend.database import get_db_connection_context
            with get_db_connection_context() as conn:
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE bt_3_lex_units SET card = card || %s::jsonb, updated_at = NOW() "
                        "WHERE id = %s AND card IS NOT NULL;",
                        (json.dumps(patch, ensure_ascii=False), int(unit["id"])),
                    )
                conn.commit()
            if any(k in patch for k in ("synonyms", "antonyms", "related_words")):
                report["filled"] += 1
            else:
                report["empty"] += 1
        except Exception:
            logging.warning("запись синонимов не удалась для %r", german, exc_info=True)
            report["errors"] += 1

    try:
        from backend import lex_units as _lu
        report["remaining"] = _lu.count_units_needing_synonyms(lang=learning_lang)
    except Exception:
        pass
    return report


def _run_units_night_enrichment(
    *,
    cap: int,
    dry_run: bool,
    report: dict,
    learning_lang: str = "de",
    native_lang: str = "ru",
    progress_cb=None,
) -> dict:
    """Ночной добор разбора для СЛОВ СЛОЯ ЕДИНИЦ.

    Отличие от добора по банку одно, но важное: разбор кладётся на саму единицу, поэтому
    он не может «переехать» к соседнему слову — у каждого слова свой ящик. Порядок —
    по востребованности: сначала то, что люди действительно сохранили себе.

    Отчёт возвращается в том же виде, что и у добора по банку, чтобы утренняя сводка
    и админ-команда продолжали работать без правок."""
    # Сначала подбираем карточки, оставшиеся без указателя на слово: путей сохранения
    # много, и каждый новый легко забыть. Подбор дешёвый и обычно находит ноль.
    try:
        attach_report = lex_units.attach_missing_entries()
        if attach_report.get("attached"):
            report["cards_attached"] = attach_report["attached"]
    except Exception:
        logging.debug("привязка карточек перед добором не удалась", exc_info=True)

    # ─────────────────────────────────────────────────────────────────────────────
    # НОЧНАЯ РАЗДАЧА РАЗБОРА ПО ЛИЧНЫМ КАРТОЧКАМ ВЫКЛЮЧЕНА 15.08.2026.
    #
    # Она вписывала содержимое слова в карточку каждого человека. Нужна была ровно
    # затем, что читатели умели читать только личную карточку: пусто в карточке —
    # пусто на экране, хотя разбор давно собран и оплачен.
    #
    # Читатели переведены на общее слово (перепись: docs/tasks/dictionary_readers_census.md):
    # словарь, «Мои слова», главный экран, тренажёр предложений, квизы в чате, очередь
    # повторения — все берут содержимое из справочника. Раздавать копии больше незачем.
    #
    # ЧЕМ ЭТО БЫЛО ВРЕДНО: копия — фотография. Слово уточняют, а у человека остаётся
    # вчерашнее. Замер 14.08.2026: у всех 3 990 тяжёлых копий слово улучшали ПОЗЖЕ, в
    # среднем на 105 дней. И она же возвращала снятые копии: 2 315 сняли — за одну ночь
    # вернулись 1 994.
    #
    # Функция fill_thin_cards_from_units НЕ удалена: её по-прежнему зовут точечно,
    # когда слово только что разобрали (там она уместна — один раз, по одному слову).
    # Если понадобится вернуть ночной прогон, ставь переменную UNIT_CARD_NIGHT_SPREAD=1.
    # ─────────────────────────────────────────────────────────────────────────────
    if not dry_run and UNIT_CARD_NIGHT_SPREAD_ENABLED:
        try:
            spread = fill_thin_cards_from_units(
                limit=UNIT_CARD_SPREAD_NIGHT_LIMIT, lang=learning_lang,
            )
            if spread.get("filled"):
                report["cards_filled_from_units"] = spread["filled"]
        except Exception:
            logging.warning("раздача готового разбора по карточкам не удалась", exc_info=True)
        # Слова, которым разбор уже собрали раньше, но часть речи так и не проставили:
        # артикль в разборе есть, а слово формально «неизвестно что» и потому без рода.
        # Проход бесплатный и идёт тут же, чтобы такие хвосты не копились годами.
        try:
            adopted = lex_units.backfill_pos_gender_from_cards(lang=learning_lang)
            if adopted.get("updated"):
                report["pos_adopted"] = adopted["updated"]
        except Exception:
            logging.warning("простановка части речи по артиклю не удалась", exc_info=True)
        # Род, взятый из разбора про ДРУГОЕ написание, врёт прямо на заголовке: у слова
        # «Spritpreis» разбор озаглавлен «die Spritpreise», и «die» уезжает на
        # единственное число — на экране «die Spritpreis». Сверяем колонку рода с тем же
        # арбитром, что решает род в игре с артиклями, и чиним ТОЛЬКО этот класс.
        # Спорное («der Dicke» толстяк / «die Dicke» толщина) не трогаем, а считаем:
        # род по значению — решение владельца, а не правила.
        try:
            genders = lex_units.fix_gender_conflicts_from_authority(lang=learning_lang)
            if genders.get("fixed"):
                report["genders_fixed"] = genders["fixed"]
            if genders.get("doubts"):
                report["gender_doubts"] = genders["doubts"]
                report["gender_doubt_samples"] = genders.get("doubt_samples") or []
        except Exception:
            logging.warning("сверка рода с арбитром не удалась", exc_info=True)

    units = lex_units.units_needing_card(cap, lang=learning_lang, native_lang=native_lang)
    report["picked"] = len(units)
    report["mode"] = "units"
    for index, unit in enumerate(units):
        if progress_cb is not None:
            try:
                progress_cb(index, len(units), report)
            except Exception:
                logging.debug("units enrich progress_cb failed", exc_info=True)
        german = str(unit.get("display") or unit.get("lemma") or "").strip()
        translation = str(unit.get("translation") or "").strip()
        if len(report["samples"]) < 20:
            report["samples"].append({
                "word": german, "translation": translation,
                "demand": unit.get("saved") or unit.get("sources"),
            })
        if dry_run:
            continue
        try:
            enrich_data = _normalize_dictionary_enrich_payload(
                _rich_enrich_card_fields(
                    source_text=german, target_text=translation,
                    source_lang=learning_lang, target_lang=native_lang,
                    timeout_seconds=POOL_NIGHT_ENRICH_TIMEOUT_SECONDS,
                )
            )
            enrich_data = _drop_wrong_language_examples(enrich_data, learning_lang=learning_lang)
            if not enrich_data:
                report["skipped"] += 1
                report["skipped_empty"] += 1
                if len(report["skipped_samples"]) < 15:
                    report["skipped_samples"].append({"word": german, "reason": "empty"})
                continue
            # Та же планка, что и везде: тонкую карточку не сохраняем, пусть слово
            # останется кандидатом, а не притворяется разобранным.
            if _dictionary_payload_needs_enrichment(enrich_data):
                report["skipped"] += 1
                report["skipped_thin"] += 1
                if len(report["skipped_samples"]) < 15:
                    report["skipped_samples"].append({"word": german, "reason": "thin"})
                continue
            if lex_units.save_unit_card(unit["id"], enrich_data):
                report["enriched"] += 1
                # Артикль из свежего разбора сразу делает слово существительным с родом.
                # Без этого шага слово остаётся «неизвестно чем»: род требуется только
                # существительным, и в отчётах оно так и висит без артикля.
                lex_units.adopt_pos_gender_from_card(int(unit["id"]), enrich_data)
                # Разбор собран — и этого достаточно: он лежит на СЛОВЕ, а карточки
                # читают его оттуда при показе. Раскладывать копии по людям больше не
                # нужно (см. пояснение у ночной раздачи). Рубильник — UNIT_CARD_NIGHT_SPREAD=1.
                if UNIT_CARD_NIGHT_SPREAD_ENABLED:
                    try:
                        fill_thin_cards_from_units(
                            limit=UNIT_CARD_SPREAD_PER_WORD_LIMIT,
                            unit_id=int(unit["id"]),
                            lang=learning_lang,
                        )
                    except Exception:
                        logging.debug(
                            "раздача разбора слова %r по карточкам не удалась", german, exc_info=True,
                        )
                # Разбор знает про слово больше, чем старая строка перевода из банка:
                # у «die Scheide» в связях было только «влагалище», хотя есть и «ножны».
                # Поэтому сразу перечитываем переводы из разбора и раскладываем по
                # значениям — иначе смысл так и остался бы невидимым.
                lex_units.sync_unit_links_from_card(
                    unit["id"], enrich_data, native_lang=native_lang,
                )
            else:
                report["errors"] += 1
        except Exception:
            logging.warning("units night enrich failed for %r", german, exc_info=True)
            report["errors"] += 1
    # Остаток берём отдельным подсчётом, а не из выборки: она ограничена ночным
    # потолком, и сводка отчиталась бы «осталось 86» при 3356 неразобранных.
    report["remaining"] = lex_units.count_units_needing_card(lang=learning_lang)

    # Добор синонимов идёт ПОСЛЕ основного и своим потолком: основной добор важнее —
    # слово без разбора вообще нечего показать, а слово без синонимов показывается,
    # просто беднее.
    if not dry_run and SYNONYM_BACKFILL_NIGHT_LIMIT > 0:
        try:
            report["synonyms"] = _run_synonym_backfill(
                limit=SYNONYM_BACKFILL_NIGHT_LIMIT,
                learning_lang=learning_lang,
                native_lang=native_lang,
            )
        except Exception:
            logging.warning("ночной добор синонимов не удался", exc_info=True)
    return report


# Личные поля карточки: кто её сохранил, каким текстом и в какую сторону. Из общего
# разбора слова их брать НЕЛЬЗЯ — иначе чужая нормализованная форма затрёт то, что
# человек сохранил себе, а направление пары может перевернуться.
_UNIT_CARD_IDENTITY_KEYS = frozenset({
    "source_text", "target_text", "source_lang", "target_lang", "language_pair",
    "word_ru", "word_de", "translation_ru", "translation_de",
    "entry_kind", "sentence_origin", "enrich_attempts",
})


def fill_thin_cards_from_units(
    *,
    limit: int = 500,
    unit_id: int | None = None,
    entry_id: int | None = None,
    lang: str = "de",
) -> dict:
    """Перенести уже собранный разбор слова в пустые личные карточки. Без GPT.

    Ночной добор кладёт разбор на ЕДИНИЦУ — одну на всех, и это правильно: одно слово
    разбирается один раз и стоит одну оплату. Но тренажёр и подсказка читают ЛИЧНУЮ
    карточку, а туда разбор сам не переезжает: на 01.08.2026 разбор был готов у 3648
    пустых карточек и ни одна его не показывала.

    Перенос бесплатный, поэтому он не имеет права ничего испортить: личные поля
    (что человек сохранил, в какую сторону) остаются как есть, из разбора берём только
    то, чего в карточке нет. Готовые блоки не переписываются никогда — выборка отдаёт
    заготовки без примеров и карточки, которым единица может добавить недостающий разбор."""
    report = {"picked": 0, "filled": 0, "skipped": 0, "errors": 0, "samples": []}
    try:
        rows = lex_units.thin_entries_with_unit_card(
            limit=int(limit), unit_id=unit_id, entry_id=entry_id, lang=lang,
        )
    except Exception:
        logging.warning("перенос разбора: выборка не удалась", exc_info=True)
        return report
    report["picked"] = len(rows)
    for row in rows:
        try:
            card = row.get("card") if isinstance(row.get("card"), dict) else {}
            merged = dict(row.get("response_json") or {})
            changed = False
            for key, value in card.items():
                if key in _UNIT_CARD_IDENTITY_KEYS:
                    continue
                if value in (None, "", [], {}):
                    continue
                existing = merged.get(key)
                if existing in (None, "", [], {}):
                    merged[key] = copy.deepcopy(value)
                    changed = True
            if not changed:
                report["skipped"] += 1
                continue
            entry_source_lang = str(row.get("source_lang") or "").strip().lower() or "de"
            entry_target_lang = str(row.get("target_lang") or "").strip().lower() or "ru"
            source_text, target_text = _resolve_entry_texts_for_pair(
                entry=row,
                response_json=merged,
                source_lang=entry_source_lang,
                target_lang=entry_target_lang,
            )
            merged = _prepare_dictionary_response_json_for_save(
                response_json=merged,
                source_text=source_text,
                target_text=target_text,
                source_lang=entry_source_lang,
                target_lang=entry_target_lang,
                word_ru=row.get("word_ru"),
                word_de=row.get("word_de"),
                translation_de=row.get("translation_de"),
                translation_ru=row.get("translation_ru"),
            )
            update_webapp_dictionary_entry(int(row["entry_id"]), merged)
            report["filled"] += 1
            if len(report["samples"]) < 20:
                report["samples"].append({
                    "word": str(row.get("word_de") or source_text or "").strip(),
                    "user_id": row.get("user_id"),
                })
        except Exception:
            report["errors"] += 1
            logging.warning(
                "перенос разбора не удался entry_id=%s", row.get("entry_id"), exc_info=True,
            )
    if report["filled"]:
        logging.info(
            "перенос разбора из слоя единиц: наполнено %d карточек из %d отобранных",
            report["filled"], report["picked"],
        )
    return report


# Потолок явного пересбора: разовая уборка не должна превращаться в тысячу вызовов
# подряд, если однажды планка полноты сдвинется ещё раз.
UNIT_RESWEEP_DEFAULT_LIMIT = int((os.getenv("UNIT_RESWEEP_DEFAULT_LIMIT") or "300").strip() or "300")


def resweep_thin_unit_cards(
    *,
    limit: int | None = None,
    dry_run: bool = False,
    learning_lang: str = "de",
    native_lang: str = "ru",
    progress_cb=None,
) -> dict:
    """Пересобрать разбор у слов с КУЦЕЙ карточкой: примеры и формы есть, а значений,
    управления и сочетаний нет.

    Ночной добор такие слова не берёт намеренно — он смотрит только на слова вовсе без
    разбора, чтобы сдвиг планки полноты не запустил массовый пересбор за деньги сам
    собой. Поэтому это отдельный ЯВНЫЙ шаг с потолком и с сухим прогоном по умолчанию.

    Собранный разбор тут же расходится по личным карточкам этого слова — иначе он снова
    ляжет на единицу и до человека не дойдёт."""
    cap = int(limit if limit is not None else UNIT_RESWEEP_DEFAULT_LIMIT)
    report = {
        "dry_run": bool(dry_run), "cap": cap, "picked": 0, "enriched": 0,
        "skipped_empty": 0, "skipped_thin": 0, "errors": 0,
        "cards_filled": 0, "remaining": 0, "samples": [],
    }
    units = lex_units.units_with_thin_card(cap, lang=learning_lang, native_lang=native_lang)
    report["picked"] = len(units)
    for index, unit in enumerate(units):
        if progress_cb is not None:
            try:
                progress_cb(index, len(units), report)
            except Exception:
                logging.debug("resweep progress_cb failed", exc_info=True)
        german = str(unit.get("display") or unit.get("lemma") or "").strip()
        translation = str(unit.get("translation") or "").strip()
        if len(report["samples"]) < 20:
            report["samples"].append({"word": german, "translation": translation,
                                      "saved": unit.get("saved")})
        if dry_run:
            continue
        try:
            enrich_data = _normalize_dictionary_enrich_payload(
                _rich_enrich_card_fields(
                    source_text=german, target_text=translation,
                    source_lang=learning_lang, target_lang=native_lang,
                    timeout_seconds=POOL_NIGHT_ENRICH_TIMEOUT_SECONDS,
                )
            )
            enrich_data = _drop_wrong_language_examples(enrich_data, learning_lang=learning_lang)
            if not enrich_data:
                report["skipped_empty"] += 1
                continue
            # Планка та же, что у ночного: не сохраняем карточку, которая не стала лучше.
            # Иначе мы платим за вызов и оставляем слово в той же куцей яме.
            if _dictionary_word_card_is_thin(enrich_data):
                report["skipped_thin"] += 1
                continue
            if lex_units.save_unit_card(unit["id"], enrich_data, source="пересбор"):
                report["enriched"] += 1
                lex_units.adopt_pos_gender_from_card(int(unit["id"]), enrich_data)
                # Копии по людям не раскладываем: карточка читает слово при показе.
                if UNIT_CARD_NIGHT_SPREAD_ENABLED:
                    spread = fill_thin_cards_from_units(
                        limit=UNIT_CARD_SPREAD_PER_WORD_LIMIT,
                        unit_id=int(unit["id"]), lang=learning_lang,
                    )
                    report["cards_filled"] += int(spread.get("filled") or 0)
                lex_units.sync_unit_links_from_card(
                    unit["id"], enrich_data, native_lang=native_lang,
                )
            else:
                report["errors"] += 1
        except Exception:
            logging.warning("пересбор не удался для %r", german, exc_info=True)
            report["errors"] += 1
    report["remaining"] = lex_units.count_units_with_thin_card(lang=learning_lang)
    return report


def run_pool_night_enrichment(
    *,
    limit: int | None = None,
    dry_run: bool = False,
    source_lang: str = "de",
    target_lang: str = "ru",
    progress_cb=None,
) -> dict:
    """Ночной добор ТОНКИХ записей общего пула.

    Пул отдаёт запрос без GPT только если карточка полная; тонкие записи (слово+перевод
    из быстрого перевода или тонкого сохранения) заставляют каждый повторный запрос идти
    в GPT. Здесь мы добираем их заранее — один раз за всех.

    Берём ТОЛЬКО одиночные слова: 71% тонких записей — фразы и предложения (замер
    2026-07-21: 2234 слова из 7819), разбор со склонением им не нужен, а бюджет бы съели.
    Порядок — по востребованности (hit_count), чтобы сначала добрать то, что реально ищут.
    Потолок в POOL_NIGHT_ENRICH_DAILY_CAP: без него это тысячи вызовов подряд."""
    cap = int(limit if limit is not None else POOL_NIGHT_ENRICH_DAILY_CAP)
    report = {
        "dry_run": bool(dry_run), "cap": cap, "picked": 0,
        "enriched": 0, "skipped": 0, "errors": 0, "remaining": 0, "samples": [],
        # Split "skipped" by ROOT CAUSE so the morning report can say WHY, not just how
        # many: "empty" = the GPT lookup failed/returned nothing usable; "thin" = GPT DID
        # answer but the card still lacked every real field (examples/tables/meanings/…),
        # usually a garbage token, proper noun, or a word whose examples the language
        # filter stripped. skipped_samples keeps a few offenders to eyeball.
        "skipped_empty": 0, "skipped_thin": 0, "skipped_samples": [],
    }
    if cap <= 0:
        return report
    global _POOL_NIGHT_ENRICH_RUNNING
    if not dry_run:
        with _POOL_NIGHT_ENRICH_LOCK:
            if _POOL_NIGHT_ENRICH_RUNNING:
                report["already_running"] = True
                return report
            _POOL_NIGHT_ENRICH_RUNNING = True
    # Когда поиск читает слой единиц, добирать надо ИМЕННО единицы: иначе ночной бюджет
    # уходил бы на строки старого банка, которые больше никто не открывает.
    if DICTIONARY_UNITS_LOOKUP_ENABLED:
        try:
            return _run_units_night_enrichment(
                cap=cap, dry_run=dry_run, report=report,
                learning_lang=source_lang if source_lang == "de" else "de",
                native_lang=target_lang if source_lang == "de" else source_lang,
                progress_cb=progress_cb,
            )
        finally:
            if not dry_run:
                with _POOL_NIGHT_ENRICH_LOCK:
                    _POOL_NIGHT_ENRICH_RUNNING = False
    try:
        rows = get_thin_pool_entries_for_enrichment(
            limit=cap, source_lang=source_lang, target_lang=target_lang,
        )
        # Обе стороны пула в одном прогоне: когда de→ru закончится (711 слов), ночной
        # бюджет обязан перетечь на ru→de (1523), иначе джоб начнёт вхолостую просыпаться,
        # а половина пула так и останется тонкой.
        if len(rows) < cap and not _POOL_ENRICH_SINGLE_PAIR:
            rows += get_thin_pool_entries_for_enrichment(
                limit=cap - len(rows), source_lang=target_lang, target_lang=source_lang,
            )
        report["picked"] = len(rows)
        for _idx, row in enumerate(rows):
            # Optional progress ping (manual runs only) — lets the caller show movement so
            # a slow run is distinguishable from a stuck one. Never let it break enrichment.
            if progress_cb is not None:
                try:
                    progress_cb(_idx, len(rows), report)
                except Exception:
                    logging.debug("pool enrich progress_cb failed", exc_info=True)
            row_source_lang = str(row.get("source_lang") or source_lang).strip().lower()
            row_target_lang = str(row.get("target_lang") or target_lang).strip().lower()
            source_text = str(row.get("source_text") or "").strip()
            target_text = str(row.get("target_text") or "").strip()
            if len(report["samples"]) < 20:
                report["samples"].append({
                    "word": source_text, "translation": target_text, "demand": row.get("demand"),
                })
            if dry_run:
                continue
            try:
                # Тот же богатый промпт, что и живой поиск / ленивое открытие — иначе ночной
                # добор оставлял бы карточки тонкими (только формы+примеры). Helper сам
                # ставит немецкое слово запросом (source=de) с пояснениями на родном, так что
                # изучаемый язык всегда цель — «der Zufall» получает немецкие примеры, не
                # русские, — и полный разбор уходит в общий пул для всех.
                enrich_data = _normalize_dictionary_enrich_payload(
                    _rich_enrich_card_fields(
                        source_text=source_text, target_text=target_text,
                        source_lang=row_source_lang, target_lang=row_target_lang,
                        timeout_seconds=POOL_NIGHT_ENRICH_TIMEOUT_SECONDS,
                    )
                )
                enrich_data = _drop_wrong_language_examples(enrich_data, learning_lang="de")
                if not enrich_data:
                    report["skipped"] += 1
                    report["skipped_empty"] += 1
                    if len(report["skipped_samples"]) < 15:
                        report["skipped_samples"].append({"word": source_text, "reason": "empty"})
                    mark_pool_entry_enrich_failed(row.get("id"), "empty")
                    continue
                merged = dict(row.get("response_json") or {})
                merged.update(enrich_data)
                merged = _prepare_dictionary_response_json_for_save(
                    response_json=merged,
                    source_text=source_text, target_text=target_text,
                    source_lang=row_source_lang, target_lang=row_target_lang,
                    word_ru=row.get("word_ru"), word_de=row.get("word_de"),
                    translation_de=row.get("translation_de"), translation_ru=row.get("translation_ru"),
                )
                # Если после обогащения карточка всё ещё тонкая — не пишем: пусть строка
                # останется кандидатом, а не притворяется полной.
                if _dictionary_payload_needs_enrichment(merged):
                    report["skipped"] += 1
                    report["skipped_thin"] += 1
                    if len(report["skipped_samples"]) < 15:
                        report["skipped_samples"].append({"word": source_text, "reason": "thin"})
                    mark_pool_entry_enrich_failed(row.get("id"), "thin")
                    continue
                _publish_enriched_card_to_shared_stores(
                    payload=merged, source_lang=row_source_lang, target_lang=row_target_lang,
                    source_text=source_text, target_text=target_text,
                )
                report["enriched"] += 1
            except Exception as exc:
                report["errors"] += 1
                logging.warning(
                    "pool night enrichment failed entry_id=%s word=%r error=%s",
                    row.get("id"), source_text, exc, exc_info=True,
                )
        try:
            report["remaining"] = count_thin_pool_entries(
                source_lang=source_lang, target_lang=target_lang,
            )
            if not _POOL_ENRICH_SINGLE_PAIR:
                report["remaining"] += count_thin_pool_entries(
                    source_lang=target_lang, target_lang=source_lang,
                )
        except Exception:
            report["remaining"] = 0
        return report
    finally:
        if not dry_run:
            with _POOL_NIGHT_ENRICH_LOCK:
                _POOL_NIGHT_ENRICH_RUNNING = False


_DICTIONARY_METAINFO_BACKFILL_LOCK = threading.Lock()
_DICTIONARY_METAINFO_BACKFILL_RUNNING = False


def _card_item_from_stored_raw_text(raw_text: str) -> dict:
    """Rebuild a full card from the model text we ALREADY paid for and stored.

    When the model's JSON did not parse, the save kept the whole answer in `raw_text` and
    wrote an empty stub next to it. The tolerant parser now reads that same text, so these
    cards are repairable for free — no second GPT call for something already answered."""
    from backend.openai_manager import parse_llm_json_object

    raw = parse_llm_json_object(raw_text, context="stored_raw_text_repair")
    if not isinstance(raw, dict) or not raw or raw.get("parse_failed"):
        return {}
    # Which side of the raw answer is German? Decide by SCRIPT, never by the row's stored
    # pair: the model answers German-first whatever direction was queried, and trusting the
    # stored pair is exactly what once produced «der Понос».
    word_source = str(raw.get("word_source") or "").strip()
    word_target = str(raw.get("word_target") or "").strip()
    if _CYRILLIC_RE.search(word_source) and word_target and not _CYRILLIC_RE.search(word_target):
        query_source_lang, query_target_lang = "ru", "de"
    else:
        query_source_lang, query_target_lang = "de", "ru"
    query_word = word_source or word_target
    if not query_word:
        return {}
    try:
        item, _direction, _detected, _sv, _tv = _build_dictionary_result_from_raw(
            raw=raw,
            query_word=query_word,
            source_lang=query_source_lang,
            target_lang=query_target_lang,
            query_source_lang=query_source_lang,
            query_target_lang=query_target_lang,
            lookup_lang="",
        )
    except Exception:
        logging.warning("raw_text card rebuild failed for %r", query_word, exc_info=True)
        return {}
    return item if isinstance(item, dict) else {}


def repair_dictionary_cards_from_raw_text(
    *,
    dry_run: bool = True,
    max_entries: int = 200,
    user_id: int | None = None,
    days: int | None = None,
    progress_cb=None,
) -> dict:
    """Free repair pass: empty cards whose model answer is already stored in `raw_text`.

    No GPT at all — we re-read the answer we paid for once, rebuild the card through the
    normal save pipeline (so the article backstop and the script guards run) and publish
    it to the shared stores. Cards that still come out thin are left for the paid
    enrichment; they are never overwritten with something worse than they had."""
    report = {
        "dry_run": bool(dry_run), "days": days,
        "scanned": 0, "repaired": 0, "unparsable": 0, "still_thin": 0,
        "errors": 0, "remaining": 0, "samples": [],
    }
    try:
        rows = get_dictionary_entries_with_stored_raw_text(
            user_id=user_id, limit=max_entries, days=days,
        )
    except Exception as exc:
        report["errors"] += 1
        report["error_detail"] = str(exc)
        return report

    for row in rows:
        report["scanned"] += 1
        response_json = row.get("response_json")
        if isinstance(response_json, str):
            try:
                response_json = json.loads(response_json)
            except Exception:
                response_json = {}
        if not isinstance(response_json, dict):
            response_json = {}
        source_lang = str(row.get("source_lang") or "de").strip().lower() or "de"
        target_lang = str(row.get("target_lang") or "ru").strip().lower() or "ru"
        german = str(row.get("word_de") or row.get("translation_de") or "").strip()
        try:
            rebuilt = _card_item_from_stored_raw_text(str(response_json.get("raw_text") or ""))
            if not rebuilt:
                report["unparsable"] += 1
                continue
            # No text hints on purpose: the row's OWN source_text/target_text carry its
            # direction (a ru→de row is «Родители» → «Eltern»), and the rebuilt card is
            # always German-first. Passing the German side as "source" would flip the pair.
            source_text, target_text = _resolve_entry_texts_for_pair(
                entry=row,
                response_json=response_json,
                source_lang=source_lang,
                target_lang=target_lang,
            )
            merged = dict(response_json)
            merged.update(_normalize_dictionary_enrich_payload(rebuilt))
            merged.pop("parse_failed", None)
            merged = _prepare_dictionary_response_json_for_save(
                response_json=merged,
                source_text=source_text,
                target_text=target_text,
                source_lang=source_lang,
                target_lang=target_lang,
                word_ru=str(row.get("word_ru") or merged.get("word_ru") or "").strip() or None,
                word_de=str(row.get("word_de") or merged.get("word_de") or "").strip() or None,
                translation_de=str(row.get("translation_de") or merged.get("translation_de") or "").strip() or None,
                translation_ru=str(row.get("translation_ru") or merged.get("translation_ru") or "").strip() or None,
            )
            if _dictionary_payload_needs_enrichment(merged):
                report["still_thin"] += 1
                continue
            if len(report["samples"]) < 25:
                # word_de уже НЕСЁТ артикль после нормализации заголовка («die Eltern»),
                # поэтому отдельным полем его не отдаём — иначе отчёт печатает «die die Eltern».
                report["samples"].append({
                    "id": row.get("id"),
                    "word": str(merged.get("word_de") or german),
                })
            if dry_run:
                report["repaired"] += 1
                continue
            update_webapp_dictionary_entry(int(row.get("id")), merged)
            _publish_enriched_card_to_shared_stores(
                payload=merged,
                source_lang=source_lang,
                target_lang=target_lang,
                source_text=source_text,
                target_text=target_text,
            )
            report["repaired"] += 1
            if progress_cb and report["repaired"] % 25 == 0:
                try:
                    progress_cb(report["repaired"], len(rows))
                except Exception:
                    pass
        except Exception as exc:
            report["errors"] += 1
            logging.warning(
                "raw_text card repair failed entry_id=%s word=%r error=%s",
                row.get("id"), german, exc, exc_info=True,
            )
    try:
        report["remaining"] = count_dictionary_entries_with_stored_raw_text(user_id=user_id, days=days)
    except Exception:
        report["remaining"] = 0
    return report


def backfill_dictionary_card_metainfo(
    *,
    dry_run: bool = True,
    max_entries: int = 200,
    user_id: int | None = None,
    days: int | None = None,
    progress_cb=None,
) -> dict:
    """Second repair pass: entries that DO have a translation but were stored without the
    card metainfo (no examples / grammar / senses — the empty detail screen). Those came
    from save paths that posted bare text with no response_json, so the save-time
    enrichment gate never fired. Re-runs the SAME enrichment the canonical save uses."""
    report = {
        "dry_run": bool(dry_run), "days": days,
        "scanned": 0, "empty_cards": 0, "enriched": 0, "errors": 0, "samples": [],
        "remaining": 0,
    }
    global _DICTIONARY_METAINFO_BACKFILL_RUNNING
    # Один вызов = один-два запроса к GPT В СЕКУНДУ в лучшем случае, поэтому повторный
    # запуск, пока идёт первый, просто удваивал бы трату токенов на те же слова.
    if not dry_run:
        with _DICTIONARY_METAINFO_BACKFILL_LOCK:
            if _DICTIONARY_METAINFO_BACKFILL_RUNNING:
                report["already_running"] = True
                report["remaining"] = count_dictionary_entries_missing_card(user_id=user_id, days=days)
                return report
            _DICTIONARY_METAINFO_BACKFILL_RUNNING = True
    try:
        return _run_dictionary_card_metainfo_backfill(
            report=report, dry_run=dry_run, max_entries=max_entries,
            user_id=user_id, days=days, progress_cb=progress_cb,
        )
    finally:
        if not dry_run:
            with _DICTIONARY_METAINFO_BACKFILL_LOCK:
                _DICTIONARY_METAINFO_BACKFILL_RUNNING = False


def _run_dictionary_card_metainfo_backfill(
    *, report: dict, dry_run: bool, max_entries: int, user_id: int | None,
    days: int | None, progress_cb=None,
) -> dict:
    try:
        rows = get_dictionary_entries_for_metainfo_scan(user_id=user_id, limit=max_entries, days=days)
    except Exception as exc:
        report["errors"] += 1
        report["error_detail"] = str(exc)
        return report

    for row in rows:
        report["scanned"] += 1
        response_json = row.get("response_json")
        if isinstance(response_json, str):
            try:
                response_json = json.loads(response_json)
            except Exception:
                response_json = {}
        if not isinstance(response_json, dict):
            response_json = {}
        source_lang = str(row.get("source_lang") or "de").strip().lower() or "de"
        target_lang = str(row.get("target_lang") or "ru").strip().lower() or "ru"
        german = str(row.get("word_de") or row.get("translation_de") or "").strip()
        if not _dictionary_payload_needs_enrichment(response_json):
            continue
        if not _is_single_word_dictionary_entry(german, "de"):
            continue
        report["empty_cards"] += 1
        if len(report["samples"]) < 25:
            report["samples"].append({"id": row.get("id"), "german": german})
        if dry_run:
            continue
        try:
            _run_saved_dictionary_entry_enrichment(
                entry_id=int(row.get("id")),
                source_lang=source_lang,
                target_lang=target_lang,
                source_text_hint=german,
                target_text_hint=str(row.get("translation_ru") or ""),
            )
            report["enriched"] += 1
            # Прогресс наружу: проход идёт минуты-часы, и молчащая команда неотличима
            # от зависшей (ровно так и выглядело 21.07).
            if progress_cb and report["enriched"] % 25 == 0:
                try:
                    progress_cb(report["enriched"], report["empty_cards"])
                except Exception:
                    pass
        except Exception as exc:
            report["errors"] += 1
            logging.warning(
                "dictionary metainfo backfill failed entry_id=%s german=%r error=%s",
                row.get("id"), german, exc, exc_info=True,
            )
    try:
        report["remaining"] = count_dictionary_entries_missing_card(user_id=user_id, days=days)
    except Exception:
        report["remaining"] = 0
    return report


def _start_saved_dictionary_entry_enrichment(
    *,
    entry_id: int,
    response_json: dict | None,
    source_lang: str,
    target_lang: str,
    source_text_hint: str,
    target_text_hint: str,
    force: bool = False,
) -> None:
    safe_entry_id = int(entry_id or 0)
    if safe_entry_id <= 0:
        return
    payload = response_json if isinstance(response_json, dict) else {}
    if not force and not _dictionary_payload_needs_enrichment(payload):
        return
    with _DICTIONARY_SAVE_ENRICHMENT_LOCK:
        if safe_entry_id in _DICTIONARY_SAVE_ENRICHMENT_INFLIGHT:
            return
        _DICTIONARY_SAVE_ENRICHMENT_INFLIGHT.add(safe_entry_id)
    threading.Thread(
        target=_run_saved_dictionary_entry_enrichment,
        kwargs={
            "entry_id": safe_entry_id,
            "source_lang": source_lang,
            "target_lang": target_lang,
            "source_text_hint": source_text_hint,
            "target_text_hint": target_text_hint,
            "force": bool(force),
        },
        daemon=True,
        name=f"dictionary-save-enrich-{safe_entry_id}",
    ).start()


def _is_legacy_ru_de_pair(source_lang: str, target_lang: str) -> bool:
    return source_lang == "ru" and target_lang == "de"


def _get_local_today_date(tz_name: str = TODAY_PLAN_DEFAULT_TZ) -> date:
    try:
        return datetime.now(ZoneInfo(tz_name)).date()
    except Exception:
        return datetime.utcnow().date()


def _safe_plan_date(raw: str | None, tz_name: str = TODAY_PLAN_DEFAULT_TZ) -> date:
    if not raw:
        return _get_local_today_date(tz_name)
    try:
        return datetime.fromisoformat(str(raw)).date()
    except Exception:
        return _get_local_today_date(tz_name)


def _today_cards_item_payload(
    *,
    due_count: int,
    has_new_candidates: bool,
) -> tuple[dict | None, int]:
    if due_count > 0:
        limit = max(10, min(20, int(due_count)))
        minutes = 10 if limit <= 15 else 15
        return (
            {
                "task_type": "cards",
                "title": "Карточки: повторение",
                "estimated_minutes": minutes,
                "payload": {"mode": "fsrs_due", "limit": limit, "due_total": int(due_count)},
                "status": "todo",
            },
            minutes,
        )
    if has_new_candidates:
        return (
            {
                "task_type": "cards",
                "title": "Карточки: новые слова",
                "estimated_minutes": 10,
                "payload": {"mode": "cards_new", "limit": 10},
                "status": "todo",
            },
            10,
        )
    return None, 0


def _compute_srs_queue_info(
    *,
    user_id: int,
    now_utc: datetime,
    source_lang: str,
    target_lang: str,
    queue_source: str = "system",
    allowed_card_ids: list[int] | None = None,
    cursor=None,
) -> dict:
    due_count_total = count_due_srs_cards(
        user_id=user_id,
        now_utc=now_utc,
        source_lang=source_lang,
        target_lang=target_lang,
        allowed_card_ids=allowed_card_ids,
        # Manual selection narrows the candidate set, but it must still respect
        # each card's next due timestamp after the user rates it.
        bypass_due_at=False,
        cursor=cursor,
    )
    introduced_today = count_new_cards_introduced_today(
        user_id=user_id,
        now_utc=now_utc,
        source_lang=source_lang,
        target_lang=target_lang,
        allowed_card_ids=allowed_card_ids,
        cursor=cursor,
    )
    due_reviewed_today = count_due_cards_reviewed_today(
        user_id=user_id,
        now_utc=now_utc,
        source_lang=source_lang,
        target_lang=target_lang,
        allowed_card_ids=allowed_card_ids,
        cursor=cursor,
    )
    has_new_candidates = has_available_new_srs_cards(
        user_id=user_id,
        source_lang=source_lang,
        target_lang=target_lang,
        allowed_card_ids=allowed_card_ids,
        cursor=cursor,
    )
    # Daily cap: show at most SRS_DUE_PER_DAY cards per day.
    # In manual mode the UI should reflect the selected subset size, not the
    # global system cap of 30 cards.
    is_manual = bool(allowed_card_ids)
    due_limit_today = len(allowed_card_ids) if is_manual else SRS_DUE_PER_DAY
    due_remaining_today = max(0, due_limit_today - due_reviewed_today)
    due_count = min(due_count_total, due_remaining_today)
    # In manual-selection mode use the selection size as the cap; also skip the
    # backlog-blocking condition so freshly selected words are always learnable.
    effective_new_cap = len(allowed_card_ids) if is_manual else NEW_PER_DAY
    new_remaining_today = max(effective_new_cap - introduced_today, 0)
    if not is_manual and due_count_total > SRS_DUE_PER_DAY * 2:
        new_remaining_today = 0
    if not has_new_candidates and not is_manual:
        # A live subscriber can still draw new cards from the admin's dictionary once their own
        # new words run out — count that so the daily new budget isn't zeroed. Fail-safe/cheap.
        try:
            _sub_state = get_starter_dictionary_state(user_id, cursor=cursor)
            if _sub_state.get("live_subscription") and has_admin_subscription_available(
                user_id=user_id,
                source_user_id=STARTER_DICTIONARY_SOURCE_USER_ID,
                source_lang=source_lang,
                target_lang=target_lang,
                cursor=cursor,
            ):
                has_new_candidates = True
        except Exception as _sub_e:
            logging.warning("subscription availability check skipped: %s", _sub_e)
    new_remaining_today = new_remaining_today if has_new_candidates else 0
    return {
        "queue_source": _normalize_flashcards_queue_source(queue_source),
        "due_count": int(due_count),
        "due_count_total": int(due_count_total),
        "due_reviewed_today": int(due_reviewed_today),
        "due_limit_today": int(due_limit_today),
        "new_remaining_today": int(new_remaining_today),
        "introduced_today": int(introduced_today),
        "available_new_total": int(1 if has_new_candidates else 0),
    }


def _build_srs_review_preview(*, current_state: dict | None, reviewed_at: datetime) -> dict:
    if reviewed_at.tzinfo is None:
        reviewed_at = reviewed_at.replace(tzinfo=timezone.utc)
    preview: dict[str, dict] = {}
    for rating_key in ("AGAIN", "HARD", "GOOD", "EASY"):
        try:
            scheduled, _canonical_rating = schedule_review(
                current_state=current_state,
                rating=rating_key,
                reviewed_at=reviewed_at,
            )
            due_at = scheduled.due_at
            if due_at.tzinfo is None:
                due_at = due_at.replace(tzinfo=timezone.utc)
            seconds = max(0, int((due_at - reviewed_at).total_seconds()))
            preview[rating_key] = {
                "seconds": int(seconds),
                "interval_days": int(scheduled.interval_days or 0),
                "due_at": due_at.isoformat(),
            }
        except Exception:
            logging.debug("Failed to build SRS preview for %s", rating_key, exc_info=True)
    return preview


def _list_srs_queue_cards(
    *,
    user_id: int,
    now_utc: datetime,
    source_lang: str,
    target_lang: str,
    limit: int,
    folder_mode: str = "all",
    folder_id: int | None = None,
    queue_source: str = "system",
    allowed_card_ids: list[int] | None = None,
    exclude_recent_seen: bool = False,
    cursor=None,
) -> tuple[list[dict], dict]:
    safe_limit = max(1, int(limit or 1))
    normalized_folder_mode = str(folder_mode or "all").strip().lower()
    normalized_queue_source = _normalize_flashcards_queue_source(queue_source)
    normalized_allowed_ids = [int(card_id) for card_id in (allowed_card_ids or []) if int(card_id) > 0]
    if allowed_card_ids is not None and not normalized_allowed_ids:
        return [], {
            "selection_strategy": "manual_subset_empty",
            "queue_source": normalized_queue_source,
            "folder_mode": normalized_folder_mode,
            "exclude_recent_seen": bool(exclude_recent_seen),
            "recent_seen_hours": int(FLASHCARD_RECENT_SEEN_HOURS),
            "due_count": 0,
            "due_selected": 0,
            "due_selected_recent_filtered": 0,
            "due_fallback_selected": 0,
            "new_remaining_today": 0,
            "new_selected": 0,
            "new_selected_recent_filtered": 0,
            "new_fallback_selected": 0,
            "returned_items": 0,
            "manual_selected_count": 0,
        }

    def _fetch(cur) -> tuple[list[dict], dict]:
        folder_filter_sql = ""
        folder_params: list[object] = []
        if normalized_folder_mode == "folder" and folder_id is not None:
            folder_filter_sql = " AND q.folder_id = %s"
            folder_params.append(int(folder_id))
        elif normalized_folder_mode == "none":
            folder_filter_sql = " AND q.folder_id IS NULL"
        allowed_filter_sql = " AND q.id = ANY(%s::bigint[])" if normalized_allowed_ids else ""
        allowed_filter_params: list[object] = [normalized_allowed_ids] if normalized_allowed_ids else []

        # Skip language pair filter in manual mode: user-selected cards may have any direction.
        if normalized_allowed_ids:
            lang_filter_sql = ""
            lang_params: list[object] = []
        else:
            # BOTH directions of the {de,ru} pair — de→ru and ru→de are the same German↔Russian
            # vocabulary, so a learner trains all of it (the card renderer normalizes each to the
            # «Russian → German» format). Was one-directional, which left half the words untrained.
            lang_filter_sql = (
                "AND ((q.source_lang = %s AND q.target_lang = %s)"
                " OR (q.source_lang = %s AND q.target_lang = %s))"
            )
            lang_params = [source_lang, target_lang, target_lang, source_lang]
        base_params = [int(user_id), *lang_params]
        recent_seen_cutoff = now_utc - timedelta(hours=FLASHCARD_RECENT_SEEN_HOURS)
        recent_seen_sql = (
            " AND q.id NOT IN ("
            " SELECT entry_id"
            " FROM bt_3_flashcard_seen"
            " WHERE user_id = %s"
            "   AND seen_at >= %s"
            " )"
        )
        recent_seen_params = [int(user_id), recent_seen_cutoff]
        due_filter_sql = "AND s.due_at <= %s"
        due_params: list[object] = [now_utc]
        due_count = 0
        due_rows: list[tuple] = []
        due_selected_ids: set[int] = set()
        due_fallback_added = 0

        cur.execute(
            f"""
            SELECT COUNT(*)
            FROM bt_3_card_srs_state s
            JOIN bt_3_webapp_dictionary_queries q
              ON q.id = s.card_id
             AND q.user_id = s.user_id
            WHERE s.user_id = %s
              {lang_filter_sql}
              AND s.status <> 'suspended'
              {due_filter_sql}
              AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
              {folder_filter_sql}
              {allowed_filter_sql};
            """,
            [*base_params, *due_params, *folder_params, *allowed_filter_params],
        )
        count_row = cur.fetchone()
        due_count = int(count_row[0] if count_row else 0)

        due_limit = min(due_count, safe_limit)
        if due_limit > 0:
            cur.execute(
                f"""
                SELECT
                    s.card_id,
                    q.word_ru,
                    q.translation_de,
                    q.word_de,
                    q.translation_ru,
                    q.response_json,
                    q.source_lang,
                    q.target_lang,
                    s.status,
                    s.due_at,
                    s.interval_days,
                    s.stability,
                    s.difficulty
                FROM bt_3_card_srs_state s
                JOIN bt_3_webapp_dictionary_queries q
                  ON q.id = s.card_id
                 AND q.user_id = s.user_id
                WHERE s.user_id = %s
                  {lang_filter_sql}
                  AND s.status <> 'suspended'
                  {due_filter_sql}
                  AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
                  {recent_seen_sql if exclude_recent_seen else ""}
                  {folder_filter_sql}
                  {allowed_filter_sql}
                ORDER BY s.due_at ASC
                LIMIT %s;
                """,
                [
                    *base_params,
                    *due_params,
                    *(recent_seen_params if exclude_recent_seen else []),
                    *folder_params,
                    *allowed_filter_params,
                    int(due_limit),
                ],
            )
            due_rows = list(cur.fetchall() or [])
            due_selected_ids = {int(row[0]) for row in due_rows}

            if exclude_recent_seen and len(due_rows) < due_limit:
                cur.execute(
                    f"""
                    SELECT
                        s.card_id,
                        q.word_ru,
                        q.translation_de,
                        q.word_de,
                        q.translation_ru,
                        q.response_json,
                        q.source_lang,
                        q.target_lang,
                        s.status,
                        s.due_at,
                        s.interval_days,
                        s.stability,
                        s.difficulty
                    FROM bt_3_card_srs_state s
                    JOIN bt_3_webapp_dictionary_queries q
                      ON q.id = s.card_id
                     AND q.user_id = s.user_id
                    WHERE s.user_id = %s
                      {lang_filter_sql}
                      AND s.status <> 'suspended'
                      {due_filter_sql}
                      AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
                      AND s.card_id <> ALL(%s::bigint[])
                      {folder_filter_sql}
                      {allowed_filter_sql}
                    ORDER BY s.due_at ASC
                    LIMIT %s;
                    """,
                    [
                        *base_params,
                        *due_params,
                        list(due_selected_ids) or [0],
                        *folder_params,
                        *allowed_filter_params,
                        int(due_limit - len(due_rows)),
                    ],
                )
                fallback_due_rows = list(cur.fetchall() or [])
                due_rows.extend(fallback_due_rows)
                due_selected_ids.update(int(row[0]) for row in fallback_due_rows)
                due_fallback_added = len(fallback_due_rows)

        introduced_today = count_new_cards_introduced_today(
            user_id=user_id,
            now_utc=now_utc,
            source_lang=source_lang,
            target_lang=target_lang,
            allowed_card_ids=normalized_allowed_ids if normalized_allowed_ids else allowed_card_ids,
            cursor=cur,
        )
        _effective_new_cap = len(normalized_allowed_ids or allowed_card_ids or []) or NEW_PER_DAY
        new_remaining_today = max(_effective_new_cap - int(introduced_today or 0), 0)
        remaining_slots = max(0, safe_limit - len(due_rows))
        new_limit = min(new_remaining_today, remaining_slots)
        new_rows: list[tuple] = []
        new_selected_ids: set[int] = set()
        new_fallback_added = 0

        if new_limit > 0:
            # Reserve a slice of the daily new-card budget for the OLDEST saved
            # words regardless of frequency_rank (#6): otherwise un-ranked / rare
            # words sit permanently behind the frequency queue and never surface.
            aged_quota = (new_limit // SRS_NEW_AGED_RESERVE_EVERY) if SRS_NEW_AGED_RESERVE_EVERY and new_limit >= SRS_NEW_AGED_RESERVE_EVERY else 0
            # Квота фраз: каждая третья новая карточка — выражение или предложение (решение
            # владельца). Без неё фразы лежат мёртвым грузом: частотный ранг есть только у
            # одиночных слов, поэтому фразы всегда проигрывают в сортировке по нужности.
            # Признак посчитан при сохранении — здесь это обычный отбор по колонке.
            try:
                _w_left, _p_left = count_remaining_new_stock(
                    user_id=user_id, source_lang=source_lang, target_lang=target_lang, cursor=cur,
                )
                _phrase_share = (_p_left / float(_w_left + _p_left)) if (_w_left + _p_left) else 0.0
            except Exception:
                logging.debug("не удалось посчитать состав остатка uid=%s", user_id, exc_info=True)
                _phrase_share = 0.0
            phrase_quota = int(new_limit * _phrase_share) if new_limit > 0 else 0
            if phrase_quota > 0:
                cur.execute(
                    f"""
                    SELECT
                        q.id, q.word_ru, q.translation_de, q.word_de,
                        q.translation_ru, q.response_json, q.source_lang, q.target_lang, q.frequency_rank
                    FROM bt_3_webapp_dictionary_queries q
                    LEFT JOIN bt_3_card_srs_state s
                      ON s.user_id = q.user_id AND s.card_id = q.id
                    WHERE q.user_id = %s
                      {lang_filter_sql}
                      AND s.id IS NULL
                      AND q.is_phrase IS TRUE
                      AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
                      {recent_seen_sql if exclude_recent_seen else ""}
                      {folder_filter_sql}
                      {allowed_filter_sql}
                    ORDER BY q.frequency_rank ASC NULLS LAST, q.created_at ASC
                    LIMIT %s;
                    """,
                    [
                        *base_params,
                        *(recent_seen_params if exclude_recent_seen else []),
                        *folder_params,
                        *allowed_filter_params,
                        int(phrase_quota),
                    ],
                )
                phrase_rows = list(cur.fetchall() or [])
                new_rows.extend(phrase_rows)
                new_selected_ids.update(int(row[0]) for row in phrase_rows)
            if aged_quota > 0:
                cur.execute(
                    f"""
                    SELECT
                        q.id, q.word_ru, q.translation_de, q.word_de,
                        q.translation_ru, q.response_json, q.source_lang, q.target_lang, q.frequency_rank
                    FROM bt_3_webapp_dictionary_queries q
                    LEFT JOIN bt_3_card_srs_state s
                      ON s.user_id = q.user_id AND s.card_id = q.id
                    WHERE q.user_id = %s
                      {lang_filter_sql}
                      AND s.id IS NULL
                      AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
                      {recent_seen_sql if exclude_recent_seen else ""}
                      {folder_filter_sql}
                      {allowed_filter_sql}
                    ORDER BY q.created_at ASC
                    LIMIT %s;
                    """,
                    [
                        *base_params,
                        *(recent_seen_params if exclude_recent_seen else []),
                        *folder_params,
                        *allowed_filter_params,
                        int(aged_quota),
                    ],
                )
                aged_rows = list(cur.fetchall() or [])
                new_rows.extend(aged_rows)
                new_selected_ids.update(int(row[0]) for row in aged_rows)

            freq_stage_ids: set[int] = set()
            freq_limit = new_limit - len(new_rows)
            if freq_limit > 0:
                cur.execute(
                    f"""
                    SELECT
                        q.id, q.word_ru, q.translation_de, q.word_de,
                        q.translation_ru, q.response_json, q.source_lang, q.target_lang, q.frequency_rank
                    FROM bt_3_webapp_dictionary_queries q
                    LEFT JOIN bt_3_card_srs_state s
                      ON s.user_id = q.user_id AND s.card_id = q.id
                    WHERE q.user_id = %s
                      {lang_filter_sql}
                      AND s.id IS NULL
                      AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
                      AND q.id <> ALL(%s::bigint[])
                      {recent_seen_sql if exclude_recent_seen else ""}
                      {folder_filter_sql}
                      {allowed_filter_sql}
                    ORDER BY q.frequency_rank ASC NULLS LAST, q.created_at ASC
                    LIMIT %s;
                    """,
                    [
                        *base_params,
                        list(new_selected_ids) or [0],
                        *(recent_seen_params if exclude_recent_seen else []),
                        *folder_params,
                        *allowed_filter_params,
                        int(freq_limit),
                    ],
                )
                freq_rows = list(cur.fetchall() or [])
                new_rows.extend(freq_rows)
                new_selected_ids.update(int(row[0]) for row in freq_rows)
                # Эти строки отобраны по частотности — именно они соревнуются со словами
                # подписки. Резерв «самое старое» (aged) в соревновании не участвует: он
                # существует ровно для того, чтобы неранжированные слова не голодали.
                freq_stage_ids.update(int(row[0]) for row in freq_rows)

            if exclude_recent_seen and len(new_rows) < new_limit:
                cur.execute(
                    f"""
                    SELECT
                        q.id,
                        q.word_ru,
                        q.translation_de,
                        q.word_de,
                        q.translation_ru,
                        q.response_json,
                        q.source_lang,
                        q.target_lang,
                        q.frequency_rank
                    FROM bt_3_webapp_dictionary_queries q
                    LEFT JOIN bt_3_card_srs_state s
                      ON s.user_id = q.user_id
                     AND s.card_id = q.id
                    WHERE q.user_id = %s
                      {lang_filter_sql}
                      AND s.id IS NULL
                      AND COALESCE(q.response_json->>'sentence_origin', '') <> 'gpt_seed'
                      AND q.id <> ALL(%s::bigint[])
                      {folder_filter_sql}
                      {allowed_filter_sql}
                    ORDER BY q.frequency_rank ASC NULLS LAST, q.created_at ASC
                    LIMIT %s;
                    """,
                    [
                        *base_params,
                        list(new_selected_ids) or [0],
                        *folder_params,
                        *allowed_filter_params,
                        int(new_limit - len(new_rows)),
                    ],
                )
                fallback_new_rows = list(cur.fetchall() or [])
                new_rows.extend(fallback_new_rows)
                new_selected_ids.update(int(row[0]) for row in fallback_new_rows)
                new_fallback_added = len(fallback_new_rows)

        # ЕДИНАЯ очередь в буфере: слово из подписки соревнуется со своими по нужности.
        # Раньше подписка добирала только свободные места — а они не пустовали никогда,
        # потому что у каждого лежала тысяча своих слов. Итог: ноль выданных слов за всё
        # время существования подписки. Теперь она (а) занимает свободные места и
        # (б) вытесняет своё слово, если её слово нужнее. Вытесненное никуда не пропадает —
        # оно остаётся в словаре человека и придёт в следующий раз. Резерв «самое старое»
        # и ручной отбор не трогаем: там выбор осознанный.
        if new_limit > 0 and not normalized_allowed_ids and not allowed_card_ids:
            try:
                _sub_state = get_starter_dictionary_state(user_id, cursor=cur) or {}
                _sub_cap = _sub_state.get("subscription_limit")
                _sub_delivered = (
                    count_subscription_delivered(user_id, cursor=cur)
                    if (_sub_state.get("live_subscription") and _sub_cap) else 0
                )
                _cap_left = (max(0, int(_sub_cap) - _sub_delivered) if _sub_cap else None)
                if _sub_state.get("live_subscription") and _cap_left != 0:
                    def _rank_of(row):
                        value = row[8] if len(row) > 8 else None
                        return float(value) if value is not None else float("inf")

                    _taken_now = 0
                    while True:
                        if _cap_left is not None and _taken_now >= _cap_left:
                            break
                        _free_slot = len(new_rows) < new_limit
                        _worst_own = None
                        if not _free_slot:
                            _own_in_play = [r for r in new_rows if int(r[0]) in freq_stage_ids]
                            if _own_in_play:
                                _worst_own = max(_own_in_play, key=_rank_of)
                            if _worst_own is None:
                                break
                        _peek = list_admin_subscription_new_candidates(
                            user_id=user_id,
                            source_user_id=STARTER_DICTIONARY_SOURCE_USER_ID,
                            source_lang=source_lang,
                            target_lang=target_lang,
                            limit=1,
                            cursor=cur,
                        )
                        if not _peek:
                            break
                        _sub_rank_raw = _peek[0].get("frequency_rank")
                        _sub_rank = float(_sub_rank_raw) if _sub_rank_raw is not None else float("inf")
                        if not _free_slot and _sub_rank >= _rank_of(_worst_own):
                            break
                        _mid = materialize_subscription_card(
                            user_id=user_id,
                            source_user_id=STARTER_DICTIONARY_SOURCE_USER_ID,
                            source_lang=source_lang,
                            target_lang=target_lang,
                            cursor=cur,
                        )
                        if not _mid:
                            break
                        invalidate_subscription_peek_cache(user_id)
                        cur.execute(
                            """
                            SELECT q.id, q.word_ru, q.translation_de, q.word_de,
                                   q.translation_ru, q.response_json, q.source_lang, q.target_lang,
                                   q.frequency_rank
                            FROM bt_3_webapp_dictionary_queries q
                            WHERE q.id = %s AND q.user_id = %s
                            LIMIT 1;
                            """,
                            (int(_mid), int(user_id)),
                        )
                        _r = cur.fetchone()
                        if not _r or int(_r[0]) in new_selected_ids:
                            break
                        if not _free_slot and _worst_own is not None:
                            new_rows.remove(_worst_own)
                            new_selected_ids.discard(int(_worst_own[0]))
                            freq_stage_ids.discard(int(_worst_own[0]))
                        new_rows.append(_r)
                        new_selected_ids.add(int(_r[0]))
                        _taken_now += 1
            except Exception as _sub_e:
                logging.warning("subscription queue merge (prefetch) skipped: %s", _sub_e)

        # One card per German word: drop NEW rows whose German is already being trained in the
        # other direction, and collapse within-batch twins. Post-filtered in Python (the buffer is
        # tiny) to avoid a slow per-row SQL subquery. Non-manual mode only; DUE cards untouched.
        if new_rows and not normalized_allowed_ids and not allowed_card_ids:
            try:
                _trained_de = set(_trained_german_word_keys(cur, int(user_id)))
            except Exception:
                _trained_de = set()
            _seen_de: set[str] = set()
            _deduped_new: list = []
            for _r in new_rows:
                _k = str(_r[3] or "").strip().lower()
                if _k and (_k in _trained_de or _k in _seen_de):
                    continue
                if _k:
                    _seen_de.add(_k)
                _deduped_new.append(_r)
            new_rows = _deduped_new

        items: list[dict] = []
        for row in due_rows:
            items.append(
                {
                    "id": row[0],
                    "word_ru": row[1],
                    "translation_de": row[2],
                    "word_de": row[3],
                    "translation_ru": row[4],
                    "response_json": row[5],
                    "source_lang": row[6],
                    "target_lang": row[7],
                    "srs": {
                        "status": row[8],
                        "due_at": row[9],
                        "interval_days": int(row[10] or 0),
                        "stability": float(row[11] or 0.0),
                        "difficulty": float(row[12] or 0.0),
                    },
                }
            )
        for row in new_rows:
            items.append(
                {
                    "id": row[0],
                    "word_ru": row[1],
                    "translation_de": row[2],
                    "word_de": row[3],
                    "translation_ru": row[4],
                    "response_json": row[5],
                    "source_lang": row[6],
                    "target_lang": row[7],
                    "srs": None,
                }
            )

        # Разбор берём с ОБЩЕГО СЛОВА, как и все остальные экраны.
        #
        # До 14.08.2026 этот путь был единственным, который этого НЕ делал: он отдавал
        # человеку только его собственный снимок разбора, снятый в момент подписки.
        # А это главный экран учёбы — тренировка и предзагрузка карточек. Получалось,
        # что владелец правит слово в словаре, все прочие экраны правку показывают, а
        # ровно тот экран, где человек учит, продолжает показывать копию.
        # Замер 14.08.2026: у 1607 карточек собственный снимок расходится с общим словом,
        # и у всех 1607 слово улучшали ПОСЛЕ того, как снимок сняли (в среднем на 105 дней
        # позже). Правило то же, что везде: только дополняем, и только если слово про это же.
        try:
            from backend.database import attach_unit_content_to_cards

            attach_unit_content_to_cards(items)
        except Exception:
            logging.debug("разбор с общего слова не подтянулся в очередь", exc_info=True)

        diagnostics = {
            "selection_strategy": "manual_subset_queue" if normalized_queue_source == "manual" else "fsrs_core_queue",
            "queue_source": normalized_queue_source,
            "folder_mode": normalized_folder_mode,
            "exclude_recent_seen": bool(exclude_recent_seen),
            "recent_seen_hours": int(FLASHCARD_RECENT_SEEN_HOURS),
            "due_count": int(due_count),
            "due_selected": len(due_rows),
            "due_selected_recent_filtered": max(0, len(due_rows) - due_fallback_added),
            "due_fallback_selected": int(due_fallback_added),
            "new_remaining_today": int(new_remaining_today),
            "new_selected": len(new_rows),
            "new_selected_recent_filtered": max(0, len(new_rows) - new_fallback_added),
            "new_fallback_selected": int(new_fallback_added),
            "returned_items": len(items),
            "manual_selected_count": len(normalized_allowed_ids),
        }
        return items, diagnostics

    if cursor is not None:
        return _fetch(cursor)
    with get_db_connection_context() as conn:
        with conn.cursor() as own_cursor:
            return _fetch(own_cursor)


def _build_next_srs_payload(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    now_utc: datetime,
    queue_source: str = "system",
    allowed_card_ids: list[int] | None = None,
    include_queue_info: bool = True,
    cursor=None,
) -> dict:
    normalized_queue_source = _normalize_flashcards_queue_source(queue_source)
    due_payload = get_next_due_srs_card(
        user_id=user_id,
        now_utc=now_utc,
        source_lang=source_lang,
        target_lang=target_lang,
        allowed_card_ids=allowed_card_ids,
        # In manual mode we still honor due_at for cards that have already been
        # reviewed; otherwise a short custom list loops immediately regardless
        # of the chosen rating.
        bypass_due_at=False,
        cursor=cursor,
    )
    card_payload = None
    srs_payload = None
    srs_state_for_preview = None
    queue_info: dict | None = None

    if include_queue_info:
        queue_info = _compute_srs_queue_info(
            user_id=user_id,
            now_utc=now_utc,
            source_lang=source_lang,
            target_lang=target_lang,
            queue_source=queue_source,
            allowed_card_ids=allowed_card_ids,
            cursor=cursor,
        )

    if due_payload:
        card_payload = due_payload.get("card")
        srs_payload = due_payload.get("srs")
        if isinstance(srs_payload, dict):
            srs_state_for_preview = {
                "status": srs_payload.get("status") or "new",
                "due_at": srs_payload.get("due_at"),
                "last_review_at": srs_payload.get("last_review_at"),
                "interval_days": int(srs_payload.get("interval_days") or 0),
                "reps": int(srs_payload.get("reps") or 0),
                "lapses": int(srs_payload.get("lapses") or 0),
                "stability": float(srs_payload.get("stability") or 0.0),
                "difficulty": float(srs_payload.get("difficulty") or 0.0),
                "step": int(srs_payload.get("step") or 0),
            }
    else:
        _cap = len(allowed_card_ids) if allowed_card_ids else NEW_PER_DAY
        if include_queue_info:
            _remaining = int(queue_info.get("new_remaining_today") or 0)
            introduced_today = max(_cap - _remaining, 0)
            can_take_new = _remaining > 0
        else:
            introduced_today = count_new_cards_introduced_today(
                user_id=user_id,
                now_utc=now_utc,
                source_lang=source_lang,
                target_lang=target_lang,
                allowed_card_ids=allowed_card_ids,
                cursor=cursor,
            )
            can_take_new = max(_cap - int(introduced_today or 0), 0) > 0
        if can_take_new:
            # Every Nth introduced new card is age-first (the #6 reserve), so the
            # single-card path doesn't starve un-ranked words either.
            prefer_oldest = bool(SRS_NEW_AGED_RESERVE_EVERY) and (
                (int(introduced_today or 0) + 1) % SRS_NEW_AGED_RESERVE_EVERY == 0
            )
            # Состав выдачи повторяет состав ОСТАТКА: сколько у человека фраз — столько же
            # и в выдаче. Без этого фразы не всплывают вообще: частотный ранг есть только у
            # одиночных слов, а фраз в словарях вдвое больше.
            _phrase_turn = False
            if not prefer_oldest:
                try:
                    _words_left, _phrases_left = count_remaining_new_stock(
                        user_id=user_id, source_lang=source_lang, target_lang=target_lang, cursor=cursor,
                    )
                    _phrase_turn = is_phrase_turn(
                        introduced_today=int(introduced_today or 0),
                        words_left=_words_left,
                        phrases_left=_phrases_left,
                    )
                except Exception:
                    logging.debug("не удалось посчитать состав остатка uid=%s", user_id, exc_info=True)
            # Единая очередь: своё слово и слово из подписки соревнуются по нужности, а не
            # «подписка включается, когда свои кончились» (при таком порядке она не отдала
            # ни одного слова за всё время — у каждого лежала тысяча своих).
            _sub_state: dict = {}
            try:
                _sub_state = get_starter_dictionary_state(user_id, cursor=cursor) or {}
                _live_sub = bool(_sub_state.get("live_subscription"))
            except Exception:
                _live_sub = False
            candidate = get_next_new_srs_candidate_with_subscription(
                user_id=user_id,
                source_user_id=STARTER_DICTIONARY_SOURCE_USER_ID,
                source_lang=source_lang,
                target_lang=target_lang,
                allowed_card_ids=allowed_card_ids,
                cursor=cursor,
                prefer_oldest=prefer_oldest,
                live_subscription=_live_sub,
                subscription_limit=_sub_state.get("subscription_limit") if _live_sub else None,
                phrases_only=_phrase_turn,
            )
            if candidate:
                state = ensure_new_srs_state(
                    user_id=user_id,
                    card_id=int(candidate["id"]),
                    now_utc=now_utc,
                    cursor=cursor,
                )
                card_payload = candidate
                srs_payload = {
                    "status": state.get("status") or "new",
                    "due_at": state.get("due_at"),
                    "interval_days": int(state.get("interval_days") or 0),
                    "stability": float(state.get("stability") or 0.0),
                    "difficulty": float(state.get("difficulty") or 0.0),
                }
                srs_state_for_preview = state

    queue_payload = None
    if isinstance(queue_info, dict):
        queue_payload = {
            "due_count": int(queue_info.get("due_count") or 0),
            "new_remaining_today": int(queue_info.get("new_remaining_today") or 0),
            "due_count_total": int(queue_info.get("due_count_total") or 0),
            "due_reviewed_today": int(queue_info.get("due_reviewed_today") or 0),
            "due_limit_today": int(queue_info.get("due_limit_today") or 30),
            "introduced_today": int(queue_info.get("introduced_today") or 0),
        }

    if not card_payload:
        return {
            "queue_source": normalized_queue_source,
            "card": None,
            "srs": None,
            "srs_preview": None,
            "queue_info": queue_payload,
        }

    due_at = srs_payload.get("due_at")
    due_iso = due_at.isoformat() if hasattr(due_at, "isoformat") else None
    interval_days = int(srs_payload.get("interval_days") or 0)
    srs_response = {
        "status": srs_payload.get("status") or "new",
        "due_at": due_iso,
        "interval_days": interval_days,
        "stability": float(srs_payload.get("stability") or 0.0),
        "difficulty": float(srs_payload.get("difficulty") or 0.0),
        "is_mature": interval_days >= MATURE_INTERVAL_DAYS,
    }
    srs_preview = _build_srs_review_preview(
        current_state=srs_state_for_preview,
        reviewed_at=now_utc,
    )
    # Заметки человека и разбор с единицы — здесь, на общем выходе очереди. Внутри
    # карточка приходит двумя путями (по сроку и новая из подписки), и обвешивать каждый
    # значило бы забыть про третий, который появится завтра.
    if isinstance(card_payload, dict) and card_payload:
        attach_unit_content_to_cards([card_payload])
    card_response = _decorate_training_dictionary_item(
        card_payload if isinstance(card_payload, dict) else {},
        source_lang=source_lang,
        target_lang=target_lang,
        direction=f"{source_lang}-{target_lang}",
    )
    if isinstance(card_payload, dict) and card_payload.get("user_notes"):
        card_response["user_notes"] = card_payload["user_notes"]
    return {
        "queue_source": normalized_queue_source,
        "card": card_response,
        "srs": srs_response,
        "srs_preview": srs_preview,
        "queue_info": queue_payload,
    }


def _build_video_search_queries(
    main_category: str | None,
    sub_category: str | None,
    *,
    skill_title: str | None = None,
    examples: list[str] | None = None,
    target_lang: str = "de",
) -> list[str]:
    target = _normalize_short_lang_code(target_lang, fallback="de")
    sub = str(sub_category or "").strip()
    main = str(main_category or "").strip()
    skill = str(skill_title or "").strip()

    def _normalize_video_search_term(raw: str) -> str:
        cleaned = " ".join(str(raw or "").strip().split())
        if not cleaned:
            return ""
        cleaned = re.sub(r"[:;|/]+", " ", cleaned)
        if target == "de":
            replacements = {
                r"\bdeclension errors?\b": "deklination",
                r"\bnouns?\b": "nomen",
                r"\badjectives?\b": "adjektive",
                r"\bverbs?\b": "verben",
                r"\bcases?\b": "faelle",
                r"\bcase\b": "fall",
                r"\barticles?\b": "artikel",
                r"\bpronouns?\b": "pronomen",
            }
            lowered = cleaned.lower()
            for pattern, replacement in replacements.items():
                lowered = re.sub(pattern, replacement, lowered, flags=re.IGNORECASE)
            cleaned = lowered
        cleaned = " ".join(cleaned.split())
        if len(cleaned) > 72:
            compact_parts: list[str] = []
            total = 0
            for word in cleaned.split():
                if total + len(word) + (1 if compact_parts else 0) > 72:
                    break
                compact_parts.append(word)
                total += len(word) + (1 if compact_parts[:-1] else 0)
            cleaned = " ".join(compact_parts).strip()
        return cleaned

    def _translate_term_for_video_search(raw: str) -> str:
        cleaned = " ".join(str(raw or "").strip().split())
        if not cleaned:
            return ""
        if target == "de" and re.search(r"[äöüßÄÖÜ]", cleaned):
            return cleaned
        if target == "ru" and re.search(r"[А-Яа-яЁё]", cleaned):
            return cleaned
        source_guess = _detect_reader_language(cleaned, fallback="en")
        source_guess = _normalize_short_lang_code(source_guess, fallback="en")
        if source_guess == target:
            return cleaned
        try:
            translated = asyncio.run(
                run_translate_subtitles_multilang(
                    lines=[cleaned],
                    source_lang=source_guess,
                    target_lang=target,
                )
            )
            candidate = str((translated or [""])[0] or "").strip()
            if candidate:
                return candidate
        except Exception:
            logging.debug("Video query translation failed for '%s' -> %s", cleaned, target, exc_info=True)
        return cleaned

    sub_local = _normalize_video_search_term(_translate_term_for_video_search(sub))
    main_local = _normalize_video_search_term(_translate_term_for_video_search(main))
    skill_local = _normalize_video_search_term(_translate_term_for_video_search(skill))

    phrase_map = {
        "de": {
            "lang_word": "deutsch",
            "grammar_explained": "grammatik erklaert",
            "grammar_practice": "grammatik uebung",
            "learn": "deutsch lernen",
            "baseline": "deutsch grammatik b1 b2",
        },
        "en": {
            "lang_word": "english",
            "grammar_explained": "grammar explained",
            "grammar_practice": "grammar practice",
            "learn": "learn english",
            "baseline": "english grammar b1 b2",
        },
        "es": {
            "lang_word": "espanol",
            "grammar_explained": "gramatica explicada",
            "grammar_practice": "ejercicios de gramatica",
            "learn": "aprender espanol",
            "baseline": "gramatica espanol b1 b2",
        },
        "it": {
            "lang_word": "italiano",
            "grammar_explained": "grammatica spiegata",
            "grammar_practice": "esercizi di grammatica",
            "learn": "imparare italiano",
            "baseline": "grammatica italiano b1 b2",
        },
        "ru": {
            "lang_word": "русский",
            "grammar_explained": "грамматика объяснение",
            "grammar_practice": "грамматика упражнения",
            "learn": "учить русский",
            "baseline": "русская грамматика b1 b2",
        },
    }
    phrases = phrase_map.get(target, phrase_map["de"])

    sample_items = []
    if isinstance(examples, list):
        for item in examples[:3]:
            text = " ".join(str(item or "").strip().split())
            if text:
                translated = _normalize_video_search_term(_translate_term_for_video_search(text[:80]))
                token_count = len(translated.split())
                # Keep only short keyword-like phrases; long sentence fragments pollute search.
                if translated and token_count <= 6 and len(translated) <= 48:
                    sample_items.append(translated)

    queries: list[str] = []
    if sub_local:
        queries.extend(
            [
                f"{sub_local} {phrases['lang_word']} {phrases['grammar_explained']}",
                f"{sub_local} {phrases['lang_word']} {phrases['grammar_practice']}",
                f"{sub_local} {phrases['learn']} b1 b2",
            ]
        )
    if main_local:
        queries.extend(
            [
                f"{main_local} {phrases['lang_word']} {phrases['grammar_explained']}",
                f"{main_local} {phrases['learn']}",
            ]
        )
    if skill_local:
        queries.extend(
            [
                f"{skill_local} {phrases['lang_word']} {phrases['grammar_explained']}",
                f"{skill_local} {phrases['learn']}",
            ]
        )
    for sample in sample_items:
        queries.append(f"{sample} {phrases['lang_word']} {phrases['grammar_explained']}")
    queries.append(phrases["baseline"])

    unique: list[str] = []
    seen: set[str] = set()
    for query in queries:
        norm = " ".join(query.strip().lower().split())
        if not norm or norm in seen:
            continue
        seen.add(norm)
        unique.append(query.strip())
    return unique


def _youtube_search_videos(
    query: str,
    *,
    max_results: int = 5,
    target_lang: str = "de",
    prefer_curated_channels: bool = True,
    billing_user_id: int | None = None,
    billing_source_lang: str | None = None,
    billing_target_lang: str | None = None,
) -> list[dict]:
    if not query:
        return []
    if not YOUTUBE_API_KEY:
        logging.info(
            "YT search skipped (no API key): query='%s'",
            query,
        )
        return []
    # Optional cap on how many curated channels we sweep per query. Each channel is
    # a separate search.list (100 units), so all 11 = 1100 units/query. Default is
    # all channels (no behaviour change); set YOUTUBE_SEARCH_MAX_CHANNELS to trade a
    # little breadth for a much lower per-query quota cost.
    curated_channels = list(_TODAY_PREFERRED_CHANNELS)
    try:
        _max_channels = int(str(os.getenv("YOUTUBE_SEARCH_MAX_CHANNELS") or "").strip() or 0)
    except Exception:
        _max_channels = 0
    if _max_channels > 0:
        curated_channels = curated_channels[:_max_channels]
    # Daily-quota guard: estimate this call's cost and fall back to pool/empty when
    # the day's budget is exhausted, instead of hitting a hard 403.
    _estimated_units = 100.0 * (len(curated_channels) if prefer_curated_channels else 1)
    if not youtube_live_search_allowed(estimated_units=_estimated_units):
        logging.warning(
            "YT live search skipped: daily quota guard (est=%s units, query='%s')",
            _estimated_units,
            query,
        )
        return []
    collected: list[dict] = []
    preferred_hits = 0
    fallback_hits = 0
    try:
        base_url = "https://www.googleapis.com/youtube/v3/search"
        common_params = {
            "part": "snippet",
            "q": query,
            "type": "video",
            "maxResults": max_results,
            "key": YOUTUBE_API_KEY,
        }
        if prefer_curated_channels:
            for channel_id in curated_channels:
                params = {**common_params, "channelId": channel_id}
                resp = requests.get(base_url, params=params, timeout=12)
                _billing_log_youtube_quota_usage(
                    user_id=billing_user_id,
                    source_lang=billing_source_lang,
                    target_lang=billing_target_lang or target_lang,
                    action_type="youtube_api_search",
                    endpoint="search",
                    quota_units=100.0,
                    metadata={"query": query[:120], "scope": "preferred_channel"},
                )
                if resp.status_code >= 400:
                    continue
                data = resp.json() if resp.content else {}
                for item in data.get("items", []):
                    video_id = ((item.get("id") or {}).get("videoId") or "").strip()
                    title = ((item.get("snippet") or {}).get("title") or "").strip()
                    if not video_id:
                        continue
                    collected.append({"video_id": video_id, "title": title})
                    preferred_hits += 1
        if not collected:
            lang_code = _normalize_short_lang_code(target_lang, fallback="de")
            region_map = {
                "de": "DE",
                "en": "US",
                "es": "ES",
                "it": "IT",
                "ru": "RU",
            }
            fallback_params = {
                **common_params,
                "relevanceLanguage": lang_code,
                "regionCode": region_map.get(lang_code, "DE"),
            }
            resp = requests.get(base_url, params=fallback_params, timeout=12)
            _billing_log_youtube_quota_usage(
                user_id=billing_user_id,
                source_lang=billing_source_lang,
                target_lang=billing_target_lang or target_lang,
                action_type="youtube_api_search",
                endpoint="search",
                quota_units=100.0,
                metadata={"query": query[:120], "scope": "fallback"},
            )
            if resp.status_code < 400:
                data = resp.json() if resp.content else {}
                for item in data.get("items", []):
                    video_id = ((item.get("id") or {}).get("videoId") or "").strip()
                    title = ((item.get("snippet") or {}).get("title") or "").strip()
                    if not video_id:
                        continue
                    collected.append({"video_id": video_id, "title": title})
                    fallback_hits += 1
    except Exception:
        logging.exception("YT search failed: query='%s'", query)
        return []

    unique = {}
    for row in collected:
        vid = row.get("video_id")
        if vid and vid not in unique:
            unique[vid] = {"video_id": vid, "title": row.get("title") or ""}
    logging.info(
        "YT search query='%s' prefer_curated=%s preferred_hits=%s fallback_hits=%s unique=%s",
        query,
        prefer_curated_channels,
        preferred_hits,
        fallback_hits,
        len(unique),
    )
    if unique:
        return list(unique.values())
    return []


def _build_youtube_manual_search_cache_key(query: str, target_lang: str, max_results: int) -> str:
    normalized_query = " ".join(str(query or "").strip().lower().split())
    normalized_lang = _normalize_short_lang_code(target_lang, fallback="de")
    normalized_limit = max(1, int(max_results or 0))
    return f"{normalized_lang}|{normalized_limit}|{normalized_query}"


def _get_cached_youtube_manual_search(query: str, target_lang: str, max_results: int) -> list[dict] | None:
    cache_key = _build_youtube_manual_search_cache_key(query, target_lang, max_results)
    now_ts = time.time()
    with _YOUTUBE_MANUAL_SEARCH_CACHE_LOCK:
        cached = _YOUTUBE_MANUAL_SEARCH_CACHE.get(cache_key)
        if not cached:
            return None
        if now_ts - float(cached.get("ts") or 0) > _YOUTUBE_MANUAL_SEARCH_CACHE_TTL_SEC:
            _YOUTUBE_MANUAL_SEARCH_CACHE.pop(cache_key, None)
            return None
        return [dict(item) for item in (cached.get("items") or [])]


def _set_cached_youtube_manual_search(query: str, target_lang: str, max_results: int, items: list[dict]) -> None:
    cache_key = _build_youtube_manual_search_cache_key(query, target_lang, max_results)
    payload = {
        "ts": time.time(),
        "items": [dict(item) for item in (items or [])],
    }
    with _YOUTUBE_MANUAL_SEARCH_CACHE_LOCK:
        _YOUTUBE_MANUAL_SEARCH_CACHE[cache_key] = payload
        if len(_YOUTUBE_MANUAL_SEARCH_CACHE) > 128:
            oldest_key = min(
                _YOUTUBE_MANUAL_SEARCH_CACHE.keys(),
                key=lambda key: float((_YOUTUBE_MANUAL_SEARCH_CACHE.get(key) or {}).get("ts") or 0),
            )
            _YOUTUBE_MANUAL_SEARCH_CACHE.pop(oldest_key, None)


def _extract_youtube_initial_data(html_text: str) -> dict | None:
    raw_html = str(html_text or "")
    if not raw_html:
        return None
    patterns = [
        r"var ytInitialData = (\{.*?\});",
        r"window\[['\"]ytInitialData['\"]\]\s*=\s*(\{.*?\});",
    ]
    for pattern in patterns:
        match = re.search(pattern, raw_html, re.DOTALL)
        if not match:
            continue
        try:
            return json.loads(match.group(1))
        except Exception:
            continue
    return None


def _iter_youtube_video_renderers(node: Any):
    if isinstance(node, dict):
        video_renderer = node.get("videoRenderer")
        if isinstance(video_renderer, dict):
            yield video_renderer
        for value in node.values():
            yield from _iter_youtube_video_renderers(value)
    elif isinstance(node, list):
        for item in node:
            yield from _iter_youtube_video_renderers(item)


def _extract_text_from_youtube_runs(payload: Any) -> str:
    if isinstance(payload, dict):
        simple_text = payload.get("simpleText")
        if isinstance(simple_text, str) and simple_text.strip():
            return simple_text.strip()
        runs = payload.get("runs")
        if isinstance(runs, list):
            parts = [str(item.get("text") or "") for item in runs if isinstance(item, dict)]
            return "".join(parts).strip()
    elif isinstance(payload, str):
        return payload.strip()
    return ""


def _youtube_search_videos_web(query: str, *, max_results: int = 8, target_lang: str = "de") -> list[dict]:
    normalized_query = " ".join(str(query or "").strip().split())
    if not normalized_query:
        return []
    cached = _get_cached_youtube_manual_search(normalized_query, target_lang, max_results)
    if cached is not None:
        return cached

    lang_code = _normalize_short_lang_code(target_lang, fallback="de")
    request_headers = {
        "User-Agent": (
            "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) "
            "AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 "
            "Mobile/15E148 Safari/604.1"
        ),
        "Accept-Language": f"{lang_code},{lang_code}-{lang_code.upper()};q=0.9,en;q=0.7",
    }
    response = requests.get(
        "https://www.youtube.com/results",
        params={"search_query": normalized_query, "hl": lang_code},
        headers=request_headers,
        timeout=8,
    )
    response.raise_for_status()
    initial_data = _extract_youtube_initial_data(response.text)
    if not initial_data:
        raise RuntimeError("youtube_initial_data_missing")

    items: list[dict] = []
    seen_ids: set[str] = set()
    for renderer in _iter_youtube_video_renderers(initial_data):
        video_id = str(renderer.get("videoId") or "").strip()
        if not video_id or video_id in seen_ids:
            continue
        title = _extract_text_from_youtube_runs(renderer.get("title")) or video_id
        thumbnails = ((renderer.get("thumbnail") or {}).get("thumbnails") or [])
        thumbnail = ""
        if isinstance(thumbnails, list) and thumbnails:
            thumbnail = str((thumbnails[-1] or {}).get("url") or "").strip()
        channel_title = _extract_text_from_youtube_runs(renderer.get("ownerText"))
        items.append(
            {
                "video_id": video_id,
                "title": title,
                "video_url": f"https://www.youtube.com/watch?v={video_id}",
                "thumbnail": thumbnail or f"https://i.ytimg.com/vi/{video_id}/hqdefault.jpg",
                "channel_title": channel_title,
                "views": 0,
            }
        )
        seen_ids.add(video_id)
        if len(items) >= max_results:
            break

    _set_cached_youtube_manual_search(normalized_query, target_lang, max_results, items)
    return items


def _youtube_search_videos_api_manual(query: str, *, max_results: int = 8, target_lang: str = "de") -> list[dict]:
    normalized_query = " ".join(str(query or "").strip().split())
    if not normalized_query:
        return []
    cached = _get_cached_youtube_manual_search(normalized_query, target_lang, max_results)
    if cached is not None:
        return cached

    items = _youtube_search_videos(
        normalized_query,
        max_results=max_results,
        target_lang=target_lang,
        prefer_curated_channels=False,
    )
    _set_cached_youtube_manual_search(normalized_query, target_lang, max_results, items)
    return items


def _youtube_search_videos_ytdlp(query: str, *, max_results: int = 8, target_lang: str = "de") -> list[dict]:
    normalized_query = " ".join(str(query or "").strip().split())
    if not normalized_query:
        return []
    cached = _get_cached_youtube_manual_search(normalized_query, target_lang, max_results)
    if cached is not None:
        return cached

    from yt_dlp import YoutubeDL

    lang_code = _normalize_short_lang_code(target_lang, fallback="de")
    search_expr = f"ytsearch{max(1, int(max_results or 1))}:{normalized_query}"
    ydl_opts = {
        "quiet": True,
        "no_warnings": True,
        "skip_download": True,
        "extract_flat": True,
        "socket_timeout": 8,
        "default_search": "ytsearch",
        "noplaylist": True,
        "playlist_items": f"1:{max(1, int(max_results or 1))}",
        "geo_bypass": True,
        "extractor_args": {
            "youtube": {
                "lang": [lang_code],
                "player_client": ["android"],
            }
        },
    }
    info = YoutubeDL(ydl_opts).extract_info(search_expr, download=False) or {}
    entries = info.get("entries") or []
    items: list[dict] = []
    seen_ids: set[str] = set()
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        video_id = str(entry.get("id") or "").strip()
        if not video_id or video_id in seen_ids:
            continue
        seen_ids.add(video_id)
        items.append(
            {
                "video_id": video_id,
                "title": str(entry.get("title") or video_id).strip(),
                "video_url": str(entry.get("webpage_url") or f"https://www.youtube.com/watch?v={video_id}").strip(),
                "thumbnail": str(entry.get("thumbnail") or f"https://i.ytimg.com/vi/{video_id}/hqdefault.jpg").strip(),
                "channel_title": str(entry.get("channel") or entry.get("uploader") or "").strip(),
                "views": int(entry.get("view_count") or 0),
            }
        )
        if len(items) >= max_results:
            break
    _set_cached_youtube_manual_search(normalized_query, target_lang, max_results, items)
    return items


def _youtube_search_videos_manual(query: str, *, max_results: int = 8, target_lang: str = "de") -> tuple[list[dict], str]:
    providers = [
        ("youtube_api_search", _youtube_search_videos_api_manual),
        ("youtube_web_search", _youtube_search_videos_web),
        ("yt_dlp_search", _youtube_search_videos_ytdlp),
    ]
    last_error: Exception | None = None
    for provider_name, provider_fn in providers:
        try:
            items = provider_fn(query, max_results=max_results, target_lang=target_lang)
            return items, provider_name
        except Exception as exc:
            last_error = exc
            logging.exception("youtube_manual_search provider=%s failed query=%r", provider_name, query)
    if last_error is not None:
        raise last_error
    return [], "none"


def _youtube_fill_view_counts(
    videos: list[dict],
    *,
    billing_user_id: int | None = None,
    billing_source_lang: str | None = None,
    billing_target_lang: str | None = None,
) -> list[dict]:
    if not videos or not YOUTUBE_API_KEY:
        return videos
    try:
        ids = ",".join([str(v.get("video_id") or "").strip() for v in videos if v.get("video_id")])
        if not ids:
            return videos
        resp = requests.get(
            "https://www.googleapis.com/youtube/v3/videos",
            params={
                "part": "statistics,snippet,contentDetails",
                "id": ids,
                "key": YOUTUBE_API_KEY,
            },
            timeout=12,
        )
        _billing_log_youtube_quota_usage(
            user_id=billing_user_id,
            source_lang=billing_source_lang,
            target_lang=billing_target_lang,
            action_type="youtube_api_videos_lookup",
            endpoint="videos",
            quota_units=1.0,
            metadata={"videos_count": len(videos)},
        )
        if resp.status_code >= 400:
            return videos
        stats = resp.json() if resp.content else {}
        by_id = {}
        for item in stats.get("items", []):
            vid = (item.get("id") or "").strip()
            if not vid:
                continue
            snippet = item.get("snippet") or {}
            by_id[vid] = {
                "views": int(((item.get("statistics") or {}).get("viewCount") or 0)),
                "title": (snippet.get("title") or "").strip(),
                "description": (snippet.get("description") or "").strip(),
                "channel_title": (snippet.get("channelTitle") or "").strip(),
                "default_audio_language": str(snippet.get("defaultAudioLanguage") or "").strip(),
                "default_language": str(snippet.get("defaultLanguage") or "").strip(),
                "duration": str(((item.get("contentDetails") or {}).get("duration") or "")).strip(),
            }
        enriched = []
        for video in videos:
            vid = str(video.get("video_id") or "").strip()
            row = dict(video)
            meta = by_id.get(vid) or {}
            row["views"] = int(meta.get("views") or 0)
            if not row.get("title"):
                row["title"] = meta.get("title") or ""
            row["description"] = str(meta.get("description") or row.get("description") or "").strip()
            row["channel_title"] = str(meta.get("channel_title") or row.get("channel_title") or "").strip()
            row["default_audio_language"] = str(meta.get("default_audio_language") or row.get("default_audio_language") or "").strip()
            row["default_language"] = str(meta.get("default_language") or row.get("default_language") or "").strip()
            row["duration"] = meta.get("duration") or ""
            enriched.append(row)
        return enriched
    except Exception:
        return videos


def _parse_iso8601_duration_to_seconds(duration: str | None) -> int:
    raw = str(duration or "").strip().upper()
    if not raw:
        return 0
    match = re.fullmatch(r"PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?", raw)
    if not match:
        return 0
    hours = int(match.group(1) or 0)
    minutes = int(match.group(2) or 0)
    seconds = int(match.group(3) or 0)
    return hours * 3600 + minutes * 60 + seconds


def _is_youtube_short_like(video: dict | None) -> bool:
    data = video if isinstance(video, dict) else {}
    title = str(data.get("title") or "").strip().lower()
    video_url = str(data.get("video_url") or "").strip().lower()
    if "#shorts" in title:
        return True
    if "/shorts/" in video_url:
        return True
    duration_seconds = int(data.get("duration_seconds") or 0)
    return 0 < duration_seconds < MIN_RECOMMENDED_VIDEO_SECONDS


def _filter_videos_for_today_task(
    videos: list[dict],
    *,
    min_seconds: int | None = None,
    target_lang: str = "de",
    native_lang: str = "",
) -> list[dict]:
    min_seconds = int(min_seconds or MIN_RECOMMENDED_VIDEO_SECONDS)
    filtered: list[dict] = []
    for item in videos or []:
        video = dict(item or {})
        duration_seconds = int(video.get("duration_seconds") or 0)
        if duration_seconds <= 0:
            duration_seconds = _parse_iso8601_duration_to_seconds(video.get("duration"))
            video["duration_seconds"] = duration_seconds
        if duration_seconds < min_seconds:
            continue
        if _is_youtube_short_like(video):
            continue
        if _video_conflicts_with_target_language(video, target_lang=target_lang, native_lang=native_lang):
            continue
        filtered.append(video)
    return filtered


def _pick_today_recommended_video(
    main_category: str | None,
    sub_category: str | None,
    *,
    skill_title: str | None = None,
    examples: list[str] | None = None,
    target_lang: str = "de",
    billing_user_id: int | None = None,
    billing_source_lang: str | None = None,
    billing_target_lang: str | None = None,
) -> dict | None:
    query_stages = [
        _build_video_search_queries(
            main_category,
            sub_category,
            skill_title=skill_title,
            examples=examples,
            target_lang=target_lang,
        ),
        _build_video_search_queries(
            main_category,
            None,
            skill_title=skill_title,
            examples=None,
            target_lang=target_lang,
        ),
        _build_video_search_queries(
            None,
            sub_category,
            skill_title=skill_title,
            examples=None,
            target_lang=target_lang,
        ),
        _build_video_search_queries(
            None,
            None,
            skill_title=skill_title,
            examples=None,
            target_lang=target_lang,
        ),
    ]
    queries: list[str] = []
    seen_queries: set[str] = set()
    for stage in query_stages:
        for query in stage:
            norm = " ".join(str(query or "").strip().lower().split())
            if not norm or norm in seen_queries:
                continue
            seen_queries.add(norm)
            queries.append(query)
    logging.info("YT recommendation queries: %s", queries)
    for query in queries:
        videos = _youtube_search_videos(
            query,
            max_results=5,
            target_lang=target_lang,
            billing_user_id=billing_user_id,
            billing_source_lang=billing_source_lang,
            billing_target_lang=billing_target_lang,
        )
        if not videos:
            continue
        videos = _youtube_fill_view_counts(
            videos,
            billing_user_id=billing_user_id,
            billing_source_lang=billing_source_lang,
            billing_target_lang=billing_target_lang,
        )
        videos = _filter_videos_for_today_task(
            videos,
            min_seconds=MIN_RECOMMENDED_VIDEO_SECONDS,
            target_lang=target_lang,
        )
        if not videos:
            continue
        videos.sort(key=lambda x: int(x.get("views") or 0), reverse=True)
        best = videos[0] if videos else None
        if not best or not best.get("video_id"):
            continue
        video_id = str(best.get("video_id")).strip()
        return {
            "video_id": video_id,
            "video_url": f"https://www.youtube.com/watch?v={video_id}",
            "title": str(best.get("title") or "").strip(),
            "query": query,
            "views": int(best.get("views") or 0),
            "duration_seconds": int(best.get("duration_seconds") or 0),
        }
    return None


def _normalize_video_focus_identity(
    skill_id: str | None = None,
    main_category: str | None = None,
    sub_category: str | None = None,
) -> tuple[str, str, str]:
    return (
        str(skill_id or "").strip().lower(),
        str(main_category or "").strip().lower(),
        str(sub_category or "").strip().lower(),
    )


def _build_video_focus_candidate(
    *,
    skill_id: str | None = None,
    skill_title: str | None = None,
    main_category: str | None = None,
    sub_category: str | None = None,
    examples: list[str] | None = None,
    source: str = "fallback",
) -> dict | None:
    resolved_skill_id = str(skill_id or "").strip() or None
    resolved_skill_title = str(skill_title or "").strip() or None
    resolved_main, resolved_sub = _sanitize_focus_topic(main_category, sub_category)
    if _is_unclassified_focus_topic(resolved_main, resolved_sub):
        resolved_main, resolved_sub = "", ""
    if not resolved_skill_id and not resolved_skill_title and not resolved_main and not resolved_sub:
        return None
    return {
        "skill_id": resolved_skill_id,
        "skill_title": resolved_skill_title,
        "main_category": resolved_main or None,
        "sub_category": resolved_sub or None,
        "examples": [str(item).strip() for item in (examples or []) if str(item).strip()][:5],
        "source": source,
    }


def _build_today_video_focus_candidates(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    weakest_skill: dict | None,
    weak_topic: dict | None,
    weak_sentences: list[str] | None,
    lookback_days: int = 7,
    cooldown_days: int = 7,
    candidate_limit: int = 5,
) -> list[dict]:
    recent_topics = list_recent_started_video_topics(
        user_id=int(user_id),
        lookback_days=max(1, int(cooldown_days or 7)),
        limit=max(5, int(candidate_limit or 5) * 3),
    )
    recent_focuses = {
        _normalize_video_focus_identity(
            entry.get("skill_id"),
            entry.get("main_category"),
            entry.get("sub_category"),
        )
        for entry in recent_topics
        if isinstance(entry, dict)
    }

    candidates: list[dict] = []
    seen_identities: set[tuple[str, str, str]] = set()

    def add_candidate(candidate: dict | None) -> None:
        if not candidate:
            return
        identity = _normalize_video_focus_identity(
            candidate.get("skill_id"),
            candidate.get("main_category"),
            candidate.get("sub_category"),
        )
        if identity in seen_identities:
            return
        seen_identities.add(identity)
        candidates.append(candidate)

    add_candidate(
        _build_video_focus_candidate(
            skill_id=(weakest_skill or {}).get("skill_id"),
            skill_title=(weakest_skill or {}).get("skill_title"),
            main_category=(weak_topic or {}).get("main_category"),
            sub_category=(weak_topic or {}).get("sub_category"),
            examples=weak_sentences or [],
            source="primary_weak_topic",
        )
    )

    for topic in list_top_weak_topics(
        user_id=int(user_id),
        lookback_days=max(1, int(lookback_days or 7)),
        source_lang=source_lang,
        target_lang=target_lang,
        limit=max(2, int(candidate_limit or 5)),
    ):
        if not isinstance(topic, dict):
            continue
        topic_main = str(topic.get("main_category") or "").strip()
        topic_sub = str(topic.get("sub_category") or "").strip()
        examples = get_weak_topic_sentences(
            user_id=int(user_id),
            main_category=topic_main,
            sub_category=topic_sub,
            lookback_days=max(1, int(lookback_days or 7)),
            limit=5,
            source_lang=source_lang,
            target_lang=target_lang,
        )
        add_candidate(
            _build_video_focus_candidate(
                main_category=topic_main,
                sub_category=topic_sub,
                examples=examples,
                source="alternate_weak_topic",
            )
        )

    if not candidates:
        fallback_candidate = _build_video_focus_candidate(
            skill_id=(weakest_skill or {}).get("skill_id"),
            skill_title=(weakest_skill or {}).get("skill_title"),
            source="skill_only_fallback",
        )
        candidates = [fallback_candidate] if fallback_candidate else []

    if not candidates:
        return []

    ordered_candidates: list[dict] = []
    recent_candidates: list[dict] = []
    cooldown_applied = bool(recent_focuses)
    for candidate in candidates:
        identity = _normalize_video_focus_identity(
            candidate.get("skill_id"),
            candidate.get("main_category"),
            candidate.get("sub_category"),
        )
        enriched = {
            **candidate,
            "cooldown_applied": cooldown_applied,
            "cooldown_skipped_recent": identity in recent_focuses,
        }
        if identity in recent_focuses:
            recent_candidates.append(enriched)
        else:
            ordered_candidates.append(enriched)

    return ordered_candidates + recent_candidates


def _select_today_video_focus_candidate(
    *,
    user_id: int,
    source_lang: str,
    target_lang: str,
    weakest_skill: dict | None,
    weak_topic: dict | None,
    weak_sentences: list[str] | None,
    lookback_days: int = 7,
    cooldown_days: int = 7,
    candidate_limit: int = 5,
) -> dict | None:
    candidates = _build_today_video_focus_candidates(
        user_id=user_id,
        source_lang=source_lang,
        target_lang=target_lang,
        weakest_skill=weakest_skill,
        weak_topic=weak_topic,
        weak_sentences=weak_sentences,
        lookback_days=lookback_days,
        cooldown_days=cooldown_days,
        candidate_limit=candidate_limit,
    )
    return candidates[0] if candidates else None


def _pick_today_recommended_video_across_focus_candidates(
    focus_candidates: list[dict] | None,
    *,
    target_lang: str,
    billing_user_id: int | None = None,
    billing_source_lang: str | None = None,
    billing_target_lang: str | None = None,
) -> tuple[dict | None, dict | None]:
    prepared_candidates = [item for item in (focus_candidates or []) if isinstance(item, dict)]
    if not prepared_candidates:
        return None, None

    selected_focus = prepared_candidates[0]
    for candidate in prepared_candidates:
        recommended_video = _pick_today_recommended_video(
            candidate.get("main_category"),
            candidate.get("sub_category"),
            skill_title=candidate.get("skill_title"),
            examples=(candidate.get("examples") if isinstance(candidate.get("examples"), list) else []),
            target_lang=target_lang,
            billing_user_id=billing_user_id,
            billing_source_lang=billing_source_lang,
            billing_target_lang=billing_target_lang,
        )
        if recommended_video:
            return candidate, recommended_video
    return selected_focus, None


def _format_theory_mistake_examples(examples: list[dict] | None) -> list[str]:
    rows: list[str] = []
    for item in examples or []:
        if not isinstance(item, dict):
            continue
        source_sentence = str(item.get("source_sentence") or "").strip()
        user_translation = str(item.get("user_translation") or "").strip()
        feedback = str(item.get("feedback") or "").strip()
        if source_sentence and user_translation:
            rows.append(f"RU: {source_sentence} | USER: {user_translation}")
        elif source_sentence:
            rows.append(f"RU: {source_sentence}")
        elif user_translation:
            rows.append(f"USER: {user_translation}")
        if feedback:
            rows.append(f"FEEDBACK: {feedback[:220]}")
        if len(rows) >= 8:
            break
    return rows[:8]


def _contains_cjk_chars(text: str) -> bool:
    return bool(re.search(r"[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]", str(text or "")))


_LANGUAGE_CONTENT_HINTS = {
    "de": ("german", "deutsch", "немец", "deutsche", "deutsch"),
    "en": ("english", "englisch", "англий", "ingles", "inglese"),
    "es": ("spanish", "espanol", "español", "spanisch", "испан"),
    "it": ("italian", "italiano", "italienisch", "итальян"),
    "ru": ("russian", "russisch", "русск"),
    "fr": ("french", "francais", "français", "franzoesisch", "француз"),
    "pt": ("portuguese", "portugues", "português", "portugiesisch", "португал"),
    "zh": ("chinese", "mandarin", "中文", "汉语", "漢語", "китай"),
    "ja": ("japanese", "日本語", "япон"),
    "ko": ("korean", "한국어", "корей"),
}


def _detect_explicit_language_mentions(text: str) -> set[str]:
    haystack = str(text or "").lower()
    mentions: set[str] = set()
    for code, hints in _LANGUAGE_CONTENT_HINTS.items():
        if any(hint in haystack for hint in hints):
            mentions.add(code)
    if _contains_cjk_chars(haystack):
        mentions.add("zh")
    return mentions


def _resource_conflicts_with_target_language(
    *,
    title: str,
    url: str,
    snippet: str,
    target_lang: str,
    native_lang: str = "",
) -> bool:
    target = _normalize_short_lang_code(target_lang, fallback="de")
    native = _normalize_short_lang_code(native_lang, fallback="")
    mentions = _detect_explicit_language_mentions(" ".join([title, url, snippet]))
    if target in mentions:
        return False
    if native and mentions == {native}:
        return True
    conflicting = {code for code in mentions if code not in {target, native}}
    return bool(conflicting)


def _normalize_metadata_language_code(value: str) -> str:
    raw = str(value or "").strip().lower()
    if not raw:
        return ""
    primary = raw.split("-", 1)[0].split("_", 1)[0].strip()
    return _normalize_short_lang_code(primary, fallback="")


def _video_conflicts_with_target_language(
    video: dict,
    *,
    target_lang: str,
    native_lang: str = "",
) -> bool:
    target = _normalize_short_lang_code(target_lang, fallback="de")
    native = _normalize_short_lang_code(native_lang, fallback="")
    metadata_langs = {
        _normalize_metadata_language_code(video.get("default_audio_language") or ""),
        _normalize_metadata_language_code(video.get("default_language") or ""),
    }
    metadata_langs.discard("")
    if metadata_langs and target not in metadata_langs:
        return True

    title = str(video.get("title") or "").strip()
    description = str(video.get("description") or "").strip()
    channel_title = str(video.get("channel_title") or "").strip()
    mentions = _detect_explicit_language_mentions(" ".join([title, description, channel_title]))
    if target in mentions:
        return False
    if native and mentions == {native}:
        return True
    conflicting = {code for code in mentions if code not in {target, native}}
    if conflicting:
        return True
    if target != "zh" and _contains_cjk_chars(title) and target not in mentions:
        return True
    return False


def _is_bad_russian_practice_sentence(sentence: str) -> bool:
    text = " ".join(str(sentence or "").strip().split())
    lower = text.lower()
    if not text or not re.search(r"[А-Яа-яЁё]", text):
        return True
    if len(re.findall(r"[А-Яа-яЁё-]+", text)) < 3:
        return True
    # Reject broken calques like "я идти", "они часто ездить", "вчера я готовить".
    if re.search(
        r"\b(я|ты|он|она|оно|мы|вы|они)\s+(?:(?:не|часто|редко|обычно|иногда|всегда|уже|снова|сейчас|здесь|там|дома|потом|сегодня|вчера|завтра)\s+){0,2}[а-яё-]+(?:ть|ти|чь)\b",
        lower,
    ):
        return True
    if re.search(
        r"\b(сегодня|вчера|завтра|часто|обычно|иногда|каждый день|по выходным)\s+(я|ты|он|она|оно|мы|вы|они)\s+(?:не\s+)?[а-яё-]+(?:ть|ти|чь)\b",
        lower,
    ):
        return True
    if re.search(r"\bкогда\s+(я|ты|он|она|оно|мы|вы|они)\s+[а-яё-]+(?:ть|ти|чь)\b", lower):
        return True
    if re.search(r"\b(я|ты|он|она|оно|мы|вы|они)\s+знать\b", lower):
        return True
    return False


def _is_bad_native_practice_sentence(sentence: str, native_lang: str) -> bool:
    normalized_native = _normalize_short_lang_code(native_lang, fallback="")
    if normalized_native == "ru":
        return _is_bad_russian_practice_sentence(sentence)
    return False


def _normalize_theory_sentences(payload: dict, *, native_lang: str = "") -> list[str]:
    raw = payload.get("sentences")
    if not isinstance(raw, list):
        return []
    cleaned: list[str] = []
    seen: set[str] = set()
    for item in raw:
        text = " ".join(str(item or "").strip().split())
        if not text:
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        if _is_bad_native_practice_sentence(text, native_lang):
            continue
        cleaned.append(text)
    if len(cleaned) >= 5:
        return cleaned[:5]
    return cleaned


