@app.errorhandler(Exception)
def handle_unexpected_error(error):
    if isinstance(error, HTTPException):
        # Preserve Flask/Werkzeug HTTP status codes (e.g. 404/405) without
        # converting them into noisy 500 errors.
        return error
    logging.exception("Unhandled exception: %s", error)
    if request.path.startswith("/api/"):
        return jsonify({"error": "Internal Server Error"}), 500
    raise error


@app.route("/api/telegram/validate", methods=["POST"])
def validate_telegram_init_data():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    return jsonify({"ok": True, **_parse_telegram_init_data(init_data)})


@app.route("/api/webapp/bootstrap", methods=["POST"])
def bootstrap_webapp_session():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    session_id = str(uuid4())
    parsed = _parse_telegram_init_data(init_data)
    starter_dictionary = None
    translation_session = None
    welcome_trial = None
    try:
        parsed_user = parsed.get("user") if isinstance(parsed.get("user"), dict) else {}
        parsed_user_id = _safe_int(parsed_user.get("id"))
        if parsed_user_id is not None and parsed_user_id > 0:
            # One-time 7-day Pro trial for everyone (Pro minus book-narration audio) on first
            # Mini-App open. Idempotent per lifetime — a returning user just gets granted=False.
            # Enrich with the app-entry plaque state (active countdown / ended → buy Pro).
            try:
                _grant_res = grant_welcome_trial_once(int(parsed_user_id))
                _ws = get_welcome_trial_status(int(parsed_user_id))
                _ent = resolve_entitlement(int(parsed_user_id))  # cached read
                _mode = str(_ent.get("effective_mode") or "free").strip().lower()
                if _ws.get("active"):
                    _state = "active"          # inside the free trial → show countdown
                elif _ws.get("used") and _mode != "pro":
                    _state = "ended"           # used it up and now Free → nudge to buy Pro
                else:
                    _state = "none"            # never eligible, or already a paying Pro
                welcome_trial = {
                    "state": _state,
                    "granted": bool(_grant_res.get("granted")),
                    "days": int(_grant_res.get("days") or 0),
                    "days_left": int(_ws.get("days_left") or 0),
                    "ends_at": _ws.get("ends_at"),
                }
            except Exception:
                logging.warning("welcome trial grant failed user=%s", parsed_user_id, exc_info=True)
            starter_dictionary = _build_starter_dictionary_offer(user_id=int(parsed_user_id))
            session_projection_payload, _session_lookup_mode = _load_session_presence_projection_with_source(int(parsed_user_id))
            if isinstance(session_projection_payload, dict):
                translation_session = _build_session_presence_response_payload(session_projection_payload)
                # Незакрытая сессия = человек перевёл часть и ушёл. Главному экрану нужны
                # живые счётчики, чтобы позвать его обратно словами «3 из 7», а не молчать.
                if str((translation_session or {}).get("type") or "").strip().lower() == "regular":
                    try:
                        _session_source_lang, _session_target_lang, _ = _get_user_language_pair(int(parsed_user_id))
                        _session_progress = get_translation_session_progress(
                            int(parsed_user_id),
                            str(translation_session.get("session_id") or "").strip(),
                            source_lang=_session_source_lang,
                            target_lang=_session_target_lang,
                        )
                        translation_session["translated_count"] = int(_session_progress.get("translated_count") or 0)
                        translation_session["total_sentences"] = int(_session_progress.get("shown_count") or 0)
                    except Exception:
                        logging.warning(
                            "Bootstrap: active translation session progress lookup failed user=%s",
                            parsed_user_id,
                            exc_info=True,
                        )
            _prime_webapp_home_snapshots_async(
                user_id=int(parsed_user_id),
                username=_extract_display_name(parsed_user),
            )
    except Exception as exc:
        logging.warning("Webapp bootstrap async prime failed: %s", exc)
    return jsonify(
        {
            "ok": True,
            "session_id": session_id,
            **parsed,
            "starter_dictionary": starter_dictionary,
            "translation_session": translation_session,
            "welcome_trial": welcome_trial,
        }
    )


@app.route("/api/webapp/instance/claim", methods=["POST"])
def claim_webapp_instance():
    payload = request.get_json(silent=True) or {}
    init_data = _extract_request_init_data(payload)
    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    if not _is_webapp_user_allowed(int(user_id)):
        return jsonify({"error": "Доступ к приложению закрыт администратором."}), 403

    instance_id = _extract_webapp_instance_id(payload)
    if not instance_id:
        return jsonify({"error": "instanceId обязателен"}), 400

    reason = str(payload.get("reason") or "heartbeat").strip().lower() or "heartbeat"
    request_ctx = _extract_webapp_app_context(payload)
    previous_lease = _get_cached_webapp_instance_lease(int(user_id))
    previous_active = bool(previous_lease and _webapp_instance_lease_is_fresh(previous_lease))
    previous_instance_id = str(previous_lease.get("instance_id") or "").strip() if isinstance(previous_lease, dict) else ""
    previous_ctx = str(previous_lease.get("app_context") or "").strip().lower() if isinstance(previous_lease, dict) else ""
    # Per-surface: a heartbeat from a DIFFERENT surface (Telegram vs installed PWA) is
    # not a conflict — the surfaces coexist and each keeps its own lease alive.
    same_surface = (not request_ctx or not previous_ctx or previous_ctx == request_ctx)
    if previous_active and previous_instance_id and previous_instance_id != instance_id and reason != "claim" and same_surface:
        return jsonify(_build_webapp_instance_conflict_payload(previous_lease)), 409
    lease = claim_webapp_instance_lease(
        user_id=int(user_id),
        instance_id=instance_id,
        session_id=str(payload.get("sessionId") or request.headers.get("X-Webapp-Session-Id") or "").strip() or None,
        platform=str(payload.get("platform") or request.headers.get("X-Webapp-Platform") or request.user_agent.string or "").strip()[:64] or None,
        app_context=str(payload.get("appContext") or request.headers.get("X-Webapp-App-Context") or "").strip()[:64] or None,
    )
    _cache_webapp_instance_lease(int(user_id), lease)
    return jsonify(
        {
            "ok": True,
            "lease": lease,
            "ttl_seconds": int(WEBAPP_INSTANCE_LEASE_TTL_SECONDS),
            "reason": reason,
            "takeover": bool(previous_active and previous_instance_id and previous_instance_id != instance_id),
        }
    )


@app.route("/api/webapp/instance/release", methods=["POST"])
def release_webapp_instance():
    payload = request.get_json(silent=True) or {}
    init_data = _extract_request_init_data(payload)
    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    if not _is_webapp_user_allowed(int(user_id)):
        return jsonify({"error": "Доступ к приложению закрыт администратором."}), 403

    instance_id = _extract_webapp_instance_id(payload)
    if not instance_id:
        return jsonify({"error": "instanceId обязателен"}), 400

    released = release_webapp_instance_lease(user_id=int(user_id), instance_id=instance_id)
    if released:
        _cache_webapp_instance_lease(int(user_id), None)
    return jsonify({"ok": True, "released": bool(released)})


def _inbox_mark_kind_done(user_id: int, kind: str) -> None:
    """Mark every open interactive-inbox row of a kind answered and queue a ✅
    edit for each (DM feed). Used by self-contained games (Adjektiv/Artikel Sprint,
    Review) whose submit endpoints don't know the exact dispatch id. Best-effort."""
    try:
        from backend.database import (
            mark_interactive_inbox_answered_all_kind, enqueue_challenge_notification,
        )
        for row in mark_interactive_inbox_answered_all_kind(user_id=int(user_id), kind=str(kind)) or []:
            if row.get("telegram_message_id") and int(row.get("chat_id") or 0) == int(user_id):
                enqueue_challenge_notification(
                    user_id=int(user_id), kind="inbox_done",
                    challenge_key=f"{kind}:{row.get('id')}",
                    payload={
                        "chat_id": int(row["chat_id"]),
                        "message_id": int(row["telegram_message_id"]),
                        "deeplink": str(row.get("deeplink") or ""),
                        "title": str(row.get("title") or ""),
                        "keyboard_json": row.get("keyboard_json"),
                    },
                )
    except Exception:
        logging.warning("inbox mark-kind-done failed user=%s kind=%s", user_id, kind, exc_info=True)


def _answer_auth_user_id() -> tuple[int | None, str, tuple]:
    """Shared auth for /api/answer/*. Returns (user_id, user_name, error_response).

    On success error_response is empty; on failure user_id is None and
    error_response is the (jsonify, status) tuple to return directly.
    """
    payload = request.get_json(silent=True) or {}
    init_data = _extract_request_init_data(payload)
    if not init_data:
        return None, "", (jsonify({"error": "initData обязателен"}), 400)
    if not _telegram_hash_is_valid(init_data):
        return None, "", (jsonify({"error": "initData не прошёл проверку"}), 401)
    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return None, "", (jsonify({"error": "user_id отсутствует в initData"}), 400)
    user_name = str(user_data.get("first_name") or user_data.get("username") or "").strip()
    # A valid Telegram signature alone is NOT access: without this check the /api/answer/*
    # family (including the GPT-spending deepdive endpoints) stayed reachable for a user an
    # admin had denied. _is_webapp_user_allowed self-serve-grants a first-time visitor, so
    # only a denied user is turned away here.
    if not _is_webapp_user_allowed(int(user_id)):
        return None, "", (jsonify({"error": "Доступ к приложению закрыт администратором."}), 403)
    return int(user_id), user_name, ()


def _resolve_qfp(user_id: int, raw_poll_id) -> tuple:
    """Resolve a poll-scoped freeform deeplink (ans_qfp_<poll_id>) to a normal
    'qf' dispatch for this user. Returns (dispatch_id, 'qf', None) or
    (None, None, error_response). poll_id is a string (big Telegram id)."""
    poll_id = str(raw_poll_id or "").strip()
    if not poll_id:
        return None, None, (jsonify({"error": "id обязателен"}), 400)
    from backend.database import get_active_quiz, get_or_create_quiz_freeform_dispatch
    aq = get_active_quiz(poll_id)
    if not aq:
        return None, None, (jsonify({"error": "Опрос не найден или устарел"}), 404)
    did = get_or_create_quiz_freeform_dispatch(
        user_id=int(user_id), poll_id=poll_id,
        chat_id=int(aq.get("chat_id") or 0),
        correct_text=str(aq.get("correct_text") or ""),
        word_ru=str(aq.get("word_ru") or ""),
        quiz_type=str(aq.get("quiz_type") or ""),
    )
    if not did:
        return None, None, (jsonify({"error": "Не удалось открыть задание"}), 404)
    return int(did), "qf", None


@app.route("/api/answer/task", methods=["GET", "POST"])
def get_answer_task():
    """Return render metadata for an in-group task (rebus/crossword).

    Never reveals the correct answer unless the user has already answered
    (then the stored verdict is included so reopening shows the result).
    """
    user_id, user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err

    payload = request.get_json(silent=True) or {}
    kind = str(request.args.get("kind") or payload.get("kind") or "").strip().lower()
    raw_id = request.args.get("id") or payload.get("id")
    if kind == "qfp":
        dispatch_id, kind, qerr = _resolve_qfp(user_id, raw_id)
        if qerr:
            return qerr
    else:
        try:
            dispatch_id = int(raw_id)
        except (TypeError, ValueError):
            return jsonify({"error": "id обязателен"}), 400

    from backend.answer_eval import (
        load_rebus_task, load_crossword_task, load_anagram_task, load_listening_task,
        load_freeform_task, load_aufgabe_task, load_mc_task,
    )
    if kind == "rb":
        meta = load_rebus_task(dispatch_id=dispatch_id, user_id=user_id)
    elif kind == "cw":
        meta = load_crossword_task(dispatch_id=dispatch_id, user_id=user_id)
    elif kind == "ag":
        meta = load_anagram_task(dispatch_id=dispatch_id, user_id=user_id)
    elif kind == "ls":
        meta = load_listening_task(dispatch_id=dispatch_id, user_id=user_id)
    elif kind == "qf":
        meta = load_freeform_task(dispatch_id=dispatch_id, user_id=user_id)
    elif kind == "au":
        meta = load_aufgabe_task(dispatch_id=dispatch_id, user_id=user_id)
    elif kind == "mc":
        meta = load_mc_task(dispatch_id=dispatch_id, user_id=user_id)
        # Pre-warm the correct answer's audio NOW (while the user reads/answers),
        # so the 🔊 button on the result is an instant cache hit instead of a
        # 20-30s cold synth. Off the critical path.
        try:
            from backend.database import get_mc_dispatch_by_id
            _d = get_mc_dispatch_by_id(dispatch_id)
            if _d:
                _opts = list(_d.get("options") or [])
                _cid = int(_d.get("correct_option_id") or 0)
                _de = (_opts[_cid] if (not _d.get("hide_correct") and 0 <= _cid < len(_opts))
                       else str(_d.get("correct_text") or ""))
                _warm_tts_async(_de, lang_short="de")
        except Exception:
            logging.debug("mc warm_tts skipped", exc_info=True)
    else:
        return jsonify({"error": "unsupported kind"}), 400
    if meta is None:
        return jsonify({"error": "Задание не найдено"}), 404
    payload_out = {"ok": True, **meta}
    # Someone who reached this task through a group/forwarded link may never have opened the
    # bot in a DM — and that is the only channel through which tasks are delivered.
    dm_hint = _build_dm_start_hint(int(user_id), user_name)
    if dm_hint:
        payload_out["dm_hint"] = dm_hint
    return jsonify(payload_out)


@app.route("/api/answer/crossword/hint", methods=["POST"])
def crossword_hint():
    """Открыть одну букву в загаданном слове кроссворда.

    Ответы никогда не уезжают на клиент, поэтому и подсказка выдаётся сервером —
    он же держит лимит «одна буква на слово»."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err

    payload = request.get_json(silent=True) or {}
    try:
        dispatch_id = int(payload.get("id"))
        row = int(payload.get("row"))
        col = int(payload.get("col"))
    except (TypeError, ValueError):
        return jsonify({"error": "Не поняли, какую клетку открыть"}), 400

    from backend.answer_eval import reveal_crossword_hint
    try:
        result = reveal_crossword_hint(
            dispatch_id=dispatch_id, user_id=user_id, row=row, col=col,
        )
    except Exception:
        logging.exception("crossword hint failed id=%s user=%s", dispatch_id, user_id)
        return jsonify({"error": "Подсказка не открылась, попробуй ещё раз"}), 500
    if result is None:
        return jsonify({"error": "Задание не найдено"}), 404
    if result.get("error"):
        return jsonify(result), 409
    return jsonify(result)


@app.route("/api/answer/submit", methods=["POST"])
def submit_answer():
    """Evaluate a free-text answer in place. user_id comes only from initData;
    a second submission returns the stored verdict (anti-replay)."""
    user_id, user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err

    payload = request.get_json(silent=True) or {}
    kind = str(payload.get("kind") or "").strip().lower()
    if kind == "qfp":
        dispatch_id, kind, qerr = _resolve_qfp(user_id, payload.get("id"))
        if qerr:
            return qerr
    else:
        try:
            dispatch_id = int(payload.get("id"))
        except (TypeError, ValueError):
            return jsonify({"error": "id обязателен"}), 400
    answer = str(payload.get("answer") or "")

    from backend.answer_eval import (
        evaluate_rebus, evaluate_crossword, evaluate_anagram, start_listening_evaluation,
        evaluate_freeform, evaluate_aufgabe, evaluate_mc,
    )
    try:
        if kind == "mc":
            try:
                sel = int(payload.get("selected_option_id"))
            except (TypeError, ValueError):
                return jsonify({"error": "selected_option_id обязателен"}), 400
            result = evaluate_mc(
                dispatch_id=dispatch_id, user_id=user_id,
                selected_option_id=sel,
                freeform_text=str(payload.get("freeform_text") or ""),
            )
        elif kind == "rb":
            result = evaluate_rebus(dispatch_id=dispatch_id, user_id=user_id, raw_input=answer)
        elif kind == "cw":
            result = evaluate_crossword(dispatch_id=dispatch_id, user_id=user_id, raw_input=answer)
        elif kind == "ag":
            result = evaluate_anagram(dispatch_id=dispatch_id, user_id=user_id, assembled=answer)
        elif kind == "qf":
            result = evaluate_freeform(dispatch_id=dispatch_id, user_id=user_id, raw_input=answer)
        elif kind == "au":
            result = evaluate_aufgabe(dispatch_id=dispatch_id, user_id=user_id, raw_input=answer)
        elif kind == "ls":
            answers = payload.get("answers")
            try:
                ls_time_ms = int(payload.get("time_ms") or 0)
            except (TypeError, ValueError):
                ls_time_ms = 0
            result = start_listening_evaluation(
                dispatch_id=dispatch_id, user_id=user_id,
                answers=answers if isinstance(answers, list) else [],
                user_name=user_name, time_ms=ls_time_ms,
            )
        else:
            return jsonify({"error": "unsupported kind"}), 400
    except Exception as exc:
        logging.exception("answer submit failed kind=%s id=%s user=%s", kind, dispatch_id, user_id)
        # Outbox an admin alert (the bot polls bt_3_challenge_notifications and DMs).
        # UNIQUE(user_id, kind, challenge_key) → one alert per admin per broken task.
        try:
            from backend.database import get_admin_telegram_ids, enqueue_challenge_notification
            for admin_id in (get_admin_telegram_ids() or []):
                enqueue_challenge_notification(
                    user_id=int(admin_id), kind="admin_alert", challenge_key=f"{kind}:{dispatch_id}",
                    payload={"task_kind": kind, "dispatch_id": dispatch_id, "error": str(exc)[:200]},
                )
        except Exception:
            logging.warning("answer submit: admin alert enqueue failed", exc_info=True)
        return jsonify({"error": "Ошибка проверки"}), 500
    if result is None:
        return jsonify({"error": "Задание не найдено"}), 404

    # Cross-cutting ranking/trophy: record the verdict + time and attach the
    # standing among everyone who answered this same challenge. Listening (ls) is
    # graded async, so its ranking is attached later in listening_status.
    if kind != "ls" and "needs_article" not in result:
        try:
            time_ms = int(payload.get("time_ms") or 0)
        except (TypeError, ValueError):
            time_ms = 0
        is_correct = bool(
            result.get("is_correct")
            if "is_correct" in result
            else (result.get("total") and result.get("correct_count") == result.get("total"))
        )
        # Key the ranking by the shared TASK content (not the per-recipient dispatch),
        # so ALL bot users who answered the same task compete in one global ranking
        # — not isolated "1 of 1" per dispatch.
        from backend.answer_eval import content_ranking_key
        challenge_key = content_ranking_key(kind, dispatch_id)
        try:
            from backend.database import record_challenge_result, compute_challenge_ranking
            record_challenge_result(
                challenge_key=challenge_key, user_id=user_id, user_name=user_name,
                is_correct=is_correct, time_ms=time_ms,
            )
            # Личная ротация: одно место на все игры. `challenge_key` уже построен по
            # СОДЕРЖИМОМУ задания («rb:42»), а не по рассылке, поэтому годится как
            # ключ памяти без всякой переделки. Без этой записи следующая выдача
            # выбирается вслепую и человеку приходит пройденное.
            #
            # Только ПЕРВАЯ сдача. Открыть уже сданное задание и нажать «проверить»
            # снова можно сколько угодно раз (проверяющие возвращают сохранённый
            # разбор с флагом `already_answered`), а лестница возврата обязана считать
            # СДАЧИ: иначе три захода в решённый кроссворд протащили бы человека
            # 90 → 120 → «никогда», а три захода в заваленный — 7 → 14 → 30.
            # `record_challenge_result` выше от этого защищён своим ON CONFLICT.
            if not result.get("already_answered"):
                try:
                    from backend.database import record_user_task_answer
                    record_user_task_answer(user_id=user_id, kind=kind,
                                            task_key=challenge_key,
                                            is_correct=is_correct, source="chat")
                except Exception:
                    logging.warning("ротация: не удалось запомнить ответ kind=%s key=%s",
                                    kind, challenge_key, exc_info=True)
            result["ranking"] = compute_challenge_ranking(challenge_key=challenge_key, user_id=user_id)
            # Overtake plaques: a faster correct answer pushes slower players down.
            # Notify whoever just lost #1, AND refresh the current place on every
            # plaque already shown for this challenge (2nd → 3rd → …). Each user
            # answers a task only once, so places only ever drop. Cheap inserts;
            # the bot polls the outbox and sends/edits the plaque (no DM on the
            # critical path).
            if is_correct:
                from backend.database import (
                    get_challenge_correct_answers,
                    get_overtaken_user_ids_for_challenge,
                    upsert_overtaken_notification,
                )
                full = get_challenge_correct_answers(challenge_key)
                place_of = {int(u["user_id"]): i + 1 for i, u in enumerate(full)}
                time_of = {int(u["user_id"]): int(u["time_ms"]) for u in full}
                targets = set(get_overtaken_user_ids_for_challenge(challenge_key))
                if place_of.get(int(user_id)) == 1 and len(full) >= 2:
                    targets.add(int(full[1]["user_id"]))  # just dethroned from #1
                targets.discard(int(user_id))
                for uid in targets:
                    p = place_of.get(uid)
                    if not p or p < 2:
                        continue
                    # The player directly ahead (place p-1) is who just overtook
                    # this user; for 2nd place that's the leader. Carry their name
                    # + id so the plaque can show "Тебя обошёл <name>" + avatar.
                    above = full[p - 2] if 0 <= (p - 2) < len(full) else full[0]
                    upsert_overtaken_notification(
                        user_id=uid, challenge_key=challenge_key,
                        payload={
                            # No task_kind here: it would be the raw kind code
                            # ("au", "rb", …) and leak into the plaque text. The bot
                            # derives a human label from challenge_key via
                            # _challenge_label(). (Battle paths set a real task_kind.)
                            "place": int(p),
                            "total_correct": len(full),
                            "leader_name": str(full[0]["name"] or ""),
                            "leader_user_id": int(full[0]["user_id"]),
                            "leader_time_ms": int(full[0]["time_ms"]),
                            "above_name": str(above["name"] or ""),
                            "above_user_id": int(above["user_id"]),
                            "your_time_ms": int(time_of.get(uid, 0)),
                        },
                    )
        except Exception:
            logging.warning("challenge ranking failed key=%s user=%s", challenge_key, user_id, exc_info=True)

    # Interactive inbox: flip this task to answered (once) and, for the DM feed,
    # mark its source message ✅ via the outbox the bot already polls. Harmless
    # no-op if the task's sender didn't write an inbox row.
    if not result.get("already_answered"):
        try:
            from backend.database import (
                mark_interactive_inbox_answered, enqueue_challenge_notification,
            )
            inbox_row = mark_interactive_inbox_answered(
                user_id=user_id, kind=kind, dispatch_id=dispatch_id,
            )
            if (inbox_row and inbox_row.get("telegram_message_id")
                    and int(inbox_row.get("chat_id") or 0) == int(user_id)):
                enqueue_challenge_notification(
                    user_id=int(user_id), kind="inbox_done",
                    challenge_key=f"{kind}:{dispatch_id}",
                    payload={
                        "chat_id": int(inbox_row["chat_id"]),
                        "message_id": int(inbox_row["telegram_message_id"]),
                        "deeplink": str(inbox_row.get("deeplink") or ""),
                        "title": str(inbox_row.get("title") or ""),
                        "keyboard_json": inbox_row.get("keyboard_json"),
                    },
                )
        except Exception:
            logging.warning("inbox answered hook failed kind=%s id=%s user=%s",
                            kind, dispatch_id, user_id, exc_info=True)

    return jsonify({"ok": True, **result})


# ── Deep-dive overlay (in-place 🔊/📌/🧩/❓ for a quiz result) ─────────────
# Replaces the four callback buttons that dumped new messages at the chat
# bottom. The DM card now carries one Mini-App button (?startapp=dive_<id>);
# this overlay reads the persisted card and runs the actions in place.

@app.route("/api/answer/deepdive", methods=["GET", "POST"])
def deepdive_load():
    """Return the word context for a deep-dive card the user owns."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    raw_id = request.args.get("id") or payload.get("id")
    try:
        card_id = int(raw_id)
    except (TypeError, ValueError):
        return jsonify({"error": "id обязателен"}), 400
    from backend.deepdive import load_card
    meta = load_card(card_id=card_id, user_id=user_id)
    if meta is None:
        return jsonify({"error": "Карточка не найдена"}), 404
    return jsonify({"ok": True, **meta})


@app.route("/api/answer/deepdive/from_text", methods=["POST"])
def deepdive_from_text():
    """Mint a deep-dive card from raw words (for results that have no card yet,
    e.g. the MC quiz) so 📌/🧩 can run on the correct answer. Returns its id."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    source_text = str(payload.get("source_text") or "").strip()
    target_text = str(payload.get("target_text") or "").strip()
    source_lang = str(payload.get("source_lang") or "de").strip().lower() or "de"
    target_lang = str(payload.get("target_lang") or "ru").strip().lower() or "ru"
    if not source_text:
        return jsonify({"error": "source_text обязателен"}), 400
    from backend.database import create_deepdive_card
    card_id = create_deepdive_card(
        user_id=user_id, source_text=source_text, target_text=target_text,
        source_lang=source_lang, target_lang=target_lang,
    )
    if not card_id:
        return jsonify({"error": "Не удалось создать карточку"}), 500
    return jsonify({"ok": True, "id": int(card_id)})


