@app.route("/api/answer/rebusreview/draw", methods=["POST"])
def answer_rebus_review_draw():
    """Нарисовать несколько карточек по требованию прямо из приёмки.

    Сам пул берётся за рисование только когда запас падает ниже порога, поэтому,
    когда очередь пуста, посмотреть приёмку в деле иначе нечем. Работу делает
    воркер: рисование идёт минуты, в вебе его держать нельзя."""
    user_id, err = _pin_review_admin_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    try:
        cards = max(1, min(4, int(payload.get("cards") or 2)))
    except (TypeError, ValueError):
        cards = 2
    # Можно назвать конкретную карточку («Дорисовать» в каталоге) — иначе рисуются
    # первые по очереди, и попасть в нужную можно только перебором за деньги.
    names = [str(payload.get("compound") or "").strip()] if payload.get("compound") else []
    ids = [str(payload.get("compound_id") or "").strip()] if payload.get("compound_id") else []
    from backend.job_queue import enqueue_rebus_draw_job
    outcome = enqueue_rebus_draw_job(chat_id=int(user_id), cards=cards,
                                     names=[n for n in names if n],
                                     compound_ids=[i for i in ids if i])
    if not outcome.get("queued"):
        return jsonify({"error": "Очередь задач недоступна — рисование не начато, "
                                 "ничего не потрачено."}), 503
    return jsonify({"ok": True, "cards": cards})


@app.route("/api/answer/rebusreview/verdict", methods=["POST"])
def answer_rebus_review_verdict():
    """Owner's verdict on one drawn half: approve / reject+reason / block the word.

    Approving composes every card that was only waiting for this half — that is pure
    image composition, no generation, so it is safe to do inline."""
    user_id, err = _pin_review_admin_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    compound_id = str(payload.get("compound_id") or "").strip()
    word = str(payload.get("word") or "").strip()
    verdict = str(payload.get("verdict") or "").strip().lower()
    reason = str(payload.get("reason") or "").strip()
    if not compound_id or verdict not in ("approve", "redraw", "drop_pair"):
        return jsonify({"error": "нужны карточка и решение"}), 400
    if verdict == "redraw" and not word:
        return jsonify({"error": "не указано, какую половинку перерисовать"}), 400
    from backend.database import rebus_pool_status, set_rebus_card_review
    result = set_rebus_card_review(compound_id, verdict, word=word, reason=reason)
    if result.get("status") == "redraw":
        # Перерисовываем СРАЗУ. Иначе картинка ждала бы, пока пул сам возьмётся за
        # работу (а он трогается только когда запас карточек падает ниже порога) —
        # то есть отказ уходил бы в никуда на недели.
        try:
            from backend.job_queue import enqueue_rebus_draw_job
            queued = enqueue_rebus_draw_job(chat_id=int(user_id), compound_ids=[compound_id], cards=1)
            if not queued.get("queued"):
                # Без очереди рисовать здесь нельзя (веб-запрос столько не живёт) —
                # честно говорим, что перерисовка не началась.
                result["redraw_started"] = False
            else:
                result["redraw_started"] = True
        except Exception:
            logging.warning("rebusreview: redraw enqueue failed id=%s", compound_id, exc_info=True)
            result["redraw_started"] = False
    if result.get("status") == "approved":
        # Собираем СРАЗУ: обе картинки уже есть, это склейка, а не генерация. Заодно
        # достраиваем всё, что ждало этих же половинок.
        composed = 0
        try:
            from backend.rebus_generator import (
                compose_rebus_entries_waiting_for, prepare_rebus_entry,
            )
            if prepare_rebus_entry(compound_id, allow_draw=False).get("status") == "ready":
                composed += 1
            for w in result.get("words") or []:
                composed += int((compose_rebus_entries_waiting_for(w) or {}).get("composed") or 0)
        except Exception:
            logging.warning("rebusreview: compose after approve failed id=%s", compound_id, exc_info=True)
        result["composed"] = composed
    return jsonify({"ok": True, **result, "status_pool": rebus_pool_status()})


# ── Спорные фразы общего словаря: экран приёмки вместо переписки в чате ─────────
# Ночная проверка откладывает владельцу фразы, по которым двое судей не сошлись. Разбор
# жил в чате бота, и это его ломало: у владельца там сотни непрочитанных учебных
# сообщений, а каждый ответ бота приходил новым сообщением в самый конец переписки —
# то есть уносил его от того места, где он читал. Экран держит весь разбор в одном
# месте: список, варианты судей, решение — и чат в этом не участвует.
_PHRASE_REVIEW_CATEGORY_RU = {
    "rechtschreibung": "опечатка", "kongruenz": "согласование", "kasus": "падеж",
    "praeposition": "предлог", "wortstellung": "порядок слов", "stil": "стиль",
}


def _phrase_fix_check_ru(judge: dict, field: str) -> dict | None:
    """Приговор проверке правки — в том виде, в каком его читает человек.

    Три состояния, и они РАЗНЫЕ: годится / судья ошибся / проверить не удалось.
    Последнее не притворяется ни первым, ни вторым.
    """
    check = judge.get(f"{field}_check") if isinstance(judge, dict) else None
    if not isinstance(check, dict) or not check.get("checked"):
        return {"state": "unknown", "why": ""} if judge.get(field) else None
    bad = []
    if not check.get("grammar_ok"):
        bad.append("немецкий неверен")
    if not check.get("meaning_kept"):
        bad.append("смысл другой")
    return {
        "state": "ok" if not bad else "bad",
        "what": ", ".join(bad),
        "why": str(check.get("why") or ""),
    }


def _phrase_review_payload(limit: int = 200) -> dict:
    """Открытые спорные фразы в том виде, в каком их показывает экран.

    Варианты нумеруются ЗДЕСЬ, на сервере, и тот же номер уходит обратно в решении —
    иначе фронт и бэкенд могли бы разойтись в том, что значит «принять второй»."""
    from backend.database import (
        list_open_phrase_reviews, phrase_review_card_examples, phrase_review_kind,
        phrase_review_variants,
    )
    items = []
    for it in list_open_phrase_reviews(int(limit)):
        judges = it.get("judges") or []
        arbiter = it.get("arbiter") if isinstance(it.get("arbiter"), dict) else None
        # include_disputed: экран владельца ПОКАЗЫВАЕТ возражение проверки рядом с
        # таким вариантом («Наша проверка не согласна: …»), поэтому имеет право его
        # получить. Нумерация вариантов здесь и в применении решения обязана совпадать.
        variants = phrase_review_variants(judges, it.get("text") or "", arbiter,
                                          include_disputed=True)
        slot_of = {v["text"]: n for n, v in enumerate(variants)}
        # ТРИ РАЗНЫХ ВОПРОСА В ОДНОЙ ОЧЕРЕДИ, и путать их нельзя.
        # "grammar"     — судьи разошлись о грамматике фразы: решение = выбрать текст.
        # "panel"       — три голоса разошлись о КАРТОЧКЕ (примеры и перевод): выбирать
        #                 нечего, там другие кнопки и на экран нужны сами примеры.
        # "translation" — перевод карточки не прошёл проверку перед подъёмом в общий
        #                 слой: решение = поднять его, вписать свой или оставить личным.
        kind = phrase_review_kind(judges)
        panel = kind == "panel"
        items.append({
            "id": it["id"],
            "kind": kind,
            "text": it.get("text") or "",
            "translation": it.get("translation") or "",
            # Примеры — предмет спора панельного вопроса. У грамматического их не
            # запрашиваем: лишний поход в базу на каждую из двух сотен строк.
            "examples": phrase_review_card_examples(it.get("card")) if panel else [],
            # «Эту фразу ты уже правил». Приходит только когда решения были: ночь
            # больше не задаёт повторный вопрос, но ДРУГУЮ ошибку в той же фразе
            # найти может — и тогда владелец должен видеть, что здесь уже было.
            "history": it.get("history") or [],
            "all_ok": bool(judges) and all(
                str(j.get("verdict") or "") == "ok" for j in judges),
            # Вердикт третейского: победивший вариант отдаём НОМЕРОМ той же нумерации,
            # что у кнопок, — иначе «прав второй» и кнопка «Принять 2» разъедутся.
            "arbiter": ({
                "why": str(arbiter.get("why") or ""),
                # Текст третьего судьи проходит ту же проверку, что правки первых двух.
                # Забракован — кнопки у него нет, но причина отказа на экране есть.
                "better_check": _phrase_fix_check_ru(arbiter, "better"),
                "winner_index": (int(arbiter.get("winner")) - 1
                                 if 1 <= int(arbiter.get("winner") or 0) <= len(variants) else None),
                "better": str(arbiter.get("better") or ""),
                "better_ru": str(arbiter.get("better_ru") or ""),
            } if arbiter else None),
            "variants": [
                {"index": n, "judge": v["judge"], "text": v["text"],
                 # перевод СВОЕГО предложения: без него не видно, сохранил ли судья
                 # смысл сохранённой фразы или молча подменил его
                 "ru": v.get("ru") or "",
                 "kind": {"corrected": "fix", "proposal": "complete"}.get(
                     v["field"], v["field"]),
                 # Третий судья назвал этот вариант верным, а наша проверка была
                 # против. Кнопка есть, но возражение проверки владелец видит рядом —
                 # решает он, и решает зряче.
                 "objection": (
                     str(((judges[v["judge"] - 1] or {}).get(f"{v['field']}_check") or {})
                         .get("why") or "")
                     if v.get("check_disputed_by_arbiter")
                     and 0 < v["judge"] <= len(judges) else "")}
                for n, v in enumerate(variants)
            ],
            "judges": [
                {
                    "no": n,
                    "verdict": str(j.get("verdict") or ""),
                    "category": _PHRASE_REVIEW_CATEGORY_RU.get(
                        str(j.get("category") or ""), str(j.get("category") or "")),
                    "why": str(j.get("why") or ""),
                    "corrected": str(j.get("corrected") or ""),
                    "corrected_ru": str(j.get("corrected_ru") or ""),
                    "proposal": str(j.get("proposal") or ""),
                    "proposal_ru": str(j.get("proposal_ru") or ""),
                    "corrected_slot": slot_of.get(str(j.get("corrected") or "").strip()),
                    "proposal_slot": slot_of.get(str(j.get("proposal") or "").strip()),
                    # Приговор проверке правки. Кнопки у забракованной правки нет, но
                    # сама она с экрана НЕ пропадает: владелец должен видеть, что судья
                    # предложил и почему это отклонено, — иначе экран врёт молчанием.
                    "corrected_check": _phrase_fix_check_ru(j, "corrected"),
                    "proposal_check": _phrase_fix_check_ru(j, "proposal"),
                }
                for n, j in enumerate(judges, 1)
            ],
        })
    from backend.database import (
        count_noise_phrase_reviews, list_open_phrase_reviews_judged_blind,
    )
    try:
        noise = count_noise_phrase_reviews()
    except Exception:
        logging.debug("phrasereview: noise count failed", exc_info=True)
        noise = 0
    try:
        blind = len(list_open_phrase_reviews_judged_blind(500))
    except Exception:
        logging.debug("phrasereview: blind count failed", exc_info=True)
        blind = 0
    # ⚠ «ВСЕГО» — ЭТО ВСЯ ОЧЕРЕДЬ, А НЕ ЗАГРУЖЕННОЕ ОКНО.
    #
    # Владелец 24.08.2026 прислал скриншот: «1 из 200», он разбирает фразу за фразой, а
    # 200 не двигается. Так и было: экран грузит не больше 200 штук, а в очереди их 202.
    # Решил одну — сервер дослал следующую из хвоста, и число снова 200. Работа шла
    # (187 фраз уже разобрано), но на экране она была невидима — а невидимая работа
    # выглядит как бесполезная.
    from backend.database import count_open_phrase_reviews
    try:
        total = count_open_phrase_reviews()
    except Exception:
        logging.debug("phrasereview: total count failed", exc_info=True)
        total = len(items)          # честнее показать окно, чем соврать нулём
    from backend.database import count_open_phrase_reviews_by_kind
    try:
        by_kind = count_open_phrase_reviews_by_kind()
    except Exception:
        logging.debug("phrasereview: kind counts failed", exc_info=True)
        by_kind = {}
    return {"items": items, "total": total, "loaded": len(items),
            "noise": noise, "blind": blind, "by_kind": by_kind}


@app.route("/api/answer/phrasereview/list", methods=["POST"])
def answer_phrase_review_list():
    """Все спорные фразы разом: экран листает их у себя, без похода на сервер за каждой."""
    user_id, err = _pin_review_admin_id()
    if user_id is None:
        return err
    return jsonify({"ok": True, **_phrase_review_payload()})


@app.route("/api/answer/phrasereview/decide", methods=["POST"])
def answer_phrase_review_decide():
    """Решение владельца по одной фразе: принять вариант судьи, вписать свой или удалить.

    Ответ сразу несёт обновлённый список — экран не должен ходить за ним отдельно и
    показывать между двумя запросами уже решённую фразу."""
    user_id, err = _pin_review_admin_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    try:
        review_id = int(payload.get("review_id"))
    except (TypeError, ValueError):
        return jsonify({"error": "нет фразы"}), 400
    decision = str(payload.get("decision") or "").strip().lower()
    if decision not in ("accept", "keep", "delete", "replace", "skip", "rewrite",
                        "link_accept", "link_own"):
        return jsonify({"error": "неизвестное решение"}), 400
    own_text = str(payload.get("text") or "").strip()
    if decision == "replace" and not own_text:
        return jsonify({"error": "пустой текст"}), 400
    try:
        variant = max(0, int(payload.get("variant") or 0))
    except (TypeError, ValueError):
        variant = 0

    from backend.database import apply_phrase_review_decision
    if decision in ("link_accept", "link_own"):
        # Вопрос о ПЕРЕВОДЕ карточки: проверка не подтвердила, что русский означает эту
        # фразу, и решает владелец. «Принять» ставит перевод карточки общим (ранг 5),
        # «свой» — его собственный, и тот встаёт выше, рангом 1 с подписью «вычитка»:
        # решение человека не должна перебивать ни модель, ни машинный перевод.
        from backend.database import apply_translation_link_decision
        own = str(payload.get("text") or "").strip()
        if decision == "link_own" and not own:
            return jsonify({"error": "пустой перевод"}), 400
        res = apply_translation_link_decision(review_id, decision, own)
        if res.get("linked"):
            note = (f"Перевод стал общим: {res.get('translation')}"
                    if decision == "link_accept"
                    else f"Записал твой перевод: {res.get('translation')}")
        else:
            note = "Не получилось записать перевод. Вопрос оставлен открытым."
        return jsonify({"ok": True, "result": decision, "note": note,
                        **_phrase_review_payload()})
    if decision == "rewrite":
        # Панельная карточка: спор не о фразе, а о её примерах и переводе. Владелец
        # отправляет её ночному переписчику — тот берёт другой моделью, проверяет
        # вторым голосом и, если не выйдет и с третьего раза, вернёт её сюда же.
        from backend.database import send_panel_card_to_rewrite
        res = send_panel_card_to_rewrite(review_id)
        note = ("Отправил примеры на переписывание — вернётся к тебе, только если "
                "и ночью не выйдет." if res.get("queued") else
                "Не удалось поставить в очередь переписывания: карточка не числится "
                "спорной. Вопрос оставлен открытым.")
        return jsonify({"ok": True, "result": "rewrite", "note": note,
                        **_phrase_review_payload()})
    if decision == "skip":
        # «Отложить» ничего не решает и не закрывает строку — фраза просто уезжает в
        # конец списка на этом экране. Никакой записи в базу.
        return jsonify({"ok": True, "result": "skipped", **_phrase_review_payload()})
    # Перевод к своему тексту. Приходит, когда владелец жмёт «Всё равно принять» на
    # правке, забракованной проверкой: текст и перевод берутся с того же места, где он
    # их прочитал, и его выбор не заменяется машинным.
    own_ru = str(payload.get("translation") or "").strip()
    result = apply_phrase_review_decision(review_id, decision, own_text, variant, own_ru)
    if decision == "keep":
        note = "Фраза оставлена как есть — вопрос закрыт."
    elif decision == "delete":
        note = "Фраза удалена из общего словаря."
    elif result.get("text"):
        note = f"Записал: {result['text']}"
        # Текст записан — а разбор под него мог не собраться (модель не ответила). Тогда
        # на слове остаётся разбор ПРО СТАРУЮ ФРАЗУ, и молчать об этом нельзя: раньше
        # экран рапортовал «Записал», владелец шёл дальше, а половина работы не сделана.
        if result.get("breakdown_rebuilt") is False:
            note += ("\n⚠️ Разбор под новую фразу пока не собрался — на слове остался "
                     "прежний. Нажми «Пересудить» позже или открой слово в словаре.")
        # Перевод владельца — его решение, и оно не должно теряться молча.
        if result.get("owner_ru_set") is False:
            note += "\n⚠️ Твой перевод не встал главным — на слове остался прежний."
    else:
        # Ни одна из веток не записала текст: либо такая фраза уже есть, либо вариант
        # совпал с исходным. Строка при этом закрыта — врать «готово» нельзя.
        note = "Не записал: такая фраза уже есть в словаре. Снял с разбора."
    return jsonify({"ok": True, "result": decision, "note": note,
                    "text": result.get("text") or "", **_phrase_review_payload()})


@app.route("/api/answer/phrasereview/ask", methods=["POST"])
def answer_phrase_review_ask():
    """Спросить про эту фразу своими словами, не выходя с экрана.

    Владельцу пришлось уйти в другое приложение, чтобы выяснить, что «Wappnen mit» и
    «Wappnen gegen» — разные значения, а не ошибка. Вопрос про фразу должен задаваться
    там же, где по ней принимается решение. В контекст кладём саму фразу, её русский
    перевод и все предложения судей: без перевода ответ будет таким же слепым, как был
    вердикт."""
    user_id, err = _pin_review_admin_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    question = str(payload.get("question") or "").strip()
    if not question:
        return jsonify({"error": "пустой вопрос"}), 400
    try:
        review_id = int(payload.get("review_id"))
    except (TypeError, ValueError):
        return jsonify({"error": "нет фразы"}), 400

    from backend.database import get_open_phrase_review, phrase_review_variants
    row = get_open_phrase_review(review_id)
    if not row:
        return jsonify({"error": "Фраза уже разобрана."}), 404
    arbiter = row.get("arbiter") if isinstance(row.get("arbiter"), dict) else None
    variants = phrase_review_variants(row.get("judges") or [], row.get("text") or "", arbiter)
    lines = [f"Немецкая фраза из словаря: {row.get('text') or ''}"]
    if row.get("translation"):
        lines.append(f"Русский перевод, ради которого её сохранили: {row['translation']}")
    for n, j in enumerate(row.get("judges") or [], 1):
        if isinstance(j, dict) and j.get("why"):
            lines.append(f"Проверяющий {n} считает: {j['why']}")
    for n, v in enumerate(variants, 1):
        lines.append(f"Предложенная замена {n}: {v['text']}"
                     + (f" ({v['ru']})" if v.get("ru") else ""))
    lines.append("Отвечай с оглядкой на сохранённый русский перевод: он и есть смысл, "
                 "который человек хотел записать. Если исходная фраза верна для этого "
                 "смысла, так и скажи прямо.")

    from backend.openai_manager import run_quick_ask
    try:
        answer = run_quick_ask(question=question, context_text="\n".join(lines))
    except Exception:
        logging.warning("phrasereview: ask failed id=%s", review_id, exc_info=True)
        answer = ""
    if not answer:
        return jsonify({"error": "Не получилось ответить. Попробуйте ещё раз."}), 503
    return jsonify({"ok": True, "answer": answer})


