@app.route("/api/sprint/finish", methods=["POST"])
def sprint_finish():
    """Authoritative end-of-round grading: count correct (list + one LLM batch),
    record the result, return final count + ranking."""
    user_id, user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    try:
        dispatch_id = int(payload.get("id"))
    except (TypeError, ValueError):
        return jsonify({"error": "id обязателен"}), 400
    words = payload.get("words")
    words = words if isinstance(words, list) else []
    try:
        time_ms = int(payload.get("time_ms") or 0)
    except (TypeError, ValueError):
        time_ms = 0
    from backend.answer_eval import evaluate_sprint
    try:
        result = evaluate_sprint(
            dispatch_id=dispatch_id, user_id=user_id, words=words,
            time_ms=time_ms, user_name=user_name,
        )
    except Exception:
        logging.exception("sprint finish failed id=%s user=%s", dispatch_id, user_id)
        return jsonify({"error": "Ошибка подсчёта"}), 500
    if result is None:
        return jsonify({"error": "Задание не найдено"}), 404
    return jsonify({"ok": True, **result})


@app.route("/api/webapp/artikel/today", methods=["POST"])
def artikel_today():
    """Artikel Sprint: load today's shared daily set (preloaded for zero-latency
    client play). Builds the set on the fly if the nightly job hasn't yet."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    from datetime import datetime as _dt
    from zoneinfo import ZoneInfo
    from backend.database import (
        ensure_article_sprint_schema, get_daily_article_sprint_set_id,
        get_article_sprint_set, get_article_sprint_theme, get_article_sprint_result,
        compute_article_sprint_ranking,
    )
    ensure_article_sprint_schema()
    play_date = _dt.now(ZoneInfo("Europe/Vienna")).date()
    set_id = get_daily_article_sprint_set_id(play_date)
    if not set_id:
        try:
            from backend.article_sprint_sets import build_daily_set
            built = build_daily_set(play_date)
        except Exception:
            logging.exception("artikel_today: build failed")
            built = {"status": "error"}
        if built.get("status") == "ready":
            set_id = built["set_id"]
        else:
            return jsonify({"ok": False, "error_code": "artikel_set_not_ready",
                            "error": "Набор Artikel Sprint на сегодня ещё готовится. Загляни чуть позже."}), 200
    s = get_article_sprint_set(set_id)
    if not s or not s.get("words"):
        return jsonify({"ok": False, "error_code": "artikel_set_empty", "error": "Набор пуст."}), 200
    theme = get_article_sprint_theme(s["theme_key"])
    existing = get_article_sprint_result(set_id, int(user_id))
    result_payload = None
    if existing:
        result_payload = {
            **existing,
            "pct": round(100 * existing["correct"] / existing["answered"]) if existing.get("answered") else 0,
            "items": [],
            "ranking": compute_article_sprint_ranking(set_id=set_id, user_id=int(user_id)),
            "already_played": True,
        }
    return jsonify({
        "ok": True, "set_id": set_id,
        "theme_label": (theme or {}).get("label_de") or s["theme_key"],
        "words": s["words"], "duration_s": 120,
        "already_played": bool(existing), "result": result_payload,
    })


@app.route("/api/webapp/adjektiv/today", methods=["POST"])
def adjektiv_today():
    """Adjektiv Sprint: load today's latest daily set (15 items, preloaded for
    zero-latency play). The set is built by the scheduled broadcast job."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    from datetime import datetime as _dt
    from zoneinfo import ZoneInfo
    from backend.database import (
        get_latest_daily_adjektiv_set, get_adjektiv_sprint_set,
        get_adjektiv_sprint_result, compute_adjektiv_sprint_ranking,
        get_or_create_personal_adjektiv_set,
    )
    play_date = _dt.now(ZoneInfo("Europe/Vienna")).date()
    set_id = get_latest_daily_adjektiv_set(play_date)
    if not set_id:
        return jsonify({"ok": False, "error_code": "adjektiv_set_not_ready",
                        "error": "Сет Adjektiv Sprint на сегодня ещё готовится. Загляни чуть позже."}), 200
    # Набор дня личный: задания собирает чистый код, поэтому подбор под слабые клетки
    # человека не стоит ни копейки. Зачёт остаётся общим — он считается по всем наборам
    # слота сразу. Не собрался личный — играем общий, как раньше.
    set_id = get_or_create_personal_adjektiv_set(set_id, int(user_id)) or set_id
    s = get_adjektiv_sprint_set(set_id)
    if not s or not s.get("items"):
        return jsonify({"ok": False, "error_code": "adjektiv_set_empty", "error": "Сет пуст."}), 200
    # Slim items for play (the correct ending is included for instant local grading,
    # like Artikel; explanations stay server-side and come back with the result).
    slim = [{"before": it.get("before", ""), "after": it.get("after", ""),
             "a": it.get("a", ""), "ru": it.get("ru", "")} for it in s["items"]]
    existing = get_adjektiv_sprint_result(set_id, int(user_id))
    result_payload = None
    if existing:
        result_payload = {
            **existing,
            "pct": round(100 * existing["correct"] / existing["answered"]) if existing.get("answered") else 0,
            "items": [],
            "ranking": compute_adjektiv_sprint_ranking(set_id=set_id, user_id=int(user_id)),
            "already_played": True,
        }
    return jsonify({
        "ok": True, "set_id": set_id, "theme_label": "Adjektivendungen",
        "items": slim, "per_item_s": 5,
        "already_played": bool(existing), "result": result_payload,
    })


@app.route("/api/webapp/adjektiv/submit", methods=["POST"])
def adjektiv_submit():
    """Adjektiv Sprint: official scoring — re-grade answers (by item order) against
    the stored set, record the first attempt, return a detailed per-item review."""
    user_id, user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    set_id = str(payload.get("set_id") or "").strip()
    answers = payload.get("answers")
    answers = answers if isinstance(answers, list) else []
    try:
        time_ms = int(payload.get("time_ms") or 0)
    except (TypeError, ValueError):
        time_ms = 0
    from backend.database import (
        adjektiv_cell_key as _adjektiv_cell_key,
        get_adjektiv_sprint_set, record_adjektiv_sprint_result,
        get_adjektiv_sprint_result, compute_adjektiv_sprint_ranking,
    )
    s = get_adjektiv_sprint_set(set_id)
    if not s or not s.get("items"):
        return jsonify({"error": "Сет не найден"}), 404
    set_items = s["items"]
    items = []
    correct = 0
    answered = 0
    for i, it in enumerate(set_items):
        ans = answers[i] if i < len(answers) else None
        chosen = str((ans or {}).get("chosen") or "").strip().lower()
        corr = str(it.get("a") or "").strip().lower()
        ok = bool(chosen) and chosen == corr
        if chosen:
            answered += 1
            if ok:
                correct += 1
        items.append({
            "before": it.get("before", ""), "after": it.get("after", ""),
            "full": it.get("full", ""), "a": corr, "chosen": chosen, "ok": ok,
            "erklaerung": it.get("erklaerung", ""), "tip": it.get("tip", ""),
            "example": it.get("example", ""), "ru": it.get("ru", ""),
        })
    total = len(set_items)
    recorded = record_adjektiv_sprint_result(
        set_id=set_id, user_id=int(user_id), user_name=user_name or "",
        correct=correct, answered=answered, total=total, time_ms=time_ms,
    )
    if recorded:
        # Ответ по КАЖДОМУ заданию — в фоне, игра ждать этого не должна. Раньше
        # хранился только итог «12 из 15», поэтому сказать, на какой клетке таблицы
        # человек спотыкается, было не из чего: клеток 27, и обычно валятся две-три.
        def _log_adjektiv_items(rows=[
            {"user_id": int(user_id), "set_id": set_id,
             "cell": _adjektiv_cell_key(it), "typ": it.get("typ", ""),
             "case": it.get("case", ""), "gender": it.get("gender", ""),
             "chosen": str((answers[i] if i < len(answers) else {} or {}).get("chosen") or ""),
             "correct": str((answers[i] if i < len(answers) else {} or {}).get("chosen") or "").strip().lower()
                        == str(it.get("a") or "").strip().lower()}
            for i, it in enumerate(set_items)]):
            try:
                from backend.database import record_adjektiv_item_answers
                record_adjektiv_item_answers(rows)
            except Exception:
                logging.warning("adjektiv item telemetry failed set=%s", set_id,
                                exc_info=True)
        threading.Thread(target=_log_adjektiv_items, daemon=True).start()
    _unpin_battle_invite_async(int(user_id), set_id)  # event-driven: result → unpin
    _flip_battle_ctas_done_async(int(user_id), set_id)  # flip play buttons → «✅ Сыграно»
    if not recorded:
        prev = get_adjektiv_sprint_result(set_id, int(user_id)) or {}
        correct = int(prev.get("correct", correct))
        answered = int(prev.get("answered", answered))
    # Overtake plaque for Adjektiv BATTLES: beating someone DMs them the crying-Smurf
    # card with a deeplink back into that battle (who beat them + results).
    if recorded:
        try:
            from backend.database import (
                get_adjektiv_battle_id_by_set_id, list_adjektiv_sprint_results_ranked,
                get_overtaken_user_ids_for_challenge, upsert_overtaken_notification,
            )
            battle_id = get_adjektiv_battle_id_by_set_id(set_id)
            if battle_id:
                challenge_key = f"adb:{set_id}"
                full = list_adjektiv_sprint_results_ranked(set_id)
                if len(full) >= 2:
                    place_of = {int(u["user_id"]): i + 1 for i, u in enumerate(full)}
                    targets = set(get_overtaken_user_ids_for_challenge(challenge_key))
                    if place_of.get(int(user_id)) == 1:
                        targets.add(int(full[1]["user_id"]))
                    targets.discard(int(user_id))
                    for uid in targets:
                        p = place_of.get(uid)
                        if not p or p < 2:
                            continue
                        above = full[p - 2]
                        upsert_overtaken_notification(
                            user_id=uid, challenge_key=challenge_key,
                            payload={
                                "task_kind": "Adjektiv Battle", "place": int(p),
                                "total_correct": len(full),
                                "leader_name": str(full[0]["name"] or ""),
                                "leader_user_id": int(full[0]["user_id"]),
                                "above_name": str(above["name"] or ""),
                                "above_user_id": int(above["user_id"]),
                                "open_kind": "adb", "battle_id": int(battle_id),
                            })
        except Exception:
            logging.warning("adjektiv overtake enqueue failed set=%s", set_id, exc_info=True)
    pct = round(100 * correct / answered) if answered else 0
    if recorded:
        _inbox_mark_kind_done(int(user_id), "ad")  # ✅ the Adjektiv Sprint card
        _maybe_record_weak_topic(int(user_id), "ad", correct, answered)
    return jsonify({
        "ok": True, "correct": correct, "answered": answered, "total": total, "pct": pct,
        "items": items, "already_played": not recorded,
        "ranking": compute_adjektiv_sprint_ranking(set_id=set_id, user_id=int(user_id)),
    })


@app.route("/api/webapp/battles/history", methods=["POST"])
def battles_history():
    """Unified battle history across all game types (Artikel, Adjektiv, …) — open
    and finished, with the user's place/score per battle. Grouped into sections so
    new game types just add another section."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    from backend.database import (
        list_user_article_battles_with_standing, list_user_adjektiv_battles_with_standing,
        list_user_wofrage_battles_with_standing,
    )

    def _row(b, play_kind):
        status = str(b.get("status") or "")
        return {
            "battle_id": int(b["id"]), "creator_name": str(b.get("creator_name") or ""),
            "label": str(b.get("label") or ""),
            "deadline": b["deadline"].isoformat() if b.get("deadline") else "", "status": status,
            "your_place": b.get("your_place"), "your_count": int(b.get("your_count") or 0),
            "total": int(b.get("total") or 0), "winner": str(b.get("winner") or ""),
            "play": (f"ans_{play_kind}_{b['id']}" if status == "open" else ""),
        }

    # One window-function query per game type (was an N+1 of ~40-80 round-trips).
    art = [_row(b, "asb") for b in list_user_article_battles_with_standing(int(user_id), 20)]
    adj = [_row(b, "adb") for b in list_user_adjektiv_battles_with_standing(int(user_id), 20)]
    wof = [_row(b, "wfb") for b in list_user_wofrage_battles_with_standing(int(user_id), 20)]

    sections = []
    if art:
        sections.append({"key": "artikel", "label": "⚡ Artikel", "battles": art})
    if adj:
        sections.append({"key": "adjektiv", "label": "🔠 Adjektiv", "battles": adj})
    if wof:
        sections.append({"key": "wofrage", "label": "❓ Wo-Fragen", "battles": wof})
    return jsonify({"ok": True, "sections": sections})


@app.route("/api/webapp/adjektiv/learn", methods=["POST"])
def adjektiv_learn():
    """Adjektiv Trainer: an endless self-paced deck of ending situations with the
    rule + tip revealed after each tap. No timer, no scoring — pure learning."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    from backend.database import pick_adjektiv_payloads_for_user, derive_adjektiv_split
    payload = request.get_json(silent=True) or {}
    try:
        n = max(5, min(20, int(payload.get("count") or 12)))
    except (TypeError, ValueError):
        n = 12
    out = []
    # Личная тренировка подстраивается: клетки таблицы окончаний, на которых человек
    # валится, идут чаще. Дневной набор так подбирать нельзя — по нему сравнивают всех.
    for p in pick_adjektiv_payloads_for_user(int(user_id), n):
        correct = str(p.get("correct") or "").lower()
        before = str(p.get("before") or "")
        after = str(p.get("after") or "")
        der = derive_adjektiv_split(str(p.get("full") or ""), correct)
        if der:
            before, after = der
        out.append({
            "before": before, "after": after, "a": correct, "full": str(p.get("full") or ""),
            "erklaerung": str(p.get("erklaerung") or ""), "tip": str(p.get("tip") or ""),
            "example": str(p.get("example") or ""), "ru": str(p.get("hint_ru") or ""),
            # Per-word translations for tap-to-translate + save (deterministic items only).
            "adj": str(p.get("adj") or ""), "adj_ru": str(p.get("adj_ru") or ""),
            "noun": str(p.get("noun") or ""), "noun_ru": str(p.get("noun_ru") or ""),
            "noun_article": str(p.get("noun_article") or ""),
        })
    if not out:
        return jsonify({"ok": False, "error": "Колода пока готовится. Загляни чуть позже."}), 200
    return jsonify({"ok": True, "items": out})


@app.route("/api/webapp/adjektiv/battle", methods=["POST"])
def adjektiv_battle():
    """Load an Adjektiv battle's shared set. Member-gated; closed/expired refused."""
    user_id, _user_name, err = _answer_auth_user_id()
    if user_id is None:
        return err
    payload = request.get_json(silent=True) or {}
    try:
        battle_id = int(payload.get("battle_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "battle_id обязателен"}), 400
    from datetime import datetime as _dt, timezone as _tz
    from backend.database import (
        get_adjektiv_sprint_battle, is_adjektiv_sprint_battle_member,
        get_adjektiv_sprint_set, get_adjektiv_sprint_result, compute_adjektiv_sprint_ranking,
    )
    battle = get_adjektiv_sprint_battle(battle_id)
    if not battle:
        return jsonify({"ok": False, "error": "Батл не найден"}), 404
    if str(battle.get("status")) != "open" or (battle.get("deadline") and battle["deadline"] <= _dt.now(_tz.utc)):
        return jsonify({"ok": False, "error_code": "battle_closed", "error": "Этот батл уже закрыт."}), 200
    if not is_adjektiv_sprint_battle_member(battle_id, int(user_id)):
        return jsonify({"ok": False, "error_code": "not_member",
                        "error": "Ты не в этом батле. Прими вызов в личке."}), 200
    set_id = str(battle.get("set_id") or "")
    s = get_adjektiv_sprint_set(set_id)
    if not s or not s.get("items"):
        return jsonify({"ok": False, "error": "Набор батла пуст."}), 200
    slim = [{"before": it.get("before", ""), "after": it.get("after", ""),
             "a": it.get("a", ""), "ru": it.get("ru", "")} for it in s["items"]]
    existing = get_adjektiv_sprint_result(set_id, int(user_id))
    result_payload = None
    if existing:
        result_payload = {
            **existing,
            "pct": round(100 * existing["correct"] / existing["answered"]) if existing.get("answered") else 0,
            "items": [],
            "ranking": compute_adjektiv_sprint_ranking(set_id=set_id, user_id=int(user_id)),
            "already_played": True,
        }
    return jsonify({
        "ok": True, "set_id": set_id, "theme_label": "⚔️ Battle",
        "items": slim, "per_item_s": 5,
        "already_played": bool(existing), "result": result_payload,
    })


