@app.route("/api/billing/sponsors", methods=["GET"])
def get_billing_sponsors():
    """Стена благодарностей: публичный список спонсоров (имя + тир), без доступа."""
    try:
        limit = int(request.args.get("limit") or 50)
    except Exception:
        limit = 50
    try:
        sponsors = list_recent_sponsors(limit=limit)
    except Exception as exc:
        logging.warning("billing sponsors fetch failed: %s", exc)
        sponsors = []
    payload = [
        {
            "tier": str(item.get("tier") or "support_coffee"),
            "name": str(item.get("display_name") or "").strip() or "Аноним",
        }
        for item in sponsors
    ]
    return jsonify({"sponsors": payload}), 200


@app.route("/api/billing/create-checkout-session", methods=["POST"])
def create_billing_checkout_session():
    # Pro is Stars-only now — Stripe checkout is retired. Refuse to mint a Stripe session
    # so nobody can obtain Pro through Stripe (even by hitting the API directly).
    if not STRIPE_BILLING_ENABLED:
        return jsonify({
            "error": "Полный доступ можно оформить только через Telegram Stars. Оформи его в приложении внутри Telegram.",
            "error_code": "stripe_disabled",
        }), 403
    started_perf = time.perf_counter()
    request_id = _extract_observability_request_id()
    correlation_id = _build_observability_correlation_id(prefix="billing_checkout")
    with db_acquire_scope("billing_checkout") as db_acquire_events:
        auth_started_at = time.perf_counter()
        user_id, username, error = _get_authenticated_user_from_request_init_data()
        auth_duration_ms = int((time.perf_counter() - auth_started_at) * 1000)
        if error:
            status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
            _log_flow_observation(
                "billing_checkout",
                "checkout_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                final_status="error",
                error_code="auth_error",
                auth_duration_ms=auth_duration_ms,
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=status,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify({"error": error}), status

        config_error = _require_stripe_config(require_webhook_secret=False)
        if config_error:
            _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), final_status="error", error_code="stripe_config", duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": config_error}), 500
        if not APP_BASE_URL:
            _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), final_status="error", error_code="missing_app_base_url", duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": "APP_BASE_URL не задан"}), 500

        payload = request.get_json(silent=True) or {}
        requested_plan = str(payload.get("plan_code") or "").strip().lower()
        if not requested_plan:
            _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), final_status="error", error_code="missing_plan_code", duration_ms=_elapsed_ms_since(started_perf), http_status=400, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": "plan_code обязателен"}), 400

        resolve_plan_duration_ms = 0
        stripe_customer_duration_ms = 0
        stripe_session_duration_ms = 0
        switch_duration_ms = 0
        try:
            plan_started_at = time.perf_counter()
            resolved_plan_code, stripe_price_id = _resolve_billing_plan_checkout_config(requested_plan)
            resolve_plan_duration_ms = int((time.perf_counter() - plan_started_at) * 1000)

            # Донат-тарифы (billing_type=one_time) — разовое «спасибо»: mode=payment,
            # доступ не выдаём и subscription-логику (switch/already-active) пропускаем.
            plan_cfg = get_billing_plan(resolved_plan_code) or {}
            if str(plan_cfg.get("billing_type") or "recurring").strip().lower() == "one_time":
                stripe_customer_id = _get_or_create_stripe_customer_id(int(user_id), username=username)
                metadata = {"user_id": str(int(user_id)), "plan_code": resolved_plan_code, "support": "1"}
                support_display_name = str(username or "").strip()
                if support_display_name:
                    # Имя для стены благодарностей фиксируем в момент оплаты.
                    metadata["display_name"] = support_display_name[:128]
                stripe_session_started_at = time.perf_counter()
                session = stripe.checkout.Session.create(
                    mode="payment",
                    customer=stripe_customer_id,
                    client_reference_id=str(int(user_id)),
                    metadata=metadata,
                    payment_intent_data={"metadata": dict(metadata)},
                    line_items=[{"price": stripe_price_id, "quantity": 1}],
                    success_url=_build_billing_telegram_return_url("success", include_session_id=True),
                    cancel_url=_build_billing_telegram_return_url("cancel"),
                )
                stripe_session_duration_ms = int((time.perf_counter() - stripe_session_started_at) * 1000)
                checkout_url = str(getattr(session, "url", "") or "")
                if not checkout_url:
                    _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), requested_plan=requested_plan, resolved_plan_code=resolved_plan_code, final_status="error", error_code="missing_checkout_url", duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
                    return jsonify({"error": "Stripe checkout session URL отсутствует"}), 500
                response_payload = {"url": checkout_url, "state": "one_time_support", "plan_code": resolved_plan_code}
                _log_flow_observation(
                    "billing_checkout",
                    "checkout_completed",
                    request_id=request_id,
                    correlation_id=correlation_id,
                    user_id=int(user_id),
                    requested_plan=requested_plan,
                    resolved_plan_code=resolved_plan_code,
                    checkout_state="one_time_support",
                    auth_duration_ms=auth_duration_ms,
                    resolve_plan_duration_ms=resolve_plan_duration_ms,
                    stripe_session_duration_ms=stripe_session_duration_ms,
                    response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
                    duration_ms=_elapsed_ms_since(started_perf),
                    final_status="success",
                    http_status=200,
                    **summarize_db_acquire_events(db_acquire_events),
                )
                return jsonify(response_payload), 200

            subscription_row = get_user_subscription(int(user_id)) or {}
            current_plan_code = str(subscription_row.get("plan_code") or "").strip().lower()
            current_status = str(subscription_row.get("status") or "").strip().lower()
            current_subscription_id = str(subscription_row.get("stripe_subscription_id") or "").strip() or None

            if current_plan_code == resolved_plan_code and current_status in {"active", "trialing"}:
                _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), requested_plan=requested_plan, resolved_plan_code=resolved_plan_code, final_status="error", error_code="plan_already_active", duration_ms=_elapsed_ms_since(started_perf), http_status=409, **summarize_db_acquire_events(db_acquire_events))
                return jsonify(
                    {
                        "error": "Этот тариф уже активен. Используйте Stripe Portal для управления подпиской.",
                        "code": "plan_already_active",
                    }
                ), 409

            customer_started_at = time.perf_counter()
            stripe_customer_id = _get_or_create_stripe_customer_id(int(user_id), username=username)
            stripe_customer_duration_ms = int((time.perf_counter() - customer_started_at) * 1000)
            metadata = {"user_id": str(int(user_id)), "plan_code": resolved_plan_code}
            subscription_data: dict = {"metadata": dict(metadata)}
            checkout_state = "new_subscription"
            switch_summary = {
                "active_count": 0,
                "cancel_scheduled_count": 0,
                "already_scheduled_count": 0,
                "failed_count": 0,
                "latest_period_end_ts": 0,
            }

            if current_plan_code != resolved_plan_code:
                switch_started_at = time.perf_counter()
                try:
                    switch_summary = _schedule_customer_active_subscriptions_for_period_end(
                        stripe_customer_id=stripe_customer_id,
                    )
                    current_period_end_ts = int(switch_summary.get("latest_period_end_ts") or 0)
                    now_ts = int(time.time())
                    if int(switch_summary.get("active_count") or 0) > 0 and current_period_end_ts > now_ts + 300:
                        subscription_data["trial_end"] = current_period_end_ts
                        checkout_state = "switch_at_period_end"
                except Exception as switch_exc:
                    logging.warning(
                        "billing switch pre-check failed user_id=%s customer=%s: %s",
                        user_id,
                        stripe_customer_id,
                        switch_exc,
                    )
                    if current_subscription_id and current_status in {"active", "trialing"}:
                        try:
                            current_sub = stripe.Subscription.retrieve(current_subscription_id)
                            current_sub_status = str(getattr(current_sub, "status", "") or current_sub.get("status") or "").strip().lower()
                            current_period_end_ts = int(
                                getattr(current_sub, "current_period_end", 0)
                                or current_sub.get("current_period_end")
                                or 0
                            )
                            now_ts = int(time.time())
                            if current_sub_status in {"active", "trialing"} and current_period_end_ts > now_ts + 300:
                                stripe.Subscription.modify(
                                    current_subscription_id,
                                    cancel_at_period_end=True,
                                    proration_behavior="none",
                                )
                                subscription_data["trial_end"] = current_period_end_ts
                                checkout_state = "switch_at_period_end"
                        except Exception as fallback_exc:
                            logging.warning(
                                "billing switch fallback failed user_id=%s sub_id=%s: %s",
                                user_id,
                                current_subscription_id,
                                fallback_exc,
                            )
                switch_duration_ms = int((time.perf_counter() - switch_started_at) * 1000)

            stripe_session_started_at = time.perf_counter()
            session = stripe.checkout.Session.create(
                mode="subscription",
                customer=stripe_customer_id,
                client_reference_id=str(int(user_id)),
                metadata=metadata,
                subscription_data=subscription_data,
                line_items=[{"price": stripe_price_id, "quantity": 1}],
                success_url=_build_billing_telegram_return_url("success", include_session_id=True),
                cancel_url=_build_billing_telegram_return_url("cancel"),
            )
            stripe_session_duration_ms = int((time.perf_counter() - stripe_session_started_at) * 1000)
            checkout_url = str(getattr(session, "url", "") or "")
            if not checkout_url:
                _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), requested_plan=requested_plan, resolved_plan_code=resolved_plan_code, final_status="error", error_code="missing_checkout_url", duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
                return jsonify({"error": "Stripe checkout session URL отсутствует"}), 500
            try:
                user_source_lang, user_target_lang, _profile = _get_user_language_pair(int(user_id))
                _billing_log_event_safe(
                    user_id=int(user_id),
                    action_type="stripe_checkout_session",
                    provider="stripe",
                    units_type="requests",
                    units_value=1.0,
                    source_lang=user_source_lang,
                    target_lang=user_target_lang,
                    idempotency_seed=f"stripe-checkout:{user_id}:{resolved_plan_code}:{int(time.time())}",
                    status="estimated",
                    metadata={
                        "plan_code": resolved_plan_code,
                        "checkout_state": checkout_state,
                        "switch_active_count": int(switch_summary.get("active_count") or 0),
                        "switch_cancel_scheduled_count": int(switch_summary.get("cancel_scheduled_count") or 0),
                        "switch_already_scheduled_count": int(switch_summary.get("already_scheduled_count") or 0),
                        "switch_failed_count": int(switch_summary.get("failed_count") or 0),
                        "switch_latest_period_end_ts": int(switch_summary.get("latest_period_end_ts") or 0),
                    },
                )
            except Exception:
                logging.debug("stripe checkout billing event skipped", exc_info=True)
            response_payload = {"url": checkout_url, "state": checkout_state, "plan_code": resolved_plan_code}
            _log_flow_observation(
                "billing_checkout",
                "checkout_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                requested_plan=requested_plan,
                resolved_plan_code=resolved_plan_code,
                checkout_state=checkout_state,
                auth_duration_ms=auth_duration_ms,
                resolve_plan_duration_ms=resolve_plan_duration_ms,
                stripe_customer_duration_ms=stripe_customer_duration_ms,
                switch_duration_ms=switch_duration_ms,
                stripe_session_duration_ms=stripe_session_duration_ms,
                response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
                final_status="success",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=200,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify(response_payload), 200
        except ValueError as exc:
            _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), requested_plan=requested_plan, final_status="error", error_code="invalid_plan", resolve_plan_duration_ms=resolve_plan_duration_ms, duration_ms=_elapsed_ms_since(started_perf), http_status=400, **summarize_db_acquire_events(db_acquire_events))
            return _сбой_запроса(exc, что="запрос", код=400)
        except Exception as exc:
            logging.exception("create checkout session failed user_id=%s: %s", user_id, exc)
            _log_flow_observation("billing_checkout", "checkout_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), requested_plan=requested_plan, final_status="error", error_code=exc.__class__.__name__, resolve_plan_duration_ms=resolve_plan_duration_ms, stripe_customer_duration_ms=stripe_customer_duration_ms, switch_duration_ms=switch_duration_ms, stripe_session_duration_ms=stripe_session_duration_ms, duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": f"Не удалось создать checkout session: {exc}"}), 500


@app.route("/api/billing/create-portal-session", methods=["POST"])
def create_billing_portal_session():
    # Stripe retired → no billing portal. Stars subscriptions are managed in Telegram.
    if not STRIPE_BILLING_ENABLED:
        return jsonify({
            "error": "Подписка «Полный доступ» управляется прямо в Telegram (Настройки → Telegram Stars и подписки).",
            "error_code": "stripe_disabled",
        }), 403
    started_perf = time.perf_counter()
    request_id = _extract_observability_request_id()
    correlation_id = _build_observability_correlation_id(prefix="billing_portal")
    with db_acquire_scope("billing_portal") as db_acquire_events:
        auth_started_at = time.perf_counter()
        user_id, username, error = _get_authenticated_user_from_request_init_data()
        auth_duration_ms = int((time.perf_counter() - auth_started_at) * 1000)
        if error:
            status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
            _log_flow_observation("billing_portal", "portal_completed", request_id=request_id, correlation_id=correlation_id, final_status="error", error_code="auth_error", auth_duration_ms=auth_duration_ms, duration_ms=_elapsed_ms_since(started_perf), http_status=status, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": error}), status

        config_error = _require_stripe_config(require_webhook_secret=False)
        if config_error:
            _log_flow_observation("billing_portal", "portal_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), final_status="error", error_code="stripe_config", duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": config_error}), 500
        if not APP_BASE_URL:
            _log_flow_observation("billing_portal", "portal_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), final_status="error", error_code="missing_app_base_url", duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": "APP_BASE_URL не задан"}), 500

        stripe_customer_duration_ms = 0
        stripe_session_duration_ms = 0
        try:
            customer_started_at = time.perf_counter()
            stripe_customer_id = _get_or_create_stripe_customer_id(int(user_id), username=username)
            stripe_customer_duration_ms = int((time.perf_counter() - customer_started_at) * 1000)
            session_started_at = time.perf_counter()
            session = stripe.billing_portal.Session.create(
                customer=stripe_customer_id,
                return_url=_build_billing_telegram_return_url("portal"),
            )
            stripe_session_duration_ms = int((time.perf_counter() - session_started_at) * 1000)
            portal_url = str(getattr(session, "url", "") or "")
            if not portal_url:
                _log_flow_observation("billing_portal", "portal_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), final_status="error", error_code="missing_portal_url", duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
                return jsonify({"error": "Stripe portal session URL отсутствует"}), 500
            try:
                user_source_lang, user_target_lang, _profile = _get_user_language_pair(int(user_id))
                _billing_log_event_safe(
                    user_id=int(user_id),
                    action_type="stripe_portal_session",
                    provider="stripe",
                    units_type="requests",
                    units_value=1.0,
                    source_lang=user_source_lang,
                    target_lang=user_target_lang,
                    idempotency_seed=f"stripe-portal:{user_id}:{int(time.time())}",
                    status="estimated",
                    metadata={"customer_id": stripe_customer_id},
                )
            except Exception:
                logging.debug("stripe portal billing event skipped", exc_info=True)
            response_payload = {"url": portal_url}
            _log_flow_observation(
                "billing_portal",
                "portal_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                auth_duration_ms=auth_duration_ms,
                stripe_customer_duration_ms=stripe_customer_duration_ms,
                stripe_session_duration_ms=stripe_session_duration_ms,
                response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
                final_status="success",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=200,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify(response_payload), 200
        except Exception as exc:
            logging.exception("create portal session failed user_id=%s: %s", user_id, exc)
            _log_flow_observation("billing_portal", "portal_completed", request_id=request_id, correlation_id=correlation_id, user_id=int(user_id), final_status="error", error_code=exc.__class__.__name__, auth_duration_ms=auth_duration_ms, stripe_customer_duration_ms=stripe_customer_duration_ms, stripe_session_duration_ms=stripe_session_duration_ms, duration_ms=_elapsed_ms_since(started_perf), http_status=500, **summarize_db_acquire_events(db_acquire_events))
            return jsonify({"error": f"Не удалось создать portal session: {exc}"}), 500


@app.route("/billing/telegram-return", methods=["GET"])
def billing_telegram_return():
    state = str(request.args.get("state") or "").strip().lower()
    if state not in {"success", "cancel", "portal"}:
        state = "portal"
    session_id = str(request.args.get("session_id") or "").strip()
    web_fallback_url = _build_billing_webapp_return_url(
        state,
        session_id=session_id or None,
    )
    telegram_deeplink = _build_webapp_deeplink(_build_billing_telegram_start_param(state))
    escaped_telegram_deeplink = html.escape(telegram_deeplink, quote=True)
    escaped_web_fallback_url = html.escape(web_fallback_url, quote=True)
    escaped_state_title = html.escape(
        {
            "success": "Оплата завершена",
            "cancel": "Оплата отменена",
            "portal": "Возврат из Stripe Portal",
        }.get(state, "Возврат в приложение")
    )
    escaped_state_message = html.escape(
        {
            "success": "Открываю Mini App в Telegram, чтобы обновить статус подписки.",
            "cancel": "Открываю Mini App в Telegram, чтобы вы могли вернуться к подписке.",
            "portal": "Открываю Mini App в Telegram после Stripe Portal.",
        }.get(state, "Открываю приложение в Telegram.")
    )
    html_body = f"""<!doctype html>
<html lang="ru">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="robots" content="noindex,nofollow" />
    <title>{escaped_state_title}</title>
    <style>
      body {{
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        background: linear-gradient(180deg, #071120, #0f172a);
        color: #f8fafc;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }}
      .card {{
        width: min(92vw, 460px);
        padding: 28px 22px;
        border-radius: 22px;
        background: rgba(15, 23, 42, 0.92);
        border: 1px solid rgba(125, 211, 252, 0.22);
        box-shadow: 0 20px 60px rgba(2, 6, 23, 0.38);
      }}
      h1 {{
        margin: 0 0 10px;
        font-size: 24px;
      }}
      p {{
        margin: 0 0 18px;
        color: rgba(226, 232, 240, 0.8);
        line-height: 1.5;
      }}
      .actions {{
        display: grid;
        gap: 10px;
      }}
      .button {{
        display: inline-flex;
        justify-content: center;
        align-items: center;
        min-height: 46px;
        border-radius: 999px;
        text-decoration: none;
        font-weight: 600;
        border: 1px solid rgba(125, 211, 252, 0.28);
      }}
      .button-primary {{
        background: #22c55e;
        color: #04130a;
        border-color: transparent;
      }}
      .button-secondary {{
        background: rgba(15, 23, 42, 0.55);
        color: #f8fafc;
      }}
      .hint {{
        margin-top: 14px;
        font-size: 13px;
        color: rgba(226, 232, 240, 0.62);
      }}
    </style>
  </head>
  <body>
    <main class="card">
      <h1>{escaped_state_title}</h1>
      <p>{escaped_state_message}</p>
      <div class="actions">
        <a class="button button-primary" id="telegram-open-link" href="{escaped_telegram_deeplink}">Открыть Mini App в Telegram</a>
        <a class="button button-secondary" href="{escaped_web_fallback_url}">Открыть веб-версию</a>
      </div>
      <div class="hint">Если Telegram не открылся автоматически, нажмите кнопку вручную.</div>
    </main>
    <script>
      (function () {{
        var telegramUrl = {json.dumps(telegram_deeplink)};
        var didAttempt = false;
        function openTelegram() {{
          if (didAttempt) return;
          didAttempt = true;
          window.location.replace(telegramUrl);
        }}
        window.setTimeout(openTelegram, 120);
        document.getElementById('telegram-open-link')?.addEventListener('click', function () {{
          didAttempt = true;
        }});
      }})();
    </script>
  </body>
</html>"""
    return html_body, 200, {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
    }


@app.route("/api/webapp/wallet", methods=["POST"])
def wallet_get():
    """Audio-wallet balance + top-up options. Read-only hot path (single indexed
    SELECT, no write) so it is cheap to poll."""
    user_id, _username, error = _get_authenticated_user_from_request_init_data()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status
    balance_minor = get_audio_wallet_balance_minor(int(user_id))
    return jsonify({
        "ok": True,
        "balance_minor": int(balance_minor),
        "currency": "EUR",
        "min_topup_minor": int(AUDIO_MIN_TOPUP_MINOR),
        "max_topup_minor": int(AUDIO_TOPUP_MAX_MINOR),
        "topup_presets_minor": list(AUDIO_TOPUP_PRESETS_MINOR),
    })


@app.route("/api/webapp/wallet/topup", methods=["POST"])
def wallet_topup():
    """Create a Stripe checkout session (mode=payment) to add funds to the audio
    wallet. Uses dynamic price_data — no pre-created Stripe prices needed. The
    credit itself lands via the webhook (background), keeping this path light."""
    user_id, username, error = _get_authenticated_user_from_request_init_data()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status
    config_error = _require_stripe_config(require_webhook_secret=False)
    if config_error:
        return jsonify({"error": config_error}), 500
    if not APP_BASE_URL:
        return jsonify({"error": "APP_BASE_URL не задан"}), 500

    payload = request.get_json(silent=True) or {}
    try:
        amount_minor = int(payload.get("amount_minor") or 0)
    except (ValueError, TypeError):
        amount_minor = 0
    if amount_minor < AUDIO_MIN_TOPUP_MINOR:
        return jsonify({
            "error": f"Минимальная сумма пополнения — €{AUDIO_MIN_TOPUP_MINOR / 100:.2f}.",
            "error_code": "amount_too_small",
            "min_topup_minor": int(AUDIO_MIN_TOPUP_MINOR),
        }), 400
    if amount_minor > AUDIO_TOPUP_MAX_MINOR:
        return jsonify({
            "error": f"Максимальная сумма за раз — €{AUDIO_TOPUP_MAX_MINOR / 100:.2f}.",
            "error_code": "amount_too_large",
            "max_topup_minor": int(AUDIO_TOPUP_MAX_MINOR),
        }), 400

    try:
        stripe_customer_id = _get_or_create_stripe_customer_id(int(user_id), username=username)
        metadata = {"user_id": str(int(user_id)), "purpose": "audio_topup", "amount_minor": str(int(amount_minor))}
        session = stripe.checkout.Session.create(
            mode="payment",
            customer=stripe_customer_id,
            client_reference_id=str(int(user_id)),
            metadata=metadata,
            payment_intent_data={"metadata": dict(metadata)},
            line_items=[{
                "quantity": 1,
                "price_data": {
                    "currency": "eur",
                    "unit_amount": int(amount_minor),
                    "product_data": {"name": "Баланс озвучки — пополнение"},
                },
            }],
            success_url=_build_billing_telegram_return_url("success", include_session_id=True),
            cancel_url=_build_billing_telegram_return_url("cancel"),
        )
        checkout_url = str(getattr(session, "url", "") or "")
        if not checkout_url:
            return jsonify({"error": "Stripe checkout session URL отсутствует"}), 500
        return jsonify({"ok": True, "url": checkout_url, "amount_minor": int(amount_minor)})
    except Exception:
        logging.exception("wallet topup checkout failed user=%s", user_id)
        return jsonify({"error": "Не удалось создать оплату. Попробуйте ещё раз чуть позже."}), 500


@app.route("/api/billing/webhook", methods=["POST"])
def stripe_billing_webhook():
    # Stripe retired → acknowledge and ignore. Prevents any leftover/test-mode Stripe
    # event (e.g. a renewal) from granting or resurrecting Pro. 200 so Stripe won't retry.
    if not STRIPE_BILLING_ENABLED:
        return jsonify({"ok": True, "ignored": "stripe_disabled"}), 200
    config_error = _require_stripe_config(require_webhook_secret=True)
    if config_error:
        return jsonify({"error": config_error}), 500

    payload = request.get_data(cache=False, as_text=False)
    signature = request.headers.get("Stripe-Signature") or ""
    try:
        event = stripe.Webhook.construct_event(payload, signature, STRIPE_WEBHOOK_SECRET)
    except Exception as exc:
        return jsonify({"error": f"Webhook signature verification failed: {exc}"}), 400

    event_id = str(getattr(event, "id", "") or "")
    if not event_id:
        return jsonify({"error": "Stripe event.id отсутствует"}), 400

    event_type = str(getattr(event, "type", "") or "")
    data_object = _stripe_object_value(getattr(event, "data", None), "object", {}) or {}

    with get_db_connection_context() as db_conn:
        try:
            # Insert-first idempotency lock to avoid duplicate processing races.
            if not try_mark_stripe_event_processed(event_id, db_conn=db_conn):
                return jsonify({"ok": True, "duplicate": True}), 200

            if event_type == "checkout.session.completed":
                metadata = _stripe_object_value(data_object, "metadata", {}) or {}
                stripe_customer_id = str(_stripe_object_value(data_object, "customer", "") or "") or None
                stripe_subscription_id = str(_stripe_object_value(data_object, "subscription", "") or "") or None
                plan_code = _extract_plan_code_from_stripe_payload(data_object)
                user_id = _resolve_user_id_for_stripe_event(
                    metadata_user_id=_stripe_object_value(metadata, "user_id"),
                    client_reference_id=_stripe_object_value(data_object, "client_reference_id"),
                    stripe_customer_id=stripe_customer_id,
                    stripe_subscription_id=stripe_subscription_id,
                )
                if user_id is None:
                    logging.warning("checkout.session.completed user_id unresolved event_id=%s", event_id)
                    return jsonify({"ok": True, "ignored": "user_not_resolved"}), 200

                # Разовый донат (mode=payment) не создаёт подписку: фиксируем «спасибо»
                # в bt_3_sponsorships и НЕ трогаем user_subscriptions (доступ не меняется).
                session_mode = str(_stripe_object_value(data_object, "mode", "") or "").strip().lower()
                if session_mode == "payment":
                    try:
                        amount_total_minor = int(_stripe_object_value(data_object, "amount_total") or 0) or None
                    except Exception:
                        amount_total_minor = None
                    # Audio-wallet top-up (mode=payment, purpose=audio_topup): credit the
                    # prepaid balance. Idempotent on the checkout session id, so a
                    # replayed webhook is a safe no-op — no double credit.
                    purpose = str(_stripe_object_value(metadata, "purpose", "") or "").strip().lower()
                    if purpose == "audio_topup":
                        session_id = str(_stripe_object_value(data_object, "id", "") or "") or None
                        result = credit_audio_wallet(
                            user_id=int(user_id),
                            delta_minor=int(amount_total_minor or 0),
                            kind="topup",
                            note="stripe_topup",
                            stripe_checkout_session_id=session_id,
                        )
                        _invalidate_billing_front_caches_for_user(int(user_id))
                        return jsonify({"ok": True, "wallet_topup": True, "balance_minor": result.get("balance_minor")}), 200
                    record_sponsorship(
                        int(user_id),
                        plan_code,
                        amount_minor=amount_total_minor,
                        currency=str(_stripe_object_value(data_object, "currency", "") or "") or None,
                        display_name=str(_stripe_object_value(metadata, "display_name", "") or "") or None,
                        stripe_checkout_session_id=str(_stripe_object_value(data_object, "id", "") or "") or None,
                    )
                    _invalidate_billing_front_caches_for_user(int(user_id))
                    return jsonify({"ok": True, "support": True}), 200

                subscription_obj = {}
                if stripe_subscription_id:
                    try:
                        subscription_obj = stripe.Subscription.retrieve(stripe_subscription_id)
                        plan_code = _extract_plan_code_from_stripe_payload(subscription_obj, default=plan_code)
                    except Exception as exc:
                        logging.warning("subscription retrieve failed id=%s event_id=%s: %s", stripe_subscription_id, event_id, exc)
                _upsert_subscription_from_stripe_payload(
                    user_id=int(user_id),
                    plan_code=plan_code,
                    stripe_customer_id=stripe_customer_id,
                    stripe_subscription_id=stripe_subscription_id,
                    stripe_status=_stripe_object_value(subscription_obj, "status", "active") or "active",
                    current_period_end_ts=_stripe_object_value(subscription_obj, "current_period_end"),
                    db_conn=db_conn,
                )
                _invalidate_billing_front_caches_for_user(int(user_id))
                return jsonify({"ok": True}), 200

            if event_type in {"customer.subscription.created", "customer.subscription.updated", "customer.subscription.deleted"}:
                metadata = _stripe_object_value(data_object, "metadata", {}) or {}
                stripe_customer_id = str(_stripe_object_value(data_object, "customer", "") or "") or None
                stripe_subscription_id = str(_stripe_object_value(data_object, "id", "") or "") or None
                plan_code = _extract_plan_code_from_stripe_payload(data_object)
                user_id = _resolve_user_id_for_stripe_event(
                    metadata_user_id=_stripe_object_value(metadata, "user_id"),
                    client_reference_id=None,
                    stripe_customer_id=stripe_customer_id,
                    stripe_subscription_id=stripe_subscription_id,
                )
                if user_id is None:
                    logging.warning("%s user_id unresolved event_id=%s", event_type, event_id)
                    return jsonify({"ok": True, "ignored": "user_not_resolved"}), 200

                _upsert_subscription_from_stripe_payload(
                    user_id=int(user_id),
                    plan_code=plan_code,
                    stripe_customer_id=stripe_customer_id,
                    stripe_subscription_id=stripe_subscription_id,
                    stripe_status=_stripe_object_value(data_object, "status") or ("canceled" if event_type.endswith(".deleted") else "inactive"),
                    current_period_end_ts=_stripe_object_value(data_object, "current_period_end"),
                    db_conn=db_conn,
                )
                _invalidate_billing_front_caches_for_user(int(user_id))
                return jsonify({"ok": True}), 200

            if event_type in {"invoice.payment_succeeded", "invoice.payment_failed"}:
                metadata = _stripe_object_value(data_object, "metadata", {}) or {}
                stripe_customer_id = str(_stripe_object_value(data_object, "customer", "") or "") or None
                stripe_subscription_id = str(_stripe_object_value(data_object, "subscription", "") or "") or None
                plan_code = _extract_plan_code_from_stripe_payload(data_object)
                user_id = _resolve_user_id_for_stripe_event(
                    metadata_user_id=_stripe_object_value(metadata, "user_id"),
                    client_reference_id=None,
                    stripe_customer_id=stripe_customer_id,
                    stripe_subscription_id=stripe_subscription_id,
                )
                if user_id is None:
                    logging.warning("%s user_id unresolved event_id=%s", event_type, event_id)
                    return jsonify({"ok": True, "ignored": "user_not_resolved"}), 200

                subscription_obj = {}
                if stripe_subscription_id:
                    try:
                        subscription_obj = stripe.Subscription.retrieve(stripe_subscription_id)
                        plan_code = _extract_plan_code_from_stripe_payload(subscription_obj, default=plan_code)
                    except Exception as exc:
                        logging.warning("invoice subscription retrieve failed id=%s event_id=%s: %s", stripe_subscription_id, event_id, exc)

                fallback_status = "active" if event_type == "invoice.payment_succeeded" else "past_due"
                _upsert_subscription_from_stripe_payload(
                    user_id=int(user_id),
                    plan_code=plan_code,
                    stripe_customer_id=stripe_customer_id,
                    stripe_subscription_id=stripe_subscription_id,
                    stripe_status=_stripe_object_value(subscription_obj, "status", fallback_status) or fallback_status,
                    current_period_end_ts=_stripe_object_value(subscription_obj, "current_period_end"),
                    db_conn=db_conn,
                )
                _invalidate_billing_front_caches_for_user(int(user_id))
                if event_type == "invoice.payment_succeeded":
                    try:
                        invoice_amount_minor = int(
                            _stripe_object_value(data_object, "amount_paid")
                            or _stripe_object_value(data_object, "amount_due")
                            or 0
                        )
                    except Exception:
                        invoice_amount_minor = 0
                    if invoice_amount_minor > 0:
                        user_source_lang, user_target_lang, _profile = _get_user_language_pair(int(user_id))
                        _billing_log_stripe_payment_fee(
                            user_id=int(user_id),
                            source_lang=user_source_lang,
                            target_lang=user_target_lang,
                            event_id=event_id,
                            invoice_id=str(_stripe_object_value(data_object, "id", "") or ""),
                            amount_minor=invoice_amount_minor,
                            event_type=event_type,
                        )
                return jsonify({"ok": True}), 200

            return jsonify({"ok": True, "ignored": event_type}), 200
        except Exception as exc:
            db_conn.rollback()
            logging.exception("stripe webhook handling failed event_id=%s type=%s: %s", event_id, event_type, exc)
            return jsonify({"error": f"Webhook handling failed: {exc}"}), 500


