def _strip_html(html_text: str) -> str:
    """Strip HTML tags and decode entities from Wiktionary definition text."""
    import html as _html_module
    import re as _re
    text = _re.sub(r"<[^>]+>", " ", str(html_text or ""))
    text = _html_module.unescape(text)
    return " ".join(text.split()).strip()


def _fetch_wiktionary_entry(word: str) -> dict | None:
    """Fetch German entry from English Wiktionary REST API. Returns None on failure."""
    import urllib.request as _urlreq
    import urllib.parse as _urlparse
    import json as _json
    encoded = _urlparse.quote(word.strip(), safe="")
    url = f"https://en.wiktionary.org/api/rest_v1/page/definition/{encoded}"
    req = _urlreq.Request(url, headers={"User-Agent": "DeutschFlow/1.0"})
    try:
        with _urlreq.urlopen(req, timeout=6) as resp:
            data = _json.loads(resp.read())
    except Exception:
        return None
    de_entries = data.get("de") or []
    if not de_entries:
        return None
    entry = de_entries[0]
    pos = str(entry.get("partOfSpeech") or "").strip()
    definitions = entry.get("definitions") or []
    glosses_en: list[str] = []
    examples_de: list[str] = []
    for d in definitions[:5]:
        clean = _strip_html(d.get("definition") or "")
        if clean:
            glosses_en.append(clean)
        for ex in (d.get("examples") or [])[:2]:
            ex_clean = _strip_html(ex)
            if ex_clean:
                examples_de.append(ex_clean)
    return {
        "pos": pos,
        "glosses_en": glosses_en[:6],
        "examples_de": examples_de[:4],
    }


def _build_base_dict_result_from_entry(db_entry: dict, *, query_lang: str = "de", query_word: str = "") -> dict:
    """Convert a bt_base_dictionary row to the dictionaryResult format the frontend expects."""
    translations_ru = list(db_entry.get("translations_ru") or [])
    senses_json = db_entry.get("senses_json") or []
    forms_json = db_entry.get("forms_json") or {}
    ipa = str(db_entry.get("ipa") or "").strip()
    lemma = str(db_entry.get("lemma") or "").strip()
    article = str(db_entry.get("article") or "").strip()
    pos = str(db_entry.get("pos") or "").strip()
    translation_ru = ", ".join(t for t in translations_ru[:5] if t)
    display_word = f"{article} {lemma}".strip() if article else lemma
    normalized_query_lang = str(query_lang or "de").strip().lower() or "de"
    source_text = display_word
    target_text = translation_ru
    source_lang = str(db_entry.get("source_lang") or "de").strip().lower() or "de"
    target_lang = "ru"
    if normalized_query_lang == "ru":
        ru_query_fallback = translations_ru[0] if translations_ru else ""
        source_text = str(query_word or ru_query_fallback or "").strip() or translation_ru
        target_text = display_word
        source_lang = "ru"
        target_lang = "de"
    return {
        "word_de": display_word,
        "word_ru": translation_ru,
        "translation_de": lemma,
        "translation_ru": translation_ru,
        "source_text": source_text,
        "target_text": target_text,
        "source_lang": source_lang,
        "target_lang": target_lang,
        "part_of_speech": pos,
        "article": article,
        "forms": forms_json,
        "pronunciation": {"ipa": ipa} if ipa else {},
        "usage_examples": [
            {"source": s.get("example_de") or "", "target": s.get("example_ru") or ""}
            for s in senses_json
            if s.get("example_de") or s.get("example_ru")
        ][:4],
        "dictionary_senses": [
            {
                "value": s.get("gloss_en") or "",
                "translation_ru": s.get("gloss_ru") or "",
            }
            for s in senses_json
            if s.get("gloss_en") or s.get("gloss_ru")
        ],
        "provider": "base_dict",
        "is_base_dict": True,
        "wikt_fetched": bool(db_entry.get("wikt_fetched")),
        "quick_mode": False,
    }


def _base_dict_core_seed(*, word: str, query_source_lang: str, query_target_lang: str) -> dict | None:
    """Stand in for the CORE GPT dictionary call using our bundled DE↔RU dictionaries
    (FreeDict → WikDict). Returns a payload shaped EXACTLY like
    _run_dictionary_core_lookup_sync ({item, raw, direction, usage, gateway_path}) so the
    caller's enrichment + response path is reused unchanged — or None on a miss. The `raw`
    carries only fields we can trust from the base row (translation/article/pos/forms);
    the background GPT enrichment fills the rich fields and may CORRECT the translation."""
    q = str(word or "").strip()
    if not q:
        return None
    qsl = str(query_source_lang or "").strip().lower()
    qtl = str(query_target_lang or "").strip().lower()
    try:
        if qsl == "ru":
            entry = lookup_base_dictionary_entry_by_translation(q, "de") or lookup_wiktionary_entry_by_translation(q, "de")
        else:
            entry = lookup_base_dictionary_entry(q, "de") or lookup_wiktionary_entry(q, "de")
    except Exception:
        logging.debug("base-dict core seed lookup failed word=%r", q, exc_info=True)
        return None
    if not entry or not entry.get("translations_ru"):
        return None
    item = _build_base_dict_result_from_entry(entry, query_lang=qsl or "de", query_word=q)
    lemma = str(entry.get("lemma") or "").strip()
    article = str(entry.get("article") or "").strip()
    display = f"{article} {lemma}".strip() if article else lemma
    translations_ru = [t for t in (entry.get("translations_ru") or []) if t]
    first_ru = translations_ru[0] if translations_ru else ""
    if qsl == "ru":
        word_source, word_target = q, display
    else:
        word_source, word_target = (display or lemma), first_ru
    raw = {
        "detected_language": "source",
        "word_source": word_source,
        "word_target": word_target,
        "part_of_speech": str(entry.get("pos") or "").strip(),
        "article": article,
        "forms": entry.get("forms_json") if isinstance(entry.get("forms_json"), dict) else {},
    }
    return {
        "item": item,
        "raw": raw,
        "direction": f"{qsl}-{qtl}",
        "usage": None,
        "gateway_path": "base_dict",
    }


@app.route("/api/webapp/dictionary/examples", methods=["POST"])
def get_dictionary_corpus_examples():
    """Живые примеры из корпуса для одного слова — отдельным запросом.

    Зачем отдельно. Быстрый перевод — это гонка обычных переводчиков, карточки разбора
    там нет вовсе, поэтому примеры некуда было положить. Владелец 10.08.2026 ждал их
    именно на быстром экране, в обоих словарях: «сначала покажем перевод, а потом,
    как подгрузится, — живые примеры».

    Так и сделано: перевод не ждёт этого запроса ни секунды, блок появляется следом.
    Модель здесь не участвует — это чтение своей таблицы, ~57 мс, денег не стоит.
    """
    payload = request.get_json(silent=True) or {}
    word = str(payload.get("word") or "").strip()
    if not word:
        return jsonify({"items": []})
    if not _resolve_webapp_user_id(payload):
        return jsonify({"error": "Не удалось определить пользователя"}), 401
    try:
        from backend.corpus_examples import examples_for_word
        # Часть речи приходит с экрана — от той статьи, которую человек выбрал. Без
        # неё корпус путает слова с одинаковым написанием: на «die Wehe» (схватка)
        # он отдавал «Wehe den Besiegten» — Горе побеждённым.
        items = examples_for_word(word, limit=2, pos=str(payload.get("pos") or "").strip())
    except Exception:
        logging.debug("корпусные примеры не отдались", exc_info=True)
        items = []
    return jsonify({"items": items})


@app.route("/api/webapp/dictionary/base-lookup", methods=["POST"])
def base_dictionary_lookup():
    ensure_webapp_tables()
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    word = str(payload.get("word") or "").strip()
    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not word:
        return jsonify({"error": "word обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    requested_source_lang = str(payload.get("source_lang") or "").strip().lower()
    query_lang = requested_source_lang or ("ru" if re.search(r"[А-Яа-яЁё]", word) else "de")

    # 1. Check FreeDict base table first
    if query_lang == "ru":
        db_entry = lookup_base_dictionary_entry_by_translation(word, "de")
    else:
        db_entry = lookup_base_dictionary_entry(word, "de")
    if db_entry and db_entry.get("translations_ru"):
        return jsonify({
            "item": _build_base_dict_result_from_entry(db_entry, query_lang=query_lang, query_word=word),
            "source": "freedict",
            "query_lang": query_lang,
            "direction": "ru-de" if query_lang == "ru" else "de-ru",
        })

    # 2. Fall back to WikDict extended table
    try:
        if query_lang == "ru":
            wikt_entry = lookup_wiktionary_entry_by_translation(word, "de")
        else:
            wikt_entry = lookup_wiktionary_entry(word, "de")
        if wikt_entry and wikt_entry.get("translations_ru"):
            return jsonify({
                "item": _build_base_dict_result_from_entry(wikt_entry, query_lang=query_lang, query_word=word),
                "source": "wikdict",
                "query_lang": query_lang,
                "direction": "ru-de" if query_lang == "ru" else "de-ru",
            })
    except Exception:
        pass

    try:
        seed_state = get_base_dictionary_seed_state("de")
        if not bool(seed_state.get("seed_complete")):
            _start_freedict_autoseed_if_needed()
            return jsonify({
                "not_found": True,
                "warming_up": True,
                "query_lang": query_lang,
                "seed_complete": False,
                "seed_entry_count": int(seed_state.get("entry_count") or 0),
            }), 202
    except Exception:
        pass

    # Word not found in either dictionary
    return jsonify({"not_found": True, "query_lang": query_lang})


@app.route("/api/webapp/dictionary/offline-pack", methods=["GET"])
def dictionary_offline_pack():
    ensure_webapp_tables()
    import json as _json
    source_lang = str(request.args.get("lang") or "de").strip() or "de"
    limit = min(int(request.args.get("limit") or 10000), 30000)
    rows = list_combined_dictionary_for_offline_pack(source_lang=source_lang, limit=limit)
    pack = [
        {
            "w": r["lemma"],
            "k": r["lemma_key"],
            "p": r["pos"] or "",
            "a": r["article"] or "",
            "ru": list(r["translations_ru"] or [])[:4],
            "en": list(r["glosses_en"] or [])[:2],
        }
        for r in rows
    ]
    body = _json.dumps({"count": len(pack), "entries": pack}, ensure_ascii=False)
    return app.response_class(
        response=body,
        status=200,
        mimetype="application/json",
    )


@app.route("/api/mobile/dictionary/lookup", methods=["POST"])
def lookup_mobile_dictionary():
    user_id, _username, error = _get_mobile_authenticated_user()
    if error:
        return error

    payload = request.get_json(silent=True) or {}
    word = (payload.get("word") or "").strip()
    if not word:
        return jsonify({"error": "word обязателен"}), 400

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    # Дверь и здесь: этот маршрут тоже уходил в модель с тем написанием, которое пришло.
    # Правило то же — вычитка только после промаха нашего словаря, то есть ровно там,
    # где мы всё равно собираемся платить за разбор.
    _query_source = source_lang if not _is_legacy_ru_de_pair(source_lang, target_lang) else (
        "ru" if any("а" <= ch.lower() <= "я" or ch.lower() == "ё" for ch in word) else "de"
    )
    _, word = _dictionary_hit_or_corrected_word(
        word=word,
        source_lang=_query_source,
        target_lang=("de" if _query_source == "ru" else "ru"),
        user_id=int(user_id),
    )

    try:
        if _is_legacy_ru_de_pair(source_lang, target_lang):
            is_ru = any("а" <= ch.lower() <= "я" or ch.lower() == "ё" for ch in word)
            if is_ru:
                cached = get_dictionary_cache(word)
                if cached:
                    cached_item = _decorate_dictionary_item(
                        cached if isinstance(cached, dict) else {},
                        source_lang=source_lang,
                        target_lang=target_lang,
                        direction="ru-de",
                    )
                    return jsonify(
                        {
                            "ok": True,
                            "item": cached_item,
                            "direction": "ru-de",
                            "user_id": user_id,
                            "language_pair": _build_language_pair_payload(source_lang, target_lang),
                        }
                    )
                result = asyncio.run(run_dictionary_lookup(word))
            else:
                result = asyncio.run(run_dictionary_lookup_de(word))
            if result and is_ru:
                upsert_dictionary_cache(word, result)
            direction = "ru-de" if is_ru else "de-ru"
        else:
            raw = asyncio.run(
                run_dictionary_lookup_multilang(
                    word=word,
                    source_lang=source_lang,
                    target_lang=target_lang,
                )
            )
            result, detected, source_value, target_value = _build_multilang_dictionary_result(
                raw=raw,
                query_word=word,
                source_lang=source_lang,
                target_lang=target_lang,
            )
            direction = f"{source_lang}-{target_lang}" if detected != "target" else f"{target_lang}-{source_lang}"

            if not source_value or source_value.casefold() == target_value.casefold():
                if DICTIONARY_ENABLE_REVERSE_LLM_FALLBACK:
                    reverse_raw = asyncio.run(
                        run_dictionary_lookup_multilang(
                            word=word,
                            source_lang=target_lang,
                            target_lang=source_lang,
                        )
                    )
                    reverse_target = str(reverse_raw.get("word_target") or "").strip()
                    if reverse_target and reverse_target.casefold() != source_value.casefold():
                        result["target_text"] = reverse_target
                        result["translation_de"] = reverse_target
                        result["word_de"] = reverse_target
                        target_value = reverse_target
                if not target_value or target_value.casefold() == source_value.casefold():
                    forced = _force_translate_text(
                        text=word,
                        source_lang=source_lang,
                        target_lang=target_lang,
                    )
                    if forced and forced.casefold() != source_value.casefold():
                        result["target_text"] = forced
                        result["translation_de"] = forced
                        result["word_de"] = forced
                        target_value = forced
    except Exception as exc:
        return jsonify({"error": f"Ошибка запроса словаря: {exc}"}), 500

    result = _decorate_dictionary_item(
        result if isinstance(result, dict) else {},
        source_lang=source_lang,
        target_lang=target_lang,
        direction=direction,
    )
    return jsonify(
        {
            "ok": True,
            "item": result,
            "direction": direction,
            "user_id": user_id,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


@app.route("/api/mobile/dashboard", methods=["GET"])
def get_mobile_dashboard():
    user_id, _username, error = _get_mobile_authenticated_user()
    if error:
        return error

    now_utc = datetime.now(timezone.utc)
    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    try:
        queue_info = _compute_srs_queue_info(
            user_id=user_id,
            now_utc=now_utc,
            source_lang=source_lang,
            target_lang=target_lang,
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка чтения SRS-статистики: {exc}"}), 500

    word_of_day = None
    try:
        latest_items = get_webapp_dictionary_entries(
            user_id=user_id,
            limit=1,
            source_lang=source_lang,
            target_lang=target_lang,
        )
        if latest_items:
            item = latest_items[0] or {}
            response_json = item.get("response_json") if isinstance(item.get("response_json"), dict) else {}
            source_word = (
                item.get("word_de")
                or item.get("word_ru")
                or response_json.get("word_de")
                or response_json.get("word_ru")
            )
            target_translation = (
                item.get("translation_ru")
                or item.get("translation_de")
                or response_json.get("translation_ru")
                or response_json.get("translation_de")
            )
            word_of_day = {
                "entry_id": item.get("id"),
                "source": source_word,
                "target": target_translation,
                "created_at": item.get("created_at"),
            }
    except Exception:
        word_of_day = None

    return jsonify(
        {
            "ok": True,
            "queue_info": {
                "due_count": int(queue_info.get("due_count") or 0),
                "new_remaining_today": int(queue_info.get("new_remaining_today") or 0),
            },
            "word_of_day": word_of_day,
            "deep_links": {
                "review": _build_webapp_deeplink("review"),
                "webapp": _build_webapp_deeplink("webapp"),
            },
        }
    )


def _today_plan_snapshot_key(plan_date: date) -> str:
    return plan_date.isoformat()


def _skill_progress_snapshot_key(lookback_days: int) -> str:
    return f"{int(lookback_days)}d"


def _weekly_plan_snapshot_key(anchor_date: date | None = None) -> str:
    current_date = anchor_date or _get_local_today_date(TODAY_PLAN_DEFAULT_TZ)
    week_start = current_date - timedelta(days=int(current_date.weekday()))
    return week_start.isoformat()


def _plan_analytics_snapshot_key(
    *,
    period: str,
    week_start: date | None = None,
    as_of_date: date | None = None,
) -> str:
    normalized_period = str(period or "week").strip().lower() or "week"
    if normalized_period == "half_year":
        normalized_period = "half-year"
    week_part = week_start.isoformat() if isinstance(week_start, date) else "-"
    as_of_part = as_of_date.isoformat() if isinstance(as_of_date, date) else _get_local_today_date(TODAY_PLAN_DEFAULT_TZ).isoformat()
    return f"{normalized_period}:{week_part}:{as_of_part}"


def _recent_finish_session_cache_key(user_id: int) -> tuple[str, int]:
    return ("recent_finish_session", int(user_id))


def _recent_finish_session_redis_key(user_id: int) -> str:
    return f"webapp:recent_finish_session:{int(user_id)}"


def _remember_recent_finish_no_active_session(user_id: int) -> None:
    payload = {"type": "none", "session_id": None}
    _HOTPATH_RECENT_FINISH_SESSION_CACHE.put(
        _recent_finish_session_cache_key(int(user_id)),
        payload,
        fresh_ttl_sec=WEBAPP_RECENT_FINISH_SESSION_CACHE_TTL_SEC,
        stale_ttl_sec=WEBAPP_RECENT_FINISH_SESSION_CACHE_TTL_SEC,
    )
    client = get_redis_client()
    if client is None:
        return
    try:
        client.set(
            _recent_finish_session_redis_key(int(user_id)),
            json.dumps(payload, ensure_ascii=False),
            ex=int(WEBAPP_RECENT_FINISH_SESSION_CACHE_TTL_SEC),
        )
    except Exception:
        logging.warning(
            "Failed to persist recent finish session marker: user_id=%s",
            int(user_id),
            exc_info=True,
        )


def _clear_recent_finish_no_active_session(user_id: int) -> None:
    _HOTPATH_RECENT_FINISH_SESSION_CACHE.invalidate(_recent_finish_session_cache_key(int(user_id)))
    client = get_redis_client()
    if client is None:
        return
    try:
        client.delete(_recent_finish_session_redis_key(int(user_id)))
    except Exception:
        logging.warning(
            "Failed to clear recent finish session marker: user_id=%s",
            int(user_id),
            exc_info=True,
        )


def _get_recent_finish_no_active_session_with_source(user_id: int) -> tuple[dict[str, Any] | None, str | None]:
    redis_key = _recent_finish_session_redis_key(int(user_id))
    client = get_redis_client()
    cached = _HOTPATH_RECENT_FINISH_SESSION_CACHE.get(_recent_finish_session_cache_key(int(user_id)))
    if cached:
        payload = cached.get("payload")
        if isinstance(payload, dict):
            if client is None:
                return dict(payload), "hot"
            try:
                raw = client.get(redis_key)
            except Exception:
                logging.warning(
                    "Failed to verify recent finish session marker from Redis: user_id=%s",
                    int(user_id),
                    exc_info=True,
                )
                return dict(payload), "hot_unverified"
            if raw:
                return dict(payload), "hot_verified"
            _HOTPATH_RECENT_FINISH_SESSION_CACHE.invalidate(_recent_finish_session_cache_key(int(user_id)))
    if client is None:
        return None, None
    try:
        raw = client.get(redis_key)
    except Exception:
        logging.warning(
            "Failed to load recent finish session marker: user_id=%s",
            int(user_id),
            exc_info=True,
        )
        return None, None
    if not raw:
        return None, None
    try:
        payload = json.loads(raw)
    except Exception:
        return None, None
    if not isinstance(payload, dict):
        return None, None
    _HOTPATH_RECENT_FINISH_SESSION_CACHE.put(
        _recent_finish_session_cache_key(int(user_id)),
        payload,
        fresh_ttl_sec=WEBAPP_RECENT_FINISH_SESSION_CACHE_TTL_SEC,
        stale_ttl_sec=WEBAPP_RECENT_FINISH_SESSION_CACHE_TTL_SEC,
    )
    return dict(payload), "redis"


def _get_recent_finish_no_active_session(user_id: int) -> dict[str, Any] | None:
    payload, _source = _get_recent_finish_no_active_session_with_source(int(user_id))
    return payload


_PHASE1_PROJECTION_JOB_KIND = "phase1_projection_materialize"
_SESSION_PRESENCE_CARD_KIND = "session_presence_card"
_TODAY_CARD_KIND = "today_card"
_SKILLS_CARD_KIND = "skills_card"
_SESSION_PRESENCE_CARD_KEY = "current"
_SKILLS_CARD_DEFAULT_LOOKBACK_DAYS = 7
_SESSION_PRESENCE_CARD_FRESH_TTL_SEC = 300
_SESSION_PRESENCE_CARD_STALE_TTL_SEC = 86400
_TODAY_CARD_FRESH_TTL_SEC = 300
_TODAY_CARD_STALE_TTL_SEC = 86400
_SKILLS_CARD_FRESH_TTL_SEC = 300
_SKILLS_CARD_STALE_TTL_SEC = 86400


def _today_card_projection_key(plan_date: date | None) -> str:
    return _today_plan_snapshot_key(plan_date or _get_local_today_date(TODAY_PLAN_DEFAULT_TZ))


def _skills_card_projection_key(lookback_days: int | None) -> str:
    return _skill_progress_snapshot_key(int(lookback_days or _SKILLS_CARD_DEFAULT_LOOKBACK_DAYS))


def _projection_language_pair(
    payload: dict[str, Any] | None,
    *,
    fallback_source: str | None = None,
    fallback_target: str | None = None,
) -> tuple[str, str]:
    safe_payload = payload if isinstance(payload, dict) else {}
    language_pair = safe_payload.get("language_pair") if isinstance(safe_payload.get("language_pair"), dict) else {}
    source_lang = _normalize_short_lang_code(
        language_pair.get("source_lang") or fallback_source or "ru",
        fallback="ru",
    )
    target_lang = _normalize_short_lang_code(
        language_pair.get("target_lang") or fallback_target or "de",
        fallback="de",
    )
    return source_lang, target_lang


def _phase1_projection_ttls(snapshot_kind: str) -> tuple[int, int]:
    normalized_kind = str(snapshot_kind or "").strip()
    if normalized_kind == _SESSION_PRESENCE_CARD_KIND:
        return _SESSION_PRESENCE_CARD_FRESH_TTL_SEC, _SESSION_PRESENCE_CARD_STALE_TTL_SEC
    if normalized_kind == _TODAY_CARD_KIND:
        return _TODAY_CARD_FRESH_TTL_SEC, _TODAY_CARD_STALE_TTL_SEC
    return _SKILLS_CARD_FRESH_TTL_SEC, _SKILLS_CARD_STALE_TTL_SEC


def _store_phase1_projection(
    *,
    user_id: int,
    snapshot_kind: str,
    snapshot_key: str,
    payload: dict[str, Any],
    source_lang: str | None,
    target_lang: str | None,
    meta: dict[str, Any] | None = None,
    timing_breakdown: dict[str, int] | None = None,
) -> dict | None:
    store_started_perf = time.perf_counter()
    schema_ensure_started_perf = time.perf_counter()
    ensure_phase1_projection_schema()
    schema_ensure_duration_ms = int((time.perf_counter() - schema_ensure_started_perf) * 1000)
    ttls_started_perf = time.perf_counter()
    fresh_ttl_sec, stale_ttl_sec = _phase1_projection_ttls(snapshot_kind)
    ttls_duration_ms = int((time.perf_counter() - ttls_started_perf) * 1000)
    upsert_started_perf = time.perf_counter()
    snapshot = upsert_user_api_snapshot(
        user_id=int(user_id),
        snapshot_kind=snapshot_kind,
        snapshot_key=str(snapshot_key or "").strip(),
        payload=payload,
        source_lang=source_lang,
        target_lang=target_lang,
        meta=meta or {},
        fresh_ttl_seconds=fresh_ttl_sec,
        stale_ttl_seconds=stale_ttl_sec,
    )
    upsert_duration_ms = int((time.perf_counter() - upsert_started_perf) * 1000)
    redis_mirror_duration_ms = 0
    try:
        redis_mirror_started_perf = time.perf_counter()
        if snapshot_kind == _SESSION_PRESENCE_CARD_KIND:
            set_session_presence_card(int(user_id), payload)
        elif snapshot_kind == _TODAY_CARD_KIND:
            set_today_card(int(user_id), str(snapshot_key or "").strip(), payload)
        elif snapshot_kind == _SKILLS_CARD_KIND:
            set_skills_card(int(user_id), str(snapshot_key or "").strip(), payload)
        redis_mirror_duration_ms = int((time.perf_counter() - redis_mirror_started_perf) * 1000)
    except Exception:
        redis_mirror_duration_ms = int((time.perf_counter() - redis_mirror_started_perf) * 1000)
        logging.warning(
            "Phase1 projection Redis mirror update failed: kind=%s user_id=%s key=%s",
            snapshot_kind,
            int(user_id),
            str(snapshot_key or "").strip(),
            exc_info=True,
        )
    if isinstance(timing_breakdown, dict):
        total_duration_ms = int((time.perf_counter() - store_started_perf) * 1000)
        timing_breakdown["phase1_schema_ensure_ms"] = schema_ensure_duration_ms
        timing_breakdown["phase1_ttls_ms"] = ttls_duration_ms
        timing_breakdown["upsert_user_api_snapshot_ms"] = upsert_duration_ms
        timing_breakdown["set_projection_card_ms"] = redis_mirror_duration_ms
        timing_breakdown["other_ms"] = max(
            0,
            total_duration_ms
            - schema_ensure_duration_ms
            - ttls_duration_ms
            - upsert_duration_ms
            - redis_mirror_duration_ms,
        )
    return snapshot


def _build_session_presence_card_payload(
    *,
    user_id: int,
    state: str,
    source_lang: str,
    target_lang: str,
    session_id: str | None = None,
    session_type: str = "regular",
    finished_session_id: str | None = None,
    finished_at: str | None = None,
    translated_count: int | None = None,
    total_sentences: int | None = None,
    recent_finish_until_ms: int | None = None,
) -> dict[str, Any]:
    return {
        "user_id": int(user_id),
        "projection_status": "ready",
        "state": str(state or "").strip().lower() or "none",
        "session_type": str(session_type or "").strip().lower() or None,
        "session_id": str(session_id or "").strip() or None,
        "source_lang": _normalize_short_lang_code(source_lang, fallback="ru"),
        "target_lang": _normalize_short_lang_code(target_lang, fallback="de"),
        "finished_session_id": str(finished_session_id or "").strip() or None,
        "finished_at": str(finished_at or "").strip() or None,
        "translated_count": int(translated_count) if translated_count is not None else None,
        "total_sentences": int(total_sentences) if total_sentences is not None else None,
        "recent_finish_until_ms": int(recent_finish_until_ms) if recent_finish_until_ms is not None else None,
        "updated_at_ms": int(time.time() * 1000),
    }


def _build_today_card_payload_from_today_snapshot(
    *,
    user_id: int,
    plan_date: date,
    today_snapshot: dict[str, Any],
    card_version: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    snapshot_payload = dict((today_snapshot or {}).get("payload") or {})
    source_lang, target_lang = _projection_language_pair(
        snapshot_payload,
        fallback_source=today_snapshot.get("source_lang") if isinstance(today_snapshot, dict) else None,
        fallback_target=today_snapshot.get("target_lang") if isinstance(today_snapshot, dict) else None,
    )
    items_payload = []
    for item in list(snapshot_payload.get("items") or []):
        if not isinstance(item, dict):
            continue
        item_payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
        card_item = {
            "id": int(item.get("id") or 0),
            "task_type": str(item.get("task_type") or "").strip() or None,
            "title": str(item.get("title") or "").strip(),
            "status": str(item.get("status") or "todo").strip().lower() or "todo",
            "estimated_minutes": int(item.get("estimated_minutes") or 0),
            "start_action": str(item_payload.get("start_action") or "").strip() or None,
        }
        if card_item["task_type"] == "translation":
            card_item.update(
                {
                    "source_session_id": str(item_payload.get("source_session_id") or "").strip() or None,
                    "translation_target_count": int(item_payload.get("translation_target_count") or 0),
                    "translation_completed_count": int(item_payload.get("translation_completed_count") or 0),
                    "translation_progress_percent": float(item_payload.get("translation_progress_percent") or 0.0),
                }
            )
        items_payload.append(card_item)
    payload = {
        "user_id": int(user_id),
        "projection_status": "ready",
        "plan_date": plan_date.isoformat(),
        "source_lang": source_lang,
        "target_lang": target_lang,
        "card_version": str(card_version or "").strip() or None,
        "updated_at": str((today_snapshot or {}).get("refreshed_at") or datetime.now(timezone.utc).isoformat()),
        "total_minutes": int(snapshot_payload.get("total_minutes") or 0),
        "items_count": len(items_payload),
        "items": items_payload,
    }
    meta = {
        "projection_status": "ready",
        "card_version": payload.get("card_version"),
        "source_snapshot_kind": "today_plan",
        "source_snapshot_key": _today_plan_snapshot_key(plan_date),
    }
    return payload, meta


