def _refresh_today_plan_snapshot_now(*, user_id: int, username: str | None, plan_date: date) -> dict | None:
    snapshot_key = _today_plan_snapshot_key(plan_date)
    front_key = ("today_plan", int(user_id), snapshot_key)
    with db_acquire_scope("today_plan_finish_seed"):
        response_payload, meta = _build_today_plan_response_payload(
            user_id=int(user_id),
            username=username,
            plan_date=plan_date,
        )
        snapshot = upsert_user_api_snapshot(
            user_id=int(user_id),
            snapshot_kind="today_plan",
            snapshot_key=snapshot_key,
            payload=response_payload,
            source_lang=str(meta.get("source_lang") or "").strip() or None,
            target_lang=str(meta.get("target_lang") or "").strip() or None,
            meta=meta,
            fresh_ttl_seconds=TODAY_PLAN_SNAPSHOT_FRESH_TTL_SEC,
            stale_ttl_seconds=TODAY_PLAN_SNAPSHOT_STALE_TTL_SEC,
        )
        _store_snapshot_in_front_cache(
            _HOTPATH_TODAY_CACHE,
            front_key=front_key,
            snapshot=snapshot,
            fresh_ttl_sec=TODAY_PLAN_SNAPSHOT_FRESH_TTL_SEC,
            stale_ttl_sec=TODAY_PLAN_SNAPSHOT_STALE_TTL_SEC,
        )
        return snapshot


def _refresh_skill_progress_snapshot_now(*, user_id: int, username: str | None, lookback_days: int) -> dict | None:
    snapshot_key = _skill_progress_snapshot_key(lookback_days)
    front_key = ("skill_progress", int(user_id), snapshot_key)
    started_perf = time.perf_counter()
    meta: dict[str, Any] = {}
    final_status = "success"
    error_code: str | None = None
    with db_acquire_scope("skill_progress_finish_seed") as db_acquire_events:
        try:
            response_payload, meta = _build_skill_progress_response_payload(
                user_id=int(user_id),
                username=username,
                lookback_days=int(lookback_days),
            )
            snapshot = upsert_user_api_snapshot(
                user_id=int(user_id),
                snapshot_kind="skill_progress",
                snapshot_key=snapshot_key,
                payload=response_payload,
                source_lang=str(meta.get("source_lang") or "").strip() or None,
                target_lang=str(meta.get("target_lang") or "").strip() or None,
                meta=meta,
                fresh_ttl_seconds=SKILL_PROGRESS_SNAPSHOT_FRESH_TTL_SEC,
                stale_ttl_seconds=SKILL_PROGRESS_SNAPSHOT_STALE_TTL_SEC,
            )
            _store_snapshot_in_front_cache(
                _HOTPATH_SKILL_PROGRESS_CACHE,
                front_key=front_key,
                snapshot=snapshot,
                fresh_ttl_sec=SKILL_PROGRESS_SNAPSHOT_FRESH_TTL_SEC,
                stale_ttl_sec=SKILL_PROGRESS_SNAPSHOT_STALE_TTL_SEC,
            )
            return snapshot
        except Exception as exc:
            final_status = "error"
            error_code = exc.__class__.__name__
            raise
        finally:
            _log_flow_observation(
                "skill_progress_snapshot",
                "finish_seed_completed",
                user_id=int(user_id),
                snapshot_key=snapshot_key,
                lookback_days=int(lookback_days),
                executor_thread=threading.current_thread().name,
                final_status=final_status,
                error_code=error_code,
                duration_ms=_elapsed_ms_since(started_perf),
                **{k: v for k, v in meta.items() if k not in ("lookback_days", "final_status")},
                **summarize_db_acquire_events(db_acquire_events),
            )


def _refresh_post_finish_user_critical_snapshots(
    *,
    user_id: int,
    username: str | None,
    plan_date: date,
    lookback_days: int,
) -> dict[str, bool | int]:
    refreshed = {
        "today": False,
        "skills": False,
        "today_duration_ms": 0,
        "skills_duration_ms": 0,
        "today_snapshot": None,
        "skills_snapshot": None,
    }

    today_started_perf = time.perf_counter()
    refreshed["today_snapshot"] = _refresh_today_plan_snapshot_now(
        user_id=int(user_id),
        username=username,
        plan_date=plan_date,
    )
    refreshed["today"] = True
    refreshed["today_duration_ms"] = int((time.perf_counter() - today_started_perf) * 1000)

    skills_started_perf = time.perf_counter()
    refreshed["skills_snapshot"] = _refresh_skill_progress_snapshot_now(
        user_id=int(user_id),
        username=username,
        lookback_days=int(lookback_days),
    )
    refreshed["skills"] = True
    refreshed["skills_duration_ms"] = int((time.perf_counter() - skills_started_perf) * 1000)

    return refreshed


def _prime_webapp_home_snapshots_async(*, user_id: int, username: str | None) -> None:
    """Warm visible home-screen snapshots only when missing or stale."""
    try:
        plan_date = _get_local_today_date(TODAY_PLAN_DEFAULT_TZ)
        _maybe_prime_today_plan_snapshot_refresh(
            user_id=int(user_id),
            username=username,
            plan_date=plan_date,
        )
        # NOT priming skill-progress here: it is a heavy, rarely-opened dashboard, so warming
        # it on every app-open (bootstrap) wastes DB work for a screen most sessions never
        # visit. It refreshes lazily on actual view (_get_skill_progress_response_cached /
        # POST /api/progress/skills/sync). today + weekly ARE on the home screen → keep warm.
        _maybe_prime_weekly_plan_snapshot_refresh(
            user_id=int(user_id),
            anchor_date=plan_date,
        )
    except Exception:
        logging.warning("Failed to prime webapp home snapshots: user_id=%s", user_id, exc_info=True)


def _get_today_plan_response_cached(
    *,
    user_id: int,
    username: str | None,
    plan_date: date,
) -> tuple[dict, dict]:
    snapshot_key = _today_plan_snapshot_key(plan_date)
    front_key = ("today_plan", int(user_id), snapshot_key)
    fresh_front = _HOTPATH_TODAY_CACHE.get(front_key)
    if fresh_front is not None:
        return (
            dict(fresh_front.get("payload") or {}),
            {
                "_db_acquire_events": [],
                "cache_hit": True,
                "cache_tier": "front",
                "cache_state": "fresh",
                "snapshot_age_ms": _snapshot_age_ms({"refreshed_at": fresh_front.get("meta", {}).get("_snapshot_refreshed_at")}),
                **(fresh_front.get("meta") or {}),
            },
        )

    stale_front = _HOTPATH_TODAY_CACHE.get(front_key, allow_stale=True)
    if stale_front is not None:
        _schedule_today_plan_snapshot_refresh(user_id=int(user_id), username=username, plan_date=plan_date)
        return (
            dict(stale_front.get("payload") or {}),
            {
                "_db_acquire_events": [],
                "cache_hit": True,
                "cache_tier": "front",
                "cache_state": "stale",
                "snapshot_age_ms": _snapshot_age_ms({"refreshed_at": stale_front.get("meta", {}).get("_snapshot_refreshed_at")}),
                **(stale_front.get("meta") or {}),
            },
        )

    with db_acquire_scope("today_plan") as db_acquire_events:
        snapshot = get_user_api_snapshot(
            user_id=int(user_id),
            snapshot_kind="today_plan",
            snapshot_key=snapshot_key,
        )
    if isinstance(snapshot, dict):
        _store_snapshot_in_front_cache(
            _HOTPATH_TODAY_CACHE,
            front_key=front_key,
            snapshot=snapshot,
            fresh_ttl_sec=TODAY_PLAN_SNAPSHOT_FRESH_TTL_SEC,
            stale_ttl_sec=TODAY_PLAN_SNAPSHOT_STALE_TTL_SEC,
        )
        if _snapshot_is_fresh(snapshot):
            return (
                dict(snapshot.get("payload") or {}),
                {
                    "_db_acquire_events": db_acquire_events,
                    "cache_hit": True,
                    "cache_tier": "db_snapshot",
                    "cache_state": "fresh",
                    "snapshot_age_ms": _snapshot_age_ms(snapshot),
                    **(snapshot.get("meta") or {}),
                },
            )
        if _snapshot_is_servable_stale(snapshot):
            _schedule_today_plan_snapshot_refresh(user_id=int(user_id), username=username, plan_date=plan_date)
            return (
                dict(snapshot.get("payload") or {}),
                {
                    "_db_acquire_events": db_acquire_events,
                    "cache_hit": True,
                    "cache_tier": "db_snapshot",
                    "cache_state": "stale",
                    "snapshot_age_ms": _snapshot_age_ms(snapshot),
                    **(snapshot.get("meta") or {}),
                },
            )

    _schedule_today_plan_snapshot_refresh(
        user_id=int(user_id),
        username=username,
        plan_date=plan_date,
    )
    response_payload, meta = _build_today_plan_snapshot_pending_payload(
        user_id=int(user_id),
        username=username,
        plan_date=plan_date,
    )
    return (
        response_payload,
        {
            "_db_acquire_events": db_acquire_events,
            **meta,
        },
    )


