def _mistake_row_to_api(m: dict) -> dict:
    """Map a bt_3_voice_session_mistakes row to the public API shape."""
    return {
        "category": m.get("error_category"),
        "subcategory": m.get("error_subtype"),
        "severity": m.get("severity"),
        "user_quote": m.get("user_quote"),
        "corrected_form": m.get("corrected_form"),
        "rule_explanation": m.get("rule_explanation"),
        "alternatives": m.get("alternatives") or [],
        "grammar_confidence": m.get("grammar_confidence"),
        "transcript_confidence": m.get("transcript_confidence"),
        "is_recurring": bool(m.get("is_recurring") or False),
    }


@app.route("/api/assistant/session/complete", methods=["POST"])
def complete_assistant_session():
    user_id, _username, error = _get_authenticated_user_from_request_init_data()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status
    payload = request.get_json(silent=True) or {}
    session_id_raw = payload.get("session_id")
    session_id = None
    if session_id_raw is not None and str(session_id_raw).strip() != "":
        try:
            session_id = int(session_id_raw)
        except Exception:
            return jsonify({"error": "session_id должен быть числом"}), 400
    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))
    try:
        session = finish_agent_voice_session(
            user_id=int(user_id),
            session_id=session_id,
            source_lang=source_lang,
            target_lang=target_lang,
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка завершения голосовой сессии: {exc}"}), 500
    assessment_payload = None
    mistakes_payload = []
    if isinstance(session, dict):
        duration_seconds = max(0, int(session.get("duration_seconds") or 0))
        session_minutes = duration_seconds / 60.0
        resolved_session_id = int(session.get("session_id") or (session_id or 0))
        if resolved_session_id > 0:
            # Extraction runs first so assessment can aggregate from mistakes table.
            try:
                asyncio.run(
                    extract_and_store_voice_mistakes(session_id=resolved_session_id)
                )
            except Exception as exc:
                logging.warning(
                    "Voice mistake extraction failed for session_id=%s: %s",
                    resolved_session_id,
                    exc,
                )
            try:
                assessment = asyncio.run(
                    build_and_store_voice_assessment(session_id=resolved_session_id)
                )
                if assessment:
                    logging.info(
                        "Voice session assessment persisted for session_id=%s",
                        resolved_session_id,
                    )
            except Exception as exc:
                logging.warning(
                    "Voice session assessment persistence failed for session_id=%s: %s",
                    resolved_session_id,
                    exc,
                )
            try:
                bridge_result = apply_voice_skill_bridge(session_id=resolved_session_id)
                logging.info(
                    "Voice skill bridge finished for session_id=%s applied=%s notes=%s",
                    resolved_session_id,
                    bool(bridge_result.applied),
                    bridge_result.notes,
                )
            except Exception as exc:
                logging.warning(
                    "Voice skill bridge failed for session_id=%s: %s",
                    resolved_session_id,
                    exc,
                )
            try:
                stored_assessment = load_voice_assessment(session_id=resolved_session_id)
                if stored_assessment:
                    assessment_payload = asdict(stored_assessment)
            except Exception as exc:
                logging.warning(
                    "Voice session assessment readback failed for session_id=%s: %s",
                    resolved_session_id,
                    exc,
                )
            mistakes_payload = []
            try:
                raw_mistakes = fetch_voice_session_mistakes(session_id=resolved_session_id)
                mistakes_payload = [_mistake_row_to_api(m) for m in raw_mistakes]
                stt_flagged = sum(
                    1 for m in raw_mistakes if m.get("error_category") == "PRONUNCIATION_STT"
                )
                grammar_count = len(raw_mistakes) - stt_flagged
                if mistakes_payload:
                    logging.info(
                        "assessment_feedback_rendered session_id=%s mistake_count=%d grammar=%d",
                        resolved_session_id, len(mistakes_payload), grammar_count,
                    )
                else:
                    logging.info(
                        "assessment_feedback_empty session_id=%s", resolved_session_id
                    )
                if stt_flagged > 0:
                    logging.info(
                        "assessment_feedback_low_confidence_warning session_id=%s stt_count=%d",
                        resolved_session_id, stt_flagged,
                    )
            except Exception as exc:
                logging.warning(
                    "Voice mistakes readback failed for session_id=%s: %s",
                    resolved_session_id,
                    exc,
                )
        if session_minutes > 0 and resolved_session_id > 0:
            whisper_snapshot = get_effective_billing_price_snapshot(
                provider="openai",
                sku="whisper_input",
                unit="audio_minutes",
                currency=BILLING_CURRENCY_DEFAULT,
            )
            try:
                log_billing_event(
                    idempotency_key=f"voice_stt_whisper_priced_{resolved_session_id}_{int(user_id)}",
                    user_id=int(user_id),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    action_type="voice_stt_whisper",
                    provider="openai",
                    units_type="audio_minutes",
                    units_value=session_minutes,
                    price_provider="openai" if whisper_snapshot else None,
                    price_sku="whisper_input" if whisper_snapshot else None,
                    price_unit="audio_minutes" if whisper_snapshot else None,
                    currency=BILLING_CURRENCY_DEFAULT,
                    status="estimated",
                    metadata={
                        "session_id": resolved_session_id,
                        "duration_seconds": duration_seconds,
                        "pricing_state": "priced" if whisper_snapshot else "missing_snapshot",
                    },
                )
            except Exception:
                pass
            tts_snapshot = get_effective_billing_price_snapshot(
                provider="agent_tts",
                sku="agent_tts_output",
                unit="audio_minutes",
                currency=BILLING_CURRENCY_DEFAULT,
            )
            try:
                log_billing_event(
                    idempotency_key=f"voice_tts_agent_priced_{resolved_session_id}_{int(user_id)}",
                    user_id=int(user_id),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    action_type="voice_tts_agent",
                    provider="agent_tts",
                    units_type="audio_minutes",
                    units_value=session_minutes,
                    price_provider="agent_tts" if tts_snapshot else None,
                    price_sku="agent_tts_output" if tts_snapshot else None,
                    price_unit="audio_minutes" if tts_snapshot else None,
                    currency=BILLING_CURRENCY_DEFAULT,
                    status="estimated",
                    metadata={
                        "session_id": resolved_session_id,
                        "duration_seconds": duration_seconds,
                        "pricing_state": "priced" if tts_snapshot else "missing_snapshot",
                    },
                )
            except Exception:
                pass
            livekit_cost, livekit_meta = _compute_livekit_session_cost(
                session_minutes,
                currency=BILLING_CURRENCY_DEFAULT,
            )
            try:
                log_billing_event(
                    idempotency_key=f"livekit_room_minutes_{resolved_session_id}",
                    user_id=int(user_id),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    action_type="livekit_room_minutes",
                    provider="livekit",
                    units_type="audio_minutes",
                    units_value=session_minutes,
                    cost_amount=livekit_cost,
                    currency=BILLING_CURRENCY_DEFAULT,
                    status="final",
                    metadata={
                        "session_id": resolved_session_id,
                        "duration_seconds": duration_seconds,
                        **(livekit_meta if isinstance(livekit_meta, dict) else {}),
                    },
                )
            except Exception:
                pass
    return jsonify({"ok": True, "session": session, "assessment": assessment_payload, "mistakes": mistakes_payload})


@app.route("/api/assistant/session/assessment/get", methods=["POST"])
def get_assistant_session_assessment():
    user_id, _username, error = _get_authenticated_user_from_request_init_data()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status
    payload = request.get_json(silent=True) or {}
    session_id_raw = payload.get("session_id")
    if session_id_raw is None or str(session_id_raw).strip() == "":
        return jsonify({"error": "session_id обязателен"}), 400
    try:
        session_id = int(session_id_raw)
    except Exception:
        return jsonify({"error": "session_id должен быть числом"}), 400

    session = get_agent_voice_session(session_id)
    if not session:
        return jsonify({"error": "Голосовая сессия не найдена"}), 404
    if int(session.get("user_id") or 0) != int(user_id):
        return jsonify({"error": "Доступ к assessment этой сессии запрещён"}), 403

    try:
        assessment = load_voice_assessment(session_id=session_id)
    except Exception as exc:
        return jsonify({"error": f"Ошибка загрузки assessment: {exc}"}), 500
    if not assessment:
        return jsonify({"error": "Assessment для этой сессии ещё не найден"}), 404

    mistakes_payload = []
    try:
        raw_mistakes = fetch_voice_session_mistakes(session_id=session_id)
        mistakes_payload = [_mistake_row_to_api(m) for m in raw_mistakes]
    except Exception as exc:
        logging.warning(
            "Voice mistakes readback failed for session_id=%s: %s", session_id, exc
        )

    return jsonify({"ok": True, "assessment": asdict(assessment), "mistakes": mistakes_payload})


