                learned_words_goal = max(0, int(payload.get("learned_words_goal", 0)))
                agent_minutes_goal = max(0, int(payload.get("agent_minutes_goal", 0)))
                reading_minutes_goal = max(0, int(payload.get("reading_minutes_goal", 0)))
