@app.route("/api/progress/plan-analytics", methods=["GET"])
def get_plan_analytics():
    started_perf = time.perf_counter()
    request_id = _extract_observability_request_id()
    correlation_id = _build_observability_correlation_id(prefix="plan_analytics")
    with db_acquire_scope("plan_analytics") as db_acquire_events:
        user_id, _username, error = _get_authenticated_user_from_request_init_data()
        if error:
            status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
            _log_flow_observation(
                "plan_analytics",
                "plan_analytics_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                final_status="error",
                error_code="auth_error",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=status,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify({"error": error}), status
        raw_period = str(request.args.get("period") or "week").strip().lower()
        if raw_period == "half_year":
            raw_period = "half-year"
        if raw_period not in {"week", "month", "quarter", "half-year", "year"}:
            _log_flow_observation(
                "plan_analytics",
                "plan_analytics_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                final_status="error",
                error_code="invalid_period",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=400,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify({"error": "period must be one of: week, month, quarter, half-year, year"}), 400
        week_start_raw = str(request.args.get("week_start") or "").strip()
        as_of_date_raw = str(request.args.get("as_of_date") or "").strip()
        week_start = _parse_iso_date(week_start_raw or None)
        as_of_date = _parse_iso_date(as_of_date_raw or None)
        if week_start_raw and week_start is None:
            _log_flow_observation(
                "plan_analytics",
                "plan_analytics_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                final_status="error",
                error_code="invalid_week_start",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=400,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify({"error": "week_start must be an ISO date"}), 400
        if as_of_date_raw and as_of_date is None:
            _log_flow_observation(
                "plan_analytics",
                "plan_analytics_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                final_status="error",
                error_code="invalid_as_of_date",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=400,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify({"error": "as_of_date must be an ISO date"}), 400
        if week_start is not None and raw_period != "week":
            _log_flow_observation(
                "plan_analytics",
                "plan_analytics_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                final_status="error",
                error_code="invalid_week_start_period_combo",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=400,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify({"error": "week_start is only supported for period=week"}), 400

        try:
            response_payload, cache_meta = _get_plan_analytics_response_cached(
                user_id=int(user_id),
                period=raw_period,
                week_start=week_start,
                as_of_date=as_of_date,
            )
        except Exception as exc:
            _log_flow_observation(
                "plan_analytics",
                "plan_analytics_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                period=raw_period,
                final_status="error",
                error_code=exc.__class__.__name__,
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=500,
                **summarize_db_acquire_events(db_acquire_events),
            )
            return jsonify({"error": f"Ошибка расчёта аналитики плана: {exc}"}), 500

        _log_flow_observation(
            "plan_analytics",
            "plan_analytics_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            user_id=int(user_id),
            period=raw_period,
            cache_hit=bool(cache_meta.get("cache_hit")),
            cache_tier=cache_meta.get("cache_tier"),
            cache_state=cache_meta.get("cache_state"),
            snapshot_age_ms=cache_meta.get("snapshot_age_ms"),
            language_pair_lookup_duration_ms=cache_meta.get("language_pair_lookup_duration_ms"),
            progress_duration_ms=cache_meta.get("progress_duration_ms"),
            response_size_bytes=cache_meta.get("response_size_bytes") or _estimate_json_payload_size_bytes(response_payload),
            final_status="success",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=200,
            **summarize_db_acquire_events(db_acquire_events),
        )
        return jsonify(response_payload)


@app.route("/api/progress/skills/<string:skill_id>/practice/start", methods=["POST"])
def start_skill_practice(skill_id: str):
    user_id, username, error = _get_authenticated_user_from_request_init_data()
    if error:
        status = 401 if "прошёл проверку" in error else 403 if "Доступ" in error else 400
        return jsonify({"error": error}), status

    payload = request.get_json(silent=True) or {}
    level = str(payload.get("level") or "b1").strip().lower() or "b1"
    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))
    skill = get_skill_by_id(skill_id, language_code=target_lang)
    if not skill or not bool(skill.get("is_active")):
        return jsonify({"error": "Навык не найден"}), 404

    focus_topic = get_top_error_topic_for_skill(
        user_id=int(user_id),
        skill_id=str(skill.get("skill_id") or skill_id),
        lookback_days=14,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    main_category = (focus_topic or {}).get("main_category")
    sub_category = (focus_topic or {}).get("sub_category")
    examples: list[str] = []
    if main_category and sub_category:
        examples = get_weak_topic_sentences(
            user_id=int(user_id),
            main_category=str(main_category),
            sub_category=str(sub_category),
            lookback_days=14,
            limit=5,
            source_lang=source_lang,
            target_lang=target_lang,
        )
    topic_label = str(skill.get("title") or skill.get("skill_id") or "Skill practice")
    if sub_category:
        topic_label = f"{topic_label}: {sub_category}"
    elif main_category:
        topic_label = f"{topic_label}: {main_category}"

    try:
        _refresh_subscription_before_translation_start(int(user_id))
        session = asyncio.run(
            start_translation_session_webapp(
                user_id=int(user_id),
                username=username,
                topic=topic_label,
                level=level,
                source_lang=source_lang,
                target_lang=target_lang,
                tested_skill_profile_seed={
                    "primary_skill_id": str(skill.get("skill_id") or skill_id),
                    "main_category": str(main_category or "").strip() or None,
                    "sub_category": str(sub_category or "").strip() or None,
                    "profile_source": "skill_practice_explicit",
                    "profile_confidence": 1.0,
                },
            )
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка запуска прокачки навыка: {exc}"}), 500

    recommended_video = _pick_today_recommended_video(
        str(main_category or ""),
        str(sub_category or ""),
        target_lang=target_lang,
        billing_user_id=int(user_id),
        billing_source_lang=source_lang,
        billing_target_lang=target_lang,
    )
    return jsonify(
        {
            "ok": True,
            "skill": {
                "skill_id": skill.get("skill_id"),
                "title": skill.get("title"),
                "category": skill.get("category"),
            },
            "practice": {
                "task_type": "translation",
                "topic_label": topic_label,
                "level": level,
                "main_category": main_category,
                "sub_category": sub_category,
                "examples": examples[:5],
                "video_url": (recommended_video or {}).get("video_url"),
                "video_id": (recommended_video or {}).get("video_id"),
                "video_title": (recommended_video or {}).get("title"),
            },
            **session,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


@app.route("/api/webapp/dictionary/collocations", methods=["POST"])
def get_webapp_dictionary_collocations():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    word = (payload.get("word") or "").strip()
    direction = (payload.get("direction") or "").strip() or None
    translation = (payload.get("translation") or "").strip()

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not word:
        return jsonify({"error": "word обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    _clear_recent_finish_no_active_session(int(user_id))
    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    try:
        if _is_legacy_ru_de_pair(source_lang, target_lang):
            if not direction:
                is_ru = any("а" <= ch.lower() <= "я" or ch.lower() == "ё" for ch in word)
                direction = "ru-de" if is_ru else "de-ru"
            result = asyncio.run(run_dictionary_collocations(direction, word, translation))
        else:
            if not direction:
                direction = f"{source_lang}-{target_lang}"
            reverse_direction = f"{target_lang}-{source_lang}"
            is_reverse = direction == reverse_direction or direction == "de-ru"
            if is_reverse:
                word_source = translation or word
                word_target = word
            else:
                word_source = word
                word_target = translation
            result = asyncio.run(
                run_dictionary_collocations_multilang(
                    source_lang=source_lang,
                    target_lang=target_lang,
                    word_source=word_source,
                    word_target=word_target,
                )
            )
        usage_collocations = get_last_llm_usage(reset=True)
        # Счётчик обращения человека; сам вызов замеряется строкой ниже (см. пояснение
        # у счётчика dictionary_lookup) — иначе один вызов считался бы дважды.
        _billing_log_event_safe(
            user_id=int(user_id),
            action_type="dictionary_collocations",
            provider="app_internal",
            units_type="requests",
            units_value=1.0,
            source_lang=source_lang,
            target_lang=target_lang,
            idempotency_seed=f"dictionary_collocations:{user_id}:{word}:{direction}:{time.time_ns()}",
            status="estimated",
            metadata={"word": word, "direction": direction},
        )
        _billing_log_openai_usage(
            user_id=int(user_id),
            action_type="dictionary_collocations",
            source_lang=source_lang,
            target_lang=target_lang,
            usage=usage_collocations,
            seed=f"dictionary_collocations_tokens:{user_id}:{word}:{time.time_ns()}",
            metadata={"word": word, "direction": direction},
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка генерации связок: {exc}"}), 500

    return jsonify(
        {
            "ok": True,
            "items": result.get("items", []),
            "direction": direction,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


def _wrap_text(text: str, max_chars: int = 80) -> list[str]:
    if not text:
        return []
    words = text.split()
    lines = []
    current = ""
    for word in words:
        candidate = f"{current} {word}".strip()
        if len(candidate) <= max_chars:
            current = candidate
        else:
            if current:
                lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def _build_dictionary_card_example_lines(examples: Any, *, limit: int = 4) -> list[str]:
    if isinstance(examples, str):
        normalized_examples = [examples]
    elif isinstance(examples, list):
        normalized_examples = examples
    else:
        normalized_examples = []

    result: list[str] = []
    for raw_example in normalized_examples:
        example_text = ""
        if isinstance(raw_example, str):
            example_text = raw_example.strip()
        elif isinstance(raw_example, dict):
            source = str(raw_example.get("source") or "").strip()
            target = str(raw_example.get("target") or "").strip()
            if source and target:
                example_text = f"{source} → {target}"
            else:
                example_text = source or target
        if example_text:
            result.append(example_text)
        if len(result) >= limit:
            break
    return result


def _build_dictionary_meaning_lines(response_json: dict | None, *, limit: int = 3) -> list[str]:
    payload = response_json if isinstance(response_json, dict) else {}
    has_rich_meanings = (
        (isinstance(payload.get("dictionary_senses"), list) and len(payload.get("dictionary_senses") or []) > 0)
        or (isinstance(payload.get("meanings"), dict) and bool(payload.get("meanings")))
        or (isinstance(payload.get("translations"), list) and len(payload.get("translations") or []) > 0)
    )
    if not has_rich_meanings:
        return []
    lines: list[str] = []
    seen: set[str] = set()
    for sense in _build_dictionary_senses(payload, ""):
        value = str(sense.get("value") or "").strip()
        context = str(sense.get("context") or "").strip()
        text = f"{value} — {context}" if value and context else (value or context)
        normalized = re.sub(r"\s+", " ", text).strip().casefold()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        rank = int(sense.get("rank") or (len(lines) + 1))
        lines.append(f"{rank}. {text}")
        if len(lines) >= limit:
            break
    return lines


def _build_dictionary_card_pdf(
    *,
    item: dict[str, Any],
    source_lang: str,
    target_lang: str,
    referral_link: str = "",
) -> tuple[BytesIO, str]:
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from reportlab.pdfgen import canvas
    from reportlab.graphics import renderPDF
    from reportlab.graphics.barcode import qr
    from reportlab.graphics.shapes import Drawing

    payload = item if isinstance(item, dict) else {}
    response_json = payload.get("response_json")
    if isinstance(response_json, str):
        try:
            response_json = json.loads(response_json)
        except Exception:
            response_json = {}
    if not isinstance(response_json, dict):
        response_json = {}

    direction_raw = str(payload.get("direction") or response_json.get("direction") or "").strip().lower()
    direction_pair = _parse_direction_pair(direction_raw)
    item_source_lang = _normalize_short_lang_code(
        payload.get("source_lang") or response_json.get("source_lang"),
        fallback=direction_pair[0] if direction_pair else source_lang,
    )
    item_target_lang = _normalize_short_lang_code(
        payload.get("target_lang") or response_json.get("target_lang"),
        fallback=direction_pair[1] if direction_pair else target_lang,
    )
    if not item_source_lang:
        item_source_lang = source_lang
    if not item_target_lang:
        item_target_lang = target_lang
    if item_source_lang == item_target_lang:
        item_source_lang = source_lang
        item_target_lang = target_lang

    source_text, target_text, word_ru, word_de, translation_de, translation_ru = _align_dictionary_legacy_ru_de_columns(
        source_lang=item_source_lang,
        target_lang=item_target_lang,
        source_text=str(payload.get("source_text") or response_json.get("source_text") or ""),
        target_text=str(payload.get("target_text") or response_json.get("target_text") or ""),
        word_ru=str(payload.get("word_ru") or response_json.get("word_ru") or ""),
        word_de=str(payload.get("word_de") or response_json.get("word_de") or ""),
        translation_de=str(payload.get("translation_de") or response_json.get("translation_de") or ""),
        translation_ru=str(payload.get("translation_ru") or response_json.get("translation_ru") or ""),
    )

    def _lang_label(code: str) -> str:
        normalized = _normalize_short_lang_code(code, fallback="")
        return normalized.upper() or "?"

    target_headline = target_text or word_de or translation_de or word_ru or translation_ru or "—"
    source_value = source_text or word_ru or translation_ru or word_de or translation_de or "—"
    part_of_speech = str(payload.get("part_of_speech") or response_json.get("part_of_speech") or "").strip()
    article = str(payload.get("article") or response_json.get("article") or "").strip()
    provider = str(payload.get("provider") or response_json.get("provider") or "").strip().upper()
    forms = payload.get("forms") if isinstance(payload.get("forms"), dict) else response_json.get("forms")
    if not isinstance(forms, dict):
        forms = {}
    created_at = str(payload.get("created_at") or response_json.get("created_at") or "").strip()
    created_at_label = created_at.replace("T", " ").split(" ", 1)[0].strip() if created_at else ""
    examples = _build_dictionary_card_example_lines(
        payload.get("usage_examples") if payload.get("usage_examples") is not None else response_json.get("usage_examples"),
        limit=4,
    )
    meaning_lines = _build_dictionary_meaning_lines(response_json, limit=3)

    metadata_rows: list[tuple[str, str]] = [
        ("Направление", f"{_lang_label(item_source_lang)} → {_lang_label(item_target_lang)}"),
    ]
    if part_of_speech:
        metadata_rows.append(("Часть речи", part_of_speech))
    if article:
        metadata_rows.append(("Артикль", article))
    if provider:
        metadata_rows.append(("Источник", provider))
    if created_at_label:
        metadata_rows.append(("Дата", created_at_label))

    form_rows: list[tuple[str, str]] = []
    for raw_key, raw_value in forms.items():
        value = str(raw_value or "").strip()
        if not value or value in {"-", "—"}:
            continue
        label = str(raw_key or "").strip().replace("_", " ")
        if not label:
            continue
        form_rows.append((label[:1].upper() + label[1:], value))
        if len(form_rows) >= 5:
            break

    buffer = BytesIO()
    pdf = canvas.Canvas(buffer, pagesize=A4)

    font_name = "Helvetica"
    font_bold = "Helvetica-Bold"
    font_paths = [
        os.path.join(os.path.dirname(__file__), "assets", "fonts", "DejaVuSans.ttf"),
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    ]
    font_bold_paths = [
        os.path.join(os.path.dirname(__file__), "assets", "fonts", "DejaVuSans-Bold.ttf"),
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
    ]
    for fp in font_paths:
        if not os.path.exists(fp):
            continue
        try:
            pdfmetrics.registerFont(TTFont("DejaVuSans", fp))
            font_name = "DejaVuSans"
            break
        except Exception:
            continue
    for fp in font_bold_paths:
        if not os.path.exists(fp):
            continue
        try:
            pdfmetrics.registerFont(TTFont("DejaVuSans-Bold", fp))
            font_bold = "DejaVuSans-Bold"
            break
        except Exception:
            continue
    if font_bold == "Helvetica-Bold" and font_name != "Helvetica":
        font_bold = font_name

    width, height = A4
    margin_x = 42
    top_y = height - 44
    card_width = width - margin_x * 2
    card_bottom = 96
    card_height = top_y - 28 - card_bottom

    pdf.setFillColorRGB(0.965, 0.954, 0.93)
    pdf.rect(0, 0, width, height, stroke=0, fill=1)

    pdf.setFillColorRGB(0.15, 0.19, 0.28)
    pdf.setFont(font_bold, 18)
    pdf.drawString(margin_x, top_y, "Das Deutsche Schluempfchen")
    pdf.setFont(font_name, 10.5)
    pdf.setFillColorRGB(0.41, 0.45, 0.53)
    pdf.drawString(margin_x, top_y - 16, "Dictionary Card")

    pdf.setFillColorRGB(0.985, 0.979, 0.955)
    pdf.setStrokeColorRGB(0.84, 0.81, 0.74)
    pdf.roundRect(margin_x, card_bottom, card_width, card_height, 18, stroke=1, fill=1)

    cursor_x = margin_x + 18
    cursor_y = card_bottom + card_height - 22
    content_width = card_width - 36

    pdf.setFillColorRGB(0.43, 0.36, 0.22)
    pdf.setFont(font_bold, 10)
    pdf.drawString(cursor_x, cursor_y, _lang_label(item_target_lang))
    cursor_y -= 18

    headline_lines = _wrap_text(str(target_headline), 32)[:3] or ["—"]
    pdf.setFillColorRGB(0.12, 0.25, 0.65)
    pdf.setFont(font_bold, 24 if len(headline_lines) == 1 else 21)
    for line in headline_lines:
        pdf.drawString(cursor_x, cursor_y, line)
        cursor_y -= 25

    cursor_y -= 4
    pdf.setFillColorRGB(0.29, 0.32, 0.39)
    pdf.setFont(font_name if item_source_lang != "ru" else font_bold, 14)
    source_lines = _wrap_text(f"{_lang_label(item_source_lang)}: {source_value}", 48)[:3] or ["—"]
    for line in source_lines:
        pdf.drawString(cursor_x, cursor_y, line)
        cursor_y -= 16 if item_source_lang != "ru" else 18

    cursor_y -= 6
    pdf.setStrokeColorRGB(0.88, 0.85, 0.78)
    pdf.line(cursor_x, cursor_y, cursor_x + content_width, cursor_y)
    cursor_y -= 18

    if meaning_lines:
        pdf.setFillColorRGB(0.18, 0.20, 0.26)
        pdf.setFont(font_bold, 11.5)
        pdf.drawString(cursor_x, cursor_y, "Значения")
        cursor_y -= 16
        pdf.setFont(font_name, 10.5)
        for meaning in meaning_lines:
            wrapped_lines = _wrap_text(meaning, 62)[:3]
            if not wrapped_lines:
                continue
            pdf.drawString(cursor_x, cursor_y, wrapped_lines[0])
            cursor_y -= 13
            for line in wrapped_lines[1:]:
                pdf.drawString(cursor_x + 12, cursor_y, line)
                cursor_y -= 13
            cursor_y -= 4

    pdf.setFont(font_bold, 11)
    pdf.setFillColorRGB(0.18, 0.20, 0.26)
    for label, value in metadata_rows:
        wrapped_value = _wrap_text(str(value), 54)[:2] or ["—"]
        pdf.drawString(cursor_x, cursor_y, f"{label}:")
        pdf.setFont(font_name, 11)
        text_y = cursor_y
        for index, line in enumerate(wrapped_value):
            offset_x = 84 if index == 0 else 0
            pdf.drawString(cursor_x + offset_x, text_y, line)
            text_y -= 14
        cursor_y = text_y - 4
        pdf.setFont(font_bold, 11)

    if form_rows:
        pdf.setFillColorRGB(0.18, 0.20, 0.26)
        pdf.setFont(font_bold, 11.5)
        pdf.drawString(cursor_x, cursor_y, "Формы")
        cursor_y -= 16
        for label, value in form_rows:
            wrapped_value = _wrap_text(str(value), 56)[:2] or ["—"]
            pdf.setFont(font_bold, 10.5)
            pdf.drawString(cursor_x, cursor_y, f"{label}:")
            pdf.setFont(font_name, 10.5)
            text_y = cursor_y
            for index, line in enumerate(wrapped_value):
                offset_x = 88 if index == 0 else 0
                pdf.drawString(cursor_x + offset_x, text_y, line)
                text_y -= 13
            cursor_y = text_y - 3

    if examples:
        pdf.setFillColorRGB(0.18, 0.20, 0.26)
        pdf.setFont(font_bold, 11.5)
        pdf.drawString(cursor_x, cursor_y, "Примеры")
        cursor_y -= 16
        pdf.setFont(font_name, 10.5)
        for example in examples:
            wrapped_lines = _wrap_text(example, 62)[:3]
            if not wrapped_lines:
                continue
            pdf.drawString(cursor_x, cursor_y, f"• {wrapped_lines[0]}")
            cursor_y -= 13
            for line in wrapped_lines[1:]:
                pdf.drawString(cursor_x + 12, cursor_y, line)
                cursor_y -= 13
            cursor_y -= 4

    # Gentle "powered by the bot" + referral footer, below the word card.
    referral_link = str(referral_link or "").strip()
    if referral_link:
        link_display = re.sub(r"^https?://", "", referral_link)
        qr_size = 66
        qr_x = width - margin_x - qr_size
        qr_y = 18
        try:
            widget = qr.QrCodeWidget(referral_link)
            bounds = widget.getBounds()
            qr_w = (bounds[2] - bounds[0]) or 1
            qr_h = (bounds[3] - bounds[1]) or 1
            drawing = Drawing(qr_size, qr_size, transform=[qr_size / qr_w, 0, 0, qr_size / qr_h, 0, 0])
            drawing.add(widget)
            renderPDF.draw(drawing, pdf, qr_x, qr_y)
            text_right = qr_x - 14
        except Exception:
            logging.warning("Dictionary card QR render failed", exc_info=True)
            text_right = width - margin_x

        text_width_chars = max(24, int((text_right - margin_x) / 5.1))
        footer_x = margin_x
        footer_y = 78
        pdf.setFillColorRGB(0.18, 0.20, 0.26)
        pdf.setFont(font_bold, 10.5)
        for line in _wrap_text("Нравится разбор? Его собрал бот-репетитор по немецкому.", text_width_chars)[:2]:
            pdf.drawString(footer_x, footer_y, line)
            footer_y -= 13

        pdf.setFillColorRGB(0.34, 0.37, 0.44)
        pdf.setFont(font_name, 9)
        body_text = (
            "Детальные разборы каждого слова, тренировки и интерактивные задания каждый день. "
            f"Перейди по ссылке и позанимайся {REFERRAL_STREAK_TRIGGER} дня — "
            f"тебе и другу по +{REFERRAL_REWARD_DAYS} дней полного доступа."
        )
        for line in _wrap_text(body_text, text_width_chars)[:3]:
            pdf.drawString(footer_x, footer_y, line)
            footer_y -= 11

        footer_y -= 2
        pdf.setFillColorRGB(0.12, 0.25, 0.65)
        pdf.setFont(font_bold, 9.5)
        for line in _wrap_text(link_display, text_width_chars)[:2]:
            pdf.drawString(footer_x, footer_y, line)
            footer_y -= 12

    pdf.setFillColor(colors.black)
    pdf.save()
    buffer.seek(0)

    filename_stem = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(target_headline or source_value or "dictionary_card")).strip("_") or "dictionary_card"
    return buffer, f"{filename_stem[:48]}.pdf"


@app.route("/api/webapp/dictionary/export/card-pdf", methods=["POST"])
def export_webapp_dictionary_card_pdf():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    item = payload.get("item")

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not isinstance(item, dict):
        return jsonify({"error": "item обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    referral_link = ""
    if TELEGRAM_BOT_USERNAME:
        referral_link = f"https://t.me/{TELEGRAM_BOT_USERNAME}?start=ref_{int(user_id)}"

    try:
        buffer, download_name = _build_dictionary_card_pdf(
            item=item,
            source_lang=source_lang,
            target_lang=target_lang,
            referral_link=referral_link,
        )
        return send_file(
            buffer,
            as_attachment=True,
            download_name=download_name,
            mimetype="application/pdf",
        )
    except Exception as exc:
        logging.exception("Dictionary card PDF export failed: user_id=%s", user_id)
        return jsonify({"error": f"Ошибка генерации PDF карточки: {exc}"}), 500


def _dictionary_save_costs_us_nothing(*, word: str, source_lang: str, target_lang: str) -> bool:
    """Знаем ли МЫ это слово сами — своей базой, без единого обращения к модели.

    Правило владельца (15.08.2026): лимит стоит там, где мы платим. Слово из задания уже
    переведено и лежит у нас; сохранить его — это одна запись в таблицу, модель тут не
    участвует. Брать за это из дневной нормы в 20 слов не за что.

    Спрашиваем ТОЛЬКО свои источники и НИКОГДА — то, что прислал браузер. Если бы решение
    принималось по присланному полю `translation_ru`, лимит обходился бы подделкой одной
    строки: написал что угодно — получил бесплатное сохранение.

    Порядок источников — от дешёвого к дорогому по чтению:
      1. слой статей (наши единицы + FreeDict) — оба поиска по индексу;
      2. общий пул — по индексу source_headword_norm;
      3. банк Artikel — по индексу lower(word), добавлен 15.08.2026.

    Почему банк отдельным пунктом: замер 15.08.2026 (выборка 300 слов) — слой статей знает
    57.3% банка. «die Richtlinie», «das Register», «der Schadensersatz» он не знает, а банк
    знает, потому что перевод там обязательное поле. Без третьего пункта человек в игре
    Artikel продолжал бы платить за слова, которые мы сами ему и показали.

    Фразы и предложения сюда не попадают: слой статей отбрасывает всё с пробелом, пул и
    банк спрашиваются одним словом. Это верно по сути — многословное человек набирает сам,
    и перевода у нас на него нет."""
    text = str(word or "").strip()
    if not text:
        return False
    bare = _LEADING_GERMAN_ARTICLE_RE.sub("", text).strip()
    if not bare or " " in bare:
        return False
    try:
        from backend.dictionary_entries import entries_for_query
        if entries_for_query(bare, source_lang=source_lang, target_lang=target_lang):
            return True
    except Exception:
        logging.debug("слой статей не ответил про %r", bare[:60], exc_info=True)
    try:
        pooled = get_pool_dictionary_entry(
            source_lang=source_lang, target_lang=target_lang, source_text=text,
        )
        if isinstance(pooled, dict) and str(pooled.get("target_text") or "").strip():
            return True
    except Exception:
        logging.debug("пул не ответил про %r", bare[:60], exc_info=True)
    try:
        from backend.database import article_bank_knows_word
        return article_bank_knows_word(bare)
    except Exception:
        logging.debug("банк Artikel не ответил про %r", bare[:60], exc_info=True)
    # Не ответил никто — считаем слово незнакомым и пускаем обычным платным путём.
    # Раздавать бесплатные сохранения из-за молчания базы нельзя.
    return False


@app.route("/api/webapp/dictionary/check-variant", methods=["POST"])
def check_own_dictionary_variant():
    """Проверить СВОЙ вариант фразы перед сохранением — и НЕ подменять его молча.

    Зачем это есть. Карточка показывает оборот так, как он прозвучал в ролике:
    «einen hohen genetischen Anteil» — винительный падеж, потому что в предложении он
    стоял в винительном. Кому-то нужно положить себе именительный, кому-то — свою
    формулировку. Раньше выбора не было вовсе: кнопка одна, и она клала показанное.

    Решение владельца 20.08.2026: человек может вписать своё, мы прогоняем это через
    проверку — вместе с ЕГО переводом, потому что предлог и падеж выбираются по смыслу, —
    и ПОКАЗЫВАЕМ, что думает судья. Решает человек, не мы: «оставить моё» или «взять
    предложенное». Молча переписать набранное человеком нельзя.

    Судья — `run_phrase_grammar_verdict`, а не «быстрый корректор». Корректор спрашивает
    «исправь слово» и на обороте начинает править стиль; этот же судит фразу КАК ФРАЗУ,
    видит перевод как контекст и прямо обязан не трогать разговорное: «Colloquial but
    attested German is CORRECT. Do not standardise it». Для оборотов из стендапа это и
    есть главное.
    """
    payload = request.get_json(silent=True) or {}
    german = str(payload.get("de") or "").strip()
    russian = str(payload.get("ru") or "").strip()
    if not german:
        return jsonify({"error": "нечего проверять"}), 400
    user_id = _resolve_webapp_user_id(payload)
    if not user_id:
        return jsonify({"error": "initData не прошёл проверку"}), 401
    if _dict_user_has_left_bot(user_id):
        return _dict_gate_response()

    # Целое предложение и оборот судятся по-разному: к обороту, вырванному из речи,
    # порядок слов неприменим. Вид берём из слоя слов, а не считаем здесь заново.
    try:
        from backend.lex_units import _kind_for_text
        kind = "sentence" if _kind_for_text(german) == "sentence" else "collocation"
    except Exception:
        kind = "collocation"

    try:
        from backend.openai_manager import run_phrase_grammar_verdict
        verdict = run_phrase_grammar_verdict(text=german, kind=kind, translation=russian)
    except Exception:
        logging.warning("свой вариант: судья не ответил", exc_info=True)
        # Судья молчит — это НЕ повод не дать человеку сохранить своё. Отдаём «вопросов
        # нет»: он написал это осознанно, а мы просто не смогли проверить.
        return jsonify({"verdict": "ok", "suggestion_de": "", "suggestion_ru": "", "why": ""})

    try:
        _billing_log_openai_usage(
            user_id=int(user_id),
            action_type="phrase_grammar_verdict",
            source_lang="de", target_lang=None,
            usage=get_last_llm_usage(reset=True),
            seed=f"own_variant:{user_id}:{time.time_ns()}",
            metadata={"origin": "dictionary_own_variant", "text": german[:64]},
        )
    except Exception:
        logging.debug("свой вариант: запись расхода не удалась", exc_info=True)

    # «context» и «style» — это отказ судьи трогать текст, а не претензия. Наружу они
    # уходят как «вопросов нет»: показывать человеку «возможно, дело вкуса» на его
    # собственной формулировке значит сеять сомнение на пустом месте.
    status = str(verdict.get("verdict") or "ok").strip().lower()
    suggestion = str(verdict.get("corrected") or "").strip()
    if status != "error" or not suggestion or suggestion == german:
        return jsonify({"verdict": "ok", "suggestion_de": "", "suggestion_ru": "", "why": ""})
    return jsonify({
        "verdict": "error",
        "suggestion_de": suggestion,
        "suggestion_ru": str(verdict.get("corrected_ru") or "").strip(),
        "why": str(verdict.get("why") or "").strip(),
    })


@app.route("/api/webapp/dictionary/save", methods=["POST"])
def save_webapp_dictionary_entry():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    word_ru = (payload.get("word_ru") or "").strip()
    word_de = (payload.get("word_de") or "").strip()
    translation_de = (payload.get("translation_de") or "").strip()
    translation_ru = (payload.get("translation_ru") or "").strip()
    generic_translation = (payload.get("translation") or "").strip()
    source_text = (payload.get("source_text") or "").strip()
    target_text = (payload.get("target_text") or "").strip()
    payload_source_lang = payload.get("source_lang")
    payload_target_lang = payload.get("target_lang")
    payload_direction = payload.get("direction")
    payload_origin_process = payload.get("origin_process")
    payload_origin_meta = payload.get("origin_meta")
    response_json = payload.get("response_json") or {}
    folder_id = payload.get("folder_id")

    if not word_ru and not word_de and not source_text:
        return jsonify({"error": "word_ru или word_de или source_text обязателен"}), 400

    # initData OR durable browser-dictionary token (standalone Safari / home-screen app).
    user_id = _resolve_webapp_user_id(payload)
    if not user_id:
        return jsonify({"error": "initData не прошёл проверку"}), 401

    profile_source_lang, profile_target_lang, _profile = _get_user_language_pair(int(user_id))
    source_lang, target_lang = _resolve_dictionary_save_pair(
        profile_source_lang=profile_source_lang,
        profile_target_lang=profile_target_lang,
        payload_source_lang=payload_source_lang,
        payload_target_lang=payload_target_lang,
        payload_direction=payload_direction,
        response_json=response_json if isinstance(response_json, dict) else None,
    )

    (
        source_lang, target_lang, source_text, target_text,
        word_ru, word_de, translation_de, translation_ru,
    ) = _flip_inverted_ru_de_dictionary_payload(
        source_lang=source_lang,
        target_lang=target_lang,
        source_text=source_text,
        target_text=target_text,
        word_ru=word_ru,
        word_de=word_de,
        translation_de=translation_de,
        translation_ru=translation_ru,
    )

    if source_lang == "ru" and target_lang == "de":
        if generic_translation and not target_text:
            target_text = generic_translation
        if generic_translation and not translation_de:
            translation_de = generic_translation
        if source_text and not word_ru:
            word_ru = source_text
        if target_text and not translation_de:
            translation_de = target_text
        if target_text and not word_de:
            word_de = target_text
        if source_text and not translation_ru:
            translation_ru = source_text
    elif source_lang == "de" and target_lang == "ru":
        if generic_translation and not target_text:
            target_text = generic_translation
        if generic_translation and not translation_ru:
            translation_ru = generic_translation
        if source_text and not word_de:
            word_de = source_text
        if target_text and not translation_ru:
            translation_ru = target_text
        if target_text and not word_ru:
            word_ru = target_text
        if source_text and not translation_de:
            translation_de = source_text
    else:
        if source_text and source_lang == "ru" and not word_ru:
            word_ru = source_text
        if source_text and source_lang == "de" and not word_de:
            word_de = source_text
        if target_text and target_lang == "de" and not translation_de:
            translation_de = target_text
        if target_text and target_lang == "ru" and not translation_ru:
            translation_ru = target_text

    source_text, target_text, word_ru, word_de, translation_de, translation_ru = _align_dictionary_legacy_ru_de_columns(
        source_lang=source_lang,
        target_lang=target_lang,
        source_text=source_text,
        target_text=target_text,
        word_ru=word_ru,
        word_de=word_de,
        translation_de=translation_de,
        translation_ru=translation_ru,
    )
    (
        source_lang, target_lang, source_text, target_text,
        word_ru, word_de, translation_de, translation_ru,
    ) = _correct_inverted_dictionary_scripts(
        source_lang=source_lang,
        target_lang=target_lang,
        source_text=source_text,
        target_text=target_text,
        word_ru=word_ru,
        word_de=word_de,
        translation_de=translation_de,
        translation_ru=translation_ru,
    )
    # Reader / YouTube "rephrase" saves can glue "original -> alternative" into a single field.
    # Keep only the correct segment per field so the arrow combo never reaches the dictionary or
    # the shared pool again (see the 130-row cleanup of 2026-07-22). No-op for ordinary text.
    source_text = _strip_rephrase_arrow_combo(source_text, prefer_script=source_lang)
    target_text = _strip_rephrase_arrow_combo(target_text, prefer_script=target_lang)
    word_de = _strip_rephrase_arrow_combo(word_de, prefer_script="de")
    translation_de = _strip_rephrase_arrow_combo(translation_de, prefer_script="de")
    word_ru = _strip_rephrase_arrow_combo(word_ru, prefer_script="ru")
    translation_ru = _strip_rephrase_arrow_combo(translation_ru, prefer_script="ru")
    sanitized_target_text = _sanitize_bilingual_dictionary_target(source_text, target_text, target_lang)
    if sanitized_target_text:
        target_text = sanitized_target_text
        if source_lang == "de" and target_lang == "ru":
            translation_ru = _sanitize_bilingual_dictionary_target(source_text, translation_ru or target_text, target_lang) or target_text
            word_ru = _sanitize_bilingual_dictionary_target(source_text, word_ru or target_text, target_lang) or target_text
        elif source_lang == "ru" and target_lang == "de":
            translation_de = _sanitize_bilingual_dictionary_target(source_text, translation_de or target_text, target_lang) or target_text
            word_de = _sanitize_bilingual_dictionary_target(source_text, word_de or target_text, target_lang) or target_text

    # Вычитка сохраняемой фразы — ТОЛЬКО там, где текст набрал человек. Где показали мы,
    # сохраняем ровно то, что было на экране, и мгновенно (см. `_save_source_was_typed_by_user`).
    origin_process = str(payload_origin_process or "webapp_dictionary_save").strip().lower() or "webapp_dictionary_save"
    source_text, word_ru, word_de, translation_ru, translation_de = _apply_dictionary_source_proofread(
        source_text=source_text,
        word_ru=word_ru,
        word_de=word_de,
        translation_ru=translation_ru,
        translation_de=translation_de,
        source_lang=source_lang,
        user_id=int(user_id),
        origin_process=origin_process,
    )

    if folder_id is None:
        try:
            default_folder = get_or_create_dictionary_folder(
                user_id=user_id,
                name="GENERAL",
                color="#7d8590",
                icon="📁",
            )
            folder_id = default_folder.get("id")
        except Exception:
            folder_id = None

    origin_meta = payload_origin_meta if isinstance(payload_origin_meta, dict) else {}
    if "endpoint" not in origin_meta:
        origin_meta["endpoint"] = "/api/webapp/dictionary/save"
    if payload_direction and "direction" not in origin_meta:
        origin_meta["direction"] = str(payload_direction)

    try:
        resolved_word_ru = _strip_bilingual_ru_combo(word_ru or response_json.get("word_ru"))
        resolved_word_de = word_de or response_json.get("word_de")
        resolved_translation_de = translation_de or response_json.get("translation_de")
        resolved_translation_ru = _strip_bilingual_ru_combo(translation_ru or response_json.get("translation_ru"))
        response_json = _prepare_dictionary_response_json_for_save(
            response_json=response_json if isinstance(response_json, dict) else {},
            source_text=source_text or resolved_word_ru or resolved_word_de or "",
            target_text=target_text or resolved_translation_de or resolved_translation_ru or resolved_word_de or "",
            source_lang=source_lang,
            target_lang=target_lang,
            word_ru=resolved_word_ru,
            word_de=resolved_word_de,
            translation_de=resolved_translation_de,
            translation_ru=resolved_translation_ru,
        )
        resolved_word_ru = str(response_json.get("word_ru") or resolved_word_ru or "").strip()
        resolved_word_de = str(response_json.get("word_de") or resolved_word_de or "").strip()
        resolved_translation_de = str(response_json.get("translation_de") or resolved_translation_de or "").strip()
        resolved_translation_ru = str(response_json.get("translation_ru") or resolved_translation_ru or "").strip()
        semantic_tag, semantic_folder_id = _resolve_dictionary_semantic_folder_for_save(int(user_id), response_json)
        if semantic_tag:
            response_json["semantic_category"] = semantic_tag
            if semantic_folder_id is not None:
                folder_id = semantic_folder_id
        existing_entry_id = get_existing_user_dictionary_entry_id_for_save(
            user_id=int(user_id),
            word_ru=resolved_word_ru if resolved_word_ru else None,
            translation_de=resolved_translation_de,
            word_de=resolved_word_de if resolved_word_de else None,
            translation_ru=resolved_translation_ru,
            response_json=response_json,
            source_lang=source_lang,
            target_lang=target_lang,
        )
        dictionary_save_feature_key = "dictionary_lookup_save_daily"
        entitlement = resolve_entitlement(user_id=int(user_id), tz="Europe/Vienna")
        effective_mode = str(entitlement.get("effective_mode") or "free").strip().lower() or "free"
        # Слово, которое мы и так знаем, сохраняется бесплатно и лимита не касается —
        # ни при проверке, ни при списании. См. _dictionary_save_costs_us_nothing.
        save_is_free_of_charge = False
        if effective_mode == "free":
            save_is_free_of_charge = _dictionary_save_costs_us_nothing(
                word=resolved_word_de or source_text,
                source_lang=source_lang,
                target_lang=target_lang,
            )
        if effective_mode == "free" and existing_entry_id is None and not save_is_free_of_charge:
            limit_meta = get_free_feature_limit_metadata(dictionary_save_feature_key) or {}
            limit_value = float(limit_meta.get("free_limit") or 0)
            used_today = get_free_feature_usage_today(
                user_id=int(user_id),
                feature_key=dictionary_save_feature_key,
                tz="Europe/Vienna",
            )
            if limit_value >= 0 and used_today + 1.0 > limit_value:
                log_limit_runtime_event(
                    user_id=int(user_id),
                    feature_code=dictionary_save_feature_key,
                    event_type="blocked",
                    origin=origin_process,
                    metadata={
                        **origin_meta,
                        "used": used_today,
                        "limit": limit_value,
                    },
                )
                return jsonify(
                    build_free_limit_error(
                        dictionary_save_feature_key,
                        used=used_today,
                        limit=limit_value,
                        tz="Europe/Vienna",
                    )
                ), 429
        entry_id, inserted = _save_dictionary_entry_with_inserted_schema_retry(
            user_id=user_id,
            word_ru=resolved_word_ru if resolved_word_ru else None,
            translation_de=resolved_translation_de,
            word_de=resolved_word_de if resolved_word_de else None,
            translation_ru=resolved_translation_ru,
            response_json=response_json,
            folder_id=int(folder_id) if folder_id is not None else None,
            source_lang=source_lang,
            target_lang=target_lang,
            origin_process=origin_process,
            origin_meta=origin_meta,
            semantic_tag=semantic_tag or None,
        )
        if effective_mode == "free" and inserted and not save_is_free_of_charge:
            increment_free_feature_usage(
                user_id=int(user_id),
                feature_key=dictionary_save_feature_key,
                idempotency_key=f"{dictionary_save_feature_key}:{int(user_id)}:{int(entry_id or 0)}",
                source_lang=source_lang,
                target_lang=target_lang,
                metadata={
                    "entry_id": int(entry_id or 0),
                    "origin_process": origin_process,
                },
            )
        # A de→ru entry that arrived without a real Russian gloss (bare-text saves from the
        # games: target_text empty or just echoing the German) must be enriched even when
        # the payload gate says otherwise — otherwise it stays German-on-both-sides forever.
        missing_russian = (
            source_lang == "de"
            and target_lang == "ru"
            and not _text_has_cyrillic(resolved_translation_ru)
            and not _text_has_cyrillic(resolved_word_ru)
        )
        _start_saved_dictionary_entry_enrichment(
            entry_id=int(entry_id or 0),
            response_json=response_json,
            source_lang=source_lang,
            target_lang=target_lang,
            source_text_hint=source_text,
            target_text_hint=target_text,
            force=missing_russian,
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка сохранения словаря: {exc}"}), 500

    try:
        _enqueue_dictionary_entry_tts_prewarm(
            user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            response_json=response_json if isinstance(response_json, dict) else {},
            source_text_hint=source_text,
            target_text_hint=target_text,
            origin_process=origin_process,
        )
    except Exception:
        logging.exception(
            "Dictionary save TTS prewarm enqueue failed: user_id=%s endpoint=%s",
            user_id,
            "/api/webapp/dictionary/save",
        )
        _record_tts_admin_monitor_event("enqueue", "error", source="/api/webapp/dictionary/save", count=1)

    return jsonify(
        {
            "ok": True,
            "entry_id": int(entry_id or 0),
            # False = the word was ALREADY in this user's dictionary and the save updated
            # that entry. The UI needs this: an updated old entry keeps its created_at, so
            # it does NOT appear at the top of the list and the user thinks the save was
            # lost. Say «уже в словаре» instead of a silent 💾.
            "inserted": bool(inserted),
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


@app.route("/api/mobile/dictionary/save", methods=["POST"])
def save_mobile_dictionary_entry():
    user_id, _username, error = _get_mobile_authenticated_user()
    if error:
        return error

    payload = request.get_json(silent=True) or {}
    word_ru = (payload.get("word_ru") or "").strip()
    word_de = (payload.get("word_de") or "").strip()
    translation_de = (payload.get("translation_de") or "").strip()
    translation_ru = (payload.get("translation_ru") or "").strip()
    generic_translation = (payload.get("translation") or "").strip()
    source_text = (payload.get("source_text") or "").strip()
    target_text = (payload.get("target_text") or "").strip()
