def _settings_current_window_key(prefs) -> str:
    """Map the user's stored schedule back to a window key for the settings slider."""
    sched = (prefs or {}).get("schedule")
    if not sched:
        return "allday"
    wd = sched.get("weekday") if isinstance(sched, dict) else None
    for key, wins in _ONBOARDING_WINDOWS.items():
        if wins is not None and wd == wins:
            return key
    return "allday"


def _preset_daily_budgets() -> dict:
    """Дневная норма заданий по каждому пресету — из ЕДИНСТВЕННОГО источника.

    Источник — `bot_3._preset_budget`, та самая функция, по которой планировщик и
    решает, сколько слать. Не копия чисел, а вызов: разойтись с правдой она не может
    по построению.
    """
    try:
        from bot_3 import _preset_budget
        return {ключ: int(_preset_budget(ключ))
                for ключ in ("intensive", "normal", "rare", "silent")}
    except Exception:
        # Норму не узнали — молчим числом, а не выдумываем его. Экран в этом случае
        # покажет пресеты без подписи «~N в день»: пустая подпись честнее неверной.
        logging.warning("настройки: не прочитал дневные нормы", exc_info=True)
        return {}


@app.route("/api/webapp/settings", methods=["POST"])
def webapp_settings_state():
    """Current values for the Mini-App settings page (autosave, battle-readiness,
    schedule preset+window) + is_pro / is_admin for gating."""
    user_id, _user_name, err = _miniapp_auth_user_id()
    if user_id is None:
        return err
    try:
        prefs = get_user_prefs(int(user_id)) or {}
    except Exception:
        prefs = {}
    try:
        ent = resolve_entitlement(user_id=int(user_id), tz="Europe/Vienna")
        is_pro = str(ent.get("effective_mode") or "free").strip().lower() in ("pro", "trial")
    except Exception:
        is_pro = False
    try:
        is_admin = int(user_id) in {int(a) for a in get_admin_telegram_ids()}
    except Exception:
        is_admin = False
    # Какой словарь подключён: ничего / базовый / полный. Читаем ИМЕННО то, что человек
    # выбрал, а не догадываемся по числу слов: раньше «полный» показывался только при
    # больше чем двух лимитах скопированных слов, а полный ничего не копирует — значит
    # «полный» не показывался НИКОГДА, и переключатель всегда отскакивал на «базовый».
    dict_tier = "none"
    dict_base_total = int(STARTER_DICTIONARY_IMPORT_LIMIT)
    dict_full_total = 0
    try:
        st = get_starter_dictionary_state(int(user_id)) or {}
        decision = str(st.get("decision_status") or "").strip().lower()
        if decision == "accepted":
            if bool(st.get("live_subscription")):
                # Оба варианта — подписка, поэтому по одному флагу их не различить:
                # разница в ПОТОЛКЕ. Есть потолок — «Быстрый старт», нет — «Весь словарь».
                # Без этого экран показывал «Весь словарь» даже сразу после переключения
                # на урезанный: человек выходил, возвращался — и видел свой выбор отменённым.
                dict_tier = "base" if st.get("subscription_limit") else "full"
            elif int(st.get("last_imported_count") or 0) > 0:
                dict_tier = "base"
    except Exception:
        logging.debug("settings: не удалось прочитать состояние словаря uid=%s", user_id, exc_info=True)
    # Сколько слов автора человек уже забрал и выбран ли потолок «урезанного» —
    # чтобы экран мог предложить включить весь словарь, а не молча остановиться.
    dict_delivered = 0
    dict_exhausted = False
    try:
        _st = get_starter_dictionary_state(int(user_id)) or {}
        _cap = _st.get("subscription_limit")
        if _st.get("live_subscription") and _cap:
            dict_delivered = count_subscription_delivered(int(user_id))
            dict_exhausted = dict_delivered >= int(_cap)
    except Exception:
        logging.debug("settings: не удалось посчитать выданное по подписке uid=%s", user_id, exc_info=True)
    # Сколько слов стоит за «полным» — чтобы подпись на переключателе называла число,
    # а не оставляла человека гадать, на что он подписался.
    try:
        if STARTER_DICTIONARY_ENABLED and STARTER_DICTIONARY_SOURCE_USER_ID > 0:
            _src_lang, _tgt_lang, _ = _get_user_language_pair(int(user_id))
            dict_full_total = int(count_dictionary_entries_for_language_pair(
                int(STARTER_DICTIONARY_SOURCE_USER_ID),
                _src_lang,
                _tgt_lang,
                both_directions=True,
            ) or 0)
    except Exception:
        logging.debug("settings: не удалось посчитать полный словарь uid=%s", user_id, exc_info=True)
    return jsonify({
        "ok": True,
        "autosave": bool(get_shortcut_autosave_enabled(int(user_id))),
        "battle_ready": bool(is_article_battle_available(int(user_id))),
        "preset": str(prefs.get("preset") or "normal"),
        # СКОЛЬКО ЗАДАНИЙ СТОИТ ЗА КАЖДЫМ ПРЕСЕТОМ — числом ОТСЮДА, а не копией на
        # экране. Нормы живут в переменных окружения (GLOBAL_DAILY_SEND_BUDGET и
        # соседние), владелец меняет их без правки кода; экран настроек держал те же
        # 20/12/8 своим списком и разошёлся бы с правдой в ту же минуту, ничем себя
        # не выдав — человек читал бы «~12 в день», получая другое число.
        "preset_budgets": _preset_daily_budgets(),
        "window": _settings_current_window_key(prefs),
        "dict_tier": dict_tier,
        "dict_base_total": int(dict_base_total),
        "dict_full_total": int(dict_full_total),
        "subscription_delivered": int(dict_delivered),
        "subscription_exhausted": bool(dict_exhausted),
        "is_pro": is_pro,
        "is_admin": is_admin,
    })


