@app.route("/api/shortcut/pairing-code", methods=["POST"])
def shortcut_create_pairing_code():
    body = request.get_json(silent=True) or {}
    admin_secret = (
        (os.getenv("SHORTCUT_BOT_SECRET") or "").strip()
        or (os.getenv("SHORTCUT_SECRET") or "").strip()
        or (os.getenv("TELEGRAM_Deutsch_BOT_TOKEN") or "").strip()
        or (os.getenv("ADMIN_TOKEN") or "").strip()
        or (os.getenv("AUDIO_DISPATCH_TOKEN") or "").strip()
    )
    if not admin_secret:
        return jsonify({"error": "Shortcut pairing endpoint не настроен (admin secret not set)"}), 503

    auth_header = (request.headers.get("Authorization") or "").strip()
    header_secret = (request.headers.get("X-Shortcut-Bot-Secret") or "").strip()
    provided_secret = ""
    if auth_header.lower().startswith("bearer "):
        provided_secret = auth_header[7:].strip()
    elif header_secret:
        provided_secret = header_secret
    else:
        provided_secret = str(body.get("secret") or body.get("token") or "").strip()

    if not provided_secret:
        return jsonify({"error": "shortcut admin secret required"}), 401
    if not hmac.compare_digest(provided_secret, admin_secret):
        return jsonify({"error": "invalid shortcut admin secret"}), 401

    raw_user_id = body.get("user_id")
    if raw_user_id is None or str(raw_user_id).strip() == "":
        return jsonify({"error": "user_id обязателен"}), 400
    try:
        user_id = int(str(raw_user_id).strip())
    except Exception:
        return jsonify({"error": "user_id должен быть числом"}), 400
    if not is_telegram_user_allowed(user_id):
        return jsonify({"error": "Пользователь не имеет доступа"}), 403

    allowed, limiter_response = _shortcut_enforce_pairing_code_issuance_limit(user_id=user_id)
    if not allowed:
        return limiter_response

    ttl_raw = body.get("ttl_seconds")
    ttl_seconds = None
    if ttl_raw is not None and str(ttl_raw).strip() != "":
        try:
            ttl_seconds = max(60, int(str(ttl_raw).strip()))
        except Exception:
            return jsonify({"error": "ttl_seconds должен быть числом"}), 400

    try:
        result = create_shortcut_pairing_code(user_id=user_id, ttl_seconds=ttl_seconds)
    except Exception as exc:
        if "shortcut schema unavailable" in str(exc).strip().lower():
            return jsonify({"error": "Shortcut processing is temporarily unavailable"}), 503
        raise
    return jsonify(_build_shortcut_pairing_code_response(result)), 200


@app.route("/api/shortcut/link", methods=["POST"])
def shortcut_link_installation():
    body = request.get_json(silent=True) or {}
    route_started_perf = time.perf_counter()
    request_id = _build_observability_correlation_id(payload=body, prefix="shortcut_link")
    remote_ip = _shortcut_request_ip()
    pairing_code_present = bool(str(body.get("pairing_code") or "").strip())
    _log_flow_observation(
        "shortcut_link",
        "SHORTCUT_LINK_REQUEST_RECEIVED",
        request_id=request_id,
        correlation_id=request_id,
        remote_ip=remote_ip,
        pairing_code_present=pairing_code_present,
    )
    allowed, limiter_response = _shortcut_enforce_link_ip_limit()
    if not allowed:
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=pairing_code_present,
            final_status="rate_limited",
            http_status=429,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return limiter_response
    pairing_code = str(body.get("pairing_code") or "").strip()
    if not pairing_code:
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=False,
            final_status="error",
            error_code="pairing_code_obligatory",
            http_status=400,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return jsonify({"error": "pairing_code обязателен"}), 400

    allowed, limiter_response = _shortcut_enforce_link_pairing_code_limit(pairing_code=pairing_code)
    if not allowed:
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=True,
            final_status="rate_limited",
            error_code="pairing_code_rate_limited",
            http_status=429,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return limiter_response

    result = link_shortcut_installation(
        pairing_code=pairing_code,
        request_id=request_id,
        remote_ip=remote_ip,
        correlation_id=request_id,
    )
    status = str(result.get("status") or "").strip().lower()
    if status == "schema_unavailable":
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=True,
            final_status="error",
            error_code="shortcut_schema_unavailable",
            http_status=503,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return jsonify({"error": "Shortcut processing is temporarily unavailable"}), 503
    if status == "invalid":
        _shortcut_record_link_pairing_code_failure(pairing_code=pairing_code)
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=True,
            final_status="error",
            error_code="invalid_pairing_code",
            http_status=400,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return jsonify({"error": "invalid_pairing_code"}), 400
    if status == "used":
        _shortcut_record_link_pairing_code_failure(pairing_code=pairing_code)
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=True,
            final_status="error",
            error_code="pairing_code_already_used",
            http_status=409,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return jsonify({"error": "pairing_code_already_used"}), 409
    if status == "expired":
        _shortcut_record_link_pairing_code_failure(pairing_code=pairing_code)
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=True,
            final_status="error",
            error_code="pairing_code_expired",
            http_status=410,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return jsonify({"error": "pairing_code_expired"}), 410
    if status != "linked":
        _log_flow_observation(
            "shortcut_link",
            "SHORTCUT_LINK_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            pairing_code_present=True,
            final_status="error",
            error_code="pairing_link_failed",
            http_status=500,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return jsonify({"error": "pairing_link_failed"}), 500

    response = jsonify(
        {
            "ok": True,
            "installation_id": int(result.get("installation_id") or 0),
            "install_token": str(result.get("install_token") or "").strip(),
            "created_at": result.get("created_at"),
            "expires_at": result.get("expires_at"),
        }
    )
    _log_flow_observation(
        "shortcut_link",
        "SHORTCUT_LINK_RESPONSE_SENT",
        request_id=request_id,
        correlation_id=request_id,
        remote_ip=remote_ip,
        pairing_code_present=True,
        final_status="success",
        http_status=200,
        duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
    )
    return response, 200


_SHORTCUT_RUN_PRO_DAILY = max(1, int((os.getenv("SHORTCUT_RUN_PRO_DAILY") or "2").strip() or "2"))
_SHORTCUT_RUN_FREE_TOTAL = max(0, int((os.getenv("SHORTCUT_RUN_FREE_TOTAL") or "5").strip() or "5"))
# One-time first-day «наладка» pool: on the CALENDAR day of the user's first-ever shortcut
# activation, allow this many SUCCESSFUL runs that do NOT consume the Pro/Free quota — so
# setup fumbling (wrong response-key, re-tests, empty album) never burns the real limit. On
# the setup day the normal quota is NOT also granted; these N runs are the whole day-one
# allowance. From the next calendar day → normal Pro=2/day, Free=5-total. Same pool for both.
_SHORTCUT_RUN_SETUP_POOL = max(0, int((os.getenv("SHORTCUT_RUN_SETUP_POOL") or "5").strip() or "5"))
# Alert admins when one user racks up more than this many BLOCKED attempts in a day
# (broken/edited shortcut or a stolen token hammering the endpoint).
_SHORTCUT_ABUSE_ALERT_THRESHOLD = max(1, int((os.getenv("SHORTCUT_ABUSE_ALERT_THRESHOLD") or "5").strip() or "5"))
# Off-peak send window: «Ночной Переводчик» may only send outside the first-setup grace
# during these hours (server is free). Configurable; fail-open if the clock/tz breaks.
_SHORTCUT_RUN_WINDOW_START = (os.getenv("SHORTCUT_RUN_WINDOW_START") or "05:00").strip()
_SHORTCUT_RUN_WINDOW_END = (os.getenv("SHORTCUT_RUN_WINDOW_END") or "09:00").strip()
_SHORTCUT_RUN_WINDOW_TZ = (os.getenv("SHORTCUT_RUN_WINDOW_TZ") or "Europe/Vienna").strip()
# First-day grace: within this many hours of the user's most recent (re)install the
# window is NOT enforced (setup / retries / after reinstall work at any hour). Grace
# resets on re-pairing. `_SHORTCUT_RUN_WINDOW_GRACE` (run count) is a fallback when the
# install time is unknown.
_SHORTCUT_RUN_WINDOW_GRACE_HOURS = max(0, int((os.getenv("SHORTCUT_RUN_WINDOW_GRACE_HOURS") or "24").strip() or "24"))
_SHORTCUT_RUN_WINDOW_GRACE = max(0, int((os.getenv("SHORTCUT_RUN_WINDOW_GRACE") or "3").strip() or "3"))


def _hhmm_to_minutes(value: str, fallback: int) -> int:
    try:
        hh, mm = str(value).split(":")
        return max(0, min(24 * 60, int(hh) * 60 + int(mm)))
    except Exception:
        return fallback


def _shortcut_within_send_window() -> tuple[bool, str]:
    """(in_window, local_HH:MM). Fail-open (True) if the clock/tz is unavailable — we
    never want a clock glitch to block a legitimate morning run."""
    try:
        from zoneinfo import ZoneInfo
        now_local = datetime.now(ZoneInfo(_SHORTCUT_RUN_WINDOW_TZ))
        now_min = now_local.hour * 60 + now_local.minute
        start_min = _hhmm_to_minutes(_SHORTCUT_RUN_WINDOW_START, 300)
        end_min = _hhmm_to_minutes(_SHORTCUT_RUN_WINDOW_END, 540)
        return (start_min <= now_min < end_min), now_local.strftime("%H:%M")
    except Exception:
        return True, ""


def _shortcut_setup_grace_active(user_id: int, total_runs: int) -> bool:
    """First-day grace: within GRACE_HOURS of the user's most recent (re)install the
    time window is not enforced — so setup, retries and after-reinstall work at any
    hour. Grace resets each time the user re-pairs. Falls back to the first-N-runs
    grace when the install time is unknown."""
    try:
        if _SHORTCUT_RUN_WINDOW_GRACE_HOURS > 0:
            info = get_shortcut_installation_stats(int(user_id))
            li = info.get("last_installed_at")
            if li is not None:
                from datetime import timedelta, timezone as _tz
                now = datetime.now(_tz.utc)
                if getattr(li, "tzinfo", None) is None:
                    li = li.replace(tzinfo=_tz.utc)
                if (now - li) <= timedelta(hours=_SHORTCUT_RUN_WINDOW_GRACE_HOURS):
                    return True
    except Exception:
        pass
    return int(total_runs) < _SHORTCUT_RUN_WINDOW_GRACE


def _shortcut_run_gate(user_id: int) -> tuple[bool, str, dict]:
    """Authoritative per-run limit decision for «Ночной Переводчик». Used by BOTH the
    advisory /run-check AND the actual work endpoint /lookup, so the limit holds even
    if the user hand-edits the shortcut to skip the pre-flight check. Pure decision —
    does NOT write to the DB (the caller records). Returns (allowed, reason, extra):
    extra carries used/limit/window/message on a block, or is_pro/in_window on approval."""
    # ДИАГНОСТИКА 18.08.2026: вместе с вердиктом запоминаем ЕГО ПРИЧИНУ. Замер показал
    # 920 запусков платящего человека, записанных как «бесплатный», и установить почему
    # было нечем — решение нигде не объяснялось. Отдельно различаем «человек free» и
    # «мы не смогли прочитать»: раньше и то и другое давало is_pro=False.
    ent_source = ""
    try:
        ent = resolve_entitlement(user_id=int(user_id), tz="Europe/Vienna")
        is_pro = str(ent.get("effective_mode") or "free").strip().lower() in ("pro", "trial")
        ent_source = str(ent.get("source_of_entitlement") or "")
    except Exception:
        is_pro = False
        ent_source = "ошибка чтения прав"
        logging.exception("shortcut gate: не смог прочитать права user_id=%s", user_id)
    try:
        is_admin = int(user_id) in {int(a) for a in get_admin_telegram_ids()}
    except Exception:
        is_admin = False
    total_runs = count_shortcut_runs_total(int(user_id))
    in_window, _local = _shortcut_within_send_window()
    base = {"is_pro": is_pro, "is_admin": is_admin, "in_window": in_window,
            "total_runs": total_runs, "entitlement_source": ent_source}
    # 0) first-day SETUP POOL — on the user's first-ever activation calendar day, hand out a
    # one-time «наладка» allowance that does NOT touch the Pro/Free quota (setup runs are
    # recorded with reason='setup' and excluded from the quota counters), so setup fumbling
    # doesn't burn the real limit. Anti-farm: the setup day is pinned to the FIRST pairing
    # (is_shortcut_setup_day), so re-pairing later never re-grants it. On the setup day the
    # normal quota is NOT additionally granted — these N runs are day-one's whole allowance —
    # and the time window is skipped (наладка at any hour). Admins bypass everything below.
    if not is_admin and _SHORTCUT_RUN_SETUP_POOL > 0 and is_shortcut_setup_day(int(user_id)):
        setup_used = count_shortcut_setup_runs_today(int(user_id))
        base["setup_day"] = True
        base["setup_used"] = setup_used
        if setup_used >= _SHORTCUT_RUN_SETUP_POOL:
            return False, "setup_used_up", {**base, "used": setup_used, "limit": _SHORTCUT_RUN_SETUP_POOL,
                "message": (f"Наладочные запуски на сегодня ({_SHORTCUT_RUN_SETUP_POOL}) закончились. "
                            "Ты всё настроил — завтра утром «Ночной Переводчик» заработает в обычном режиме.")}
        return True, "setup", base
    # 1) quota (count) — only approved runs count; admins exempt
    if not is_admin:
        if is_pro:
            used_today = count_shortcut_runs_today(int(user_id))
            base["used_today"] = used_today
            if used_today >= _SHORTCUT_RUN_PRO_DAILY:
                # Hard daily cap — no grace. The user is warned right after the 2nd send
                # («all sends used today»), so a 3rd is on them. DROP (don't process/save).
                return False, "pro_daily", {**base, "used": used_today, "limit": _SHORTCUT_RUN_PRO_DAILY,
                    "message": f"Лимит «Полного доступа» — {_SHORTCUT_RUN_PRO_DAILY} отправки в день — уже исчерпан. Больше сегодня не отправляй. Завтра утром снова доступно."}
        elif total_runs >= _SHORTCUT_RUN_FREE_TOTAL:
            return False, "free_total", {**base, "used": total_runs, "limit": _SHORTCUT_RUN_FREE_TOTAL,
                "message": f"Бесплатные пробные запуски ({_SHORTCUT_RUN_FREE_TOTAL}) закончились. Оформите полный доступ, чтобы пользоваться дальше."}
    # 2) time window — skipped during first-day grace and for admins
    grace_active = _shortcut_setup_grace_active(int(user_id), total_runs)
    if (not grace_active) and (not is_admin) and (not in_window):
        return False, "time_window", {**base, "window": f"{_SHORTCUT_RUN_WINDOW_START}–{_SHORTCUT_RUN_WINDOW_END}",
            "message": f"Отправка доступна утром ({_SHORTCUT_RUN_WINDOW_START}–{_SHORTCUT_RUN_WINDOW_END}). Поставь автозапуск на это время — всё пойдёт само."}
    # 3) approved
    return True, ("grace" if grace_active else ("admin" if is_admin else "ok")), base


def _shortcut_send_dm(user_id: int, caption: str, poster, *, pro_button: bool) -> None:
    """Send one shortcut-status DM (photo card if available, else text). pro_button adds
    the «✨ Оформить Pro» → subscription button (Free upsell); Pro users get no button."""
    reply_markup = None
    if pro_button:
        reply_markup = json.dumps({"inline_keyboard": [[
            {"text": "✨ Оформить полный доступ", "url": _build_webapp_deeplink("subscription")}]]})
    token = TELEGRAM_Deutsch_BOT_TOKEN
    # Это уходит ЧЕЛОВЕКУ, а не в лог: если карточка не дошла, он просто не получил
    # результат своего запуска и не узнает почему. Telegram отвечает на отказ телом
    # `{"ok": false, …}`, а не исключением, поэтому прежний вызов без взгляда на ответ
    # считал доставленным даже то, что бот отправить не смог.
    try:
        if poster:
            data = {"chat_id": int(user_id), "caption": caption, "parse_mode": "HTML"}
            if reply_markup:
                data["reply_markup"] = reply_markup
            ответ = requests.post(f"https://api.telegram.org/bot{token}/sendPhoto",
                                  data=data, files={"photo": ("card.png", poster, "image/png")},
                                  timeout=30)
            тело = ответ.json() if ответ.content else {}
            if ответ.status_code != 200 or not тело.get("ok"):
                logging.warning("карточка Ярлыка не дошла до %s — %s", user_id,
                                str(тело.get("description") or f"HTTP {ответ.status_code}"))
        else:
            from backend.telegram_delivery import send_telegram_message
            дошло, почему = send_telegram_message(
                chat_id=int(user_id), text=caption, token=token,
                reply_markup=json.loads(reply_markup) if reply_markup else None,
                what="карточка Ярлыка")
            if not дошло:
                logging.warning("карточка Ярлыка не дошла до %s — %s", user_id, почему)
    except Exception:
        logging.warning("shortcut DM send failed user=%s", user_id, exc_info=True)


def _notify_shortcut_run_status(user_id: int, reason: str, extra: dict) -> None:
    """Friendly DM when a run is limited. free_total = trial ended (once EVER, Free upsell).
    pro_used_up = the 2nd (last) send of the day just went through — soft «you're out for
    today» warning. pro_daily = a 3rd+ run was DROPPED. Both Pro cases share ONE DM/day
    (the proactive pro_used_up normally fires first). Guards stop it nagging on retries."""
    try:
        import datetime as _dt
        today = _dt.date.today().isoformat()
        if reason == "free_total":
            if not mark_announcement_sent(int(user_id), "shortcut_trial_ended_v1"):
                return
            limit = int(extra.get("limit") or _SHORTCUT_RUN_FREE_TOTAL)
            try:
                from backend.interactive_card import render_shortcut_limit_card
                poster = render_shortcut_limit_card(limit=limit)
            except Exception:
                poster = None
            caption = ("🔒 <b>Пробные запуски закончились</b>\n\n"
                "Ты запустил авто-перевод скриншотов из папки, но на бесплатном доступно только "
                f"<b>{limit}</b> запусков — чтобы попробовать, как это работает.\n\n"
                "Поэтому последняя операция <b>не прошла</b> — фото не переведены.\n\n"
                "Хочешь пользоваться дальше — оформи <b>Полный доступ</b> 👇")
            _shortcut_send_dm(user_id, caption, poster, pro_button=True)
        elif reason in ("pro_used_up", "pro_daily"):
            # one DM per day covers both the proactive «you're out» and any later drop
            if not mark_announcement_sent(int(user_id), f"shortcut_pro_daily_{today}"):
                return
            limit = int(extra.get("limit") or _SHORTCUT_RUN_PRO_DAILY)
            try:
                from backend.interactive_card import render_shortcut_pro_limit_card
                poster = render_shortcut_pro_limit_card(limit=limit)
            except Exception:
                poster = None
            if reason == "pro_used_up":
                caption = (f"✅ <b>На сегодня всё — обе отправки пришли</b>\n\n"
                    f"В «Полном доступе» доступно <b>{limit}</b> отправки в день (в каждой — до 25 фото), в утренние часы.\n\n"
                    "❗️<b>Больше сегодня не запускай</b> «Ночной Переводчик»: следующие фото просто удалятся из папки, "
                    "а перевод не придёт. Завтра утром снова доступно.")
            else:
                caption = (f"🚫 <b>Лимит на сегодня исчерпан</b>\n\n"
                    f"В «Полном доступе» — <b>{limit}</b> отправки в день. Этот запуск <b>не обработан</b>, фото из папки удалены.\n\n"
                    "Не запускай больше сегодня — завтра утром снова доступно.")
            _shortcut_send_dm(user_id, caption, poster, pro_button=False)
        elif reason == "setup_used_up":
            # First-day setup pool spent — one gentle DM/day, no poster, no upsell.
            if not mark_announcement_sent(int(user_id), f"shortcut_setup_used_up_{today}"):
                return
            limit = int(extra.get("limit") or _SHORTCUT_RUN_SETUP_POOL)
            caption = (f"✅ <b>Наладка завершена — {limit} пробных запусков за сегодня использованы</b>\n\n"
                "«Ночной Переводчик» настроен. Этот запуск дальше <b>не обрабатывался</b>.\n\n"
                "⏰ Завтра утром он заработает в обычном режиме — поставь автозапуск на утро, и всё пойдёт само.")
            _shortcut_send_dm(user_id, caption, None, pro_button=False)
    except Exception:
        logging.warning("shortcut run-status DM failed user=%s reason=%s", user_id, reason, exc_info=True)


def _shortcut_check_abuse(user_id: int) -> None:
    """When one user racks up more than _SHORTCUT_ABUSE_ALERT_THRESHOLD blocked attempts in
    a day (broken/edited shortcut or a stolen token hammering the endpoint), DM the admins
    ONCE that day. Called right after a denial is recorded."""
    try:
        denied = count_shortcut_denied_runs_today(int(user_id))
        if denied <= _SHORTCUT_ABUSE_ALERT_THRESHOLD:
            return
        import datetime as _dt
        today = _dt.date.today().isoformat()
        if not mark_announcement_sent(int(user_id), f"shortcut_abuse_alert_{today}"):
            return  # already alerted for this user today
        text = (f"⚠️ <b>Shortcut: подозрение на абьюз</b>\n\n"
                f"user_id <code>{int(user_id)}</code> — <b>{denied}</b> отказов сегодня "
                f"(&gt;{_SHORTCUT_ABUSE_ALERT_THRESHOLD}).\n\n"
                f"Вероятно, сломанный/отредактированный шорткат или украденный токен долбит эндпоинт. "
                f"Смотри <code>/shortcut_runs</code>. При необходимости отзови токен (пользователь переустанавливает — re-pair).")
        # Тревога о злоупотреблении — сообщение, которое обязано дойти. Здесь стояло
        # `except Exception: pass`: отказ Telegram глушился насовсем, и тревога могла
        # не приходить, ничем себя не выдав.
        from backend.telegram_delivery import send_telegram_message
        token = TELEGRAM_Deutsch_BOT_TOKEN
        for admin_id in get_admin_telegram_ids():
            дошло, почему = send_telegram_message(
                chat_id=int(admin_id), text=text, token=token,
                what="тревога о злоупотреблении Ярлыком")
            if not дошло:
                logging.warning("тревога о злоупотреблении не дошла до %s — %s", admin_id, почему)
    except Exception:
        logging.debug("shortcut abuse check failed user=%s", user_id, exc_info=True)


@app.route("/api/shortcut/run-check", methods=["POST"])
def shortcut_run_check():
    """Per-RUN gate for «Ночной Переводчик». The shortcut MUST call this FIRST and,
    on allowed=false, STOP without deleting the album photos.
    Rules: Pro ≤ N runs/day, Free ≤ N trial runs total (persistent — anti-cheat via
    the stable user_id); sends only within the off-peak window EXCEPT the first N
    setup runs (grace) and admins. Every decision is logged for the admin report."""
    body = request.get_json(silent=True) or {}
    _text, install_token = _shortcut_lookup_request_payload(body)
    if not install_token:
        return jsonify({"allowed": False, "error": "install_token обязателен"}), 400
    request_id = _build_observability_correlation_id(payload=body, prefix="shortcut_run_check")
    remote_ip = _shortcut_request_ip()
    installation = resolve_shortcut_install_token(
        install_token=install_token, request_id=request_id, remote_ip=remote_ip,
    )
    if isinstance(installation, dict) and str(installation.get("status") or "").strip().lower() == "schema_unavailable":
        return jsonify({"allowed": False, "error": "temporarily_unavailable"}), 503
    if not installation:
        return jsonify({"allowed": False, "error": "invalid_install_token"}), 401
    user_id = int(installation.get("user_id") or 0)
    if user_id <= 0:
        return jsonify({"allowed": False, "error": "invalid_install_token"}), 401
    if not is_telegram_user_allowed(user_id):
        return jsonify({"allowed": False, "reason": "no_access", "message": "Доступ закрыт."}), 403
    # Advisory pre-flight: decide via the SHARED gate. The ACTUAL run is recorded at the
    # work endpoint (/lookup), which re-runs the same gate — so a well-behaved shortcut
    # sees the verdict here and stops early, but the real enforcement lives on /lookup
    # (holds even if the shortcut is hand-edited to skip this call).
    allowed, reason, extra = _shortcut_run_gate(int(user_id))
    if not allowed:
        record_shortcut_run_check(user_id, allowed=False, reason=reason,
                                  is_pro=extra.get("is_pro"), in_window=extra.get("in_window"),
                                  run_index=extra.get("total_runs"),
                                  entitlement_source=extra.get("entitlement_source"))
        _shortcut_check_abuse(int(user_id))  # alert admins if this user is hammering the endpoint
        payload = {"allowed": False, "reason": reason}
        for k in ("used", "limit", "window", "message"):
            if k in extra:
                payload[k] = extra[k]
        return jsonify(payload), 200
    # `reason` echoed for diagnosis: "admin"=exempt from caps, "grace"=first-day, "ok"=counted.
    return jsonify({"allowed": True, "reason": reason, "used": int(extra.get("total_runs", 0)) + 1,
                    "is_pro": extra.get("is_pro"), "is_admin": extra.get("is_admin"),
                    "in_window": extra.get("in_window")}), 200


@app.route("/api/shortcut/lookup", methods=["POST"])
def shortcut_dictionary_lookup():
    route_started_perf = time.perf_counter()
    body = request.get_json(silent=True) or {}
    text, install_token = _shortcut_lookup_request_payload(body)
    request_id = _build_observability_correlation_id(payload=body, prefix="shortcut_lookup")
    remote_ip = _shortcut_request_ip()
    _log_flow_observation(
        "shortcut_lookup",
        "SHORTCUT_LOOKUP_REQUEST_RECEIVED",
        request_id=request_id,
        correlation_id=request_id,
        remote_ip=remote_ip,
        install_token_present=bool(install_token),
        text_present=bool(text),
    )
    if not install_token:
        _log_flow_observation(
            "shortcut_lookup",
            "SHORTCUT_LOOKUP_RESPONSE_SENT",
            request_id=request_id,
            correlation_id=request_id,
            remote_ip=remote_ip,
            install_token_present=False,
            text_present=bool(text),
            final_status="error",
            error_code="install_token_obligatory",
            http_status=400,
            duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
        )
        return jsonify({"error": "install_token обязателен"}), 400
    result, status = _shortcut_lookup_from_install_token(install_token=install_token, text=text, request_id=request_id, remote_ip=remote_ip)
    _log_flow_observation(
        "shortcut_lookup",
        "SHORTCUT_LOOKUP_RESPONSE_SENT",
        request_id=request_id,
        correlation_id=request_id,
        remote_ip=remote_ip,
        install_token_present=True,
        text_present=bool(text),
        final_status="success" if int(status) == 200 else "error",
        error_code=str(result.get("error") or "").strip() or None,
        http_status=int(status),
        duration_ms=max(0, int((time.perf_counter() - route_started_perf) * 1000)),
    )
    return jsonify(result), status


@app.route("/api/internal/bot-private/dictionary/save", methods=["POST"])
def save_bot_private_dictionary_entry():
    payload = request.get_json(silent=True) or {}
    token = str(payload.get("token") or request.headers.get("X-Admin-Token") or "").strip()
    required_token = (os.getenv("ADMIN_TOKEN") or os.getenv("AUDIO_DISPATCH_TOKEN") or "").strip()
    if not required_token:
        return jsonify({"error": "ADMIN_TOKEN не задан"}), 500
    if token != required_token:
        return jsonify({"error": "Неверный токен"}), 401

    user_id_raw = payload.get("user_id")
    if user_id_raw is None or str(user_id_raw).strip() == "":
        return jsonify({"error": "user_id обязателен"}), 400
    try:
        user_id = int(str(user_id_raw).strip())
    except Exception:
        return jsonify({"error": "user_id должен быть числом"}), 400
    if not is_telegram_user_allowed(int(user_id)):
        return jsonify({"error": "Доступ пользователя к Telegram-боту закрыт"}), 403

    source_text = str(
        payload.get("save_source_text")
        or payload.get("source_text")
        or payload.get("word")
        or payload.get("word_ru")
        or payload.get("word_de")
        or ""
    ).strip()
    target_text = str(
        payload.get("save_target_text")
        or payload.get("target_text")
        or payload.get("translation")
        or payload.get("translation_ru")
        or payload.get("translation_de")
        or ""
    ).strip()
    response_json = payload.get("response_json") if isinstance(payload.get("response_json"), dict) else {}
    payload_source_lang = payload.get("source_lang")
    payload_target_lang = payload.get("target_lang")
    payload_direction = payload.get("direction")
    folder_id = payload.get("folder_id")
    origin_meta = payload.get("origin_meta") if isinstance(payload.get("origin_meta"), dict) else {}

    if not source_text and not response_json:
        return jsonify({"error": "source_text/save_source_text обязателен"}), 400

    profile_source_lang, profile_target_lang, _profile = _get_user_language_pair(int(user_id))
    source_lang, target_lang = _resolve_dictionary_save_pair(
        profile_source_lang=profile_source_lang,
        profile_target_lang=profile_target_lang,
        payload_source_lang=payload_source_lang,
        payload_target_lang=payload_target_lang,
        payload_direction=payload_direction,
        response_json=response_json if isinstance(response_json, dict) else None,
    )

    # Вычитка на входе из ЛИЧНОГО ЧАТА С БОТОМ. Слово сюда ПРИСЛАЛ человек — значит это
    # тот самый случай, ради которого вычитка и существует: опечатка, чужой артикль,
    # неверный падеж не должны уехать в общий словарь. Правило одно на все двери и живёт
    # в `_save_source_was_typed_by_user`; здесь оно спрашивается явно, чтобы дверь не
    # разошлась с остальными, если ярлык источника когда-нибудь поменяется.
    corrected_source = _proofread_dictionary_phrase(
        source_text, source_lang=source_lang, user_id=int(user_id),
    ) if _save_source_was_typed_by_user("bot_private_save") else ""
    if corrected_source and corrected_source != source_text:
        logging.info("бот: сохраняемая фраза исправлена %r → %r",
                     source_text[:60], corrected_source[:60])
        source_text = corrected_source

    lookup_used = False
    if source_text and _is_single_word_dictionary_entry(source_text, source_lang):
        try:
            normalized_word = _normalize_dictionary_lookup_word(source_text)
            query_source_lang, query_target_lang = _resolve_dictionary_query_languages(
                word=normalized_word,
                source_lang=source_lang,
                target_lang=target_lang,
                lookup_lang=_normalize_short_lang_code(payload.get("lookup_lang"), fallback="") or source_lang,
            )
            lookup_payload = _run_dictionary_full_lookup_sync(
                word=normalized_word,
                source_lang=source_lang,
                target_lang=target_lang,
                query_source_lang=query_source_lang,
                query_target_lang=query_target_lang,
                lookup_lang=query_source_lang,
                user_id=int(user_id),
            )
            lookup_item = lookup_payload.get("item") if isinstance(lookup_payload.get("item"), dict) else {}
            lookup_direction = str(lookup_payload.get("direction") or "").strip().lower()
            if lookup_item:
                response_json = lookup_item
                payload_direction = lookup_direction or payload_direction
                lookup_used = True
                source_lang, target_lang = _resolve_dictionary_save_pair(
                    profile_source_lang=profile_source_lang,
                    profile_target_lang=profile_target_lang,
                    payload_source_lang=payload_source_lang,
                    payload_target_lang=payload_target_lang,
                    payload_direction=payload_direction,
                    response_json=response_json,
                )
                source_text = str(response_json.get("source_text") or source_text).strip()
                target_text = str(response_json.get("target_text") or target_text).strip()
        except Exception as exc:
            logging.warning(
                "Private bot dictionary auto-lookup failed user_id=%s source_text=%r: %s",
                int(user_id),
                source_text,
                exc,
                exc_info=True,
            )

    word_ru = str(payload.get("word_ru") or response_json.get("word_ru") or "").strip()
    word_de = str(payload.get("word_de") or response_json.get("word_de") or "").strip()
    translation_de = str(payload.get("translation_de") or response_json.get("translation_de") or "").strip()
    translation_ru = str(payload.get("translation_ru") or response_json.get("translation_ru") or "").strip()

    if source_lang == "ru" and target_lang == "de":
        if source_text and not word_ru:
            word_ru = source_text
        if target_text and not translation_de:
            translation_de = target_text
        if target_text and not word_de:
            word_de = target_text
        if source_text and not translation_ru:
            translation_ru = source_text
    elif source_lang == "de" and target_lang == "ru":
        if source_text and not word_de:
            word_de = source_text
        if target_text and not translation_ru:
            translation_ru = target_text
        if target_text and not word_ru:
            word_ru = target_text
        if source_text and not translation_de:
            translation_de = source_text

    source_text, target_text, word_ru, word_de, translation_de, translation_ru = _align_dictionary_legacy_ru_de_columns(
        source_lang=source_lang,
        target_lang=target_lang,
        source_text=source_text,
        target_text=target_text,
        word_ru=word_ru,
        word_de=word_de,
        translation_de=translation_de,
        translation_ru=translation_ru,
    )
    (
        source_lang, target_lang, source_text, target_text,
        word_ru, word_de, translation_de, translation_ru,
    ) = _correct_inverted_dictionary_scripts(
        source_lang=source_lang,
        target_lang=target_lang,
        source_text=source_text,
        target_text=target_text,
        word_ru=word_ru,
        word_de=word_de,
        translation_de=translation_de,
        translation_ru=translation_ru,
    )

    if folder_id is None:
        try:
            default_folder = get_or_create_dictionary_folder(
                user_id=user_id,
                name="GENERAL",
                color="#7d8590",
                icon="📁",
            )
            folder_id = default_folder.get("id")
        except Exception:
            folder_id = None

    response_json = _prepare_dictionary_response_json_for_save(
        response_json=response_json if isinstance(response_json, dict) else {},
        source_text=source_text or word_ru or word_de or "",
        target_text=target_text or translation_de or translation_ru or word_de or "",
        source_lang=source_lang,
        target_lang=target_lang,
        word_ru=word_ru or None,
        word_de=word_de or None,
        translation_de=translation_de or None,
        translation_ru=translation_ru or None,
    )
    word_ru = str(response_json.get("word_ru") or word_ru or "").strip()
    word_de = str(response_json.get("word_de") or word_de or "").strip()
    translation_de = str(response_json.get("translation_de") or translation_de or "").strip()
    translation_ru = str(response_json.get("translation_ru") or translation_ru or "").strip()
    origin_meta = {
        **origin_meta,
        "endpoint": "/api/internal/bot-private/dictionary/save",
        "flow": str(origin_meta.get("flow") or "private_bot_save").strip() or "private_bot_save",
        "lookup_used": bool(lookup_used),
    }
    if payload_direction and "direction" not in origin_meta:
        origin_meta["direction"] = str(payload_direction)

    try:
        entry_id = _save_dictionary_entry_with_schema_retry(
            user_id=user_id,
            word_ru=word_ru or None,
            translation_de=translation_de or None,
            word_de=word_de or None,
            translation_ru=translation_ru or None,
            response_json=response_json,
            folder_id=int(folder_id) if folder_id is not None else None,
            source_lang=source_lang,
            target_lang=target_lang,
            origin_process="bot_private_save",
            origin_meta=origin_meta,
        )
        _start_saved_dictionary_entry_enrichment(
            entry_id=int(entry_id or 0),
            response_json=response_json,
            source_lang=source_lang,
            target_lang=target_lang,
            source_text_hint=source_text,
            target_text_hint=target_text,
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка сохранения словаря: {exc}"}), 500

    return jsonify(
        {
            "ok": True,
            "entry_id": int(entry_id or 0),
            "lookup_used": bool(lookup_used),
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
            "item": response_json,
        }
    )


@app.route("/api/webapp/dictionary/cards", methods=["POST"])
def get_webapp_dictionary_cards():
    payload = request.get_json(silent=True) or {}
    limit = payload.get("limit", 100)
    folder_mode = payload.get("folder_mode", "all")
    folder_id = payload.get("folder_id")
    search = payload.get("search")
    offset = payload.get("offset", 0)

    # Пользователя определяем общим способом: сессией Telegram ИЛИ долговременным
    # токеном словаря. Раньше здесь требовалась только сессия — и словарь, открытый
    # иконкой с рабочего стола, получал отказ: он живёт вне Telegram и работает по
    # токену. Владелец 10.08.2026 увидел это как «Мои слова» с ошибкой на пустом экране.
    user_id = _resolve_webapp_user_id(payload)
    if not user_id:
        return jsonify({"error": "Не удалось определить пользователя"}), 401

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    try:
        items = get_webapp_dictionary_entries(
            user_id=user_id,
            limit=int(limit),
            folder_mode=folder_mode,
            folder_id=int(folder_id) if folder_id is not None else None,
            source_lang=source_lang,
            target_lang=target_lang,
            search=search,
            offset=int(offset or 0),
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка получения словаря: {exc}"}), 500

    direction = f"{source_lang}-{target_lang}"
    decorated_items = [
        _decorate_dictionary_item(
            item if isinstance(item, dict) else {},
            source_lang=source_lang,
            target_lang=target_lang,
            direction=direction,
        )
        for item in items
    ]
    return jsonify(
        {
            "ok": True,
            "items": decorated_items,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


@app.route("/api/webapp/dictionary/distractors", methods=["POST"])
def get_webapp_dictionary_distractors():
    """Random learning-language words from the shared pool, used to fill quiz options to
    4 when the local session/dictionary is too small (single-word «разбор» sessions, or a
    fresh account without the starter dictionary). Best-effort: on any error return an
    empty list so the quiz just falls back to whatever local options it had."""
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))
    try:
        limit = max(1, min(60, int(payload.get("limit", 12) or 12)))
    except (TypeError, ValueError):
        limit = 12
    exclude = payload.get("exclude") or []
    exclude_norms = {str(x or "").strip().lower() for x in exclude if str(x or "").strip()}

    # The quiz options are in the learning language (German for this app); target_lang is
    # the learning side of the canonical native→learning pair.
    try:
        words = fetch_random_pool_words(
            source_lang=source_lang,
            target_lang=target_lang,
            learning_lang=target_lang,
            limit=limit,
            exclude_norms=exclude_norms,
        )
    except Exception as exc:
        logger.warning("distractor pool fetch failed for user %s: %s", user_id, exc)
        words = []

    return jsonify({"ok": True, "words": words})


@app.route("/api/webapp/dictionary/folders", methods=["POST"])
def list_webapp_dictionary_folders():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    try:
        items = get_dictionary_folders(user_id=user_id)
    except Exception as exc:
        return jsonify({"error": f"Ошибка получения папок: {exc}"}), 500

    return jsonify({"ok": True, "items": items})


@app.route("/api/webapp/dictionary/folders/create", methods=["POST"])
def create_webapp_dictionary_folder():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    name = (payload.get("name") or "").strip()
    color = (payload.get("color") or "").strip()
    icon = (payload.get("icon") or "").strip()

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not name:
        return jsonify({"error": "name обязателен"}), 400
    if not color:
        return jsonify({"error": "color обязателен"}), 400
    if not icon:
        return jsonify({"error": "icon обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    try:
        folder = create_dictionary_folder(user_id=user_id, name=name, color=color, icon=icon)
    except Exception as exc:
        return jsonify({"error": f"Ошибка создания папки: {exc}"}), 500

    return jsonify({"ok": True, "item": folder})


@app.route("/api/webapp/vocabulary/list", methods=["POST"])
def webapp_vocabulary_list():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401
    parsed = _parse_telegram_init_data(init_data)
    user_id = (parsed.get("user") or {}).get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует"}), 400

    raw_folder = payload.get("folder_id")
    folder_id = None
    if raw_folder is not None:
        try:
            folder_id = int(raw_folder)
        except (TypeError, ValueError):
            pass

    search = (payload.get("search") or "").strip() or None
    sort = str(payload.get("sort") or "date_desc").strip()
    limit = max(1, min(100, int(payload.get("limit") or 50)))
    offset = max(0, int(payload.get("offset") or 0))
    updated_since = _parse_iso_datetime(payload.get("updated_since"))

    try:
        result = list_user_vocabulary(
            user_id=user_id,
            folder_id=folder_id,
            search=search,
            sort=sort,
            limit=limit,
            offset=offset,
            updated_since=updated_since,
        )
        folders_data = get_vocabulary_folders_with_counts(user_id=user_id)
    except Exception as exc:
        return _сбой_запроса(exc, что="webapp_vocabulary_list", код=500)

    # Признак админа нужен списку, чтобы показать кнопку пересборки разбора. Отдаём
    # здесь, а не отдельным запросом: список и так грузится при каждом открытии словаря.
    try:
        is_admin = int(user_id) in {int(a) for a in get_admin_telegram_ids()}
    except Exception:
        is_admin = False

    return jsonify({"ok": True, **result, "folders_meta": folders_data, "is_admin": is_admin})


@app.route("/api/webapp/vocabulary/pool-search", methods=["POST"])
def webapp_vocabulary_pool_search():
    """Поиск по общему словарю — тому, что у нас уже разобрано и лежит в пуле.

    Открыт всем и не зависит от подписки на базовый словарь: цель ровно обратная —
    чтобы человек нашёл слово У НАС и не заказывал за деньги разбор того, что мы уже
    знаем. Выдаёт только то, чего у него ещё нет: своё он видит в первом списке.
    Никаких обращений к модели здесь нет, это чтение из своей базы.
    """
    payload = request.get_json(silent=True) or {}
    user_id = _resolve_webapp_user_id(payload)
    if not user_id:
        return jsonify({"error": "initData не прошёл проверку"}), 401

    query = str(payload.get("query") or payload.get("search") or "").strip()
    if not query:
        return jsonify({"ok": True, "items": []})
    try:
        limit = max(1, min(60, int(payload.get("limit") or 40)))
    except (TypeError, ValueError):
        limit = 40

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))
    try:
        items = search_shared_dictionary(
            user_id=int(user_id),
            query=query,
            source_lang=source_lang,
            target_lang=target_lang,
            limit=limit,
        )
    except Exception:
        logging.exception("pool search failed for user=%s", user_id)
        return jsonify({"error": "Не удалось найти в общем словаре"}), 500

    return jsonify({"ok": True, "items": items})


@app.route("/api/webapp/vocabulary/add-from-pool", methods=["POST"])
def webapp_vocabulary_add_from_pool():
    """Перенести слово из общего словаря в личный.

    Разбор уже сделан и лежит в пуле, поэтому здесь НЕТ ни вычитки текста, ни
    дообогащения — это чистое копирование готовой карточки. Бесплатный дневной
    потолок сохранений тот же, что у обычного сохранения слова.
    """
    payload = request.get_json(silent=True) or {}
    user_id = _resolve_webapp_user_id(payload)
    if not user_id:
        return jsonify({"error": "initData не прошёл проверку"}), 401

    try:
        entry_id = int(payload.get("entry_id") or 0)
    except (TypeError, ValueError):
        entry_id = 0
    try:
        unit_id = int(payload.get("unit_id") or 0)
    except (TypeError, ValueError):
        unit_id = 0
    if entry_id <= 0 and unit_id <= 0:
        return jsonify({"error": "не указано, какое слово добавить"}), 400

    # Слово из слоя единиц: карточку собирает тот же сборщик, что отдаёт разбор в
    # приложении, — так в личный словарь попадает ровно то, что человек видел на экране.
    entry = None
    if unit_id > 0:
        display = lex_units.unit_display(unit_id)
        if display:
            item = lex_units.lookup(display, source_lang="de", target_lang="ru") or {}
            if item:
                entry = {
                    "source_lang": "de",
                    "target_lang": "ru",
                    "word_de": str(item.get("word_de") or item.get("source_text") or "").strip(),
                    "word_ru": str(item.get("word_ru") or item.get("target_text") or "").strip(),
                    "translation_de": str(item.get("translation_de") or "").strip(),
                    "translation_ru": str(item.get("translation_ru") or item.get("target_text") or "").strip(),
                    "response_json": {k: v for k, v in item.items() if not k.startswith("__")},
                }
    if entry is None and entry_id > 0:
        entry = get_dictionary_pool_entry(entry_id)
    if not entry:
        return jsonify({"error": "Слово не найдено в общем словаре"}), 404

    source_lang = str(entry.get("source_lang") or "").strip().lower() or "de"
    target_lang = str(entry.get("target_lang") or "").strip().lower() or "ru"
    response_json = entry.get("response_json") if isinstance(entry.get("response_json"), dict) else {}
    word_ru = str(entry.get("word_ru") or "").strip()
    word_de = str(entry.get("word_de") or "").strip()
    translation_ru = str(entry.get("translation_ru") or "").strip()
    translation_de = str(entry.get("translation_de") or "").strip()

    # Лимита здесь нет и быть не может: сюда попадает СТРОКА ОБЩЕГО ПУЛА, то есть слово,
    # которое у нас уже разобрано и переведено. Копирование своей же строки в личный
    # словарь модели не стоит ничего, а лимит мы держим там, где платим (правило владельца
    # от 15.08.2026; тот же принцип — в _dictionary_save_costs_us_nothing).
    #
    # Вместе с лимитом ушла и предварительная проверка на дубликат: она считалась ТОЛЬКО
    # ради него. Повтор по-прежнему не создаёт второй карточки — это делает сама запись,
    # и она же возвращает `inserted`, из которого собирается ответ «уже было».

    folder_id = None
    try:
        default_folder = get_or_create_dictionary_folder(
            user_id=int(user_id), name="GENERAL", color="#7d8590", icon="📁",
        )
        folder_id = default_folder.get("id")
    except Exception:
        folder_id = None

    try:
        saved_id, inserted = _save_dictionary_entry_with_inserted_schema_retry(
            user_id=int(user_id),
            word_ru=word_ru or None,
            translation_de=translation_de,
            word_de=word_de or None,
            translation_ru=translation_ru,
            response_json=response_json,
            folder_id=int(folder_id) if folder_id is not None else None,
            source_lang=source_lang,
            target_lang=target_lang,
            origin_process="vocabulary_add_from_pool",
            origin_meta={
                "endpoint": "/api/webapp/vocabulary/add-from-pool",
                "pool_entry_id": entry_id or None,
                "lex_unit_id": unit_id or None,
            },
        )
    except Exception:
        logging.exception("add-from-pool: save failed for user=%s entry=%s", user_id, entry_id)
        return jsonify({"error": "Не удалось добавить слово"}), 500

    return jsonify({"ok": True, "entry_id": int(saved_id or 0), "already_had": not bool(inserted)})


@app.route("/api/webapp/vocabulary/notes", methods=["POST"])
def webapp_vocabulary_notes():
    """Личные заметки человека к слову.

    Общий разбор они не трогают: лежат отдельной колонкой при карточке, поэтому
    улучшение слова для всех никогда их не затрёт, а заметка никогда не уедет
    другим людям.

    Сохраняем весь список целиком — так интерфейсу не нужно знать про номера заметок
    и порядок, а нам не нужен отдельный путь на «удалить одну»."""
    payload = request.get_json(silent=True) or {}
    user_id = _resolve_webapp_user_id(payload)
    if not user_id:
        return jsonify({"error": "initData не прошёл проверку"}), 401
    try:
        entry_id = int(payload.get("entry_id") or 0)
    except (TypeError, ValueError):
        entry_id = 0
    if entry_id <= 0:
        return jsonify({"error": "entry_id обязателен"}), 400

    try:
        saved = save_card_user_notes(int(user_id), entry_id, payload.get("notes"))
    except Exception:
        logging.exception("не удалось сохранить заметки: user=%s entry=%s", user_id, entry_id)
        return jsonify({"error": "Не удалось сохранить заметку"}), 500
    if saved is None:
        return jsonify({"error": "Слово не найдено"}), 404
    return jsonify({"ok": True, "notes": saved, "limit": USER_NOTES_MAX})


