@app.route("/api/webapp/reader/library/delete", methods=["POST"])
def reader_library_delete():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    document_id = payload.get("document_id")

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if document_id is None:
        return jsonify({"error": "document_id обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401
    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))
    ingest_state = None
    try:
        ingest_state = get_reader_library_document_ingest_state(
            user_id=int(user_id),
            document_id=int(document_id),
            source_lang=source_lang,
            target_lang=target_lang,
        )
    except Exception:
        ingest_state = None
    try:
        deleted = delete_reader_library_document(
            user_id=int(user_id),
            document_id=int(document_id),
            source_lang=source_lang,
            target_lang=target_lang,
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка удаления книги: {exc}"}), 500
    if not deleted:
        return jsonify({"error": "Книга не найдена"}), 404
    object_key = str(((ingest_state or {}).get("ingest_payload") or {}).get("upload_r2_object_key") or "").strip()
    if object_key:
        try:
            r2_delete_object(object_key)
        except Exception:
            logging.warning(
                "reader delete cleanup failed object_key=%s document_id=%s user_id=%s",
                object_key,
                document_id,
                user_id,
                exc_info=True,
            )
    # Reclaim the book's FULL R2 footprint: the retained source PDF (1-20MB), the rendered
    # page images and the per-page audio were previously orphaned forever on delete. Prefixes
    # are scoped to this exact (user, document). Best-effort — failures logged, never fail the delete.
    for _prefix in (
        f"reader_source/{int(user_id)}/{int(document_id)}/",
        f"reader_pages/{int(user_id)}/{int(document_id)}/",
        f"reader-audio-pages/{int(user_id)}/{int(document_id)}/",
    ):
        try:
            r2_delete_prefix(_prefix)
        except Exception:
            logging.warning(
                "reader delete: R2 prefix cleanup failed prefix=%s document_id=%s user_id=%s",
                _prefix, document_id, user_id, exc_info=True,
            )
    return jsonify({"ok": True, "deleted": True})


def _get_reader_audio_pages_usage_window(user_id: int, *, window_days: int = READER_AUDIO_PAGES_WINDOW_DAYS) -> float:
    normalized_days = max(1, int(window_days or 1))
    window_start = datetime.now(timezone.utc) - timedelta(days=normalized_days)
    try:
        with get_db_connection_context() as conn:
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT COALESCE(SUM(units_value), 0)
                    FROM bt_3_billing_events
                    WHERE user_id = %s
                      AND action_type = 'reader_audio_tts_pages'
                      AND units_type = 'pages'
                      AND event_time >= %s;
                    """,
                    (int(user_id), window_start),
                )
                row = cursor.fetchone()
        return float((row or [0])[0] or 0.0)
    except Exception:
        return 0.0


@app.route("/api/webapp/reader/audio", methods=["POST"])
def reader_audio_export():
    started_perf = time.perf_counter()
    payload = request.get_json(silent=True) or {}
    request_id = _extract_observability_request_id(payload)
    correlation_id = _build_observability_correlation_id(payload=payload, prefix="tts")
    init_data = payload.get("initData")
    document_id = payload.get("document_id")
    page_from = payload.get("page_from")
    page_to = payload.get("page_to")
    requested_language = str(payload.get("language") or "").strip()
    user_id_int: int | None = None
    db_lookup_duration_ms = 0

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if document_id is None:
        return jsonify({"error": "document_id обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401
    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    user_id_int = int(user_id)
    correlation_id = _build_observability_correlation_id(
        payload=payload,
        fallback_seed=f"reader-{user_id_int}-{document_id}",
        prefix="tts",
    )
    now_utc = datetime.now(timezone.utc)
    source_lang, target_lang, _profile = _get_user_language_pair(user_id_int)
    entitlement, _subscription = _resolve_user_entitlement(user_id=user_id_int, now_ts_utc=now_utc, tz="Europe/Vienna")
    effective_mode = str(entitlement.get("effective_mode") or "free").lower()
    if effective_mode not in {"pro", "trial"}:
        return jsonify(
            {
                "error": "Аудио-конвертация книг в Reader доступна только на премиум подписке. Перейдите на премиум подписку.",
                "error_code": "reader_audio_premium_required",
                "upgrade": {
                    "available": True,
                    "plan_code": "pro",
                    "action": "checkout",
                    "endpoint": "/api/billing/create-checkout-session",
                },
            }
        ), 403
    try:
        document_lookup_started_perf = time.perf_counter()
        document = get_reader_library_document(
            user_id=user_id_int,
            document_id=int(document_id),
            source_lang=source_lang,
            target_lang=target_lang,
        )
        db_lookup_duration_ms += _elapsed_ms_since(document_lookup_started_perf)
    except Exception as exc:
        return jsonify({"error": f"Ошибка загрузки документа: {exc}"}), 500
    if not document:
        return jsonify({"error": "Книга не найдена"}), 404

    pages = document.get("content_pages") if isinstance(document.get("content_pages"), list) else []
    selected_page_count = 0
    if pages:
        try:
            start_page = int(page_from) if page_from is not None else 1
            end_page = int(page_to) if page_to is not None else len(pages)
        except Exception:
            return jsonify({"error": "page_from/page_to должны быть числами"}), 400
        start_page = max(1, start_page)
        end_page = max(start_page, min(len(pages), end_page))
        selected_page_count = max(0, end_page - start_page + 1)
        pages_usage_lookup_started_perf = time.perf_counter()
        used_pages_7d = _get_reader_audio_pages_usage_window(
            user_id_int,
            window_days=READER_AUDIO_PAGES_WINDOW_DAYS,
        )
        db_lookup_duration_ms += _elapsed_ms_since(pages_usage_lookup_started_perf)
        limit_pages_7d = float(READER_AUDIO_PAGES_7D_LIMIT)
        if user_id_int not in READER_AUDIO_UNLIMITED_USER_IDS and selected_page_count > 0 and (used_pages_7d + float(selected_page_count)) > limit_pages_7d:
            return jsonify(
                {
                    "error": (
                        f"Лимит Reader Audio: не более {int(limit_pages_7d)} страниц "
                        f"за последние {READER_AUDIO_PAGES_WINDOW_DAYS} дней."
                    ),
                    "error_code": "reader_audio_page_limit_exceeded",
                    "limit_pages_7d": int(limit_pages_7d),
                    "window_days": int(READER_AUDIO_PAGES_WINDOW_DAYS),
                    "used_pages_7d": round(float(used_pages_7d), 3),
                    "requested_pages": selected_page_count,
                }
            ), 403
        selected = []
        for page in pages:
            try:
                page_no = int(page.get("page_number") or 0)
            except Exception:
                page_no = 0
            if start_page <= page_no <= end_page:
                selected.append(str(page.get("text") or "").strip())
        text_to_read = "\n\n".join([chunk for chunk in selected if chunk])
        filename_suffix = f"p{start_page}-{end_page}"
    else:
        text_to_read = str(document.get("content_text") or "").strip()
        filename_suffix = "full"

    if not text_to_read:
        return jsonify({"error": "В выбранном диапазоне нет текста"}), 422
    normalized_text_key = hashlib.sha256(_normalize_utterance_text(text_to_read).encode("utf-8")).hexdigest()[:16]
    reader_audio_limit_error = enforce_reader_audio_pro_monthly_limit(
        user_id=user_id_int,
        requested_units=float(len(text_to_read)),
        now_ts_utc=now_utc,
        tz="Europe/Vienna",
    )
    if reader_audio_limit_error:
        return jsonify(reader_audio_limit_error), 429
    # Hard global ceiling across all users — protects the external TTS budget.
    reader_audio_global_error = enforce_reader_audio_global_monthly_limit(
        user_id=user_id_int,
        requested_units=float(len(text_to_read)),
        now_ts_utc=now_utc,
        tz="Europe/Vienna",
    )
    if reader_audio_global_error:
        logging.warning(
            "reader_audio: GLOBAL monthly limit hit user_id=%s used=%s limit=%s requested=%s",
            user_id_int, reader_audio_global_error.get("used"),
            reader_audio_global_error.get("limit"), reader_audio_global_error.get("requested"),
        )
        return jsonify(reader_audio_global_error), 429
    language_for_tts = _normalize_short_lang_code(
        requested_language or _detect_reader_language(text_to_read, fallback=target_lang),
        fallback=_normalize_short_lang_code(target_lang, fallback="de"),
    )
    safe_title = re.sub(r"[^A-Za-z0-9._-]+", "_", str(document.get("title") or "reader"))[:60]
    try:
        generation_start_ts_ms = _to_epoch_ms()
        google_voice = _TTS_VOICES.get(language_for_tts, _TTS_VOICES["de"])
        google_lang_code = _TTS_LANG_CODES.get(language_for_tts, "de-DE")
        provider_started_perf = time.perf_counter()
        mp3_bytes = _synthesize_mp3(
            text_to_read,
            language=google_lang_code,
            voice=google_voice,
            speed=_TTS_SPEED_DEFAULT,
        )
        provider_duration_ms = _elapsed_ms_since(provider_started_perf)
        _billing_log_event_safe(
            user_id=user_id_int,
            action_type="reader_audio_tts",
            provider="google_tts",
            units_type="chars",
            units_value=float(len(text_to_read)),
            source_lang=source_lang,
            target_lang=target_lang,
            idempotency_seed=f"reader_audio:{user_id_int}:{document_id}:{filename_suffix}:{len(text_to_read)}:{time.time_ns()}",
            status="estimated",
            metadata={
                "document_id": int(document_id),
                "language": language_for_tts,
                "voice": google_voice,
                "format": "mp3",
            },
        )
        if selected_page_count > 0:
            _billing_log_event_safe(
                user_id=user_id_int,
                action_type="reader_audio_tts_pages",
                provider="app_internal",
                units_type="pages",
                units_value=float(selected_page_count),
                source_lang=source_lang,
                target_lang=target_lang,
                idempotency_seed=f"reader_audio_pages:{user_id_int}:{document_id}:{filename_suffix}:{selected_page_count}:mp3:{time.time_ns()}",
                status="estimated",
                metadata={
                    "document_id": int(document_id),
                    "format": "mp3",
                    "page_count": int(selected_page_count),
                },
            )
        _log_flow_observation(
            "tts",
            "reader_audio_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            user_id=user_id_int,
            cache_key=normalized_text_key,
            cache_hit=False,
            cache_miss=True,
            db_lookup_duration_ms=db_lookup_duration_ms,
            generation_start_ts_ms=generation_start_ts_ms,
            external_tts_provider_duration_ms=provider_duration_ms,
            storage_upload_duration_ms=None,
            final_status="generated",
            provider="google_tts",
            document_id=int(document_id),
            selected_page_count=int(selected_page_count),
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=200,
        )
        return send_file(
            BytesIO(mp3_bytes),
            mimetype="audio/mpeg",
            as_attachment=True,
            download_name=f"{safe_title}_{filename_suffix}.mp3",
        )
    except Exception as google_exc:
        logging.warning("Reader audio Google TTS failed, fallback to offline: %s", google_exc)
        try:
            fallback_started_perf = time.perf_counter()
            wav_bytes = _synthesize_offline_audio_wav(text_to_read, language=language_for_tts)
            fallback_duration_ms = _elapsed_ms_since(fallback_started_perf)
            _billing_log_event_safe(
                user_id=user_id_int,
                action_type="reader_audio_tts_fallback",
                provider="offline_tts",
                units_type="chars",
                units_value=float(len(text_to_read)),
                source_lang=source_lang,
                target_lang=target_lang,
                idempotency_seed=f"reader_audio_fallback:{user_id_int}:{document_id}:{filename_suffix}:{len(text_to_read)}:{time.time_ns()}",
                status="final",
                metadata={
                    "document_id": int(document_id),
                    "language": language_for_tts,
                    "format": "wav",
                },
            )
            if selected_page_count > 0:
                _billing_log_event_safe(
                    user_id=user_id_int,
                    action_type="reader_audio_tts_pages",
                    provider="app_internal",
                    units_type="pages",
                    units_value=float(selected_page_count),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    idempotency_seed=f"reader_audio_pages:{user_id_int}:{document_id}:{filename_suffix}:{selected_page_count}:wav:{time.time_ns()}",
                    status="estimated",
                    metadata={
                        "document_id": int(document_id),
                        "format": "wav",
                        "page_count": int(selected_page_count),
                    },
                )
            _log_flow_observation(
                "tts",
                "reader_audio_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=user_id_int,
                cache_key=normalized_text_key,
                cache_hit=False,
                cache_miss=True,
                db_lookup_duration_ms=db_lookup_duration_ms,
                generation_start_ts_ms=None,
                external_tts_provider_duration_ms=None,
                storage_upload_duration_ms=None,
                final_status="generated",
                provider="offline_tts",
                fallback_duration_ms=fallback_duration_ms,
                document_id=int(document_id),
                selected_page_count=int(selected_page_count),
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=200,
            )
            return send_file(
                BytesIO(wav_bytes),
                mimetype="audio/wav",
                as_attachment=True,
                download_name=f"{safe_title}_{filename_suffix}.wav",
            )
        except Exception as offline_exc:
            _log_flow_observation(
                "tts",
                "reader_audio_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=user_id_int,
                cache_key=normalized_text_key,
                cache_hit=False,
                cache_miss=True,
                db_lookup_duration_ms=db_lookup_duration_ms,
                final_status="error",
                error_code="reader_audio_tts_unavailable",
                document_id=int(document_id),
                selected_page_count=int(selected_page_count),
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=500,
            )
            return jsonify(
                {
                    "error": (
                        f"TTS недоступен. Google: {google_exc}. "
                        f"Offline: {offline_exc}"
                    )
                }
            ), 500

def _build_reader_audio_page_ready_response(
    *,
    audio_url: str,
    mime: str,
    duration_ms: int,
    word_timings: list,
    voice_name: str,
    rate_float: float,
    cached: bool,
    deduped: bool = False,
) -> dict:
    payload = {
        "audio_url": str(audio_url or ""),
        "mime": str(mime or "audio/mpeg"),
        "duration_ms": int(duration_ms or 0),
        "word_timings": list(word_timings or []),
        "voice": voice_name,
        "rate": rate_float,
        "cached": bool(cached),
    }
    if deduped:
        payload["deduped"] = True
    return payload


def _normalize_reader_visible_page_text_full(raw_text: str) -> str:
    """Python mirror of the frontend `normalizeReaderVisiblePageText` (App.jsx): strip
    PUA/"tofu" glyphs and control chars, collapse TOC dot-leaders and ellipsis runs,
    then reflow paragraphs — EXACTLY the transform the reader applies to on-screen page
    text before it hits `getReaderDisplayPageText`.

    Why this must exist server-side: a single classic page the client asks to voice is
    sent as `normalizeReaderVisiblePageText(page)`. The public-library pre-gen job runs
    server-side off the RAW stored page text, so unless it applies the SAME full
    normalization its cache key (text_hash) never matches the on-demand request — which
    is exactly why pre-generated classics audio was never being hit and every play did a
    cold on-demand synth. Keep this byte-compatible with the JS version.
    JS regex order:
      .replace(/[\\uE000-\\uF8FF\\uFFFC\\uFFFD]+/g,' ')
      .replace(/[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F]+/g,' ')
      .replace(/(?:\\s*[.\\u00B7\\u2022\\u2219]\\s*){4,}\\s*([0-9]{1,4}|[IVXLCM]{1,7})\\b/g,' \\u00B7 $1\\n\\n')
      .replace(/(?:\\s*[.\\u00B7\\u2022\\u2219]\\s*){4,}/g,' \\u00B7 ')
      .replace(/\\u2026{2,}/g,' ')
      .split(/\\n\\n+/).map(p=>p.replace(/\\n/g,' ').replace(/ {2,}/g,' ').trim()).filter(Boolean).join('\\n\\n')
    """
    s = str(raw_text or "")
    # Strip PUA/tofu glyphs (U+E000..U+F8FF, U+FFFC, U+FFFD) and control chars
    # (U+0000..U+0008, U+000B, U+000C, U+000E..U+001F, U+007F) — normal strings so the
    # \uXXXX escapes are interpreted (raw strings would keep them literal).
    s = re.sub("[\ue000-\uf8ff\ufffc\ufffd]+", " ", s)
    s = re.sub("[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]+", " ", s)
    # TOC dot-leaders: 4+ of [. \u00B7 \u2022 \u2219] then a page number -> " \u00B7 N\n\n".
    dots = ".\u00b7\u2022\u2219"
    s = re.sub(r"(?:\s*[" + dots + r"]\s*){4,}\s*([0-9]{1,4}|[IVXLCM]{1,7})\b",
               " \u00b7 " + r"\1" + "\n\n", s)
    s = re.sub(r"(?:\s*[" + dots + r"]\s*){4,}", " \u00b7 ", s)
    s = re.sub("\u2026{2,}", " ", s)
    paras = re.split(r"\n\n+", s)
    paras = [re.sub(r" {2,}", " ", p.replace("\n", " ")).strip() for p in paras]
    return "\n\n".join(p for p in paras if p)


def _reader_audio_page_text_and_hash(raw_text: str) -> tuple[str, str]:
    """Normalize a raw reader page exactly like the frontend's readerVisibleText and
    derive its cache text_hash. Single source of truth so the audio endpoint and the
    public-library pre-gen job produce identical cache keys for the same page.
    JS: raw.split(/\\n\\n+/).map(p => p.replace(/\\n/g,' ').replace(/ {2,}/g,' ').trim()).filter(Boolean).join('\\n\\n')"""
    paras = re.split(r'\n\n+', str(raw_text or ""))
    paras = [re.sub(r'  +', ' ', p.replace('\n', ' ')).strip() for p in paras]
    page_text = '\n\n'.join(p for p in paras if p)
    text_hash = (hashlib.sha256(page_text.encode("utf-8")).hexdigest()[:24] + "-v6") if page_text else ""
    return page_text, text_hash


def _generate_and_cache_reader_audio_page(
    *,
    user_id_int: int,
    document_id_int: int,
    page_int: int,
    page_source: str,
    page_text: str,
    text_hash: str,
    voice_name: str,
    rate_float: float,
    google_lang_code: str,
    language_for_tts: str,
    source_lang: str,
    target_lang: str,
    document_title: str,
    budget_provider: str = "google_tts",
    billing_provider: str = "google_tts",
) -> dict:
    # Route reader-audio synthesis off the free google_tts bucket (which the
    # dictionary/SRS rely on): the public-library Standard voice bills its own free
    # Standard bucket; personal paid narration bills the paid bucket (revenue from the
    # per-book unlock covers it, so it is never blocked by the free tier).
    if voice_name == PUBLIC_LIBRARY_TTS_VOICE:
        if budget_provider == "google_tts":
            budget_provider = "google_tts_standard"
        if billing_provider == "google_tts":
            billing_provider = "google_tts_standard"
    else:
        if budget_provider == "google_tts":
            budget_provider = "google_tts_paid"
        if billing_provider == "google_tts":
            billing_provider = "google_tts_paid"
    logging.info(
        "[READER_AUDIO] SYNTHESIZING user=%s doc=%s page=%s source=%s voice=%s lang=%s text_preview=%r",
        user_id_int, document_id_int, page_int, page_source, voice_name, google_lang_code, page_text[:80],
    )
    result = synthesize_page_with_timings(
        page_text=page_text,
        lang_code=google_lang_code,
        voice_name=voice_name,
        speaking_rate=rate_float,
        budget_provider=budget_provider,
    )

    timing_sample = result["word_timings"][:5] if result.get("word_timings") else []
    logging.info(
        "[READER_AUDIO] SYNTHESIZED user=%s doc=%s page=%s words=%s duration_ms=%s sample=%s",
        user_id_int, document_id_int, page_int,
        len(result.get("word_timings") or []), result.get("duration_ms"), timing_sample,
    )

    safe_title = re.sub(r"[^A-Za-z0-9._-]+", "_", str(document_title or "reader"))[:40]
    r2_rate = str(rate_float).replace(".", "_")
    object_key = f"reader-audio-pages/{user_id_int}/{document_id_int}/p{page_int}/{voice_name}/{r2_rate}/{text_hash}.mp3"
    r2_put_bytes(
        object_key,
        result["audio_bytes"],
        content_type="audio/mpeg",
        cache_control="public, max-age=2592000",
    )
    audio_url = r2_public_url(object_key)

    save_reader_audio_page_cache(
        user_id=user_id_int,
        document_id=document_id_int,
        page_number=page_int,
        voice_name=voice_name,
        speaking_rate=rate_float,
        text_hash=text_hash,
        audio_url=audio_url,
        audio_mime="audio/mpeg",
        audio_bytes_len=len(result["audio_bytes"]),
        duration_ms=result["duration_ms"],
        word_timings=result["word_timings"],
    )

    _billing_log_event_safe(
        user_id=user_id_int,
        action_type="reader_audio_tts",
        provider=billing_provider,
        units_type="chars",
        units_value=float(len(page_text)),
        source_lang=source_lang,
        target_lang=target_lang,
        idempotency_seed=f"reader_audio_page:{user_id_int}:{document_id_int}:p{page_int}:{text_hash}:{time.time_ns()}",
        status="estimated",
        metadata={
            "document_id": document_id_int,
            "page": page_int,
            "page_source": page_source,
            "voice": voice_name,
            "rate": rate_float,
            "language": language_for_tts,
            "title": safe_title,
        },
    )

    return _build_reader_audio_page_ready_response(
        audio_url=audio_url,
        mime="audio/mpeg",
        duration_ms=result["duration_ms"],
        word_timings=result["word_timings"],
        voice_name=voice_name,
        rate_float=rate_float,
        cached=False,
    )


def _run_reader_audio_page_generation_job(
    *,
    job_key: str,
    user_id: int,
    document_id: int,
    page: int,
    page_source: str,
    page_text: str,
    text_hash: str,
    voice_name: str,
    rate: float,
    google_lang_code: str,
    language_for_tts: str,
    source_lang: str,
    target_lang: str,
) -> None:
    set_reader_audio_page_job_status(job_key, status="running", source="worker")
    cached = get_cached_reader_audio_page(
        document_id=int(document_id),
        page_number=int(page),
        voice_name=str(voice_name),
        speaking_rate=float(rate),
        text_hash=str(text_hash),
    )
    if cached:
        set_reader_audio_page_job_status(
            job_key,
            status="ready",
            audio_url=str(cached.get("audio_url") or ""),
            duration_ms=int(cached.get("duration_ms") or 0),
            source="cache",
        )
        return

    try:
        ready_payload = _generate_and_cache_reader_audio_page(
            user_id_int=int(user_id),
            document_id_int=int(document_id),
            page_int=int(page),
            page_source=str(page_source or "async"),
            page_text=str(page_text or ""),
            text_hash=str(text_hash or ""),
            voice_name=str(voice_name or ""),
            rate_float=float(rate),
            google_lang_code=str(google_lang_code or "de-DE"),
            language_for_tts=str(language_for_tts or "de"),
            source_lang=str(source_lang or ""),
            target_lang=str(target_lang or ""),
            document_title="reader",
        )
        set_reader_audio_page_job_status(
            job_key,
            status="ready",
            audio_url=str(ready_payload.get("audio_url") or ""),
            duration_ms=int(ready_payload.get("duration_ms") or 0),
            source="worker",
        )
    except GoogleTTSBudgetBlockedError as exc:
        set_reader_audio_page_job_status(
            job_key,
            status="failed",
            error=str(exc),
            source="worker",
        )
        raise
    except Exception as exc:
        set_reader_audio_page_job_status(
            job_key,
            status="failed",
            error=str(exc),
            source="worker",
        )
        raise


@app.route("/api/webapp/reader/audio/stars_invoice", methods=["POST"])
def reader_audio_stars_invoice():
    """Create a Telegram Stars invoice link to narrate a personal book in a voice
    tier. The Mini App opens it with WebApp.openInvoice → native in-app payment; the
    bot grants the unlock on successful_payment. No wallet, no external browser."""
    payload = request.get_json(silent=True) or {}
    init_data = str(payload.get("initData") or "").strip()
    if not init_data or not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401
    parsed = _parse_telegram_init_data(init_data)
    user_id = (parsed.get("user") or {}).get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    user_id_int = int(user_id)
    try:
        document_id_int = int(payload.get("document_id"))
    except (ValueError, TypeError):
        return jsonify({"error": "document_id обязателен"}), 400
    voice_tier = str(payload.get("voice_tier") or "").strip().lower() or AUDIO_DEFAULT_VOICE_TIER
    if voice_tier not in AUDIO_PRICE_PER_1M_MINOR:
        return jsonify({"error": "Неизвестный голос", "error_code": "unknown_voice_tier"}), 400
    # Partial narration: buy the first 25% / 50% or the whole (100%) book.
    coverage_pct = int(payload.get("coverage_pct") or 100)
    if coverage_pct not in AUDIO_COVERAGE_OPTIONS:
        coverage_pct = 100

    source_lang, target_lang, _profile = _get_user_language_pair(user_id_int)
    document, document_is_public = _resolve_reader_document_for_user(
        user_id=user_id_int, document_id=document_id_int,
        source_lang=source_lang, target_lang=target_lang, include_content=False,
    )
    if not document:
        return jsonify({"error": "Книга не найдена"}), 404
    if document_is_public:
        return jsonify({"ok": True, "already_unlocked": True, "free": True, "voice_tier": voice_tier})
    owned_cov = int(get_book_audio_unlock_coverage(user_id_int, document_id_int, voice_tier) or 0)
    if owned_cov >= coverage_pct:
        return jsonify({"ok": True, "already_unlocked": True, "voice_tier": voice_tier,
                        "coverage_pct": owned_cov})

    # Only charge for the *additional* coverage (upgrading 25%→100% costs the delta).
    chars = int(document.get("total_chars") or 0)
    price_minor = _book_audio_coverage_price_minor(chars, voice_tier, coverage_pct)
    owned_minor = _book_audio_coverage_price_minor(chars, voice_tier, owned_cov) if owned_cov > 0 else 0
    delta_minor = max(0, price_minor - owned_minor)
    stars = max(1, eur_minor_to_stars(delta_minor))
    tier_label = (_AUDIO_TIER_LABELS.get(voice_tier, {}) or {}).get("ru", "Голос")
    book_title = str(document.get("title") or "книга")[:48]
    if coverage_pct >= 100:
        scope_ru = "вся книга"
        scope_desc = "слушать эту книгу всю, без ограничений."
    else:
        scope_ru = f"{coverage_pct}% книги"
        scope_desc = f"озвучка первых {coverage_pct}% книги — попробуйте, прежде чем брать всю."
    link, detail = create_stars_invoice_link(
        title=f"Озвучка ({scope_ru}): {book_title}",
        description=f"{tier_label} · {scope_desc}",
        payload_obj={
            "purpose": "book_audio",
            "user_id": user_id_int,
            "document_id": document_id_int,
            "voice_tier": voice_tier,
            "coverage_pct": coverage_pct,
        },
        stars=stars,
    )
    if not link:
        return jsonify({"error": "Не удалось создать счёт. Попробуйте ещё раз.", "detail": detail}), 502
    return jsonify({"ok": True, "invoice_link": link, "stars": int(stars),
                    "voice_tier": voice_tier, "coverage_pct": coverage_pct})


@app.route("/api/webapp/billing/stars_invoice", methods=["POST"])
def billing_stars_invoice():
    """Create a native Telegram Stars invoice the Mini App opens with WebApp.openInvoice.
    Two products (Stripe is retired — everything is Stars now):
      • plan_code='pro' → monthly Stars SUBSCRIPTION; the bot grants Pro on successful_payment
        and on each auto-renewal.
      • plan_code='support_coffee' | 'support_cheesecake' → ONE-TIME "thank you" donation; the
        bot records the sponsor AND grants bonus Pro days (7 / 14) on successful_payment.
    No external browser, no multi-window."""
    payload = request.get_json(silent=True) or {}
    init_data = str(payload.get("initData") or "").strip()
    if not init_data or not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401
    parsed = _parse_telegram_init_data(init_data)
    user_id = (parsed.get("user") or {}).get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    user_id_int = int(user_id)
    plan_code = str(payload.get("plan_code") or "pro").strip().lower() or "pro"

    if plan_code == "pro":
        stars = pro_price_stars()
        # Keep the Stars invoice `payload` tiny — Telegram caps it at 128 bytes and the bot
        # only needs the purpose + who paid (the tier for donations lives in `purpose`).
        link, detail = create_stars_invoice_link(
            title="Полный доступ — подписка",
            description="Полный доступ: больше заданий, YouTube-субтитры, переводы и разборы. Продление раз в месяц, отмена в любой момент.",
            payload_obj={"purpose": "pro", "user_id": user_id_int},
            stars=stars,
            subscription_period=STARS_SUBSCRIPTION_PERIOD_SECONDS,
        )
    elif plan_code in SUPPORT_TIER_EUR_MINOR:
        stars = support_price_stars(plan_code)
        _title = "Кофе разработчику ☕️" if plan_code == "support_coffee" else "Кофе ☕️ и чизкейк 🍰"
        _pro_days = 7 if plan_code == "support_coffee" else 14
        _desc = (f"Разовое спасибо — в подарок {_pro_days} дней полного доступа, бейдж спонсора "
                 "и место на стене благодарностей. И это помогает оплачивать серверы.")
        link, detail = create_stars_invoice_link(
            title=_title,
            description=_desc,
            payload_obj={"purpose": plan_code, "user_id": user_id_int},
            stars=stars,
        )
    else:
        return jsonify({"error": "Неизвестный тариф", "error_code": "unsupported_plan"}), 400

    if not link:
        return jsonify({"error": "Не удалось создать счёт. Попробуйте ещё раз.", "detail": detail}), 502
    return jsonify({"ok": True, "invoice_link": link, "stars": int(stars), "plan_code": plan_code})


@app.route("/api/webapp/reader/audio/unlock", methods=["POST"])
def reader_audio_unlock():
    """Pay once (from the audio wallet) to narrate a personal book in a voice tier →
    listen forever, unlimited. Lightweight: a wallet debit + a record row, no TTS
    here (synthesis stays lazy/per-page/cached). Returns 402 with the price when the
    balance is short so the client can prompt a top-up."""
    payload = request.get_json(silent=True) or {}
    init_data = str(payload.get("initData") or "").strip()
    if not init_data:
        init_data = request.headers.get("Authorization", "").removeprefix("Bearer ").strip()
    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401
    parsed = _parse_telegram_init_data(init_data)
    user_id = (parsed.get("user") or {}).get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    user_id_int = int(user_id)

    try:
        document_id_int = int(payload.get("document_id"))
    except (ValueError, TypeError):
        return jsonify({"error": "document_id обязателен"}), 400
    voice_tier = str(payload.get("voice_tier") or "").strip().lower() or AUDIO_DEFAULT_VOICE_TIER
    if voice_tier not in AUDIO_PRICE_PER_1M_MINOR:
        return jsonify({"error": "Неизвестный голос", "error_code": "unknown_voice_tier"}), 400

    source_lang, target_lang, _profile = _get_user_language_pair(user_id_int)
    document, document_is_public = _resolve_reader_document_for_user(
        user_id=user_id_int, document_id=document_id_int,
        source_lang=source_lang, target_lang=target_lang, include_content=False,
    )
    if not document:
        return jsonify({"error": "Книга не найдена"}), 404
    if document_is_public:
        # Classics are already free — nothing to buy.
        return jsonify({"ok": True, "already_unlocked": True, "free": True, "voice_tier": voice_tier})

    chars = int(document.get("total_chars") or 0)
    price_minor = estimate_book_audio_price_minor(chars, voice_tier)
    result = unlock_book_audio(
        user_id=user_id_int, document_id=document_id_int,
        voice_tier=voice_tier, price_minor=price_minor, chars=chars,
    )
    if not result.get("ok") and result.get("insufficient"):
        return jsonify({
            "error": "Недостаточно средств на балансе.",
            "error_code": "insufficient_balance",
            "voice_tier": voice_tier,
            "price_minor": int(price_minor),
            "balance_minor": int(result.get("balance_minor") or 0),
            "shortfall_minor": int(result.get("shortfall_minor") or 0),
            "currency": "EUR",
        }), 402
    return jsonify({
        "ok": True,
        "voice_tier": voice_tier,
        "already_unlocked": bool(result.get("already_unlocked")),
        "charged_minor": int(result.get("charged_minor") or 0),
        "price_minor": int(price_minor),
        "balance_minor": int(result.get("balance_minor") or 0),
        "currency": "EUR",
    })


@app.route("/api/webapp/reader/audio/samples", methods=["POST"])
def reader_audio_samples():
    """Short voice-preview clips (same passage in each paid tier) so the user can
    listen BEFORE paying. Generated once per voice + cached in R2; cheap to call."""
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    if not init_data or not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401
    samples = {}
    for tier in AUDIO_OFFERED_VOICE_TIERS:
        url = _get_or_create_voice_sample_url(tier)
        if url:
            samples[tier] = url
    return jsonify({"ok": True, "samples": samples, "sample_text": _READER_VOICE_SAMPLE_TEXT})


@app.route("/api/webapp/reader/audio/page", methods=["GET", "POST"])
def reader_audio_page():
    """
    GET/POST /api/webapp/reader/audio/page
    Returns JSON: {audio_url, mime, duration_ms, word_timings, voice, rate, cached}
    """
    payload = request.get_json(silent=True) or {}
    init_data = request.headers.get("Authorization", "").removeprefix("Bearer ").strip()
    if not init_data:
        init_data = str(payload.get("initData") or "").strip()
    if not init_data:
        init_data = request.args.get("initData", "").strip()
    document_id_raw = payload.get("document_id")
    if document_id_raw in (None, ""):
        document_id_raw = request.args.get("document_id", "")
    page_raw = payload.get("page")
    if page_raw in (None, ""):
        page_raw = request.args.get("page", "1")
    voice_raw = str(payload.get("voice") or "").strip()
    if not voice_raw:
        voice_raw = request.args.get("voice", "").strip()
    rate_raw = payload.get("rate")
    if rate_raw in (None, ""):
        rate_raw = request.args.get("rate", "1.0")
    page_text_override_raw = str(payload.get("page_text") or "").strip()
    # Language the client detected over the WHOLE document at open time. Preferred
    # over re-detecting from this request's (possibly tiny) page_text — see below.
    language_raw = str(payload.get("language") or "").strip()
    prefetch_only_raw = payload.get("prefetch_only")
    if prefetch_only_raw in (None, ""):
        prefetch_only_raw = request.args.get("prefetch_only", "")
    prefetch_only = str(prefetch_only_raw or "").strip().lower() in {"1", "true", "yes", "on"}

    if not init_data:
        return jsonify({"error": "Authorization обязателен"}), 400
    if not document_id_raw:
        return jsonify({"error": "document_id обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    user_id_int = int(user_id)

    try:
        document_id_int = int(document_id_raw)
        page_int = max(1, int(page_raw))
    except (ValueError, TypeError):
        return jsonify({"error": "document_id и page должны быть числами"}), 400

    try:
        rate_float = float(rate_raw)
        rate_float = max(0.5, min(2.0, rate_float))
        rate_float = round(rate_float * 4) / 4  # snap to 0.25 steps
    except (ValueError, TypeError):
        rate_float = 1.0

    now_utc = datetime.now(timezone.utc)
    source_lang, target_lang, _profile = _get_user_language_pair(user_id_int)

    document, document_is_public = _resolve_reader_document_for_user(
        user_id=user_id_int,
        document_id=document_id_int,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    if not document:
        return jsonify({"error": "Книга не найдена"}), 404

    # Public-domain "Классика" audio is free for everyone (shared, pre-generated from
    # the free Standard bucket). Personal-book audio is paid per-book: the user must
    # have unlocked THIS book in the requested voice tier (one-time wallet charge) —
    # then it plays forever, unlimited. No subscription tier includes narration.
    voice_tier = str(payload.get("voice_tier") or "").strip().lower() or AUDIO_DEFAULT_VOICE_TIER
    # Partial narration: an unlock may cover only the first N% of the book — the gate
    # allows pages within that fraction and blocks the rest (offering the upgrade).
    _doc_pages = document.get("content_pages") if isinstance(document.get("content_pages"), list) else []
    total_pages_for_gate = len(_doc_pages) or int(document.get("total_pages") or 0)
    if not document_is_public and not is_book_audio_unlocked(
        user_id_int, document_id_int, voice_tier,
        page_number=page_int, total_pages=total_pages_for_gate,
    ):
        owned_cov = int(get_book_audio_unlock_coverage(user_id_int, document_id_int, voice_tier) or 0)
        chars = int(document.get("total_chars") or 0)
        price_minor = _book_audio_coverage_price_minor(chars, voice_tier, 100)
        balance_minor = get_audio_wallet_balance_minor(user_id_int)
        return jsonify({
            "error": "Озвучка этой части книги ещё не оплачена." if owned_cov > 0
                     else "Озвучка этой книги ещё не оплачена.",
            "error_code": "audio_unlock_required",
            "unlock": {
                "document_id": document_id_int,
                "voice_tier": voice_tier,
                "owned_coverage_pct": owned_cov,
                "price_minor": int(price_minor),
                "currency": "EUR",
                "balance_minor": int(balance_minor),
                "sufficient": bool(balance_minor >= price_minor),
            },
        }), 402

    pages = document.get("content_pages") if isinstance(document.get("content_pages"), list) else []
    raw_text = page_text_override_raw
    page_source = "override" if raw_text else "document_page"
    if not raw_text:
        if not pages or page_int > len(pages):
            return jsonify({"error": "page_not_found", "page": page_int, "page_count": len(pages)}), 404

        page_obj = next((p for p in pages if int(p.get("page_number") or 0) == page_int), None)
        if page_obj is None:
            page_obj = pages[page_int - 1] if page_int <= len(pages) else None
        if not page_obj:
            return jsonify({"error": "page_not_found", "page": page_int, "page_count": len(pages)}), 404

        raw_text = str(page_obj.get("text") or "").strip()
    if not raw_text:
        return jsonify({"error": "Страница пустая"}), 422

    # Normalize exactly like the frontend does for readerVisibleText so that
    # char_start values in word_timings align with token.start on the frontend.
    page_text, page_text_hash = _reader_audio_page_text_and_hash(raw_text)

    if not page_text:
        return jsonify({"error": "Страница пустая"}), 422

    # Prefer the client-detected document language (`language`) over re-detecting
    # from this request's page_text. A short audio window — e.g. a dense
    # index/glossary page full of names, numbers and abbreviations — carries too
    # little signal for the stopword detector and can flip a German book to an
    # English voice. The whole-document detection done at open time is reliable,
    # so use it when supplied; per-page detection is only the fallback.
    requested_language = _normalize_short_lang_code(language_raw, fallback="") if language_raw else ""
    if requested_language:
        language_for_tts = requested_language
    else:
        language_for_tts = _normalize_short_lang_code(
            _detect_reader_language(page_text, fallback=target_lang),
            fallback=_normalize_short_lang_code(target_lang, fallback="de"),
        )
    google_lang_code = _TTS_LANG_CODES.get(language_for_tts, "de-DE")
    default_voice = _TTS_VOICES.get(language_for_tts, _TTS_VOICES["de"])
    if document_is_public:
        # Pin voice + rate so the shared cache key is identical for every reader and
        # matches what the nightly pre-gen job writes. Client voice/rate ignored.
        language_for_tts = _normalize_short_lang_code(target_lang, fallback="de")
        google_lang_code = _TTS_LANG_CODES.get(language_for_tts, "de-DE")
        voice_name = PUBLIC_LIBRARY_TTS_VOICE
        rate_float = PUBLIC_LIBRARY_TTS_RATE
    else:
        # Personal paid book — voice is fixed by the unlocked tier (keeps the cache
        # key consistent with what the user paid for).
        voice_name = _voice_tier_to_voice(voice_tier, language_for_tts)

    # v6: frontend may send the visible reader page text directly so tapped-word
    # audio always aligns with the page the user currently sees.
    text_hash = page_text_hash

    logging.info(
        "[READER_AUDIO] user=%s doc=%s page=%s source=%s voice=%s rate=%s raw_len=%s norm_len=%s hash=%s",
        user_id_int, document_id_int, page_int, page_source, voice_name, rate_float, len(raw_text), len(page_text), text_hash,
    )

    cached = get_cached_reader_audio_page(
        document_id=document_id_int,
        page_number=page_int,
        voice_name=voice_name,
        speaking_rate=rate_float,
        text_hash=text_hash,
    )
    if cached:
        timing_sample = cached["word_timings"][:3] if cached.get("word_timings") else []
        has_char_start = bool(cached.get("word_timings") and cached["word_timings"][0].get("char_start") is not None)
        logging.info(
            "[READER_AUDIO] CACHE HIT user=%s doc=%s page=%s words=%s has_char_start=%s sample=%s",
            user_id_int, document_id_int, page_int,
            len(cached.get("word_timings") or []), has_char_start, timing_sample,
        )
        return jsonify(_build_reader_audio_page_ready_response(
            audio_url=cached["audio_url"],
            mime=cached["mime"],
            duration_ms=cached["duration_ms"],
            word_timings=cached["word_timings"],
            voice_name=voice_name,
            rate_float=rate_float,
            cached=True,
        ))

    reader_audio_singleflight_key = (
        f"{document_id_int}:{page_int}:{voice_name}:{rate_float}:{text_hash}"
    )
    if prefetch_only and is_reader_audio_page_async_enabled() and can_enqueue_background_jobs():
        job_status = get_reader_audio_page_job_status(reader_audio_singleflight_key) or {}
        normalized_job_status = str(job_status.get("status") or "").strip().lower()
        if normalized_job_status in {"pending", "running"}:
            return jsonify({
                "status": "pending",
                "job_key": reader_audio_singleflight_key,
                "retry_after_ms": int(_READER_AUDIO_PAGE_PENDING_RETRY_MS),
            }), 202
        if normalized_job_status == "failed":
            return jsonify({
                "status": "failed",
                "job_key": reader_audio_singleflight_key,
                "error": str(job_status.get("error") or "reader_audio_page_generation_failed"),
            }), 200

        # No per-user monthly char cap here: personal audio is paid per-book (unlock
        # gate above) → unlimited replays; public audio is free. Provider budget is
        # still enforced inside synthesis (paid/standard buckets).
        enqueue_result = enqueue_reader_audio_page_job(
            {
                "job_key": reader_audio_singleflight_key,
                # Public «Классика» → shared owner (0), same as the inline synth + pre-gen.
                "user_id": int(PUBLIC_LIBRARY_OWNER_ID) if document_is_public else user_id_int,
                "document_id": document_id_int,
                "page": page_int,
                "page_source": page_source,
                "page_text": page_text,
                "text_hash": text_hash,
                "voice_name": voice_name,
                "rate": rate_float,
                "google_lang_code": google_lang_code,
                "language_for_tts": language_for_tts,
                "source_lang": source_lang,
                "target_lang": target_lang,
            }
        )
        enqueue_reason = str(enqueue_result.get("reason") or "").strip().lower()
        if bool(enqueue_result.get("queued")) or enqueue_reason in {"already_pending", "duplicate_in_flight"}:
            return jsonify({
                "status": "pending",
                "job_key": reader_audio_singleflight_key,
                "retry_after_ms": int(_READER_AUDIO_PAGE_PENDING_RETRY_MS),
            }), 202
        if prefetch_only:
            return jsonify({
                "status": "skipped",
                "job_key": reader_audio_singleflight_key,
                "reason": enqueue_reason or "async_unavailable",
            }), 202
        logging.warning(
            "[READER_AUDIO] ASYNC_FALLBACK_SYNC user=%s doc=%s page=%s reason=%s",
            user_id_int,
            document_id_int,
            page_int,
            enqueue_reason or "unknown",
        )

    owns_singleflight_slot, singleflight_event = acquire_reader_audio_singleflight_slot(
        reader_audio_singleflight_key
    )
    if not owns_singleflight_slot and singleflight_event is not None:
        logging.info(
            "[READER_AUDIO] WAITING_FOR_INFLIGHT user=%s doc=%s page=%s wait_sec=%s",
            user_id_int,
            document_id_int,
            page_int,
            _READER_AUDIO_SINGLEFLIGHT_WAIT_SEC,
        )
        singleflight_event.wait(timeout=_READER_AUDIO_SINGLEFLIGHT_WAIT_SEC)
        cached = get_cached_reader_audio_page(
            document_id=document_id_int,
            page_number=page_int,
            voice_name=voice_name,
            speaking_rate=rate_float,
            text_hash=text_hash,
        )
        if cached:
            logging.info(
                "[READER_AUDIO] DEDUPED_CACHE_HIT user=%s doc=%s page=%s",
                user_id_int,
                document_id_int,
                page_int,
            )
            return jsonify(_build_reader_audio_page_ready_response(
                audio_url=cached["audio_url"],
                mime=cached["mime"],
                duration_ms=cached["duration_ms"],
                word_timings=cached["word_timings"],
                voice_name=voice_name,
                rate_float=rate_float,
                cached=True,
                deduped=True,
            ))
        logging.warning(
            "[READER_AUDIO] INFLIGHT_WAIT_FALLBACK user=%s doc=%s page=%s",
            user_id_int,
            document_id_int,
            page_int,
        )
        if prefetch_only:
            return jsonify({
                "status": "pending",
                "job_key": reader_audio_singleflight_key,
                "retry_after_ms": int(_READER_AUDIO_PAGE_PENDING_RETRY_MS),
            }), 202

    # (No per-user char cap — personal audio is paid per-book, public is free.)
    try:
        try:
            # Public «Классика» audio is SHARED: key its R2 object + cache row under
            # PUBLIC_LIBRARY_OWNER_ID (0), never the requesting user. Otherwise an
            # on-demand synth writes reader-audio-pages/<uid>/... — not shared, missed
            # by the pre-gen (which uses 0), and reaped by the per-user churn cleanup,
            # leaving the shared cache row pointing at a deleted object (404 → silence).
            cache_owner_id = int(PUBLIC_LIBRARY_OWNER_ID) if document_is_public else user_id_int
            ready_payload = _generate_and_cache_reader_audio_page(
                user_id_int=cache_owner_id,
                document_id_int=document_id_int,
                page_int=page_int,
                page_source=page_source,
                page_text=page_text,
                text_hash=text_hash,
                voice_name=voice_name,
                rate_float=rate_float,
                google_lang_code=google_lang_code,
                language_for_tts=language_for_tts,
                source_lang=source_lang,
                target_lang=target_lang,
                document_title=str(document.get("title") or "reader"),
            )
        except GoogleTTSBudgetBlockedError as exc:
            # str(exc) is an internal budget reason ("google_tts_standard over 4000000
            # chars…") — never a sentence for a person. The frontend shows the honest
            # «Озвучка временно на паузе» plaque off error_code; keep the raw reason in
            # the log where it belongs.
            logging.warning("[READER_AUDIO] TTS budget blocked user=%s doc=%s page=%s: %s",
                            user_id_int, document_id_int, page_int, exc)
            return jsonify({
                "error": "reader_audio_budget_global",
                "error_code": "google_tts_budget_blocked",
                "message": "Озвучка книг сейчас на паузе. Чтение, перевод по тапу и словарь работают как обычно.",
            }), 429
        except Exception as exc:
            logging.exception("[READER_AUDIO] SYNTHESIS ERROR user=%s doc=%s page=%s: %s", user_id_int, document_id_int, page_int, exc)
            return jsonify({"error": f"Ошибка синтеза: {exc}"}), 500
        return jsonify(ready_payload)
    finally:
        if owns_singleflight_slot:
            release_reader_audio_singleflight_slot(
                reader_audio_singleflight_key,
                singleflight_event,
            )


@app.route("/api/webapp/normalize/de", methods=["POST"])
@app.route("/api/webapp/normalize/<lang_code>", methods=["POST"])
def normalize_lookup_text(lang_code: str = "de"):
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    text = (payload.get("text") or "").strip()

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not text:
        return jsonify({"error": "text обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    try:
        normalized = _normalize_lookup_text(text, lang_code)
    except Exception as exc:
        return jsonify({"error": f"Не удалось нормализовать текст: {exc}"}), 500

    return jsonify({"ok": True, "normalized": normalized})


@app.route("/api/webapp/sentences", methods=["POST"])
def get_webapp_sentences():
    started_perf = time.perf_counter()
    payload = request.get_json(silent=True) or {}
    request_id = _extract_observability_request_id(payload)
    correlation_id = _build_observability_correlation_id(payload=payload, prefix="webapp_sentences")
    init_data = payload.get("initData")
    requested_limit = payload.get("limit", 7)
    try:
        limit = int(requested_limit)
    except Exception:
        limit = 7
    limit = max(1, min(limit, 7))

    if not init_data:
        _log_flow_observation(
            "webapp_translation",
            "sentences_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            requested_limit=limit,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        _log_flow_observation(
            "webapp_translation",
            "sentences_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            requested_limit=limit,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=401,
        )
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    username = _extract_display_name(user_data)
    requested_session_id = _extract_webapp_session_id(payload)

    if not user_id:
        _log_flow_observation(
            "webapp_translation",
            "sentences_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            requested_limit=limit,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    fast_path_generation_status_payload: dict[str, Any] | None = None
    fast_path_source_lang: str | None = None
    fast_path_target_lang: str | None = None
    if requested_session_id and is_translation_sentence_fill_async_enabled():
        try:
            fast_path_generation_status_payload = get_translation_fill_job_status(int(requested_session_id))
        except Exception:
            fast_path_generation_status_payload = None
        if is_translation_fill_job_status_fast_path_eligible(fast_path_generation_status_payload):
            hint_pair = _extract_webapp_language_pair_hint(payload)
            if hint_pair:
                fast_path_source_lang, fast_path_target_lang = _normalize_language_profile_for_mode(
                    native_language=hint_pair[0],
                    learning_language=hint_pair[1],
                )
            else:
                fast_path_source_lang, fast_path_target_lang = "ru", "de"
            response_payload = _build_translation_fill_pending_payload(
                source_lang=fast_path_source_lang,
                target_lang=fast_path_target_lang,
                generation_status_payload=fast_path_generation_status_payload,
                expected_total=7,
                base_payload={"ok": True},
            )
            source_session_id = str(requested_session_id or "").strip()
            _log_flow_observation(
                "webapp_translation",
                "sentences_completed",
                request_id=request_id,
                correlation_id=correlation_id,
                user_id=int(user_id),
                source_session_id=source_session_id or None,
                requested_session_id=requested_session_id or None,
                session_lookup_mode="redis_fill_cache",
                requested_limit=limit,
                ready_count=0,
                expected_total=7,
                generation_in_progress=True,
                generation_status=str(response_payload.get("generation_status") or "pending"),
                language_pair_lookup_duration_ms=0,
                language_pair_lookup_mode="request_hint" if hint_pair else "default_fast_path",
                sentence_lookup_duration_ms=0,
                dedupe_duration_ms=0,
                delivered_mark_duration_ms=0,
                access_guard_cache_source=getattr(g, "webapp_access_guard_cache_source", None),
                instance_guard_cache_source=getattr(g, "webapp_instance_guard_cache_source", None),
                response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
                final_status="success",
                duration_ms=_elapsed_ms_since(started_perf),
                http_status=200,
            )
            return jsonify(response_payload)

    with db_acquire_scope("webapp_sentences") as db_acquire_events:
        language_pair_started_perf = time.perf_counter()
        source_lang, target_lang, _profile, language_pair_lookup_mode = _get_user_language_pair_for_webapp_request(
            int(user_id),
            payload=payload,
        )
        language_pair_duration_ms = _elapsed_ms_since(language_pair_started_perf)
        sentence_lookup_started_perf = time.perf_counter()
        session_lookup_mode = "header_session" if requested_session_id else "active_discovery_fallback"
        sentences = get_pending_daily_sentences(
            user_id=user_id,
            limit=limit,
            source_lang=source_lang,
            target_lang=target_lang,
            close_stale_sessions=False,
            session_id=requested_session_id,
        )
        sentence_lookup_duration_ms = _elapsed_ms_since(sentence_lookup_started_perf)
    dedupe_started_perf = time.perf_counter()
    deduped = _dedupe_sentences(sentences)
    dedupe_duration_ms = _elapsed_ms_since(dedupe_started_perf)
    delivered_mark_duration_ms = 0
    if deduped:
        delivered_mark_started_perf = time.perf_counter()
        _mark_translation_sentences_delivered(
            user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            items=deduped,
        )
        delivered_mark_duration_ms = _elapsed_ms_since(delivered_mark_started_perf)
    generation_status_payload: dict[str, Any] | None = None
    if requested_session_id and is_translation_sentence_fill_async_enabled():
        try:
            generation_status_payload = get_translation_fill_job_status(int(requested_session_id))
        except Exception:
            generation_status_payload = None
    ready_count = len(deduped)
    expected_total = 7
    if requested_session_id and ready_count < expected_total:
        generation_status_payload = _maybe_restart_translation_session_fill(
            user_id=int(user_id),
            username=username,
            session_id=int(requested_session_id),
            source_lang=source_lang,
            target_lang=target_lang,
            ready_count=ready_count,
            expected_total=expected_total,
            generation_status_payload=generation_status_payload,
        )
    raw_generation_status = str((generation_status_payload or {}).get("status") or "").strip().lower()
    if ready_count >= expected_total:
        generation_status = "ready"
    elif raw_generation_status in {"pending", "running"}:
        generation_status = raw_generation_status
    elif raw_generation_status == "failed":
        generation_status = "failed"
    elif requested_session_id and ready_count < expected_total and not is_translation_sentence_fill_async_enabled():
        generation_status = "failed"
    else:
        generation_status = "idle"
    generation_in_progress = generation_status in {"pending", "running"} and ready_count < expected_total
    response_payload = {
        "ok": True,
        "items": deduped,
        "ready_count": ready_count,
        "expected_total": expected_total,
        "generation_in_progress": generation_in_progress,
        "generation_status": generation_status,
        "generation_error": (
            str((generation_status_payload or {}).get("error") or "").strip()
            or (
                "translation_sentence_fill_async_disabled"
                if requested_session_id and ready_count < expected_total and not is_translation_sentence_fill_async_enabled()
                else None
            )
        ),
        "language_pair": _build_language_pair_payload(source_lang, target_lang),
    }
    source_session_id = str(deduped[0].get("source_session_id") or "").strip() if deduped else requested_session_id
    _log_flow_observation(
        "webapp_translation",
        "sentences_completed",
        request_id=request_id,
        correlation_id=correlation_id,
        user_id=int(user_id),
        source_session_id=source_session_id or None,
        requested_session_id=requested_session_id or None,
        session_lookup_mode=session_lookup_mode,
        requested_limit=limit,
        ready_count=ready_count,
        expected_total=expected_total,
        generation_in_progress=generation_in_progress,
        generation_status=generation_status,
        language_pair_lookup_duration_ms=language_pair_duration_ms,
        language_pair_lookup_mode=language_pair_lookup_mode,
        sentence_lookup_duration_ms=sentence_lookup_duration_ms,
        dedupe_duration_ms=dedupe_duration_ms,
        delivered_mark_duration_ms=delivered_mark_duration_ms,
        access_guard_cache_source=getattr(g, "webapp_access_guard_cache_source", None),
        instance_guard_cache_source=getattr(g, "webapp_instance_guard_cache_source", None),
        response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
        final_status="success",
        duration_ms=_elapsed_ms_since(started_perf),
        http_status=200,
        **summarize_db_acquire_events(db_acquire_events),
    )
    return jsonify(response_payload)


@app.route("/api/webapp/sentences/ack", methods=["POST"])
def ack_webapp_sentences_shown():
    started_perf = time.perf_counter()
    payload = request.get_json(silent=True) or {}
    request_id = _extract_observability_request_id(payload)
    correlation_id = _build_observability_correlation_id(payload=payload, prefix="webapp_sentences_ack")
    init_data = payload.get("initData")
    source_session_id = str(payload.get("source_session_id") or "").strip()
    sentence_ids_payload = payload.get("sentence_ids")

    if not init_data:
        _log_flow_observation(
            "webapp_translation",
            "sentences_ack_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "initData обязателен"}), 400
    if not source_session_id:
        _log_flow_observation(
            "webapp_translation",
            "sentences_ack_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "source_session_id обязателен"}), 400
    if not isinstance(sentence_ids_payload, list):
        _log_flow_observation(
            "webapp_translation",
            "sentences_ack_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            source_session_id=source_session_id,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "sentence_ids должны быть списком"}), 400

    if not _telegram_hash_is_valid(init_data):
        _log_flow_observation(
            "webapp_translation",
            "sentences_ack_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            source_session_id=source_session_id,
            requested_sentence_count=len(sentence_ids_payload),
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=401,
        )
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        _log_flow_observation(
            "webapp_translation",
            "sentences_ack_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            source_session_id=source_session_id,
            requested_sentence_count=len(sentence_ids_payload),
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    source_lang, target_lang, _profile, language_pair_lookup_mode = _get_user_language_pair_for_webapp_request(
        int(user_id),
        payload=payload,
    )
    try:
        db_started_perf = time.perf_counter()
        result = mark_translation_sentences_shown(
            user_id=int(user_id),
            source_session_id=source_session_id,
            sentence_ids=sentence_ids_payload,
            source_lang=source_lang,
            target_lang=target_lang,
        )
        db_update_duration_ms = _elapsed_ms_since(db_started_perf)
    except Exception as exc:
        _log_flow_observation(
            "webapp_translation",
            "sentences_ack_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            user_id=int(user_id),
            source_session_id=source_session_id,
            requested_sentence_count=len(sentence_ids_payload),
            source_lang=source_lang,
            target_lang=target_lang,
            final_status="error",
            error_code=exc.__class__.__name__,
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=500,
        )
        return jsonify({"error": f"Ошибка подтверждения показа предложений: {exc}"}), 500

    response_payload = {
        "ok": True,
        **result,
        "session": {
            "session_id": str(result.get("session_id") or "").strip() or None,
            "status": str(result.get("status") or "").strip() or None,
            "total_sentences": int(result.get("total_sentences") or 0) if result.get("total_sentences") is not None else None,
            "translated_count": int(result.get("translated_count") or 0) if result.get("translated_count") is not None else None,
            "completed": str(result.get("status") or "").strip().lower() == "completed",
        },
        "home_refresh": {
            "refreshing": True,
            "manual_refresh_recommended": True,
        },
    }
    _log_flow_observation(
        "webapp_translation",
        "sentences_ack_completed",
        request_id=request_id,
        correlation_id=correlation_id,
        user_id=int(user_id),
        source_session_id=source_session_id,
        requested_sentence_count=len(sentence_ids_payload),
        updated_sentence_count=int(result.get("updated") or 0),
        source_lang=source_lang,
        target_lang=target_lang,
        language_pair_lookup_mode=language_pair_lookup_mode,
        db_update_duration_ms=db_update_duration_ms,
        response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
        final_status="success",
        duration_ms=_elapsed_ms_since(started_perf),
        http_status=200,
    )
    return jsonify(response_payload)


def _build_translation_session_start_payload(
    *,
    user_id: int,
    username: str | None,
    source_lang: str,
    target_lang: str,
    result: dict[str, Any],
    topic: str,
    level: str | None,
    grammar_focus: dict[str, Any] | None,
    tested_skill_profile_seed: dict[str, Any] | None = None,
) -> dict[str, Any]:
    session_id = int(result.get("session_id") or 0) if isinstance(result, dict) and result.get("session_id") else None
    expected_total = int(result.get("expected_total") or 7) if isinstance(result, dict) else 7
    preloaded_items = list((result or {}).get("items") or []) if isinstance(result, dict) else []
    preloaded_ready_count = int(result.get("ready_count") or len(preloaded_items) or 0) if isinstance(result, dict) else len(preloaded_items)
    normalized_preloaded_items = _dedupe_sentences([
        {
            "id_for_mistake_table": int(item.get("id_for_mistake_table") or 0),
            "sentence": str(item.get("sentence") or "").strip(),
            "unique_id": int(item.get("unique_id") or 0),
            "source_session_id": str(item.get("source_session_id") or session_id),
        }
        for item in preloaded_items
        if int(item.get("id_for_mistake_table") or 0) > 0
        and str(item.get("sentence") or "").strip()
    ])
    if (
        session_id is not None
        and is_translation_sentence_fill_async_enabled()
        and int(result.get("ready_count") or 0) <= 0
        and not bool(result.get("completion_required"))
    ):
        _start_translation_session_fill_runner(
            user_id=int(user_id),
            username=username,
            session_id=int(session_id),
            topic=topic,
            level=level,
            source_lang=source_lang,
            target_lang=target_lang,
            grammar_focus=grammar_focus,
            tested_skill_profile_seed=tested_skill_profile_seed,
        )
        generation_status_payload = get_translation_fill_job_status(int(session_id))
        return _build_translation_fill_pending_payload(
            source_lang=source_lang,
            target_lang=target_lang,
            generation_status_payload=generation_status_payload,
            expected_total=expected_total,
            base_payload={
                **(result or {}),
                "type": "regular",
            },
        )
    if session_id is not None and normalized_preloaded_items and len(normalized_preloaded_items) >= expected_total:
        return {
            **(result or {}),
            "type": "regular",
            "items": normalized_preloaded_items,
            "ready_count": len(normalized_preloaded_items),
            "expected_total": expected_total,
            "remaining_count": max(0, expected_total - len(normalized_preloaded_items)),
            "generation_in_progress": False,
            "generation_status": "ready",
            "generation_error": None,
        }
    if session_id is not None and normalized_preloaded_items:
        deduped_items = normalized_preloaded_items
    else:
        ready_items = get_pending_daily_sentences(
            user_id=user_id,
            limit=7,
            source_lang=source_lang,
            target_lang=target_lang,
            close_stale_sessions=False,
            session_id=session_id,
        )
        deduped_items = _dedupe_sentences(ready_items)
    if deduped_items and len(deduped_items) < expected_total:
        _mark_translation_sentences_delivered(
            user_id=int(user_id),
            source_lang=source_lang,
            target_lang=target_lang,
            items=deduped_items,
        )
    ready_count = len(deduped_items)
    remaining_count = max(0, expected_total - ready_count)
    generation_started = bool(session_id and remaining_count > 0 and not bool(result.get("completion_required")))
    generation_status_payload: dict[str, Any] | None = None
    if generation_started and session_id is not None:
        _start_translation_session_fill_runner(
            user_id=int(user_id),
            username=username,
            session_id=int(session_id),
            topic=topic,
            level=level,
            source_lang=source_lang,
            target_lang=target_lang,
            grammar_focus=grammar_focus,
            tested_skill_profile_seed=tested_skill_profile_seed,
        )
        if is_translation_sentence_fill_async_enabled():
            generation_status_payload = get_translation_fill_job_status(int(session_id))
    elif session_id is not None and is_translation_sentence_fill_async_enabled():
        generation_status_payload = get_translation_fill_job_status(int(session_id))

    raw_generation_status = str((generation_status_payload or {}).get("status") or "").strip().lower()
    if ready_count >= expected_total:
        generation_status = "ready"
    elif raw_generation_status in {"pending", "running"}:
        generation_status = raw_generation_status
    elif raw_generation_status == "failed":
        generation_status = "failed"
    elif generation_started and is_translation_sentence_fill_async_enabled():
        generation_status = "pending"
    elif generation_started:
        generation_status = "failed"
    else:
        generation_status = "idle"
    generation_in_progress = generation_status in {"pending", "running"} and ready_count < expected_total
    response_payload = {
        **(result or {}),
        "type": "regular",
        "items": deduped_items,
        "ready_count": ready_count,
        "expected_total": expected_total,
        "remaining_count": remaining_count,
        "generation_in_progress": generation_in_progress,
        "generation_status": generation_status,
        "generation_error": (
            str((generation_status_payload or {}).get("error") or "").strip()
            or (
                "translation_sentence_fill_async_disabled"
                if generation_started and not is_translation_sentence_fill_async_enabled()
                else None
            )
        ),
    }
    return response_payload


def _get_translation_session_fill_recovery_payload(
    *,
    user_id: int,
    session_id: int,
    source_lang: str,
    target_lang: str,
) -> dict[str, Any] | None:
    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    COALESCE(NULLIF(ds.focus_key, ''), ''),
                    COALESCE(NULLIF(ds.level, ''), ''),
                    COALESCE(up.username, ''),
                    COALESCE(up.completed, FALSE)
                FROM bt_3_daily_sentences ds
                LEFT JOIN bt_3_user_progress up
                  ON up.user_id = ds.user_id
                 AND up.session_id = ds.session_id
                WHERE ds.user_id = %s
                  AND ds.session_id = %s
                  AND COALESCE(ds.source_lang, 'ru') = %s
                  AND COALESCE(ds.target_lang, 'de') = %s
                ORDER BY ds.unique_id ASC, ds.id ASC
                LIMIT 1;
                """,
                (int(user_id), int(session_id), source_lang, target_lang),
            )
            row = cursor.fetchone()
    if not row:
        return None
    focus_key = str(row[0] or "").strip()
    level = str(row[1] or "").strip().lower() or None
    recovered_username = str(row[2] or "").strip() or None
    if bool(row[3]):
        return None
    grammar_focus = get_grammar_focus_by_key(focus_key) if focus_key else None
    topic = str((grammar_focus or {}).get("prompt_topic") or "Random sentences").strip() or "Random sentences"
    return {
        "username": recovered_username,
        "topic": topic,
        "level": level,
        "grammar_focus": grammar_focus,
    }


def _maybe_restart_translation_session_fill(
    *,
    user_id: int,
    username: str | None,
    session_id: int | None,
    source_lang: str,
    target_lang: str,
    ready_count: int,
    expected_total: int,
    generation_status_payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    safe_session_id = int(session_id or 0)
    if safe_session_id <= 0 or ready_count >= expected_total:
        return generation_status_payload
    current_status = str((generation_status_payload or {}).get("status") or "").strip().lower()
    if current_status in {"pending", "running", "ready"}:
        return generation_status_payload
    if current_status == "failed":
        return generation_status_payload
    recovery_payload = _get_translation_session_fill_recovery_payload(
        user_id=int(user_id),
        session_id=safe_session_id,
        source_lang=source_lang,
        target_lang=target_lang,
    )
    if not recovery_payload:
        return generation_status_payload
    try:
        _start_translation_session_fill_runner(
            user_id=int(user_id),
            username=username or recovery_payload.get("username"),
            session_id=safe_session_id,
            topic=str(recovery_payload.get("topic") or "Random sentences").strip() or "Random sentences",
            level=recovery_payload.get("level"),
            source_lang=source_lang,
            target_lang=target_lang,
            grammar_focus=recovery_payload.get("grammar_focus"),
            tested_skill_profile_seed=None,
        )
        if is_translation_sentence_fill_async_enabled():
            refreshed_payload = get_translation_fill_job_status(safe_session_id)
            if refreshed_payload:
                return refreshed_payload
    except Exception:
        logging.exception(
            "translation session fill recovery enqueue failed: user_id=%s session_id=%s",
            int(user_id),
            safe_session_id,
        )
    return generation_status_payload


def _run_translation_session_fill(
    *,
    user_id: int,
    username: str | None,
    session_id: int,
    topic: str,
    level: str | None,
    source_lang: str,
    target_lang: str,
    grammar_focus: dict[str, Any] | None,
    tested_skill_profile_seed: dict[str, Any] | None = None,
) -> dict[str, Any]:
    launched_at_ms = _pop_translation_session_fill_launched_at(int(session_id))
    if launched_at_ms:
        logging.info(
            "translation session background fill runner started: user_id=%s session_id=%s launch_delay_ms=%s",
            int(user_id),
            int(session_id),
            max(0, int(time.time() * 1000) - int(launched_at_ms)),
        )
    try:
        result = asyncio.run(
            fill_translation_session_webapp(
                user_id=int(user_id),
                username=username,
                session_id=int(session_id),
                topic=topic,
                level=level,
                source_lang=source_lang,
                target_lang=target_lang,
                tested_skill_profile_seed=tested_skill_profile_seed,
                grammar_focus=grammar_focus,
            )
        )
        if isinstance(result, dict):
            ready_count = int(result.get("ready_count") or 0)
            expected_total = int(result.get("expected_total") or 0)
            focus_kind = str(result.get("focus_kind") or "").strip().lower() or "legacy"
            focus_key = str(result.get("focus_key") or "").strip()
            focus_label = str(result.get("focus_label") or focus_key).strip() or focus_key
            if focus_key:
                _record_translation_readiness_fill_result(
                    source_lang=source_lang,
                    target_lang=target_lang,
                    focus_kind=focus_kind,
                    focus_key=focus_key,
                    focus_label=focus_label,
                    level=level,
                    fill_rounds=int(result.get("fill_rounds") or 0),
                    underfilled=bool(result.get("underfilled")),
                    failed=False,
                    time_to_first_ready_ms=(
                        int(result.get("time_to_first_ready_ms"))
                        if result.get("time_to_first_ready_ms") is not None
                        else None
                    ),
                )
            if expected_total > 0 and ready_count < expected_total:
                logging.warning(
                    "translation session background fill completed under target: user_id=%s session_id=%s ready_count=%s expected_total=%s diagnostics=%s",
                    int(user_id),
                    int(session_id),
                    ready_count,
                    expected_total,
                    result.get("round_diagnostics"),
                )
            else:
                logging.info(
                    "translation session background fill completed: user_id=%s session_id=%s ready_count=%s expected_total=%s",
                    int(user_id),
                    int(session_id),
                    ready_count,
                    expected_total,
                )
        return result if isinstance(result, dict) else {"ready_count": 0, "expected_total": 0}
    except Exception as exc:
        focus_kind, focus_key, focus_label = _resolve_translation_readiness_focus_identity(
            focus=grammar_focus,
            level=level,
        )
        if focus_key:
            try:
                _record_translation_readiness_fill_result(
                    source_lang=source_lang,
                    target_lang=target_lang,
                    focus_kind=focus_kind,
                    focus_key=focus_key,
                    focus_label=focus_label,
                    level=level,
                    fill_rounds=0,
                    underfilled=False,
                    failed=True,
                    time_to_first_ready_ms=None,
                )
            except Exception:
                logging.exception(
                    "Failed to record translation readiness fill failure: user_id=%s session_id=%s",
                    int(user_id),
                    int(session_id),
                )
        logging.error(
            "Translation session background fill failed: user_id=%s session_id=%s error=%s",
            user_id,
            session_id,
            exc,
            exc_info=True,
        )
        return {"error": str(exc), "ready_count": 0, "expected_total": 0}
    finally:
        with _TRANSLATION_SESSION_FILL_RUNNERS_LOCK:
            _TRANSLATION_SESSION_FILL_RUNNERS.discard(int(session_id))


def _start_translation_session_fill_runner(
    *,
    user_id: int,
    username: str | None,
    session_id: int,
    topic: str,
    level: str | None,
    source_lang: str,
    target_lang: str,
    grammar_focus: dict[str, Any] | None,
    tested_skill_profile_seed: dict[str, Any] | None = None,
) -> None:
    if is_translation_sentence_fill_async_enabled():
        current_status = str((get_translation_fill_job_status(int(session_id)) or {}).get("status") or "").strip().lower()
        if current_status not in {"pending", "running"}:
            _remember_translation_session_fill_launched_at(int(session_id), int(time.time() * 1000))
        enqueue_translation_fill_job(
            user_id=int(user_id),
            username=username,
            session_id=int(session_id),
            topic=topic,
            level=level,
            source_lang=source_lang,
            target_lang=target_lang,
            grammar_focus=grammar_focus,
            tested_skill_profile_seed=tested_skill_profile_seed,
        )
        return
    logging.error(
        "Translation session fill local fallback disabled in BACKEND_WEB: session_id=%s reason=translation_sentence_fill_async_disabled",
        int(session_id),
    )


@app.route("/api/webapp/topics", methods=["GET"])
def get_webapp_topics():
    return jsonify({"ok": True, "items": WEBAPP_TOPICS})


@app.route("/api/webapp/start", methods=["POST"])
def start_webapp_translation():
    started_at = time.perf_counter()
    payload = request.get_json(silent=True) or {}
    request_id = _extract_observability_request_id(payload)
    g.request_id = request_id
    correlation_id = _build_observability_correlation_id(payload=payload, prefix="webapp_start")
    g.correlation_id = correlation_id
    route_path = request.path or "/api/webapp/start"
    init_data = payload.get("initData")
    topic = (payload.get("topic") or "Random sentences").strip()
    custom_focus = str(payload.get("custom_focus") or "").strip()
    valid_translation_levels = {"a1", "a2", "b1", "b2", "c1", "c2"}
    level = str(payload.get("level") or "").strip().lower()

    def _log_start_route_observation(**fields: Any) -> None:
        _log_flow_observation(
            "webapp_translation",
            "start_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            route=route_path,
            **fields,
        )

    if not level:
        _log_start_route_observation(
            final_status="error",
            error_code="level_required",
            duration_ms=_elapsed_ms_since(started_at),
            http_status=400,
        )
        return jsonify({"error": "level обязателен"}), 400
    if level not in valid_translation_levels:
        _log_start_route_observation(
            final_status="error",
            error_code="invalid_level",
            duration_ms=_elapsed_ms_since(started_at),
            http_status=400,
        )
        return jsonify({"error": "Некорректный level"}), 400
    force_new_session = bool(payload.get("force_new_session"))
    auth_resolution_started_perf = time.perf_counter()

    if not init_data:
        _log_start_route_observation(
            final_status="error",
            duration_ms=_elapsed_ms_since(started_at),
            http_status=400,
        )
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        _log_start_route_observation(
            final_status="error",
            duration_ms=_elapsed_ms_since(started_at),
            http_status=401,
        )
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    username = _extract_display_name(user_data)

    if not user_id:
        _log_start_route_observation(
            final_status="error",
            duration_ms=_elapsed_ms_since(started_at),
            http_status=400,
        )
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    g.trace_auth_user_id = int(user_id)
    _log_compact_trace(
        "auth_start",
        stage="auth_resolved",
        request_id=request_id,
        path=request.path,
        method=request.method,
        user_id=int(user_id),
        auth_resolution_duration_ms=int((time.perf_counter() - auth_resolution_started_perf) * 1000),
        force_new_session=force_new_session,
    )

    start_idempotency_key = _webapp_start_idempotency_key(int(user_id))
    start_idempotency_token = _try_acquire_shared_idempotency(
        start_idempotency_key,
        ttl_sec=WEBAPP_START_IDEMPOTENCY_TTL_SEC,
    )
    if not start_idempotency_token:
        _log_start_route_observation(
            user_id=int(user_id),
            final_status="error",
            error_code="start_in_progress",
            duration_ms=_elapsed_ms_since(started_at),
            http_status=409,
        )
        return jsonify({"error": "Запуск сессии уже выполняется."}), 409

    _clear_recent_finish_no_active_session(int(user_id))
    try:
        with db_acquire_scope("webapp_start") as db_acquire_events:
            language_pair_started_perf = time.perf_counter()
            source_lang, target_lang, _profile, language_pair_lookup_mode = _get_user_language_pair_for_webapp_request(
                int(user_id),
                payload=payload,
            )
            language_pair_duration_ms = _elapsed_ms_since(language_pair_started_perf)
            focus_started_perf = time.perf_counter()
            resolved_focus = resolve_webapp_focus(topic, custom_focus)
            focus_duration_ms = _elapsed_ms_since(focus_started_perf)
            _log_compact_trace(
                "auth_start",
                stage="preflight_done",
                request_id=request_id,
                path=request.path,
                user_id=int(user_id),
                language_pair_lookup_duration_ms=language_pair_duration_ms,
                language_pair_lookup_mode=language_pair_lookup_mode,
                focus_duration_ms=focus_duration_ms,
                focus_kind=str(resolved_focus.get("kind") or "").strip() or None,
                focus_key=str(resolved_focus.get("key") or "").strip() or None,
            )
            if str(resolved_focus.get("kind") or "") == "custom" and not str(resolved_focus.get("custom_text") or "").strip():
                _log_start_route_observation(
                    user_id=int(user_id),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    focus_kind=str(resolved_focus.get("kind") or "").strip(),
                    focus_key=str(resolved_focus.get("key") or "").strip() or None,
                    language_pair_lookup_duration_ms=language_pair_duration_ms,
                    language_pair_lookup_mode=language_pair_lookup_mode,
                    focus_duration_ms=focus_duration_ms,
                    final_status="error",
                    duration_ms=_elapsed_ms_since(started_at),
                    http_status=400,
                    **summarize_db_acquire_events(db_acquire_events),
                )
                return jsonify({"error": "custom_focus обязателен для пользовательского грамматического фокуса"}), 400

            try:
                refresh_started_perf = time.perf_counter()
                _refresh_subscription_before_translation_start(int(user_id))
                _log_compact_trace(
                    "auth_start",
                    stage="refresh_done",
                    request_id=request_id,
                    path=request.path,
                    user_id=int(user_id),
                    refresh_duration_ms=int((time.perf_counter() - refresh_started_perf) * 1000),
                )
                workflow_started_at = time.perf_counter()
                result = asyncio.run(
                    start_translation_session_webapp(
                        user_id=user_id,
                        username=username,
                        topic=str(resolved_focus.get("prompt_topic") or topic or "Random sentences").strip(),
                        level=level,
                        source_lang=source_lang,
                        target_lang=target_lang,
                        force_new_session=force_new_session,
                        grammar_focus=resolved_focus,
                        observability_context={
                            "request_id": request_id,
                            "correlation_id": correlation_id,
                            "route": route_path,
                        },
                    )
                )
                workflow_elapsed_ms = int((time.perf_counter() - workflow_started_at) * 1000)
                workflow_phase_metrics = dict(result.get("phase_metrics") or {}) if isinstance(result, dict) else {}
                workflow_readiness = dict((result or {}).get("readiness_diagnostics") or {}) if isinstance(result, dict) else {}
                _log_compact_trace(
                    "auth_start",
                    stage="workflow_done",
                    request_id=request_id,
                    path=request.path,
                    user_id=int(user_id),
                    workflow_duration_ms=workflow_elapsed_ms,
                    feature_limit_duration_ms=int(workflow_phase_metrics.get("feature_limit_ms") or 0),
                    session_lookup_duration_ms=int(workflow_phase_metrics.get("active_lookup_ms") or 0),
                    session_state_duration_ms=int(workflow_phase_metrics.get("session_state_ms") or 0),
                    session_insert_duration_ms=int(workflow_phase_metrics.get("session_insert_ms") or 0),
                    seed_collect_duration_ms=int(workflow_phase_metrics.get("seed_collect_ms") or 0),
                    seed_topup_duration_ms=int(workflow_phase_metrics.get("seed_topup_ms") or 0),
                    seed_insert_duration_ms=int(workflow_phase_metrics.get("seed_insert_ms") or 0),
                    commit_duration_ms=int(workflow_phase_metrics.get("commit_ms") or 0),
                    personal_added=int(workflow_readiness.get("personal_added") or 0),
                    pool_added=int(workflow_readiness.get("pool_added") or 0),
                    generic_added=int(workflow_readiness.get("generic_added") or 0),
                    llm_added_on_start=int(workflow_readiness.get("quick_topup_added") or 0),
                )
            except Exception as exc:
                _log_compact_trace(
                    "auth_start",
                    stage="workflow_exception",
                    request_id=request_id,
                    path=request.path,
                    user_id=int(user_id),
                    duration_ms=_elapsed_ms_since(started_at),
                    exception=exc.__class__.__name__,
                )
                _log_start_route_observation(
                    user_id=int(user_id),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    focus_kind=str(resolved_focus.get("kind") or "").strip(),
                    focus_key=str(resolved_focus.get("key") or "").strip() or None,
                    level=str(level or "").strip().lower(),
                    access_guard_cache_source=getattr(g, "webapp_access_guard_cache_source", None),
                    instance_guard_cache_source=getattr(g, "webapp_instance_guard_cache_source", None),
                    language_pair_lookup_duration_ms=language_pair_duration_ms,
                    language_pair_lookup_mode=language_pair_lookup_mode,
                    focus_duration_ms=focus_duration_ms,
                    final_status="error",
                    error_code=exc.__class__.__name__,
                    duration_ms=_elapsed_ms_since(started_at),
                    http_status=500,
                    **summarize_db_acquire_events(db_acquire_events),
                )
                return jsonify({"error": f"Ошибка запуска сессии: {exc}"}), 500

            if isinstance(result, dict) and result.get("error"):
                error_code = str(result.get("error") or "").strip().lower()
                status_code = 429 if error_code in {"feature_limit_exceeded", "cost_cap_exceeded"} else 500
                start_phase_metrics = dict(result.get("phase_metrics") or {})
                _log_start_route_observation(
                    user_id=int(user_id),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    focus_kind=str(resolved_focus.get("kind") or "").strip(),
                    focus_key=str(resolved_focus.get("key") or "").strip() or None,
                    level=str(level or "").strip().lower(),
                    access_guard_cache_source=getattr(g, "webapp_access_guard_cache_source", None),
                    instance_guard_cache_source=getattr(g, "webapp_instance_guard_cache_source", None),
                    language_pair_lookup_duration_ms=language_pair_duration_ms,
                    language_pair_lookup_mode=language_pair_lookup_mode,
                    focus_duration_ms=focus_duration_ms,
                    workflow_duration_ms=workflow_elapsed_ms,
                    start_close_stale_open_duration_ms=int(start_phase_metrics.get("close_stale_open_ms") or 0),
                    start_active_lookup_duration_ms=int(start_phase_metrics.get("active_lookup_ms") or 0),
                    start_session_state_duration_ms=int(start_phase_metrics.get("session_state_ms") or 0),
                    start_close_empty_active_duration_ms=int(start_phase_metrics.get("close_empty_active_ms") or 0),
                    start_feature_limit_duration_ms=int(start_phase_metrics.get("feature_limit_ms") or 0),
                    start_session_insert_duration_ms=int(start_phase_metrics.get("session_insert_ms") or 0),
                    start_recent_keys_duration_ms=int(start_phase_metrics.get("recent_keys_ms") or 0),
                    start_seed_collect_duration_ms=int(start_phase_metrics.get("seed_collect_ms") or 0),
                    start_seed_topup_duration_ms=int(start_phase_metrics.get("seed_topup_ms") or 0),
                    start_seed_insert_duration_ms=int(start_phase_metrics.get("seed_insert_ms") or 0),
                    start_commit_duration_ms=int(start_phase_metrics.get("commit_ms") or 0),
                    final_status="error",
                    error_code=error_code or "workflow_error",
                    duration_ms=_elapsed_ms_since(started_at),
                    http_status=status_code,
                    **summarize_db_acquire_events(db_acquire_events),
                )
                if error_code in {"feature_limit_exceeded", "cost_cap_exceeded"}:
                    return jsonify(result), 429
                return jsonify({"error": result["error"]}), 500

            build_payload_started_perf = time.perf_counter()
            response_payload = _build_translation_session_start_payload(
                user_id=int(user_id),
                username=username,
                source_lang=source_lang,
                target_lang=target_lang,
                result=result if isinstance(result, dict) else {},
                topic=str(resolved_focus.get("prompt_topic") or topic or "Random sentences").strip(),
                level=level,
                grammar_focus=resolved_focus,
                tested_skill_profile_seed=None,
            )
            build_payload_duration_ms = _elapsed_ms_since(build_payload_started_perf)
            session_id = int(response_payload.get("session_id") or 0) if response_payload.get("session_id") else None
            ready_count = int(response_payload.get("ready_count") or 0)
            expected_total = int(response_payload.get("expected_total") or 7)
            remaining_count = int(response_payload.get("remaining_count") or 0)
            generation_started = bool(response_payload.get("generation_in_progress"))
            start_phase_metrics = dict(result.get("phase_metrics") or {}) if isinstance(result, dict) else {}
            effective_focus_kind = str((result or {}).get("focus_kind") or resolved_focus.get("kind") or "").strip().lower()
            effective_focus_key = str((result or {}).get("focus_key") or resolved_focus.get("key") or "").strip()
            readiness_diagnostics = dict((result or {}).get("readiness_diagnostics") or {})
            background_fill_required = bool((result or {}).get("background_fill_required"))
            refill_trigger_result = _maybe_trigger_translation_focus_pool_deficit_refill(
                source_lang=source_lang,
                target_lang=target_lang,
                focus_key=effective_focus_key,
                level=level,
                readiness_diagnostics=readiness_diagnostics,
                background_fill_required=background_fill_required,
            )

            total_elapsed_ms = int((time.perf_counter() - started_at) * 1000)
            logging.info(
                "webapp translation start completed: user_id=%s session_id=%s ready_count=%s expected_total=%s remaining_count=%s "
                "generation_in_progress=%s workflow_ms=%s total_ms=%s focus_kind=%s focus_key=%s level=%s "
                "personal_added=%s pool_added=%s generic_added=%s llm_added_on_start=%s deficit_refill_triggered=%s",
                int(user_id),
                int(session_id or 0),
                int(ready_count),
                int(expected_total),
                int(remaining_count),
                bool(generation_started),
                int(workflow_elapsed_ms),
                int(total_elapsed_ms),
                effective_focus_kind,
                effective_focus_key,
                str(level or "").strip().lower(),
                int(readiness_diagnostics.get("personal_added") or 0),
                int(readiness_diagnostics.get("pool_added") or 0),
                int(readiness_diagnostics.get("generic_added") or 0),
                int(readiness_diagnostics.get("quick_topup_added") or 0),
                bool(refill_trigger_result.get("triggered")),
            )
            db_trace_meta = summarize_db_acquire_events(db_acquire_events)
            _log_compact_trace(
                "auth_start",
                stage="response_ready",
                request_id=request_id,
                path=request.path,
                user_id=int(user_id),
                build_payload_duration_ms=build_payload_duration_ms,
                session_id=int(session_id or 0) if session_id else None,
                ready_count=ready_count,
                expected_total=expected_total,
                remaining_count=remaining_count,
                generation_in_progress=bool(generation_started),
                background_fill_required=bool(background_fill_required),
                deficit_refill_triggered=bool(refill_trigger_result.get("triggered")),
                db_pool_acquire_count=int(db_trace_meta.get("db_pool_acquire_count") or 0),
                db_pool_acquire_wait_ms_total=int(db_trace_meta.get("db_pool_acquire_wait_ms_total") or 0),
            )
            response_body = {
                "ok": True,
                **response_payload,
                "language_pair": _build_language_pair_payload(source_lang, target_lang),
            }
            if session_id and response_body.get("items"):
                _mark_translation_sentences_delivered(
                    user_id=int(user_id),
                    source_lang=source_lang,
                    target_lang=target_lang,
                    items=response_body.get("items"),
                )
            if session_id:
                try:
                    _write_session_presence_projection_active(
                        user_id=int(user_id),
                        session_id=int(session_id),
                        source_lang=source_lang,
                        target_lang=target_lang,
                    )
                except Exception:
                    logging.warning(
                        "Phase1 session_presence_card publish failed on start: user_id=%s session_id=%s",
                        int(user_id),
                        int(session_id or 0),
                        exc_info=True,
                    )
            _log_start_route_observation(
                user_id=int(user_id),
                session_id=int(session_id or 0) if session_id else None,
                source_lang=source_lang,
                target_lang=target_lang,
                focus_kind=effective_focus_kind,
                focus_key=effective_focus_key or None,
                level=str(level or "").strip().lower(),
                ready_count=ready_count,
                expected_total=expected_total,
                remaining_count=remaining_count,
                generation_in_progress=bool(generation_started),
                personal_added=int(readiness_diagnostics.get("personal_added") or 0),
                pool_added=int(readiness_diagnostics.get("pool_added") or 0),
                generic_added=int(readiness_diagnostics.get("generic_added") or 0),
                llm_added_on_start=int(readiness_diagnostics.get("quick_topup_added") or 0),
                background_fill_required=bool(background_fill_required),
                deficit_refill_triggered=bool(refill_trigger_result.get("triggered")),
                ready_items_lookup_mode="session_id" if session_id else "active_discovery_fallback",
                sync_cleanup_mode="removed_from_start_path",
                access_guard_cache_source=getattr(g, "webapp_access_guard_cache_source", None),
                instance_guard_cache_source=getattr(g, "webapp_instance_guard_cache_source", None),
                language_pair_lookup_duration_ms=language_pair_duration_ms,
                language_pair_lookup_mode=language_pair_lookup_mode,
                focus_duration_ms=focus_duration_ms,
                workflow_duration_ms=workflow_elapsed_ms,
                build_payload_duration_ms=build_payload_duration_ms,
                start_close_stale_open_duration_ms=int(start_phase_metrics.get("close_stale_open_ms") or 0),
                start_active_lookup_duration_ms=int(start_phase_metrics.get("active_lookup_ms") or 0),
                start_session_state_duration_ms=int(start_phase_metrics.get("session_state_ms") or 0),
                start_close_empty_active_duration_ms=int(start_phase_metrics.get("close_empty_active_ms") or 0),
                start_feature_limit_duration_ms=int(start_phase_metrics.get("feature_limit_ms") or 0),
                start_session_insert_duration_ms=int(start_phase_metrics.get("session_insert_ms") or 0),
                start_recent_keys_duration_ms=int(start_phase_metrics.get("recent_keys_ms") or 0),
                start_seed_collect_duration_ms=int(start_phase_metrics.get("seed_collect_ms") or 0),
                start_seed_topup_duration_ms=int(start_phase_metrics.get("seed_topup_ms") or 0),
                start_seed_insert_duration_ms=int(start_phase_metrics.get("seed_insert_ms") or 0),
                start_commit_duration_ms=int(start_phase_metrics.get("commit_ms") or 0),
                response_size_bytes=_estimate_json_payload_size_bytes(response_body),
                final_status="success",
                duration_ms=_elapsed_ms_since(started_at),
                http_status=200,
                **db_trace_meta,
            )
            return jsonify(response_body)
    finally:
        _release_shared_idempotency(start_idempotency_key, start_idempotency_token)


@app.route("/api/webapp/story/history", methods=["POST"])
def get_webapp_story_history():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    limit = int(payload.get("limit", 10))

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    items = get_story_history_webapp(user_id=user_id, limit=limit)
    return jsonify(
        {
            "ok": True,
            "items": items,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


@app.route("/api/webapp/story/start", methods=["POST"])
def start_webapp_story():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    mode = (payload.get("mode") or "new").strip().lower()
    story_type = (payload.get("story_type") or "знаменитая личность").strip()
    difficulty = (payload.get("difficulty") or "средний").strip()
    story_id = payload.get("story_id")

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    username = _extract_display_name(user_data)

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    paid_gate_payload, paid_gate_status = _paid_surface_gate_response(
        user_id=int(user_id),
        feature="story_mode",
        feature_title="Загадочная история",
    )
    if paid_gate_payload is not None:
        return jsonify(paid_gate_payload), paid_gate_status

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    # Плательщика ставим, но САМА генерация истории — за счёт заведения: она наполняет
    # общий банк, и арена предлагает готовую историю другим игрокам. Поэтому
    # generate_mystery_story занесена в _SYSTEM_ATTRIBUTION_TASKS и принудительно
    # пишется ничьей, что бы тут ни стояло — это единственная точка правды по вопросу
    # «на человека или на дом». Строка остаётся, чтобы ЛИЧНАЯ работа, если она появится
    # под этим обработчиком, сразу попадала в потолок игрока, а не терялась как раньше.
    # Снимаем в finally: поток веб-сервера переиспользуется, забытый id уехал бы на
    # следующий запрос. Внутри asyncio.run значение доживает — задачи копируют текущий
    # контекст, в том числе под asyncio.gather.
    from backend.openai_manager import set_llm_billing_user
    set_llm_billing_user(int(user_id))
    try:
        result = asyncio.run(
            start_story_session_webapp(
                user_id=user_id,
                username=username,
                mode=mode,
                story_type=story_type,
                difficulty=difficulty,
                story_id=int(story_id) if story_id else None,
                source_lang=source_lang,
                target_lang=target_lang,
            )
        )
    except Exception as exc:
        return jsonify({"error": f"Ошибка запуска истории: {exc}"}), 500
    finally:
        set_llm_billing_user(None)

    if isinstance(result, dict) and result.get("error"):
        return jsonify({"error": result["error"]}), 400
    if isinstance(result, dict) and bool(result.get("created")):
        # Счётчик «человек запустил историю». Настоящий вызов (generate_mystery_story)
        # теперь замеряется и пишется на него же — см. set_llm_billing_user выше.
        _billing_log_event_safe(
            user_id=int(user_id),
            action_type="story_start_generation",
            provider="app_internal",
            units_type="requests",
            units_value=1.0,
            source_lang=source_lang,
            target_lang=target_lang,
            idempotency_seed=f"story_start:{user_id}:{result.get('session_id') or time.time_ns()}",
            status="estimated",
            metadata={
                "mode": mode,
                "story_type": story_type,
                "difficulty": difficulty,
            },
        )

    return jsonify(
        {
            "ok": True,
            **result,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


@app.route("/api/webapp/story/submit", methods=["POST"])
def submit_webapp_story():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    translations = payload.get("translations") or []
    guess = (payload.get("guess") or "").strip()

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not translations:
        return jsonify({"error": "translations обязательны"}), 400
    if not guess:
        return jsonify({"error": "guess обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    username = _extract_display_name(user_data)

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    paid_gate_payload, paid_gate_status = _paid_surface_gate_response(
        user_id=int(user_id),
        feature="story_mode",
        feature_title="Загадочная история",
    )
    if paid_gate_payload is not None:
        return jsonify(paid_gate_payload), paid_gate_status

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    # Проверка ЕГО перевода и разбор ЕГО догадки — чисто личная работа, никому больше
    # не пригодится. Два вызова (check_translation_story_arena и
    # check_story_guess_semantic) писались в никуда; теперь идут в его дневной потолок.
    from backend.openai_manager import set_llm_billing_user
    set_llm_billing_user(int(user_id))
    try:
        result = asyncio.run(
            submit_story_translation_webapp(
                user_id=user_id,
                username=username,
                translations=translations,
                guess=guess,
                source_lang=source_lang,
                target_lang=target_lang,
            )
        )
    except Exception as exc:
        detailed_message = _extract_api_error_message(exc)
        if detailed_message:
            return jsonify({"error": f"Ошибка истории: {detailed_message}"}), 500
        return jsonify({"error": "Ошибка истории: не удалось обработать проверку"}), 500
    finally:
        set_llm_billing_user(None)

    if isinstance(result, dict) and result.get("error"):
        return jsonify({"error": result["error"]}), 400
    # Счётчик «человек сдал перевод». Настоящие вызовы замеряются и пишутся на него.
    _billing_log_event_safe(
        user_id=int(user_id),
        action_type="story_submit_check",
        provider="app_internal",
        units_type="requests",
        units_value=3.0,
        source_lang=source_lang,
        target_lang=target_lang,
        idempotency_seed=f"story_submit:{user_id}:{result.get('session_id') or time.time_ns()}",
        status="estimated",
        metadata={
            "translations_count": len(translations),
            "has_guess": bool(guess),
            "estimated_llm_calls": 2,  # arena scoring + semantic guess; teacher breakdown billed by /story/explain
        },
    )

    return jsonify(
        {
            "ok": True,
            **result,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


@app.route("/api/webapp/story/explain", methods=["POST"])
def explain_webapp_story():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    session_id = payload.get("session_id")
    explanation_language = (payload.get("explanation_language") or "ru").strip().lower()

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    paid_gate_payload, paid_gate_status = _paid_surface_gate_response(
        user_id=int(user_id),
        feature="story_mode",
        feature_title="Загадочная история",
    )
    if paid_gate_payload is not None:
        return jsonify(paid_gate_payload), paid_gate_status

    source_lang, target_lang, _profile = _get_user_language_pair(int(user_id))

    # Разбор ЕГО ошибок в истории. Внутри два параллельных вызова через asyncio.gather
    # (check_story_explanation_core и ..._meta) — оба копируют этот контекст, поэтому
    # обоим достаётся владелец разбора.
    from backend.openai_manager import set_llm_billing_user
    set_llm_billing_user(int(user_id))
    try:
        result = asyncio.run(
            explain_story_translation_webapp(
                user_id=user_id,
                session_id=session_id,
                explanation_language=explanation_language,
            )
        )
    except Exception as exc:
        detailed_message = _extract_api_error_message(exc)
        if detailed_message:
            return jsonify({"error": f"Ошибка разбора: {detailed_message}"}), 500
        return jsonify({"error": "Ошибка разбора: не удалось подготовить разбор"}), 500
    finally:
        set_llm_billing_user(None)

    if isinstance(result, dict) and result.get("error"):
        return jsonify({"error": result["error"]}), 400

    # Only bill when we actually ran the LLM (cached re-opens are free).
    if not result.get("cached"):
        # Счётчик «человек открыл разбор». Настоящие вызовы замеряются и пишутся на него.
        _billing_log_event_safe(
            user_id=int(user_id),
            action_type="story_explain",
            provider="app_internal",
            units_type="requests",
            units_value=1.0,
            source_lang=source_lang,
            target_lang=target_lang,
            idempotency_seed=f"story_explain:{user_id}:{result.get('session_id') or time.time_ns()}:{explanation_language}",
            status="estimated",
            metadata={"estimated_llm_calls": 1, "explanation_language": explanation_language},
        )

    return jsonify(
        {
            "ok": True,
            **result,
            "language_pair": _build_language_pair_payload(source_lang, target_lang),
        }
    )


