@app.route("/api/webapp/session", methods=["POST"])
def get_webapp_session():
    started_perf = time.perf_counter()
    payload = request.get_json(silent=True) or {}
    request_id = _extract_observability_request_id(payload)
    g.request_id = request_id
    correlation_id = _build_observability_correlation_id(payload=payload, prefix="webapp_session")
    init_data = payload.get("initData")

    if not init_data:
        _log_flow_observation(
            "webapp_session",
            "session_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "initData обязателен"}), 400

    if not _telegram_hash_is_valid(init_data):
        _log_flow_observation(
            "webapp_session",
            "session_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=401,
        )
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")

    if not user_id:
        _log_flow_observation(
            "webapp_session",
            "session_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=400,
        )
        return jsonify({"error": "user_id отсутствует в initData"}), 400
    g.trace_auth_user_id = int(user_id)
    _log_compact_trace(
        "auth_session",
        stage="auth_resolved",
        request_id=request_id,
        path=request.path,
        method=request.method,
        user_id=int(user_id),
        auth_resolution_duration_ms=_elapsed_ms_since(started_perf),
    )

    lookup_started_perf = time.perf_counter()
    projection_payload, session_lookup_mode = _load_session_presence_projection_with_source(int(user_id))
    lookup_duration_ms = _elapsed_ms_since(lookup_started_perf)
    _log_compact_trace(
        "auth_session",
        stage="lookup_done",
        request_id=request_id,
        path=request.path,
        user_id=int(user_id),
        session_lookup_mode=session_lookup_mode,
        session_lookup_duration_ms=lookup_duration_ms,
    )
    if not isinstance(projection_payload, dict):
        response_payload = {
            "error": "Session presence projection is not ready",
            "code": "session_presence_projection_not_ready",
        }
        _log_flow_observation(
            "webapp_session",
            "session_completed",
            request_id=request_id,
            correlation_id=correlation_id,
            user_id=int(user_id),
            language_pair_lookup_duration_ms=0,
            session_lookup_duration_ms=lookup_duration_ms,
            session_lookup_mode="projection_missing",
            response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
            final_status="error",
            duration_ms=_elapsed_ms_since(started_perf),
            http_status=503,
        )
        return jsonify(response_payload), 503

    response_payload = _build_session_presence_response_payload(projection_payload)
    _log_flow_observation(
        "webapp_session",
        "session_completed",
        request_id=request_id,
        correlation_id=correlation_id,
        user_id=int(user_id),
        session_type=str(response_payload.get("type") or "").strip() or "none",
        session_id=str(response_payload.get("session_id") or "").strip() or None,
        source_lang=str(projection_payload.get("source_lang") or "").strip() or None,
        target_lang=str(projection_payload.get("target_lang") or "").strip() or None,
        language_pair_lookup_duration_ms=0,
        session_lookup_duration_ms=lookup_duration_ms,
        session_lookup_mode=session_lookup_mode,
        response_size_bytes=_estimate_json_payload_size_bytes(response_payload),
        final_status="success",
        duration_ms=_elapsed_ms_since(started_perf),
        http_status=200,
    )
    return jsonify(response_payload)


@app.route("/api/webapp/session/activity", methods=["POST"])
def sync_webapp_translation_session_activity():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    session_id = payload.get("session_id")
    action = str(payload.get("action") or "").strip().lower()

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not session_id:
        return jsonify({"error": "session_id обязателен"}), 400
    if action not in {"start", "resume", "pause", "stop"}:
        return jsonify({"error": "Некорректное действие активности"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    try:
        result = sync_translation_session_activity(
            user_id=int(user_id),
            session_id=session_id,
            action=action,
        )
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400
    except Exception as exc:
        logging.warning(
            "Failed to sync translation session activity: user_id=%s session_id=%s action=%s error=%s",
            user_id,
            session_id,
            action,
            exc,
            exc_info=True,
        )
        return jsonify({"error": "Не удалось синхронизировать активное время"}), 500

    if not result:
        return jsonify({"error": "Сессия не найдена"}), 404

    return jsonify({"ok": True, **result})


@app.route("/api/webapp/submit-group", methods=["POST"])
def submit_webapp_group_message():
    payload = request.get_json(silent=True) or {}
    init_data = payload.get("initData")
    translations = payload.get("translations") or []

    if not init_data:
        return jsonify({"error": "initData обязателен"}), 400
    if not translations:
        return jsonify({"error": "translations обязательны"}), 400

    if not _telegram_hash_is_valid(init_data):
        return jsonify({"error": "initData не прошёл проверку"}), 401

    parsed = _parse_telegram_init_data(init_data)
    user_data = parsed.get("user") or {}
    user_id = user_data.get("id")
    user_name = user_data.get("first_name") or "User"
    username = _extract_display_name(user_data)

    if not user_id:
        return jsonify({"error": "user_id отсутствует в initData"}), 400

    latest_sentences = get_latest_daily_sentences(user_id=user_id, limit=50)
    sentence_map = {
        item["id_for_mistake_table"]: item["sentence"]
        for item in latest_sentences
    }

    lines = [f"WebApp submission от {user_name}" + (f" (@{username})" if username else "")]
    for idx, entry in enumerate(translations, start=1):
        sentence_id = entry.get("id_for_mistake_table")
        translation = (entry.get("translation") or "").strip()
        if not translation:
            continue
        original = sentence_map.get(sentence_id, "—")
        lines.append(f"{idx}. {original}")
        lines.append(f"DE: {translation}")

    if len(lines) == 1:
        return jsonify({"error": "Нет заполненных переводов"}), 400

    # Техническую карточку «Сегодняшняя статистика» больше не дописываем —
    # после перевода такие сводки не отправляем никуда (личка/группа), это лишняя нагрузка.

    try:
        target_chat_id = _resolve_user_delivery_chat_id(int(user_id), job_name="submit_webapp_group_message")
        if int(target_chat_id) < 0:
            _send_group_message("\n".join(lines), chat_id=int(target_chat_id))
        else:
            _send_private_message(user_id=int(target_chat_id), text="\n".join(lines))
    except Exception as exc:
        return jsonify({"error": f"Ошибка отправки сообщения: {exc}"}), 500

    return jsonify({"ok": True})


def pack_mistake_segments(
    segments: list[AudioSegment],
    max_part_bytes: int | None = None,
) -> list[bytes]:
    """Group rendered разборы into files Telegram will accept — bot uploads die at 50 MB
    with a 413, which is exactly how a 32-разбор batch went missing. A разбор is the atom:
    it always lands whole inside one file, so nobody gets a sentence cut mid-drill. Sizes
    come from duration — the export bitrate is constant, so ms → bytes is exact enough."""
    budget_bytes = max(1, int(max_part_bytes or _MISTAKES_AUDIO_MAX_PART_BYTES))
    parts: list[bytes] = []
    current: AudioSegment | None = None
    current_bytes = 0

    def _estimate_bytes(segment: AudioSegment) -> int:
        return int(len(segment) / 1000.0 * _AUDIO_EXPORT_KBPS * 1000 / 8)

    def _flush() -> None:
        nonlocal current, current_bytes
        if current is not None and len(current) > 0:
            parts.append(export_audio_segment(current))
        current, current_bytes = None, 0

    for segment in segments:
        if len(segment) == 0:
            continue
        size = _estimate_bytes(segment)
        if current is not None and current_bytes + size > budget_bytes:
            _flush()
        if current is None:
            # A single разбор over budget can't be split without breaking the drill —
            # send it alone and let the 413 (if any) surface in the job errors.
            current, current_bytes = segment, size
        else:
            current += segment
            current_bytes += size
    _flush()
    return parts


def _send_mistakes_audio_parts(
    *,
    target_chat_id: int,
    parts: list[bytes],
    filename: str,
    caption: str,
) -> None:
    total = len(parts)
    for index, payload in enumerate(parts, start=1):
        part_caption = caption if total == 1 else f"{caption} — часть {index} из {total}"
        part_filename = filename if total == 1 else f"{filename.rsplit('.', 1)[0]}_{index}.mp3"
        if int(target_chat_id) < 0:
            _send_group_audio(payload, part_filename, part_caption, chat_id=int(target_chat_id))
        else:
            _send_private_audio(
                user_id=int(target_chat_id),
                audio_bytes=payload,
                filename=part_filename,
                caption=part_caption,
            )


