def _apply_group_summary_labels(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not rows:
        return []
    cache: dict[int, str | None] = {}
    normalized: list[dict[str, Any]] = []
    for row in rows:
        item = dict(row)
        user_id = int(item.get("user_id") or 0)
        item["username"] = _resolve_today_group_user_label(
            user_id,
            str(item.get("username") or "").strip() or None,
            cache=cache,
        )
        normalized.append(item)
    return normalized


def _ru_plural(n: int, one: str, few: str, many: str) -> str:
    n = abs(int(n))
    if n % 10 == 1 and n % 100 != 11:
        return one
    if 2 <= n % 10 <= 4 and not (12 <= n % 100 <= 14):
        return few
    return many


def _is_dead_group_error(exc) -> bool:
    """True when a group-send failure means the bot can no longer post there (kicked,
    chat deleted/not found, not a member, upgraded to supergroup) — as opposed to a
    transient network/timeout error we should retry next run."""
    msg = str(exc or "").lower()
    return any(s in msg for s in (
        "bot was kicked", "bot is not a member", "chat not found", "forbidden",
        "chat was upgraded", "group chat was deactivated", "the group chat was deleted",
        "user_deactivated", "peer_id_invalid", "chat_write_forbidden",
    ))


def _retire_group_if_dead(chat_id: int, exc) -> bool:
    """If a group send failed because the group is dead, retire it (deactivate_group_chat)
    so its members fall back to individual delivery — or to another live group they're in
    (only this chat's rows are marked). No-op on transient errors. Returns True if retired."""
    if not _is_dead_group_error(exc):
        return False
    try:
        from backend.database import deactivate_group_chat
        deactivate_group_chat(int(chat_id))
        logging.warning("group summary: chat %s is dead (%s) → retired", chat_id, exc)
        return True
    except Exception:
        logging.warning("group summary: deactivate_group_chat failed chat_id=%s", chat_id, exc_info=True)
        return False


def _get_users_active_on_date_safe(day) -> set:
    try:
        from backend.database import get_users_active_on_date
        return {int(u) for u in (get_users_active_on_date(day) or set())}
    except Exception:
        logging.warning("group: get_users_active_on_date failed for %s", day, exc_info=True)
        return set()


def _make_active_on_date_cache():
    """Memoise the (heavy) per-date active-user set within one dispatch run so multiple
    groups + a multi-day streak walk don't re-query the same day."""
    cache: dict = {}

    def getter(day):
        if day not in cache:
            cache[day] = _get_users_active_on_date_safe(day)
        return cache[day]

    return getter


def _group_streak_days(cohort: set, today: date, active_getter, max_lookback: int = 60) -> int:
    """Consecutive days ending today the group was 'on the go' — at least ONE member
    active. Blame-free by design: a single member skipping never breaks it."""
    if not cohort:
        return 0
    streak = 0
    day = today
    for _ in range(max_lookback):
        if active_getter(day) & cohort:
            streak += 1
            day = day - timedelta(days=1)
        else:
            break
    return streak


def _group_all_together_days(cohort: set, start: date, end: date, active_getter) -> int:
    """Days in [start, end] EVERY member trained — the weekly 'all together' pride stat
    (kept out of the daily streak so one skipped day never blames anyone)."""
    if not cohort:
        return 0
    days = 0
    day = start
    while day <= end:
        if cohort <= active_getter(day):
            days += 1
        day = day + timedelta(days=1)
    return days


def _group_day_total(cohort: set, day: date) -> int:
    """Total activities the group did on `day`: translations + interactive/quiz answers
    + words learned. (Quiz uses the last-24h window — valid for today's pulse only.)"""
    total = 0
    try:
        trows = _fetch_group_daily_summary_rows(target_date=day, cohort_user_ids=list(cohort))
        total += sum(int(r.get("translated") or 0) for r in (trows or []))
    except Exception:
        logging.warning("group day total: translations failed", exc_info=True)
    try:
        from backend.quiz_leaderboard import get_leaderboard_rows_since, compute_quiz_leaderboard
        qrows = [r for r in (get_leaderboard_rows_since(24) or []) if int(r.get("user_id") or 0) in cohort]
        total += sum(int(l.get("answered") or 0) for l in (compute_quiz_leaderboard(qrows).get("leaders") or []))
    except Exception:
        logging.warning("group day total: quiz failed", exc_info=True)
    try:
        from backend.database import _cert_learned_words_by_user
        wmap = _cert_learned_words_by_user(day, day + timedelta(days=1))
        total += sum(int(c or 0) for u, c in (wmap or {}).items() if int(u) in cohort)
    except Exception:
        logging.warning("group day total: words failed", exc_info=True)
    return int(total)


def _format_group_daily_pulse(*, target_date: date, member_names: dict, active_ids: set, streak_days: int, day_total: int) -> str:
    """Tiny co-op end-of-day pulse (Telegram HTML): who trained, group streak, day total."""
    from html import escape as _esc

    def nm(uid: int) -> str:
        n = str(member_names.get(int(uid)) or "").strip()
        return _esc(n) if n else "участник"

    ordered = list(member_names.keys())
    active = [uid for uid in ordered if int(uid) in active_ids]
    absent = [uid for uid in ordered if int(uid) not in active_ids]
    lines = [f"🦊 <b>Итоги дня</b> · {target_date.strftime('%d.%m')}"]
    if active:
        lines.append("Занимались: " + " · ".join(f"✅ {nm(u)}" for u in active))
    else:
        lines.append("Сегодня пока тихо — завтра наверстаем 🙂")
    if absent and active:
        verb = "сегодня отдохнул" if len(absent) == 1 else "сегодня отдыхают"
        lines.append("🌙 " + ", ".join(nm(u) for u in absent) + " " + verb)
    if streak_days >= 2:
        lines.append(f"🔥 Группа на ходу — {streak_days}-й день подряд")
    if day_total > 0:
        word = _ru_plural(day_total, "задание", "задания", "заданий")
        lines.append(f"📚 Сегодня вместе: {day_total} {word}")
    return "\n".join(lines)


def _dispatch_daily_group_summary(*, target_date: date, tz_name: str = TODAY_PLAN_DEFAULT_TZ) -> dict[str, Any]:
    targets = _collect_group_summary_targets()
    if not targets:
        return {"ok": True, "date": target_date.isoformat(), "sent": 0, "groups": 0, "errors": [], "tz": tz_name}

    active_getter = _make_active_on_date_cache()
    from backend.database import get_display_names_for_users

    sent = 0
    errors: list[str] = []
    groups = 0
    for target in targets:
        chat_id = int(target.get("chat_id") or 0)
        if chat_id >= 0:
            continue
        groups += 1
        try:
            member_user_ids = list_webapp_group_member_user_ids(chat_id, limit=5000, only_confirmed=False)
            cohort = {int(u) for u in member_user_ids}
            if not cohort:
                continue
            try:
                member_names = dict(get_display_names_for_users(list(cohort)) or {})
            except Exception:
                member_names = {}
            for uid in cohort:
                member_names.setdefault(int(uid), "")
            active_ids = active_getter(target_date) & cohort
            streak = _group_streak_days(cohort, target_date, active_getter)
            day_total = _group_day_total(cohort, target_date)
            text = _format_group_daily_pulse(
                target_date=target_date, member_names=member_names,
                active_ids=active_ids, streak_days=streak, day_total=day_total,
            )
            _send_group_message(text=text, chat_id=chat_id, parse_mode="HTML")
            sent += 1
        except Exception as exc:
            errors.append(f"chat {chat_id}: {exc}")
            _retire_group_if_dead(chat_id, exc)
            logging.warning("⚠️ Failed to send daily group pulse chat_id=%s", chat_id, exc_info=True)

    return {
        "ok": True,
        "date": target_date.isoformat(),
        "tz": tz_name,
        "groups": groups,
        "sent": sent,
        "errors": errors,
    }


def _build_group_week_vs_avg_chart_png(
    *, this_week: int, avg4: float | None, record: int | None, title: str, subtitle: str | None = None
) -> bytes | None:
    """Co-op weekly bar chart: this week vs the group's 4-week average (+ record).
    Fuchs/Felix warm palette; the current week is the amber hero bar."""
    plt = _get_plt()
    if plt is None:
        return None
    outer_bg = "#efe2cd"; inner_bg = "#f8f1e5"; grid_color = "#d9cabb"
    text_color = "#554636"; amber = "#e0952f"; muted = "#b8a894"; record_col = "#cdb89c"
    labels = ["Эта неделя"]; values = [float(this_week or 0)]; colors = [amber]
    if avg4 is not None:
        labels.append("Среднее\n4 недели"); values.append(float(avg4)); colors.append(muted)
    if record is not None:
        labels.append("Рекорд"); values.append(float(record)); colors.append(record_col)
    fig, ax = plt.subplots(figsize=(6.6, 4.4), dpi=170)
    fig.patch.set_facecolor(outer_bg); ax.set_facecolor(inner_bg)
    x = list(range(len(values)))
    bars = ax.bar(x, values, color=colors, width=0.6, edgecolor="none")
    top = max(values + [1.0])
    ax.set_ylim(0, top * 1.24)
    ax.set_xticks(x); ax.set_xticklabels(labels, fontsize=13, color=text_color)
    ax.tick_params(axis="x", length=0)
    ax.tick_params(axis="y", colors=text_color, labelsize=11, length=0)
    ax.grid(axis="y", color=grid_color, linewidth=1, alpha=0.8); ax.set_axisbelow(True)
    for spine in ax.spines.values():
        spine.set_visible(False)
    for b, v in zip(bars, values):
        ax.text(b.get_x() + b.get_width() / 2.0, v + top * 0.03, f"{int(round(v))}",
                ha="center", va="bottom", fontsize=17, fontweight="bold", color=text_color)
    fig.text(0.065, 0.965, str(title or "").strip(), fontsize=17, fontweight="bold", color=text_color, ha="left", va="top")
    if subtitle:
        fig.text(0.065, 0.910, str(subtitle).strip(), fontsize=10.5, color="#7b6e62", ha="left", va="top")
    ax.set_position([0.10, 0.13, 0.86, 0.70])
    buf = io.BytesIO()
    fig.savefig(buf, format="png", facecolor=outer_bg)
    plt.close(fig)
    buf.seek(0)
    return buf.getvalue()


def _collect_group_weekly_activity(*, member_user_ids: list[int], week_start: date, week_end: date) -> dict[str, Any]:
    """Merge a group's weekly activity per member across translations + interactive/quiz
    answers (incl. battles/sprints) + words learned. 'total' per member sums all three."""
    cohort = {int(u) for u in (member_user_ids or [])}
    members: dict[int, dict] = {}

    def rec(uid: int) -> dict:
        return members.setdefault(int(uid), {
            "name": "", "translated": 0, "quiz_answered": 0,
            "quiz_points": 0, "quiz_correct": 0, "golds": 0, "words": 0,
        })

    try:
        trows = _fetch_group_weekly_summary_rows(
            week_start=week_start, week_end=week_end, cohort_user_ids=list(cohort)
        )
    except Exception:
        trows = []
        logging.warning("group weekly: translation rows failed", exc_info=True)
    for r in trows or []:
        uid = int(r.get("user_id") or 0)
        if uid <= 0:
            continue
        m = rec(uid)
        m["translated"] += int(r.get("translated") or 0)
        if not m["name"]:
            m["name"] = str(r.get("username") or "").strip()

    try:
        from backend.quiz_leaderboard import get_leaderboard_rows_since, compute_quiz_leaderboard
        qrows = [r for r in (get_leaderboard_rows_since(7 * 24) or []) if int(r.get("user_id") or 0) in cohort]
        for l in (compute_quiz_leaderboard(qrows).get("leaders") or []):
            uid = int(l.get("user_id") or 0)
            if uid <= 0:
                continue
            m = rec(uid)
            m["quiz_answered"] += int(l.get("answered") or 0)
            m["quiz_points"] += int(l.get("points") or 0)
            m["quiz_correct"] += int(l.get("correct") or 0)
            m["golds"] += int(l.get("golds") or 0)
            nm = str(l.get("name") or "").strip()
            if not m["name"] and nm and nm != "Student":
                m["name"] = nm
    except Exception:
        logging.warning("group weekly: quiz aggregation failed", exc_info=True)

    try:
        from backend.database import _cert_learned_words_by_user
        wmap = _cert_learned_words_by_user(week_start, week_end + timedelta(days=1))
        for uid, cnt in (wmap or {}).items():
            if int(uid) in cohort:
                rec(uid)["words"] += int(cnt or 0)
    except Exception:
        logging.warning("group weekly: words aggregation failed", exc_info=True)

    for m in members.values():
        m["total"] = int(m["translated"]) + int(m["quiz_answered"]) + int(m["words"])

    return {
        "members": members,
        "group_total": sum(m["total"] for m in members.values()),
        "translations_total": sum(m["translated"] for m in members.values()),
        "quizzes_total": sum(m["quiz_answered"] for m in members.values()),
        "words_total": sum(m["words"] for m in members.values()),
    }


def _format_group_weekly_hybrid_caption(
    *, activity: dict, avg4: float | None, record: int | None,
    week_start: date, week_end: date, global_rank: dict, global_total: int,
    all_together_days: int = 0, week_days: int = 7
) -> str:
    """Short co-op caption (Telegram HTML): group-vs-usual hero line, who led each activity,
    and each member's global top-N%. The chart image carries the visual comparison."""
    from html import escape as _esc
    members = activity["members"]
    group_total = int(activity["group_total"])

    def nm(uid: int) -> str:
        n = str(members.get(int(uid), {}).get("name") or "").strip()
        return _esc(n) if n else "участник"

    period = f"{week_start.strftime('%d.%m')}–{week_end.strftime('%d.%m')}"
    lines = [f"🦊 <b>Итоги недели</b> · {period}", ""]

    if avg4 is None:
        lines.append(f"🌱 Первая неделя вместе — <b>{group_total}</b> заданий. Задаём планку на будущее!")
    else:
        avg_i = int(round(avg4))
        if group_total > avg_i and avg_i > 0:
            pct = int(round((group_total - avg_i) / avg_i * 100))
            lines.append(f"🎉 <b>{group_total}</b> заданий вместе — обычно {avg_i}. ↑ +{pct}% лучше обычного!")
        elif group_total >= avg_i:
            lines.append(f"💪 <b>{group_total}</b> заданий вместе — как обычно (~{avg_i}). Держим темп!")
        else:
            lines.append(f"💪 <b>{group_total}</b> заданий вместе — обычно {avg_i}. Чуть меньше — наверстаем!")
        if record and group_total >= int(record) and group_total > avg_i:
            lines.append("🏆 Новый рекорд группы!")

    if all_together_days and week_days:
        dword = _ru_plural(all_together_days, "день", "дня", "дней")
        lines.append(f"👨‍👩‍👧 Все вместе занимались {all_together_days} из {week_days} {dword}")

    def top_by(key: str):
        cand = [(uid, m) for uid, m in members.items() if int(m.get(key) or 0) > 0]
        return max(cand, key=lambda kv: int(kv[1].get(key) or 0))[0] if cand else None

    standings = []
    t = top_by("translated")
    if t:
        standings.append(f"🥇 переводы — <b>{nm(t)}</b>")
    q = top_by("quiz_points")
    if q:
        standings.append(f"🎮 интерактивы — <b>{nm(q)}</b>")
    w = top_by("words")
    if w:
        standings.append(f"📚 слова — <b>{nm(w)}</b>")
    if standings:
        lines.append("")
        lines.extend(standings)

    if global_rank and global_total:
        ranked = sorted((uid for uid in members if int(uid) in global_rank), key=lambda u: global_rank[int(u)])
        gp = []
        for uid in ranked[:5]:
            pct = max(1, int(round((global_rank[int(uid)] + 1) / max(1, global_total) * 100)))
            gp.append(f"{nm(uid)} — топ {pct}%")
        if gp:
            lines.append("")
            lines.append("🌍 В общем рейтинге бота: " + " · ".join(gp))

    return "\n".join(lines)


def _dispatch_weekly_group_summary(*, target_date: date, tz_name: str = TODAY_PLAN_DEFAULT_TZ) -> dict[str, Any]:
    bounds = get_period_bounds("week", today=target_date)
    targets = _collect_group_summary_targets()
    if not targets:
        return {
            "ok": True,
            "date": target_date.isoformat(),
            "week_start": bounds.start_date.isoformat(),
            "week_end": bounds.end_date.isoformat(),
            "sent": 0,
            "groups": 0,
            "errors": [],
            "tz": tz_name,
        }

    # Global quiz leaderboard once — for each member's "top N%" among ALL bot users.
    global_rank: dict[int, int] = {}
    global_total = 0
    try:
        from backend.quiz_leaderboard import get_quiz_leaderboard
        glb = get_quiz_leaderboard(7)
        leaders = glb.get("leaders") or []
        global_total = int(glb.get("total_players") or len(leaders))
        global_rank = {int(l["user_id"]): i for i, l in enumerate(leaders) if l.get("user_id") is not None}
    except Exception:
        logging.warning("weekly group: global leaderboard failed", exc_info=True)

    from backend.database import upsert_group_weekly_total, get_group_recent_weekly_totals
    active_getter = _make_active_on_date_cache()

    sent = 0
    errors: list[str] = []
    groups = 0
    for target in targets:
        chat_id = int(target.get("chat_id") or 0)
        if chat_id >= 0:
            continue
        groups += 1
        try:
            member_user_ids = list_webapp_group_member_user_ids(chat_id, limit=5000, only_confirmed=False)
            if not member_user_ids:
                continue  # retired/dead group (or no members) — nothing to report
            activity = _collect_group_weekly_activity(
                member_user_ids=member_user_ids,
                week_start=bounds.start_date,
                week_end=bounds.end_date,
            )
            group_total = int(activity["group_total"])
            past = get_group_recent_weekly_totals(chat_id, bounds.start_date, limit=4)
            avg4 = (sum(past) / len(past)) if past else None
            record = max(past + [group_total]) if past else None

            all_together = _group_all_together_days(
                {int(u) for u in member_user_ids}, bounds.start_date, bounds.end_date, active_getter
            )
            caption = _format_group_weekly_hybrid_caption(
                activity=activity, avg4=avg4, record=record,
                week_start=bounds.start_date, week_end=bounds.end_date,
                global_rank=global_rank, global_total=global_total,
                all_together_days=all_together,
                week_days=(bounds.end_date - bounds.start_date).days + 1,
            )
            subtitle = f"{bounds.start_date.strftime('%d.%m')} — {bounds.end_date.strftime('%d.%m')}"
            chart_png = _build_group_week_vs_avg_chart_png(
                this_week=group_total, avg4=avg4, record=record,
                title="Неделя группы", subtitle=subtitle,
            )
            if chart_png:
                _send_group_photo(
                    image_bytes=chart_png,
                    filename=f"group_week_{abs(chat_id)}_{bounds.end_date.isoformat()}.png",
                    caption=caption, chat_id=chat_id, parse_mode="HTML",
                )
            else:
                # matplotlib unavailable → plain-text fallback (strip the bold tags).
                _send_group_message(text=caption.replace("<b>", "").replace("</b>", ""), chat_id=chat_id)

            try:
                upsert_group_weekly_total(
                    chat_id, bounds.start_date, group_total,
                    int(activity["translations_total"]), int(activity["quizzes_total"]), int(activity["words_total"]),
                )
            except Exception:
                logging.warning("weekly group: snapshot upsert failed chat_id=%s", chat_id, exc_info=True)
            sent += 1
        except Exception as exc:
            errors.append(f"chat {chat_id}: {exc}")
            _retire_group_if_dead(chat_id, exc)
            logging.warning("⚠️ Failed to send weekly group summary chat_id=%s", chat_id, exc_info=True)

    return {
        "ok": True,
        "date": target_date.isoformat(),
        "week_start": bounds.start_date.isoformat(),
        "week_end": bounds.end_date.isoformat(),
        "tz": tz_name,
        "groups": groups,
        "sent": sent,
        "errors": errors,
    }


def _run_stars_refund_reconcile_job() -> None:
    """Daily safety net: catch Stars refunds that never went through /refund_star (a
    Telegram-side or support refund sends the bot NO event) and claw back the perks they'd
    otherwise leave in place — closing the "pay → refund → keep Pro" loophole.

    Source of truth is Telegram's own ledger (getStarTransactions), NOT an event we must
    receive. A refund appears there as an OUTGOING transaction whose id EQUALS the original
    charge id, so we intersect the ledger's outgoing ids with our still-active fulfilled
    charges and revoke each match. Idempotent; safe to re-run."""
    from backend.database import (
        list_unrefunded_star_payments, mark_star_payment_refunded,
        revoke_star_payment_fulfillment,
    )
    token = TELEGRAM_Deutsch_BOT_TOKEN
    if not token:
        logging.warning("stars refund reconcile: no bot token"); return
    ours = {p["charge_id"]: p for p in list_unrefunded_star_payments() if p.get("charge_id")}
    if not ours:
        return
    refunded_ids: set[str] = set()
    offset = 0
    for _page in range(5):  # up to ~500 recent ledger entries
        try:
            resp = requests.get(
                f"https://api.telegram.org/bot{token}/getStarTransactions",
                params={"offset": offset, "limit": 100}, timeout=20,
            )
            body = resp.json()
        except Exception:
            logging.warning("stars refund reconcile: ledger fetch failed", exc_info=True); break
        if not body.get("ok"):
            logging.warning("stars refund reconcile: ledger error %s", body.get("description")); break
        txns = (body.get("result") or {}).get("transactions") or []
        if not txns:
            break
        for t in txns:
            # OUTGOING (no incoming `source`) = refund/withdrawal; its id == the original
            # charge id. Only ids matching OUR fulfilled charges are refunds we must undo.
            if not isinstance(t.get("source"), dict):
                tid = str(t.get("id") or "")
                if tid in ours:
                    refunded_ids.add(tid)
        offset += len(txns)
        if len(txns) < 100:
            break
    if not refunded_ids:
        return
    # Silent by design (owner: daily reconcile runs quietly; the weekly report is the notification).
    # We stamp refunded_via='reconcile' so the weekly report can flag these as "расхождения"
    # (refunds that bypassed /refund_star).
    revoked_count = 0
    for cid in refunded_ids:
        try:
            mark_star_payment_refunded(cid, via="reconcile")
            revoke_star_payment_fulfillment(cid)
            revoked_count += 1
        except Exception:
            logging.warning("stars refund reconcile: revoke failed charge=%s", cid, exc_info=True)
    if revoked_count:
        logging.info("stars refund reconcile: revoked %d refunded charge(s)", revoked_count)


def _run_stars_refund_weekly_report_job() -> None:
    """Weekly heartbeat report (DM to admins): Stars refunds in the last 7 days and how many
    users had perks clawed back, splitting auto-caught «расхождения» (refunds that bypassed
    /refund_star, stamped refunded_via='reconcile') from manual ones. ALWAYS sends — even
    «всё чисто» — so it shows up as alive in /scheduler_health."""
    from backend.database import (
        list_star_refunds_in_window, list_unrefunded_star_payments,
        get_admin_telegram_ids, record_scheduler_heartbeat,
    )
    from backend.telegram_notify import _send_private_message
    refunds = list_star_refunds_in_window(7)
    active_count = len(list_unrefunded_star_payments())
    total = len(refunds)
    users = len({r["user_id"] for r in refunds})
    reconcile = [r for r in refunds if r["refunded_via"] == "reconcile"]
    manual = [r for r in refunds if r["refunded_via"] != "reconcile"]
    lines = ["🧾 <b>Недельная сверка возвратов Stars</b>", "За последние 7 дней:"]
    if total == 0:
        lines.append("✅ Возвратов не было — всё чисто.")
    else:
        lines.append(f"• Возвратов: <b>{total}</b> (пользователей: {users})")
        lines.append(f"• Авто-выявлено сверкой (мимо /refund_star): <b>{len(reconcile)}</b>")
        lines.append(f"• Ручных (через /refund_star): {len(manual)}")
        lines.append("Перки по возвратам отозваны (дни полного доступа / спонсор / подписка / озвучка).")
        lines.append("")
        _emoji = {"support_coffee": "☕️", "support_cheesecake": "☕️🍰", "pro": "💎", "book_audio": "🔊"}
        for r in refunds[:15]:
            tag = "🔁авто" if r["refunded_via"] == "reconcile" else "🙋ручной"
            when = r["refunded_at"].strftime("%d.%m %H:%M") if r.get("refunded_at") else "—"
            lines.append(f"• {when} · id {r['user_id']} · {_emoji.get(r['purpose'], '')}{r['purpose'] or '—'} · {r['stars']}⭐ · {tag}")
        if total > 15:
            lines.append(f"…и ещё {total - 15}")
    lines.append("")
    lines.append(f"Активных (не возвращённых) оплат: {active_count}")
    text = "\n".join(lines)
    sent = False
    for admin_id in get_admin_telegram_ids():
        try:
            _send_private_message(int(admin_id), text, parse_mode="HTML")
            sent = True
        except Exception:
            logging.warning("stars refund weekly report: DM failed id=%s", admin_id, exc_info=True)
    try:
        record_scheduler_heartbeat(
            job_key="stars_refund_weekly_report",
            status="completed" if sent else "failed",
            metadata={"refunds_7d": total, "reconcile": len(reconcile), "users": users},
        )
    except Exception:
        logging.debug("stars refund weekly report heartbeat failed", exc_info=True)


def _run_daily_group_summary_scheduler_job() -> None:
    tz_name = (os.getenv("GROUP_SUMMARY_TZ") or TODAY_PLAN_DEFAULT_TZ).strip() or TODAY_PLAN_DEFAULT_TZ
    target_date = _get_local_today_date(tz_name)
    run_period = target_date.isoformat()
    if not claim_scheduler_run_guard(
        job_key="daily_group_summary_auto",
        run_period=run_period,
        target_scope="global",
        metadata={"tz": tz_name},
    ):
        logging.info("ℹ️ Daily group summary scheduler skipped: run guard already claimed for %s", run_period)
        return
    try:
        result = _dispatch_daily_group_summary(target_date=target_date, tz_name=tz_name)
        finish_scheduler_run_guard(
            job_key="daily_group_summary_auto",
            run_period=run_period,
            target_scope="global",
            status="completed",
            metadata=result if isinstance(result, dict) else {},
        )
        logging.info("✅ Daily group summary scheduler finished: %s", result)
    except Exception as exc:
        finish_scheduler_run_guard(
            job_key="daily_group_summary_auto",
            run_period=run_period,
            target_scope="global",
            status="failed",
            metadata={"error": str(exc)[:1000], "tz": tz_name},
        )
        logging.exception("❌ Daily group summary scheduler failed")


