_RU_MONTHS_NOM = {
    1: "Январь", 2: "Февраль", 3: "Март", 4: "Апрель", 5: "Май", 6: "Июнь",
    7: "Июль", 8: "Август", 9: "Сентябрь", 10: "Октябрь", 11: "Ноябрь", 12: "Декабрь",
}


def _group_month_member_totals(cohort: set, start: date, end_exclusive: date) -> dict[int, int]:
    """Per-member activity total (games + translations + words) over [start, end_exclusive),
    calendar-aligned via certificate_stats_for_window. {user_id: total}."""
    try:
        from backend.database import certificate_stats_for_window
        stats = certificate_stats_for_window(start, end_exclusive) or {}
    except Exception:
        logging.warning("group month: certificate_stats_for_window failed", exc_info=True)
        return {}
    out: dict[int, int] = {}
    for uid, s in stats.items():
        if int(uid) not in cohort:
            continue
        out[int(uid)] = int(s.get("games") or 0) + int(s.get("translations") or 0) + int(s.get("words") or 0)
    return out


def _dispatch_monthly_group_summary(*, target_date: date, tz_name: str = TODAY_PLAN_DEFAULT_TZ) -> dict[str, Any]:
    # Fired on the 1st → celebrate the month that JUST ended (the month containing yesterday).
    month_ref = target_date.replace(day=1) - timedelta(days=1)
    bounds = get_period_bounds("month", today=month_ref)
    next_month_start = bounds.end_date + timedelta(days=1)
    prior_ref = bounds.start_date - timedelta(days=1)
    prior_bounds = get_period_bounds("month", today=prior_ref)
    prior_next = prior_bounds.end_date + timedelta(days=1)
    month_label = f"{_RU_MONTHS_NOM.get(bounds.start_date.month, '')} {bounds.start_date.year}".strip()
    month_days = (bounds.end_date - bounds.start_date).days + 1

    targets = _collect_group_summary_targets()
    if not targets:
        return {"ok": True, "date": target_date.isoformat(), "month": month_label,
                "sent": 0, "groups": 0, "errors": [], "tz": tz_name}

    from backend.database import get_display_names_for_users
    try:
        fox_png = r2_get_bytes("battle/fox_reminder.png")
    except Exception:
        fox_png = None
    active_getter = _make_active_on_date_cache()

    sent = 0
    errors: list[str] = []
    groups = 0
    for target in targets:
        chat_id = int(target.get("chat_id") or 0)
        if chat_id >= 0:
            continue
        groups += 1
        try:
            member_user_ids = list_webapp_group_member_user_ids(chat_id, limit=5000, only_confirmed=False)
            cohort = {int(u) for u in member_user_ids}
            if not cohort:
                continue
            per = _group_month_member_totals(cohort, bounds.start_date, next_month_start)
            total = sum(per.values())
            if total <= 0:
                continue  # nothing happened this month — skip the empty celebration
            prev_total = sum(_group_month_member_totals(cohort, prior_bounds.start_date, prior_next).values())
            champion_uid = max(per, key=lambda u: per[u]) if per else None
            champion_name = ""
            if champion_uid is not None and per.get(champion_uid, 0) > 0:
                try:
                    champion_name = str((get_display_names_for_users([champion_uid]) or {}).get(champion_uid) or "").strip()
                except Exception:
                    champion_name = ""
            together = _group_all_together_days(cohort, bounds.start_date, bounds.end_date, active_getter)
            group_name = str(target.get("chat_title") or "").strip()

            from backend.certificate_poster import render_monthly_group_poster
            poster = render_monthly_group_poster(
                group_name=group_name, month_label=month_label, total=total,
                prev_total=(prev_total or None), champion_name=(champion_name or None),
                together_days=together, month_days=month_days, hero_png=fox_png,
            )
            caption = f"🎉 <b>Итог месяца — {month_label}</b>. Так держать всей группой! 👏"
            if poster:
                _send_group_photo(
                    image_bytes=poster,
                    filename=f"group_month_{abs(chat_id)}_{bounds.start_date.isoformat()}.png",
                    caption=caption, chat_id=chat_id, parse_mode="HTML",
                )
            else:
                _send_group_message(text=caption, chat_id=chat_id, parse_mode="HTML")
            sent += 1
        except Exception as exc:
            errors.append(f"chat {chat_id}: {exc}")
            _retire_group_if_dead(chat_id, exc)
            logging.warning("⚠️ Failed to send monthly group summary chat_id=%s", chat_id, exc_info=True)

    return {"ok": True, "date": target_date.isoformat(), "month": month_label, "tz": tz_name,
            "groups": groups, "sent": sent, "errors": errors}


def _run_monthly_group_summary_scheduler_job() -> None:
    tz_name = (os.getenv("GROUP_SUMMARY_TZ") or TODAY_PLAN_DEFAULT_TZ).strip() or TODAY_PLAN_DEFAULT_TZ
    target_date = _get_local_today_date(tz_name)
    month_ref = target_date.replace(day=1) - timedelta(days=1)
    run_period = month_ref.strftime("%Y-%m")
    if not claim_scheduler_run_guard(
        job_key="monthly_group_summary_auto",
        run_period=run_period,
        target_scope="global",
        metadata={"tz": tz_name, "month": run_period},
    ):
        logging.info("ℹ️ Monthly group summary scheduler skipped: run guard already claimed for %s", run_period)
        return
    try:
        result = _dispatch_monthly_group_summary(target_date=target_date, tz_name=tz_name)
        finish_scheduler_run_guard(
            job_key="monthly_group_summary_auto", run_period=run_period, target_scope="global",
            status="completed", metadata=result if isinstance(result, dict) else {},
        )
        logging.info("✅ Monthly group summary scheduler finished: %s", result)
    except Exception as exc:
        finish_scheduler_run_guard(
            job_key="monthly_group_summary_auto", run_period=run_period, target_scope="global",
            status="failed", metadata={"error": str(exc)[:1000], "tz": tz_name},
        )
        logging.exception("❌ Monthly group summary scheduler failed")


def _format_today_plan_message(plan: dict) -> str:
    total = int(plan.get("total_minutes") or 0)
    lines = ["Твои задачи на сегодня готовы ✅", f"Всего {total} минут:"]
    for idx, item in enumerate(plan.get("items") or [], start=1):
        title = str(item.get("title") or "Задача").strip()
        payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
        if item.get("task_type") == "cards":
            limit = payload.get("limit")
            if limit:
                lines.append(f"{idx}. Карточки: {limit} повторений")
            else:
                lines.append(f"{idx}. {title}")
            continue
        if item.get("task_type") == "translation":
            sentences = int(payload.get("sentences") or 7)
            sub = str(payload.get("sub_category") or "").strip()
            if sub:
                lines.append(f"{idx}. Перевод: {sentences} предложений ({sub})")
            else:
                lines.append(f"{idx}. Перевод: {sentences} предложений")
            continue
        if item.get("task_type") == "theory":
            sub = str(payload.get("sub_category") or "").strip()
            skill = str(payload.get("skill_title") or "").strip()
            label = sub or skill
            if label:
                lines.append(f"{idx}. Теория: {label}")
            else:
                lines.append(f"{idx}. Теория")
            continue
        if item.get("task_type") == "video":
            lines.append(f"{idx}. Видео: 5 минут")
            continue
        lines.append(f"{idx}. {title}")
    lines.append("")
    lines.append("Нажми и начинай 👇")
    return "\n".join(lines)


def _format_today_group_announcement(user_label: str, plan: dict) -> str:
    total = int(plan.get("total_minutes") or 0)
    lines = [f"📌 Для {user_label} готов дневной план", f"Всего: {total} минут"]
    for idx, item in enumerate(plan.get("items") or [], start=1):
        payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
        task_type = str(item.get("task_type") or "").lower()
        if task_type == "cards":
            limit = int(payload.get("limit") or 0)
            if limit > 0:
                lines.append(f"{idx}. Карточки: {limit} повторений")
            else:
                lines.append(f"{idx}. Карточки")
            continue
        if task_type == "translation":
            sentences = int(payload.get("sentences") or 7)
            sub = str(payload.get("sub_category") or "").strip()
            if sub:
                lines.append(f"{idx}. Перевод: {sentences} предложений ({sub})")
            else:
                lines.append(f"{idx}. Перевод: {sentences} предложений")
            continue
        if task_type == "theory":
            sub = str(payload.get("sub_category") or "").strip()
            skill = str(payload.get("skill_title") or "").strip()
            label = sub or skill
            if label:
                lines.append(f"{idx}. Теория: {label}")
            else:
                lines.append(f"{idx}. Теория")
            continue
        if task_type == "video":
            sec = int(payload.get("duration_sec") or 300)
            minutes = max(1, round(sec / 60))
            lines.append(f"{idx}. Видео: {minutes} минут")
            continue
        lines.append(f"{idx}. {str(item.get('title') or 'Задача')}")
    return "\n".join(lines)


def _resolve_user_group_chat_id_for_today_motivation(user_id: int) -> int | None:
    safe_user_id = int(user_id)
    candidate_chat_ids: list[int] = []

    for only_confirmed in (True, False):
        try:
            contexts = list_webapp_group_contexts(
                user_id=safe_user_id,
                limit=20,
                only_confirmed=only_confirmed,
            )
        except Exception:
            contexts = []
        for item in contexts:
            try:
                chat_id = int(item.get("chat_id"))
            except Exception:
                continue
            if chat_id not in candidate_chat_ids:
                candidate_chat_ids.append(chat_id)

    if TELEGRAM_GROUP_CHAT_ID:
        try:
            fallback_group_chat_id = int(TELEGRAM_GROUP_CHAT_ID)
            if fallback_group_chat_id not in candidate_chat_ids:
                candidate_chat_ids.append(fallback_group_chat_id)
        except Exception:
            pass

    for chat_id in candidate_chat_ids:
        if _is_user_member_of_chat(chat_id=chat_id, user_id=safe_user_id):
            return int(chat_id)
    return None


def _normalize_today_translation_session_id(value: object) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        return str(int(raw))
    except Exception:
        return raw


def _parse_today_plan_date(value: object) -> date | None:
    if isinstance(value, date):
        return value
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return date.fromisoformat(raw[:10])
    except Exception:
        return None


def _resolve_legacy_today_translation_session_id(
    *,
    user_id: int,
    plan_date: date | str | None,
    target_count: int,
    source_lang: str,
    target_lang: str,
) -> str:
    resolved_plan_date = _parse_today_plan_date(plan_date)
    if resolved_plan_date is None:
        return ""

    normalized_source_lang = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target_lang = str(target_lang or "de").strip().lower() or "de"
    safe_target_count = max(0, int(target_count or 0))

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    ds.session_id::text AS session_id,
                    COUNT(*) AS sentence_count,
                    COUNT(DISTINCT tr.sentence_id) AS completed_count,
                    MAX(ds.id) AS last_sentence_id
                FROM bt_3_daily_sentences ds
                LEFT JOIN bt_3_translations tr
                  ON tr.user_id = ds.user_id
                 AND tr.sentence_id = ds.id
                WHERE ds.user_id = %s
                  AND ds.date = %s
                  AND COALESCE(ds.source_lang, 'ru') = %s
                  AND COALESCE(ds.target_lang, 'de') = %s
                GROUP BY ds.session_id
                ORDER BY COUNT(DISTINCT tr.sentence_id) DESC, COUNT(*) DESC, MAX(ds.id) DESC;
                """,
                (
                    int(user_id),
                    resolved_plan_date,
                    normalized_source_lang,
                    normalized_target_lang,
                ),
            )
            rows = cursor.fetchall() or []

    candidates: list[dict[str, int | str]] = []
    for row in rows:
        session_id = _normalize_today_translation_session_id(row[0])
        if not session_id:
            continue
        candidates.append(
            {
                "session_id": session_id,
                "sentence_count": max(0, int(row[1] or 0)),
                "completed_count": max(0, int(row[2] or 0)),
                "last_sentence_id": max(0, int(row[3] or 0)),
            }
        )

    if not candidates:
        return ""
    if len(candidates) == 1:
        return str(candidates[0]["session_id"])

    exact_target_candidates = [
        candidate
        for candidate in candidates
        if int(candidate.get("sentence_count") or 0) == safe_target_count and safe_target_count > 0
    ]
    if len(exact_target_candidates) == 1:
        return str(exact_target_candidates[0]["session_id"])

    translated_candidates = [
        candidate
        for candidate in (exact_target_candidates or candidates)
        if int(candidate.get("completed_count") or 0) > 0
    ]
    if len(translated_candidates) == 1:
        return str(translated_candidates[0]["session_id"])

    logging.info(
        "Today translation session recovery ambiguous: user=%s plan_date=%s source_lang=%s target_lang=%s candidates=%s",
        int(user_id),
        resolved_plan_date.isoformat(),
        normalized_source_lang,
        normalized_target_lang,
        [str(candidate.get("session_id") or "") for candidate in candidates],
    )
    return ""


def _count_translation_session_completed_sentences(
    *,
    user_id: int,
    translation_session_id: str,
    source_lang: str,
    target_lang: str,
) -> int:
    normalized_session_id = _normalize_today_translation_session_id(translation_session_id)
    if not normalized_session_id:
        return 0
    try:
        session_id_value = int(normalized_session_id)
    except Exception:
        return 0

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT COUNT(DISTINCT tr.sentence_id)
                FROM bt_3_translations tr
                JOIN bt_3_daily_sentences ds
                  ON ds.id = tr.sentence_id
                WHERE tr.user_id = %s
                  AND ds.user_id = %s
                  AND ds.session_id = %s
                  AND COALESCE(tr.source_lang, 'ru') = %s
                  AND COALESCE(tr.target_lang, 'de') = %s
                  AND COALESCE(ds.source_lang, 'ru') = %s
                  AND COALESCE(ds.target_lang, 'de') = %s;
                """,
                (
                    int(user_id),
                    int(user_id),
                    int(session_id_value),
                    str(source_lang or "ru").strip().lower() or "ru",
                    str(target_lang or "de").strip().lower() or "de",
                    str(source_lang or "ru").strip().lower() or "ru",
                    str(target_lang or "de").strip().lower() or "de",
                ),
            )
            row = cursor.fetchone()
    return max(0, int(row[0] or 0)) if row else 0


def _count_today_translation_completed_sentences(
    *,
    user_id: int,
    plan_date: date | str | None,
    source_lang: str,
    target_lang: str,
) -> int:
    resolved_plan_date = _parse_today_plan_date(plan_date)
    if resolved_plan_date is None:
        return 0

    normalized_source_lang = str(source_lang or "ru").strip().lower() or "ru"
    normalized_target_lang = str(target_lang or "de").strip().lower() or "de"

    with get_db_connection_context() as conn:
        with conn.cursor() as cursor:
            cursor.execute(
                """
                SELECT COUNT(DISTINCT tr.sentence_id)
                FROM bt_3_translations tr
                JOIN bt_3_daily_sentences ds
                  ON ds.id = tr.sentence_id
                WHERE tr.user_id = %s
                  AND ds.user_id = %s
                  AND ds.date = %s
                  AND COALESCE(tr.source_lang, 'ru') = %s
                  AND COALESCE(tr.target_lang, 'de') = %s
                  AND COALESCE(ds.source_lang, 'ru') = %s
                  AND COALESCE(ds.target_lang, 'de') = %s;
                """,
                (
                    int(user_id),
                    int(user_id),
                    resolved_plan_date,
                    normalized_source_lang,
                    normalized_target_lang,
                    normalized_source_lang,
                    normalized_target_lang,
                ),
            )
            row = cursor.fetchone()
    return max(0, int(row[0] or 0)) if row else 0


def _sync_today_translation_item_progress(
    *,
    user_id: int,
    username: str | None,
    item: dict | None,
    source_lang: str,
    target_lang: str,
    trigger: str,
    plan_date: date | str | None = None,
    fallback_translation_session_id: str | None = None,
) -> dict | None:
    if not isinstance(item, dict):
        return item
    if str(item.get("task_type") or "").strip().lower() != "translation":
        return item

    payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
    effective_source_lang = str(payload.get("source_lang") or source_lang or "ru").strip().lower() or "ru"
    effective_target_lang = str(payload.get("target_lang") or target_lang or "de").strip().lower() or "de"
    target_count = max(1, int(payload.get("translation_target_count") or payload.get("sentences") or 7))
    translation_session_id = _normalize_today_translation_session_id(
        payload.get("translation_session_id") or payload.get("source_session_id") or fallback_translation_session_id
    )
    if not translation_session_id:
        translation_session_id = _resolve_legacy_today_translation_session_id(
            user_id=int(user_id),
            plan_date=plan_date,
            target_count=target_count,
            source_lang=effective_source_lang,
            target_lang=effective_target_lang,
        )
    completed_count = _count_today_translation_completed_sentences(
        user_id=int(user_id),
        plan_date=plan_date,
        source_lang=effective_source_lang,
        target_lang=effective_target_lang,
    )
    if translation_session_id:
        completed_count = max(
            completed_count,
            _count_translation_session_completed_sentences(
                user_id=int(user_id),
                translation_session_id=translation_session_id,
                source_lang=effective_source_lang,
                target_lang=effective_target_lang,
            ),
        )
    progress_percent = min(100.0, (float(completed_count) / float(target_count)) * 100.0) if target_count > 0 else 0.0
    current_status = str(item.get("status") or "todo").strip().lower() or "todo"

    desired_status = current_status
    if completed_count >= target_count and target_count > 0:
        desired_status = "done"
    elif current_status == "done":
        desired_status = "doing" if translation_session_id else "todo"
    elif current_status in {"todo", "skipped"} and (completed_count > 0 or translation_session_id):
        desired_status = "doing"

    payload_updates = {
        "translation_session_id": translation_session_id,
        "source_session_id": translation_session_id,
        "translation_target_count": int(target_count),
        "translation_completed_count": int(completed_count),
        "translation_progress_percent": round(progress_percent, 2),
        "source_lang": effective_source_lang,
        "target_lang": effective_target_lang,
        "translation_completed_at": datetime.now(timezone.utc).isoformat()
        if desired_status == "done"
        else None,
    }
    changed_payload = any(payload.get(key) != value for key, value in payload_updates.items())

    updated_item = item
    if changed_payload:
        saved_item = update_daily_plan_item_payload(
            user_id=int(user_id),
            item_id=int(item.get("id") or 0),
            payload_updates=payload_updates,
        )
        if saved_item:
            updated_item = saved_item
    if desired_status != current_status:
        saved_status_item = update_daily_plan_item_status(
            user_id=int(user_id),
            item_id=int(item.get("id") or 0),
            status=desired_status,
        )
        if saved_status_item:
            updated_item = saved_status_item

    if str((updated_item or {}).get("status") or "").strip().lower() == "done":
        try:
            _announce_today_task_completion_to_group(
                user_id=int(user_id),
                username=username,
                item=updated_item,
                trigger=trigger,
            )
        except Exception:
            logging.warning(
                "Today translation task group announcement failed: user=%s item=%s",
                user_id,
                (updated_item or {}).get("id"),
                exc_info=True,
            )
    return updated_item


def _sync_today_plan_translation_progress(
    *,
    user_id: int,
    username: str | None,
    plan: dict | None,
    source_lang: str,
    target_lang: str,
    trigger: str,
) -> dict | None:
    if not isinstance(plan, dict):
        return plan
    items = list(plan.get("items") or [])
    if not items:
        return plan
    synced_items: list[dict] = []
    changed = False
    for item in items:
        if str(item.get("task_type") or "").strip().lower() != "translation":
            synced_items.append(item)
            continue
        synced_item = _sync_today_translation_item_progress(
            user_id=int(user_id),
            username=username,
            item=item,
            source_lang=source_lang,
            target_lang=target_lang,
            trigger=trigger,
            plan_date=plan.get("plan_date"),
        )
        synced_items.append(synced_item or item)
        changed = changed or (synced_item is not None and synced_item != item)
    if not changed:
        return plan
    return {
        **plan,
        "items": synced_items,
    }


def _sync_today_plan_cards_progress(
    *,
    user_id: int,
    username: str | None,
    plan: dict | None,
    source_lang: str,
    target_lang: str,
    trigger: str,
) -> dict | None:
    if not isinstance(plan, dict):
        return plan
    items = list(plan.get("items") or [])
    if not items:
        return plan

    now_utc = datetime.now(timezone.utc)
    srs_queue_computed = False
    current_due = 0
    due_review_elapsed_seconds: int | None = None
    new_review_elapsed_seconds: int | None = None

    synced_items: list[dict] = []
    changed = False
    for item in items:
        task_type = str(item.get("task_type") or "").strip().lower()
        if task_type != "cards":
            synced_items.append(item)
            continue

        current_status = str(item.get("status") or "todo").strip().lower() or "todo"
        payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
        mode = str(payload.get("mode") or "").strip().lower()
        limit = max(1, int(payload.get("limit") or 1))
        goal_seconds = max(0, int(payload.get("timer_goal_seconds") or (max(0, int(item.get("estimated_minutes") or 0)) * 60)))
        stored_elapsed = max(0, int(payload.get("timer_seconds") or 0))
        derived_elapsed = stored_elapsed

        desired_status = current_status

        if mode == "fsrs_due":
            if due_review_elapsed_seconds is None:
                try:
                    due_review_elapsed_seconds = int(
                        count_card_review_response_seconds_today(
                            user_id=int(user_id),
                            now_utc=now_utc,
                            source_lang=source_lang,
                            target_lang=target_lang,
                            review_kind="due",
                            tz_name=TODAY_PLAN_DEFAULT_TZ,
                        )
                    )
                except Exception:
                    due_review_elapsed_seconds = 0
            derived_elapsed = max(derived_elapsed, max(0, int(due_review_elapsed_seconds or 0)))
            if not srs_queue_computed:
                try:
                    current_due = int(
                        count_due_srs_cards(
                            user_id=int(user_id),
                            now_utc=now_utc,
                            source_lang=source_lang,
                            target_lang=target_lang,
                        )
                    )
                except Exception:
                    current_due = -1
                srs_queue_computed = True
            if current_due >= 0:
                initial_due = max(0, int(payload.get("due_total") or limit))
                reviewed = max(0, min(limit, initial_due - current_due))
                if current_due <= 0 or reviewed >= limit:
                    desired_status = "done"
                elif reviewed > 0 and current_status == "todo":
                    desired_status = "doing"

        elif mode == "cards_new":
            if new_review_elapsed_seconds is None:
                try:
                    new_review_elapsed_seconds = int(
                        count_card_review_response_seconds_today(
                            user_id=int(user_id),
                            now_utc=now_utc,
                            source_lang=source_lang,
                            target_lang=target_lang,
                            review_kind="new",
                            tz_name=TODAY_PLAN_DEFAULT_TZ,
                        )
                    )
                except Exception:
                    new_review_elapsed_seconds = 0
            derived_elapsed = max(derived_elapsed, max(0, int(new_review_elapsed_seconds or 0)))
            try:
                introduced_today = int(
                    count_new_cards_introduced_today(
                        user_id=int(user_id),
                        now_utc=now_utc,
                        source_lang=source_lang,
                        target_lang=target_lang,
                    )
                )
            except Exception:
                synced_items.append(item)
                continue
            if introduced_today >= limit:
                desired_status = "done"
            elif introduced_today > 0 and current_status == "todo":
                desired_status = "doing"

        progress_percent = 0.0
        if goal_seconds > 0:
            progress_percent = min(100.0, (float(derived_elapsed) / float(goal_seconds)) * 100.0)
        elif derived_elapsed > 0:
            progress_percent = 100.0

        if goal_seconds > 0 and derived_elapsed >= goal_seconds:
            desired_status = "done"
        elif desired_status in {"todo", "skipped"} and derived_elapsed > 0:
            desired_status = "doing"

        payload_updates = {
            "timer_seconds": int(derived_elapsed),
            "timer_goal_seconds": int(goal_seconds),
            "timer_progress_percent": round(progress_percent, 2),
        }
        changed_payload = any(payload.get(key) != value for key, value in payload_updates.items())

        updated_item = item
        if changed_payload:
            try:
                saved_item = update_daily_plan_item_payload(
                    user_id=int(user_id),
                    item_id=int(item.get("id") or 0),
                    payload_updates=payload_updates,
                )
                if saved_item:
                    updated_item = saved_item
                    changed = True
            except Exception:
                logging.warning(
                    "Failed to sync cards item payload: user=%s item=%s trigger=%s",
                    user_id,
                    item.get("id"),
                    trigger,
                    exc_info=True,
                )

        if desired_status != current_status:
            try:
                updated = update_daily_plan_item_status(
                    user_id=int(user_id),
                    item_id=int((updated_item or item).get("id") or 0),
                    status=desired_status,
                )
                if updated:
                    if desired_status == "done":
                        try:
                            _announce_today_task_completion_to_group(
                                user_id=int(user_id),
                                username=username,
                                item=updated,
                                trigger=trigger,
                            )
                        except Exception:
                            logging.warning(
                                "Today cards task group announcement failed: user=%s item=%s",
                                user_id,
                                (updated or {}).get("id"),
                                exc_info=True,
                            )
                    synced_items.append(updated)
                    changed = True
                    continue
            except Exception:
                logging.warning(
                    "Failed to sync cards item status: user=%s item=%s trigger=%s",
                    user_id,
                    item.get("id"),
                    trigger,
                    exc_info=True,
                )
        synced_items.append(updated_item or item)

    if not changed:
        return plan
    return {**plan, "items": synced_items}


_PLAN_NOT_PROVIDED = object()


def _sync_today_translation_task_progress_for_session(
    *,
    user_id: int,
    username: str | None,
    source_lang: str,
    target_lang: str,
    translation_session_id: str | None,
    trigger: str,
    timing_breakdown: dict[str, int] | None = None,
    prefetched_plan: dict | None | object = _PLAN_NOT_PROVIDED,
) -> dict | None:
    normalized_session_id = _normalize_today_translation_session_id(translation_session_id)
    if not normalized_session_id:
        return None
    if prefetched_plan is not _PLAN_NOT_PROVIDED:
        plan = prefetched_plan
        if isinstance(timing_breakdown, dict):
            timing_breakdown["sync_plan_fetch_ms"] = 0
    else:
        today_date = _get_local_today_date(TODAY_PLAN_DEFAULT_TZ)
        sync_plan_fetch_started_perf = time.perf_counter()
        with db_acquire_scope("today_translation_task_sync"):
            plan = get_daily_plan(user_id=int(user_id), plan_date=today_date)
        if isinstance(timing_breakdown, dict):
            timing_breakdown["sync_plan_fetch_ms"] = int((time.perf_counter() - sync_plan_fetch_started_perf) * 1000)
    if not plan:
        return None

    target_item = None
    for item in (plan.get("items") or []):
        if str(item.get("task_type") or "").strip().lower() != "translation":
            continue
        payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
        item_session_id = _normalize_today_translation_session_id(
            payload.get("translation_session_id") or payload.get("source_session_id")
        )
        if item_session_id == normalized_session_id:
            target_item = item
            break

    if target_item is None:
        translation_items = [
            item
            for item in (plan.get("items") or [])
            if str(item.get("task_type") or "").strip().lower() == "translation"
        ]
        if len(translation_items) == 1:
            target_item = translation_items[0]

    if target_item is None:
        return None

    sync_item_write_started_perf = time.perf_counter()
    with db_acquire_scope("today_translation_task_sync"):
        result = _sync_today_translation_item_progress(
            user_id=int(user_id),
            username=username,
            item=target_item,
            source_lang=source_lang,
            target_lang=target_lang,
            trigger=trigger,
            plan_date=plan.get("plan_date"),
            fallback_translation_session_id=normalized_session_id,
        )
    if isinstance(timing_breakdown, dict):
        timing_breakdown["sync_item_write_ms"] = int((time.perf_counter() - sync_item_write_started_perf) * 1000)
    return result


def _normalize_stale_today_plan_timers(
    *,
    user_id: int,
    plan: dict | None,
    stale_after_seconds: int = 120,
) -> dict | None:
    if not isinstance(plan, dict):
        return plan
    items = list(plan.get("items") or [])
    if not items:
        return plan
    now_utc = datetime.now(timezone.utc)
    normalized_items: list[dict] = []
    changed = False
    safe_stale_after = max(30, int(stale_after_seconds or 120))

    for item in items:
        payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
        status = str(item.get("status") or "").strip().lower()
        timer_running = bool(payload.get("timer_running"))
        if status == "done" or not timer_running:
            normalized_items.append(item)
            continue

        marker_dt = _parse_iso_datetime(payload.get("timer_updated_at")) or _parse_iso_datetime(payload.get("timer_started_at"))
        if marker_dt is None:
            normalized_items.append(item)
            continue
        stale_seconds = max(0.0, (now_utc - marker_dt).total_seconds())
        if stale_seconds < float(safe_stale_after):
            normalized_items.append(item)
            continue

        # Do NOT pass elapsed_seconds — let update_daily_plan_item_timer compute
        # the live elapsed from (timer_seconds + time_since_timer_started_at).
        # Passing stored_elapsed here would discard all time accumulated since the
        # last sync, which is exactly what causes the "timer resets to earlier value"
        # bug when syncs were missed (network issues, background throttling, etc.).
        paused_item = update_daily_plan_item_timer(
            user_id=int(user_id),
            item_id=int(item.get("id") or 0),
            action="pause",
            running=False,
            event_at=now_utc,
        ) or item
        normalized_items.append(paused_item)
        changed = True

    if not changed:
        return plan
    return {
        **plan,
        "items": normalized_items,
    }


def _is_today_task_done_for_group_announcement(item: dict | None) -> bool:
    payload = item.get("payload") if isinstance(item, dict) and isinstance(item.get("payload"), dict) else {}
    status = str((item or {}).get("status") or "").strip().lower()
    if status == "done":
        return True
    task_type = str((item or {}).get("task_type") or "").strip().lower()
    if task_type == "translation":
        try:
            progress = float(
                payload.get("translation_progress_percent")
                or (
                    (float(payload.get("translation_completed_count") or 0.0) / max(1.0, float(payload.get("translation_target_count") or payload.get("sentences") or 7.0)))
                    * 100.0
                )
            )
        except Exception:
            progress = 0.0
        return progress >= 100.0
    try:
        progress = float(payload.get("timer_progress_percent") or 0.0)
    except Exception:
        progress = 0.0
    return progress >= 100.0


def _format_today_task_completion_title(item: dict | None) -> str:
    if not isinstance(item, dict):
        return "Задача"
    payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
    task_type = str(item.get("task_type") or "").strip().lower()
    explicit_title = str(item.get("title") or "").strip()
    if explicit_title and explicit_title != "Задача":
        return explicit_title
    if task_type == "cards":
        limit = int(payload.get("limit") or 0)
        return f"Карточки ({limit})" if limit > 0 else "Карточки"
    if task_type == "translation":
        sentences = int(payload.get("sentences") or 7)
        sub = str(payload.get("sub_category") or "").strip()
        return f"Перевод ({sentences} предложений, {sub})" if sub else f"Перевод ({sentences} предложений)"
    if task_type == "theory":
        label = str(payload.get("sub_category") or payload.get("skill_title") or "").strip()
        return f"Теория ({label})" if label else "Теория"
    if task_type in {"video", "youtube"}:
        sec = int(payload.get("duration_sec") or 300)
        minutes = max(1, round(sec / 60))
        return f"YouTube ({minutes} минут)"
    return explicit_title or "Задача"


def _build_today_task_completion_group_message(user_label: str, task_title: str) -> str:
    variants = [
        (
            "🏁 Прогресс дня\n"
            f"👏 {user_label} выполнил(а) на 100% задачу:\n"
            f"✅ {task_title}\n\n"
            "Так держать! 🔥"
        ),
        (
            "🎯 Дневная цель закрыта\n"
            f"🙌 {user_label} закрыл(а) задачу на 100%:\n"
            f"✅ {task_title}\n\n"
            "Классный темп, продолжаем! ⚡"
        ),
        (
            "🚀 Новый результат в плане дня\n"
            f"⭐ {user_label} довёл(а) до 100%:\n"
            f"✅ {task_title}\n\n"
            "Отличный пример для команды!"
        ),
        (
            "🔥 Мотивация дня\n"
            f"💪 {user_label} полностью завершил(а):\n"
            f"✅ {task_title}\n\n"
            "Берём темп и двигаемся дальше!"
        ),
    ]
    return random.choice(variants)


def _announce_today_task_completion_to_group(
    *,
    user_id: int,
    username: str | None,
    item: dict | None,
    trigger: str,
) -> None:
    if not _is_today_task_done_for_group_announcement(item):
        return
    if not isinstance(item, dict):
        return
    payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
    if str(payload.get("today_group_done_announcement_at") or "").strip():
        return
    item_id = int(item.get("id") or 0)
    if item_id <= 0:
        return

    target_chat_id = _resolve_user_group_chat_id_for_today_motivation(int(user_id))
    if target_chat_id is None or int(target_chat_id) >= 0:
        return

    user_label = _resolve_today_group_user_label(
        int(user_id),
        username,
        cache=None,
    )
    task_title = _format_today_task_completion_title(item)
    button_url = _build_webapp_deeplink("today")
    reply_markup = {"inline_keyboard": [[{"text": "Открыть план на сегодня", "url": button_url}]]}
    text = _build_today_task_completion_group_message(user_label=user_label, task_title=task_title)
    _send_group_message(text=text, reply_markup=reply_markup, chat_id=int(target_chat_id))

    try:
        update_daily_plan_item_payload(
            user_id=int(user_id),
            item_id=item_id,
            payload_updates={
                "today_group_done_announcement_at": datetime.now(timezone.utc).isoformat(),
                "today_group_done_announcement_chat_id": int(target_chat_id),
                "today_group_done_announcement_trigger": str(trigger or "").strip() or "unknown",
            },
        )
    except Exception:
        logging.warning(
            "Failed to persist today group completion announcement marker: user_id=%s item_id=%s",
            user_id,
            item_id,
            exc_info=True,
        )


def _send_today_plan_private_message(user_id: int, plan: dict) -> None:
    button_url = _build_webapp_deeplink("today")
    reply_markup = {
        "inline_keyboard": [[{"text": "Открыть план", "url": button_url}]],
    }
    _send_private_message(
        user_id=int(user_id),
        text=_format_today_plan_message(plan),
        reply_markup=reply_markup,
    )


def _dispatch_today_plans(target_date: date, tz_name: str = TODAY_PLAN_DEFAULT_TZ) -> dict:
    users = list_today_reminder_users(limit=5000, offset=0)
    if not users:
        return {"ok": True, "date": target_date.isoformat(), "sent_private": 0, "sent_group_fallback": 0, "errors": []}

    group_on_private_fail = str(os.getenv("TODAY_PLAN_GROUP_ON_PRIVATE_FAIL") or "1").strip().lower() in {"1", "true", "yes", "on"}
    sent_private = 0
    sent_group_fallback = 0
    errors: list[str] = []
    name_cache: dict[int, str | None] = {}
    for row in users:
        user_id = int(row.get("user_id"))
        if not is_telegram_user_allowed(user_id):
            continue
        try:
            source_lang, target_lang, _profile = _get_user_language_pair(user_id)
            plan = _get_or_create_today_plan(
                user_id=user_id,
                plan_date=target_date,
                source_lang=source_lang,
                target_lang=target_lang,
            )
            try:
                target_chat_id = _resolve_user_delivery_chat_id(user_id, job_name="_dispatch_today_plans")
                if int(target_chat_id) < 0:
                    user_label = _resolve_today_group_user_label(
                        user_id,
                        row.get("username"),
                        cache=name_cache,
                    )
                    text = _format_today_group_announcement(user_label, plan)
                    button_url = _build_webapp_deeplink("today")
                    reply_markup = {
                        "inline_keyboard": [[{"text": "Открыть план", "url": button_url}]],
                    }
                    _send_group_message(text=text, reply_markup=reply_markup, chat_id=int(target_chat_id))
                    sent_group_fallback += 1
                else:
                    _send_today_plan_private_message(user_id=int(target_chat_id), plan=plan)
                    sent_private += 1
            except Exception as route_exc:
                if not group_on_private_fail:
                    raise
                try:
                    _send_private_message(user_id=user_id, text=_format_today_plan_message(plan))
                    sent_private += 1
                except Exception as private_exc:
                    errors.append(f"user {user_id}: route_failed={route_exc}; private_fallback_failed={private_exc}")
                    logging.warning("Today plan routing failed for user %s: %s / %s", user_id, route_exc, private_exc)
        except Exception as exc:
            errors.append(f"user {user_id}: {exc}")
    return {
        "ok": True,
        "date": target_date.isoformat(),
        "sent_private": sent_private,
        "sent_group_fallback": sent_group_fallback,
        "errors": errors,
    }


def _run_today_plan_scheduler_job() -> None:
    # HARD-DISABLED (owner decision): the «Твои задачи на сегодня готовы» morning DM must never
    # go out. The cron registrations are already gated off, but a message may still be sitting
    # in the dramatiq queue from an earlier fire — a restarted worker would process it late and
    # the DM would resurface at an odd hour. This early return makes any such lingering queued
    # message a no-op. To bring the feature back, remove this guard AND the `if False` gates.
    logging.info("today_plan morning DM is hard-disabled — skipping run")
    return
    tz_name = (os.getenv("TODAY_PLAN_TZ") or TODAY_PLAN_DEFAULT_TZ).strip() or TODAY_PLAN_DEFAULT_TZ
    target_date = _get_local_today_date(tz_name)
    run_period = target_date.isoformat()
    if not claim_scheduler_run_guard(
        job_key="today_plan_auto",
        run_period=run_period,
        target_scope="global",
        metadata={"tz": tz_name},
    ):
        logging.info("ℹ️ Today plan scheduler skipped: run guard already claimed for %s", run_period)
        return
    try:
        result = _dispatch_today_plans(target_date=target_date, tz_name=tz_name)
        finish_scheduler_run_guard(
            job_key="today_plan_auto",
            run_period=run_period,
            target_scope="global",
            status="completed",
            metadata=result if isinstance(result, dict) else {},
        )
        logging.info("✅ Today plan scheduler finished: %s", result)
    except Exception as exc:
        finish_scheduler_run_guard(
            job_key="today_plan_auto",
            run_period=run_period,
            target_scope="global",
            status="failed",
            metadata={"error": str(exc)[:1000], "tz": tz_name},
        )
        logging.exception("❌ Today plan scheduler failed")


